    public static class KeystoneArcHub
    {
        private static readonly object Sync = new object();
        private static readonly List<KeystoneArcEvent> latestEvents = new List<KeystoneArcEvent>();
        private static readonly Dictionary<string, List<KeystoneArcEvent>> eventsByFiveMinuteBar = new Dictionary<string, List<KeystoneArcEvent>>();
        private static KeystoneArcRunConfig latestConfig = new KeystoneArcRunConfig();
        public static bool ShowChartMarks = true;
        public static bool ShowChartOutcomeLabels = true;
        public static bool ShowChartWins = true;
        public static bool ShowChartLosses = true;
        public static bool ShowChartSessionExits = false;
        public static bool ShowChartNoEntryData = false;
        public static bool ShowChartBh = true;
        public static bool ShowChartFvg = true;
        public static bool ShowChartDt = true;
        public static bool ShowChartFvgZones = false;
        public static int MaxChartMarks = 250;
        public static long ChartReviewRevision { get; private set; }

        public static void Publish(List<KeystoneArcEvent> events, KeystoneArcRunConfig config)
        {
            lock (Sync)
            {
                latestEvents.Clear();
                eventsByFiveMinuteBar.Clear();
                if (events != null)
                {
                    foreach (KeystoneArcEvent e in events)
                    {
                        KeystoneArcEvent copy = Clone(e);
                        latestEvents.Add(copy);
                        string key = EventKey(copy.Symbol, copy.TriggerTime);
                        List<KeystoneArcEvent> bucket;
                        if (!eventsByFiveMinuteBar.TryGetValue(key, out bucket)) { bucket = new List<KeystoneArcEvent>(); eventsByFiveMinuteBar[key] = bucket; }
                        bucket.Add(copy);
                    }
                }
                latestConfig = config ?? new KeystoneArcRunConfig();
                ChartReviewRevision++;
            }
        }

        public static List<KeystoneArcEvent> Snapshot(string symbol)
        {
            string root = (symbol ?? string.Empty).Trim().Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries).FirstOrDefault() ?? string.Empty;
            lock (Sync)
                return latestEvents.Where(x => string.Equals(x.Symbol, root, StringComparison.OrdinalIgnoreCase)).Where(ChartReviewIncludes).Select(Clone).ToList();
        }

        public static List<KeystoneArcEvent> SnapshotAt(string symbol, DateTime fiveMinuteTime)
        {
            lock (Sync)
            {
                List<KeystoneArcEvent> bucket;
                if (!eventsByFiveMinuteBar.TryGetValue(EventKey(symbol, fiveMinuteTime), out bucket)) return new List<KeystoneArcEvent>();
                return bucket.Where(ChartReviewIncludes).Select(Clone).ToList();
            }
        }

        private static string EventKey(string symbol, DateTime time)
        {
            string root = (symbol ?? string.Empty).Trim().Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries).FirstOrDefault() ?? string.Empty;
            return root.ToUpperInvariant() + "|" + time.Ticks.ToString(CultureInfo.InvariantCulture);
        }

        private static bool ChartReviewIncludes(KeystoneArcEvent e)
        {
            if (e == null) return false;
            if (e.SetupClass == "BH" && !ShowChartBh) return false;
            if (e.SetupClass == "FVG" && !ShowChartFvg) return false;
            if (e.SetupClass == "DT" && !ShowChartDt) return false;
            if (e.Outcome == "WIN") return ShowChartWins;
            if (e.Outcome.StartsWith("LOSS")) return ShowChartLosses;
            if (e.Outcome == "SESSION EXIT") return ShowChartSessionExits;
            if (e.Outcome == "NO ENTRY DATA") return ShowChartNoEntryData;
            return false;
        }

        private static KeystoneArcEvent Clone(KeystoneArcEvent x)
        {
            return new KeystoneArcEvent
            {
                Id = x.Id, Symbol = x.Symbol, SetupClass = x.SetupClass, Direction = x.Direction, StrengthTag = x.StrengthTag,
                ReferenceTime = x.ReferenceTime, TriggerTime = x.TriggerTime, EntryTime = x.EntryTime, Entry = x.Entry, Stop = x.Stop, Quantity = x.Quantity, StopDistance = x.StopDistance, RiskModel = x.RiskModel,
                Target = x.Target, ExitTime = x.ExitTime, ExitPrice = x.ExitPrice, Outcome = x.Outcome, GrossPnl = x.GrossPnl, PeakAfterEntry = x.PeakAfterEntry, TroughAfterEntry = x.TroughAfterEntry, TargetTouched = x.TargetTouched, StopTouched = x.StopTouched,
                SessionOrder = x.SessionOrder, FvgLower = x.FvgLower, FvgUpper = x.FvgUpper, FvgFormedTime = x.FvgFormedTime, FvgVisit = x.FvgVisit, FvgRedRun = x.FvgRedRun, FvgDrop = x.FvgDrop, FvgGap = x.FvgGap, QualityScore = x.QualityScore, QualityTier = x.QualityTier, FeatureAtr = x.FeatureAtr, FeatureDipPercent = x.FeatureDipPercent, FeatureGreenBody = x.FeatureGreenBody, AssignedVirtualAccount = x.AssignedVirtualAccount,
                SkipReason = x.SkipReason, ConfigurationKey = x.ConfigurationKey, ReviewState = x.ReviewState, ReviewNote = x.ReviewNote,
                AsianLegNumber = x.AsianLegNumber, AsianCyclePnlAtExit = x.AsianCyclePnlAtExit, AsianCycleWorstAtExit = x.AsianCycleWorstAtExit,
                GoldenRunBeforeStop = x.GoldenRunBeforeStop, GoldenStopHit = x.GoldenStopHit, MoveMfe = x.MoveMfe, MoveMae = x.MoveMae, MoveMaeBeforeMfe = x.MoveMaeBeforeMfe, MoveClose = x.MoveClose, MoveMfeMinutes = x.MoveMfeMinutes, MoveHeat = x.MoveHeat
            };
        }
    }

    public static class KeystoneArcEngine
    {
        private sealed class Asian75Position
        {
            public string Symbol;
            public int LegNumber;
            public int Quantity;
            public int Direction; // +1 long, -1 short
            public DateTime EntryTime;
            public double EntryPrice;
            public bool PendingEntry;
            public DateTime PendingAt;
            public int PendingDirection;
            public int PendingQuantity;
            public bool Halted;
            // Realized loss is held per instrument so an optional instrument cap can stop MNQ
            // without pretending that MGC must also stop. It is never used to synthesize a price.
            public double RealizedPnl;
            // Highest / lowest price traded while the current leg was open (chart MFE / MAE).
            public double LegHigh, LegLow;
        }

        private sealed class BullishFvg
        {
            public double Lower;
            public double Upper;
            public DateTime Formed;
            public bool Touched;
            public DateTime PendingReference;
            public double PendingHigh;
            public bool Invalid;
        }

        public static List<KeystoneArcBar> ToSetupBars(List<KeystoneArcBar> oneMinute, string symbol, int minutes)
        {
            var result = new List<KeystoneArcBar>();
            if (oneMinute == null) return result;
            minutes = minutes == 1 ? 1 : 5;
            foreach (var group in oneMinute.Where(x => x != null).OrderBy(x => x.Time)
                .GroupBy(x => new DateTime(x.Time.Year, x.Time.Month, x.Time.Day, x.Time.Hour, (x.Time.Minute / minutes) * minutes, 0)))
            {
                var items = group.ToList();
                if (items.Count == 0) continue;
                result.Add(new KeystoneArcBar
                {
                    Time = group.Key,
                    Symbol = symbol,
                    Open = items[0].Open,
                    High = items.Max(x => x.High),
                    Low = items.Min(x => x.Low),
                    Close = items[items.Count - 1].Close,
                    Volume = items.Sum(x => x.Volume)
                });
            }
            return result;
        }

        public static List<KeystoneArcEvent> DetectAndResolve(List<KeystoneArcBar> oneMinute, KeystoneArcRunConfig cfg)
        {
            return DetectAndResolve(oneMinute, null, cfg);
        }

        public static List<KeystoneArcEvent> DetectAndResolve(List<KeystoneArcBar> oneMinute, List<KeystoneArcBar> directSetupBars, KeystoneArcRunConfig cfg)
        {
            List<KeystoneArcEvent> result = DetectAndResolveCore(oneMinute, directSetupBars, cfg);
            ApplyTradingCosts(result, cfg);
            return result;
        }

        // Real-world costs on every resolved trade: round-trip commission per contract plus
        // slippage (ticks per side, entry and exit). 0 / 0 (default) = the original gross model.
        public static double TradingCost(KeystoneArcEvent e, KeystoneArcRunConfig cfg)
        {
            if (e == null || cfg == null || (cfg.CommissionPerContract <= 0 && cfg.SlippageTicks <= 0)) return 0;
            double qty = Math.Max(0, e.Quantity > 0 ? e.Quantity : cfg.Quantity);
            double tickValue = IsMgc(e.Symbol) ? 1.0 : 0.5; // MGC 0.1 × $10, MNQ 0.25 × $2
            return qty * (Math.Max(0, cfg.CommissionPerContract) + 2 * Math.Max(0, cfg.SlippageTicks) * tickValue);
        }

        private static void ApplyTradingCosts(List<KeystoneArcEvent> events, KeystoneArcRunConfig cfg)
        {
            if (events == null || cfg == null || (cfg.CommissionPerContract <= 0 && cfg.SlippageTicks <= 0)) return;
            foreach (KeystoneArcEvent e in events)
            {
                string o = e.Outcome ?? string.Empty;
                bool traded = o == "WIN" || o.StartsWith("LOSS", StringComparison.OrdinalIgnoreCase) || o == "SESSION EXIT" || o == "BREAKEVEN";
                if (!traded) continue;
                double cost = TradingCost(e, cfg);
                e.GrossPnl -= cost;
                if (!string.IsNullOrEmpty(e.EvaluationOutcome) && e.EvaluationOutcome != "OPEN") e.EvaluationGrossPnl -= cost;
            }
        }

        // SELL setups = the same detector on the price mirrored around K (open/high/low/close → K − open / K − low / K − high /
        // K − close): a bullish gap / break of a high there is a bearish gap / break of a low here. The events are mapped back
        // (prices K − x, SHORT). The BUY path is untouched, so the long results stay exactly as they were.
        public static List<KeystoneArcBar> Mirror(List<KeystoneArcBar> bars, double k)
        {
            return bars.Select(b => new KeystoneArcBar { Symbol = b.Symbol, Time = b.Time, Open = k - b.Open, High = k - b.Low, Low = k - b.High, Close = k - b.Close, Volume = b.Volume }).ToList();
        }

        public static double MirrorConstant(List<KeystoneArcBar> a, List<KeystoneArcBar> b)
        {
            double hi = Math.Max(a == null || a.Count == 0 ? 0 : a.Max(x => x.High), b == null || b.Count == 0 ? 0 : b.Max(x => x.High));
            return 2 * Math.Ceiling(hi + 1);
        }

        public static void Unmirror(KeystoneArcEvent e, double k)
        {
            Func<double, double> m = x => double.IsNaN(x) ? x : k - x;
            e.Entry = m(e.Entry); e.Stop = m(e.Stop); e.Target = m(e.Target); e.ExitPrice = m(e.ExitPrice);
            e.EvaluationExitPrice = m(e.EvaluationExitPrice); e.EvaluationTarget = m(e.EvaluationTarget); e.EvaluationStop = m(e.EvaluationStop);
            double peak = e.PeakAfterEntry; e.PeakAfterEntry = m(e.TroughAfterEntry); e.TroughAfterEntry = m(peak);
            double lo = e.FvgLower; e.FvgLower = m(e.FvgUpper); e.FvgUpper = m(lo);
            e.GoldenStartPrice = m(e.GoldenStartPrice); e.GoldenLowPrice = m(e.GoldenLowPrice);
            e.Direction = "SHORT";
            e.Id = (e.Id ?? string.Empty).Contains("|LONG|") ? e.Id.Replace("|LONG|", "|SHORT|") : (e.Id ?? string.Empty) + "|SHORT";
            if (!string.IsNullOrEmpty(e.RiskModel)) e.RiskModel = e.RiskModel + " • SELL (BREAK OF THE LOW)";
        }

        private static List<KeystoneArcEvent> Sided(List<KeystoneArcBar> raw, List<KeystoneArcBar> bars, KeystoneArcRunConfig cfg, Func<List<KeystoneArcBar>, List<KeystoneArcBar>, List<KeystoneArcEvent>> detect)
        {
            string side = (cfg.TradeSide ?? "BUY").ToUpperInvariant(); var output = new List<KeystoneArcEvent>();
            if (side != "SELL") output.AddRange(detect(raw, bars));
            if (side == "SELL" || side == "BOTH")
            {
                double k = MirrorConstant(raw, bars);
                var mr = Mirror(raw, k); var mb = ReferenceEquals(raw, bars) ? mr : Mirror(bars, k);
                var sells = detect(mr, mb); foreach (var e in sells) Unmirror(e, k);
                output.AddRange(sells);
                if (side == "BOTH") output = output.OrderBy(e => e.TriggerTime).ToList();
            }
            return output;
        }

        private static List<KeystoneArcEvent> DetectAndResolveCore(List<KeystoneArcBar> oneMinute, List<KeystoneArcBar> directSetupBars, KeystoneArcRunConfig cfg)
        {
            var events = new List<KeystoneArcEvent>();
            if (oneMinute == null || cfg == null) return events;
            // BH sells: the BH detector on the mirrored price (a break of a low), mapped back; the BUY path is untouched.
            string side = (cfg.TradeSide ?? "BUY").ToUpperInvariant();
            if (string.Equals(cfg.StrategyCode, "BH", StringComparison.OrdinalIgnoreCase) && (side == "SELL" || side == "BOTH"))
            {
                var buyCfg = cfg.ShallowCopy(); buyCfg.TradeSide = "BUY";
                var output = side == "BOTH" ? DetectAndResolveCore(oneMinute, directSetupBars, buyCfg) : new List<KeystoneArcEvent>();
                double k = MirrorConstant(oneMinute, directSetupBars);
                var sells = DetectAndResolveCore(Mirror(oneMinute, k), directSetupBars == null ? null : Mirror(directSetupBars, k), buyCfg);
                foreach (var e in sells) Unmirror(e, k);
                output.AddRange(sells);
                return output.OrderBy(e => e.TriggerTime).ToList();
            }
            if (string.Equals(cfg.StrategyCode, "ASIAN75", StringComparison.OrdinalIgnoreCase))
                return DetectAsian75Reversal(oneMinute, cfg);
            foreach (string symbol in oneMinute.Select(x => x.Symbol).Distinct(StringComparer.OrdinalIgnoreCase))
            {
                var raw = oneMinute.Where(x => string.Equals(x.Symbol, symbol, StringComparison.OrdinalIgnoreCase)).OrderBy(x => x.Time).ToList();
                var bars = directSetupBars == null ? new List<KeystoneArcBar>() : directSetupBars.Where(x => string.Equals(x.Symbol, symbol, StringComparison.OrdinalIgnoreCase)).OrderBy(x => x.Time).ToList();
                if (bars.Count == 0) bars = ToSetupBars(raw, symbol, cfg.SetupMinutes);
                if (string.Equals(cfg.StrategyCode, "FVG", StringComparison.OrdinalIgnoreCase)) { events.AddRange(Sided(raw, bars, cfg, (r, b) => DetectFvgRetest(r, b, cfg, symbol))); continue; }
                if (string.Equals(cfg.StrategyCode, "ENG", StringComparison.OrdinalIgnoreCase)) { events.AddRange(DetectEngulfing(raw, bars, cfg, symbol)); continue; }
                if (string.Equals(cfg.StrategyCode, "RLY", StringComparison.OrdinalIgnoreCase)) { events.AddRange(DetectLastHourRelay(raw, cfg, symbol)); continue; }
                if (string.Equals(cfg.StrategyCode, "VWP", StringComparison.OrdinalIgnoreCase)) { events.AddRange(DetectVwapSnapBack(raw, bars, cfg, symbol)); continue; }
                if (string.Equals(cfg.StrategyCode, "GLD", StringComparison.OrdinalIgnoreCase)) { events.AddRange(Sided(raw, bars, cfg, (r, b) => DetectGolden(r, b, cfg, symbol))); continue; }
                if (string.Equals(cfg.StrategyCode, "MAD", StringComparison.OrdinalIgnoreCase)) { events.AddRange(DetectMicroADay(raw, cfg, symbol)); continue; }
                int order = 0;
                DateTime orderDay = DateTime.MinValue;
                var zones = new List<BullishFvg>();
                for (int i = 2; i < bars.Count; i++)
                {
                    KeystoneArcBar current = bars[i];
                    if (current.Time < cfg.Start) continue;
                    if (current.Time > cfg.End) break;
                    DateTime tradingDay = SessionGroupingDate(current.Time, cfg);
                    if (orderDay != tradingDay)
                    {
                        orderDay = tradingDay;
                        order = 0;
                    }
                    if (!InsideSession(current.Time, symbol, cfg))
                    {
                        if (cfg.EnableFvg == 1) DetectNewBullishFvg(bars, i, zones);
                        continue;
                    }

                    // Resolve a pending FVG reference only on the immediately following selected-timeframe bar.
                    // The retained FVG implementation is a bullish long setup. When this
                    // instrument is set to SELL, it is intentionally excluded until the separate
                    // bearish-FVG contract is enabled rather than falsely labeling it short.
                    var fvgEvent = cfg.EnableFvg == 1 && DirectionAllows(symbol, "LONG", cfg) ? ResolveFvgBreak(current, zones, cfg, symbol, bars, i) : null;
                    KeystoneArcEvent bhEvent = cfg.EnableBh == 1 ? DetectBhBreak(bars, i, cfg, symbol) : null;
                    if (bhEvent != null || fvgEvent != null)
                    {
                        order++;
                        KeystoneArcEvent e = fvgEvent ?? bhEvent;
                        if (bhEvent != null && fvgEvent != null) e.SetupClass = "DT";
                        e.SessionOrder = order;
                        e.StrengthTag = Strength(bars, i);
                        e.ConfigurationKey = cfg.Snapshot();
                        ResolveOutcome(e, raw, cfg, symbol);
                        ResolveEvaluationStageOutcome(e, raw, cfg, symbol);
                        events.Add(e);
                    }

                    if (cfg.EnableFvg == 1) { UpdateFvgTouchState(current, zones, cfg); DetectNewBullishFvg(bars, i, zones); }
                }
            }
            return events.OrderBy(x => x.TriggerTime).ThenBy(x => x.Symbol).ToList();
        }

        // Asian is not a pattern detector.  This receipt deliberately reports only whether the
        // exact configured opening minute exists for every selected instrument.  It never creates
        // a price, substitutes a nearby bar, or changes the historical request path.
        public static string AsianCycleReadinessReceipt(IEnumerable<KeystoneArcBar> source, KeystoneArcRunConfig cfg)
        {
            if (cfg == null) return "ASIAN CYCLE DIAGNOSTIC: configuration unavailable.";
            List<KeystoneArcBar> all = (source ?? Enumerable.Empty<KeystoneArcBar>()).Where(x => x != null).OrderBy(x => x.Time).ThenBy(x => x.Symbol, StringComparer.OrdinalIgnoreCase).ToList();
            if (all.Count == 0) return "ASIAN CYCLE DIAGNOSTIC: no direct 1-minute bars were supplied to the cycle engine.";
            string[] symbols = AsianSelectedSymbols(cfg);
            DateTime first = SessionGroupingDate(cfg.Start, cfg).Date;
            DateTime last = SessionGroupingDate(cfg.End, cfg).Date;
            if (last < first) last = first;
            var lines = new List<string>();
            int stampOffset = AsianBarStampOffsetMinutes(all, cfg);
            for (DateTime sessionDate = first; sessionDate <= last; sessionDate = sessionDate.AddDays(1))
            {
                DateTime start = AsianDateAtHhmm(sessionDate, cfg.AsianStartHhmm).AddMinutes(stampOffset);
                DateTime end = AsianDateAtHhmm(sessionDate, cfg.AsianEndHhmm);
                if (end < start) end = end.AddDays(1);
                var states = new List<string>();
                bool ready = true;
                foreach (string symbol in symbols)
                {
                    List<KeystoneArcBar> symbolBars = all.Where(x => string.Equals(x.Symbol, symbol, StringComparison.OrdinalIgnoreCase)).ToList();
                    List<KeystoneArcBar> bars = symbolBars.Where(x => x.Time >= start && x.Time <= end).ToList();
                    KeystoneArcBar opening = bars.FirstOrDefault(x => x.Time == start);
                    if (opening != null)
                    {
                        states.Add(symbol + " exact " + start.ToString("HH:mm") + " OPEN " + opening.Open.ToString("0.####", CultureInfo.InvariantCulture));
                        continue;
                    }
                    ready = false;
                    KeystoneArcBar before = symbolBars.Where(x => x.Time < start).OrderByDescending(x => x.Time).FirstOrDefault();
                    KeystoneArcBar after = symbolBars.Where(x => x.Time > start).OrderBy(x => x.Time).FirstOrDefault();
                    string range = bars.Count == 0 ? "no bars in configured window" : (bars.First().Time.ToString("HH:mm") + "→" + bars.Last().Time.ToString("HH:mm"));
                    states.Add(symbol + " MISSING exact " + start.ToString("HH:mm") + " • window " + range + " • previous " + (before == null ? "none" : before.Time.ToString("yyyy-MM-dd HH:mm")) + " • next " + (after == null ? "none" : after.Time.ToString("yyyy-MM-dd HH:mm")));
                }
                lines.Add(sessionDate.ToString("yyyy-MM-dd") + " • " + (ready ? "CYCLE READY" : "NO CYCLE — exact simultaneous opening bar required") + " • " + string.Join(" | ", states));
            }
            return "ASIAN CYCLE DIAGNOSTIC • entry " + cfg.AsianStartHhmm.ToString("0000") + " ET • selected scope " + cfg.Scope + " • " + AsianStampDescription(stampOffset, cfg) + " • exact opening-bar policy (no nearest-bar substitute)\n" + string.Join("\n", lines);
        }

        // NinjaTrader stamps a completed minute bar with its CLOSING time: the bar that trades
        // 18:00:00–18:00:59 is stamped 18:01. Some other feeds stamp the OPENING minute instead.
        // The Asian cycle enters at the configured minute's opening price, so the engine must
        // know which stamp that bar carries. The convention is read from the data itself: after
        // a trading pause (the daily 17:00–18:00 halt or the weekend), a close-stamped series
        // resumes at :01 and an open-stamped series at :00. Returns minutes to add to a clock
        // time to get the stamp of the bar that opens at that time (1 = close-stamped).
        // Undetermined data defaults to the NinjaTrader close-stamp convention.
        private static int AsianBarStampOffsetMinutes(List<KeystoneArcBar> all, KeystoneArcRunConfig cfg)
        {
            int openStamped = 0, closeStamped = 0;
            foreach (IGrouping<string, KeystoneArcBar> series in all.Where(x => x != null).GroupBy(x => x.Symbol ?? string.Empty, StringComparer.OrdinalIgnoreCase))
            {
                KeystoneArcBar previous = null;
                foreach (KeystoneArcBar bar in series.OrderBy(x => x.Time))
                {
                    bool resumed = previous == null || (bar.Time - previous.Time).TotalMinutes >= 30;
                    if (resumed && bar.Time.Hour == 18 && bar.Time.Minute == 0) openStamped++;
                    if (resumed && bar.Time.Hour == 18 && bar.Time.Minute == 1) closeStamped++;
                    previous = bar;
                }
            }
            return openStamped > closeStamped ? 0 : 1;
        }

        private static string AsianStampDescription(int stampOffset, KeystoneArcRunConfig cfg)
        {
            DateTime clock = AsianDateAtHhmm(DateTime.Today, cfg.AsianStartHhmm);
            return stampOffset == 1
                ? "bars are close-stamped (NinjaTrader standard): the " + clock.ToString("HH:mm") + " opening minute is the bar stamped " + clock.AddMinutes(1).ToString("HH:mm")
                : "bars are open-stamped: the " + clock.ToString("HH:mm") + " opening minute is the bar stamped " + clock.ToString("HH:mm");
        }

        private static string[] AsianSelectedSymbols(KeystoneArcRunConfig cfg)
        {
            if (cfg != null && string.Equals(cfg.Scope, "MNQ", StringComparison.OrdinalIgnoreCase)) return new[] { "MNQ" };
            if (cfg != null && string.Equals(cfg.Scope, "MGC", StringComparison.OrdinalIgnoreCase)) return new[] { "MGC" };
            return new[] { "MNQ", "MGC" };
        }

        // Research-only Asian cycle backtest. It operates directly on validated 1-minute bars:
        // each selected instrument enters at the exact chosen opening minute, reverses at the
        // next 1M bar open after its own limit, and adds one micro. The combined target/stop
        // decision is deliberately 1M-close confirmed because OHLC data cannot establish
        // cross-instrument intrabar ordering.
        private static List<KeystoneArcEvent> DetectAsian75Reversal(List<KeystoneArcBar> oneMinute, KeystoneArcRunConfig cfg)
        {
            return SimulateAsian75Sessions(PrepareAsian75Sessions(oneMinute, cfg), cfg);
        }

        // AUTO daily loss ceiling shared by the lab and the optimizer. FIXED CASH keeps the lab's
        // original rule (leg loss × max reversals × instruments). PRICE MOVE legs grow ($x1, 2×x1,
        // 3×x1 …), so the ceiling is every leg of every selected instrument being stopped out.
        public static double AsianAutoDailyLossLimit(string riskMode, string scope, double cashLegLoss, double mnqPriceMove, double mgcPriceMove, int reversals)
        {
            reversals = Math.Max(1, reversals);
            bool mnq = scope != "MGC", mgc = scope != "MNQ";
            if (string.Equals(riskMode, "PRICE", StringComparison.OrdinalIgnoreCase))
            {
                double legSum = (reversals + 1) * (reversals + 2) / 2.0;
                return legSum * ((mnq ? Math.Max(0, mnqPriceMove) * 2.0 : 0) + (mgc ? Math.Max(0, mgcPriceMove) * 10.0 : 0));
            }
            return Math.Max(0, cashLegLoss) * reversals * (mnq && mgc ? 2 : 1);
        }

        public sealed class MgcRollSegment
        {
            public DateTime ContractMonth;   // first day of the delivery month, e.g. 2026-12-01 = MGC 12-26
            public DateTime Start;
            public DateTime End;
        }

        // Gold's liquid contracts are Feb, Apr, Jun, Aug and Dec (Oct is thin). Trading moves to
        // the next of these about a week before first notice day (end of the month before
        // delivery), so each contract is used until 17:00 ET on the 24th of the month before its
        // delivery month. 17:00 is inside the daily 17:00–18:00 halt, so every session comes
        // from one contract and no fake price jump from a contract switch lands inside a session.
        // Using each contract until its expiry (the old rule) read weeks of thin delivery-month
        // bars and left the range empty once the last requested contract expired.
        public static List<MgcRollSegment> MgcLiquidRollSchedule(DateTime start, DateTime end)
        {
            var segments = new List<MgcRollSegment>();
            int[] liquid = { 2, 4, 6, 8, 12 };
            DateTime cursor = start;
            for (int guard = 0; cursor < end && guard < 400; guard++)
            {
                DateTime month = new DateTime(cursor.Year, cursor.Month, 1), contract = DateTime.MinValue, roll = DateTime.MinValue;
                for (int k = 0; k <= 14; k++)
                {
                    DateTime candidate = month.AddMonths(k);
                    if (!liquid.Contains(candidate.Month)) continue;
                    DateTime before = candidate.AddMonths(-1);
                    DateTime candidateRoll = new DateTime(before.Year, before.Month, 24, 17, 0, 0);
                    if (candidateRoll > cursor) { contract = candidate; roll = candidateRoll; break; }
                }
                if (contract == DateTime.MinValue) break;
                DateTime segmentEnd = roll < end ? roll : end;
                segments.Add(new MgcRollSegment { ContractMonth = contract, Start = cursor, End = segmentEnd });
                cursor = roll.AddMinutes(1);
            }
            return segments;
        }

        // One Asian session's 1-minute bars laid out for fast repeated simulation: Times holds
        // every distinct bar stamp in the window, and Bars[s][t] is symbol s's bar at Times[t]
        // (null when that minute had no trade). Built once per start/end time and instrument
        // scope, then reused by every parameter combination the optimizer tests.
        public sealed class Asian75Session
        {
            public DateTime SessionDate;
            public DateTime OpeningStamp;
            public string[] Symbols;
            public DateTime[] Times;
            public KeystoneArcBar[][] Bars;
            public bool OpeningComplete;
        }

        public static List<Asian75Session> PrepareAsian75Sessions(List<KeystoneArcBar> oneMinute, KeystoneArcRunConfig cfg)
        {
            var sessions = new List<Asian75Session>();
            if (oneMinute == null || cfg == null) return sessions;
            string[] symbols = AsianSelectedSymbols(cfg);
            List<KeystoneArcBar> all = oneMinute.Where(x => x != null && symbols.Contains(x.Symbol ?? string.Empty, StringComparer.OrdinalIgnoreCase)).OrderBy(x => x.Time).ToList();
            // Stamp of the bar that OPENS at the configured start minute (18:01 for NinjaTrader's
            // close-stamped 1M bars). Requiring a bar stamped exactly 18:00 skipped every session.
            int stampOffset = AsianBarStampOffsetMinutes(all, cfg);
            foreach (IGrouping<DateTime, KeystoneArcBar> day in all.GroupBy(x => SessionGroupingDate(x.Time, cfg)).OrderBy(x => x.Key))
            {
                DateTime sessionDate = day.Key.Date;
                DateTime start = AsianDateAtHhmm(sessionDate, cfg.AsianStartHhmm).AddMinutes(stampOffset);
                DateTime end = AsianDateAtHhmm(sessionDate, cfg.AsianEndHhmm);
                if (end < start) end = end.AddDays(1);
                List<KeystoneArcBar> range = day.Where(x => x.Time >= start && x.Time <= end).ToList();
                if (range.Count == 0) continue;
                DateTime[] times = range.Select(x => x.Time).Distinct().OrderBy(x => x).ToArray();
                var index = new Dictionary<DateTime, int>(times.Length);
                for (int t = 0; t < times.Length; t++) index[times[t]] = t;
                var bars = new KeystoneArcBar[symbols.Length][];
                for (int s = 0; s < symbols.Length; s++) bars[s] = new KeystoneArcBar[times.Length];
                foreach (KeystoneArcBar b in range)
                {
                    int s = Array.FindIndex(symbols, x => string.Equals(x, b.Symbol, StringComparison.OrdinalIgnoreCase));
                    bars[s][index[b.Time]] = b;
                }
                // BOTH is one shared cycle, not two independent optional cycles. A selected
                // instrument lacking its exact configured opening 1M bar makes that session
                // unavailable rather than silently testing only the other instrument. No 17:59
                // carry-forward or nearest-bar proxy is permitted.
                bool openingComplete = times[0] == start;
                for (int s = 0; s < symbols.Length && openingComplete; s++) openingComplete = bars[s][0] != null;
                sessions.Add(new Asian75Session { SessionDate = sessionDate, OpeningStamp = start, Symbols = symbols, Times = times, Bars = bars, OpeningComplete = openingComplete });
            }
            return sessions;
        }

        public static List<KeystoneArcEvent> SimulateAsian75Sessions(List<Asian75Session> sessions, KeystoneArcRunConfig cfg)
        {
            var output = new List<KeystoneArcEvent>();
            bool invalidRisk = AsianUsesPriceRisk(cfg)
                ? (cfg.AsianMnqReversalPriceMove <= 0 || cfg.AsianMgcReversalPriceMove <= 0)
                : cfg.AsianReversalLossDollars <= 0;
            if (invalidRisk || cfg.AsianCycleTargetDollars <= 0 || cfg.AsianDailyLossLimitDollars <= 0 || cfg.AsianStartingQuantity <= 0 || cfg.AsianMnqMaxReversals < 0 || cfg.AsianMgcMaxReversals < 0) return output;
            foreach (Asian75Session session in sessions ?? new List<Asian75Session>())
                if (session.OpeningComplete) SimulateAsian75Session(session, cfg, output);
            string configurationKey = cfg.Snapshot();
            output = output.OrderBy(x => x.TriggerTime).ThenBy(x => x.Symbol, StringComparer.OrdinalIgnoreCase).ThenBy(x => x.EntryTime).ToList();
            int order = 0; DateTime orderDay = DateTime.MinValue;
            foreach (KeystoneArcEvent e in output)
            {
                DateTime day = SessionGroupingDate(e.TriggerTime, cfg);
                if (day != orderDay) { orderDay = day; order = 0; }
                e.SessionOrder = ++order; e.ConfigurationKey = configurationKey;
            }
            return output;
        }

        private static void SimulateAsian75Session(Asian75Session session, KeystoneArcRunConfig cfg, List<KeystoneArcEvent> output)
        {
            DateTime sessionDate = session.SessionDate;
            int n = session.Symbols.Length;
            var positions = new Asian75Position[n];
            var latestClose = new double[n];
            var hasClose = new bool[n];
            for (int s = 0; s < n; s++)
            {
                KeystoneArcBar opening = session.Bars[s][0];
                positions[s] = new Asian75Position { Symbol = session.Symbols[s], LegNumber = 1, Quantity = cfg.AsianStartingQuantity, Direction = AsianInitialDirection(session.Symbols[s], cfg), EntryTime = session.OpeningStamp, EntryPrice = opening.Open, LegHigh = opening.Open, LegLow = opening.Open };
            }
            double[] stopPrice = new double[n];
            for (int s = 0; s < n; s++) stopPrice[s] = Asian75StopPrice(positions[s], cfg);
            double combinedPeakMarked = double.MinValue, combinedLowMarked = 0;
            var closedThisMinute = new List<KeystoneArcEvent>();
            for (int t = 0; t < session.Times.Length; t++)
            {
                DateTime time = session.Times[t];
                for (int s = 0; s < n; s++) { KeystoneArcBar b = session.Bars[s][t]; if (b != null) { latestClose[s] = b.Close; hasClose[s] = true; } }
                // A minute with no trades has no bar, so the reversal enters on the first bar at
                // or after the next minute rather than waiting for an exact stamp forever.
                for (int s = 0; s < n; s++)
                {
                    Asian75Position p = positions[s]; KeystoneArcBar b = session.Bars[s][t];
                    if (!p.PendingEntry || p.PendingAt > time || b == null) continue;
                    p.PendingEntry = false; p.Direction = p.PendingDirection; p.Quantity = p.PendingQuantity; p.LegNumber++; p.EntryTime = time; p.EntryPrice = b.Open;
                    p.LegHigh = b.Open; p.LegLow = b.Open;
                    stopPrice[s] = Asian75StopPrice(p, cfg);
                }
                // Every leg enters at a bar's OPEN, so that bar's whole high/low range happens
                // after the entry and must be checked for the stop as well.
                KeystoneArcEvent lastLossThisMinute = null;
                closedThisMinute.Clear();
                for (int s = 0; s < n; s++)
                {
                    Asian75Position p = positions[s]; KeystoneArcBar b = session.Bars[s][t];
                    if (p.Halted || p.PendingEntry || p.EntryTime > time || b == null) continue;
                    double stop = stopPrice[s];
                    bool hit = p.Direction > 0 ? b.Low <= stop : b.High >= stop;
                    if (!hit) { p.LegHigh = Math.Max(p.LegHigh, b.High); p.LegLow = Math.Min(p.LegLow, b.Low); continue; }
                    // A bar that opens beyond the stop cannot fill at the stop; use its open.
                    bool gapped = p.Direction > 0 ? b.Open < stop : b.Open > stop;
                    double fill = gapped ? b.Open : stop;
                    // Within the stop bar only the move to the fill is known to precede the exit.
                    p.LegHigh = Math.Max(p.LegHigh, fill); p.LegLow = Math.Min(p.LegLow, fill);
                    double reversalLoss = Asian75OpenPnl(p, fill);
                    p.RealizedPnl += reversalLoss;
                    int maxTotalLegs = Math.Max(1, AsianMaxReversalsForSymbol(p.Symbol, cfg) + 1);
                    double instrumentCap = AsianInstrumentCapForSymbol(p.Symbol, cfg);
                    bool instrumentStop = instrumentCap > 0 && p.RealizedPnl <= -Math.Abs(instrumentCap);
                    string lossNote = "REVERSAL LOSS • " + AsianRiskDescription(p, cfg);
                    if (gapped) lossNote += " • GAP: FILLED AT BAR OPEN BEYOND STOP";
                    if (instrumentStop) lossNote += " • INSTRUMENT LOSS CAP REACHED";
                    else if (p.LegNumber >= maxTotalLegs) lossNote += " • MAX REVERSALS REACHED";
                    lastLossThisMinute = NewAsian75Event(p, sessionDate, fill, time, "LOSS", reversalLoss, cfg, lossNote);
                    output.Add(lastLossThisMinute); closedThisMinute.Add(lastLossThisMinute);
                    if (instrumentStop || p.LegNumber >= maxTotalLegs) p.Halted = true;
                    else { p.PendingEntry = true; p.PendingAt = time.AddMinutes(1); p.PendingDirection = -p.Direction; p.PendingQuantity = p.Quantity + 1; }
                }
                // Realized reversal losses booked this session plus every open leg marked to its
                // latest 1M close.
                double marked = 0;
                for (int s = 0; s < n; s++)
                {
                    Asian75Position p = positions[s];
                    marked += p.RealizedPnl;
                    if (!p.Halted && !p.PendingEntry && hasClose[s]) marked += Asian75OpenPnl(p, latestClose[s]);
                }
                combinedPeakMarked = Math.Max(combinedPeakMarked, marked);
                combinedLowMarked = Math.Min(combinedLowMarked, marked);
                foreach (KeystoneArcEvent closedLeg in closedThisMinute) { closedLeg.AsianCyclePnlAtExit = marked; closedLeg.AsianCycleWorstAtExit = combinedLowMarked; }
                string outcome = null, reason = null;
                if (marked >= cfg.AsianCycleTargetDollars) { outcome = "WIN"; reason = "CYCLE TARGET • 1M CLOSE CONFIRMED"; }
                else if (cfg.AsianCombinedStopLossDollars > 0 && marked <= -Math.Abs(cfg.AsianCombinedStopLossDollars))
                {
                    if (lastLossThisMinute != null) lastLossThisMinute.ReviewNote = (lastLossThisMinute.ReviewNote ?? string.Empty) + " • COMBINED CYCLE STOP REACHED";
                    outcome = "LOSS"; reason = "COMBINED CYCLE STOP • 1M CLOSE CONFIRMED";
                }
                // Minute OHLC cannot prove the exact intraminute flat print after the trigger.
                // Exit at the known completed-bar close and preserve actual P/L.
                else if (cfg.AsianBreakEvenTriggerDollars > 0 && combinedPeakMarked >= cfg.AsianBreakEvenTriggerDollars && marked <= 0) { outcome = "BREAKEVEN GUARD"; reason = "BREAKEVEN GUARD • PROFIT TRIGGER REACHED; 1M CLOSE RETURNED TO FLAT/NEGATIVE"; }
                else if (marked <= -Math.Abs(cfg.AsianDailyLossLimitDollars)) { outcome = "LOSS"; reason = "DAILY LOSS LIMIT • 1M CLOSE CONFIRMED"; }
                if (outcome != null) { CloseAsian75Positions(output, positions, latestClose, hasClose, sessionDate, time, outcome, reason, cfg, marked, combinedLowMarked); return; }
            }
            double finalMarked = 0;
            for (int s = 0; s < n; s++) { finalMarked += positions[s].RealizedPnl; if (!positions[s].Halted && !positions[s].PendingEntry && hasClose[s]) finalMarked += Asian75OpenPnl(positions[s], latestClose[s]); }
            CloseAsian75Positions(output, positions, latestClose, hasClose, sessionDate, session.Times[session.Times.Length - 1], "SESSION EXIT", "SESSION END • LAST AVAILABLE 1M CLOSE", cfg, finalMarked, Math.Min(combinedLowMarked, finalMarked));
        }

        private static void CloseAsian75Positions(List<KeystoneArcEvent> output, Asian75Position[] positions, double[] latestClose, bool[] hasClose, DateTime sessionDate, DateTime time, string outcome, string reason, KeystoneArcRunConfig cfg, double cyclePnl, double cycleWorst)
        {
            for (int s = 0; s < positions.Length; s++)
            {
                Asian75Position p = positions[s];
                if (p.PendingEntry) { p.Halted = true; continue; }
                if (p.Halted || !hasClose[s]) continue;
                KeystoneArcEvent closing = NewAsian75Event(p, sessionDate, latestClose[s], time, outcome, Asian75OpenPnl(p, latestClose[s]), cfg, reason);
                closing.AsianCyclePnlAtExit = cyclePnl; closing.AsianCycleWorstAtExit = cycleWorst;
                output.Add(closing);
                p.Halted = true;
            }
        }

        private static KeystoneArcEvent NewAsian75Event(Asian75Position p, DateTime sessionDate, double exit, DateTime exitTime, string outcome, double pnl, KeystoneArcRunConfig cfg, string note)
        {
            bool reversalLoss = (note ?? string.Empty).StartsWith("REVERSAL LOSS", StringComparison.OrdinalIgnoreCase);
            double cyclePnlThroughEvent = reversalLoss ? p.RealizedPnl : p.RealizedPnl + pnl;
            return new KeystoneArcEvent
            {
                Id = "KA|" + p.Symbol + "|ASIA75|L" + p.LegNumber + "|" + p.EntryTime.Ticks.ToString(CultureInfo.InvariantCulture),
                Symbol = p.Symbol,
                SetupClass = "ASIA75",
                Direction = p.Direction > 0 ? "LONG" : "SHORT",
                StrengthTag = "ASIA 75 • LEG " + p.LegNumber,
                ReferenceTime = AsianDateAtHhmm(sessionDate, cfg.AsianStartHhmm),
                TriggerTime = p.EntryTime,
                EntryTime = p.EntryTime,
                Entry = p.EntryPrice,
                Stop = Asian75StopPrice(p, cfg),
                // Target is combined across active MNQ/MGC legs, not a per-leg price level.
                // Reusing entry prevents a false chart price target from being drawn.
                Target = p.EntryPrice,
                Quantity = p.Quantity,
                StopDistance = Math.Abs(p.EntryPrice - Asian75StopPrice(p, cfg)),
                RiskModel = "ASIAN CYCLE • " + (AsianUsesPriceRisk(cfg) ? "PRICE-MOVE REVERSAL" : "FIXED-CASH REVERSAL") + " • " + AsianRiskDescription(p, cfg) + " • COMBINED $" + cfg.AsianCycleTargetDollars.ToString("0") + " TARGET • CYCLE STOP " + (cfg.AsianCombinedStopLossDollars <= 0 ? "OFF" : "$" + cfg.AsianCombinedStopLossDollars.ToString("0")) + " • INSTRUMENT CAP " + (AsianInstrumentCapForSymbol(p.Symbol, cfg) <= 0 ? "OFF" : "$" + AsianInstrumentCapForSymbol(p.Symbol, cfg).ToString("0")),
                ExitTime = exitTime,
                ExitPrice = exit,
                Outcome = outcome,
                GrossPnl = pnl,
                PeakAfterEntry = Math.Max(Math.Max(p.EntryPrice, exit), p.LegHigh > 0 ? p.LegHigh : p.EntryPrice),
                TroughAfterEntry = Math.Min(Math.Min(p.EntryPrice, exit), p.LegLow > 0 ? p.LegLow : p.EntryPrice),
                AsianLegNumber = p.LegNumber,
                TargetTouched = outcome == "WIN" ? 1 : 0,
                StopTouched = note.StartsWith("REVERSAL LOSS", StringComparison.OrdinalIgnoreCase) ? 1 : 0,
                ReviewState = "ACCEPTED",
                ReviewNote = (note ?? string.Empty) + " • LEG " + p.LegNumber + " • CURRENT CONTRACTS x" + p.Quantity + " • LEG P/L " + pnl.ToString("C0") + " • CYCLE P/L THROUGH EVENT " + cyclePnlThroughEvent.ToString("C0")
            };
        }

        private static DateTime AsianDateAtHhmm(DateTime day, int hhmm)
        {
            int clean = Math.Max(0, Math.Min(2359, hhmm));
            return new DateTime(day.Year, day.Month, day.Day, clean / 100, clean % 100, 0);
        }

        private static int AsianInitialDirection(string symbol, KeystoneArcRunConfig cfg)
        {
            string direction = IsMgc(symbol) ? cfg.AsianMgcInitialDirection : cfg.AsianMnqInitialDirection;
            return string.Equals(direction, "SHORT", StringComparison.OrdinalIgnoreCase) ? -1 : 1;
        }

        private static bool AsianUsesPriceRisk(KeystoneArcRunConfig cfg)
        {
            return cfg != null && string.Equals(cfg.AsianRiskMode, "PRICE", StringComparison.OrdinalIgnoreCase);
        }

        private static double AsianPriceLossMove(string symbol, KeystoneArcRunConfig cfg)
        {
            return Math.Max(0.0001, IsMgc(symbol) ? cfg.AsianMgcReversalPriceMove : cfg.AsianMnqReversalPriceMove);
        }

        private static double Asian75LegLoss(Asian75Position p, KeystoneArcRunConfig cfg)
        {
            if (AsianUsesPriceRisk(cfg)) return AsianPriceLossMove(p.Symbol, cfg) * CashValuePerPriceMove(p.Symbol, cfg) * Math.Max(1, p.Quantity);
            return Math.Abs(cfg.AsianReversalLossDollars);
        }

        private static string AsianRiskDescription(Asian75Position p, KeystoneArcRunConfig cfg)
        {
            return AsianUsesPriceRisk(cfg)
                ? AsianPriceLossMove(p.Symbol, cfg).ToString("0.####", CultureInfo.InvariantCulture) + " PRICE MOVE • " + Asian75LegLoss(p, cfg).ToString("C0") + " AT x" + p.Quantity
                : Asian75LegLoss(p, cfg).ToString("C0") + " FIXED CASH";
        }

        private static int AsianMaxReversalsForSymbol(string symbol, KeystoneArcRunConfig cfg)
        {
            int specific = IsMgc(symbol) ? cfg.AsianMgcMaxReversals : cfg.AsianMnqMaxReversals;
            return Math.Max(0, specific);
        }

        private static double AsianInstrumentCapForSymbol(string symbol, KeystoneArcRunConfig cfg)
        {
            double specific = IsMgc(symbol) ? cfg.AsianMgcInstrumentStopLossDollars : cfg.AsianMnqInstrumentStopLossDollars;
            return Math.Max(0, specific > 0 ? specific : cfg.AsianInstrumentStopLossDollars);
        }

        private static double Asian75StopPrice(Asian75Position p, KeystoneArcRunConfig cfg)
        {
            double distance = AsianUsesPriceRisk(cfg)
                ? AsianPriceLossMove(p.Symbol, cfg)
                : Asian75LegLoss(p, cfg) / Math.Max(0.0001, CashValuePerPriceMove(p.Symbol, cfg) * p.Quantity);
            return p.Direction > 0 ? p.EntryPrice - distance : p.EntryPrice + distance;
        }

        private static double Asian75OpenPnl(Asian75Position p, double mark)
        {
            return (mark - p.EntryPrice) * CashValuePerPriceMove(p.Symbol, null) * p.Quantity * p.Direction;
        }

        private static KeystoneArcEvent DetectBhBreak(List<KeystoneArcBar> bars, int i, KeystoneArcRunConfig cfg, string symbol)
        {
            KeystoneArcBar bearish = bars[i - 2], reference = bars[i - 1], trigger = bars[i];
            // Every formation candle must occur after the chosen session begins. Pre-session
            // candles remain visible only as chart context, never as a qualifying setup leg.
            if (bearish.Time < cfg.Start || reference.Time < cfg.Start || trigger.Time < cfg.Start || trigger.Time > cfg.End) return null;
            if (!InsideSession(bearish.Time, symbol, cfg) || !InsideSession(reference.Time, symbol, cfg) || !InsideSession(trigger.Time, symbol, cfg)) return null;
            bool longSide = DirectionAllows(symbol, "LONG", cfg);
            bool shortSide = DirectionAllows(symbol, "SHORT", cfg);
            bool longCandidate = longSide && bearish.Close < bearish.Open && reference.Close > reference.Open && trigger.High >= reference.High;
            bool shortCandidate = shortSide && bearish.Close > bearish.Open && reference.Close < reference.Open && trigger.Low <= reference.Low;
            if (!longCandidate && !shortCandidate) return null;
            bool shortSignal = shortCandidate && !longCandidate;
            if (string.Equals(cfg.BhAggressionFilter, "STRONGER", StringComparison.OrdinalIgnoreCase) && !PassesStrongerBhAggression(bars, i, symbol, cfg, shortSignal)) return null;
            return NewEvent(symbol, shortSignal ? "BL" : "BH", reference.Time, trigger.Time, shortSignal ? reference.Low : reference.High, cfg, bars, i, shortSignal ? "SHORT" : "LONG");
        }

        // ---- GOLDEN SETUP --------------------------------------------------------------------
        // MNQ from 09:30, MGC from 08:00 (settings): the FIRST bullish setup whose candles all form
        // after the start — BH (the unchanged BH rule) or a bullish FVG (entry at candle 3's close,
        // or touch + break like BH). Target / stop in points; stop below the pattern's low (or fixed).
        // The push down before it (points from the start price, red candles in a row) is measured for
        // every setup: TAG compares with / without, REQUIRED trades only setups that had it.
        // One trade a day by default; with more tries a loss allows the next setup, a win ends the day.
        // GOLDEN session day: a trading day runs 18:00 (previous evening) → 17:00, so a start after 18:00
        // belongs to the next day's session. The clock of HHMM inside that session day.
        internal static DateTime GoldenSessionDay(DateTime t) { return t.Hour >= 18 ? t.Date.AddDays(1) : t.Date; }
        internal static DateTime GoldenClock(DateTime sessionDay, int hhmm) { return (hhmm >= 1800 ? sessionDay.AddDays(-1) : sessionDay).AddHours(hhmm / 100).AddMinutes(hhmm % 100); }

        // Walk the 1-minute bars from the entry: for every stop level (study levels + the pattern stop), the best run up
        // before that stop was touched (stop first when a minute touches both, like the outcome rule).
        private static void GoldenExcursion(KeystoneArcEvent e, List<KeystoneArcBar> raw, KeystoneArcRunConfig cfg, string symbol, bool marketEntry)
        {
            if (e == null || raw == null || raw.Count == 0 || e.EntryTime == DateTime.MinValue || double.IsNaN(e.Entry)) return;
            int offset = IsMgc(symbol) ? cfg.MgcOutcomeTimeOffsetMinutes : cfg.MnqOutcomeTimeOffsetMinutes;
            int idx;
            if (marketEntry) { idx = FirstIndexAtOrAfter(raw, e.TriggerTime.AddMinutes(offset)); while (idx >= 0 && idx < raw.Count && raw[idx].Time <= e.TriggerTime.AddMinutes(offset)) idx++; }
            else idx = FirstIndexAtOrAfter(raw, e.EntryTime.AddMinutes(offset));
            if (idx < 0 || idx >= raw.Count) return;
            double[] levels = KeystoneGoldenStudy.StopLevels(symbol);
            int n = levels.Length + 1;
            var stops = new double[n]; Array.Copy(levels, stops, levels.Length); stops[n - 1] = Math.Max(0, e.Entry - e.Stop);
            double enough = Math.Max(KeystoneGoldenStudy.TargetLevels(symbol).Max(), e.Target - e.Entry);
            var run = new double[n]; var hit = new bool[n]; var done = new bool[n]; int left = n;
            for (int i = idx; i < raw.Count && left > 0; i++)
            {
                KeystoneArcBar b = raw[i];
                for (int k = 0; k < n; k++)
                {
                    if (done[k]) continue;
                    if (b.Low <= e.Entry - stops[k] + 1e-9) { hit[k] = true; done[k] = true; left--; continue; }
                    run[k] = Math.Max(run[k], b.High - e.Entry);
                    if (run[k] >= enough) { done[k] = true; left--; }
                }
            }
            e.GoldenRunBeforeStop = run; e.GoldenStopHit = hit;
        }

        // ---- MICRO A DAY ------------------------------------------------------------------------------
        // Every trading session: at the open (18:00 New York by default) buy or sell MadQty micros at the open of the first
        // 1-minute bar (it must start within 15 minutes of the open — holidays / missing data = no trade). No stop, no adding,
        // no management: out at the take profit (points, 0 = none) or at the close (16:59 the next day by default).
        // When one minute reaches the take profit the exit is the take-profit price; the deepest point against us is recorded.
        public static List<KeystoneArcEvent> DetectMicroADayPublic(List<KeystoneArcBar> raw, KeystoneArcRunConfig cfg, string symbol) { return DetectMicroADay(raw, cfg, symbol); }
        internal static List<KeystoneArcEvent> DetectMicroADay(List<KeystoneArcBar> raw, KeystoneArcRunConfig cfg, string symbol)
        {
            var output = new List<KeystoneArcEvent>(); if (raw == null || raw.Count == 0) return output;
            bool sell = string.Equals(cfg.MadDirection, "SELL", StringComparison.OrdinalIgnoreCase); double sign = sell ? -1 : 1;
            double tp = Math.Max(0, IsMgc(symbol) ? cfg.MadMgcTarget : cfg.MadMnqTarget); int qty = Math.Max(1, cfg.MadQty);
            double pv = CashValuePerPriceMove(symbol, cfg);
            int openM = cfg.MadOpenHhmm / 100 * 60 + cfg.MadOpenHhmm % 100, closeM = cfg.MadCloseHhmm / 100 * 60 + cfg.MadCloseHhmm % 100;
            bool overnight = closeM <= openM;
            var days = raw.Select(b => { var o = b.Time.Date.AddMinutes(openM); return b.Time > o ? o : (overnight ? o.AddDays(-1) : o); }).Distinct().OrderBy(d => d).ToList();
            int idx = 0;
            foreach (DateTime open in days)
            {
                DateTime close = open.Date.AddDays(overnight ? 1 : 0).AddMinutes(closeM);
                if (open < cfg.Start.AddMinutes(-1) || close > cfg.End.AddDays(1)) continue;
                while (idx < raw.Count && raw[idx].Time <= open) idx++;
                if (idx >= raw.Count) break;
                if (raw[idx].Time > open.AddMinutes(15) || raw[idx].Time > close) continue;      // no bar at the open (holiday / no data)
                var first = raw[idx]; double entry = first.Open;
                var e = new KeystoneArcEvent
                {
                    Id = "KA|" + symbol + "|MAD|" + (sell ? "SHORT" : "LONG") + "|" + open.Ticks.ToString(CultureInfo.InvariantCulture), Symbol = symbol, SetupClass = "MAD", Direction = sell ? "SHORT" : "LONG",
                    ReferenceTime = open, TriggerTime = open, EntryTime = open, Entry = entry, Quantity = qty, Stop = double.NaN, StopDistance = 0,
                    Target = tp > 0 ? entry + sign * tp : double.NaN, RiskModel = "MAD " + (sell ? "SELL" : "BUY") + " " + qty + " • " + (tp > 0 ? "+" + tp.ToString("0.##", CultureInfo.InvariantCulture) + " PTS OR THE CLOSE" : "HOLD TO THE CLOSE"),
                    PeakAfterEntry = first.High, TroughAfterEntry = first.Low, Outcome = "OPEN", StrengthTag = sell ? "SELL" : "BUY"
                };
                int j = idx; double exit = double.NaN; DateTime exitTime = DateTime.MinValue;
                for (; j < raw.Count && raw[j].Time <= close; j++)
                {
                    var b = raw[j]; e.PeakAfterEntry = Math.Max(e.PeakAfterEntry, b.High); e.TroughAfterEntry = Math.Min(e.TroughAfterEntry, b.Low);
                    if (tp > 0 && (sell ? b.Low <= e.Target : b.High >= e.Target)) { exit = e.Target; exitTime = b.Time; e.Outcome = "WIN"; e.TargetTouched = 1; break; }
                    exit = b.Close; exitTime = b.Time;
                }
                if (double.IsNaN(exit)) continue;
                if (e.Outcome != "WIN") e.Outcome = "SESSION EXIT";
                e.ExitPrice = exit; e.ExitTime = exitTime; e.GrossPnl = sign * (exit - entry) * pv * qty;
                double worst = sell ? e.PeakAfterEntry - entry : entry - e.TroughAfterEntry, best = sell ? entry - e.TroughAfterEntry : e.PeakAfterEntry - entry;
                e.ReviewNote = "MICRO A DAY • " + (sell ? "SELL " : "BUY ") + qty + " " + symbol + " at the " + KeystoneBracket.Hm(cfg.MadOpenHhmm) + " open " + entry.ToString(IsMgc(symbol) ? "0.0" : "0.00", CultureInfo.InvariantCulture)
                    + " • " + (e.Outcome == "WIN" ? "take profit +" + tp.ToString("0.##", CultureInfo.InvariantCulture) + " pts at " + exitTime.ToString("ddd HH:mm") : "closed at " + exitTime.ToString("ddd HH:mm") + " " + (sign * (exit - entry) >= 0 ? "+" : "") + (sign * (exit - entry)).ToString("0.##", CultureInfo.InvariantCulture) + " pts")
                    + " • worst against −" + worst.ToString("0.##", CultureInfo.InvariantCulture) + " pts (" + (worst * pv * qty).ToString("C0") + ") • best +" + best.ToString("0.##", CultureInfo.InvariantCulture) + " pts";
                e.ConfigurationKey = cfg.Snapshot();
                output.Add(e);
                idx = Math.Max(idx, j);
            }
            return output;
        }

        // MOVE STUDY: walk the 1-minute bars from the fill to the session close (same fill minute as the outcome rule).
        // Conservative: the adverse move of a minute counts before the favourable move of the same minute.
        internal static void GoldenMove(KeystoneArcEvent e, List<KeystoneArcBar> raw, KeystoneArcRunConfig cfg, string symbol, bool marketEntry, DateTime close)
        {
            if (e == null || raw == null || raw.Count == 0 || e.EntryTime == DateTime.MinValue || double.IsNaN(e.Entry)) return;
            int offset = IsMgc(symbol) ? cfg.MgcOutcomeTimeOffsetMinutes : cfg.MnqOutcomeTimeOffsetMinutes;
            int idx;
            if (marketEntry) { idx = FirstIndexAtOrAfter(raw, e.TriggerTime.AddMinutes(offset)); while (idx >= 0 && idx < raw.Count && raw[idx].Time <= e.TriggerTime.AddMinutes(offset)) idx++; }
            else idx = FirstIndexAtOrAfter(raw, e.EntryTime.AddMinutes(offset));
            if (idx < 0 || idx >= raw.Count || raw[idx].Time > close.AddMinutes(offset)) return;
            KeystoneMoveStudy.Walk(e, raw, idx, 1, close.AddMinutes(offset), symbol);
        }

        private static List<KeystoneArcEvent> DetectGolden(List<KeystoneArcBar> raw, List<KeystoneArcBar> bars, KeystoneArcRunConfig cfg, string symbol)
        {
            var output = new List<KeystoneArcEvent>();
            if (raw == null || bars == null || bars.Count < 3) return output;
            bool mgc = IsMgc(symbol);
            int startHhmm = mgc ? cfg.GoldenMgcStart : cfg.GoldenMnqStart;
            double target = Math.Max(0.01, mgc ? cfg.GoldenMgcTargetPoints : cfg.GoldenMnqTargetPoints);
            double dropNeeded = Math.Max(0, mgc ? cfg.GoldenMgcDropPoints : cfg.GoldenMnqDropPoints);
            double buffer = Math.Max(0, mgc ? cfg.GoldenMgcStopBuffer : cfg.GoldenMnqStopBuffer);
            double fixedStop = Math.Max(0.01, mgc ? cfg.GoldenMgcStopPoints : cfg.GoldenMnqStopPoints);
            double maxStop = Math.Max(0, mgc ? cfg.GoldenMgcMaxStop : cfg.GoldenMnqMaxStop);
            double minGap = Math.Max(0, mgc ? cfg.GoldenMgcMinGap : cfg.GoldenMnqMinGap);
            int qty = Math.Max(1, mgc ? cfg.GoldenMgcQuantity : cfg.GoldenMnqQuantity);
            string fvgMode = (cfg.GoldenFvgMode ?? "CLOSE").ToUpperInvariant();
            string aggression = (cfg.GoldenAggression ?? "TAG").ToUpperInvariant();
            // BH detection with its own rules, restricted to this instrument's window (long only).
            KeystoneArcRunConfig bhCfg = cfg.ShallowCopy();
            bhCfg.SessionMode = "CUSTOM"; bhCfg.CustomStart = startHhmm; bhCfg.EndTime = cfg.GoldenLastEntry; bhCfg.DirectionMode = "BB";
            string fmt = mgc ? "0.0" : "0.00";
            DateTime day = DateTime.MinValue, busyUntil = DateTime.MinValue;
            int taken = 0, startIndex = -1; bool dayDone = false; double startOpen = double.NaN;
            var zones = new List<BullishFvg>();
            var dipZones = new List<double[]>();   // DIP50: { gap low, gap high, candle-1 low, formed index, state 0 open / 1 used / 2 dead }
            for (int i = 2; i < bars.Count; i++)
            {
                KeystoneArcBar cur = bars[i];
                if (cur.Time < cfg.Start) continue;
                if (cur.Time > cfg.End) break;
                DateTime sessionDay = GoldenSessionDay(cur.Time);
                if (sessionDay != day) { day = sessionDay; taken = 0; dayDone = false; startIndex = -1; startOpen = double.NaN; zones.Clear(); dipZones.Clear(); busyUntil = DateTime.MinValue; }
                DateTime startClock = GoldenClock(day, startHhmm);
                DateTime lastEntry = GoldenClock(day, cfg.GoldenLastEntry);
                if (lastEntry <= startClock) lastEntry = lastEntry.AddDays(1);
                if (cur.Time <= startClock) continue;                        // candles that end by the start are pre-open
                if (startIndex < 0)
                {
                    // The first candle after the start (it may sit before the scan's first index).
                    int k = i; while (k - 1 >= 0 && bars[k - 1].Time > startClock && GoldenSessionDay(bars[k - 1].Time) == day) k--;
                    startIndex = k; startOpen = bars[k].Open;
                }
                bool patternAfterStart = i - 2 >= startIndex;                 // every pattern candle formed after the start
                // OPENING CANDLE GAP: candle 1 may be the last candle before the start when candle 2 (the displacement) is after it.
                bool fvgPatternOk = patternAfterStart || (cfg.GoldenFvgOpenCandle == 1 && i - 1 >= startIndex && i - 2 >= 0 && GoldenSessionDay(bars[i - 2].Time) == day);
                KeystoneArcEvent pick = null; string kind = null; double patternLow = double.NaN; bool marketEntry = false;
                bool takeAll = cfg.GoldenTakeAll == 1;
                if ((takeAll || (!dayDone && taken < Math.Max(1, cfg.GoldenMaxTradesPerDay) && cur.Time > busyUntil)) && cur.Time <= lastEntry && fvgPatternOk)
                {
                    KeystoneArcEvent bh = cfg.GoldenUseBh == 1 && patternAfterStart ? DetectBhBreak(bars, i, bhCfg, symbol) : null;
                    if (bh != null && string.Equals(bh.Direction, "LONG", StringComparison.OrdinalIgnoreCase)) { pick = bh; kind = "BH"; patternLow = Math.Min(bars[i - 2].Low, bars[i - 1].Low); }
                    KeystoneArcEvent fvg = null; double fvgLow = double.NaN; bool fvgMarket = false;
                    if (fvgMode == "CLOSE" && cur.Low > bars[i - 2].High && cur.Low - bars[i - 2].High >= minGap - 1e-9)
                    {
                        fvg = NewEvent(symbol, "FVG", cur.Time, cur.Time, cur.Close, bhCfg, bars, i);
                        fvg.FvgLower = bars[i - 2].High; fvg.FvgUpper = cur.Low; fvg.FvgFormedTime = cur.Time; fvg.FvgGap = cur.Low - bars[i - 2].High;
                        fvgLow = Math.Min(bars[i - 2].Low, Math.Min(bars[i - 1].Low, cur.Low)); fvgMarket = true;
                    }
                    else if (fvgMode == "DIP50")
                    {
                        // 50% TAP: a gap formed on an earlier candle; this candle trades down to its middle → limit fill at the middle
                        // (or at the minute's open when it opened below), stop below the low of the gap's first candle.
                        foreach (var z in dipZones.Where(z => z[4] == 0 && z[3] < i).OrderByDescending(z => z[3]))
                        {
                            double mid = (z[0] + z[1]) / 2.0; if (cur.Low > mid + 1e-9) continue;
                            int lo = 0, hi = raw.Count - 1, from = raw.Count; while (lo <= hi) { int mid2 = (lo + hi) / 2; if (raw[mid2].Time > bars[i - 1].Time) { from = mid2; hi = mid2 - 1; } else lo = mid2 + 1; }
                            int fillAt = -1; for (int q = from; q < raw.Count && raw[q].Time <= cur.Time; q++) if (raw[q].Low <= mid + 1e-9) { fillAt = q; break; }
                            if (fillAt < 0) continue;
                            double px = Math.Min(mid, raw[fillAt].Open);
                            fvg = NewEvent(symbol, "FVG", raw[fillAt].Time, raw[fillAt].Time, px, bhCfg, bars, i);
                            int f = (int)z[3]; fvg.FvgLower = z[0]; fvg.FvgUpper = z[1]; fvg.FvgFormedTime = bars[f].Time; fvg.FvgGap = z[1] - z[0];
                            fvgLow = z[2]; fvgMarket = false; z[4] = 1;
                            break;
                        }
                    }
                    else if (fvgMode == "BREAK")
                    {
                        fvg = ResolveFvgBreak(cur, zones, bhCfg, symbol, bars, i);
                        if (fvg != null && fvg.FvgUpper - fvg.FvgLower < minGap - 1e-9) fvg = null;
                        if (fvg != null) fvg.FvgGap = fvg.FvgUpper - fvg.FvgLower;
                        if (fvg != null) { int f = bars.FindIndex(b => b.Time == fvg.FvgFormedTime); fvgLow = f >= 2 ? Math.Min(bars[f - 2].Low, Math.Min(bars[f - 1].Low, bars[f].Low)) : fvg.FvgLower; for (int q = Math.Max(0, f); q < i; q++) fvgLow = Math.Min(fvgLow, bars[q].Low); }
                    }
                    if (fvg != null && pick != null) { kind = "DT"; patternLow = Math.Min(patternLow, fvgLow); pick.FvgGap = fvg.FvgGap; }   // both on the same candle: BH fills first (inside the candle)
                    else if (fvg != null) { pick = fvg; kind = "FVG"; patternLow = fvgLow; marketEntry = fvgMarket; }
                }
                if (pick != null)
                {
                    // Push down before the setup: start price → lowest low before the trigger candle; red candles in a row before it.
                    double low = double.MaxValue; for (int q = startIndex; q < i; q++) low = Math.Min(low, bars[q].Low);
                    double drop = double.IsNaN(startOpen) || low == double.MaxValue ? 0 : Math.Max(0, startOpen - low);
                    int red = 0; for (int q = i - 2; q >= startIndex && bars[q].Close < bars[q].Open; q--) red++;   // red candles in a row after the start, ending at the pattern's first candle
                    bool aggressive = drop >= dropNeeded && dropNeeded > 0 || (dropNeeded <= 0 && red >= 2);
                    double entry = pick.Entry;
                    double stop = string.Equals(cfg.GoldenStopMode, "FIXED", StringComparison.OrdinalIgnoreCase) ? entry - fixedStop : patternLow - buffer;
                    double stopPts = entry - stop;
                    bool skip = (aggression == "REQUIRED" && !aggressive) || stopPts <= 0 || (maxStop > 0 && stopPts > maxStop) || (cfg.GoldenSkipStopOverTarget == 1 && stopPts > target + 1e-9);
                    // Strictly the first setup: a setup a filter skips still uses up the day.
                    if (skip && cfg.GoldenStrictFirst == 1 && !takeAll) dayDone = true;
                    if (!skip)
                    {
                        pick.SetupClass = kind; pick.Quantity = qty; pick.Stop = stop; pick.Target = entry + target; pick.StopDistance = stopPts;
                        pick.RiskModel = "GLD " + kind + (kind == "FVG" && fvgMode == "DIP50" ? " • 50% TAP" : "") + " • +" + target.ToString("0.##", CultureInfo.InvariantCulture) + " PTS";
                        pick.StrengthTag = aggressive ? "AGGR" : "BASE";
                        pick.FvgDrop = drop; pick.FvgRedRun = red;
                        int lowIndex = startIndex; for (int q = startIndex; q < i; q++) if (bars[q].Low < bars[lowIndex].Low) lowIndex = q;
                        pick.GoldenStartTime = startClock; pick.GoldenStartPrice = startOpen; pick.GoldenLowTime = bars[lowIndex].Time; pick.GoldenLowPrice = bars[lowIndex].Low;
                        pick.GoldenPatternTime = kind == "FVG" && pick.FvgFormedTime != DateTime.MinValue ? pick.FvgFormedTime.AddMinutes(-2 * Math.Max(1, cfg.SetupMinutes)) : bars[i - 2].Time;
                        pick.SessionOrder = taken + 1;
                        pick.ConfigurationKey = cfg.Snapshot();
                        KeystoneArcRunConfig outCfg = cfg.ShallowCopy(); outCfg.EndTime = cfg.GoldenClose;
                        // HOLD: no session close — the trade runs until the target or the stop, overnight and into the next days.
                        ResolveOutcome(pick, raw, outCfg, symbol, marketEntry, cfg.GoldenHold == 1 ? raw[raw.Count - 1].Time : default(DateTime));
                        GoldenExcursion(pick, raw, cfg, symbol, marketEntry);
                        DateTime moveClose = GoldenClock(day, cfg.GoldenClose); if (moveClose <= pick.EntryTime) moveClose = moveClose.AddDays(1);
                        GoldenMove(pick, raw, cfg, symbol, marketEntry, moveClose);
                        pick.ReviewNote = "GOLDEN • " + (takeAll ? "#" + (taken + 1) : taken == 0 ? "first" : (taken + 1) == 2 ? "2nd" : "3rd") + " setup after " + (startHhmm / 100).ToString("00") + ":" + (startHhmm % 100).ToString("00") + " • " + (kind == "DT" ? "BH + FVG" : kind)
                            + " • push down " + drop.ToString(fmt, CultureInfo.InvariantCulture) + " pts" + (red > 0 ? " (" + red + " red)" : string.Empty) + (aggressive ? " = AGGRESSION" : " = no aggression")
                            + " • entry " + entry.ToString(fmt, CultureInfo.InvariantCulture) + " • target " + pick.Target.ToString(fmt, CultureInfo.InvariantCulture) + " (+" + target.ToString("0.##", CultureInfo.InvariantCulture) + ")"
                            + " • stop " + stop.ToString(fmt, CultureInfo.InvariantCulture) + " (−" + stopPts.ToString(fmt, CultureInfo.InvariantCulture) + ")";
                        output.Add(pick);
                        taken++;
                        if (pick.Outcome == "WIN" || pick.Outcome == "SESSION EXIT" || pick.ExitTime == DateTime.MinValue) dayDone = true;
                        if (cfg.GoldenHold == 1 && pick.ExitTime != DateTime.MinValue && GoldenSessionDay(pick.ExitTime) != day) dayDone = true;   // still open when the session ended
                        busyUntil = pick.ExitTime == DateTime.MinValue ? DateTime.MaxValue : pick.ExitTime;
                    }
                }
                if (fvgMode == "BREAK") { UpdateFvgTouchState(cur, zones, bhCfg); if (fvgPatternOk) DetectNewBullishFvg(bars, i, zones); }
                if (fvgMode == "DIP50")
                {
                    foreach (var z in dipZones) if (z[4] == 0 && cur.Close < z[0] && z[3] < i) z[4] = 2;     // closed below the gap before a tap: dead
                    if (fvgPatternOk && cur.Low > bars[i - 2].High && cur.Low - bars[i - 2].High >= minGap - 1e-9) dipZones.Add(new[] { bars[i - 2].High, cur.Low, bars[i - 2].Low, i, 0.0 });
                }
            }
            return output;
        }

        // ---- FVG retest long -------------------------------------------------------------
        // Box = candle 1 high → candle 3 low when candle 3 low > candle 1 high (any colours).
        // A later candle dips into the box (depth parameter) without closing below it; the first
        // green close after the dip is the reference; the next candle breaking that high is the
        // entry at that high (same entry mechanic as BH). A close below the box kills it; price
        // running far above retires it; each box gives up to FvgMaxEntriesPerBox entries.
        private sealed class FvgWork
        {
            public KeystoneArcFvgZone Zone; public int FormedIndex;
            public int State;            // 0 waiting for a dip, 1 dipped (waiting green close), 2 armed (reference set)
            public double RetestLow = double.MaxValue;
            public int LastFormedIndex;
            public double LastShallowLog = double.NaN;
            public double RefHigh, RefLow; public DateTime RefTime; public int RefIndex;
            public bool Dead;
        }

        public sealed class FvgScanEntry { public KeystoneArcFvgZone Zone; public int ReferenceIndex, TriggerIndex; public double Entry, GreenLow, RetestLow; public int Visit; }

        public static List<KeystoneArcFvgZone> FvgScan(List<KeystoneArcBar> bars, KeystoneArcRunConfig cfg, string symbol, List<FvgScanEntry> entries)
        {
            var zones = new List<KeystoneArcFvgZone>();
            if (bars == null || cfg == null) return zones;
            bool mgc = IsMgc(symbol);
            double minGap = Math.Max(0, mgc ? cfg.FvgMgcMinGap : cfg.FvgMnqMinGap);
            double depth = Math.Max(0, Math.Min(100, cfg.FvgMinDepthPercent)) / 100.0;
            string aggression = (cfg.FvgAggressionMode ?? "TAG").ToUpperInvariant();
            var live = new List<FvgWork>();
            string fmt = mgc ? "0.0" : "0.00";
            Func<double, string> px = v => v.ToString(fmt, CultureInfo.InvariantCulture);
            for (int i = 0; i < bars.Count; i++)
            {
                KeystoneArcBar bar = bars[i];
                bool inWindow = bar.Time >= cfg.Start && bar.Time <= cfg.End && InsideSession(bar.Time, symbol, cfg);
                DateTime session = SessionGroupingDate(bar.Time, cfg);
                foreach (FvgWork w in live)
                {
                    if (w.Dead || w.FormedIndex >= i) continue;
                    KeystoneArcFvgZone z = w.Zone;
                    if (cfg.FvgSameSessionOnly > 0 && SessionGroupingDate(z.FormedTime, cfg) != session) { Retire(w, bars[i - 1].Time, "SESSION END"); continue; }
                    if (cfg.FvgMaxBoxAgeBars > 0 && i - w.FormedIndex > cfg.FvgMaxBoxAgeBars) { Retire(w, bars[i - 1].Time, "AGE"); continue; }
                    double zoneDepth = z.Stacked > 1 ? Math.Max(depth, Math.Max(0, Math.Min(100, cfg.FvgMergedDepthPercent)) / 100.0) : depth;
                    // 1. Armed: this candle breaking the green candle's high is the entry.
                    if (w.State == 2)
                    {
                        if (bar.High >= w.RefHigh && inWindow && DirectionAllows(symbol, "LONG", cfg))
                        {
                            z.Entries++;
                            z.Note(bar.Time, "ENTRY: broke " + px(w.RefHigh) + " (try " + z.Entries + ")");
                            if (entries != null) entries.Add(new FvgScanEntry { Zone = z, ReferenceIndex = w.RefIndex, TriggerIndex = i, Entry = w.RefHigh, GreenLow = w.RefLow, RetestLow = w.RetestLow, Visit = z.Visits });
                            if (z.Entries >= Math.Max(1, cfg.FvgMaxEntriesPerBox)) { Retire(w, bar.Time, "USED"); continue; }
                            w.State = 0;
                        }
                        else
                        {
                            bool needDip = cfg.FvgNeedNewDipAfterMiss > 0;
                            z.Note(bar.Time, bar.High >= w.RefHigh ? "break outside the session window → no entry" : "next candle did not break " + px(w.RefHigh) + (needDip ? " → needs a new dip" : " → waits for the next green close"));
                            w.State = needDip ? 0 : 1;
                        }
                    }
                    // 2. A close below the box kills it.
                    if (bar.Close < z.Lower) { Retire(w, bar.Time, "CLOSED BELOW"); continue; }
                    // 3. "Moved away" = the whole candle (its low too) trades above the run-away distance.
                    if (cfg.FvgRunAwayMultiple > 0 && w.State != 2 && bar.Low > z.Upper + cfg.FvgRunAwayMultiple * Math.Max(z.Height, 1e-9)) { Retire(w, bar.Time, "RUN AWAY"); continue; }
                    // 4. Dip into the zone (deep enough) starts a retest.
                    double reach = z.Height <= 0 ? 0 : (z.Upper - bar.Low) / z.Height;
                    bool dipped = bar.Low <= z.Upper - zoneDepth * z.Height + 1e-9;
                    if (dipped && w.State == 0) { w.State = 1; z.Visits++; w.RetestLow = bar.Low; z.Note(bar.Time, "dip " + (reach * 100).ToString("0") + "% into the " + (z.Stacked > 1 ? "stacked zone" : "box") + " (visit " + z.Visits + ")"); }
                    else if (!dipped && w.State == 0 && bar.Low <= z.Upper && (double.IsNaN(w.LastShallowLog) || w.LastShallowLog != i - 1))
                        z.Note(bar.Time, "touch only " + (reach * 100).ToString("0") + "% (needs " + (zoneDepth * 100).ToString("0") + "%) → not a retest");
                    if (!dipped && w.State == 0 && bar.Low <= z.Upper) w.LastShallowLog = i;
                    if (w.State == 1) w.RetestLow = Math.Min(w.RetestLow, bar.Low);
                    // 5. First green close after the dip (the dip candle itself counts) arms the zone.
                    if (w.State == 1 && bar.Close > bar.Open) { w.State = 2; w.RefHigh = bar.High; w.RefLow = bar.Low; w.RefTime = bar.Time; w.RefIndex = i; z.Note(bar.Time, "green close → entry if the next candle breaks " + px(bar.High)); }
                }
                live.RemoveAll(w => w.Dead);
                // New box on this candle (candle 3 = this bar).
                if (i >= 2 && bar.Low > bars[i - 2].High && bar.Low - bars[i - 2].High >= minGap - 1e-9)
                {
                    bool formedInside = bar.Time >= cfg.Start && bar.Time <= cfg.End && InsideSession(bar.Time, symbol, cfg);
                    if (formedInside || (cfg.FvgZonesOutsideWindow > 0 && bar.Time <= cfg.End))
                    {
                        double lower = bars[i - 2].High, upper = bar.Low, formationLow = Math.Min(bars[i - 2].Low, Math.Min(bars[i - 1].Low, bar.Low));
                        // Stacked FVGs (formed in a row, zone not yet retested) become one zone.
                        FvgWork stack = cfg.FvgMergeStacked > 0 ? live.LastOrDefault(w => !w.Dead && w.State == 0 && w.Zone.Visits == 0 && i - w.LastFormedIndex <= 2) : null;
                        if (stack != null)
                        {
                            KeystoneArcFvgZone z = stack.Zone;
                            z.Lower = Math.Min(z.Lower, lower); z.Upper = Math.Max(z.Upper, upper); z.FormationLow = Math.Min(z.FormationLow, formationLow);
                            z.Stacked++; z.Parts.Add(new[] { lower, upper });
                            stack.LastFormedIndex = i; stack.FormedIndex = i;
                            z.Note(bar.Time, "stacked FVG " + px(lower) + "–" + px(upper) + " merged → zone " + px(z.Lower) + "–" + px(z.Upper) + " (" + z.Stacked + " boxes, dip must reach the middle)");
                            continue;
                        }
                        int red; double drop; FvgAggression(bars, i - 2, cfg.FvgAllowOneGreenInRun > 0, out red, out drop);
                        int needRed = Math.Max(0, mgc ? cfg.FvgMgcRedCandles : cfg.FvgMnqRedCandles);
                        double needDrop = Math.Max(0, mgc ? cfg.FvgMgcDropPoints : cfg.FvgMnqDropPoints);
                        bool useRed = needRed > 0, useDrop = needDrop > 0;
                        bool aggressive = (useRed || useDrop) && (string.Equals(cfg.FvgAggressionCombine, "ALL", StringComparison.OrdinalIgnoreCase)
                            ? (!useRed || red >= needRed) && (!useDrop || drop >= needDrop)
                            : (useRed && red >= needRed) || (useDrop && drop >= needDrop));
                        if (aggression != "REQUIRED" || aggressive)
                        {
                            var zone = new KeystoneArcFvgZone { Symbol = symbol, Lower = lower, Upper = upper, FormedTime = bar.Time, RedRun = red, Drop = drop, Aggressive = aggressive, FormationLow = formationLow };
                            zone.Parts.Add(new[] { lower, upper });
                            zone.Note(bar.Time, "FVG formed " + px(lower) + "–" + px(upper) + " (" + (upper - lower).ToString("0.##", CultureInfo.InvariantCulture) + " pts)" + (aggressive ? " after aggression: " + red + " red, drop " + drop.ToString("0.#", CultureInfo.InvariantCulture) : ""));
                            zones.Add(zone);
                            live.Add(new FvgWork { Zone = zone, FormedIndex = i, LastFormedIndex = i });
                        }
                    }
                }
            }
            foreach (FvgWork w in live.Where(x => !x.Dead)) w.Zone.Note(bars.Count == 0 ? DateTime.MinValue : bars[bars.Count - 1].Time, "still open at the end of the data");
            return zones;
        }

        private static void Retire(FvgWork w, DateTime when, string reason) { w.Dead = true; w.Zone.EndTime = when; w.Zone.EndReason = reason; w.Zone.Note(when, "ENDED: " + (reason == "CLOSED BELOW" ? "a candle closed below the zone" : (reason == "RUN AWAY" ? "a whole candle ran far above the zone" : (reason == "USED" ? "all tries used" : reason.ToLowerInvariant())))); }

        // Red candles in a row ending at (or just before) candle 1 of the box, and the price drop
        // from the top of that run to its lowest low. Optionally one small green candle (body
        // smaller than the red candle after it) does not break the run.
        private static void FvgAggression(List<KeystoneArcBar> bars, int candle1, bool allowOneGreen, out int red, out double drop)
        {
            red = 0; drop = 0;
            int last = candle1;
            if (last >= 0 && bars[last].Close >= bars[last].Open) last--;
            if (last < 0 || bars[last].Close >= bars[last].Open) return;
            bool greenUsed = false; int first = last;
            for (int k = last; k >= 0; k--)
            {
                KeystoneArcBar b = bars[k];
                if (b.Close < b.Open) { red++; first = k; continue; }
                if (allowOneGreen && !greenUsed && k + 1 <= last && k - 1 >= 0 && bars[k - 1].Close < bars[k - 1].Open && Math.Abs(b.Close - b.Open) < Math.Abs(bars[k + 1].Close - bars[k + 1].Open)) { greenUsed = true; continue; }
                break;
            }
            double top = double.MinValue, low = double.MaxValue;
            for (int k = first; k <= Math.Max(last, candle1); k++) { top = Math.Max(top, bars[k].High); low = Math.Min(low, bars[k].Low); }
            drop = top > low ? top - low : 0;
        }

        private static List<KeystoneArcEvent> DetectFvgRetest(List<KeystoneArcBar> raw, List<KeystoneArcBar> bars, KeystoneArcRunConfig cfg, string symbol)
        {
            var output = new List<KeystoneArcEvent>();
            var entries = new List<FvgScanEntry>();
            FvgScan(bars, cfg, symbol, entries);
            double pointValue = CashValuePerPriceMove(symbol, cfg);
            string stopMode = (cfg.FvgStopMode ?? "FIXED").ToUpperInvariant();
            int order = 0; DateTime orderDay = DateTime.MinValue;
            var learner = new KeystoneArcQualityLearner();
            Func<KeystoneArcEvent, double> pv = ev => CashValuePerPriceMove(ev.Symbol, cfg);
            foreach (FvgScanEntry x in entries.OrderBy(v => v.TriggerIndex))
            {
                KeystoneArcBar green = bars[x.ReferenceIndex], trigger = bars[x.TriggerIndex];
                KeystoneArcEvent e = NewEvent(symbol, "FVG", green.Time, trigger.Time, x.Entry, cfg, bars, x.TriggerIndex);
                // Entry-time features for grading (known before the outcome).
                double tr = 0; int trn = 0;
                for (int k = Math.Max(1, x.TriggerIndex - 14); k < x.TriggerIndex; k++) { tr += Math.Max(bars[k].High, bars[k - 1].Close) - Math.Min(bars[k].Low, bars[k - 1].Close); trn++; }
                e.FeatureAtr = trn == 0 ? Math.Max(1e-9, trigger.High - trigger.Low) : tr / trn;
                e.FeatureDipPercent = x.Zone.Height <= 0 || x.RetestLow == double.MaxValue ? 0 : Math.Max(0, Math.Min(150, (x.Zone.Upper - x.RetestLow) / x.Zone.Height * 100));
                e.FeatureGreenBody = green.High - green.Low <= 0 ? 0 : Math.Abs(green.Close - green.Open) / (green.High - green.Low);
                if (stopMode == "BOX" || stopMode == "GREEN_LOW" || stopMode == "FORMATION_LOW")
                {
                    double basePrice = stopMode == "BOX" ? x.Zone.Lower : (stopMode == "GREEN_LOW" ? x.GreenLow : x.Zone.FormationLow);
                    double stop = basePrice - Math.Max(0, cfg.FvgStopBufferPoints);
                    double distance = Math.Max(0.0001, x.Entry - stop);
                    double qty = Math.Max(1, Math.Min(Math.Max(1, cfg.FvgMaxQuantity), Math.Floor(cfg.StopDollars / (distance * pointValue))));
                    e.Stop = stop; e.StopDistance = distance; e.Quantity = qty;
                    e.Target = x.Entry + cfg.TargetDollars / Math.Max(0.0001, pointValue * qty);
                    e.RiskModel = "FVG " + (stopMode == "BOX" ? "BELOW BOX" : (stopMode == "GREEN_LOW" ? "BELOW GREEN CANDLE" : "BELOW FVG CANDLES LOW")) + " • AUTO SIZE " + qty + " • PRICE P/L";
                }
                e.FvgGap = x.Zone.Height; e.FvgVisit = x.Visit; e.StrengthTag = x.Zone.Aggressive ? "AGGR" : "BASE";
                learner.Grade(e, trigger.Time, pv);
                // DOUBLE TROUBLE: aggression before the box, and the FVG entry is also a BH entry
                // (red candle → green reference → next candle breaks the reference high).
                bool doubleTrouble = x.Zone.Aggressive && x.ReferenceIndex >= 1 && bars[x.ReferenceIndex - 1].Close < bars[x.ReferenceIndex - 1].Open && green.Close > green.Open;
                if (doubleTrouble) e.QualityTier = "DT";
                if (stopMode == "POINTS")
                {
                    // Fixed contracts, stop / target in points by grade (N uses B).
                    string g = e.QualityTier;
                    double sp = g == "DT" ? cfg.FvgStopPointsDT : (g == "A" ? cfg.FvgStopPointsA : (g == "C" ? cfg.FvgStopPointsC : cfg.FvgStopPointsB));
                    double tp = g == "DT" ? cfg.FvgTargetPointsDT : (g == "A" ? cfg.FvgTargetPointsA : (g == "C" ? cfg.FvgTargetPointsC : cfg.FvgTargetPointsB));
                    sp = Math.Max(0.01, sp); tp = Math.Max(0.01, tp);
                    e.Quantity = Math.Max(1, cfg.Quantity); e.Stop = x.Entry - sp; e.StopDistance = sp; e.Target = x.Entry + tp;
                    e.RiskModel = "FVG POINTS BY GRADE " + g + " • STOP " + sp.ToString("0.##", CultureInfo.InvariantCulture) + " / TARGET " + tp.ToString("0.##", CultureInfo.InvariantCulture) + " PTS • " + e.Quantity.ToString("0", CultureInfo.InvariantCulture) + " CONTRACTS • PRICE P/L";
                }
                if ((stopMode == "BOX" || stopMode == "GREEN_LOW" || stopMode == "FORMATION_LOW") && string.Equals(cfg.FvgTargetMode, "R_BY_QUALITY", StringComparison.OrdinalIgnoreCase))
                {
                    // Dynamic reward: stronger setups aim further (A 3R, B 2R, C 1.5R by default; N = B).
                    double r = e.QualityTier == "DT" ? cfg.FvgTargetRDT : (e.QualityTier == "A" ? cfg.FvgTargetRA : (e.QualityTier == "C" ? cfg.FvgTargetRC : cfg.FvgTargetRB));
                    e.Target = x.Entry + Math.Max(0.1, r) * e.StopDistance;
                    e.RiskModel += " • TARGET " + r.ToString("0.#", CultureInfo.InvariantCulture) + "R (" + e.QualityTier + ")";
                }
                DateTime day = SessionGroupingDate(trigger.Time, cfg); if (day != orderDay) { orderDay = day; order = 0; }
                e.SessionOrder = ++order;
                e.FvgLower = x.Zone.Lower; e.FvgUpper = x.Zone.Upper; e.FvgFormedTime = x.Zone.FormedTime;
                e.FvgVisit = x.Visit; e.FvgRedRun = x.Zone.RedRun; e.FvgDrop = x.Zone.Drop; e.FvgGap = x.Zone.Height;
                e.StrengthTag = x.Zone.Aggressive ? "AGGR" : "BASE";
                e.ReviewNote = (e.QualityTier == "DT" ? "DOUBLE TROUBLE • " : "") + (x.Zone.Stacked > 1 ? "STACKED ZONE (" + x.Zone.Stacked + " FVGs) • " : "") + "FVG box " + x.Zone.Lower.ToString("0.##", CultureInfo.InvariantCulture) + "–" + x.Zone.Upper.ToString("0.##", CultureInfo.InvariantCulture) + " formed " + x.Zone.FormedTime.ToString("yyyy-MM-dd HH:mm") + " • visit " + x.Visit + " • red run " + x.Zone.RedRun + " • drop " + x.Zone.Drop.ToString("0.##", CultureInfo.InvariantCulture) + (x.Zone.Aggressive ? " • AGGRESSIVE" : "");
                e.ConfigurationKey = cfg.Snapshot();
                ResolveOutcome(e, raw, cfg, symbol);
                ResolveEvaluationStageOutcome(e, raw, cfg, symbol);
                learner.Learn(e);
                output.Add(e);
            }
            return output;
        }

        // 123 ENGULFING: run of same-colour candles, then an engulfing close in the other direction.
        private static List<KeystoneArcEvent> DetectEngulfing(List<KeystoneArcBar> raw, List<KeystoneArcBar> bars, KeystoneArcRunConfig cfg, string symbol)
        {
            var output = new List<KeystoneArcEvent>();
            if (bars == null || bars.Count < 3) return output;
            string dir = (cfg.EngDirection ?? "BOTH").ToUpperInvariant();
            string strength = (cfg.EngStrength ?? "ALL").ToUpperInvariant();
            string stopMode = (cfg.EngStopMode ?? "CANDLE").ToUpperInvariant();
            double pointValue = CashValuePerPriceMove(symbol, cfg);
            double minBody = Math.Max(0, IsMgc(symbol) ? cfg.EngMgcMinBody : cfg.EngMnqMinBody);
            int minRun = Math.Max(1, cfg.EngMinRun);
            var learner = new KeystoneArcQualityLearner();
            Func<KeystoneArcEvent, double> pv = ev => CashValuePerPriceMove(ev.Symbol, cfg);
            int order = 0; DateTime orderDay = DateTime.MinValue;
            string fmt = IsMgc(symbol) ? "0.0" : "0.00";
            for (int i = 2; i < bars.Count; i++)
            {
                KeystoneArcBar c = bars[i];
                if (c.Time < cfg.Start || c.Time > cfg.End || !InsideSession(c.Time, symbol, cfg)) continue;
                bool up = c.Close > c.Open, down = c.Close < c.Open;
                if (!up && !down) continue;
                bool isBuy = up;
                if ((isBuy && dir == "SELL") || (!isBuy && dir == "BUY")) continue;
                if (Math.Abs(c.Close - c.Open) < minBody) continue;
                // Run of opposite-colour candles right before the signal candle.
                int run = 0;
                for (int k = i - 1; k >= 0; k--) { bool red = bars[k].Close < bars[k].Open, green = bars[k].Close > bars[k].Open; if (isBuy ? red : green) run++; else break; }
                if (run < minRun || (cfg.EngMaxRun > 0 && run > cfg.EngMaxRun)) continue;
                KeystoneArcBar last = bars[i - 1], prev = bars[i - 2];
                // Body engulf: the close is beyond the last run candle's body (its open).
                if (isBuy ? c.Close <= last.Open : c.Close >= last.Open) continue;
                bool wick = isBuy ? c.Close > last.High : c.Close < last.Low;
                bool sweep = isBuy ? c.Low < Math.Min(last.Low, prev.Low) : c.High > Math.Max(last.High, prev.High);
                if (strength == "WICK" && !wick && !sweep) continue;
                if (strength == "SWEEP" && !sweep) continue;
                if (strength == "SWEEP_WICK" && !(sweep && wick)) continue;
                string direction = isBuy ? "LONG" : "SHORT";
                double sign = isBuy ? 1.0 : -1.0;
                double entry = c.Close;
                KeystoneArcEvent e = NewEvent(symbol, "ENG", c.Time, c.Time, entry, cfg, bars, i, direction);
                e.StrengthTag = sweep && wick ? "SWEEP+WICK" : (sweep ? "SWEEP" : (wick ? "WICK" : "BODY"));
                double tr = 0; int trn = 0;
                for (int k = Math.Max(1, i - 14); k < i; k++) { tr += Math.Max(bars[k].High, bars[k - 1].Close) - Math.Min(bars[k].Low, bars[k - 1].Close); trn++; }
                e.FeatureAtr = trn == 0 ? Math.Max(1e-9, c.High - c.Low) : tr / trn;
                e.FeatureGreenBody = c.High - c.Low <= 0 ? 0 : Math.Abs(c.Close - c.Open) / (c.High - c.Low);
                e.FeatureDipPercent = Math.Min(150, (c.High - c.Low) / Math.Max(1e-9, e.FeatureAtr) * 50);
                e.FvgRedRun = run;
                if (stopMode == "CANDLE") e.StopDistance = Math.Max(0.0001, Math.Abs(entry - (isBuy ? c.Low : c.High)));
                learner.Grade(e, c.Time, pv);
                if (sweep && wick && run >= Math.Max(1, cfg.EngDtRun)) e.QualityTier = "DT";
                string g = e.QualityTier;
                if (stopMode == "CANDLE")
                {
                    double stop = (isBuy ? c.Low : c.High) - sign * Math.Max(0, cfg.EngStopBufferPoints);
                    double distance = Math.Max(0.0001, Math.Abs(entry - stop));
                    double qty = Math.Max(1, Math.Min(Math.Max(1, cfg.EngMaxQuantity), Math.Floor(cfg.StopDollars / (distance * pointValue))));
                    e.Stop = stop; e.StopDistance = distance; e.Quantity = qty;
                    if (string.Equals(cfg.EngTargetMode, "FIXED_DOLLARS", StringComparison.OrdinalIgnoreCase))
                    { e.Target = entry + sign * cfg.TargetDollars / Math.Max(0.0001, pointValue * qty); e.RiskModel = "ENG BEYOND ENGULFING WICK • AUTO SIZE " + qty + " • FIXED $ TARGET • PRICE P/L"; }
                    else
                    {
                        double r = g == "DT" ? cfg.EngTargetRDT : (g == "A" ? cfg.EngTargetRA : (g == "C" ? cfg.EngTargetRC : cfg.EngTargetRB));
                        e.Target = entry + sign * Math.Max(0.1, r) * distance;
                        e.RiskModel = "ENG BEYOND ENGULFING WICK • AUTO SIZE " + qty + " • TARGET " + r.ToString("0.#", CultureInfo.InvariantCulture) + "R (" + g + ") • PRICE P/L";
                    }
                }
                else if (stopMode == "POINTS")
                {
                    double sp = g == "DT" ? cfg.EngStopPointsDT : (g == "A" ? cfg.EngStopPointsA : (g == "C" ? cfg.EngStopPointsC : cfg.EngStopPointsB));
                    double tp = g == "DT" ? cfg.EngTargetPointsDT : (g == "A" ? cfg.EngTargetPointsA : (g == "C" ? cfg.EngTargetPointsC : cfg.EngTargetPointsB));
                    sp = Math.Max(0.01, sp); tp = Math.Max(0.01, tp);
                    e.Quantity = Math.Max(1, cfg.Quantity); e.Stop = entry - sign * sp; e.StopDistance = sp; e.Target = entry + sign * tp;
                    e.RiskModel = "ENG POINTS BY GRADE " + g + " • STOP " + sp.ToString("0.##", CultureInfo.InvariantCulture) + " / TARGET " + tp.ToString("0.##", CultureInfo.InvariantCulture) + " PTS • " + e.Quantity.ToString("0", CultureInfo.InvariantCulture) + " CONTRACTS • PRICE P/L";
                }
                else
                {
                    // FIXED: Step 2 contract size, $ stop and $ target (no BH stop modes mixed in).
                    double qty = Math.Max(1, cfg.Quantity);
                    e.Quantity = qty; e.StopDistance = cfg.StopDollars / Math.Max(0.0001, pointValue * qty);
                    e.Stop = entry - sign * e.StopDistance; e.Target = entry + sign * cfg.TargetDollars / Math.Max(0.0001, pointValue * qty);
                    e.RiskModel = "PROP STANDARD • FIXED MICRO SIZE • ENGULFING";
                }
                DateTime day = SessionGroupingDate(c.Time, cfg); if (day != orderDay) { orderDay = day; order = 0; }
                e.SessionOrder = ++order;
                e.ReviewNote = (g == "DT" ? "DOUBLE TROUBLE • " : "") + (isBuy ? "BULLISH" : "BEARISH") + " ENGULFING after " + run + " " + (isBuy ? "red" : "green") + " candle" + (run == 1 ? "" : "s") + " • " + e.StrengthTag +
                    (wick ? " • closed beyond the last candle's wick" : " • closed beyond the last candle's body") + (sweep ? " • swept the " + (isBuy ? "lows" : "highs") + " of the last 2 candles" : "") + " • entry " + entry.ToString(fmt, CultureInfo.InvariantCulture) + " at the close";
                e.ConfigurationKey = cfg.Snapshot();
                ResolveOutcome(e, raw, cfg, symbol, true);
                ResolveEvaluationStageOutcome(e, raw, cfg, symbol, true);
                learner.Learn(e);
                output.Add(e);
            }
            return output;
        }

        private static DateTime AtHhmm(DateTime date, int hhmm) { return date.Date.AddHours(hhmm / 100).AddMinutes(hhmm % 100); }
        private static int LastIndexAtOrBefore(List<KeystoneArcBar> bars, DateTime t)
        {
            int lo = 0, hi = bars.Count - 1, found = -1;
            while (lo <= hi) { int mid = (lo + hi) / 2; if (bars[mid].Time <= t) { found = mid; lo = mid + 1; } else hi = mid - 1; }
            return found;
        }

        // LAST-HOUR RELAY (intraday momentum): one decision a day from 1-minute bars.
        private static List<KeystoneArcEvent> DetectLastHourRelay(List<KeystoneArcBar> raw, KeystoneArcRunConfig cfg, string symbol)
        {
            var output = new List<KeystoneArcEvent>();
            if (raw == null || raw.Count < 100) return output;
            double pv = CashValuePerPriceMove(symbol, cfg);
            string dir = (cfg.RelayDirection ?? "BOTH").ToUpperInvariant();
            // Day D = the NY day of the 10:00 signal; it starts at the 18:00 Globex open the evening before.
            var days = raw.Where(b => b.Time.DayOfWeek != DayOfWeek.Saturday && b.Time.DayOfWeek != DayOfWeek.Sunday && b.Time.Hour * 100 + b.Time.Minute >= 930 && b.Time.Hour < 17).Select(b => b.Time.Date).Distinct().OrderBy(d => d).ToList();
            var ranges = new Dictionary<DateTime, double>();
            foreach (DateTime d in days)
            {
                int a = LastIndexAtOrBefore(raw, AtHhmm(d.AddDays(-1), 1700)) + 1, z = LastIndexAtOrBefore(raw, AtHhmm(d, 1600));
                if (z >= a && a >= 0) { double hi = double.MinValue, lo = double.MaxValue; for (int i = a; i <= z; i++) { hi = Math.Max(hi, raw[i].High); lo = Math.Min(lo, raw[i].Low); } ranges[d] = hi - lo; }
            }
            var ctx = new KeystoneArcRunConfig(); ctx = cfg.ShallowCopy(); ctx.EndTime = cfg.RelayExitHhmm;
            for (int k = 0; k < days.Count; k++)
            {
                DateTime d = days[k];
                DateTime entryTime = AtHhmm(d, cfg.RelayEntryHhmm);
                if (entryTime < cfg.Start || entryTime > cfg.End) continue;
                var prior = days.Take(k).Where(x => ranges.ContainsKey(x)).Reverse().Take(Math.Max(1, cfg.RelayRangeDays)).Select(x => ranges[x]).ToList();
                if (prior.Count < 5) continue;
                double avgRange = prior.Average(); if (avgRange <= 0) continue;
                int anchorIdx = LastIndexAtOrBefore(raw, AtHhmm(d.AddDays(-1), 1700)) + 1;
                int signalIdx = LastIndexAtOrBefore(raw, AtHhmm(d, cfg.RelaySignalHhmm));
                int entryIdx = LastIndexAtOrBefore(raw, entryTime);
                if (anchorIdx < 0 || anchorIdx >= raw.Count || signalIdx < anchorIdx || entryIdx <= signalIdx) continue;
                if (raw[entryIdx].Time.Date != d || raw[entryIdx].Time < entryTime.AddMinutes(-5) || raw[signalIdx].Time.Date != d) continue;
                double anchor = raw[anchorIdx].Open, atSignal = raw[signalIdx].Close, entry = raw[entryIdx].Close;
                double signal = (atSignal - anchor) / avgRange;
                if (Math.Abs(signal) < cfg.RelayThreshold) continue;
                bool buy = signal > 0;
                if ((buy && dir == "SELL") || (!buy && dir == "BUY")) continue;
                if (cfg.RelayConfirm > 0 && Math.Sign(entry - atSignal) != Math.Sign(signal)) continue;
                double sign = buy ? 1 : -1, stopDist = Math.Max(0.25, cfg.RelayStopFraction * avgRange);
                KeystoneArcEvent e = NewEvent(symbol, "RLY", raw[signalIdx].Time, raw[entryIdx].Time, entry, cfg, null, -1, buy ? "LONG" : "SHORT");
                double qty = Math.Max(1, Math.Min(Math.Max(1, cfg.EngMaxQuantity), Math.Floor(cfg.StopDollars / (stopDist * pv))));
                e.Quantity = qty; e.Stop = entry - sign * stopDist; e.StopDistance = stopDist; e.Target = entry + sign * avgRange * 20; // time exit, no real target
                e.StrengthTag = Math.Abs(signal) >= 2 * cfg.RelayThreshold ? "STRONG" : "BASE";
                e.FeatureAtr = avgRange; e.FeatureDipPercent = Math.Min(150, Math.Abs(signal) * 100); e.FeatureGreenBody = Math.Abs(signal);
                e.RiskModel = "RLY TIME EXIT " + cfg.RelayExitHhmm.ToString("0000") + " • PROTECTIVE STOP " + stopDist.ToString("0.##", CultureInfo.InvariantCulture) + " PTS • AUTO SIZE " + qty + " • PRICE P/L";
                e.ReviewNote = "LAST-HOUR RELAY • open→" + cfg.RelaySignalHhmm.ToString("0000") + " move " + (atSignal - anchor).ToString("+0.##;-0.##", CultureInfo.InvariantCulture) + " pts = " + signal.ToString("+0.00;-0.00", CultureInfo.InvariantCulture) + " × the " + prior.Count + "-day average range (" + avgRange.ToString("0.##", CultureInfo.InvariantCulture) + ") → " + (buy ? "BUY" : "SELL") + " at " + cfg.RelayEntryHhmm.ToString("0000") + ", out at " + cfg.RelayExitHhmm.ToString("0000");
                e.SessionOrder = 1; e.ConfigurationKey = cfg.Snapshot();
                ResolveOutcome(e, raw, ctx, symbol, true);
                ResolveEvaluationStageOutcome(e, raw, ctx, symbol, true);
                output.Add(e);
            }
            return output;
        }

        // VWAP SNAP-BACK (midday mean reversion) on the selected setup timeframe.
        private static List<KeystoneArcEvent> DetectVwapSnapBack(List<KeystoneArcBar> raw, List<KeystoneArcBar> bars, KeystoneArcRunConfig cfg, string symbol)
        {
            var output = new List<KeystoneArcEvent>();
            if (bars == null || bars.Count < 10) return output;
            double pv = CashValuePerPriceMove(symbol, cfg);
            string dir = (cfg.VwapDirection ?? "BOTH").ToUpperInvariant();
            bool anyVolume = bars.Any(b => b.Volume > 0);
            var byDay = bars.Where(b => b.Time.Hour * 100 + b.Time.Minute > 930 && b.Time.Hour * 100 + b.Time.Minute <= 1600).GroupBy(b => b.Time.Date).OrderBy(g => g.Key).ToList();
            var firstHour = new Dictionary<DateTime, double>();
            foreach (var g in byDay) { var fh = g.Where(b => b.Time.Hour * 100 + b.Time.Minute <= 1030).ToList(); if (fh.Count > 0) firstHour[g.Key] = fh.Max(b => b.High) - fh.Min(b => b.Low); }
            for (int k = 0; k < byDay.Count; k++)
            {
                var day = byDay[k].ToList();
                if (day.Count < 5 || day[0].Time.Date.AddHours(16) < cfg.Start || day[0].Time > cfg.End) continue;
                var prior = byDay.Take(k).Where(g => firstHour.ContainsKey(g.Key)).Reverse().Take(Math.Max(1, cfg.VwapTrendDays)).Select(g => firstHour[g.Key]).ToList();
                double fhToday; if (!firstHour.TryGetValue(byDay[k].Key, out fhToday)) continue;
                if (cfg.VwapTrendFilter > 0 && prior.Count >= 5 && fhToday > cfg.VwapTrendFilter * prior.Average()) continue; // trend day: stay out
                double sumW = 0, sumPV = 0, sumP2V = 0; int trades = 0;
                for (int i = 0; i < day.Count; i++)
                {
                    KeystoneArcBar b = day[i];
                    double tp = (b.High + b.Low + b.Close) / 3.0, w = anyVolume ? Math.Max(1, b.Volume) : 1;
                    sumW += w; sumPV += tp * w; sumP2V += tp * tp * w;
                    double vwap = sumPV / sumW, sigma = Math.Sqrt(Math.Max(0, sumP2V / sumW - vwap * vwap));
                    if (i < 1 || sigma <= 0 || trades >= Math.Max(1, cfg.VwapMaxTradesPerDay)) continue;
                    int hhmm = b.Time.Hour * 100 + b.Time.Minute;
                    if (hhmm <= cfg.VwapStartHhmm || hhmm > cfg.VwapEndHhmm) continue;
                    if (b.Time < cfg.Start || b.Time > cfg.End) continue;
                    KeystoneArcBar s = day[i - 1];
                    double upper = vwap + cfg.VwapBandSigma * sigma, lower = vwap - cfg.VwapBandSigma * sigma;
                    // Up-stretch → sell when the next bar makes no new high and closes lower; mirror for down-stretch.
                    bool sell = s.Close > upper && b.High <= s.High && b.Close < s.Close && dir != "BUY";
                    bool buy = s.Close < lower && b.Low >= s.Low && b.Close > s.Close && dir != "SELL";
                    if (!sell && !buy) continue;
                    double sign = buy ? 1 : -1, entry = b.Close;
                    double extreme = buy ? Math.Min(s.Low, b.Low) : Math.Max(s.High, b.High);
                    double stop = extreme - sign * Math.Max(0, cfg.VwapStopBufferPoints), dist = Math.Max(0.0001, Math.Abs(entry - stop));
                    double target = string.Equals(cfg.VwapTarget, "VWAP", StringComparison.OrdinalIgnoreCase) ? vwap : vwap - sign * sigma;
                    if ((target - entry) * sign <= 0) continue; // already back inside the target band
                    KeystoneArcEvent e = NewEvent(symbol, "VWP", s.Time, b.Time, entry, cfg, bars, -1, buy ? "LONG" : "SHORT");
                    double qty = Math.Max(1, Math.Min(Math.Max(1, cfg.EngMaxQuantity), Math.Floor(cfg.StopDollars / (dist * pv))));
                    e.Quantity = qty; e.Stop = stop; e.StopDistance = dist; e.Target = target;
                    double stretch = Math.Abs(s.Close - vwap) / sigma;
                    e.StrengthTag = stretch >= cfg.VwapBandSigma + 0.5 ? "STRONG" : "BASE";
                    e.FeatureAtr = sigma; e.FeatureDipPercent = Math.Min(150, stretch * 30); e.FeatureGreenBody = b.High - b.Low <= 0 ? 0 : Math.Abs(b.Close - b.Open) / (b.High - b.Low);
                    e.RiskModel = "VWP STOP BEYOND THE STRETCH • TARGET " + (string.Equals(cfg.VwapTarget, "VWAP", StringComparison.OrdinalIgnoreCase) ? "VWAP" : "1σ BAND") + " • AUTO SIZE " + qty + " • PRICE P/L";
                    e.ReviewNote = "VWAP SNAP-BACK • stretch " + stretch.ToString("0.0", CultureInfo.InvariantCulture) + "σ " + (sell ? "above" : "below") + " VWAP " + vwap.ToString("0.00", CultureInfo.InvariantCulture) + " • next bar made no new " + (sell ? "high" : "low") + " and closed back → " + (sell ? "SELL" : "BUY") + " at the close • target " + target.ToString("0.00", CultureInfo.InvariantCulture);
                    e.SessionOrder = ++trades; e.ConfigurationKey = cfg.Snapshot();
                    ResolveOutcome(e, raw, cfg, symbol, true);
                    ResolveEvaluationStageOutcome(e, raw, cfg, symbol, true);
                    output.Add(e);
                }
            }
            return output;
        }

        private static bool DirectionAllows(string symbol, string direction, KeystoneArcRunConfig cfg)
        {
            string mode = (cfg == null ? "BB" : cfg.DirectionMode ?? "BB").ToUpperInvariant();
            if (mode.Length < 2) mode = "BB";
            bool mnq = !IsMgc(symbol);
            char selected = mnq ? mode[0] : mode.Length > 1 ? mode[1] : 'B';
            return string.Equals(direction, "SHORT", StringComparison.OrdinalIgnoreCase) ? selected == 'S' : selected == 'B';
        }

        private static bool PassesStrongerBhAggression(List<KeystoneArcBar> bars, int triggerIndex, string symbol, KeystoneArcRunConfig cfg, bool shortSignal)
        {
            // The stronger tag mirrors the selected side: red/down aggression precedes LONG;
            // green/up aggression precedes SHORT. A doji breaks either consecutive sequence.
            int lastImpulse = triggerIndex - 2;
            int firstImpulse = lastImpulse;
            while (firstImpulse > 0 && (shortSignal ? bars[firstImpulse - 1].Close > bars[firstImpulse - 1].Open : bars[firstImpulse - 1].Close < bars[firstImpulse - 1].Open)) firstImpulse--;
            int impulseCount = lastImpulse - firstImpulse + 1;
            double move = shortSignal ? bars[lastImpulse].Close - bars[firstImpulse].Open : bars[firstImpulse].Open - bars[lastImpulse].Close;
            bool mgc = IsMgc(symbol);
            int requiredRed = Math.Max(0, mgc ? cfg.MgcStrongRedCandles : cfg.MnqStrongRedCandles);
            double requiredDecline = Math.Max(0, mgc ? cfg.MgcStrongDeclineDollars : cfg.MnqStrongDeclinePoints);
            bool useRed = requiredRed > 0;
            bool useDecline = requiredDecline > 0;
            // Stronger mode cannot silently fall back to the base rule when every threshold is
            // disabled. Require at least one active filter before it can produce results.
            if (!useRed && !useDecline) return false;
            bool redPass = !useRed || impulseCount >= requiredRed;
            bool declinePass = !useDecline || move >= requiredDecline;
            return string.Equals(cfg.BhStrongCombine, "ALL", StringComparison.OrdinalIgnoreCase)
                ? redPass && declinePass
                : (useRed && redPass) || (useDecline && declinePass);
        }

        private static KeystoneArcEvent ResolveFvgBreak(KeystoneArcBar current, List<BullishFvg> zones, KeystoneArcRunConfig cfg, string symbol, List<KeystoneArcBar> setupBars, int triggerIndex)
        {
            KeystoneArcEvent result = null;
            foreach (BullishFvg zone in zones.Where(z => !z.Invalid && z.PendingReference != DateTime.MinValue).ToList())
            {
                if (current.Time <= zone.PendingReference) continue;
                // Optional FVG evidence obeys the same strict selected-session rule as BH:
                // its formation, bullish reference, and break must be inside the chosen range.
                if (zone.Formed < cfg.Start || zone.PendingReference < cfg.Start || current.Time < cfg.Start || current.Time > cfg.End) { zone.Invalid = true; continue; }
                // The FVG rule is an immediate next selected-timeframe-bar break after a bullish reference close.
                if (current.Time == zone.PendingReference.AddMinutes(cfg.SetupMinutes) && current.High >= zone.PendingHigh && result == null)
                {
                    result = NewEvent(symbol, "FVG", zone.PendingReference, current.Time, zone.PendingHigh, cfg, setupBars, triggerIndex);
                    result.FvgLower = zone.Lower;
                    result.FvgUpper = zone.Upper;
                    result.FvgFormedTime = zone.Formed;
                }
                zone.Invalid = true; // prevents repeated entries from one FVG touch/reference sequence
            }
            return result;
        }

        private static void UpdateFvgTouchState(KeystoneArcBar current, List<BullishFvg> zones, KeystoneArcRunConfig cfg)
        {
            foreach (BullishFvg zone in zones.Where(z => !z.Invalid && z.Formed < current.Time).ToList())
            {
                if (current.Close < zone.Lower) { zone.Invalid = true; continue; }
                if (zone.PendingReference != DateTime.MinValue) continue;
                bool touched = current.Low <= zone.Upper && current.High >= zone.Lower;
                if (!touched) continue;
                zone.Touched = true;
                if (current.Close > current.Open)
                {
                    zone.PendingReference = current.Time;
                    zone.PendingHigh = current.High;
                }
                else if (current.Close < current.Open)
                {
                    // Bearish touch requires the next completed 5m candle to close bullish.
                    zone.PendingReference = current.Time.AddMinutes(cfg.SetupMinutes);
                    zone.PendingHigh = double.NaN;
                }
            }

            foreach (BullishFvg zone in zones.Where(z => !z.Invalid && z.PendingReference != DateTime.MinValue && double.IsNaN(z.PendingHigh) && current.Time == z.PendingReference).ToList())
            {
                if (current.Close > current.Open) zone.PendingHigh = current.High;
                else zone.Invalid = true;
            }
        }

        private static void DetectNewBullishFvg(List<KeystoneArcBar> bars, int i, List<BullishFvg> zones)
        {
            if (i < 2) return;
            KeystoneArcBar first = bars[i - 2], third = bars[i];
            if (third.Low > first.High)
                zones.Add(new BullishFvg { Lower = first.High, Upper = third.Low, Formed = third.Time });
        }

        private static bool IsPersonalAccount(KeystoneArcRunConfig cfg)
        {
            // Keystone Arc is prop virtual-pool research only. This compatibility helper is kept
            // false so legacy snapshots cannot re-enable the removed personal-account model.
            return false;
        }

        private static double CashValuePerPriceMove(string symbol, KeystoneArcRunConfig cfg)
        {
            if (IsPersonalAccount(cfg)) return Math.Max(0.0001, IsMgc(symbol) ? cfg.MgcCashPerPointPerLot : cfg.MnqCashPerPointPerLot);
            return IsMgc(symbol) ? 10.0 : 2.0;
        }

        private static double EventPnlForMove(KeystoneArcEvent e, double priceMove, KeystoneArcRunConfig cfg)
        {
            return priceMove * CashValuePerPriceMove(e.Symbol, cfg) * Math.Max(0.0001, e.Quantity);
        }

        private static bool IsPersonalAutoRiskStop(KeystoneArcRunConfig cfg)
        {
            return IsPersonalAccount(cfg) && string.Equals(cfg.StopMode, "LIVE_LOW_AUTO_RISK", StringComparison.OrdinalIgnoreCase);
        }

        private static KeystoneArcEvent NewEvent(string symbol, string setup, DateTime reference, DateTime trigger, double entry, KeystoneArcRunConfig cfg, List<KeystoneArcBar> setupBars, int triggerIndex, string direction = "LONG")
        {
            bool personal = IsPersonalAccount(cfg);
            bool shortSide = string.Equals(direction, "SHORT", StringComparison.OrdinalIgnoreCase);
            double sign = shortSide ? -1.0 : 1.0;
            double pointValue = CashValuePerPriceMove(symbol, cfg);
            double qty = personal ? Math.Max(0.01, cfg.PersonalLotSize) : Math.Max(1, cfg.Quantity);
            double targetMove = personal ? Math.Max(0.0001, IsMgc(symbol) ? cfg.MgcTargetMove : cfg.MnqTargetMove) : cfg.TargetDollars / Math.Max(0.0001, pointValue * qty);
            double standardStopMove = personal ? Math.Max(0.0001, IsMgc(symbol) ? cfg.MgcStandardStopMove : cfg.MnqStandardStopMove) : cfg.StopDollars / Math.Max(0.0001, pointValue * qty);
            double stop = entry - sign * standardStopMove;
            string riskModel = personal ? "LIVE STANDARD • FIXED LOT" : "PROP STANDARD • FIXED MICRO SIZE";
            bool belowSetupLow = string.Equals(cfg.StopMode, "BELOW_SETUP_LOW", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(cfg.StopMode, "LIVE_LOW_FIXED", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(cfg.StopMode, "LIVE_LOW_AUTO_RISK", StringComparison.OrdinalIgnoreCase);
            if (belowSetupLow && setupBars != null && triggerIndex >= 2 && triggerIndex < setupBars.Count)
            {
                double extreme = shortSide
                    ? Math.Max(setupBars[triggerIndex - 2].High, Math.Max(setupBars[triggerIndex - 1].High, setupBars[triggerIndex].High))
                    : Math.Min(setupBars[triggerIndex - 2].Low, Math.Min(setupBars[triggerIndex - 1].Low, setupBars[triggerIndex].Low));
                double offset = IsMgc(symbol) ? Math.Max(0, cfg.MgcStopOffsetPoints) : Math.Max(0, cfg.MnqStopOffsetPoints);
                stop = extreme - sign * offset;
                double distance = Math.Max(0.0001, Math.Abs(entry - stop));
                if (IsPersonalAutoRiskStop(cfg))
                {
                    // Broker lot increments differ. Keep the calculation transparent at 0.01
                    // lots; the user can adjust the final rounded lot in the personal input.
                    qty = Math.Max(0.01, Math.Floor(Math.Max(0, cfg.PersonalMaxRiskDollars) / (distance * pointValue) * 100.0) / 100.0);
                    riskModel = shortSide ? "LIVE ABOVE 3-CANDLE HIGH • AUTO-RISK LOT" : "LIVE BELOW 3-CANDLE LOW • AUTO-RISK LOT";
                }
                else if (personal) riskModel = shortSide ? "LIVE ABOVE 3-CANDLE HIGH • FIXED LOT" : "LIVE BELOW 3-CANDLE LOW • FIXED LOT";
                else
                {
                    qty = Math.Max(1, Math.Floor(cfg.StopDollars / (distance * pointValue)));
                    riskModel = shortSide ? "PROP ABOVE 3-CANDLE HIGH • RISK-SIZED" : "PROP BELOW 3-CANDLE LOW • RISK-SIZED";
                }
            }
            return new KeystoneArcEvent
            {
                Id = "KA|" + symbol + "|" + setup + "|" + direction + "|" + trigger.Ticks.ToString(CultureInfo.InvariantCulture),
                Symbol = symbol,
                SetupClass = setup,
                Direction = shortSide ? "SHORT" : "LONG",
                ReferenceTime = reference,
                TriggerTime = trigger,
                EntryTime = trigger,
                Entry = entry,
                Target = entry + sign * targetMove,
                Stop = stop,
                Quantity = qty,
                StopDistance = Math.Abs(entry - stop),
                RiskModel = riskModel,
                Outcome = "OPEN"
            };
        }

        private static bool IsShort(KeystoneArcEvent e) { return e != null && string.Equals(e.Direction, "SHORT", StringComparison.OrdinalIgnoreCase); }
        private static double EventPnlAtExit(KeystoneArcEvent e, double exitPrice, double pointValue, double qty)
        {
            return (IsShort(e) ? e.Entry - exitPrice : exitPrice - e.Entry) * pointValue * qty;
        }
        private static bool UsesFixedDollarStop(KeystoneArcRunConfig cfg)
        {
            return !IsPersonalAccount(cfg) && string.Equals(cfg.StopMode, "STANDARD", StringComparison.OrdinalIgnoreCase);
        }

        private static void ResolveOutcome(KeystoneArcEvent e, List<KeystoneArcBar> raw, KeystoneArcRunConfig cfg, string symbol, bool marketEntry = false, DateTime endOverride = default(DateTime))
        {
            if (cfg.OutcomeModelEnabled == 0)
            {
                e.Outcome = "OUTCOME BLOCKED • SERIES MISMATCH";
                e.EntryTime = e.TriggerTime;
                e.ExitTime = e.TriggerTime;
                e.GrossPnl = 0;
                return;
            }
            int timeOffset = IsMgc(symbol) ? cfg.MgcOutcomeTimeOffsetMinutes : cfg.MnqOutcomeTimeOffsetMinutes;
            DateTime sessionEnd = new DateTime(e.TriggerTime.Year, e.TriggerTime.Month, e.TriggerTime.Day, cfg.EndTime / 100, cfg.EndTime % 100, 0);
            int triggerHhmm = e.TriggerTime.Hour * 100 + e.TriggerTime.Minute;
            if (cfg.EndTime < triggerHhmm) sessionEnd = sessionEnd.AddDays(1);
            if (sessionEnd > cfg.End) sessionEnd = cfg.End;
            if (endOverride != default(DateTime)) sessionEnd = endOverride.AddMinutes(-timeOffset);   // GOLDEN hold: until the data ends
            sessionEnd = sessionEnd.AddMinutes(timeOffset);
            double pointValue = CashValuePerPriceMove(symbol, cfg);
            // FVG box / green-low stops are risk-sized: their P/L is the real price move × size.
            bool priceBased = e.RiskModel != null && (e.RiskModel.StartsWith("GLD ", StringComparison.Ordinal) || e.RiskModel.StartsWith("FVG ", StringComparison.Ordinal) || e.RiskModel.StartsWith("ENG ", StringComparison.Ordinal) || e.RiskModel.StartsWith("RLY ", StringComparison.Ordinal) || e.RiskModel.StartsWith("VWP ", StringComparison.Ordinal));
            double qty = Math.Max(0.0001, e.Quantity > 0 ? e.Quantity : (IsPersonalAccount(cfg) ? cfg.PersonalLotSize : cfg.Quantity));
            int startIndex = FirstIndexAtOrAfter(raw, e.TriggerTime.AddMinutes(timeOffset));
            if (startIndex < 0) { e.Outcome = "NO ENTRY DATA"; e.GrossPnl = 0; return; }
            int entryIndex = -1;
            // Market entry at the close of the signal candle: the first 1-minute bar that starts
            // after that close is the entry bar (the signal candle's own minutes are never used).
            if (marketEntry)
            {
                while (startIndex < raw.Count && raw[startIndex].Time <= e.TriggerTime.AddMinutes(timeOffset)) startIndex++;
                if (startIndex < raw.Count && raw[startIndex].Time <= sessionEnd) entryIndex = startIndex;
            }
            for (int i = startIndex; !marketEntry && i < raw.Count; i++)
            {
                KeystoneArcBar candidate = raw[i];
                if (candidate.Time > sessionEnd) break;
                if (IsShort(e) ? candidate.Low <= e.Entry : candidate.High >= e.Entry) { entryIndex = i; break; }
            }
            if (entryIndex < 0) { e.Outcome = "NO ENTRY DATA"; e.GrossPnl = 0; return; }
            KeystoneArcBar entryBar = raw[entryIndex];
            // Market entry happens at the signal candle's close (its time); the next minute only fills it.
            e.EntryTime = marketEntry ? e.TriggerTime : entryBar.Time.AddMinutes(-timeOffset);
            e.PeakAfterEntry = entryBar.High;
            e.TroughAfterEntry = entryBar.Low;
            bool entryBarTarget = IsShort(e) ? entryBar.Low <= e.Target : entryBar.High >= e.Target;
            // A limit fill on a dip (GOLDEN 50% TAP): that minute's high may have printed before the fill — it cannot reach the target.
            if ((e.RiskModel ?? string.Empty).Contains("50% TAP")) entryBarTarget = false;
            bool entryBarStop = IsShort(e) ? entryBar.High >= e.Stop : entryBar.Low <= e.Stop;
            e.TargetTouched = entryBarTarget ? 1 : 0;
            e.StopTouched = entryBarStop ? 1 : 0;
            bool breakEvenActive = IsPersonalAccount(cfg) && cfg.BreakEvenEnabled > 0 && cfg.BreakEvenTriggerMove > 0;
            bool breakEvenArmed = false;
            if (entryBarStop)
            {
                e.Outcome = entryBarTarget ? "LOSS SAME-MINUTE STOP-FIRST" : "LOSS ENTRY-MINUTE AMBIGUOUS STOP-FIRST";
                e.GrossPnl = UsesFixedDollarStop(cfg) && !priceBased ? -Math.Abs(cfg.StopDollars) : EventPnlAtExit(e, e.Stop, pointValue, qty);
                e.ExitTime = entryBar.Time.AddMinutes(-timeOffset);
                e.ExitPrice = e.Stop;
                return;
            }
            if (entryBarTarget)
            {
                e.Outcome = "WIN";
                e.GrossPnl = IsPersonalAccount(cfg) || priceBased ? EventPnlAtExit(e, e.Target, pointValue, qty) : cfg.TargetDollars;
                e.ExitTime = entryBar.Time.AddMinutes(-timeOffset);
                e.ExitPrice = e.Target;
                return;
            }
            if (breakEvenActive && (IsShort(e) ? entryBar.Low <= e.Entry - cfg.BreakEvenTriggerMove : entryBar.High >= e.Entry + cfg.BreakEvenTriggerMove)) breakEvenArmed = true;
            KeystoneArcBar last = entryBar;
            for (int i = entryIndex + 1; i < raw.Count; i++)
            {
                KeystoneArcBar bar = raw[i];
                if (bar.Time > sessionEnd) break;
                last = bar;
                e.PeakAfterEntry = Math.Max(e.PeakAfterEntry, bar.High);
                e.TroughAfterEntry = Math.Min(e.TroughAfterEntry, bar.Low);
                bool hitTarget = IsShort(e) ? bar.Low <= e.Target : bar.High >= e.Target;
                bool hitStop = IsShort(e) ? bar.High >= e.Stop : bar.Low <= e.Stop;
                bool hitBreakEven = breakEvenArmed && (IsShort(e) ? bar.High >= e.Entry : bar.Low <= e.Entry);
                if (hitTarget) e.TargetTouched = 1;
                if (hitStop) e.StopTouched = 1;
                if (hitTarget && hitStop)
                {
                    e.Outcome = "LOSS SAME-MINUTE STOP-FIRST";
                    e.GrossPnl = UsesFixedDollarStop(cfg) && !priceBased ? -Math.Abs(cfg.StopDollars) : EventPnlAtExit(e, e.Stop, pointValue, qty);
                    e.ExitTime = bar.Time.AddMinutes(-timeOffset);
                    e.ExitPrice = e.Stop;
                    return;
                }
                if (hitStop)
                {
                    e.Outcome = "LOSS";
                    e.GrossPnl = UsesFixedDollarStop(cfg) && !priceBased ? -Math.Abs(cfg.StopDollars) : EventPnlAtExit(e, e.Stop, pointValue, qty);
                    e.ExitTime = bar.Time.AddMinutes(-timeOffset);
                    e.ExitPrice = e.Stop;
                    return;
                }
                if (hitTarget)
                {
                    e.Outcome = "WIN";
                    e.GrossPnl = IsPersonalAccount(cfg) || priceBased ? EventPnlAtExit(e, e.Target, pointValue, qty) : cfg.TargetDollars;
                    e.ExitTime = bar.Time.AddMinutes(-timeOffset);
                    e.ExitPrice = e.Target;
                    return;
                }
                // Once the requested movement is reached, subsequent bars may exit at the entry
                // price. Within a one-minute bar, an original stop still wins the tie first.
                if (hitBreakEven)
                {
                    e.Outcome = "BREAKEVEN";
                    e.GrossPnl = 0;
                    e.ExitTime = bar.Time.AddMinutes(-timeOffset);
                    e.ExitPrice = e.Entry;
                    return;
                }
                if (breakEvenActive && (IsShort(e) ? bar.Low <= e.Entry - cfg.BreakEvenTriggerMove : bar.High >= e.Entry + cfg.BreakEvenTriggerMove)) breakEvenArmed = true;
            }
            e.Outcome = "SESSION EXIT";
            e.ExitTime = last.Time.AddMinutes(-timeOffset);
            e.ExitPrice = last.Close;
            e.GrossPnl = EventPnlAtExit(e, last.Close, pointValue, qty);
        }

        // Evaluation-stage terms are pre-resolved from the same direct 1-minute path as the base
        // model. The pool later chooses them only while an assigned account has not passed; this
        // avoids changing funded outcomes or pretending a different data series was used.
        private static void ResolveEvaluationStageOutcome(KeystoneArcEvent source, List<KeystoneArcBar> raw, KeystoneArcRunConfig cfg, string symbol, bool marketEntry = false)
        {
            if (source == null || cfg == null || cfg.EvaluationStageTradeRulesEnabled <= 0 || cfg.EvaluationTradeTargetDollars <= 0 || cfg.EvaluationTradeStopDollars <= 0) return;
            double pointValue = CashValuePerPriceMove(symbol, cfg);
            double qty = Math.Max(0.0001, source.Quantity > 0 ? source.Quantity : cfg.Quantity);
            double sign = IsShort(source) ? -1.0 : 1.0;
            var stage = new KeystoneArcEvent
            {
                Id = source.Id + "|EVAL",
                Symbol = source.Symbol,
                SetupClass = source.SetupClass,
                Direction = source.Direction,
                ReferenceTime = source.ReferenceTime,
                TriggerTime = source.TriggerTime,
                EntryTime = source.EntryTime,
                Entry = source.Entry,
                Quantity = qty,
                Target = source.Entry + sign * cfg.EvaluationTradeTargetDollars / Math.Max(0.0001, pointValue * qty),
                Stop = source.Entry - sign * cfg.EvaluationTradeStopDollars / Math.Max(0.0001, pointValue * qty),
                RiskModel = "EVALUATION STAGE • FIXED CASH TERMS",
                Outcome = "OPEN"
            };
            var stageCfg = new KeystoneArcRunConfig
            {
                OutcomeModelEnabled = cfg.OutcomeModelEnabled,
                End = cfg.End,
                EndTime = cfg.EndTime,
                Quantity = Math.Max(1, (int)Math.Round(qty, MidpointRounding.AwayFromZero)),
                TargetDollars = cfg.EvaluationTradeTargetDollars,
                StopDollars = cfg.EvaluationTradeStopDollars,
                StopMode = "STANDARD",
                MnqOutcomeTimeOffsetMinutes = cfg.MnqOutcomeTimeOffsetMinutes,
                MgcOutcomeTimeOffsetMinutes = cfg.MgcOutcomeTimeOffsetMinutes
            };
            ResolveOutcome(stage, raw, stageCfg, symbol, marketEntry);
            source.EvaluationOutcome = stage.Outcome;
            source.EvaluationExitTime = stage.ExitTime;
            source.EvaluationExitPrice = stage.ExitPrice;
            source.EvaluationGrossPnl = stage.GrossPnl;
            source.EvaluationTarget = stage.Target;
            source.EvaluationStop = stage.Stop;
        }

        private static void ApplyEvaluationStageOutcomeForAccount(KeystoneArcEvent e, KeystoneArcVirtualAccount account, KeystoneArcRunConfig cfg)
        {
            if (e == null || account == null || cfg == null || !EvaluationPhase(account, cfg) || cfg.EvaluationStageTradeRulesEnabled <= 0 || string.IsNullOrWhiteSpace(e.EvaluationOutcome)) return;
            e.Outcome = e.EvaluationOutcome;
            e.ExitTime = e.EvaluationExitTime;
            e.ExitPrice = e.EvaluationExitPrice;
            e.GrossPnl = e.EvaluationGrossPnl;
            e.Target = e.EvaluationTarget;
            e.Stop = e.EvaluationStop;
            e.StopDistance = Math.Abs(e.Entry - e.Stop);
            e.RiskModel = "EVALUATION STAGE • " + cfg.EvaluationTradeTargetDollars.ToString("C0") + " TARGET / " + cfg.EvaluationTradeStopDollars.ToString("C0") + " STOP";
        }

        private static int FirstIndexAtOrAfter(List<KeystoneArcBar> raw, DateTime time)
        {
            if (raw == null || raw.Count == 0) return -1;
            int low = 0, high = raw.Count - 1, result = -1;
            while (low <= high)
            {
                int mid = low + (high - low) / 2;
                if (raw[mid].Time >= time) { result = mid; high = mid - 1; }
                else low = mid + 1;
            }
            return result;
        }

        private static bool UsesFirmFundedCap(KeystoneArcRunConfig cfg)
        {
            return cfg != null && cfg.EvaluationEnabled >= 0 && cfg.FirmFundedCapEnabled > 0 && cfg.EvaluationSlotsPerFirm > 0 && cfg.MaxFundedPerFirm > 0;
        }

        // A slot still running as the funded account bought at the start of a direct-funded study.
        private static bool DirectFundedPhase(KeystoneArcVirtualAccount a, KeystoneArcRunConfig cfg)
        {
            return a != null && cfg != null && cfg.EvaluationEnabled == 0 && a.DirectFundedStart;
        }

        // Evaluation rules apply: evaluation-first slots before passing, and replacement
        // evaluations bought after a direct-funded slot blew.
        private static bool EvaluationPhase(KeystoneArcVirtualAccount a, KeystoneArcRunConfig cfg)
        {
            return a != null && cfg != null && !a.Funded && (cfg.EvaluationEnabled > 0 || (cfg.EvaluationEnabled == 0 && !a.DirectFundedStart));
        }

        // A blown slot that will never trade again (no replacement pending).
        private static bool IsTerminalSlot(KeystoneArcVirtualAccount a)
        {
            return a != null && a.Blown && !a.ReplacementPending;
        }

        private static bool TierFiltersOff(KeystoneArcRunConfig cfg)
        {
            return cfg == null || (string.Equals(cfg.EvalTierFilter ?? "ALL", "ALL", StringComparison.OrdinalIgnoreCase) && string.Equals(cfg.FundedTierFilter ?? "ALL", "ALL", StringComparison.OrdinalIgnoreCase));
        }

        // Quality filter per account stage: e.g. evaluations trade every setup, funded accounts
        // only A / A+B setups. Off (ALL / ALL) keeps the original allocation exactly.
        private static bool StageAllows(KeystoneArcVirtualAccount a, KeystoneArcEvent e, KeystoneArcRunConfig cfg)
        {
            if (TierFiltersOff(cfg) || a == null || e == null) return true;
            bool funded = a.Funded || DirectFundedPhase(a, cfg);
            return KeystoneArcQualityLearner.TierAllowed(funded ? cfg.FundedTierFilter : cfg.EvalTierFilter, e.QualityTier);
        }

        private static bool ReplacesBlownAccounts(KeystoneArcRunConfig cfg)
        {
            return cfg != null && cfg.EvaluationEnabled >= 0 && cfg.BlownAccountReplacement > 0 && !string.Equals(cfg.AccountPath, "PERSONAL", StringComparison.OrdinalIgnoreCase);
        }

        private static KeystoneArcVirtualAccount CreatePoolAccount(KeystoneArcRunConfig cfg, int accountIndex, DateTime initialStart, string readyState)
        {
            bool grouped = UsesFirmFundedCap(cfg);
            // Direct-funded slots are funded from the start, so a firm holds at most its funded cap.
            int slotsPerFirm = Math.Max(1, cfg == null ? 10 : (cfg.EvaluationEnabled == 0 ? cfg.MaxFundedPerFirm : cfg.EvaluationSlotsPerFirm));
            int firmIndex = ((Math.Max(1, accountIndex) - 1) / slotsPerFirm) + 1;
            int firmSlot = ((Math.Max(1, accountIndex) - 1) % slotsPerFirm) + 1;
            string firm = grouped ? "P" + firmIndex.ToString(CultureInfo.InvariantCulture) : string.Empty;
            return new KeystoneArcVirtualAccount
            {
                // Keep the original neutral KA-V naming whenever the optional firm-cap scenario
                // is off, so existing reports/regressions retain their historical identifiers.
                Name = grouped ? firm + (cfg.EvaluationEnabled == 0 ? "-FUND" : "-EVAL") + firmSlot.ToString(CultureInfo.InvariantCulture) : "KA-V" + accountIndex.ToString("00", CultureInfo.InvariantCulture),
                PropFirmCode = firm,
                PropFirmSlot = grouped ? firmSlot : accountIndex,
                StartingBalance = cfg.PropStartingBalance,
                // Every prop account is bought: an evaluation, or a direct-funded account at the same price.
                EvaluationCost = cfg.EvaluationEnabled < 0 ? 0 : cfg.InitialAccountCost(),
                EvaluationPurchases = cfg.EvaluationEnabled >= 0 ? 1 : 0,
                DirectFundedStart = cfg.EvaluationEnabled == 0,
                InitialLifecycleStart = initialStart,
                CurrentLifecycleStart = initialStart,
                LastState = readyState
            };
        }

        private static int FundedSlotsInFirm(IEnumerable<KeystoneArcVirtualAccount> pool, string firm)
        {
            return (pool ?? Enumerable.Empty<KeystoneArcVirtualAccount>()).Count(a => a != null && a.Funded && string.Equals(a.PropFirmCode, firm ?? string.Empty, StringComparison.OrdinalIgnoreCase));
        }

        // Promotion/deferment happens after every completed session. If several evaluations pass
        // on the same date, earlier pass time/slot has priority and later passes wait. A funded
        // blowout frees a place at the next session close; no pending evaluation is discarded.
        private static void EnforceFirmFundedCapacity(IEnumerable<KeystoneArcVirtualAccount> pool, KeystoneArcRunConfig cfg)
        {
            if (!UsesFirmFundedCap(cfg)) return;
            List<KeystoneArcVirtualAccount> all = (pool ?? Enumerable.Empty<KeystoneArcVirtualAccount>()).Where(a => a != null).ToList();
            foreach (IGrouping<string, KeystoneArcVirtualAccount> group in all.Where(a => !string.IsNullOrEmpty(a.PropFirmCode)).GroupBy(a => a.PropFirmCode, StringComparer.OrdinalIgnoreCase))
            {
                int cap = Math.Max(1, cfg.MaxFundedPerFirm);
                List<KeystoneArcVirtualAccount> funded = group.Where(a => a.Funded).OrderBy(a => a.FundedSinceDate == DateTime.MinValue ? DateTime.MinValue : a.FundedSinceDate).ThenBy(a => a.PropFirmSlot).ToList();
                for (int index = cap; index < funded.Count; index++)
                {
                    KeystoneArcVirtualAccount wait = funded[index];
                    wait.Funded = false;
                    wait.EvaluationPassed = true;
                    wait.FundedCapPending = true;
                    wait.FundedBalance = 0;
                    wait.FundedPositiveDays = 0;
                    wait.LastState = "EVAL PASSED • FIRM FUNDED CAP WAIT (ILLUSTRATIVE)";
                }
                int available = Math.Max(0, cap - FundedSlotsInFirm(group, group.Key));
                foreach (KeystoneArcVirtualAccount wait in group.Where(a => a.FundedCapPending && !a.Blown && !a.ReplacementPending).OrderBy(a => a.FundedSinceDate == DateTime.MinValue ? a.ActiveDay : a.FundedSinceDate).ThenBy(a => a.PropFirmSlot).ToList())
                {
                    if (available <= 0) break;
                    wait.FundedCapPending = false;
                    wait.Funded = true;
                    wait.EvaluationPassed = true;
                    wait.FundedBalance = 0;
                    wait.FundedPositiveDays = 0;
                    wait.FundedSinceDate = wait.ActiveDay == DateTime.MinValue ? DateTime.MinValue : wait.ActiveDay;
                    wait.LastState = "FUNDED • FIRM CAP OPENED (ILLUSTRATIVE)";
                    available--;
                }
                foreach (KeystoneArcVirtualAccount account in group)
                {
                    KeystoneArcAccountDay last = account.DayHistory.Count == 0 ? null : account.DayHistory[account.DayHistory.Count - 1];
                    if (last == null) continue;
                    // A later capacity opening must not rewrite the historical daily close that
                    // recorded this evaluation as waiting at the firm cap. The current account
                    // state below still changes to funded; the audit keeps both facts visible.
                    bool historicalCapWait = last.FundedCapPendingAfter || (!string.IsNullOrEmpty(last.StateAfterClose) && last.StateAfterClose.IndexOf("FIRM FUNDED CAP WAIT", StringComparison.OrdinalIgnoreCase) >= 0);
                    if (historicalCapWait && !account.FundedCapPending) continue;
                    last.FundedAfter = account.Funded;
                    last.FundedCapPendingAfter = account.FundedCapPending;
                    last.PropFirmAfter = account.PropFirmCode;
                    last.FundedSlotsInFirmAfter = FundedSlotsInFirm(group, group.Key);
                    if (account.FundedCapPending) last.StateAfterClose = account.LastState;
                }
            }
        }

        public static List<KeystoneArcVirtualAccount> SimulatePool(List<KeystoneArcEvent> events, KeystoneArcRunConfig cfg)
        {
            return SimulatePool(events, cfg, null);
        }

        // evaluationStageEvents: Asian only, the cycle ledger produced with the evaluation-stage
        // settings (null = accounts use the same ledger in every stage).
        // PROP RULE • NO HEDGING: while any account holds a position on an instrument, no account may
        // open the opposite direction on that same instrument (MNQ long + MGC short is fine).
        // Returns the blocking open position, or null. Positions closed by now are dropped.
        private static KeystoneArcEvent OppositeOpenPosition(List<KeystoneArcEvent> open, KeystoneArcEvent e, DateTime when)
        {
            open.RemoveAll(o => (o.ExitTime == DateTime.MinValue ? (o.EntryTime == DateTime.MinValue ? o.TriggerTime : o.EntryTime) : o.ExitTime) <= when);
            return open.FirstOrDefault(o => string.Equals(o.Symbol, e.Symbol, StringComparison.OrdinalIgnoreCase) && IsShort(o) != IsShort(e));
        }
        private static string NoHedgeReason(KeystoneArcEvent block) { return "NO HEDGING • " + block.Symbol + " " + (IsShort(block) ? "SHORT" : "LONG") + " STILL OPEN (" + block.AssignedVirtualAccount + ") • opposite direction not allowed"; }

        public static List<KeystoneArcVirtualAccount> SimulatePool(List<KeystoneArcEvent> events, KeystoneArcRunConfig cfg, List<KeystoneArcEvent> evaluationStageEvents)
        {
            if (cfg != null && string.Equals(cfg.StrategyCode, "ASIAN75", StringComparison.OrdinalIgnoreCase))
                return SimulateAsian75CopyPool(events, cfg, evaluationStageEvents);
            if (cfg != null && (cfg.CopyTradingPool > 0 || cfg.CopyGroupSize > 1))
                return SimulateBhCopyPool(events, cfg);
            List<KeystoneArcVirtualAccount> accounts = new List<KeystoneArcVirtualAccount>();
            // Prop-only lab: every eligible event is evaluated through the virtual-pool allocator.
            bool personalPath = false;
            int poolCount = Math.Max(1, cfg.PoolSize);
            // Pool accounts are modeled as purchased at the beginning of the selected research
            // range—not at the first setup. This makes "days to first return" answer the user's
            // actual question: how long from starting the test/evaluation until cash was received.
            DateTime configuredInitialSlotStart = cfg.Start == DateTime.MinValue ? DateTime.MinValue : SessionGroupingDate(cfg.Start, cfg).Date;
            int accountIndex;
            for (accountIndex = 1; accountIndex <= poolCount; accountIndex++)
            {
                var account = CreatePoolAccount(cfg, accountIndex, configuredInitialSlotStart, "EVALUATION READY");
                if (cfg.EvaluationEnabled == -2)
                {
                    account.LastState = "SINGLE ACCOUNT • RANGE P/L ONLY";
                }
                else if (cfg.EvaluationEnabled < 0)
                {
                    account.LastState = "ONE-DAY ASSIGNMENT";
                }
                else if (cfg.EvaluationEnabled == 0)
                {
                    account.Funded = true;
                    account.EvaluationPassed = true;
                    account.FundedSinceDate = configuredInitialSlotStart;
                    account.LastState = "FUNDED READY (ILLUSTRATIVE)";
                }
                accounts.Add(account);
            }

            List<KeystoneArcEvent> orderedEvents = new List<KeystoneArcEvent>(events);
            orderedEvents.Sort(CompareEventsByEntryTime);

            int eventIndex;
            int nextAccountCursor = 0;
            var openPositions = new List<KeystoneArcEvent>();
            for (eventIndex = 0; eventIndex < orderedEvents.Count; eventIndex++)
            {
                KeystoneArcEvent e = orderedEvents[eventIndex];
                DateTime when = e.EntryTime == DateTime.MinValue ? e.TriggerTime : e.EntryTime;
                int stateIndex;
                for (stateIndex = 0; stateIndex < accounts.Count; stateIndex++)
                {
                    if (accounts[stateIndex].InitialLifecycleStart == DateTime.MinValue)
                    {
                        accounts[stateIndex].InitialLifecycleStart = when.Date;
                        accounts[stateIndex].CurrentLifecycleStart = when.Date;
                    }
                    // A direct-funded terminal blowout is no longer an active lifecycle.  Do
                    // not manufacture daily zero-P/L snapshots through the rest of the range;
                    // this keeps its visible activity dates and report duration ending at blowout.
                    if (IsTerminalSlot(accounts[stateIndex])) continue;
                    RollDay(accounts[stateIndex], when.Date, cfg, accounts);
                }

                // Each account has now closed the prior session. Re-open available firm capacity
                // before allocating the first event of this new session.
                EnforceFirmFundedCapacity(accounts, cfg);

                KeystoneArcEvent hedgeBlock = OppositeOpenPosition(openPositions, e, when);
                if (hedgeBlock != null) { e.SkipReason = NoHedgeReason(hedgeBlock); continue; }
                KeystoneArcVirtualAccount selected = null;
                int selectedIndex = -1;
                // Round-robin starts after the most recently assigned account. This deliberately spreads
                // sequential opportunities through the pool instead of repeatedly reusing A1 when it is free.
                for (stateIndex = 0; stateIndex < accounts.Count; stateIndex++)
                {
                    int candidateIndex = (nextAccountCursor + stateIndex) % accounts.Count;
                    KeystoneArcVirtualAccount candidate = accounts[candidateIndex];
                    if (!candidate.Blown && !candidate.ReplacementPending && !candidate.FundedCapPending && !candidate.DayLocked && !candidate.EvalMinDayHold && candidate.FreeAt <= when && StageAllows(candidate, e, cfg)) { selected = candidate; selectedIndex = candidateIndex; break; }
                }
                if (selected == null)
                {
                    List<KeystoneArcVirtualAccount> activeSlots = accounts.Where(x => !x.Blown && !x.ReplacementPending && !x.FundedCapPending).ToList();
                    e.SkipReason = !TierFiltersOff(cfg) && activeSlots.Any(x => !x.DayLocked && !StageAllows(x, e, cfg)) ? "QUALITY FILTER • TIER " + (string.IsNullOrEmpty(e.QualityTier) ? "?" : e.QualityTier) + " NOT TRADED BY THIS STAGE"
                        : activeSlots.Count > 0 && activeSlots.All(x => x.DayLocked)
                        ? "DAILY ACCOUNT LOCK • ALL ACTIVE ACCOUNTS LOCKED"
                        : (accounts.Any(x => x.FundedCapPending) ? "FIRM FUNDED CAP WAIT • PASSED EVAL BENCHED" : "NO FREE VIRTUAL ACCOUNT");
                    continue;
                }
                nextAccountCursor = (selectedIndex + 1) % accounts.Count;
                ApplyEvaluationStageOutcomeForAccount(e, selected, cfg);
                e.AssignedVirtualAccount = selected.Name;
                openPositions.Add(e);
                selected.LastAssignedDate = when.Date;
                selected.FreeAt = e.ExitTime == DateTime.MinValue ? when : e.ExitTime;
                selected.Trades++;
                selected.DayPnl += e.GrossPnl;
                selected.TotalPnl += e.GrossPnl;
                selected.PeakPnl = Math.Max(selected.PeakPnl, selected.TotalPnl);
                if (e.GrossPnl > 0) selected.Wins++; else if (e.GrossPnl < 0) selected.Losses++;
                if (cfg.EvaluationEnabled >= 0) ApplyIllustrativeLifecycle(selected, e.GrossPnl, cfg);
                if (IsTerminalSlot(selected))
                    FinalizeDay(selected, cfg);
                if (cfg.AllowMultipleSetupsPerDay <= 0)
                {
                    selected.DayLocked = true;
                    if (!selected.Blown && !selected.ReplacementPending) selected.LastState = "ONE SETUP / DAY LOCK";
                }
                else
                {
                    double profitLock = DailyProfitLock(selected, cfg);
                    double lossLock = DailyLossLock(selected, cfg);
                    // In one-day assignment mode there is no evaluation-credit ledger. Its stated
                    // rotation target is therefore measured from actual account DayPnl, exactly as
                    // it is for personal and funded scenarios. Only an active evaluation uses its
                    // capped evaluation-day credit for this lock.
                    double profitLockMeasure = EvaluationPhase(selected, cfg) ? selected.EvalDayCredit : selected.DayPnl;
                    if (profitLock > 0 && profitLockMeasure >= profitLock) { selected.DayLocked = true; selected.LastState = "DAILY PROFIT LOCK"; }
                    if (lossLock > 0 && selected.DayPnl <= -Math.Abs(lossLock)) { selected.DayLocked = true; selected.LastState = "DAILY LOSS LOCK"; }
                }
            }
                for (accountIndex = 0; accountIndex < accounts.Count; accountIndex++)
                    if (!(IsTerminalSlot(accounts[accountIndex]))) FinalizeDay(accounts[accountIndex], cfg);
            EnforceFirmFundedCapacity(accounts, cfg);
            return accounts;
        }

        // BH copy pool: every active slot receives each eligible event at the same time. This is
        // intentionally separate from rotation; it models a synchronized cohort, not an order
        // copier or live account action.
        private static List<KeystoneArcVirtualAccount> SimulateBhCopyPool(List<KeystoneArcEvent> events, KeystoneArcRunConfig cfg)
        {
            var accounts = new List<KeystoneArcVirtualAccount>();
            int count = Math.Max(1, cfg.PoolSize);
            DateTime initial = cfg.Start == DateTime.MinValue ? DateTime.MinValue : SessionGroupingDate(cfg.Start, cfg).Date;
            for (int i = 1; i <= count; i++)
            {
                KeystoneArcVirtualAccount account = CreatePoolAccount(cfg, i, initial, "COPY COHORT • EVALUATION READY");
                if (cfg.EvaluationEnabled == -2) account.LastState = "SINGLE ACCOUNT • COPY RANGE P/L ONLY";
                else if (cfg.EvaluationEnabled < 0) account.LastState = "ONE-DAY • COPY ASSIGNMENT";
                else if (cfg.EvaluationEnabled == 0) { account.Funded = true; account.EvaluationPassed = true; account.FundedSinceDate = initial; account.LastState = "COPY COHORT • FUNDED READY (ILLUSTRATIVE)"; }
                accounts.Add(account);
            }
            bool grouped = cfg.CopyTradingPool <= 0 && cfg.CopyGroupSize > 1;
            int groupSize = Math.Max(1, cfg.CopyGroupSize), groupCount = Math.Max(1, (accounts.Count + groupSize - 1) / groupSize), groupCursor = 0;
            var openPositions = new List<KeystoneArcEvent>();
            foreach (KeystoneArcEvent e in (events ?? new List<KeystoneArcEvent>()).OrderBy(x => x.EntryTime == DateTime.MinValue ? x.TriggerTime : x.EntryTime))
            {
                DateTime when = e.EntryTime == DateTime.MinValue ? e.TriggerTime : e.EntryTime;
                foreach (KeystoneArcVirtualAccount account in accounts)
                {
                    if (account.InitialLifecycleStart == DateTime.MinValue) { account.InitialLifecycleStart = when.Date; account.CurrentLifecycleStart = when.Date; }
                    if (IsTerminalSlot(account)) continue;
                    RollDay(account, when.Date, cfg, accounts);
                }
                EnforceFirmFundedCapacity(accounts, cfg);
                KeystoneArcEvent hedgeBlock = OppositeOpenPosition(openPositions, e, when);
                if (hedgeBlock != null) { e.SkipReason = NoHedgeReason(hedgeBlock); continue; }
                Func<KeystoneArcVirtualAccount, bool> free = x => !x.Blown && !x.ReplacementPending && !x.FundedCapPending && !x.DayLocked && !x.EvalMinDayHold && x.FreeAt <= when && StageAllows(x, e, cfg);
                List<KeystoneArcVirtualAccount> active;
                string groupLabel = null;
                if (grouped)
                {
                    // Copy to groups: the next group (in turn) with at least one free account takes it.
                    active = new List<KeystoneArcVirtualAccount>();
                    for (int k = 0; k < groupCount && active.Count == 0; k++)
                    {
                        int g = (groupCursor + k) % groupCount;
                        active = accounts.Skip(g * groupSize).Take(groupSize).Where(free).ToList();
                        if (active.Count > 0) { groupCursor = (g + 1) % groupCount; groupLabel = "GROUP " + (g + 1) + " → " + string.Join(", ", active.Select(a => a.Name)); }
                    }
                }
                else active = accounts.Where(free).ToList();
                if (active.Count == 0)
                {
                    e.SkipReason = accounts.Any(x => x.ReplacementPending || x.ReplacementBudgetBlocked) ? "COPY COHORT • WAITING FOR REPLACEMENT" : "COPY COHORT • DAILY LOCK OR NO ACTIVE ACCOUNT";
                    continue;
                }
                // All active accounts are at the same lifecycle point under a synchronized copy
                // run, so the evaluation override (if selected) produces one shared outcome.
                ApplyEvaluationStageOutcomeForAccount(e, active[0], cfg);
                e.AssignedVirtualAccount = groupLabel ?? ("COPY → " + active.Count + " ACTIVE ACCOUNT" + (active.Count == 1 ? string.Empty : "S"));
                openPositions.Add(e);
                foreach (KeystoneArcVirtualAccount account in active)
                {
                    account.LastAssignedDate = when.Date;
                    account.FreeAt = e.ExitTime == DateTime.MinValue ? when : e.ExitTime;
                    account.Trades++; account.DayPnl += e.GrossPnl; account.TotalPnl += e.GrossPnl; account.PeakPnl = Math.Max(account.PeakPnl, account.TotalPnl);
                    if (e.GrossPnl > 0) account.Wins++; else if (e.GrossPnl < 0) account.Losses++;
                    if (cfg.EvaluationEnabled >= 0) ApplyIllustrativeLifecycle(account, e.GrossPnl, cfg);
                    if (IsTerminalSlot(account)) FinalizeDay(account, cfg);
                    if (cfg.AllowMultipleSetupsPerDay <= 0)
                    {
                        account.DayLocked = true;
                        if (!account.Blown && !account.ReplacementPending) account.LastState = "COPY COHORT • ONE SETUP / DAY LOCK";
                    }
                    else
                    {
                        double profitLock = DailyProfitLock(account, cfg), lossLock = DailyLossLock(account, cfg);
                        double lockMeasure = EvaluationPhase(account, cfg) ? account.EvalDayCredit : account.DayPnl;
                        if (profitLock > 0 && lockMeasure >= profitLock) { account.DayLocked = true; account.LastState = "COPY COHORT • DAILY PROFIT LOCK"; }
                        if (lossLock > 0 && account.DayPnl <= -Math.Abs(lossLock)) { account.DayLocked = true; account.LastState = "COPY COHORT • DAILY LOSS LOCK"; }
                    }
                }
            }
            foreach (KeystoneArcVirtualAccount account in accounts)
                if (!(IsTerminalSlot(account))) FinalizeDay(account, cfg);
            EnforceFirmFundedCapacity(accounts, cfg);
            return accounts;
        }

        // Asian is copy trading, not rotation: one fully resolved 18:00 session result is copied
        // to every active virtual slot. Slots that are terminally blown (direct funded) or await a
        // next-session replacement are excluded without altering the historical cycle itself.
        // The Asian cycle settings to use while an account is in evaluation (a copy of the
        // funded/main configuration with the evaluation-stage overrides applied).
        public static KeystoneArcRunConfig AsianEvaluationStageConfig(KeystoneArcRunConfig cfg)
        {
            if (cfg == null || cfg.AsianEvalStageEnabled <= 0) return null;
            KeystoneArcRunConfig copy = cfg.ShallowCopy();
            copy.AsianCycleTargetDollars = cfg.AsianEvalCycleTargetDollars;
            copy.AsianReversalLossDollars = cfg.AsianEvalReversalLossDollars;
            int reversals = Math.Max(1, cfg.AsianEvalMaxReversals);
            copy.AsianMaxReversalsPerInstrument = reversals; copy.AsianMnqMaxReversals = reversals; copy.AsianMgcMaxReversals = reversals; copy.AsianMaxTotalLegsPerInstrument = reversals + 1;
            if (!string.Equals(cfg.AsianRiskMode, "PRICE", StringComparison.OrdinalIgnoreCase))
                copy.AsianDailyLossLimitDollars = AsianAutoDailyLossLimit("CASH", cfg.Scope, copy.AsianReversalLossDollars, cfg.AsianMnqReversalPriceMove, cfg.AsianMgcReversalPriceMove, reversals);
            return copy;
        }

        private static List<KeystoneArcVirtualAccount> SimulateAsian75CopyPool(List<KeystoneArcEvent> events, KeystoneArcRunConfig cfg, List<KeystoneArcEvent> evaluationStageEvents)
        {
            Dictionary<DateTime, List<KeystoneArcEvent>> evaluationNights = evaluationStageEvents == null ? null
                : evaluationStageEvents.Where(x => x != null).GroupBy(x => SessionGroupingDate(x.EntryTime == DateTime.MinValue ? x.TriggerTime : x.EntryTime, cfg)).ToDictionary(g => g.Key, g => g.ToList());
            var accounts = new List<KeystoneArcVirtualAccount>();
            int count = Math.Max(1, cfg.PoolSize);
            DateTime initial = cfg.Start == DateTime.MinValue ? DateTime.MinValue : SessionGroupingDate(cfg.Start, cfg).Date;
            for (int i = 1; i <= count; i++)
            {
                var account = CreatePoolAccount(cfg, i, initial, "EVALUATION READY • ASIAN COPY");
                if (cfg.EvaluationEnabled == -2) account.LastState = "SINGLE ACCOUNT • ASIAN COPY RANGE P/L ONLY";
                else if (cfg.EvaluationEnabled < 0) account.LastState = "ONE-DAY • ASIAN COPY";
                else if (cfg.EvaluationEnabled == 0) { account.Funded = true; account.EvaluationPassed = true; account.FundedSinceDate = initial; account.LastState = "FUNDED READY • ASIAN COPY (ILLUSTRATIVE)"; }
                accounts.Add(account);
            }
            foreach (IGrouping<DateTime, KeystoneArcEvent> group in (events ?? new List<KeystoneArcEvent>()).Where(x => x != null).OrderBy(x => x.EntryTime == DateTime.MinValue ? x.TriggerTime : x.EntryTime).GroupBy(x => SessionGroupingDate(x.TriggerTime, cfg)).OrderBy(x => x.Key))
            {
                DateTime day = group.Key;
                List<KeystoneArcEvent> cycle = group.OrderBy(x => x.EntryTime == DateTime.MinValue ? x.TriggerTime : x.EntryTime).ToList();
                foreach (KeystoneArcVirtualAccount account in accounts)
                {
                    if (IsTerminalSlot(account)) continue;
                    RollDay(account, day, cfg, accounts);
                }
                EnforceFirmFundedCapacity(accounts, cfg);
                List<KeystoneArcVirtualAccount> active = accounts.Where(x => !x.Blown && !x.ReplacementPending && !x.FundedCapPending && !x.DayLocked && !x.EvalMinDayHold).ToList();
                if (active.Count == 0)
                {
                    foreach (KeystoneArcEvent e in cycle) e.SkipReason = "NO ACTIVE VIRTUAL COPY ACCOUNT";
                    continue;
                }
                double fundedPnl = cycle.Sum(x => x.GrossPnl);
                int fundedWins = cycle.Count(x => x.GrossPnl > 0), fundedLosses = cycle.Count(x => x.GrossPnl < 0);
                List<KeystoneArcEvent> evalCycle = null;
                if (evaluationNights != null && !evaluationNights.TryGetValue(day, out evalCycle)) evalCycle = new List<KeystoneArcEvent>();
                string assigned = "COPY → " + active.Count + " ACTIVE ACCOUNT" + (active.Count == 1 ? string.Empty : "S");
                foreach (KeystoneArcEvent e in cycle) { e.AssignedVirtualAccount = assigned; e.SkipReason = string.Empty; }
                foreach (KeystoneArcVirtualAccount account in active)
                {
                    // An account in evaluation takes the evaluation-stage cycle when one was run.
                    bool evalLedger = evalCycle != null && EvaluationPhase(account, cfg);
                    List<KeystoneArcEvent> legs = evalLedger ? evalCycle : cycle;
                    double sessionPnl = evalLedger ? evalCycle.Sum(x => x.GrossPnl) : fundedPnl;
                    account.LastAssignedDate = day;
                    account.Trades += legs.Count;
                    account.Wins += evalLedger ? evalCycle.Count(x => x.GrossPnl > 0) : fundedWins;
                    account.Losses += evalLedger ? evalCycle.Count(x => x.GrossPnl < 0) : fundedLosses;
                    account.DayPnl += sessionPnl;
                    account.TotalPnl += sessionPnl;
                    account.PeakPnl = Math.Max(account.PeakPnl, account.TotalPnl);
                    if (cfg.EvaluationEnabled >= 0) ApplyIllustrativeLifecycle(account, sessionPnl, cfg);
                    if (IsTerminalSlot(account)) FinalizeDay(account, cfg);
                    // One combined cycle per night: its own target / loss limit already closed it,
                    // so the BH daily profit / loss locks do not apply to Asian accounts.
                }
            }
            foreach (KeystoneArcVirtualAccount account in accounts)
                if (!(IsTerminalSlot(account))) FinalizeDay(account, cfg);
            EnforceFirmFundedCapacity(accounts, cfg);
            return accounts;
        }

        private static List<KeystoneArcVirtualAccount> SimulateLiveAccount(List<KeystoneArcEvent> source, KeystoneArcRunConfig cfg)
        {
            var account = new KeystoneArcVirtualAccount { Name = "KA-LIVE", LastState = "LIVE ACCOUNT • HISTORICAL RANGE READY" };
            var events = (source ?? new List<KeystoneArcEvent>()).Where(x => x != null).OrderBy(x => x.EntryTime == DateTime.MinValue ? x.TriggerTime : x.EntryTime).ToList();
            for (int i = 0; i < events.Count; i++) { events[i].AssignedVirtualAccount = string.Empty; events[i].SkipReason = string.Empty; }

            var selected = new List<KeystoneArcEvent>();
            foreach (var dayGroup in events.GroupBy(x => SessionGroupingDate(x.TriggerTime, cfg)).OrderBy(x => x.Key))
            {
                // The live-account path is intentionally conservative: when BOTH is selected,
                // MNQ and MGC compete for the same single daily slot.  The earliest fully
                // resolved setup wins; the other instrument remains visible as evidence only.
                KeystoneArcEvent chosen = dayGroup
                    .Where(x => x.Outcome != "UNVERIFIED 1M" && x.Outcome != "NO ENTRY DATA" && !x.Outcome.StartsWith("OUTCOME BLOCKED", StringComparison.OrdinalIgnoreCase))
                    .OrderBy(x => x.EntryTime == DateTime.MinValue ? x.TriggerTime : x.EntryTime)
                    .ThenBy(x => x.Symbol, StringComparer.OrdinalIgnoreCase)
                    .FirstOrDefault();
                foreach (KeystoneArcEvent e in dayGroup.OrderBy(x => x.EntryTime == DateTime.MinValue ? x.TriggerTime : x.EntryTime))
                {
                    if (object.ReferenceEquals(e, chosen))
                    {
                        e.AssignedVirtualAccount = account.Name;
                        selected.Add(e);
                    }
                    else if (e.Outcome == "UNVERIFIED 1M" || e.Outcome == "NO ENTRY DATA" || e.Outcome.StartsWith("OUTCOME BLOCKED", StringComparison.OrdinalIgnoreCase))
                        e.SkipReason = "LIVE OUTCOME UNAVAILABLE";
                    else
                        e.SkipReason = "LIVE MAX ONE SETUP PER SESSION DATE";
                }
            }

            double running = 0;
            foreach (KeystoneArcEvent e in selected.OrderBy(x => x.EntryTime == DateTime.MinValue ? x.TriggerTime : x.EntryTime))
            {
                account.Trades++;
                account.TotalPnl += e.GrossPnl;
                running += e.GrossPnl;
                account.PeakPnl = Math.Max(account.PeakPnl, running);
                if (e.GrossPnl > 0) account.Wins++; else if (e.GrossPnl < 0) account.Losses++;
            }
            foreach (var day in events.GroupBy(x => SessionGroupingDate(x.TriggerTime, cfg)).OrderBy(x => x.Key))
            {
                List<KeystoneArcEvent> daySelected = selected.Where(x => SessionGroupingDate(x.TriggerTime, cfg) == day.Key).ToList();
                double dayPnl = daySelected.Sum(x => x.GrossPnl);
                account.DayHistory.Add(new KeystoneArcAccountDay
                {
                    Day = day.Key,
                    DayPnl = dayPnl,
                    DayLocked = daySelected.Count > 0,
                    EvaluationBalanceAfter = 0,
                    FundedBalanceAfter = 0,
                    StateAfterClose = daySelected.Count == 0 ? "LIVE DAY • NO RESOLVED TRADE" : "LIVE DAY • FIRST RESOLVED SETUP COMPLETE"
                });
            }
            account.ActiveDay = account.DayHistory.Count == 0 ? DateTime.MinValue : account.DayHistory[account.DayHistory.Count - 1].Day;
            account.DayPnl = account.DayHistory.Count == 0 ? 0 : account.DayHistory[account.DayHistory.Count - 1].DayPnl;
            account.LastState = "LIVE RANGE COMPLETE • ONE EARLIEST RESOLVED SETUP / SESSION DATE";
            return new List<KeystoneArcVirtualAccount> { account };
        }

        private static int CompareEventsByEntryTime(KeystoneArcEvent left, KeystoneArcEvent right)
        {
            DateTime leftTime = left.EntryTime == DateTime.MinValue ? left.TriggerTime : left.EntryTime;
            DateTime rightTime = right.EntryTime == DateTime.MinValue ? right.TriggerTime : right.EntryTime;
            return DateTime.Compare(leftTime, rightTime);
        }

        private static double DailyProfitLock(KeystoneArcVirtualAccount a, KeystoneArcRunConfig cfg)
        {
            // The regular DAILY PROFIT LOCK is the operational stop for every account.  The
            // evaluation daily-credit cap only limits what counts toward passing; it must not
            // silently let an evaluation keep trading beyond the stated daily target.
            if (EvaluationPhase(a, cfg))
            {
                double dailyTarget = Math.Max(0, cfg.DailyGoal);
                double creditCap = Math.Max(0, cfg.EvaluationDailyCreditCap);
                if (dailyTarget <= 0) return creditCap;
                return creditCap <= 0 ? dailyTarget : Math.Min(dailyTarget, creditCap);
            }
            return Math.Max(0, cfg.DailyGoal);
        }

        private static double DailyLossLock(KeystoneArcVirtualAccount a, KeystoneArcRunConfig cfg)
        {
            if (EvaluationPhase(a, cfg))
            {
                double regular = Math.Max(0, cfg.DailyLoss);
                double evalSpecific = Math.Max(0, cfg.EvaluationDailyLoss);
                return regular <= 0 ? evalSpecific : (evalSpecific <= 0 ? regular : Math.Min(regular, evalSpecific));
            }
            if (cfg.EvaluationEnabled >= 0 && a.Funded)
            {
                double regular = Math.Max(0, cfg.DailyLoss);
                double fundedSpecific = Math.Max(0, cfg.FundedDailyLoss);
                return regular <= 0 ? fundedSpecific : (fundedSpecific <= 0 ? regular : Math.Min(regular, fundedSpecific));
            }
            return Math.Max(0, cfg.DailyLoss);
        }

        private static void RollDay(KeystoneArcVirtualAccount a, DateTime day, KeystoneArcRunConfig cfg, IEnumerable<KeystoneArcVirtualAccount> pool)
        {
            if (a.ActiveDay == DateTime.MinValue) { a.ActiveDay = day; SnapshotDayStart(a, false); return; }
            if (a.ActiveDay == day) return;
            FinalizeDay(a, cfg);
            SnapshotDayStart(a, true);
            StartPendingReplacementAtNewSession(a, day, cfg, pool);
            a.DayStartBalance = a.Funded ? a.FundedBalance : a.EvaluationBalance;
            a.ActiveDay = day;
            a.DayPnl = 0;
            a.EvalDayCredit = 0;
            a.DayLocked = false;
        }

        private static void SnapshotDayStart(KeystoneArcVirtualAccount a, bool includePurchases)
        {
            a.DayStartTrades = a.Trades; a.DayStartWins = a.Wins; a.DayStartLosses = a.Losses;
            a.DayStartBalance = a.Funded ? a.FundedBalance : a.EvaluationBalance;
            a.DayStartPayouts = a.Payouts; a.DayStartPayoutGross = a.PayoutGrossWithdrawn; a.DayStartPayoutCash = a.PayoutCash;
            if (includePurchases) { a.DayStartCost = a.EvaluationCost; a.DayStartPurchases = a.EvaluationPurchases; }
        }

        private static void StartPendingReplacementAtNewSession(KeystoneArcVirtualAccount a, DateTime day, KeystoneArcRunConfig cfg, IEnumerable<KeystoneArcVirtualAccount> pool)
        {
            if (a == null || !a.ReplacementPending || cfg.EvaluationEnabled < 0 || string.Equals(cfg.AccountPath, "PERSONAL", StringComparison.OrdinalIgnoreCase)) return;
            // Realistic restart: buying and setting up a new evaluation takes time. With a delay of
            // N days the replacement first trades on the first session at least N + 1 calendar
            // days after the blowout (0 = next session, the original behaviour).
            if (cfg.DirectRefund())
            {
                if (a.LastBlowoutDate != DateTime.MinValue && day.Date < a.LastBlowoutDate.Date.AddDays(Math.Max(0, cfg.DirectRefundDays) + 1))
                {
                    a.LastState = "BLOWN • FUNDED AGAIN FROM " + a.LastBlowoutDate.Date.AddDays(Math.Max(0, cfg.DirectRefundDays) + 1).ToString("yyyy-MM-dd") + " (time to pass a new evaluation) (ILLUSTRATIVE)";
                    return;
                }
            }
            else if (cfg.ReplacementDelayDays > 0 && a.LastBlowoutDate != DateTime.MinValue && day.Date < a.LastBlowoutDate.Date.AddDays(cfg.ReplacementDelayDays + 1))
            {
                a.LastState = "BLOWN • NEW EVALUATION STARTS " + a.LastBlowoutDate.Date.AddDays(cfg.ReplacementDelayDays + 1).ToString("yyyy-MM-dd") + " OR LATER (ILLUSTRATIVE)";
                return;
            }
            if (cfg.ReplacementsRequirePayoutFunding > 0)
            {
                KeystoneArcCapitalPolicySummary capital = BuildCapitalPolicySummary(pool, cfg);
                // Replacements are released only when the modeled payout cash can fund the full
                // currently benched/pending replacement batch, rather than silently restarting
                // the first failed slot while the remaining failed slots are still unfunded.
                if (capital.ReplacementCashAvailable + 0.0001 < capital.CashRequiredForPendingReplacements)
                {
                    a.ReplacementBudgetBlocked = true;
                    a.LastState = "BENCHED • WAITING FOR PAYOUT-FUNDED REPLACEMENT (ILLUSTRATIVE)";
                    return;
                }
            }
            a.ReplacementPending = false;
            a.ReplacementFromFunded = false;
            a.ReplacementBudgetBlocked = false;
            a.FundedCapPending = false;
            a.DirectFundedStart = false;
            a.Blown = false;
            a.Funded = false; a.EvaluationPassed = false;
            a.EvaluationBalance = 0; a.FundedBalance = 0;
            a.PositiveDays = 0; a.ConsecutiveEvalQualifyingDays = 0; a.FundedPositiveDays = 0; a.EvalDayCredit = 0; a.EvalBestPositiveDay = 0;
            a.EvalTradingDays = 0; a.EvalMinDayHold = false;
            a.EvaluationPurchases++;
            a.EvaluationCost += cfg.ReplacementCost();
            a.CurrentLifecycleStart = a.ActiveDay == DateTime.MinValue ? DateTime.MinValue : a.ActiveDay.AddDays(1);
            a.LastState = "NEW EVALUATION PURCHASED • REPLACEMENT (ILLUSTRATIVE)";
            if (cfg.DirectRefund())
            {
                a.Funded = true; a.EvaluationPassed = true; a.DirectFundedStart = true;
                a.FundedSinceDate = day.Date;
                a.LastState = "FUNDED AGAIN • NEW ACCOUNT AFTER " + Math.Max(0, cfg.DirectRefundDays) + " DAY(S) (ILLUSTRATIVE)";
            }
        }

        private static void FinalizeDay(KeystoneArcVirtualAccount a, KeystoneArcRunConfig cfg)
        {
            if (a.ActiveDay == DateTime.MinValue) return;
            int tradesBefore = a.DayStartTrades;
            int winsBefore = a.DayStartWins;
            int lossesBefore = a.DayStartLosses;
            int purchasesBefore = a.DayStartPurchases;
            double costBefore = a.DayStartCost;
            int payoutsBefore = a.DayStartPayouts;
            double payoutGrossBefore = a.DayStartPayoutGross;
            double payoutCashBefore = a.DayStartPayoutCash;
            double balanceBefore = a.DayStartBalance;
            bool evalQualified = false;
            bool fundedQualified = false;
            if (cfg.EvaluationEnabled == -2)
            {
                a.LastState = a.Blown ? "SINGLE ACCOUNT • BLOWN" : "SINGLE ACCOUNT • RANGE P/L ONLY";
            }
            else if (string.Equals(cfg.AccountPath, "PERSONAL", StringComparison.OrdinalIgnoreCase))
            {
                a.LastState = a.Trades == 0 ? "LIVE ACCOUNT • UNUSED" :
                    (a.DayLocked ? (a.DayPnl >= Math.Max(0, cfg.DailyGoal) ? "DAILY PROFIT LOCK" : "DAILY LOSS LOCK") : "LIVE ACCOUNT • SESSION COMPLETE");
            }
            else if (cfg.EvaluationEnabled < 0)
            {
                a.LastState = a.Trades == 0 ? "ONE-DAY • UNUSED" :
                    (a.DayLocked ? (a.DayPnl >= Math.Max(0, cfg.DailyGoal) ? "DAILY PROFIT LOCK" : "DAILY LOSS LOCK") : "ONE-DAY • SESSION COMPLETE");
            }
            else if (a.ReplacementPending)
            {
                if (a.ReplacementBudgetBlocked)
                    a.LastState = "BENCHED • WAITING FOR PAYOUT-FUNDED REPLACEMENT (ILLUSTRATIVE)";
                else if (cfg.DirectRefund())
                    a.LastState = "FUNDED FAILURE • NEW FUNDED ACCOUNT FROM " + (a.LastBlowoutDate == DateTime.MinValue ? "THE NEXT SESSION" : a.LastBlowoutDate.Date.AddDays(Math.Max(0, cfg.DirectRefundDays) + 1).ToString("yyyy-MM-dd")) + " (ILLUSTRATIVE)";
                else
                    a.LastState = a.ReplacementFromFunded
                        ? "FUNDED FAILURE • REPLACEMENT EVALUATION NEXT SESSION (ILLUSTRATIVE)"
                        : "EVALUATION FAILURE • REPLACEMENT EVALUATION NEXT SESSION (ILLUSTRATIVE)";
            }
            else if (a.Blown)
            {
                a.LastState = cfg.EvaluationEnabled == 0 && a.EvaluationPurchases <= 1
                    ? "FUNDED BLOWN • DIRECT-FUNDED SLOT ENDED (ILLUSTRATIVE)"
                    : (ReplacesBlownAccounts(cfg) ? "ACCOUNT BLOWN • UNAVAILABLE" : "ACCOUNT BLOWN • SLOT ENDED (NO REPLACEMENT)");
            }
            else if (a.FundedCapPending)
            {
                a.LastState = "EVAL PASSED • FIRM FUNDED CAP WAIT (ILLUSTRATIVE)";
            }
            else if (!a.Funded)
            {
                // An evaluation pass is based on complete qualifying sessions.  The daily target
                // is the governing minimum when it is higher than the generic qualifying-day
                // field: for example, $1,000/day for three days requires three $1,000 days.
                // Asian trades one combined cycle per night, whose target is its own setting: the
                // BH daily profit lock ($1,500 by default) must not decide whether a night qualifies,
                // otherwise an Asian evaluation could never pass.
                bool asianStudy = string.Equals(cfg.StrategyCode, "ASIAN75", StringComparison.OrdinalIgnoreCase);
                double evalDayRequirement = Math.Max(0, cfg.MinimumQualifyingDayProfit);   // like the firms: the target decides; a pass day only needs the qualifying-day profit (not the daily profit lock)
                evalQualified = a.EvalDayCredit >= evalDayRequirement && (!asianStudy || a.DayPnl > 0);
                // A minimum-day trade (target already met) neither qualifies nor breaks the streak.
                if (a.EvalMinDayHold) { }
                else if (evalQualified)
                {
                    a.PositiveDays++;
                    a.ConsecutiveEvalQualifyingDays++;
                    a.EvalBestPositiveDay = Math.Max(a.EvalBestPositiveDay, a.EvalDayCredit);
                }
                else if (cfg.EvalQualifyingDaysConsecutive > 0) a.ConsecutiveEvalQualifyingDays = 0;
                bool consistencyOk = cfg.EvaluationConsistencyPercent <= 0 || a.EvaluationBalance <= 0 || a.EvalBestPositiveDay * 100.0 <= a.EvaluationBalance * cfg.EvaluationConsistencyPercent;
                // A day counts as a trading day when the account traded, or made its minimum-day trade.
                if (a.EvalMinDayHold || a.Trades > a.DayStartTrades) a.EvalTradingDays++;
                bool targetRulesMet = a.EvaluationBalance >= cfg.EvaluationTarget && a.ConsecutiveEvalQualifyingDays >= cfg.MinimumPositiveDays && consistencyOk;
                bool tradingDaysMet = cfg.EvaluationMinTradingDays <= 0 || a.EvalTradingDays >= cfg.EvaluationMinTradingDays;
                a.EvalMinDayHold = targetRulesMet && !tradingDaysMet;
                if (a.EvalMinDayHold)
                    a.LastState = "EVAL TARGET MET • MINIMUM TRADING DAYS " + a.EvalTradingDays + " / " + cfg.EvaluationMinTradingDays + " • NEXT DAY: MINIMAL TRADE (ILLUSTRATIVE)";
                else if (targetRulesMet)
                {
                    a.Funded = true;
                    a.EvaluationPassed = true;
                    a.FundedCapPending = false;
                    a.EvalMinDayHold = false; a.EvalTradingDays = 0;
                    a.FundedSinceDate = a.ActiveDay;
                    if (a.FirstEvaluationPassDate == DateTime.MinValue) a.FirstEvaluationPassDate = a.ActiveDay;
                    a.EvaluationPasses++;
                    a.FundedBalance = 0;
                    a.FundedPositiveDays = 0;
                    a.LastState = "FUNDED (ILLUSTRATIVE)";
                }
                else if (a.EvaluationBalance >= cfg.EvaluationTarget && a.ConsecutiveEvalQualifyingDays >= cfg.MinimumPositiveDays && !consistencyOk)
                    a.LastState = "EVAL TARGET MET • CONSISTENCY WAIT (ILLUSTRATIVE)";
                else if (a.LastState != "EVALUATION RESET (ILLUSTRATIVE)")
                    a.LastState = "EVALUATION IN PROGRESS (ILLUSTRATIVE)";
            }
            else
            {
                fundedQualified = a.DayPnl >= Math.Max(0, cfg.MinimumQualifyingDayProfit);
                if (fundedQualified) a.FundedPositiveDays++;
                if (a.FundedBalance >= cfg.PayoutThreshold && a.FundedPositiveDays >= cfg.PayoutDaysRequired)
                {
                    double balanceBeforeWithdrawal = a.FundedBalance;
                    double withdrawal = Math.Min(Math.Max(0, cfg.PayoutAmount), a.FundedBalance);
                    double netCash = withdrawal * Math.Max(0, Math.Min(100, cfg.PayoutProfitSharePercent)) / 100.0;
                    a.Payouts++;
                    a.LastPayoutDate = a.ActiveDay;
                    if (a.FirstPayoutDate == DateTime.MinValue) a.FirstPayoutDate = a.ActiveDay;
                    a.PayoutGrossWithdrawn += withdrawal;
                    a.PayoutCash += netCash;
                    a.FundedBalance -= withdrawal;
                    a.FundedPositiveDays = 0;
                    a.LastState = "PAYOUT RECORDED • GROSS " + withdrawal.ToString("C0") + " • NET SHARE " + netCash.ToString("C0") + " • BALANCE " + balanceBeforeWithdrawal.ToString("C0") + " → " + a.FundedBalance.ToString("C0") + " (ILLUSTRATIVE)";
                }
                else if (a.LastState != "FUNDED FAILURE → EVALUATION RESET (ILLUSTRATIVE)")
                    a.LastState = "FUNDED • PAYOUT PROGRESS (ILLUSTRATIVE)";
            }
            string closeState = a.LastState;
            if (a.DayLocked)
            {
                double profitLock = DailyProfitLock(a, cfg);
                double profitLockMeasure = EvaluationPhase(a, cfg) ? a.EvalDayCredit : a.DayPnl;
                bool profitLocked = profitLockMeasure >= profitLock;
                string lockLabel = profitLocked ? "DAILY PROFIT LOCK" : "DAILY LOSS LOCK";
                closeState = closeState.StartsWith(lockLabel, StringComparison.OrdinalIgnoreCase) ? closeState : lockLabel + " • " + closeState;
            }
            a.DayHistory.Add(new KeystoneArcAccountDay
            {
                Day = a.ActiveDay,
                DayPnl = a.DayPnl,
                TradesAfter = Math.Max(0, a.Trades - tradesBefore),
                WinsAfter = Math.Max(0, a.Wins - winsBefore),
                LossesAfter = Math.Max(0, a.Losses - lossesBefore),
                BalanceBefore = balanceBefore,
                BalanceAfter = a.Funded ? a.FundedBalance : a.EvaluationBalance,
                CostDelta = a.EvaluationCost - costBefore,
                PayoutGrossDelta = a.PayoutGrossWithdrawn - payoutGrossBefore,
                PayoutCashDelta = a.PayoutCash - payoutCashBefore,
                EvaluationPurchaseDelta = Math.Max(0, a.EvaluationPurchases - purchasesBefore),
                EvaluationPassDateAfter = a.FirstEvaluationPassDate,
                FirstPayoutDateAfter = a.FirstPayoutDate,
                DayLocked = a.DayLocked,
                EvalQualifyingDay = evalQualified,
                FundedQualifyingDay = fundedQualified,
                EvaluationBalanceAfter = cfg.EvaluationEnabled == -2 ? a.StartingBalance + a.TotalPnl : a.EvaluationBalance,
                FundedBalanceAfter = cfg.EvaluationEnabled == -2 ? a.StartingBalance + a.TotalPnl : a.FundedBalance,
                EvaluationQualifyingDaysAfter = a.PositiveDays,
                ConsecutiveEvalQualifyingDaysAfter = a.ConsecutiveEvalQualifyingDays,
                FundedQualifyingDaysAfter = a.FundedPositiveDays,
                PayoutsAfter = a.Payouts,
                PayoutGrossAfter = a.PayoutGrossWithdrawn,
                PayoutCashAfter = a.PayoutCash,
                EvaluationPurchasesAfter = a.EvaluationPurchases,
                EvaluationPassesAfter = a.EvaluationPasses,
                EvaluationCostAfter = a.EvaluationCost,
                FundedAfter = a.Funded,
                LifecycleStartAfter = a.CurrentLifecycleStart,
                ReplacementPendingAfter = a.ReplacementPending,
                FundedCapPendingAfter = a.FundedCapPending,
                PropFirmAfter = a.PropFirmCode,
                FundedSlotsInFirmAfter = UsesFirmFundedCap(cfg) ? FundedSlotsInFirm(new[] { a }, a.PropFirmCode) : 0,
                BlownAfter = a.Blown,
                StateAfterClose = closeState
            });
            a.LastState = closeState;
        }

        private static void ApplyIllustrativeLifecycle(KeystoneArcVirtualAccount a, double pnl, KeystoneArcRunConfig cfg)
        {
            if (cfg.EvaluationEnabled < 0) return;
            // A direct-funded start trades funded from day one; its replacement (if any) is an
            // evaluation and follows the evaluation branch below.
            if (DirectFundedPhase(a, cfg)) a.Funded = true;
            bool replace = ReplacesBlownAccounts(cfg);
            if (!a.Funded)
            {
                if (pnl > 0)
                {
                    double credit = Math.Min(pnl, Math.Max(0, cfg.EvaluationDailyCreditCap - a.EvalDayCredit));
                    a.EvalDayCredit += credit;
                    a.EvaluationBalance += credit;
                }
                else a.EvaluationBalance += pnl;
                if (a.EvaluationBalance <= -Math.Abs(cfg.EvaluationFailure))
                {
                    a.FailedEvaluations++;
                    a.PositiveDays = 0;
                    a.ConsecutiveEvalQualifyingDays = 0;
                    a.EvalDayCredit = 0;
                    a.EvalBestPositiveDay = 0;
                    a.ReplacementPending = replace;
                    a.ReplacementFromFunded = false;
                    a.FundedCapPending = false;
                    a.Blown = true;
                    a.LastBlowoutDate = a.ActiveDay;
                    if (!replace) a.TerminalLifecycleEnd = a.ActiveDay;
                    a.DayLocked = true;
                    a.LastState = replace ? "EVALUATION FAILURE • REPLACEMENT NEXT SESSION (ILLUSTRATIVE)" : "EVALUATION FAILURE • SLOT ENDED (NO REPLACEMENT)";
                }
            }
            else
            {
                a.FundedBalance += pnl;
                if (a.FundedBalance <= -Math.Abs(cfg.FundedFailure))
                {
                    a.FailedFunded++;
                    a.Funded = false;
                    a.EvaluationPassed = false;
                    a.PositiveDays = 0;
                    a.ConsecutiveEvalQualifyingDays = 0;
                    a.FundedPositiveDays = 0;
                    a.EvalDayCredit = 0;
                    a.EvalBestPositiveDay = 0;
                    a.Blown = true;
                    a.ReplacementPending = replace;
                    a.ReplacementFromFunded = replace;
                    a.FundedCapPending = false;
                    a.LastBlowoutDate = a.ActiveDay;
                    if (!replace) a.TerminalLifecycleEnd = a.ActiveDay;
                    a.DayLocked = true;
                    a.LastState = replace
                        ? (cfg.DirectRefund() ? "FUNDED BLOWN • NEW FUNDED ACCOUNT AFTER " + Math.Max(0, cfg.DirectRefundDays) + " DAY(S) (ILLUSTRATIVE)" : "FUNDED BLOWN • REPLACEMENT EVALUATION NEXT SESSION (ILLUSTRATIVE)")
                        : (cfg.EvaluationEnabled == 0 ? "FUNDED BLOWN • DIRECT-FUNDED SLOT ENDED (ILLUSTRATIVE)" : "FUNDED BLOWN • SLOT ENDED (NO REPLACEMENT)");
                }
            }
        }

        // Cumulative values in AccountDay are deliberately converted to daily deltas here.  A
        // report must never sum PayoutsAfter or PayoutCashAfter directly because that would
        // overstate simultaneous payout-cycle totals.
        public static List<KeystoneArcPayoutAuditDay> BuildPayoutAuditDays(IEnumerable<KeystoneArcVirtualAccount> source)
        {
            var rows = new List<KeystoneArcPayoutAuditDay>();
            foreach (KeystoneArcVirtualAccount account in source ?? Enumerable.Empty<KeystoneArcVirtualAccount>())
            {
                if (account == null) continue;
                int priorPayouts = 0, priorPurchases = 0;
                double priorGross = 0, priorNet = 0, priorCost = 0;
                foreach (KeystoneArcAccountDay day in account.DayHistory.OrderBy(x => x.Day))
                {
                    if (day == null) continue;
                    rows.Add(new KeystoneArcPayoutAuditDay
                    {
                        Account = account.Name ?? string.Empty,
                        DaySnapshot = day,
                        PayoutDelta = Math.Max(0, day.PayoutsAfter - priorPayouts),
                        PayoutGrossDelta = day.PayoutGrossAfter - priorGross,
                        PayoutCashDelta = day.PayoutCashAfter - priorNet,
                        EvaluationPurchaseDelta = Math.Max(0, day.EvaluationPurchasesAfter - priorPurchases),
                        EvaluationCostDelta = day.EvaluationCostAfter - priorCost
                    });
                    priorPayouts = day.PayoutsAfter;
                    priorPurchases = day.EvaluationPurchasesAfter;
                    priorGross = day.PayoutGrossAfter;
                    priorNet = day.PayoutCashAfter;
                    priorCost = day.EvaluationCostAfter;
                }
            }
            return rows.OrderBy(x => x.DaySnapshot.Day).ThenBy(x => x.Account, StringComparer.OrdinalIgnoreCase).ToList();
        }

        public static KeystoneArcCapitalPolicySummary BuildCapitalPolicySummary(IEnumerable<KeystoneArcVirtualAccount> source, KeystoneArcRunConfig cfg)
        {
            List<KeystoneArcVirtualAccount> accounts = (source ?? Enumerable.Empty<KeystoneArcVirtualAccount>()).Where(x => x != null).ToList();
            var result = new KeystoneArcCapitalPolicySummary
            {
                GateEnabled = cfg != null && cfg.EvaluationEnabled >= 0 && cfg.ReplacementsRequirePayoutFunding > 0,
                InitialEvaluationPurchases = cfg != null && cfg.EvaluationEnabled >= 0 ? accounts.Count : 0,
                PayoutCashAfterShare = accounts.Sum(x => x.PayoutCash),
                TotalEvaluationCost = accounts.Sum(x => x.EvaluationCost),
                BenchedReplacementSlots = accounts.Count(x => x.ReplacementPending && x.ReplacementBudgetBlocked),
                PendingReplacementSlots = accounts.Count(x => x.ReplacementPending)
            };
            // The selected initial pool is a separate cash commitment. The optional gate compares
            // subsequent replacement purchases only with modeled payout cash after the account
            // share, avoiding any claim that trading P/L is withdrawable cash.
            result.InitialEvaluationInvestment = result.InitialEvaluationPurchases * (cfg == null ? 0 : Math.Max(0, cfg.InitialAccountCost()));
            result.ReplacementEvaluationCost = Math.Max(0, result.TotalEvaluationCost - result.InitialEvaluationInvestment);
            result.ReplacementEvaluationPurchases = cfg == null || cfg.ReplacementCost() <= 0 ? 0 : (int)Math.Round(result.ReplacementEvaluationCost / cfg.ReplacementCost(), MidpointRounding.AwayFromZero);
            result.PayoutCashAfterInitialInvestment = result.PayoutCashAfterShare - result.InitialEvaluationInvestment;
            // The optional policy is intentionally stricter than merely matching one new fee:
            // modeled payout cash must recover the initial selected evaluation investment and
            // any already-paid replacement cost before it is available to buy another batch.
            // This is a virtual cash gate, not a claim about a firm's actual payout timing.
            result.ReplacementCashAvailable = Math.Max(0, result.PayoutCashAfterShare - result.InitialEvaluationInvestment - result.ReplacementEvaluationCost);
            result.CashRequiredForPendingReplacements = result.PendingReplacementSlots * (cfg == null ? 0 : Math.Max(0, cfg.ReplacementCost()));
            result.ReplacementCashShortfall = Math.Max(0, result.CashRequiredForPendingReplacements - result.ReplacementCashAvailable);
            result.FullNetCashAfterAllCosts = result.PayoutCashAfterShare - result.TotalEvaluationCost;

            // Build a chronological cash trail from immutable daily snapshots.  Initial purchases
            // are present in the first daily snapshot for every active slot; later positive
            // purchase deltas are replacement evaluations.  This makes the cost through the
            // actual first payout and the later break-even date auditable instead of deducting
            // only the initial account batch in every scenario.
            List<KeystoneArcPayoutAuditDay> audit = BuildPayoutAuditDays(accounts);
            var byDay = new Dictionary<DateTime, KeystoneArcCapitalPolicyDay>();
            foreach (IGrouping<string, KeystoneArcPayoutAuditDay> accountRows in audit.GroupBy(x => x.Account ?? string.Empty, StringComparer.OrdinalIgnoreCase))
            {
                // All selected accounts are purchased at the start of the test, including slots
                // whose first assigned trade occurs later.  Therefore the first daily snapshot
                // for a slot establishes its initial purchase baseline and must not be added to
                // the later replenishment timeline.
                bool baseline = true;
                foreach (KeystoneArcPayoutAuditDay row in accountRows.OrderBy(x => x.DaySnapshot == null ? DateTime.MaxValue : x.DaySnapshot.Day))
                {
                    if (row == null || row.DaySnapshot == null) continue;
                    DateTime day = row.DaySnapshot.Day.Date;
                    KeystoneArcCapitalPolicyDay dayRow;
                    if (!byDay.TryGetValue(day, out dayRow))
                    {
                        dayRow = new KeystoneArcCapitalPolicyDay { Day = day };
                        byDay.Add(day, dayRow);
                    }
                    dayRow.PayoutCash += row.PayoutCashDelta;
                    if (!baseline && row.EvaluationPurchaseDelta > 0)
                    {
                        dayRow.ReplacementPurchases += row.EvaluationPurchaseDelta;
                        dayRow.ReplenishedSlots.Add(row.Account ?? string.Empty);
                    }
                    baseline = false;
                }
            }
            double cumulativePayout = 0;
            double cumulativeInvestment = result.InitialEvaluationInvestment;
            int cumulativePurchases = result.InitialEvaluationPurchases;
            int cumulativeReplacementPurchases = 0;
            var replenishedSlots = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            result.MaxOutOfPocket = result.InitialEvaluationInvestment;
            foreach (KeystoneArcCapitalPolicyDay dayRow in byDay.Values.OrderBy(x => x.Day))
            {
                // The cumulative cost derives from the daily purchase count, preserving the
                // configured fee even if an account was later blown or benched.
                int purchasesThisDay = dayRow.ReplacementPurchases;
                cumulativePurchases += purchasesThisDay;
                cumulativeReplacementPurchases += dayRow.ReplacementPurchases;
                cumulativeInvestment += purchasesThisDay * (cfg == null ? 0 : Math.Max(0, cfg.ReplacementCost()));
                double outOfPocket = cumulativeInvestment - cumulativePayout;
                if (outOfPocket > result.MaxOutOfPocket + 0.005) { result.MaxOutOfPocket = outOfPocket; result.MaxOutOfPocketDate = dayRow.Day; }
                cumulativePayout += dayRow.PayoutCash;
                foreach (string name in dayRow.ReplenishedSlots) replenishedSlots.Add(name);

                if (!result.FirstPayoutReached && dayRow.PayoutCash > 0)
                {
                    result.FirstPayoutReached = true;
                    result.FirstPayoutDate = dayRow.Day;
                    result.PayoutCashThroughFirstPayoutDate = cumulativePayout;
                    result.InvestmentThroughFirstPayoutDate = cumulativeInvestment;
                    result.EvaluationPurchasesThroughFirstPayoutDate = cumulativePurchases;
                    result.ReplacementPurchasesThroughFirstPayoutDate = cumulativeReplacementPurchases;
                    result.ReplenishedSlotsThroughFirstPayoutDate = replenishedSlots.Count;
                    result.NetCashThroughFirstPayoutDate = cumulativePayout - cumulativeInvestment;
                }
                if (!result.ProfitabilityReached && cumulativePayout > 0 && cumulativePayout >= cumulativeInvestment)
                {
                    result.ProfitabilityReached = true;
                    result.ProfitabilityDate = dayRow.Day;
                    result.PayoutCashThroughProfitability = cumulativePayout;
                    result.InvestmentThroughProfitability = cumulativeInvestment;
                    result.EvaluationPurchasesThroughProfitability = cumulativePurchases;
                    result.ReplacementPurchasesThroughProfitability = cumulativeReplacementPurchases;
                    result.NetCashAtProfitability = cumulativePayout - cumulativeInvestment;
                }
            }
            // If the date range has no daily snapshots (for example no eligible setup), retain
            // truthful range totals without fabricating a first-cash or profitability date.
            if (!result.FirstPayoutReached) result.InvestmentThroughFirstPayoutDate = result.TotalEvaluationCost;
            result.AccountsPaidUpfront = Math.Min(result.TotalEvaluationCost, result.MaxOutOfPocket);
            result.AccountsPaidFromPayouts = Math.Max(0, result.TotalEvaluationCost - result.AccountsPaidUpfront);
            result.PayoutsWithdrawn = Math.Max(0, result.PayoutCashAfterShare - result.AccountsPaidFromPayouts);
            if (!result.ProfitabilityReached)
            {
                result.InvestmentThroughProfitability = result.TotalEvaluationCost;
                result.PayoutCashThroughProfitability = result.PayoutCashAfterShare;
                result.NetCashAtProfitability = result.FullNetCashAfterAllCosts;
                result.EvaluationPurchasesThroughProfitability = cfg == null || cfg.EvaluationCost <= 0 ? 0 : (int)Math.Round(result.TotalEvaluationCost / cfg.EvaluationCost, MidpointRounding.AwayFromZero);
                result.ReplacementPurchasesThroughProfitability = result.ReplacementEvaluationPurchases;
            }
            return result;
        }

        public static KeystoneArcFirstPayoutTiming GetFirstPayoutTiming(KeystoneArcVirtualAccount account)
        {
            var result = new KeystoneArcFirstPayoutTiming();
            if (account == null || account.DayHistory.Count == 0) return result;
            List<KeystoneArcAccountDay> days = account.DayHistory.OrderBy(x => x.Day).ToList();
            result.InitialSlotStart = account.InitialLifecycleStart == DateTime.MinValue ? days[0].Day : account.InitialLifecycleStart;
            int priorPayouts = 0;
            DateTime lifeStart = result.InitialSlotStart;
            for (int i = 0; i < days.Count; i++)
            {
                KeystoneArcAccountDay day = days[i];
                if (day.LifecycleStartAfter != DateTime.MinValue) lifeStart = day.LifecycleStartAfter;
                if (day.PayoutsAfter > priorPayouts)
                {
                    result.HasPayout = true;
                    result.FirstPayoutDate = day.Day;
                    result.LifecycleStartForFirstPayout = lifeStart;
                    result.CalendarDaysFromInitial = Math.Max(0, (day.Day.Date - result.InitialSlotStart.Date).Days);
                    result.RecordedSessionsFromInitial = days.Count(x => x.Day >= result.InitialSlotStart && x.Day <= day.Day);
                    result.CalendarDaysFromLifecycleStart = Math.Max(0, (day.Day.Date - lifeStart.Date).Days);
                    result.RecordedSessionsFromLifecycleStart = days.Count(x => x.Day >= lifeStart && x.Day <= day.Day);
                    return result;
                }
                priorPayouts = day.PayoutsAfter;
            }
            return result;
        }

        public static List<KeystoneArcFirstReturnRow> BuildFirstReturnRows(IEnumerable<KeystoneArcVirtualAccount> source)
        {
            var rows = new List<KeystoneArcFirstReturnRow>();
            foreach (KeystoneArcVirtualAccount account in (source ?? Enumerable.Empty<KeystoneArcVirtualAccount>()).Where(x => x != null).OrderBy(x => x.Name, StringComparer.OrdinalIgnoreCase))
            {
                List<KeystoneArcAccountDay> days = account.DayHistory.Where(x => x != null).OrderBy(x => x.Day).ToList();
                var row = new KeystoneArcFirstReturnRow
                {
                    Account = account.Name ?? string.Empty,
                    InitialSlotStart = account.InitialLifecycleStart == DateTime.MinValue ? (days.Count == 0 ? DateTime.MinValue : days[0].Day) : account.InitialLifecycleStart
                };
                int priorPayouts = 0;
                double priorGross = 0, priorCash = 0;
                for (int i = 0; i < days.Count; i++)
                {
                    KeystoneArcAccountDay day = days[i];
                    if (day.PayoutsAfter > priorPayouts)
                    {
                        row.HasPayout = true;
                        row.FirstPayoutDate = day.Day;
                        row.FirstPayoutGross = day.PayoutGrossAfter - priorGross;
                        row.FirstPayoutCashAfterShare = day.PayoutCashAfter - priorCash;
                        row.EvaluationCostThroughFirstPayout = day.EvaluationCostAfter;
                        // PayoutCashAfter is all cash recorded through the first return. Before
                        // that date it is zero; costs include every initial/replacement purchase.
                        row.FullNetReturnAfterAllCosts = day.PayoutCashAfter - day.EvaluationCostAfter;
                        row.CalendarDaysFromInitial = row.InitialSlotStart == DateTime.MinValue ? 0 : Math.Max(0, (day.Day.Date - row.InitialSlotStart.Date).Days);
                        row.RecordedSessionsFromInitial = row.InitialSlotStart == DateTime.MinValue ? 0 : days.Count(x => x.Day >= row.InitialSlotStart && x.Day <= day.Day);
                        row.StateAtFirstPayout = day.StateAfterClose ?? string.Empty;
                        break;
                    }
                    priorPayouts = day.PayoutsAfter;
                    priorGross = day.PayoutGrossAfter;
                    priorCash = day.PayoutCashAfter;
                }
                rows.Add(row);
            }
            return rows;
        }

        public static List<KeystoneArcPayoutCycleRow> BuildPayoutCycleRows(IEnumerable<KeystoneArcVirtualAccount> source, KeystoneArcRunConfig cfg)
        {
            List<KeystoneArcVirtualAccount> accounts = (source ?? Enumerable.Empty<KeystoneArcVirtualAccount>()).Where(x => x != null).ToList();
            List<KeystoneArcPayoutAuditDay> audit = BuildPayoutAuditDays(accounts);
            var rows = new List<KeystoneArcPayoutCycleRow>();
            foreach (IGrouping<DateTime, KeystoneArcPayoutAuditDay> group in audit.Where(x => x.PayoutDelta > 0).GroupBy(x => x.DaySnapshot.Day.Date).OrderBy(x => x.Key))
            {
                var row = new KeystoneArcPayoutCycleRow
                {
                    Day = group.Key,
                    PayoutAccounts = group.Count(x => x.PayoutDelta > 0),
                    PayoutCycles = group.Sum(x => x.PayoutDelta),
                    GrossWithdrawals = group.Sum(x => x.PayoutGrossDelta),
                    NetCashAfterShare = group.Sum(x => x.PayoutCashDelta),
                    EvaluationPurchases = audit.Where(x => x.DaySnapshot.Day.Date == group.Key).Sum(x => x.EvaluationPurchaseDelta),
                    EvaluationCostOnDate = audit.Where(x => x.DaySnapshot.Day.Date == group.Key).Sum(x => x.EvaluationCostDelta)
                };
                row.NetCashAfterEvaluationCost = row.NetCashAfterShare - row.EvaluationCostOnDate;
                row.CumulativePayoutCashThroughDate = audit.Where(x => x.DaySnapshot.Day.Date <= group.Key).Sum(x => x.PayoutCashDelta);
                row.CumulativeEvaluationCostThroughDate = audit.Where(x => x.DaySnapshot.Day.Date <= group.Key).Sum(x => x.EvaluationCostDelta);
                row.CumulativeFullNetCashAfterAllCosts = row.CumulativePayoutCashThroughDate - row.CumulativeEvaluationCostThroughDate;
                row.PayoutContributors.AddRange(group.OrderBy(x => x.Account, StringComparer.OrdinalIgnoreCase).Select(x => x.Account + " ×" + x.PayoutDelta));
                foreach (KeystoneArcVirtualAccount account in accounts)
                {
                    KeystoneArcAccountDay snapshot = account.DayHistory.Where(x => x.Day <= group.Key).OrderByDescending(x => x.Day).FirstOrDefault();
                    if (snapshot == null)
                    {
                        if (account.Blown && !account.ReplacementPending) row.TerminalBlown++;
                        else if (account.ReplacementPending) row.ReplacementNextSession++;
                        else if (account.Funded)
                        {
                            row.FundedAtClose++;
                            if (cfg != null && account.FundedBalance < cfg.PayoutThreshold) row.FundedBelowPayoutGoal++;
                        }
                        else row.EvaluationInProgress++;
                        continue;
                    }
                    if (snapshot.BlownAfter && !snapshot.ReplacementPendingAfter) row.TerminalBlown++;
                    else if (snapshot.ReplacementPendingAfter) row.ReplacementNextSession++;
                    else if (snapshot.FundedAfter)
                    {
                        row.FundedAtClose++;
                        if (cfg != null && snapshot.FundedBalanceAfter < cfg.PayoutThreshold) row.FundedBelowPayoutGoal++;
                    }
                    else row.EvaluationInProgress++;
                }
                rows.Add(row);
            }
            for (int i = 0; i < rows.Count; i++) rows[i].CycleNumber = i + 1;
            return rows;
        }

        public static List<KeystoneArcBalanceMatrixRow> BuildBalanceMatrixRows(IEnumerable<KeystoneArcVirtualAccount> source, KeystoneArcRunConfig cfg)
        {
            List<KeystoneArcVirtualAccount> accounts = (source ?? Enumerable.Empty<KeystoneArcVirtualAccount>()).Where(x => x != null).ToList();
            List<KeystoneArcPayoutAuditDay> audit = BuildPayoutAuditDays(accounts);
            var rows = new List<KeystoneArcBalanceMatrixRow>();
            foreach (KeystoneArcPayoutCycleRow cycle in BuildPayoutCycleRows(accounts, cfg))
            {
                foreach (KeystoneArcVirtualAccount account in accounts)
                {
                    KeystoneArcAccountDay snapshot = account.DayHistory.Where(x => x.Day <= cycle.Day).OrderByDescending(x => x.Day).FirstOrDefault();
                    if (snapshot == null)
                    {
                        string unstarted = account.Blown && !account.ReplacementPending ? "TERMINAL BLOWN" : (account.ReplacementPending ? "REPLACEMENT NEXT SESSION" : (account.Funded ? "FUNDED BELOW PAYOUT GOAL" : "NO RECORDED SESSION YET"));
                        rows.Add(new KeystoneArcBalanceMatrixRow { CycleNumber = cycle.CycleNumber, Day = cycle.Day, Account = account.Name, Status = unstarted, BalanceBefore = 0, GrossPayout = 0, CarryForwardBalance = 0, DayPnl = 0 });
                        continue;
                    }
                    KeystoneArcPayoutAuditDay transaction = audit.FirstOrDefault(x => string.Equals(x.Account, account.Name, StringComparison.OrdinalIgnoreCase) && x.DaySnapshot.Day.Date == cycle.Day.Date);
                    double gross = transaction == null ? 0 : transaction.PayoutGrossDelta;
                    double carry = snapshot.FundedAfter ? snapshot.FundedBalanceAfter : snapshot.EvaluationBalanceAfter;
                    string status = gross > 0 ? "PAID" : (snapshot.BlownAfter && !snapshot.ReplacementPendingAfter ? "TERMINAL BLOWN" : (snapshot.ReplacementPendingAfter ? "REPLACEMENT NEXT SESSION" : (snapshot.FundedAfter ? "FUNDED BELOW PAYOUT GOAL" : "EVALUATION IN PROGRESS")));
                    rows.Add(new KeystoneArcBalanceMatrixRow
                    {
                        CycleNumber = cycle.CycleNumber,
                        Day = cycle.Day,
                        Account = account.Name,
                        Status = status,
                        BalanceBefore = gross > 0 ? snapshot.FundedBalanceAfter + gross : carry,
                        GrossPayout = gross,
                        CarryForwardBalance = carry,
                        DayPnl = snapshot.DayPnl
                    });
                }
            }
            return rows.OrderBy(x => x.CycleNumber).ThenBy(x => x.Account, StringComparer.OrdinalIgnoreCase).ToList();
        }

        private static bool InsideSession(DateTime t, string symbol, KeystoneArcRunConfig cfg)
        {
            int hhmm = t.Hour * 100 + t.Minute;
            string mode = (cfg.SessionMode ?? "INSTRUMENT_DEFAULT").ToUpperInvariant();
            if (mode == "FULL_GLOBEX" || mode == "ALL_ELIGIBLE") return InSessionWindow(hhmm, 1800, cfg.EndTime);
            if (mode == "ASIAN75") return InSessionWindow(hhmm, cfg.AsianStartHhmm, cfg.AsianEndHhmm);
            if (mode == "ASIA" || mode == "ASIAN") return InSessionWindow(hhmm, 1900, 300);
            if (mode == "LONDON") return InSessionWindow(hhmm, 300, 1130);
            if (mode == "NY_EARLY") return InSessionWindow(hhmm, 800, cfg.EndTime);
            if (mode == "NY_OPEN" || mode == "NY_AFTER_0930" || mode == "CUSTOM") return InSessionWindow(hhmm, cfg.CustomStart, cfg.EndTime);
            int start = IsMgc(symbol) ? cfg.MgcStart : cfg.MnqStart;
            return InSessionWindow(hhmm, start, cfg.EndTime);
        }

        private static bool InSessionWindow(int hhmm, int start, int end)
        {
            if (start <= end) return hhmm >= start && hhmm <= end;
            return hhmm >= start || hhmm <= end;
        }

        private static string Strength(List<KeystoneArcBar> bars, int i)
        {
            if (i < 3) return "BASE";
            double redBody = 0;
            int red = 0;
            for (int x = i - 2; x >= 0 && x >= i - 7; x--)
            {
                if (bars[x].Close >= bars[x].Open) break;
                red++;
                redBody += bars[x].Open - bars[x].Close;
            }
            double referenceBody = Math.Abs(bars[i - 1].Close - bars[i - 1].Open);
            if (red >= 3 || redBody > Math.Max(0.0001, referenceBody) * 3.0) return "AGGR";
            double wick = Math.Min(bars[i - 1].Open, bars[i - 1].Close) - bars[i - 1].Low;
            if (wick > Math.Max(0.0001, referenceBody) * 0.5) return "WICK";
            return "BASE";
        }

        private static bool IsMgc(string s) { return (s ?? string.Empty).StartsWith("MGC", StringComparison.OrdinalIgnoreCase); }
        // A selected session date starts at 18:00 Eastern and ends on the following calendar day before the next 18:00 open.
        public static DateTime TradingSessionDate(DateTime time)
        {
            return time.TimeOfDay < new TimeSpan(18, 0, 0) ? time.Date.AddDays(-1) : time.Date;
        }
        public static bool UsesOvernightSessionDate(KeystoneArcRunConfig cfg)
        {
            string mode = cfg == null ? string.Empty : (cfg.SessionMode ?? string.Empty).ToUpperInvariant();
            if (mode == "ASIAN75") return cfg.AsianStartHhmm > cfg.AsianEndHhmm;
            return mode == "FULL_GLOBEX" || mode == "ASIA" || mode == "ALL_ELIGIBLE" || mode == "ASIAN" || (mode == "CUSTOM" && cfg.CustomStart > cfg.EndTime);
        }
        public static DateTime SessionGroupingDate(DateTime time, KeystoneArcRunConfig cfg)
        {
            if (cfg != null && string.Equals(cfg.SessionMode, "ASIAN75", StringComparison.OrdinalIgnoreCase))
            {
                int hhmm = time.Hour * 100 + time.Minute;
                bool overnight = cfg.AsianStartHhmm > cfg.AsianEndHhmm;
                return overnight && hhmm < cfg.AsianStartHhmm ? time.Date.AddDays(-1) : time.Date;
            }
            return UsesOvernightSessionDate(cfg) ? TradingSessionDate(time) : time.Date;
        }
    }
    // ---------------------------------------------------------------------------------------
    // Asian 75 parameter optimizer. Runs the Asian cycle engine above over every combination of
    // the requested parameters on the already-loaded 1-minute bars and ranks the results.
    // Overfitting guard: ranking uses only the earlier IN-SAMPLE sessions; every row also shows
    // how the same settings did on the later OUT-OF-SAMPLE sessions they were not ranked on.
    // Historical research only: costs are modeled per contract, fills are 1M-bar based.
    // ---------------------------------------------------------------------------------------
    public sealed class KeystoneArcAsianGrid
    {
        public List<string> Scopes = new List<string> { "MNQ", "MGC", "BOTH" };
        public List<string> MnqDirections = new List<string> { "LONG", "SHORT" };
        public List<string> MgcDirections = new List<string> { "LONG", "SHORT" };
        public List<string> RiskModes = new List<string> { "CASH" };
        public List<double> LegLosses = new List<double> { 50, 75, 100, 125, 150 };
        public List<int> Reversals = new List<int> { 1, 2, 3, 4, 5 };
        public List<double> Targets = new List<double> { 150, 250, 350, 500, 750 };
        public List<double> CycleStops = new List<double> { 0 };
        public List<double> InstrumentCaps = new List<double> { 0 };
        public List<double> BreakEvens = new List<double> { 0 };
        public List<int> StartTimes = new List<int> { 1800 };
        public int EndHhmm = 1555;
        // 0 = AUTO, exactly like the lab: leg loss × max reversals × selected instruments.
        public double DailyLossLimit = 0;
        // True = one start direction for both instruments (the lab's single direction selector).
        public bool LinkDirections;
        public int StartingQuantity = 1;
        public double CostPerContract = 1.00;   // round trip per contract: commission + exchange fees
        public double OutOfSampleFraction = 0.30;
        public int MinimumNights = 40;
        public double PropDrawdown = 2000;
    }

    public sealed class KeystoneArcAsianCombo
    {
        public string Scope, MnqDirection, MgcDirection, RiskMode;
        public double LegLoss, Target, CycleStop, InstrumentCap, BreakEven, DailyLossLimit;
        public int Reversals, StartHhmm, EndHhmm, StartingQuantity;

        public string Label()
        {
            string dir = Scope == "BOTH" ? MnqDirection.Substring(0, 1) + "/" + MgcDirection.Substring(0, 1) : (Scope == "MNQ" ? MnqDirection : MgcDirection);
            return Scope + " " + dir + " " + StartHhmm.ToString("0000") + (RiskMode == "PRICE" ? " FIXED STOP x1 $" : " FIXED $ leg $") + LegLoss.ToString("0") + " rev " + Reversals + " tgt $" + Target.ToString("0")
                + (CycleStop > 0 ? " cyc $" + CycleStop.ToString("0") : "") + (InstrumentCap > 0 ? " cap $" + InstrumentCap.ToString("0") : "") + (BreakEven > 0 ? " BE $" + BreakEven.ToString("0") : "");
        }

        // Writes these Asian settings onto a configuration (a clone of the lab's, or a new one).
        public KeystoneArcRunConfig Apply(KeystoneArcRunConfig cfg)
        {
            cfg.StrategyCode = "ASIAN75"; cfg.SessionMode = "ASIAN75"; cfg.Scope = Scope; cfg.SetupMinutes = 1;
            cfg.AsianStartHhmm = StartHhmm; cfg.AsianEndHhmm = EndHhmm; cfg.CustomStart = StartHhmm; cfg.EndTime = EndHhmm;
            cfg.AsianMnqInitialDirection = MnqDirection; cfg.AsianMgcInitialDirection = MgcDirection;
            cfg.AsianRiskMode = RiskMode; cfg.AsianReversalLossDollars = LegLoss;
            // PRICE mode: the leg-loss value is the x1 leg loss, converted to each instrument's price move.
            cfg.AsianMnqReversalPriceMove = LegLoss / 2.0; cfg.AsianMgcReversalPriceMove = LegLoss / 10.0;
            cfg.AsianCycleTargetDollars = Target; cfg.AsianCombinedStopLossDollars = CycleStop;
            cfg.AsianDailyLossLimitDollars = DailyLossLimit > 0 ? DailyLossLimit : Math.Max(1, KeystoneArcEngine.AsianAutoDailyLossLimit(RiskMode, Scope, LegLoss, cfg.AsianMnqReversalPriceMove, cfg.AsianMgcReversalPriceMove, Reversals));
            cfg.AsianInstrumentStopLossDollars = InstrumentCap; cfg.AsianMnqInstrumentStopLossDollars = InstrumentCap; cfg.AsianMgcInstrumentStopLossDollars = InstrumentCap;
            cfg.AsianBreakEvenTriggerDollars = BreakEven; cfg.AsianStartingQuantity = StartingQuantity;
            cfg.AsianMaxReversalsPerInstrument = Reversals; cfg.AsianMnqMaxReversals = Reversals; cfg.AsianMgcMaxReversals = Reversals;
            cfg.AsianMaxTotalLegsPerInstrument = Reversals + 1;
            return cfg;
        }
    }

    public sealed class KeystoneArcAsianStats
    {
        public int Nights, WinNights, TargetNights, Legs, Contracts, MaxLosingStreak;
        public double Net, Gross, MaxDrawdown, WorstNight, BestNight, GrossWin, GrossLoss;
        public double WinRate { get { return Nights == 0 ? 0 : 100.0 * WinNights / Nights; } }
        public double TargetRate { get { return Nights == 0 ? 0 : 100.0 * TargetNights / Nights; } }
        public double ProfitFactor { get { return GrossLoss <= 0 ? (GrossWin > 0 ? 99 : 0) : GrossWin / GrossLoss; } }
        public double NetPerNight { get { return Nights == 0 ? 0 : Net / Nights; } }
        // Net profit per $1 of worst peak-to-trough drawdown: rewards a steady equity curve.
        public double ReturnToDrawdown { get { return MaxDrawdown <= 0 ? (Net > 0 ? 99 : 0) : Net / MaxDrawdown; } }
    }

    public sealed class KeystoneArcAsianNight
    {
        public DateTime SessionDate;
        public double Gross, Net;
        public int Legs, Contracts;
        public bool TargetReached;
    }

    public sealed class KeystoneArcAsianResult
    {
        public KeystoneArcAsianCombo Combo;
        public KeystoneArcAsianStats InSample, OutOfSample, All;
        public List<KeystoneArcAsianNight> Nights;
        // A real edge should hold up calendar year after calendar year, not in one lucky stretch.
        public int Years, ProfitableYears;
        public double WorstYear;
    }

    public sealed class KeystoneArcAsianOptimization
    {
        public List<KeystoneArcAsianResult> Ranked = new List<KeystoneArcAsianResult>();
        public int Combinations;
        public DateTime FirstSession, OutOfSampleStart, LastSession;
        public KeystoneArcAsianGrid Grid;
        public bool Cancelled;
    }

    public static class KeystoneArcAsianOptimizer
    {
        public static List<KeystoneArcAsianCombo> BuildCombos(KeystoneArcAsianGrid g, bool hasMnq, bool hasMgc)
        {
            var combos = new List<KeystoneArcAsianCombo>();
            foreach (string scope in g.Scopes.Distinct())
            {
                if ((scope == "MNQ" || scope == "BOTH") && !hasMnq) continue;
                if ((scope == "MGC" || scope == "BOTH") && !hasMgc) continue;
                foreach (string mnqDir in scope == "MGC" ? new List<string> { "LONG" } : g.MnqDirections.Distinct().ToList())
                foreach (string mgcDir in scope == "MNQ" ? new List<string> { "LONG" } : (g.LinkDirections && scope == "BOTH" ? new List<string> { mnqDir } : g.MgcDirections.Distinct().ToList()))
                foreach (string mode in g.RiskModes.Distinct())
                foreach (double loss in g.LegLosses.Distinct())
                foreach (int rev in g.Reversals.Distinct())
                foreach (double target in g.Targets.Distinct())
                foreach (double cycle in g.CycleStops.Distinct())
                foreach (double cap in g.InstrumentCaps.Distinct())
                foreach (double be in g.BreakEvens.Distinct())
                foreach (int start in g.StartTimes.Distinct())
                    combos.Add(new KeystoneArcAsianCombo { Scope = scope, MnqDirection = mnqDir, MgcDirection = mgcDir, RiskMode = mode, LegLoss = loss, Reversals = rev, Target = target, CycleStop = cycle, InstrumentCap = cap, BreakEven = be, StartHhmm = start, EndHhmm = g.EndHhmm, DailyLossLimit = g.DailyLossLimit, StartingQuantity = g.StartingQuantity });
            }
            return combos;
        }

        // progress(done, total) is called from worker threads. cancelled() is polled.
        public static KeystoneArcAsianOptimization Run(List<KeystoneArcBar> oneMinute, KeystoneArcAsianGrid g, Action<int, int> progress, Func<bool> cancelled)
        {
            var result = new KeystoneArcAsianOptimization { Grid = g };
            List<KeystoneArcBar> bars = (oneMinute ?? new List<KeystoneArcBar>()).Where(x => x != null).ToList();
            bool hasMnq = bars.Any(x => !(x.Symbol ?? string.Empty).StartsWith("MGC", StringComparison.OrdinalIgnoreCase));
            bool hasMgc = bars.Any(x => (x.Symbol ?? string.Empty).StartsWith("MGC", StringComparison.OrdinalIgnoreCase));
            List<KeystoneArcAsianCombo> combos = BuildCombos(g, hasMnq, hasMgc);
            result.Combinations = combos.Count;
            if (combos.Count == 0 || bars.Count == 0) return result;

            var probe = new KeystoneArcRunConfig { SessionMode = "ASIAN75", AsianStartHhmm = 1800, AsianEndHhmm = g.EndHhmm };
            List<DateTime> dates = bars.Select(x => KeystoneArcEngine.SessionGroupingDate(x.Time, probe)).Distinct().OrderBy(x => x).ToList();
            result.FirstSession = dates.First(); result.LastSession = dates.Last();
            int split = Math.Max(0, Math.Min(dates.Count - 1, (int)Math.Floor(dates.Count * (1 - Math.Max(0, Math.Min(0.9, g.OutOfSampleFraction))))));
            result.OutOfSampleStart = g.OutOfSampleFraction <= 0 ? DateTime.MaxValue : dates[split];

            // Prepare each (scope, start, end) session layout once; every combo reuses it.
            var prepared = new Dictionary<string, List<KeystoneArcEngine.Asian75Session>>();
            foreach (var key in combos.Select(c => new { c.Scope, c.StartHhmm, c.EndHhmm }).Distinct())
            {
                if (cancelled != null && cancelled()) { result.Cancelled = true; return result; }
                var cfg = new KeystoneArcAsianCombo { Scope = key.Scope, StartHhmm = key.StartHhmm, EndHhmm = key.EndHhmm, MnqDirection = "LONG", MgcDirection = "LONG", RiskMode = "CASH" }.Apply(new KeystoneArcRunConfig());
                prepared[key.Scope + "|" + key.StartHhmm + "|" + key.EndHhmm] = KeystoneArcEngine.PrepareAsian75Sessions(bars, cfg);
            }

            var results = new KeystoneArcAsianResult[combos.Count];
            int done = 0;
            var options = new System.Threading.Tasks.ParallelOptions { MaxDegreeOfParallelism = Math.Max(1, Environment.ProcessorCount - 1) };
            System.Threading.Tasks.Parallel.For(0, combos.Count, options, (i, state) =>
            {
                if (cancelled != null && cancelled()) { state.Stop(); return; }
                KeystoneArcAsianCombo c = combos[i];
                KeystoneArcRunConfig cfg = c.Apply(new KeystoneArcRunConfig());
                List<KeystoneArcEvent> events = KeystoneArcEngine.SimulateAsian75Sessions(prepared[c.Scope + "|" + c.StartHhmm + "|" + c.EndHhmm], cfg);
                results[i] = Score(c, events, g, result.OutOfSampleStart);
                int k = System.Threading.Interlocked.Increment(ref done);
                if (progress != null) progress(k, combos.Count);
            });
            result.Cancelled = cancelled != null && cancelled();
            result.Ranked = results.Where(r => r != null && r.InSample.Nights >= g.MinimumNights)
                .OrderByDescending(r => r.InSample.Net > 0 ? r.InSample.ReturnToDrawdown : r.InSample.Net / 1e6)
                .ThenByDescending(r => r.InSample.Net).ToList();
            return result;
        }

        private static KeystoneArcAsianResult Score(KeystoneArcAsianCombo c, List<KeystoneArcEvent> events, KeystoneArcAsianGrid g, DateTime oosStart)
        {
            // Events carry the cycle's opening clock time as ReferenceTime; its date names the session.
            List<KeystoneArcAsianNight> nights = events.GroupBy(e => e.ReferenceTime.Date).OrderBy(x => x.Key).Select(x =>
            {
                int contracts = (int)Math.Round(x.Sum(e => e.Quantity)); double gross = x.Sum(e => e.GrossPnl);
                return new KeystoneArcAsianNight { SessionDate = x.Key, Gross = gross, Net = gross - contracts * g.CostPerContract, Legs = x.Count(), Contracts = contracts, TargetReached = x.Any(e => e.Outcome == "WIN") };
            }).ToList();
            List<double> years = nights.GroupBy(n => n.SessionDate.Year).Select(y => y.Sum(n => n.Net)).ToList();
            return new KeystoneArcAsianResult
            {
                Combo = c, Nights = nights,
                InSample = Stats(nights.Where(n => n.SessionDate < oosStart)),
                OutOfSample = Stats(nights.Where(n => n.SessionDate >= oosStart)),
                All = Stats(nights),
                Years = years.Count, ProfitableYears = years.Count(y => y > 0), WorstYear = years.Count == 0 ? 0 : years.Min()
            };
        }

        public static KeystoneArcAsianStats Stats(IEnumerable<KeystoneArcAsianNight> nights)
        {
            var s = new KeystoneArcAsianStats(); double equity = 0, peak = 0; int streak = 0;
            foreach (KeystoneArcAsianNight n in nights)
            {
                s.Nights++; s.Legs += n.Legs; s.Contracts += n.Contracts; s.Gross += n.Gross; s.Net += n.Net;
                if (n.Net > 0) { s.WinNights++; s.GrossWin += n.Net; streak = 0; } else { s.GrossLoss -= n.Net; streak++; s.MaxLosingStreak = Math.Max(s.MaxLosingStreak, streak); }
                if (n.TargetReached) s.TargetNights++;
                s.WorstNight = s.Nights == 1 ? n.Net : Math.Min(s.WorstNight, n.Net); s.BestNight = Math.Max(s.BestNight, n.Net);
                equity += n.Net; peak = Math.Max(peak, equity); s.MaxDrawdown = Math.Max(s.MaxDrawdown, peak - equity);
            }
            return s;
        }

        // The ranked row for a given setting (e.g. the lab's current configuration), or null.
        public static KeystoneArcAsianResult FindMatch(KeystoneArcAsianOptimization o, KeystoneArcAsianCombo m)
        {
            if (o == null || m == null) return null;
            return o.Ranked.FirstOrDefault(r => r.Combo.Scope == m.Scope && r.Combo.LegLoss == m.LegLoss && r.Combo.Target == m.Target && r.Combo.Reversals == m.Reversals && r.Combo.RiskMode == m.RiskMode
                && r.Combo.CycleStop == m.CycleStop && r.Combo.InstrumentCap == m.InstrumentCap && r.Combo.BreakEven == m.BreakEven && r.Combo.StartHhmm == m.StartHhmm
                && (m.Scope == "MGC" || r.Combo.MnqDirection == m.MnqDirection) && (m.Scope == "MNQ" || r.Combo.MgcDirection == m.MgcDirection));
        }

        public static string FormatTable(KeystoneArcAsianOptimization o, int top, KeystoneArcAsianCombo current)
        {
            var sb = new StringBuilder();
            KeystoneArcAsianGrid g = o.Grid ?? new KeystoneArcAsianGrid();
            sb.AppendLine("ASIAN 75 OPTIMIZER • " + o.Combinations.ToString("N0") + " combinations • " + o.Ranked.Count.ToString("N0") + " with at least " + g.MinimumNights + " in-sample nights" + (o.Cancelled ? " • CANCELLED (partial)" : ""));
            sb.AppendLine("IN-SAMPLE " + o.FirstSession.ToString("yyyy-MM-dd") + " → " + (o.OutOfSampleStart == DateTime.MaxValue ? o.LastSession : o.OutOfSampleStart.AddDays(-1)).ToString("yyyy-MM-dd")
                + "   OUT-OF-SAMPLE " + (o.OutOfSampleStart == DateTime.MaxValue ? "none" : o.OutOfSampleStart.ToString("yyyy-MM-dd") + " → " + o.LastSession.ToString("yyyy-MM-dd")));
            sb.AppendLine("Net = after $" + g.CostPerContract.ToString("0.00") + " round trip per contract. Ranked by IN-SAMPLE net ÷ max drawdown. OOS columns were NOT used for ranking: settings that stay good there are the trustworthy ones.");
            sb.AppendLine();
            sb.AppendLine(string.Format("{0,-4}{1,-50}{2,9}{3,6}{4,9}{5,6} |{6,9}{7,6}{8,9}{9,6} |{10,6}{11,10}{12,5}", "#", "SETTINGS", "IS NET", "WIN", "MAX DD", "R/DD", "OOS NET", "WIN", "MAX DD", "R/DD", "YRS+", "WORST YR", "PROP"));
            for (int i = 0; i < Math.Min(top, o.Ranked.Count); i++) sb.AppendLine(Line(i + 1, o.Ranked[i], g));
            KeystoneArcAsianResult d = FindMatch(o, current);
            if (d != null)
            {
                sb.AppendLine();
                sb.AppendLine("YOUR CURRENT SETTINGS • rank " + (o.Ranked.IndexOf(d) + 1) + " of " + o.Ranked.Count);
                sb.AppendLine(Line(o.Ranked.IndexOf(d) + 1, d, g));
            }
            sb.AppendLine();
            sb.AppendLine("WIN = % of nights with net profit. R/DD = net ÷ max drawdown. YRS+ = profitable calendar years / years tested. PROP = whole-history max drawdown within $" + g.PropDrawdown.ToString("N0") + ".");
            return sb.ToString();
        }

        private static string Line(int rank, KeystoneArcAsianResult r, KeystoneArcAsianGrid g)
        {
            return string.Format(CultureInfo.InvariantCulture, "{0,-4}{1,-50}{2,9:N0}{3,5:0}%{4,9:N0}{5,6:0.0} |{6,9:N0}{7,5:0}%{8,9:N0}{9,6:0.0} |{10,6}{11,10:N0}{12,5}",
                rank, r.Combo.Label(), r.InSample.Net, r.InSample.WinRate, r.InSample.MaxDrawdown, r.InSample.ReturnToDrawdown,
                r.OutOfSample.Net, r.OutOfSample.WinRate, r.OutOfSample.MaxDrawdown, r.OutOfSample.ReturnToDrawdown,
                r.ProfitableYears + "/" + r.Years, r.WorstYear, r.All.MaxDrawdown <= g.PropDrawdown ? "ok" : "DD!");
        }

        public static string ToCsv(KeystoneArcAsianOptimization o)
        {
            KeystoneArcAsianGrid g = o.Grid ?? new KeystoneArcAsianGrid();
            var sb = new StringBuilder("rank,scope,mnq_dir,mgc_dir,start,end,risk_mode,leg_loss,reversals,target,cycle_stop,instrument_cap,breakeven,daily_loss_limit,cost_per_contract,"
                + "is_nights,is_net,is_win_pct,is_target_pct,is_max_dd,is_return_dd,is_profit_factor,is_worst_night,is_max_losing_streak,"
                + "oos_nights,oos_net,oos_win_pct,oos_target_pct,oos_max_dd,oos_return_dd,oos_profit_factor,oos_worst_night,"
                + "all_nights,all_net,all_net_per_night,all_max_dd,all_contracts,profitable_years,years,worst_year,within_prop_dd\n");
            Func<double, string> f = x => x.ToString("0.##", CultureInfo.InvariantCulture);
            for (int i = 0; i < o.Ranked.Count; i++)
            {
                KeystoneArcAsianResult r = o.Ranked[i]; KeystoneArcAsianCombo c = r.Combo;
                sb.AppendLine(string.Join(",", new[] { (i + 1).ToString(), c.Scope, c.MnqDirection, c.MgcDirection, c.StartHhmm.ToString("0000"), c.EndHhmm.ToString("0000"), c.RiskMode, f(c.LegLoss), c.Reversals.ToString(), f(c.Target), f(c.CycleStop), f(c.InstrumentCap), f(c.BreakEven), f(c.DailyLossLimit), f(g.CostPerContract),
                    r.InSample.Nights.ToString(), f(r.InSample.Net), f(r.InSample.WinRate), f(r.InSample.TargetRate), f(r.InSample.MaxDrawdown), f(r.InSample.ReturnToDrawdown), f(r.InSample.ProfitFactor), f(r.InSample.WorstNight), r.InSample.MaxLosingStreak.ToString(),
                    r.OutOfSample.Nights.ToString(), f(r.OutOfSample.Net), f(r.OutOfSample.WinRate), f(r.OutOfSample.TargetRate), f(r.OutOfSample.MaxDrawdown), f(r.OutOfSample.ReturnToDrawdown), f(r.OutOfSample.ProfitFactor), f(r.OutOfSample.WorstNight),
                    r.All.Nights.ToString(), f(r.All.Net), f(r.All.NetPerNight), f(r.All.MaxDrawdown), r.All.Contracts.ToString(), r.ProfitableYears.ToString(), r.Years.ToString(), f(r.WorstYear), r.All.MaxDrawdown <= g.PropDrawdown ? "1" : "0" }));
            }
            return sb.ToString();
        }

        // One line per Asian night: every stopped leg is its own LOSS row in the ledger, so the
        // ledger alone cannot show whether a night made money. This groups the legs by session.
        public static string NightlySummary(List<KeystoneArcEvent> events, double costPerContract)
        {
            var nights = (events ?? new List<KeystoneArcEvent>()).Where(e => e != null && e.SetupClass == "ASIA75").GroupBy(e => e.ReferenceTime.Date).OrderBy(g => g.Key).ToList();
            if (nights.Count == 0) return string.Empty;
            var sb = new StringBuilder();
            sb.AppendLine("NIGHT-BY-NIGHT CYCLE SUMMARY • session date = the evening the cycle starts • P/L after $" + costPerContract.ToString("0.00", CultureInfo.InvariantCulture) + " round trip per contract");
            sb.AppendLine(string.Format(CultureInfo.InvariantCulture, "{0,-12}{1,-24}{2,-24}{3,-26}{4,10}{5,12}", "SESSION", "MNQ LEGS", "MGC LEGS", "HOW THE NIGHT ENDED", "NIGHT P/L", "RUNNING"));
            double running = 0; int wins = 0;
            foreach (var night in nights)
            {
                List<KeystoneArcEvent> legs = night.OrderBy(e => e.ExitTime).ThenBy(e => e.Symbol).ToList();
                double net = legs.Sum(e => e.GrossPnl) - legs.Sum(e => e.Quantity) * costPerContract;
                running += net; if (net > 0) wins++;
                Func<string, string> legText = symbol =>
                {
                    List<KeystoneArcEvent> mine = legs.Where(e => e.Symbol == symbol).OrderBy(e => e.EntryTime).ToList();
                    if (mine.Count == 0) return "-";
                    return mine.Count + " (" + string.Join(" ", mine.Select(e => (e.Direction == "LONG" ? "L" : "S") + "x" + e.Quantity.ToString("0", CultureInfo.InvariantCulture))) + ")";
                };
                string ended = NightEnding(legs);
                sb.AppendLine(string.Format(CultureInfo.InvariantCulture, "{0,-12}{1,-24}{2,-24}{3,-26}{4,10:N0}{5,12:N0}", night.Key.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture), legText("MNQ"), legText("MGC"), ended, net, running));
            }
            sb.AppendLine("NIGHTS " + nights.Count + " • PROFITABLE " + wins + " (" + (100.0 * wins / nights.Count).ToString("0", CultureInfo.InvariantCulture) + "%) • NET " + running.ToString("N0", CultureInfo.InvariantCulture) + " • AVERAGE / NIGHT " + (running / nights.Count).ToString("N0", CultureInfo.InvariantCulture));
            return sb.ToString();
        }

        // How one Asian night ended, from its legs: the closing (non-reversal) event decides.
        public static string NightEnding(IEnumerable<KeystoneArcEvent> nightLegs)
        {
            KeystoneArcEvent closing = (nightLegs ?? Enumerable.Empty<KeystoneArcEvent>()).OrderBy(e => e.ExitTime).LastOrDefault(e => !(e.ReviewNote ?? string.Empty).StartsWith("REVERSAL LOSS", StringComparison.OrdinalIgnoreCase));
            if (closing == null) return "ALL LEGS STOPPED OUT";
            string at = " " + closing.ExitTime.ToString("HH:mm", CultureInfo.InvariantCulture);
            if (closing.Outcome == "WIN") return "TARGET" + at;
            if (closing.Outcome == "SESSION EXIT") return "SESSION END" + at;
            if (closing.Outcome == "BREAKEVEN GUARD") return "BREAKEVEN GUARD" + at;
            return "LOSS LIMIT" + at;
        }

        public static string NightsCsv(KeystoneArcAsianResult r)
        {
            var sb = new StringBuilder("# " + r.Combo.Label() + "\nsession_date,legs,contracts,gross,net_after_costs,cumulative_net,target_reached\n"); double cum = 0;
            foreach (KeystoneArcAsianNight n in r.Nights)
            {
                cum += n.Net;
                sb.AppendLine(n.SessionDate.ToString("yyyy-MM-dd") + "," + n.Legs + "," + n.Contracts + "," + n.Gross.ToString("0.##", CultureInfo.InvariantCulture) + "," + n.Net.ToString("0.##", CultureInfo.InvariantCulture) + "," + cum.ToString("0.##", CultureInfo.InvariantCulture) + "," + (n.TargetReached ? "1" : "0"));
            }
            return sb.ToString();
        }
    }
    // ---------------------------------------------------------------------------------------
    // Asian night replay: turns one night's legs (both instruments) into ordered steps — the
    // cycle opening, every stop + reversal, the closing — with the state of BOTH instruments and
    // the combined cycle P/L at each step. Used by the evidence chart's PREV / NEXT / PLAY replay.
    // ---------------------------------------------------------------------------------------
    public sealed class KeystoneArcReplayStep
    {
        public DateTime Time;
        public string Headline = string.Empty;
        public string Detail = string.Empty;
        public double CombinedPnl;
        public double WorstCombined;
        public List<KeystoneArcEvent> Entries = new List<KeystoneArcEvent>();
        public List<KeystoneArcEvent> Exits = new List<KeystoneArcEvent>();
    }

    public static class KeystoneArcAsianReplay
    {
        static double PointValue(string symbol) { return (symbol ?? string.Empty).StartsWith("MGC", StringComparison.OrdinalIgnoreCase) ? 10.0 : 2.0; }
        static string Money(double v) { return (v >= 0 ? "+$" : "−$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture); }
        static string Price(string symbol, double p) { return p.ToString((symbol ?? string.Empty).StartsWith("MGC", StringComparison.OrdinalIgnoreCase) ? "0.0" : "0.00", CultureInfo.InvariantCulture); }
        static bool IsStop(KeystoneArcEvent e) { return (e.ReviewNote ?? string.Empty).StartsWith("REVERSAL LOSS", StringComparison.OrdinalIgnoreCase); }
        static bool IsLastLeg(KeystoneArcEvent e) { string n = e.ReviewNote ?? string.Empty; return n.IndexOf("MAX REVERSALS", StringComparison.OrdinalIgnoreCase) >= 0 || n.IndexOf("INSTRUMENT LOSS CAP", StringComparison.OrdinalIgnoreCase) >= 0; }

        static string Closing(KeystoneArcEvent e)
        {
            if (e.Outcome == "WIN") return "CYCLE TARGET REACHED";
            if (e.Outcome == "SESSION EXIT") return "SESSION END";
            if (e.Outcome == "BREAKEVEN GUARD") return "BREAKEVEN GUARD";
            return (e.ReviewNote ?? string.Empty).IndexOf("COMBINED CYCLE STOP", StringComparison.OrdinalIgnoreCase) >= 0 ? "COMBINED CYCLE STOP" : "DAILY LOSS LIMIT";
        }

        // closeAt(symbol, time): latest 1-minute close at or before time (null if unknown); used to
        // mark open legs. target / lossLimit are the cycle's combined target and loss limit.
        public static List<KeystoneArcReplayStep> Build(List<KeystoneArcEvent> nightLegs, Func<string, DateTime, double?> closeAt, double target, double lossLimit)
        {
            var steps = new List<KeystoneArcReplayStep>();
            List<KeystoneArcEvent> legs = (nightLegs ?? new List<KeystoneArcEvent>()).Where(e => e != null && e.SetupClass == "ASIA75").OrderBy(e => e.EntryTime).ThenBy(e => e.Symbol).ToList();
            if (legs.Count == 0) return steps;
            string[] symbols = legs.Select(e => e.Symbol).Distinct().OrderBy(x => x).ToArray();
            var times = legs.Select(e => e.EntryTime).Concat(legs.Select(e => e.ExitTime)).Where(t => t != DateTime.MinValue).Distinct().OrderBy(t => t).ToList();
            double worst = 0;
            foreach (DateTime t in times)
            {
                var step = new KeystoneArcReplayStep { Time = t };
                step.Exits = legs.Where(e => e.ExitTime == t).ToList();
                step.Entries = legs.Where(e => e.EntryTime == t).ToList();
                var lines = new List<string>();
                // what happened — entries first: a leg enters at the minute's open, stops happen during it
                foreach (KeystoneArcEvent e in step.Entries.OrderBy(x => x.Symbol))
                    lines.Add(e.Symbol + "  L" + e.AsianLegNumber + " " + (e.AsianLegNumber <= 1 ? "OPENED " : "REVERSED → ") + e.Direction + " x" + e.Quantity.ToString("0", CultureInfo.InvariantCulture) + " @ " + Price(e.Symbol, e.Entry)
                        + " • stop " + Price(e.Symbol, e.Stop) + " (" + Money(-Math.Abs(e.Entry - e.Stop) * PointValue(e.Symbol) * e.Quantity) + ")");
                foreach (KeystoneArcEvent e in step.Exits.OrderBy(x => x.Symbol))
                {
                    if (IsStop(e))
                        lines.Add(e.Symbol + "  L" + e.AsianLegNumber + " " + e.Direction + " x" + e.Quantity.ToString("0", CultureInfo.InvariantCulture) + " STOPPED " + Money(e.GrossPnl) + " @ " + Price(e.Symbol, e.ExitPrice)
                            + (IsLastLeg(e) ? "  → last leg, " + e.Symbol + " done for the night" : "  → reverses " + (e.Direction == "LONG" ? "SHORT" : "LONG") + " x" + (e.Quantity + 1).ToString("0", CultureInfo.InvariantCulture) + " next minute"));
                    else
                        lines.Add(e.Symbol + "  L" + e.AsianLegNumber + " " + e.Direction + " x" + e.Quantity.ToString("0", CultureInfo.InvariantCulture) + " CLOSED " + Money(e.GrossPnl) + " @ " + Price(e.Symbol, e.ExitPrice) + "  (" + Closing(e) + ")");
                }
                KeystoneArcEvent closing = step.Exits.FirstOrDefault(e => !IsStop(e));
                string stopText = step.Exits.Any(IsStop) ? "STOP HIT" + (step.Exits.Any(IsLastLeg) ? " • LAST LEG" : " • REVERSAL NEXT MINUTE") : string.Empty;
                string entryText = step.Entries.Any(e => e.AsianLegNumber <= 1) ? "CYCLE OPENED" : (step.Entries.Count > 0 ? "REVERSAL ENTERED" : string.Empty);
                step.Headline = closing != null ? (entryText.Length > 0 ? entryText + " • " : string.Empty) + "NIGHT CLOSED • " + Closing(closing)
                    : string.Join(" • ", new[] { entryText, stopText }.Where(x => x.Length > 0));
                // state of every instrument after this step
                lines.Add("────────────────────────────────────────────────────────");
                double combined = 0;
                foreach (string symbol in symbols)
                {
                    double realized = legs.Where(e => e.Symbol == symbol && e.ExitTime <= t).Sum(e => e.GrossPnl);
                    KeystoneArcEvent open = legs.FirstOrDefault(e => e.Symbol == symbol && e.EntryTime <= t && e.ExitTime > t);
                    int done = legs.Count(e => e.Symbol == symbol && e.ExitTime <= t);
                    string state;
                    double openPnl = 0;
                    if (open != null)
                    {
                        double? mark = closeAt == null ? null : closeAt(symbol, t);
                        double now = mark ?? open.Entry;
                        openPnl = (now - open.Entry) * PointValue(symbol) * open.Quantity * (open.Direction == "LONG" ? 1 : -1);
                        state = "OPEN L" + open.AsianLegNumber + " " + open.Direction + " x" + open.Quantity.ToString("0", CultureInfo.InvariantCulture) + " @ " + Price(symbol, open.Entry) + " • now " + Price(symbol, now) + " • open " + Money(openPnl);
                    }
                    else if (legs.Any(e => e.Symbol == symbol && e.EntryTime > t)) state = "FLAT • reversal enters next minute";
                    else state = "FLAT • done for the night";
                    combined += realized + openPnl;
                    lines.Add(symbol.PadRight(4) + " " + state + " • realized " + Money(realized) + " • legs closed " + done);
                }
                // the engine's own combined value at an exit minute is authoritative (1M-close marked)
                KeystoneArcEvent recorded = step.Exits.FirstOrDefault(e => !double.IsNaN(e.AsianCyclePnlAtExit));
                if (recorded != null) combined = recorded.AsianCyclePnlAtExit;
                worst = Math.Min(worst, combined);
                if (recorded != null && !double.IsNaN(recorded.AsianCycleWorstAtExit)) worst = Math.Min(worst, recorded.AsianCycleWorstAtExit);
                step.CombinedPnl = combined; step.WorstCombined = worst;
                lines.Add("COMBINED P/L " + Money(combined) + " • WORST SO FAR " + Money(worst) + " • TARGET " + Money(target) + " • LOSS LIMIT " + Money(-Math.Abs(lossLimit)));
                step.Detail = string.Join("\n", lines);
                steps.Add(step);
            }
            return steps;
        }
    }
    // Walk-forward setup grading. A setup is graded only from setups that had already finished
    // (exit before its entry): no look-ahead. Each feature bucket keeps the average result in R
    // (P/L ÷ money at risk); a setup's score is the average of its buckets' results, shrunk toward
    // the overall average when a bucket has few examples. Tier A = top 25% of scores so far,
    // B = next 35%, C = the rest, N = fewer than MinHistory finished setups.
    public sealed class KeystoneArcQualityLearner
    {
        public int MinHistory = 30; public double Shrink = 10;
        readonly Dictionary<string, double[]> buckets = new Dictionary<string, double[]>(StringComparer.Ordinal);
        readonly List<KeystoneArcEvent> pending = new List<KeystoneArcEvent>();
        readonly List<double> scores = new List<double>();
        int count; double sum;

        static string Bin(double v, double[] edges) { int i = 0; while (i < edges.Length && v >= edges[i]) i++; return i.ToString(CultureInfo.InvariantCulture); }

        public static List<string> Features(KeystoneArcEvent e, DateTime entry)
        {
            var f = new List<string> { "H" + entry.Hour, "T" + (e.StrengthTag ?? ""), "W" + (int)entry.DayOfWeek };
            if (e.SetupClass == "FVG")
            {
                double atr = e.FeatureAtr > 0 ? e.FeatureAtr : 1;
                f.Add("G" + Bin(e.FvgGap / atr, new[] { 0.5, 1.0, 2.0 }));
                f.Add("V" + Math.Min(3, Math.Max(1, e.FvgVisit)));
                f.Add("D" + Bin(e.FeatureDipPercent, new[] { 25.0, 50.0, 75.0, 100.0 }));
                f.Add("B" + Bin(e.FeatureGreenBody, new[] { 0.4, 0.7 }));
                f.Add("S" + Bin(e.StopDistance / atr, new[] { 0.5, 1.0, 2.0, 3.0 }));
            }
            else f.Add("O" + Math.Min(3, Math.Max(1, e.SessionOrder)));
            return f;
        }

        public static double ResultR(KeystoneArcEvent e, double pointValue)
        {
            double risk = Math.Abs(e.StopDistance) * pointValue * Math.Max(0.0001, e.Quantity);
            return risk > 0.0001 ? e.GrossPnl / risk : Math.Sign(e.GrossPnl);
        }

        void Absorb(DateTime upTo, Func<KeystoneArcEvent, double> pointValue)
        {
            foreach (KeystoneArcEvent done in pending.Where(x => x.ExitTime != DateTime.MinValue && x.ExitTime <= upTo).ToList())
            {
                pending.Remove(done);
                double r = ResultR(done, pointValue(done)); count++; sum += r;
                foreach (string k in Features(done, done.EntryTime))
                {
                    double[] b; if (!buckets.TryGetValue(k, out b)) { b = new double[2]; buckets[k] = b; }
                    b[0]++; b[1] += r;
                }
            }
        }

        // Grade e as of 'entry' (before its outcome is known), then call Learn(e) once resolved.
        public void Grade(KeystoneArcEvent e, DateTime entry, Func<KeystoneArcEvent, double> pointValue)
        {
            Absorb(entry, pointValue);
            if (count < MinHistory) { e.QualityTier = "N"; e.QualityScore = double.NaN; return; }
            double mean = sum / count, score = 0; var keys = Features(e, entry);
            foreach (string k in keys) { double[] b; buckets.TryGetValue(k, out b); double n = b == null ? 0 : b[0], sm = b == null ? 0 : b[1]; score += (sm + Shrink * mean) / (n + Shrink); }
            score /= keys.Count;
            int below = scores.Count(v => v < score);
            double pct = scores.Count == 0 ? 0.5 : (double)below / scores.Count;
            e.QualityScore = score; e.QualityTier = pct >= 0.75 ? "A" : (pct >= 0.40 ? "B" : "C");
            scores.Add(score);
        }

        public void Learn(KeystoneArcEvent e) { if (e != null && e.ExitTime != DateTime.MinValue && e.Outcome != "NO ENTRY DATA") pending.Add(e); }

        // Grades an already-resolved ledger in entry order (used for BH; outcomes unchanged).
        public static void GradeAll(IEnumerable<KeystoneArcEvent> events, Func<KeystoneArcEvent, double> pointValue)
        {
            foreach (var group in (events ?? Enumerable.Empty<KeystoneArcEvent>()).Where(e => e != null).GroupBy(e => e.Symbol ?? ""))
            {
                var learner = new KeystoneArcQualityLearner();
                foreach (KeystoneArcEvent e in group.OrderBy(x => x.EntryTime == DateTime.MinValue ? x.TriggerTime : x.EntryTime))
                {
                    learner.Grade(e, e.EntryTime == DateTime.MinValue ? e.TriggerTime : e.EntryTime, pointValue);
                    learner.Learn(e);
                }
            }
        }

        public static bool TierAllowed(string filter, string tier)
        {
            string f = (filter ?? "ALL").ToUpperInvariant();
            if (f == "ALL") return true;
            if (f == "DT") return tier == "DT";
            if (f == "A") return tier == "DT" || tier == "A";
            return tier == "DT" || tier == "A" || tier == "B";
        }
    }

    // Live replay state at one minute: open positions marked at that minute's close, realized
    // P/L so far and the combined total — for any strategy (Asian legs or BH / FVG trades).
    public sealed class KeystoneArcLiveLine { public string Symbol; public double Realized, Open; public int Closed; public string Position = string.Empty; }
    public sealed class KeystoneArcLiveState
    {
        public DateTime Time; public double Realized, Open, Combined;
        public List<KeystoneArcLiveLine> Lines = new List<KeystoneArcLiveLine>();
    }

    public static class KeystoneArcLive
    {
        static double PointValue(string symbol) { return (symbol ?? string.Empty).StartsWith("MGC", StringComparison.OrdinalIgnoreCase) ? 10.0 : 2.0; }
        static bool Resolved(KeystoneArcEvent e) { return e != null && e.EntryTime != DateTime.MinValue && e.Outcome != "NO ENTRY DATA" && e.Outcome != "UNVERIFIED 1M" && !(e.Outcome ?? string.Empty).StartsWith("OUTCOME BLOCKED", StringComparison.OrdinalIgnoreCase); }

        public static KeystoneArcLiveState At(IEnumerable<KeystoneArcEvent> trades, Func<string, DateTime, double?> closeAt, DateTime t)
        {
            var state = new KeystoneArcLiveState { Time = t };
            var list = (trades ?? Enumerable.Empty<KeystoneArcEvent>()).Where(Resolved).ToList();
            foreach (string symbol in list.Select(e => e.Symbol).Distinct().OrderBy(x => x))
            {
                var line = new KeystoneArcLiveLine { Symbol = symbol };
                var mine = list.Where(e => e.Symbol == symbol).ToList();
                var closed = mine.Where(e => e.ExitTime != DateTime.MinValue && e.ExitTime <= t).ToList();
                line.Realized = closed.Sum(e => e.GrossPnl); line.Closed = closed.Count;
                var open = mine.Where(e => e.EntryTime <= t && (e.ExitTime == DateTime.MinValue || e.ExitTime > t)).ToList();
                var parts = new List<string>();
                foreach (KeystoneArcEvent e in open)
                {
                    double? mark = closeAt == null ? null : closeAt(symbol, t);
                    double now = mark ?? e.Entry;
                    double pnl = (now - e.Entry) * PointValue(symbol) * Math.Max(0.0001, e.Quantity) * (string.Equals(e.Direction, "SHORT", StringComparison.OrdinalIgnoreCase) ? -1 : 1);
                    line.Open += pnl;
                    string fmt = symbol.StartsWith("MGC", StringComparison.OrdinalIgnoreCase) ? "0.0" : "0.00";
                    parts.Add((e.AsianLegNumber > 0 ? "L" + e.AsianLegNumber + " " : e.SetupClass + " ") + e.Direction + " x" + e.Quantity.ToString("0.##", CultureInfo.InvariantCulture) + " @ " + e.Entry.ToString(fmt, CultureInfo.InvariantCulture)
                        + " • now " + now.ToString(fmt, CultureInfo.InvariantCulture) + (double.IsNaN(e.Stop) || e.Stop == 0 ? "" : " • stop " + e.Stop.ToString(fmt, CultureInfo.InvariantCulture)) + (double.IsNaN(e.Target) || e.Target == 0 || e.AsianLegNumber > 0 ? "" : " • target " + e.Target.ToString(fmt, CultureInfo.InvariantCulture)));
                }
                line.Position = parts.Count == 0 ? (mine.Any(e => e.EntryTime > t) ? "FLAT • waiting" : "FLAT • done") : string.Join("  |  ", parts);
                state.Lines.Add(line);
                state.Realized += line.Realized; state.Open += line.Open;
            }
            state.Combined = state.Realized + state.Open;
            return state;
        }

        // Lowest combined value reached at any 1-minute close from the first entry up to t.
        public static double WorstUntil(IEnumerable<KeystoneArcEvent> trades, Func<string, DateTime, double?> closeAt, IEnumerable<DateTime> minuteCloses, DateTime t)
        {
            var list = (trades ?? Enumerable.Empty<KeystoneArcEvent>()).Where(Resolved).ToList();
            if (list.Count == 0) return 0;
            DateTime first = list.Min(e => e.EntryTime);
            double worst = 0;
            foreach (DateTime m in (minuteCloses ?? Enumerable.Empty<DateTime>()).Where(m => m >= first && m <= t)) worst = Math.Min(worst, At(list, closeAt, m).Combined);
            return worst;
        }

        // Event steps for setup strategies (BH / FVG): one step per entry or exit minute.
        public static List<KeystoneArcReplayStep> TradeSteps(IEnumerable<KeystoneArcEvent> trades)
        {
            var steps = new List<KeystoneArcReplayStep>();
            var list = (trades ?? Enumerable.Empty<KeystoneArcEvent>()).Where(Resolved).OrderBy(e => e.EntryTime).ToList();
            foreach (DateTime t in list.Select(e => e.EntryTime).Concat(list.Where(e => e.ExitTime != DateTime.MinValue).Select(e => e.ExitTime)).Distinct().OrderBy(x => x))
            {
                var step = new KeystoneArcReplayStep { Time = t, Entries = list.Where(e => e.EntryTime == t).ToList(), Exits = list.Where(e => e.ExitTime == t).ToList() };
                var words = new List<string>();
                foreach (var e in step.Entries) words.Add(e.Symbol + " " + e.SetupClass + " ENTRY " + e.Direction + " @ " + e.Entry.ToString("0.##", CultureInfo.InvariantCulture));
                foreach (var e in step.Exits) words.Add(e.Symbol + " " + e.SetupClass + " " + (e.Outcome == "WIN" ? "TARGET" : (e.Outcome ?? "").StartsWith("LOSS") ? "STOP" : "EXIT") + " " + (e.GrossPnl >= 0 ? "+$" : "−$") + Math.Abs(e.GrossPnl).ToString("N0", CultureInfo.InvariantCulture));
                step.Headline = string.Join(" • ", words);
                steps.Add(step);
            }
            return steps;
        }
    }

    // ---------------------------------------------------------------------------------------
    // Strategy-only day scoreboard (no accounts): one row per session with setups / legs, wins,
    // losses, P/L, how an Asian night ended; plus totals, streaks and a month-by-month table.
    // Same for every strategy; Asian adds per-instrument legs and the night ending.
    // ---------------------------------------------------------------------------------------
    public sealed class KeystoneArcDayScore
    {
        public DateTime Day;
        public int Setups, Wins, Losses, Exits;
        public double Pnl;
        public string Detail = string.Empty;   // Asian: legs per instrument + ending; BH: per instrument counts
    }

    public static class KeystoneArcScoreboard
    {
        static string Money(double v) { return (v >= 0 ? "+$" : "−$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture); }

        public static List<KeystoneArcDayScore> Days(IEnumerable<KeystoneArcEvent> source, KeystoneArcRunConfig cfg)
        {
            bool asian = cfg != null && string.Equals(cfg.StrategyCode, "ASIAN75", StringComparison.OrdinalIgnoreCase);
            var rows = new List<KeystoneArcDayScore>();
            var list = (source ?? Enumerable.Empty<KeystoneArcEvent>()).Where(e => e != null && e.Outcome != "UNVERIFIED 1M").ToList();
            foreach (var g in list.GroupBy(e => asian ? e.ReferenceTime.Date : KeystoneArcEngine.SessionGroupingDate(e.TriggerTime, cfg).Date).OrderBy(g => g.Key))
            {
                var legs = g.ToList();
                var row = new KeystoneArcDayScore { Day = g.Key, Setups = legs.Count, Pnl = legs.Sum(e => e.GrossPnl),
                    Wins = legs.Count(e => e.Outcome == "WIN"), Losses = legs.Count(e => (e.Outcome ?? string.Empty).StartsWith("LOSS", StringComparison.OrdinalIgnoreCase)), Exits = legs.Count(e => e.Outcome == "SESSION EXIT") };
                if (asian)
                {
                    row.Detail = string.Join(" • ", legs.GroupBy(e => e.Symbol).OrderBy(x => x.Key).Select(x => x.Key + " " + x.Count() + " leg" + (x.Count() == 1 ? "" : "s") + " " + Money(x.Sum(e => e.GrossPnl))))
                        + " • " + KeystoneArcAsianOptimizer.NightEnding(legs);
                }
                else row.Detail = string.Join(" • ", legs.GroupBy(e => e.Symbol).OrderBy(x => x.Key).Select(x => x.Key + " " + x.Count() + " setup" + (x.Count() == 1 ? "" : "s") + " " + x.Count(e => e.Outcome == "WIN") + "W/" + x.Count(e => (e.Outcome ?? "").StartsWith("LOSS")) + "L " + Money(x.Sum(e => e.GrossPnl))));
                rows.Add(row);
            }
            return rows;
        }

        public static string DayLine(KeystoneArcDayScore d, bool asian)
        {
            return d.Day.ToString("yyyy-MM-dd ddd", CultureInfo.InvariantCulture) + " • " + (d.Pnl > 0 ? "WIN DAY " : (d.Pnl < 0 ? "LOSS DAY " : "FLAT DAY ")) + Money(d.Pnl)
                + " • " + d.Setups + (asian ? " legs" : " setups") + " (" + d.Wins + "W / " + d.Losses + "L" + (d.Exits > 0 ? " / " + d.Exits + " exit" : "") + ") • " + d.Detail;
        }

        // Full strategy-only report: totals, streaks, month-by-month, then every day.
        public static string Report(List<KeystoneArcDayScore> days, KeystoneArcRunConfig cfg)
        {
            bool asian = cfg != null && string.Equals(cfg.StrategyCode, "ASIAN75", StringComparison.OrdinalIgnoreCase);
            var sb = new StringBuilder();
            if (days == null || days.Count == 0) return "SETUPS ONLY • no resolved setups loaded.";
            int winDays = days.Count(d => d.Pnl > 0), lossDays = days.Count(d => d.Pnl < 0);
            double total = days.Sum(d => d.Pnl), equity = 0, peak = 0, maxDd = 0;
            int streak = 0, worstStreak = 0; double streakPnl = 0, worstStreakPnl = 0;
            foreach (var d in days)
            {
                equity += d.Pnl; peak = Math.Max(peak, equity); maxDd = Math.Max(maxDd, peak - equity);
                if (d.Pnl < 0) { streak++; streakPnl += d.Pnl; if (streak > worstStreak || (streak == worstStreak && streakPnl < worstStreakPnl)) { worstStreak = streak; worstStreakPnl = streakPnl; } }
                else { streak = 0; streakPnl = 0; }
            }
            var best = days.OrderByDescending(d => d.Pnl).First(); var worst = days.OrderBy(d => d.Pnl).First();
            sb.AppendLine("SETUPS ONLY • STRATEGY RESULT WITHOUT ACCOUNTS • " + days.First().Day.ToString("yyyy-MM-dd") + " → " + days.Last().Day.ToString("yyyy-MM-dd") + " • before commissions");
            sb.AppendLine("DAYS " + days.Count + " • WIN DAYS " + winDays + " (" + (100.0 * winDays / days.Count).ToString("0", CultureInfo.InvariantCulture) + "%) • LOSS DAYS " + lossDays + " • TOTAL " + Money(total) + " • AVG / DAY " + Money(total / days.Count));
            sb.AppendLine("BEST DAY " + best.Day.ToString("yyyy-MM-dd") + " " + Money(best.Pnl) + " • WORST DAY " + worst.Day.ToString("yyyy-MM-dd") + " " + Money(worst.Pnl) + " • MAX DRAWDOWN " + Money(-maxDd) + " • LONGEST LOSING STREAK " + worstStreak + " days (" + Money(worstStreakPnl) + ")");
            sb.AppendLine();
            sb.AppendLine("MONTH BY MONTH");
            sb.AppendLine(string.Format(CultureInfo.InvariantCulture, "{0,-9}{1,6}{2,10}{3,11}{4,12}", "MONTH", "DAYS", "WIN DAYS", "P/L", "RUNNING"));
            double running = 0;
            foreach (var m in days.GroupBy(d => new DateTime(d.Day.Year, d.Day.Month, 1)).OrderBy(g => g.Key))
            {
                double p = m.Sum(d => d.Pnl); running += p;
                sb.AppendLine(string.Format(CultureInfo.InvariantCulture, "{0,-9}{1,6}{2,9}%{3,11}{4,12}", m.Key.ToString("yyyy-MM"), m.Count(), (100.0 * m.Count(d => d.Pnl > 0) / m.Count()).ToString("0"), Money(p), Money(running)));
            }
            sb.AppendLine();
            sb.AppendLine("EVERY DAY");
            foreach (var d in days) sb.AppendLine(DayLine(d, asian));
            return sb.ToString();
        }
    }

    // One instrument's strategy result (no accounts): setups / legs, wins, losses, P/L.
    public sealed class KeystoneArcInstrumentStats
    {
        public string Symbol = string.Empty;
        public int Setups, Wins, Losses, Exits, Days, WinDays, LossDays;
        public double Pnl, BestDay, WorstDay, MaxDrawdown;
        public double WinRate { get { return Wins + Losses == 0 ? 0 : 100.0 * Wins / (Wins + Losses); } }
    }

    // Everything the results screens show in their top boxes, computed once from the pool.
    // Pure calculation over accounts / day records / events: no UI, no data requests.
    public sealed class KeystoneArcPoolInsights
    {
        public int Accounts, FundedNow, EvaluationNow, WaitingReplacement, SlotsEnded;
        public int BlowupEvents, EvaluationFails, FundedBlowups, MaxBlowupsPerAccount, MinBlowupsPerAccount;
        public int EvaluationPasses, Payouts, PaidAccounts, PayoutDates, EvaluationPurchases;
        public double Gross, CashAfterShare, Cost, Net;
        public DateTime FirstPayoutDate = DateTime.MinValue, LastPayoutDate = DateTime.MinValue;
        public string FirstPayoutAccount = string.Empty, LastPayoutAccount = string.Empty;
        public int AccountsPaidOnLastDate, StillFundedAfterLastPayout;
        public double AverageDaysToFirstPayout, AverageCostThroughFirstPayout;
        public DateTime LargestPayoutDay = DateTime.MinValue; public double LargestPayoutDayCash;
        public DateTime BestMonth = DateTime.MinValue, WorstMonth = DateTime.MinValue; public double BestMonthNet, WorstMonthNet;
        public int PositiveMonths, NegativeMonths;
        public string LongestFundedAccount = string.Empty; public int LongestFundedDays;
        public string MostPayoutsAccount = string.Empty; public int MostPayouts;
        public double MaxCarryBalance; public double AverageCarryBalance;
        public List<KeystoneArcInstrumentStats> Instruments = new List<KeystoneArcInstrumentStats>();

        public static KeystoneArcPoolInsights Build(List<KeystoneArcVirtualAccount> accounts, IEnumerable<KeystoneArcEvent> events, KeystoneArcRunConfig cfg)
        {
            var x = new KeystoneArcPoolInsights();
            var acc = (accounts ?? new List<KeystoneArcVirtualAccount>()).Where(a => a != null).ToList();
            x.Accounts = acc.Count;
            x.FundedNow = acc.Count(a => a.Funded && !a.Blown);
            x.WaitingReplacement = acc.Count(a => a.ReplacementPending);
            x.SlotsEnded = acc.Count(a => a.Blown && !a.ReplacementPending);
            x.EvaluationNow = acc.Count(a => !a.Funded && !a.Blown && !a.ReplacementPending);
            x.EvaluationFails = acc.Sum(a => a.FailedEvaluations);
            x.FundedBlowups = acc.Sum(a => a.FailedFunded);
            x.BlowupEvents = x.EvaluationFails + x.FundedBlowups;
            x.MaxBlowupsPerAccount = acc.Count == 0 ? 0 : acc.Max(a => a.FailedEvaluations + a.FailedFunded);
            x.MinBlowupsPerAccount = acc.Count == 0 ? 0 : acc.Min(a => a.FailedEvaluations + a.FailedFunded);
            x.EvaluationPasses = acc.Sum(a => a.EvaluationPasses);
            x.EvaluationPurchases = acc.Sum(a => a.EvaluationPurchases);
            x.Payouts = acc.Sum(a => a.Payouts);
            x.PaidAccounts = acc.Count(a => a.Payouts > 0);
            x.Gross = acc.Sum(a => a.PayoutGrossWithdrawn);
            x.CashAfterShare = acc.Sum(a => a.PayoutCash);
            x.Cost = acc.Sum(a => a.EvaluationCost);
            x.Net = x.CashAfterShare - x.Cost;
            var paid = acc.Where(a => a.FirstPayoutDate != DateTime.MinValue).ToList();
            if (paid.Count > 0)
            {
                var first = paid.OrderBy(a => a.FirstPayoutDate).ThenBy(a => a.Name).First();
                x.FirstPayoutDate = first.FirstPayoutDate; x.FirstPayoutAccount = first.Name;
                x.AverageDaysToFirstPayout = paid.Average(a => (a.FirstPayoutDate - (a.InitialLifecycleStart == DateTime.MinValue ? a.FirstPayoutDate : a.InitialLifecycleStart)).TotalDays);
                x.AverageCostThroughFirstPayout = paid.Average(a => a.DayHistory.Where(d => d.Day <= a.FirstPayoutDate).Sum(d => d.CostDelta));
            }
            var lastPaid = acc.Where(a => a.LastPayoutDate != DateTime.MinValue).ToList();
            if (lastPaid.Count > 0)
            {
                var last = lastPaid.OrderByDescending(a => a.LastPayoutDate).ThenBy(a => a.Name).First();
                x.LastPayoutDate = last.LastPayoutDate; x.LastPayoutAccount = last.Name;
                x.AccountsPaidOnLastDate = lastPaid.Count(a => a.LastPayoutDate == x.LastPayoutDate);
                x.StillFundedAfterLastPayout = lastPaid.Count(a => a.Funded && !a.Blown);
            }
            var payoutDays = acc.SelectMany(a => a.DayHistory).Where(d => d.PayoutCashDelta > 0).GroupBy(d => d.Day.Date).Select(g => new { Day = g.Key, Cash = g.Sum(d => d.PayoutCashDelta) }).ToList();
            x.PayoutDates = payoutDays.Count;
            if (payoutDays.Count > 0) { var big = payoutDays.OrderByDescending(d => d.Cash).ThenBy(d => d.Day).First(); x.LargestPayoutDay = big.Day; x.LargestPayoutDayCash = big.Cash; }
            var months = acc.SelectMany(a => a.DayHistory).GroupBy(d => new DateTime(d.Day.Year, d.Day.Month, 1)).Select(g => new { Month = g.Key, Net = g.Sum(d => d.PayoutCashDelta - d.CostDelta) }).OrderBy(m => m.Month).ToList();
            if (months.Count > 0)
            {
                var best = months.OrderByDescending(m => m.Net).ThenBy(m => m.Month).First(); var worst = months.OrderBy(m => m.Net).ThenBy(m => m.Month).First();
                x.BestMonth = best.Month; x.BestMonthNet = best.Net; x.WorstMonth = worst.Month; x.WorstMonthNet = worst.Net;
                x.PositiveMonths = months.Count(m => m.Net > 0); x.NegativeMonths = months.Count(m => m.Net < 0);
            }
            foreach (var a in acc)
            {
                int run = 0, bestRun = 0;
                foreach (var d in a.DayHistory.OrderBy(d => d.Day)) { if (d.FundedAfter) { run++; bestRun = Math.Max(bestRun, run); } else run = 0; }
                if (bestRun > x.LongestFundedDays) { x.LongestFundedDays = bestRun; x.LongestFundedAccount = a.Name; }
                if (a.Payouts > x.MostPayouts) { x.MostPayouts = a.Payouts; x.MostPayoutsAccount = a.Name; }
            }
            var carry = acc.Where(a => a.Funded && !a.Blown).Select(a => a.FundedBalance).ToList();
            if (carry.Count > 0) { x.MaxCarryBalance = carry.Max(); x.AverageCarryBalance = carry.Average(); }
            x.Instruments = InstrumentStats(events, cfg);
            return x;
        }

        // Plain-language answer to "how much money did I need, and when did it pay back?"
        public static string InvestmentAnswer(KeystoneArcCapitalPolicySummary c, KeystoneArcPoolInsights x)
        {
            if (c == null || x == null) return string.Empty;
            Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            var sb = new StringBuilder("YOUR MONEY • start " + m(c.InitialEvaluationInvestment));
            if (!c.FirstPayoutReached || x.FirstPayoutDate == DateTime.MinValue)
                return sb.Append(" • NO PAYOUT in this range • spent " + m(c.TotalEvaluationCost) + " in total").ToString();
            sb.Append(" • FIRST PAYOUT " + c.FirstPayoutDate.ToString("yyyy-MM-dd") + (string.IsNullOrEmpty(x.FirstPayoutAccount) ? "" : " (" + x.FirstPayoutAccount + ")") + " after " + m(c.InvestmentThroughFirstPayoutDate) + " spent");
            double extra = c.InvestmentThroughFirstPayoutDate - c.InitialEvaluationInvestment;
            sb.Append(extra <= 0.5 ? " → the initial investment WAS ENOUGH" : " → initial NOT enough: " + m(extra) + " extra before the first payout");
            sb.Append(c.ProfitabilityReached ? " • PROFITABLE FROM " + c.ProfitabilityDate.ToString("yyyy-MM-dd") : " • NOT yet paid back");
            double after = c.TotalEvaluationCost - (c.ProfitabilityReached ? c.InvestmentThroughProfitability : c.InvestmentThroughFirstPayoutDate);
            if (after > 0.5) sb.Append(" • " + m(after) + " more spent on accounts after that");
            sb.Append(" • FINAL NET " + m(c.FullNetCashAfterAllCosts));
            return sb.ToString();
        }

        // Second line of the money answer: where the account money came from.
        public static string CashFlowAnswer(KeystoneArcCapitalPolicySummary c)
        {
            if (c == null) return string.Empty;
            Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            var sb = new StringBuilder("CASH FLOW • MAX OWN MONEY IN " + m(c.MaxOutOfPocket));
            sb.Append(c.MaxOutOfPocketDate == DateTime.MinValue ? " (the initial purchase — never needed more)" : " (deepest on " + c.MaxOutOfPocketDate.ToString("yyyy-MM-dd") + ")");
            sb.Append(" • accounts " + m(c.TotalEvaluationCost) + " = " + m(c.AccountsPaidUpfront) + " upfront + " + m(c.AccountsPaidFromPayouts) + " from payouts");
            sb.Append(" • payouts " + m(c.PayoutCashAfterShare) + " → " + m(c.AccountsPaidFromPayouts) + " reinvested, " + m(c.PayoutsWithdrawn) + " kept");
            return sb.ToString();
        }

        public static List<KeystoneArcInstrumentStats> InstrumentStats(IEnumerable<KeystoneArcEvent> events, KeystoneArcRunConfig cfg)
        {
            var output = new List<KeystoneArcInstrumentStats>();
            var list = (events ?? Enumerable.Empty<KeystoneArcEvent>()).Where(e => e != null && e.Outcome != "UNVERIFIED 1M" && !string.IsNullOrEmpty(e.Symbol)).ToList();
            foreach (var g in list.GroupBy(e => e.Symbol.ToUpperInvariant()).OrderBy(g => g.Key))
            {
                var days = KeystoneArcScoreboard.Days(g, cfg);
                var s = new KeystoneArcInstrumentStats { Symbol = g.Key, Setups = g.Count(), Wins = g.Count(e => e.Outcome == "WIN"), Losses = g.Count(e => (e.Outcome ?? string.Empty).StartsWith("LOSS", StringComparison.OrdinalIgnoreCase)), Exits = g.Count(e => e.Outcome == "SESSION EXIT"), Pnl = g.Sum(e => e.GrossPnl) };
                s.Days = days.Count; s.WinDays = days.Count(d => d.Pnl > 0); s.LossDays = days.Count(d => d.Pnl < 0);
                if (days.Count > 0) { s.BestDay = days.Max(d => d.Pnl); s.WorstDay = days.Min(d => d.Pnl); }
                double eq = 0, peak = 0; foreach (var d in days) { eq += d.Pnl; peak = Math.Max(peak, eq); s.MaxDrawdown = Math.Max(s.MaxDrawdown, peak - eq); }
                output.Add(s);
            }
            return output;
        }
    }
    // One pool scenario result for the account-count / allocation comparison.
    // Every time an account was funded: how long it stayed funded, how close it came to the payout
    // balance and whether it was ever paid. Rebuilt from the per-day account records (no engine change).
    public sealed class KeystoneArcFundedEpisodes
    {
        public int Episodes, Paid, NeverPaid, StillOpen, ReachedThresholdNoPayout;
        public double AverageDays, AveragePeak, BestPeak, AveragePeakPercent;
        public string BestAccount = string.Empty;

        public static KeystoneArcFundedEpisodes Build(List<KeystoneArcVirtualAccount> accounts, KeystoneArcRunConfig cfg)
        {
            var x = new KeystoneArcFundedEpisodes();
            if (accounts == null) return x;
            var days = new List<double>(); var peaks = new List<double>();
            foreach (var a in accounts.Where(a => a != null && a.DayHistory != null))
            {
                bool open = false; DateTime start = DateTime.MinValue, last = DateTime.MinValue; double peak = 0; int payoutsAtStart = 0, payoutsNow = 0;
                Action close = () =>
                {
                    x.Episodes++; days.Add(Math.Max(1, (last - start).TotalDays + 1)); peaks.Add(peak);
                    if (payoutsNow > payoutsAtStart) x.Paid++; else { x.NeverPaid++; if (cfg != null && cfg.PayoutThreshold > 0 && peak >= cfg.PayoutThreshold) x.ReachedThresholdNoPayout++; }
                    if (peak > x.BestPeak) { x.BestPeak = peak; x.BestAccount = a.Name; }
                };
                foreach (var d in a.DayHistory.OrderBy(d => d.Day))
                {
                    bool funded = d.FundedAfter && !d.BlownAfter;
                    if (!open && funded)
                    { open = true; start = d.Day; peak = d.FundedBalanceAfter; payoutsAtStart = d.PayoutsAfter - (d.PayoutGrossDelta > 0 ? 1 : 0); }
                    if (open)
                    {
                        last = d.Day; payoutsNow = d.PayoutsAfter; peak = Math.Max(peak, d.FundedBalanceAfter + d.PayoutGrossDelta);
                        if (!funded) { close(); open = false; }
                    }
                }
                if (open) { close(); x.StillOpen++; if (payoutsNow <= payoutsAtStart) x.NeverPaid--; }
            }
            if (x.Episodes > 0) { x.AverageDays = days.Average(); x.AveragePeak = peaks.Average(); }
            if (cfg != null && cfg.PayoutThreshold > 0) x.AveragePeakPercent = 100.0 * x.AveragePeak / cfg.PayoutThreshold;
            return x;
        }

        public string Line(KeystoneArcRunConfig cfg)
        {
            if (Episodes == 0) return "FUNDED • no account was funded in this range";
            Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            return "FUNDED " + Episodes + " TIME" + (Episodes == 1 ? "" : "S") + " • PAID " + Paid + " • FUNDED BUT NEVER PAID (blown) " + NeverPaid + (StillOpen > 0 ? " • STILL FUNDED AT THE END " + StillOpen : "") +
                " • stayed funded ~" + AverageDays.ToString("0", CultureInfo.InvariantCulture) + " days • highest balance reached: average " + m(AveragePeak) + " (" + AveragePeakPercent.ToString("0", CultureInfo.InvariantCulture) + "% of the " + m(cfg == null ? 0 : cfg.PayoutThreshold) + " payout balance), best " + m(BestPeak) + " (" + BestAccount + ")" +
                (ReachedThresholdNoPayout > 0 ? " • " + ReachedThresholdNoPayout + " reached the payout balance but lacked qualifying days" : "");
        }
    }

    public sealed class KeystoneArcPoolScenario
    {
        public string Label = string.Empty; public int Accounts, GroupSize; public bool Copy;
        public int Payouts, Blowups, PaidAccounts; public double ToBank, Cost, Net, TradesPerAccount;
        public DateTime FirstPayout = DateTime.MinValue, Profitable = DateTime.MinValue;
        public bool Best;
    }

    // ---- PROP GAME OPTIMIZER: the same ledger and firm rules through the real pool with every choice YOU control -----------
    // (instrument, which hours, contract size, daily profit lock, daily loss lock, accounts), ranked by net cash after every
    // account cost. Hours "BEST" keeps the entry hours whose setups made money in the first 70% of the dates only (no look-
    // ahead), so the last 30% shows whether the choice held up.
    public sealed class KeystoneArcGameRow
    {
        public string Instrument = "BOTH", Hours = "ALL", Start = string.Empty; public double Size = 1, DayProfit, DayLoss; public int Accounts;
        public int Setups, Payouts, Blowups, Bought, PositiveMonths, Months; public double ToBank, Cost, Net, LateNet, CashLow, NetPerAccountDollar;
        public DateTime FirstPayout = DateTime.MinValue, Profitable = DateTime.MinValue;
        public string Label { get { return (Start == string.Empty ? "" : Start + " • ") + Instrument + " • " + (Hours == "ALL" ? "ALL HOURS" : "BEST HOURS " + Hours) + " • " + Size.ToString("0.##", CultureInfo.InvariantCulture) + "× SIZE • DAY LOCK +$" + DayProfit.ToString("N0", CultureInfo.InvariantCulture) + " / −$" + DayLoss.ToString("N0", CultureInfo.InvariantCulture) + " • " + Accounts + " ACCOUNTS"; } }
    }

    public sealed class KeystoneArcGameGrid
    {
        public List<string> Instruments = new List<string> { "BOTH", "MNQ", "MGC" }; public List<string> Hours = new List<string> { "ALL", "BEST" };
        public List<double> Sizes = new List<double> { 1, 2 }, DayProfits = new List<double> { 500, 1000, 1500 }, DayLosses = new List<double> { 500, 1000 };
        public List<int> Accounts = new List<int> { 20, 40 };
        public List<string> Starts = new List<string>();   // "DIRECT FUNDED" / "EVALUATION" (empty = the loaded setting)
    }

    public static class KeystoneArcGameOptimizer
    {
        // Hours (NY clock of the entry) whose setups made money on the first 70% of the dates.
        public static HashSet<int> BestHours(List<KeystoneArcEvent> events, DateTime splitAt)
        {
            return new HashSet<int>(events.Where(e => e.EntryTime < splitAt && e.EntryTime != DateTime.MinValue).GroupBy(e => e.EntryTime.Hour).Where(g => g.Count() >= 20 && g.Sum(e => e.GrossPnl) > 0).Select(g => g.Key));
        }

        public static KeystoneArcEvent Scaled(KeystoneArcEvent e, double k)
        {
            var c = e.CopyForPool(); if (k == 1) return c;
            c.GrossPnl *= k; c.EvaluationGrossPnl *= k; c.Quantity *= k; return c;
        }

        public static KeystoneArcGameRow One(List<KeystoneArcEvent> ledger, KeystoneArcRunConfig cfg, string inst, string hoursName, HashSet<int> hours, double size, double dayProfit, double dayLoss, int accounts, DateTime splitAt)
        {
            var ev = ledger.Where(e => (inst == "BOTH" || string.Equals(e.Symbol, inst, StringComparison.OrdinalIgnoreCase)) && (hours == null || hours.Contains(e.EntryTime.Hour))).Select(e => Scaled(e, size)).ToList();
            var c = cfg.ShallowCopy(); c.PoolSize = accounts; c.DailyGoal = dayProfit; c.DailyLoss = dayLoss; c.EvaluationDailyLoss = dayLoss; c.EvaluationDailyCreditCap = Math.Max(c.EvaluationDailyCreditCap, dayProfit);
            c.Scope = inst;
            var row = new KeystoneArcGameRow { Instrument = inst, Hours = hoursName, Size = size, DayProfit = dayProfit, DayLoss = dayLoss, Accounts = accounts, Setups = ev.Count };
            if (ev.Count == 0) return row;
            var acc = KeystoneArcEngine.SimulatePool(ev, c);
            var x = KeystoneArcPoolInsights.Build(acc, null, c); var cap = KeystoneArcEngine.BuildCapitalPolicySummary(acc, c);
            row.Payouts = x.Payouts; row.Blowups = x.BlowupEvents; row.Bought = x.EvaluationPurchases; row.ToBank = x.CashAfterShare; row.Cost = x.Cost; row.Net = x.Net;
            row.FirstPayout = x.FirstPayoutDate; row.Profitable = cap.ProfitabilityReached ? cap.ProfitabilityDate : DateTime.MinValue; row.PositiveMonths = x.PositiveMonths; row.Months = x.PositiveMonths + x.NegativeMonths;
            row.NetPerAccountDollar = row.Cost > 0 ? row.Net / row.Cost : 0;
            // cash curve: payouts in, account purchases out, by date — the lowest point = the money you need on hand; late = after the split
            var flows = acc.SelectMany(a => a.DayHistory).Select(d => Tuple.Create(d.Day, d.PayoutCashDelta - d.CostDelta)).ToList();
            double run = 0, low = 0; foreach (var f in flows.OrderBy(f => f.Item1)) { run += f.Item2; low = Math.Min(low, run); }
            row.CashLow = low; row.LateNet = flows.Where(f => f.Item1 >= splitAt).Sum(f => f.Item2);
            return row;
        }

        public static List<KeystoneArcGameRow> Run(List<KeystoneArcEvent> ledger, KeystoneArcRunConfig cfg, KeystoneArcGameGrid g, Action<int, int> progress, Func<bool> cancelled)
        {
            var rows = new List<KeystoneArcGameRow>(); if (ledger == null || ledger.Count == 0) return rows;
            var dates = ledger.Where(e => e.EntryTime != DateTime.MinValue).Select(e => e.EntryTime.Date).Distinct().OrderBy(d => d).ToList(); if (dates.Count == 0) return rows;
            DateTime split = dates[Math.Min(dates.Count - 1, (int)(dates.Count * 0.7))];
            var jobs = new List<Tuple<string, string, double, double, double, int, string>>(); var starts = g.Starts.Count == 0 ? new List<string> { "" } : g.Starts.Distinct().ToList();
            foreach (var st in starts) foreach (var inst in g.Instruments.Distinct()) foreach (var h in g.Hours.Distinct()) foreach (var s in g.Sizes.Distinct()) foreach (var dp in g.DayProfits.Distinct()) foreach (var dl in g.DayLosses.Distinct()) foreach (var n in g.Accounts.Distinct())
                jobs.Add(Tuple.Create(inst, h, s, dp, dl, n, st));
            var hourSets = new Dictionary<string, HashSet<int>>();
            foreach (var inst in g.Instruments.Distinct()) hourSets[inst] = BestHours(ledger.Where(e => inst == "BOTH" || string.Equals(e.Symbol, inst, StringComparison.OrdinalIgnoreCase)).ToList(), split);
            var output = new KeystoneArcGameRow[jobs.Count]; int done = 0;
            System.Threading.Tasks.Parallel.For(0, jobs.Count, new System.Threading.Tasks.ParallelOptions { MaxDegreeOfParallelism = Math.Max(1, Environment.ProcessorCount - 1) }, (i, state) =>
            {
                if (cancelled != null && cancelled()) { state.Stop(); return; }
                var j = jobs[i]; HashSet<int> hs = j.Item2 == "BEST" ? hourSets[j.Item1] : null;
                string hname = j.Item2 == "BEST" ? string.Join(",", hs.OrderBy(h => h).Select(h => h.ToString("00"))) : "ALL";
                var cc = cfg; if (j.Item7 != "") { cc = cfg.ShallowCopy(); cc.EvaluationEnabled = j.Item7 == "DIRECT FUNDED" ? 0 : 1; }
                output[i] = One(ledger, cc, j.Item1, j.Item2 == "BEST" && hs.Count == 0 ? "NONE" : hname, hs, j.Item3, j.Item4, j.Item5, j.Item6, split); output[i].Start = j.Item7;
                int c = System.Threading.Interlocked.Increment(ref done); if (progress != null) progress(c, jobs.Count);
            });
            return output.Where(r => r != null && r.Setups > 0).OrderByDescending(r => r.Net).ToList();
        }

        public static List<string> Advice(List<KeystoneArcGameRow> rows, KeystoneArcGameRow current)
        {
            var l = new List<string>(); if (rows.Count == 0) return l;
            Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            var best = rows[0];
            l.Add("MOST CASH: " + best.Label + " → net " + m(best.Net) + " (" + best.Payouts + " payouts, " + m(best.Cost) + " on accounts, last 30% of the dates " + m(best.LateNet) + ", cash low " + m(best.CashLow) + ")");
            if (current != null) l.Add("YOUR CURRENT SETTINGS: " + current.Label + " → net " + m(current.Net) + (best.Net > current.Net ? " • the best row adds " + m(best.Net - current.Net) : ""));
            var held = rows.Where(r => r.LateNet > 0).OrderByDescending(r => r.Net).FirstOrDefault();
            if (held != null) l.Add("BEST THAT ALSO WON IN THE LAST 30%: " + held.Label + " → net " + m(held.Net) + ", last 30% " + m(held.LateNet));
            var eff = rows.Where(r => r.Cost > 0 && r.Net > 0).OrderByDescending(r => r.NetPerAccountDollar).FirstOrDefault();
            if (eff != null) l.Add("MOST CASH PER $1 OF ACCOUNTS: " + eff.Label + " → " + eff.NetPerAccountDollar.ToString("0.0", CultureInfo.InvariantCulture) + " back per $1 (net " + m(eff.Net) + ", cash low " + m(eff.CashLow) + ")");
            var safe = rows.Where(r => r.Net > 0).OrderByDescending(r => r.CashLow).ThenByDescending(r => r.Net).FirstOrDefault();
            if (safe != null) l.Add("SMALLEST BUDGET NEEDED: " + safe.Label + " → cash never below " + m(safe.CashLow) + ", net " + m(safe.Net));
            foreach (var key in new[] { "START", "INSTRUMENT", "HOURS", "SIZE", "DAY PROFIT LOCK", "DAY LOSS LOCK", "ACCOUNTS" })
            {
                Func<KeystoneArcGameRow, string> f = r => key == "START" ? r.Start : key == "INSTRUMENT" ? r.Instrument : key == "HOURS" ? (r.Hours == "ALL" ? "ALL" : "BEST") : key == "SIZE" ? r.Size.ToString("0.##", CultureInfo.InvariantCulture) + "×" : key == "DAY PROFIT LOCK" ? "+$" + r.DayProfit.ToString("N0", CultureInfo.InvariantCulture) : key == "DAY LOSS LOCK" ? "−$" + r.DayLoss.ToString("N0", CultureInfo.InvariantCulture) : r.Accounts.ToString();
                var groups = rows.GroupBy(f).ToList(); if (groups.Count < 2) continue;
                l.Add(key + ": " + string.Join(" • ", groups.Select(gp => new { gp.Key, Med = gp.Select(r => r.Net).OrderBy(v => v).ElementAt(gp.Count() / 2), Best = gp.Max(r => r.Net) }).OrderByDescending(x => x.Med).Select(x => x.Key + " median " + m(x.Med) + " (best " + m(x.Best) + ")")));
            }
            return l;
        }
    }

    public static class KeystoneArcPoolCompare
    {
        // Runs the same ledger and settings with different account counts and allocations.
        public static List<KeystoneArcPoolScenario> Run(List<KeystoneArcEvent> events, KeystoneArcRunConfig cfg)
        {
            var rows = new List<KeystoneArcPoolScenario>();
            if (events == null || cfg == null) return rows;
            bool asian = string.Equals(cfg.StrategyCode, "ASIAN75", StringComparison.OrdinalIgnoreCase);
            var plans = new List<Tuple<string, int, int, bool>>();
            foreach (int n in new[] { 1, 2, 3, 5, 10, 20 }) plans.Add(Tuple.Create(asian ? "COPY " + n + " ACCOUNTS" : "ROTATION " + n + " ACCOUNT" + (n == 1 ? "" : "S"), n, 0, asian));
            if (!asian)
            {
                plans.Add(Tuple.Create("COPY TO ALL 3", 3, 0, true)); plans.Add(Tuple.Create("COPY TO ALL 5", 5, 0, true));
                plans.Add(Tuple.Create("10 ACCOUNTS • 2 GROUPS OF 5", 10, 5, false)); plans.Add(Tuple.Create("20 ACCOUNTS • 4 GROUPS OF 5", 20, 5, false)); plans.Add(Tuple.Create("20 ACCOUNTS • 2 GROUPS OF 10", 20, 10, false));
            }
            foreach (var plan in plans)
            {
                KeystoneArcRunConfig c = cfg.ShallowCopy(); c.PoolSize = plan.Item2; c.CopyGroupSize = plan.Item3; c.CopyTradingPool = plan.Item4 && !asian ? 1 : 0;
                List<KeystoneArcVirtualAccount> acc = KeystoneArcEngine.SimulatePool(events.Where(e => e != null).Select(e => e.CopyForPool()).ToList(), c);
                KeystoneArcPoolInsights x = KeystoneArcPoolInsights.Build(acc, null, c);
                KeystoneArcCapitalPolicySummary cap = KeystoneArcEngine.BuildCapitalPolicySummary(acc, c);
                rows.Add(new KeystoneArcPoolScenario { Label = plan.Item1, Accounts = plan.Item2, GroupSize = plan.Item3, Copy = plan.Item4, Payouts = x.Payouts, Blowups = x.BlowupEvents, PaidAccounts = x.PaidAccounts,
                    ToBank = x.CashAfterShare, Cost = x.Cost, Net = x.Net, TradesPerAccount = acc.Count == 0 ? 0 : acc.Average(a => a.Trades), FirstPayout = x.FirstPayoutDate, Profitable = cap.ProfitabilityReached ? cap.ProfitabilityDate : DateTime.MinValue });
            }
            var best = rows.OrderByDescending(r => r.Net).ThenBy(r => r.Cost).FirstOrDefault();
            if (best != null && best.Net > 0) best.Best = true;
            return rows;
        }

        public static string Table(List<KeystoneArcPoolScenario> rows)
        {
            Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            var sb = new StringBuilder();
            sb.AppendLine(string.Format(CultureInfo.InvariantCulture, "{0,-30} {1,7} {2,8} {3,11} {4,10} {5,11} {6,8} {7,11} {8,11}", "ALLOCATION", "TRADES", "PAYOUTS", "TO BANK", "COST", "NET", "BLOWUPS", "1ST PAYOUT", "PROFITABLE"));
            foreach (var r in rows)
                sb.AppendLine(string.Format(CultureInfo.InvariantCulture, "{0,-30} {1,7:0} {2,8} {3,11} {4,10} {5,11} {6,8} {7,11} {8,11}", (r.Best ? "★ " : "  ") + r.Label, r.TradesPerAccount, r.Payouts, m(r.ToBank), m(r.Cost), m(r.Net), r.Blowups,
                    r.FirstPayout == DateTime.MinValue ? "—" : r.FirstPayout.ToString("yyyy-MM-dd"), r.Profitable == DateTime.MinValue ? "—" : r.Profitable.ToString("yyyy-MM-dd")));
            return sb.ToString().TrimEnd();
        }

        // Plain answer when payouts are missing or rare: what each account earned vs what a payout needs.
        public static string PayoutDiagnosis(List<KeystoneArcVirtualAccount> accounts, KeystoneArcRunConfig cfg)
        {
            if (accounts == null || accounts.Count == 0 || cfg == null || cfg.EvaluationEnabled < 0) return string.Empty;
            Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            int payouts = accounts.Sum(a => a.Payouts);
            double avgPnl = accounts.Average(a => a.TotalPnl), avgTrades = accounts.Average(a => a.Trades);
            var bestAcc = accounts.OrderByDescending(a => a.FundedBalance).First();
            int maxQual = accounts.Max(a => a.FundedPositiveDays);
            if (payouts > 0 && payouts >= accounts.Count) return string.Empty;
            bool copyAll = cfg.CopyTradingPool > 0 || string.Equals(cfg.StrategyCode, "ASIAN75", StringComparison.OrdinalIgnoreCase);
            var sb = new StringBuilder("WHY " + (payouts == 0 ? "NO PAYOUT" : "FEW PAYOUTS") + " • each account took ~" + avgTrades.ToString("0", CultureInfo.InvariantCulture) + " trades and averaged " + m(avgPnl));
            if (copyAll && accounts.Count > 1) sb.Append(" • COPY: all " + accounts.Count + " accounts trade the same thing, so this is ONE result repeated " + accounts.Count + " times — more accounts multiply the cost of a losing strategy, they do not change the result");
            sb.Append(" • a payout needs a funded balance of " + m(cfg.PayoutThreshold) + " and " + cfg.PayoutDaysRequired + " qualifying days (≥ " + m(cfg.MinimumQualifyingDayProfit) + ")");
            sb.Append(" • best: " + bestAcc.Name + " at " + m(bestAcc.FundedBalance) + ", most qualifying days " + maxQual);
            sb.Append("\n" + KeystoneArcFundedEpisodes.Build(accounts, cfg).Line(cfg));
            sb.Append(avgPnl < 0 ? " → the strategy itself lost money per account (" + m(avgPnl) + "): fix the strategy first (COMPARE MNQ vs MGC, COMPARE TIMEFRAMES / optimizer), accounts cannot fix a losing edge" : avgTrades < 25 ? " → too few trades per account: use FEWER ACCOUNTS or COPY GROUPS (COMPARE ACCOUNTS shows which is best)" : " → the strategy result per account is too small or blows up first: check the stop / target and daily loss");
            return sb.ToString();
        }
    }

    public sealed class KeystoneArcStrategyRow
    {
        public string Strategy = string.Empty;
        public int Setups, Resolved, Wins, Losses, Exits, Days, GreenDays, Payouts, Blowups, EvalPasses;
        public double TradePnl, WinRate, ProfitFactor, AvgWin, AvgLoss, WorstDay, BestDay, MaxDrawdown, ToBank, Cost, Net, OwnMoney;
        public string BestHour = "—", BestGrade = "—";
        public bool PoolRan, Best;
    }

    // BH vs FVG (and more strategies later) on the same loaded bars, the same session and the same
    // prop rules. Detection and outcomes come from each strategy's own engine; nothing is changed.
    public static class KeystoneArcStrategyCompare
    {
        public static bool Resolved(KeystoneArcEvent e)
        {
            string o = e == null ? string.Empty : (e.Outcome ?? string.Empty);
            return o == "WIN" || o.StartsWith("LOSS", StringComparison.OrdinalIgnoreCase) || o == "SESSION EXIT" || o == "BREAKEVEN";
        }

        public static KeystoneArcRunConfig ConfigFor(KeystoneArcRunConfig cfg, string strategy)
        {
            KeystoneArcRunConfig c = cfg.ShallowCopy();
            c.StrategyCode = strategy;
            if (strategy == "BH") { c.EnableBh = 1; c.EnableFvg = 0; }
            return c;
        }

        public static KeystoneArcStrategyRow Summarize(string strategy, List<KeystoneArcEvent> events, List<KeystoneArcVirtualAccount> accounts, KeystoneArcRunConfig cfg)
        {
            var r = new KeystoneArcStrategyRow { Strategy = strategy };
            if (events == null) return r;
            List<KeystoneArcEvent> done = events.Where(Resolved).OrderBy(e => e.EntryTime).ToList();
            r.Setups = events.Count; r.Resolved = done.Count;
            r.Wins = done.Count(e => e.Outcome == "WIN"); r.Losses = done.Count(e => e.Outcome.StartsWith("LOSS", StringComparison.OrdinalIgnoreCase)); r.Exits = done.Count - r.Wins - r.Losses;
            r.TradePnl = done.Sum(e => e.GrossPnl);
            r.WinRate = done.Count == 0 ? 0 : 100.0 * r.Wins / done.Count;
            double gw = done.Where(e => e.GrossPnl > 0).Sum(e => e.GrossPnl), gl = -done.Where(e => e.GrossPnl < 0).Sum(e => e.GrossPnl);
            r.ProfitFactor = gl <= 0 ? (gw > 0 ? 99 : 0) : gw / gl;
            r.AvgWin = done.Where(e => e.GrossPnl > 0).Select(e => e.GrossPnl).DefaultIfEmpty(0).Average();
            r.AvgLoss = done.Where(e => e.GrossPnl < 0).Select(e => e.GrossPnl).DefaultIfEmpty(0).Average();
            var byDay = done.GroupBy(e => cfg == null ? e.EntryTime.Date : KeystoneArcEngine.SessionGroupingDate(e.TriggerTime, cfg)).Select(g => g.Sum(e => e.GrossPnl)).ToList();
            r.Days = byDay.Count; r.GreenDays = byDay.Count(v => v > 0);
            r.BestDay = byDay.DefaultIfEmpty(0).Max(); r.WorstDay = byDay.DefaultIfEmpty(0).Min();
            double equity = 0, peak = 0;
            foreach (var e in done) { equity += e.GrossPnl; peak = Math.Max(peak, equity); r.MaxDrawdown = Math.Max(r.MaxDrawdown, peak - equity); }
            var hour = done.GroupBy(e => e.EntryTime.Hour).Where(g => g.Count() >= 3).OrderByDescending(g => g.Sum(e => e.GrossPnl)).FirstOrDefault();
            if (hour != null && hour.Sum(e => e.GrossPnl) > 0) r.BestHour = hour.Key.ToString("00") + ":00";
            var grade = done.Where(e => !string.IsNullOrEmpty(e.QualityTier) && e.QualityTier != "N").GroupBy(e => e.QualityTier).Where(g => g.Count() >= 3).OrderByDescending(g => g.Average(e => e.GrossPnl)).FirstOrDefault();
            if (grade != null) r.BestGrade = grade.Key;
            if (accounts != null && accounts.Count > 0 && cfg != null && cfg.EvaluationEnabled >= 0)
            {
                KeystoneArcPoolInsights x = KeystoneArcPoolInsights.Build(accounts, null, cfg);
                r.PoolRan = true; r.Payouts = x.Payouts; r.Blowups = x.BlowupEvents; r.ToBank = x.CashAfterShare; r.Cost = x.Cost; r.Net = x.Net;
                r.EvalPasses = accounts.Sum(a => a.EvaluationPasses);
                r.OwnMoney = KeystoneArcEngine.BuildCapitalPolicySummary(accounts, cfg).MaxOutOfPocket;
            }
            return r;
        }

        public static void MarkBest(List<KeystoneArcStrategyRow> rows)
        {
            if (rows == null || rows.Count == 0) return;
            // Net cash after costs decides when any strategy reached payouts; otherwise trade P/L.
            bool pool = rows.All(r => r.PoolRan) && rows.Any(r => r.Net > 0);
            var best = rows.OrderByDescending(r => pool ? r.Net : r.TradePnl).ThenByDescending(r => r.TradePnl).First();
            if ((pool ? best.Net : best.TradePnl) > 0) best.Best = true;
        }

        // Entries of two strategies on the same instrument within toleranceMinutes of each other.
        public static List<KeystoneArcEvent> SameEntries(List<KeystoneArcEvent> a, List<KeystoneArcEvent> b, int toleranceMinutes)
        {
            var output = new List<KeystoneArcEvent>();
            if (a == null || b == null) return output;
            var bySymbol = b.Where(e => e.EntryTime != DateTime.MinValue).GroupBy(e => e.Symbol ?? string.Empty).ToDictionary(g => g.Key, g => g.Select(e => e.EntryTime).OrderBy(t => t).ToList());
            foreach (var e in a)
            {
                List<DateTime> times;
                if (e.EntryTime == DateTime.MinValue || !bySymbol.TryGetValue(e.Symbol ?? string.Empty, out times)) continue;
                if (times.Any(t => Math.Abs((t - e.EntryTime).TotalMinutes) <= toleranceMinutes)) output.Add(e);
            }
            return output;
        }

        public static string Table(List<KeystoneArcStrategyRow> rows)
        {
            Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            var sb = new StringBuilder();
            bool pool = rows.Count > 0 && rows.All(r => r.PoolRan);
            sb.AppendLine(string.Format(CultureInfo.InvariantCulture, "{0,-10} {1,7} {2,13} {3,5} {4,5} {5,11} {6,9} {7,10} {8,10} {9,6} {10,6}{11}", "STRATEGY", "SETUPS", "W / L / EXIT", "WIN%", "PF", "TRADE P/L", "WORSTDAY", "MAX DD", "GREEN DAYS", "HOUR", "GRADE",
                pool ? string.Format(CultureInfo.InvariantCulture, " {0,8} {1,11} {2,10} {3,10} {4,11}", "PAYOUTS", "TO BANK", "COST", "OWN $ MAX", "NET") : string.Empty));
            foreach (var r in rows)
                sb.AppendLine(string.Format(CultureInfo.InvariantCulture, "{0,-10} {1,7} {2,13} {3,4:0}% {4,5:0.00} {5,11} {6,9} {7,10} {8,10} {9,6} {10,6}{11}", (r.Best ? "★ " : "  ") + r.Strategy, r.Setups, r.Wins + "/" + r.Losses + "/" + r.Exits, r.WinRate, r.ProfitFactor, m(r.TradePnl), m(r.WorstDay), m(-r.MaxDrawdown), r.GreenDays + "/" + r.Days, r.BestHour, r.BestGrade,
                    pool ? string.Format(CultureInfo.InvariantCulture, " {0,8} {1,11} {2,10} {3,10} {4,11}", r.Payouts, m(r.ToBank), m(r.Cost), m(r.OwnMoney), m(r.Net)) : string.Empty));
            return sb.ToString().TrimEnd();
        }

        public static string Verdict(List<KeystoneArcStrategyRow> rows, int agreeCount, int agreeWins, double agreePnl)
        {
            Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            var best = rows == null ? null : rows.FirstOrDefault(r => r.Best);
            var sb = new StringBuilder();
            if (best == null) sb.Append("WINNER • none of the strategies made money with these settings.");
            else
            {
                bool byNet = best.PoolRan && best.Net > 0;
                var other = rows.Where(r => r != best).OrderByDescending(r => byNet ? r.Net : r.TradePnl).FirstOrDefault();
                sb.Append("WINNER • " + best.Strategy + (byNet ? " • net cash " + m(best.Net) : " • trade P/L " + m(best.TradePnl)));
                if (other != null) sb.Append(" vs " + other.Strategy + " " + (byNet ? m(other.Net) : m(other.TradePnl)));
                if (!byNet && best.PoolRan) sb.Append(" • no payouts with these prop rules yet (try COMPARE ACCOUNTS)");
                sb.Append(" • win " + best.WinRate.ToString("0", CultureInfo.InvariantCulture) + "% • PF " + best.ProfitFactor.ToString("0.00", CultureInfo.InvariantCulture) + " • worst day " + m(best.WorstDay));
            }
            if (agreeCount > 0)
                sb.Append("\nBOTH AGREE (FVG entry = BH entry, ±1 bar) • " + agreeCount + " setups • win " + (100.0 * agreeWins / agreeCount).ToString("0", CultureInfo.InvariantCulture) + "% • FVG P/L " + m(agreePnl) + " → these are DOUBLE TROUBLE confirmations.");
            return sb.ToString();
        }

        // One-line result per strategy for a single day on the chart.
        public static string DayLine(string day, IEnumerable<Tuple<string, List<KeystoneArcEvent>>> strategies)
        {
            Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            var parts = new List<string>(); string winner = null; double best = double.MinValue;
            foreach (var s in strategies)
            {
                var done = s.Item2.Where(Resolved).ToList(); double pnl = done.Sum(e => e.GrossPnl);
                parts.Add(s.Item1 + " " + s.Item2.Count + " setups • " + done.Count(e => e.Outcome == "WIN") + "W/" + done.Count(e => e.Outcome.StartsWith("LOSS", StringComparison.OrdinalIgnoreCase)) + "L • " + m(pnl));
                if (done.Count > 0 && pnl > best) { best = pnl; winner = s.Item1; }
            }
            return "DAY COMPARE " + day + " • " + string.Join("  |  ", parts) + (winner != null && best > 0 ? "  → " + winner + " WINS THE DAY" : "  → no strategy made money this day");
        }
    }

    public sealed class KeystoneArcPeriodRow
    {
        public string Label = string.Empty; public DateTime Start, End;
        public int Setups, Wins, Losses, Exits, Days, GreenDays;
        public double TradePnl, WinRate, PerSetup, WorstDay, MaxDrawdown;
        // The loaded (continuous) pool during this period.
        public int Payouts, Blowups; public double ToBank, Cost, Net;
        // This period alone with brand-new accounts bought on its first day.
        public bool FreshRan; public int FreshPayouts, FreshBlowups, FreshPasses, FreshDaysToFirstPayout = -1; public double FreshToBank, FreshCost, FreshNet;
        public bool Best, Worst;
    }

    // MONTHS / WEEKS: the same loaded setups and settings, split by calendar period.
    public static class KeystoneArcPeriods
    {
        public static DateTime PeriodStart(DateTime day, string mode)
        {
            DateTime d = day.Date;
            if (string.Equals(mode, "WEEK", StringComparison.OrdinalIgnoreCase)) return d.AddDays(-((7 + (int)d.DayOfWeek - 1) % 7));
            return new DateTime(d.Year, d.Month, 1);
        }

        public static List<KeystoneArcPeriodRow> Build(List<KeystoneArcEvent> events, List<KeystoneArcVirtualAccount> accounts, KeystoneArcRunConfig cfg, string mode, bool fresh, DateTime from, DateTime to)
        {
            var rows = new List<KeystoneArcPeriodRow>();
            if (events == null || cfg == null) return rows;
            bool week = string.Equals(mode, "WEEK", StringComparison.OrdinalIgnoreCase);
            Func<KeystoneArcEvent, DateTime> dayOf = e => KeystoneArcEngine.SessionGroupingDate(e.TriggerTime, cfg).Date;
            var accepted = events.Where(e => string.Equals(e.ReviewState ?? "ACCEPTED", "ACCEPTED", StringComparison.OrdinalIgnoreCase) && dayOf(e) >= from.Date && dayOf(e) <= to.Date).ToList();
            foreach (var g in accepted.GroupBy(e => PeriodStart(dayOf(e), mode)).OrderBy(g => g.Key))
            {
                DateTime start = g.Key, end = week ? start.AddDays(6) : start.AddMonths(1).AddDays(-1);
                var r = new KeystoneArcPeriodRow { Start = start, End = end, Label = week ? start.ToString("MMM dd", CultureInfo.InvariantCulture) + " – " + end.ToString("MMM dd", CultureInfo.InvariantCulture) : start.ToString("MMM yyyy", CultureInfo.InvariantCulture) };
                var done = g.Where(KeystoneArcStrategyCompare.Resolved).OrderBy(e => e.EntryTime).ToList();
                r.Setups = g.Count(); r.Wins = done.Count(e => e.Outcome == "WIN"); r.Losses = done.Count(e => (e.Outcome ?? "").StartsWith("LOSS", StringComparison.OrdinalIgnoreCase)); r.Exits = done.Count - r.Wins - r.Losses;
                r.TradePnl = done.Sum(e => e.GrossPnl); r.WinRate = done.Count == 0 ? 0 : 100.0 * r.Wins / done.Count; r.PerSetup = done.Count == 0 ? 0 : r.TradePnl / done.Count;
                var byDay = done.GroupBy(dayOf).Select(d => d.Sum(e => e.GrossPnl)).ToList();
                r.Days = byDay.Count; r.GreenDays = byDay.Count(v => v > 0); r.WorstDay = byDay.DefaultIfEmpty(0).Min();
                double eq = 0, peak = 0; foreach (var e in done) { eq += e.GrossPnl; peak = Math.Max(peak, eq); r.MaxDrawdown = Math.Max(r.MaxDrawdown, peak - eq); }
                if (accounts != null)
                    foreach (var a in accounts.Where(a => a != null && a.DayHistory != null))
                    {
                        var hist = a.DayHistory.OrderBy(d => d.Day).ToList();
                        int payoutsBefore = hist.Where(d => d.Day.Date < start).Select(d => d.PayoutsAfter).DefaultIfEmpty(0).Last();
                        var inside = hist.Where(d => d.Day.Date >= start && d.Day.Date <= end).ToList();
                        if (inside.Count == 0) continue;
                        r.Payouts += Math.Max(0, inside.Last().PayoutsAfter - payoutsBefore);
                        r.ToBank += inside.Sum(d => d.PayoutCashDelta); r.Cost += inside.Sum(d => d.CostDelta);
                        bool wasBlown = hist.Where(d => d.Day.Date < start).Select(d => d.BlownAfter).DefaultIfEmpty(false).Last();
                        foreach (var d in inside) { if (d.BlownAfter && !wasBlown) r.Blowups++; wasBlown = d.BlownAfter; }
                    }
                r.Net = r.ToBank - r.Cost;
                if (fresh && cfg.EvaluationEnabled >= 0)
                {
                    KeystoneArcRunConfig c = cfg.ShallowCopy(); c.Start = start; c.End = end.AddDays(1).AddMinutes(-1);
                    var acc = KeystoneArcEngine.SimulatePool(g.Select(e => e.CopyForPool()).ToList(), c);
                    r.FreshRan = true; r.FreshPayouts = acc.Sum(a => a.Payouts); r.FreshBlowups = acc.Sum(a => a.FailedEvaluations + a.FailedFunded); r.FreshPasses = acc.Sum(a => a.EvaluationPasses);
                    r.FreshToBank = acc.Sum(a => a.PayoutCash); r.FreshCost = acc.Sum(a => a.EvaluationCost); r.FreshNet = r.FreshToBank - r.FreshCost;
                    var firsts = acc.Select(KeystoneArcEngine.GetFirstPayoutTiming).Where(t => t.HasPayout).Select(t => (t.FirstPayoutDate.Date - start).TotalDays).ToList();
                    if (firsts.Count > 0) r.FreshDaysToFirstPayout = (int)firsts.Min();
                }
                rows.Add(r);
            }
            if (rows.Count > 1)
            {
                bool freshPays = rows.Any(x => x.FreshRan && x.FreshNet > 0);
                Func<KeystoneArcPeriodRow, double> key = x => freshPays ? x.FreshNet : x.TradePnl;
                var best = rows.OrderByDescending(key).First(); var worst = rows.OrderBy(key).First();
                if (key(best) > 0) best.Best = true;
                if (key(worst) < key(best)) worst.Worst = true;
            }
            return rows;
        }

        public static string Table(List<KeystoneArcPeriodRow> rows, string title)
        {
            Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            var sb = new StringBuilder(title + "\n");
            sb.AppendLine(string.Format(CultureInfo.InvariantCulture, "{0,-18} {1,6} {2,12} {3,5} {4,10} {5,9} {6,9} | {7,7} {8,7} {9,10} | {10,12} {11,7} {12,9}", "PERIOD", "SETUPS", "W/L/EXIT", "WIN%", "TRADE P/L", "WORSTDAY", "MAX DD", "PAYOUTS", "BLOWUPS", "POOL NET", "ALONE NET", "PAYOUTS", "1ST PAY"));
            foreach (var r in rows)
                sb.AppendLine(string.Format(CultureInfo.InvariantCulture, "{0,-18} {1,6} {2,12} {3,4:0}% {4,10} {5,9} {6,9} | {7,7} {8,7} {9,10} | {10,12} {11,7} {12,9}", (r.Best ? "★ " : r.Worst ? "✖ " : "  ") + r.Label, r.Setups, r.Wins + "/" + r.Losses + "/" + r.Exits, r.WinRate, m(r.TradePnl), m(r.WorstDay), m(-r.MaxDrawdown), r.Payouts, r.Blowups, m(r.Net),
                    r.FreshRan ? m(r.FreshNet) : "—", r.FreshRan ? r.FreshPayouts.ToString(CultureInfo.InvariantCulture) : "—", r.FreshDaysToFirstPayout >= 0 ? r.FreshDaysToFirstPayout + "d" : "—"));
            return sb.ToString().TrimEnd();
        }
    }

    public sealed class KeystoneArcSessionRow
    {
        public string Label = string.Empty; public int StartHhmm, EndHhmm;
        public int Setups, Wins, Losses; public double TradePnl, WinRate, PerSetup, ProfitFactor, MaxDrawdown, WorstDay;
        public int FirstN, LaterN; public double FirstPerSetup, LaterPerSetup;
        public bool PoolRan; public double PoolNet; public int PoolPayouts, PoolBlowups;
        public bool Best, Loaded = true;
    }

    public sealed class KeystoneArcSessionReport
    {
        public List<KeystoneArcSessionRow> Windows = new List<KeystoneArcSessionRow>();
        public List<KeystoneArcSessionRow> Hours = new List<KeystoneArcSessionRow>();
        public DateTime Split; public string Verdict = string.Empty;
    }

    // SESSION FINDER: the loaded setups filtered by entry time of day (NY). Ranked by quality per
    // setup (not by pool totals, which are capped by how many trades the accounts can take).
    // Honesty check: the best window is picked on the first two thirds of the range and then
    // shown on the last third it was not picked on.
    public static class KeystoneArcSessions
    {
        public static readonly Tuple<string, int, int>[] Windows =
        {
            Tuple.Create("ASIA 18:00–03:00", 1800, 300), Tuple.Create("LONDON 03:00–08:00", 300, 800), Tuple.Create("PRE-NY 08:00–09:30", 800, 930),
            Tuple.Create("NY OPEN 09:30–11:00", 930, 1100), Tuple.Create("MIDDAY 11:00–14:00", 1100, 1400), Tuple.Create("AFTERNOON 14:00–17:00", 1400, 1700),
            Tuple.Create("NY 08:00–11:00", 800, 1100), Tuple.Create("NY DAY 09:30–16:00", 930, 1600)
        };

        public static bool Inside(DateTime t, int start, int end)
        {
            int hhmm = t.Hour * 100 + t.Minute;
            return start <= end ? hhmm >= start && hhmm < end : hhmm >= start || hhmm < end;
        }

        static KeystoneArcSessionRow Stats(string label, int start, int end, List<KeystoneArcEvent> done, DateTime split, KeystoneArcRunConfig cfg)
        {
            var r = new KeystoneArcSessionRow { Label = label, StartHhmm = start, EndHhmm = end };
            var rows = done.Where(e => Inside(e.EntryTime, start, end)).ToList();
            r.Setups = rows.Count; r.Wins = rows.Count(e => e.Outcome == "WIN"); r.Losses = rows.Count(e => (e.Outcome ?? "").StartsWith("LOSS", StringComparison.OrdinalIgnoreCase));
            r.TradePnl = rows.Sum(e => e.GrossPnl); r.WinRate = rows.Count == 0 ? 0 : 100.0 * r.Wins / rows.Count; r.PerSetup = rows.Count == 0 ? 0 : r.TradePnl / rows.Count;
            double gw = rows.Where(e => e.GrossPnl > 0).Sum(e => e.GrossPnl), gl = -rows.Where(e => e.GrossPnl < 0).Sum(e => e.GrossPnl);
            r.ProfitFactor = gl <= 0 ? (gw > 0 ? 99 : 0) : gw / gl;
            double eq = 0, peak = 0; foreach (var e in rows) { eq += e.GrossPnl; peak = Math.Max(peak, eq); r.MaxDrawdown = Math.Max(r.MaxDrawdown, peak - eq); }
            r.WorstDay = rows.GroupBy(e => KeystoneArcEngine.SessionGroupingDate(e.TriggerTime, cfg).Date).Select(g => g.Sum(e => e.GrossPnl)).DefaultIfEmpty(0).Min();
            var first = rows.Where(e => e.EntryTime < split).ToList(); var later = rows.Where(e => e.EntryTime >= split).ToList();
            r.FirstN = first.Count; r.LaterN = later.Count;
            r.FirstPerSetup = first.Count == 0 ? 0 : first.Average(e => e.GrossPnl); r.LaterPerSetup = later.Count == 0 ? 0 : later.Average(e => e.GrossPnl);
            return r;
        }

        public static KeystoneArcSessionReport Build(List<KeystoneArcEvent> events, KeystoneArcRunConfig cfg, bool runPool)
        {
            var rep = new KeystoneArcSessionReport();
            if (events == null || cfg == null) return rep;
            var done = events.Where(e => KeystoneArcStrategyCompare.Resolved(e) && string.Equals(e.ReviewState ?? "ACCEPTED", "ACCEPTED", StringComparison.OrdinalIgnoreCase)).OrderBy(e => e.EntryTime).ToList();
            if (done.Count == 0) { rep.Verdict = "No finished setups to rank."; return rep; }
            DateTime a = done.First().EntryTime, b = done.Last().EntryTime;
            rep.Split = a.AddTicks((long)((b - a).Ticks * (2.0 / 3.0))).Date;
            var loadedHours = new HashSet<int>(done.Select(e => e.EntryTime.Hour));
            foreach (var w in Windows)
            {
                var r = Stats(w.Item1, w.Item2, w.Item3, done, rep.Split, cfg);
                r.Loaded = r.Setups > 0;
                if (runPool && r.Setups > 0 && cfg.EvaluationEnabled >= 0)
                {
                    var acc = KeystoneArcEngine.SimulatePool(events.Where(e => Inside(e.EntryTime == DateTime.MinValue ? e.TriggerTime : e.EntryTime, w.Item2, w.Item3) && string.Equals(e.ReviewState ?? "ACCEPTED", "ACCEPTED", StringComparison.OrdinalIgnoreCase)).Select(e => e.CopyForPool()).ToList(), cfg);
                    r.PoolRan = true; r.PoolNet = acc.Sum(x => x.PayoutCash - x.EvaluationCost); r.PoolPayouts = acc.Sum(x => x.Payouts); r.PoolBlowups = acc.Sum(x => x.FailedEvaluations + x.FailedFunded);
                }
                rep.Windows.Add(r);
            }
            for (int h = 0; h < 24; h++) if (loadedHours.Contains(h)) rep.Hours.Add(Stats(h.ToString("00") + ":00", h * 100, h * 100 + 100 > 2400 ? 0 : (h + 1) * 100 % 2400, done, rep.Split, cfg));
            // Pick on the first part only (at least 15 setups there), then show the later part.
            var pick = rep.Windows.Where(r => r.FirstN >= 15).OrderByDescending(r => r.FirstPerSetup).FirstOrDefault();
            Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            if (pick == null) { rep.Verdict = "Not enough setups per window to pick a session (need 15+ in the first part of the range). Load a longer range or FULL GLOBEX."; return rep; }
            pick.Best = true;
            bool held = pick.LaterN >= 5 && pick.LaterPerSetup > 0;
            rep.Verdict = "BEST SESSION (picked on data before " + rep.Split.ToString("yyyy-MM-dd") + "): " + pick.Label + " • " + m(pick.FirstPerSetup) + " per setup there (" + pick.FirstN + " setups). ON THE LATER DATA IT WAS NOT PICKED ON: " + m(pick.LaterPerSetup) + " per setup (" + pick.LaterN + " setups) → " +
                (pick.LaterN < 5 ? "too few later setups to confirm." : held ? "HELD UP — a real candidate." : "DID NOT HOLD — likely luck; do not trade this window on its own.");
            if (loadedHours.Count < 18) rep.Verdict += " (Only " + loadedHours.Count + " hours of the day were loaded; load FULL GLOBEX to compare every session.)";
            return rep;
        }

        public static string Table(KeystoneArcSessionReport rep)
        {
            Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            var sb = new StringBuilder();
            sb.AppendLine(string.Format(CultureInfo.InvariantCulture, "{0,-24} {1,6} {2,5} {3,9} {4,5} {5,10} {6,9} | {7,11} {8,11} | {9,10} {10,7}", "SESSION (NY)", "SETUPS", "WIN%", "PER SETUP", "PF", "TRADE P/L", "MAX DD", "FIRST PART", "LATER PART", "POOL NET", "PAYOUTS"));
            foreach (var r in rep.Windows)
                sb.AppendLine(string.Format(CultureInfo.InvariantCulture, "{0,-24} {1,6} {2,4:0}% {3,9} {4,5:0.00} {5,10} {6,9} | {7,11} {8,11} | {9,10} {10,7}", (r.Best ? "★ " : "  ") + r.Label, r.Setups, r.WinRate, m(r.PerSetup), r.ProfitFactor, m(r.TradePnl), m(-r.MaxDrawdown), r.FirstN == 0 ? "—" : m(r.FirstPerSetup), r.LaterN == 0 ? "—" : m(r.LaterPerSetup), r.PoolRan ? m(r.PoolNet) : "—", r.PoolRan ? r.PoolPayouts.ToString(CultureInfo.InvariantCulture) : "—"));
            sb.AppendLine(rep.Verdict);
            if (rep.Hours.Count > 0) sb.Append("BY HOUR (per setup): " + string.Join("  ", rep.Hours.Select(h => h.Label.Substring(0, 2) + " " + m(h.PerSetup) + "(" + h.Setups + ")")));
            return sb.ToString().TrimEnd();
        }
    }

    public sealed class KeystoneArcLiveSettings
    {
        public double StartBalance = 2000, RiskPercent = 1, DailyStopPercent = 2, MonthlyStopPercent = 6, WithdrawPercent = 0;
        public int MaxTradesPerDay = 1; public string TierFilter = "ALL"; public bool Compound = true;
        public bool FixedContracts;   // true = the strategy's own contracts and $ (no % sizing); MNQ and MGC may be open together
    }

    public sealed class KeystoneArcLiveMonth { public DateTime Month; public double StartBalance, EndBalance, Pnl, Withdrawn, ReturnPercent; public int Trades, Wins, Losses; public bool Stopped; }

    public sealed class KeystoneArcLiveResult
    {
        public double FinalBalance, Withdrawn, ReturnPercent, MaxDrawdownPercent, WorstDayPercent, PeakBalance;
        public int Trades, Wins, Losses, SkippedTier, SkippedDailyCap, SkippedDailyStop, SkippedMonthlyStop, SkippedAfterRuin;
        public bool Ruined; public DateTime RuinDate = DateTime.MinValue;
        public List<Tuple<DateTime, double>> Equity = new List<Tuple<DateTime, double>>();
        public List<KeystoneArcLiveMonth> Months = new List<KeystoneArcLiveMonth>();
        public List<KeystoneArcEvent> Taken = new List<KeystoneArcEvent>();
    }

    // LIVE ACCOUNT (personal, e.g. MT5 NAS100 / XAUUSD CFD): no targets, payouts or rotation. The balance is
    // the whole drawdown. Each trade risks RiskPercent of the balance: its result is the setup's own
    // result scaled by (risk $ ÷ the setup's risk $), so contract specs do not matter. One account,
    // the strongest setups only, a daily trade cap and daily / monthly loss stops.
    public static class KeystoneArcLiveAccount
    {
        static double SetupRisk(KeystoneArcEvent e, KeystoneArcRunConfig cfg)
        {
            double pv = string.Equals(e.Symbol, "MGC", StringComparison.OrdinalIgnoreCase) ? 10.0 : 2.0;
            double risk = e.StopDistance > 0 ? e.StopDistance * pv * Math.Max(1, e.Quantity) : 0;
            if (risk <= 0 && e.Stop > 0 && e.Entry > 0) risk = Math.Abs(e.Entry - e.Stop) * pv * Math.Max(1, e.Quantity);
            if (risk <= 0 && cfg != null) risk = Math.Abs(cfg.StopDollars);
            return Math.Max(1, risk);
        }

        public static KeystoneArcLiveResult Simulate(List<KeystoneArcEvent> events, KeystoneArcRunConfig cfg, KeystoneArcLiveSettings set)
        {
            var r = new KeystoneArcLiveResult();
            if (events == null || cfg == null || set == null) return r;
            double balance = Math.Max(1, set.StartBalance), peak = balance;
            r.PeakBalance = balance;
            Func<KeystoneArcEvent, DateTime> dayOf = e => KeystoneArcEngine.SessionGroupingDate(e.TriggerTime, cfg).Date;
            var done = events.Where(e => KeystoneArcStrategyCompare.Resolved(e) && string.Equals(e.ReviewState ?? "ACCEPTED", "ACCEPTED", StringComparison.OrdinalIgnoreCase)).OrderBy(e => e.EntryTime).ToList();
            DateTime day = DateTime.MinValue, month = DateTime.MinValue; double dayStart = balance, monthStart = balance; int dayTrades = 0; bool dayStopped = false, monthStopped = false;
            KeystoneArcLiveMonth cur = null;
            DateTime openUntil = DateTime.MinValue;
            var openBySymbol = new Dictionary<string, DateTime>(StringComparer.OrdinalIgnoreCase);
            Action closeMonth = () =>
            {
                if (cur == null) return;
                cur.EndBalance = balance;
                if (set.WithdrawPercent > 0 && cur.EndBalance > cur.StartBalance && !r.Ruined)
                {
                    double w = (cur.EndBalance - cur.StartBalance) * Math.Min(100, set.WithdrawPercent) / 100.0;
                    balance -= w; cur.Withdrawn = w; r.Withdrawn += w; cur.EndBalance = balance; peak = Math.Max(balance, peak - w);
                }
                cur.ReturnPercent = cur.StartBalance <= 0 ? 0 : 100.0 * cur.Pnl / cur.StartBalance;
                r.Months.Add(cur);
            };
            foreach (var e in done)
            {
                DateTime d = dayOf(e); DateTime m = new DateTime(d.Year, d.Month, 1);
                if (m != month) { closeMonth(); month = m; monthStart = balance; monthStopped = false; cur = new KeystoneArcLiveMonth { Month = m, StartBalance = balance }; }
                if (d != day)
                {
                    if (day != DateTime.MinValue) { r.Equity.Add(Tuple.Create(day, balance)); r.WorstDayPercent = Math.Min(r.WorstDayPercent, dayStart <= 0 ? 0 : 100.0 * (balance - dayStart) / dayStart); }
                    day = d; dayStart = balance; dayTrades = 0; dayStopped = false;
                }
                if (r.Ruined) { r.SkippedAfterRuin++; continue; }
                if (!KeystoneArcQualityLearner.TierAllowed(set.TierFilter, e.QualityTier)) { r.SkippedTier++; continue; }
                if (monthStopped) { r.SkippedMonthlyStop++; continue; }
                if (dayStopped) { r.SkippedDailyStop++; continue; }
                if (dayTrades >= Math.Max(1, set.MaxTradesPerDay)) { r.SkippedDailyCap++; continue; }
                DateTime busy = set.FixedContracts ? (openBySymbol.ContainsKey(e.Symbol ?? string.Empty) ? openBySymbol[e.Symbol ?? string.Empty] : DateTime.MinValue) : openUntil;
                if (e.EntryTime < busy) { r.SkippedDailyCap++; continue; } // one position at a time (per instrument with fixed contracts)
                double riskDollars = (set.Compound ? balance : set.StartBalance) * Math.Max(0, set.RiskPercent) / 100.0;
                double pnl = set.FixedContracts ? e.GrossPnl : e.GrossPnl * riskDollars / SetupRisk(e, cfg);
                balance += pnl; dayTrades++; r.Trades++; if (pnl > 0) r.Wins++; else if (pnl < 0) r.Losses++;
                cur.Trades++; cur.Pnl += pnl; if (pnl > 0) cur.Wins++; else if (pnl < 0) cur.Losses++;
                openUntil = e.ExitTime == DateTime.MinValue ? e.EntryTime : e.ExitTime;
                openBySymbol[e.Symbol ?? string.Empty] = openUntil;
                var t = e.CopyForPool(); t.GrossPnl = pnl; t.AssignedVirtualAccount = "LIVE"; r.Taken.Add(t);
                peak = Math.Max(peak, balance); r.PeakBalance = Math.Max(r.PeakBalance, balance);
                r.MaxDrawdownPercent = Math.Max(r.MaxDrawdownPercent, peak <= 0 ? 0 : 100.0 * (peak - balance) / peak);
                if (set.DailyStopPercent > 0 && balance <= dayStart * (1 - set.DailyStopPercent / 100.0)) dayStopped = true;
                if (set.MonthlyStopPercent > 0 && balance <= monthStart * (1 - set.MonthlyStopPercent / 100.0)) { monthStopped = true; cur.Stopped = true; }
                if (balance <= 0) { r.Ruined = true; r.RuinDate = d; balance = 0; }
            }
            if (day != DateTime.MinValue) { r.Equity.Add(Tuple.Create(day, balance)); r.WorstDayPercent = Math.Min(r.WorstDayPercent, dayStart <= 0 ? 0 : 100.0 * (balance - dayStart) / dayStart); }
            closeMonth();
            r.FinalBalance = balance;
            r.ReturnPercent = 100.0 * (balance + r.Withdrawn - set.StartBalance) / Math.Max(1, set.StartBalance);
            return r;
        }

        public static string Summary(KeystoneArcLiveResult r, KeystoneArcLiveSettings set)
        {
            Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            var sb = new StringBuilder();
            sb.AppendLine("LIVE ACCOUNT • start " + m(set.StartBalance) + " • risk " + set.RiskPercent.ToString("0.##", CultureInfo.InvariantCulture) + "% per trade" + (set.Compound ? " (of the current balance)" : " (of the start balance)") + " • max " + set.MaxTradesPerDay + " trade(s)/day • setups " + set.TierFilter + " • daily stop " + set.DailyStopPercent.ToString("0.#", CultureInfo.InvariantCulture) + "% • monthly stop " + set.MonthlyStopPercent.ToString("0.#", CultureInfo.InvariantCulture) + "%");
            sb.AppendLine("RESULT • balance " + m(r.FinalBalance) + (r.Withdrawn > 0 ? " + withdrawn " + m(r.Withdrawn) : "") + " • return " + r.ReturnPercent.ToString("0.#", CultureInfo.InvariantCulture) + "% • max drawdown " + r.MaxDrawdownPercent.ToString("0.#", CultureInfo.InvariantCulture) + "% • worst day " + r.WorstDayPercent.ToString("0.#", CultureInfo.InvariantCulture) + "% • " + r.Trades + " trades (" + r.Wins + " W / " + r.Losses + " L)" + (r.Ruined ? " • ACCOUNT LOST on " + r.RuinDate.ToString("yyyy-MM-dd") : ""));
            sb.AppendLine("SKIPPED • grade filter " + r.SkippedTier + " • daily trade cap / position open " + r.SkippedDailyCap + " • daily stop " + r.SkippedDailyStop + " • monthly stop " + r.SkippedMonthlyStop);
            foreach (var mo in r.Months) sb.AppendLine(string.Format(CultureInfo.InvariantCulture, "{0:MMM yyyy}  {1,8}  {2,6:0.0}%  {3,3} trades {4}/{5}{6}{7}", mo.Month, m(mo.Pnl), mo.ReturnPercent, mo.Trades, mo.Wins, mo.Losses, mo.Stopped ? "  MONTHLY STOP HIT" : "", mo.Withdrawn > 0 ? "  withdrew " + m(mo.Withdrawn) : ""));
            return sb.ToString().TrimEnd();
        }
    }

    public sealed class KeystoneArcInsight
    {
        public string Level;   // GOOD, WARN, BAD, IDEA
        public string Title;
        public string Text;
    }

    // Automatic analysis: plain-English conclusions and suggestions drawn only from the loaded
    // run (no outside data, no promises). Every sentence can be traced to a number in the report.
    public sealed class KeystoneArcFilterRow
    {
        public string Filter = "ALL", Label = "ALL SETUPS";
        public int Setups, Wins, Days;
        public double WinRate, PerSetup, ProfitFactor, MaxDrawdown, WorstDay, PerDay, DaysToEvalTarget = double.NaN, Total;
        public bool EvalPick, FundedPick;
    }

    public sealed class KeystoneArcBestEntryPlan
    {
        public List<KeystoneArcFilterRow> Filters = new List<KeystoneArcFilterRow>();
        public List<KeystoneArcInsight> Cards = new List<KeystoneArcInsight>();
        public string EvalFilter = "ALL", FundedFilter = "ALL";
        public string Headline = string.Empty;
    }

    public static class KeystoneArcAnalyst
    {
        static string M(double v) { return (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture); }
        static string P(double v) { return v.ToString("0", CultureInfo.InvariantCulture) + "%"; }
        static void Add(List<KeystoneArcInsight> list, string level, string title, string text) { list.Add(new KeystoneArcInsight { Level = level, Title = title, Text = text }); }

        // OPTIMAL BEST ENTRIES FOR PROP: which setup grades to trade while passing an evaluation
        // (reach the target fastest without breaking the drawdown) and while funded (safest steady
        // profit), plus the best entry hours, setup types and data-based stop / target points.
        // Everything is measured on this run's finished setups; grades are walk-forward (no look-ahead).
        public static KeystoneArcBestEntryPlan BestEntries(IEnumerable<KeystoneArcEvent> events, KeystoneArcRunConfig cfg, List<KeystoneArcPoolScenario> accountRows, List<KeystoneArcStrategyRow> strategyRows)
        {
            var plan = new KeystoneArcBestEntryPlan();
            if (cfg == null) return plan;
            bool asian = string.Equals(cfg.StrategyCode, "ASIAN75", StringComparison.OrdinalIgnoreCase);
            bool fvg = string.Equals(cfg.StrategyCode, "FVG", StringComparison.OrdinalIgnoreCase);
            var ev = (events ?? Enumerable.Empty<KeystoneArcEvent>()).Where(e => e != null && KeystoneArcStrategyCompare.Resolved(e) && string.Equals(e.ReviewState ?? "ACCEPTED", "ACCEPTED", StringComparison.OrdinalIgnoreCase)).OrderBy(e => e.EntryTime).ToList();
            if (ev.Count == 0) { plan.Headline = "Not enough finished setups yet for a recommendation."; return plan; }
            int rangeDays = Math.Max(1, ev.Select(e => KeystoneArcEngine.SessionGroupingDate(e.TriggerTime, cfg)).Distinct().Count());
            double evalRoom = Math.Abs(cfg.EvaluationFailure), fundedRoom = Math.Abs(cfg.FundedFailure);
            var labels = new Dictionary<string, string> { { "ALL", "ALL SETUPS" }, { "AB", "GRADE A + B (+DT)" }, { "A", "GRADE A (+DT)" }, { "DT", "DOUBLE TROUBLE ONLY" } };
            foreach (string f in asian ? new[] { "ALL" } : new[] { "ALL", "AB", "A", "DT" })
            {
                var rows = ev.Where(e => KeystoneArcQualityLearner.TierAllowed(f, e.QualityTier)).ToList();
                var r = new KeystoneArcFilterRow { Filter = f, Label = labels[f], Setups = rows.Count };
                if (rows.Count > 0)
                {
                    r.Wins = rows.Count(e => e.Outcome == "WIN"); r.WinRate = 100.0 * r.Wins / rows.Count; r.Total = rows.Sum(e => e.GrossPnl); r.PerSetup = r.Total / rows.Count;
                    double gw = rows.Where(e => e.GrossPnl > 0).Sum(e => e.GrossPnl), gl = -rows.Where(e => e.GrossPnl < 0).Sum(e => e.GrossPnl);
                    r.ProfitFactor = gl <= 0 ? (gw > 0 ? 99 : 0) : gw / gl;
                    double eq = 0, peak = 0; foreach (var e in rows) { eq += e.GrossPnl; peak = Math.Max(peak, eq); r.MaxDrawdown = Math.Max(r.MaxDrawdown, peak - eq); }
                    var byDay = rows.GroupBy(e => KeystoneArcEngine.SessionGroupingDate(e.TriggerTime, cfg)).Select(g => g.Sum(e => e.GrossPnl)).ToList();
                    r.Days = byDay.Count; r.WorstDay = byDay.Min(); r.PerDay = r.Total / rangeDays;
                    if (r.PerDay > 0 && cfg.EvaluationTarget > 0) r.DaysToEvalTarget = cfg.EvaluationTarget / r.PerDay;
                }
                if (f == "ALL" || r.Setups > 0) plan.Filters.Add(r);
            }
            // Evaluation: fastest to the target while the drawdown stays inside the evaluation limit.
            var evalCandidates = plan.Filters.Where(r => r.Setups >= 10 && r.PerDay > 0).ToList();
            var evalPick = evalCandidates.Where(r => evalRoom <= 0 || r.MaxDrawdown < evalRoom).OrderBy(r => r.DaysToEvalTarget).FirstOrDefault()
                ?? evalCandidates.OrderBy(r => r.MaxDrawdown).FirstOrDefault();
            // Funded: best profit per setup with a profit factor above 1 and a drawdown inside the funded limit.
            var fundedCandidates = plan.Filters.Where(r => r.Setups >= 10 && r.ProfitFactor > 1).ToList();
            var fundedPick = fundedCandidates.Where(r => fundedRoom <= 0 || r.MaxDrawdown < fundedRoom).OrderByDescending(r => r.PerSetup).ThenByDescending(r => r.ProfitFactor).FirstOrDefault()
                ?? fundedCandidates.OrderByDescending(r => r.ProfitFactor).FirstOrDefault();
            if (evalPick != null) { evalPick.EvalPick = true; plan.EvalFilter = evalPick.Filter; }
            if (fundedPick != null) { fundedPick.FundedPick = true; plan.FundedFilter = fundedPick.Filter; }
            if (asian)
            {
                var only = plan.Filters.FirstOrDefault();
                Add(plan.Cards, "IDEA", "ASIAN CYCLES ARE NOT GRADED", "Every night trades the same cycle, so there is no grade filter to pick. " + (only == null ? "" : only.Setups + " legs, " + M(only.PerDay) + " per night, worst drawdown " + M(-only.MaxDrawdown) + (fundedRoom > 0 ? (only.MaxDrawdown < fundedRoom ? " — inside" : " — LARGER than") + " the " + M(fundedRoom) + " funded limit" : "") + ". ") + "Tune the risk (loss per leg, reversals, cycle target, daily loss) with the ASIAN 75 OPTIMIZER and keep the drawdown under the account limit.");
                evalPick = null; fundedPick = null;
                foreach (var r in plan.Filters) { r.EvalPick = false; r.FundedPick = false; }
            }
            else if (evalPick != null)
                Add(plan.Cards, evalRoom > 0 && evalPick.MaxDrawdown >= evalRoom ? "WARN" : "BEST", "EVALUATION • TRADE " + evalPick.Label, evalPick.Setups + " setups, " + P(evalPick.WinRate) + " win, " + M(evalPick.PerDay) + " per " + (asian ? "night" : "day") + " on one account → about " + (double.IsNaN(evalPick.DaysToEvalTarget) ? "—" : evalPick.DaysToEvalTarget.ToString("0", CultureInfo.InvariantCulture)) + " trading days to the " + M(cfg.EvaluationTarget) + " target; its worst drawdown " + M(-evalPick.MaxDrawdown) + (evalRoom > 0 ? (evalPick.MaxDrawdown < evalRoom ? " stays inside" : " is LARGER than") + " the " + M(evalRoom) + " evaluation limit" : "") + ". Set Pool Settings → EVALUATION TRADES = " + evalPick.Label + ".");
            else if (!asian) Add(plan.Cards, "WARN", "EVALUATION", "No grade filter makes money per day on this range yet — an evaluation would not pass reliably. Test a longer range or other stop / target settings.");
            if (asian) { }
            else if (fundedPick != null)
                Add(plan.Cards, fundedRoom > 0 && fundedPick.MaxDrawdown >= fundedRoom ? "WARN" : "BEST", "FUNDED • TRADE " + fundedPick.Label, M(fundedPick.PerSetup) + " per setup, profit factor " + fundedPick.ProfitFactor.ToString("0.00", CultureInfo.InvariantCulture) + ", worst day " + M(fundedPick.WorstDay) + ", drawdown " + M(-fundedPick.MaxDrawdown) + (fundedRoom > 0 ? " vs " + M(fundedRoom) + " funded limit" : "") + ". Set FUNDED TRADES = " + fundedPick.Label + " to protect the account between payouts." + (fundedRoom > 0 && fundedPick.MaxDrawdown >= fundedRoom ? " Its drawdown is larger than the funded limit: reduce size (fewer contracts / smaller stop) before trading it funded." : ""));
            else Add(plan.Cards, "WARN", "FUNDED", "No grade filter has a profit factor above 1 with at least 10 setups — funded accounts would lose money on this range.");
            // Best entry hours (NY time).
            if (!asian)
            {
                var hours = ev.GroupBy(e => e.EntryTime.Hour).Select(g => new { Hour = g.Key, Count = g.Count(), Avg = g.Average(e => e.GrossPnl), Win = 100.0 * g.Count(e => e.Outcome == "WIN") / g.Count() }).Where(h => h.Count >= 5).OrderByDescending(h => h.Avg).ToList();
                var good = hours.Where(h => h.Avg > 0).Take(3).OrderBy(h => h.Hour).ToList();
                if (good.Count > 0)
                    Add(plan.Cards, "BEST", "BEST ENTRY HOURS (NY)", string.Join(" • ", good.Select(h => h.Hour.ToString("00") + ":00–" + h.Hour.ToString("00") + ":59 " + M(h.Avg) + "/setup, " + P(h.Win) + " win (" + h.Count + ")")) + "." + (hours.Any(h => h.Avg < 0) ? " Avoid: " + string.Join(", ", hours.Where(h => h.Avg < 0).OrderBy(h => h.Avg).Take(2).Select(h => h.Hour.ToString("00") + ":00 " + M(h.Avg) + "/setup")) + "." : ""));
            }
            // Setup types.
            var dt = ev.Where(e => e.QualityTier == "DT").ToList(); var rest = ev.Where(e => e.QualityTier != "DT").ToList();
            if (dt.Count >= 3 && rest.Count > 0)
                Add(plan.Cards, dt.Average(e => e.GrossPnl) > rest.Average(e => e.GrossPnl) ? "BEST" : "IDEA", "DOUBLE TROUBLE", dt.Count + " setups, " + P(100.0 * dt.Count(e => e.Outcome == "WIN") / dt.Count) + " win, " + M(dt.Average(e => e.GrossPnl)) + " per setup vs " + M(rest.Average(e => e.GrossPnl)) + " for the rest.");
            if (fvg)
            {
                var stacked = ev.Where(e => (e.ReviewNote ?? string.Empty).Contains("STACKED ZONE")).ToList(); var single = ev.Where(e => !(e.ReviewNote ?? string.Empty).Contains("STACKED ZONE")).ToList();
                if (stacked.Count >= 3 && single.Count > 0) Add(plan.Cards, "IDEA", "STACKED FVG ZONES", stacked.Count + " entries from merged zones: " + M(stacked.Average(e => e.GrossPnl)) + " per setup vs " + M(single.Average(e => e.GrossPnl)) + " for single boxes.");
                var first = ev.Where(e => e.FvgVisit <= 1).ToList(); var later = ev.Where(e => e.FvgVisit >= 2).ToList();
                if (first.Count >= 5 && later.Count >= 5) Add(plan.Cards, first.Average(e => e.GrossPnl) >= later.Average(e => e.GrossPnl) ? "IDEA" : "BEST", "FIRST TRY vs RETRIES", "1st try " + M(first.Average(e => e.GrossPnl)) + "/setup (" + first.Count + "), 2nd+ try " + M(later.Average(e => e.GrossPnl)) + "/setup (" + later.Count + ")." + (later.Average(e => e.GrossPnl) < 0 ? " Retries lose: set TRIES PER BOX = 1." : ""));
            }
            if (string.Equals(cfg.StrategyCode, "ENG", StringComparison.OrdinalIgnoreCase))
            {
                Func<IEnumerable<KeystoneArcEvent>, string> sum = xs => { var l = xs.ToList(); return l.Count == 0 ? "—" : l.Count + " • " + P(100.0 * l.Count(e => e.Outcome == "WIN") / l.Count) + " win • " + M(l.Average(e => e.GrossPnl)) + "/setup"; };
                Add(plan.Cards, "BEST", "ENGULFING • BUY vs SELL", "BUY " + sum(ev.Where(e => !string.Equals(e.Direction, "SHORT", StringComparison.OrdinalIgnoreCase))) + "  |  SELL " + sum(ev.Where(e => string.Equals(e.Direction, "SHORT", StringComparison.OrdinalIgnoreCase))) + ".");
                Add(plan.Cards, "BEST", "ENGULFING • HOW STRONG", string.Join("  |  ", new[] { "BODY", "WICK", "SWEEP", "SWEEP+WICK" }.Select(t => t + " " + sum(ev.Where(e => e.StrengthTag == t)))) + ". If SWEEP / WICK clearly beat BODY, set WHICH SETUPS to STRONG for funded or live accounts and keep ALL for evaluations.");
                Add(plan.Cards, "IDEA", "ENGULFING • PRE-NY vs NY OPEN", "08:00–09:29 " + sum(ev.Where(e => e.EntryTime.Hour * 100 + e.EntryTime.Minute >= 800 && e.EntryTime.Hour * 100 + e.EntryTime.Minute < 930)) + "  |  09:30–10:59 " + sum(ev.Where(e => e.EntryTime.Hour * 100 + e.EntryTime.Minute >= 930 && e.EntryTime.Hour * 100 + e.EntryTime.Minute < 1100)) + "  |  later " + sum(ev.Where(e => e.EntryTime.Hour * 100 + e.EntryTime.Minute >= 1100)) + ".");
            }
            // Data-based stop / target points per instrument (price moves after entry, long setups).
            // Not for Asian: a cycle leg's high includes the whole night, not one trade.
            foreach (var bySymbol in ev.Where(e => !asian).Where(e => !double.IsNaN(e.PeakAfterEntry) && !double.IsNaN(e.TroughAfterEntry) && e.Entry > 0 && !string.Equals(e.Direction, "SHORT", StringComparison.OrdinalIgnoreCase)).GroupBy(e => e.Symbol))
            {
                var winners = bySymbol.Where(e => e.Outcome == "WIN").ToList(); var losers = bySymbol.Where(e => e.Outcome.StartsWith("LOSS", StringComparison.OrdinalIgnoreCase)).ToList();
                if (winners.Count < 5) continue;
                Func<List<double>, double, double> pct = (list, q) => { var o = list.OrderBy(v => v).ToList(); return o.Count == 0 ? double.NaN : o[Math.Min(o.Count - 1, (int)Math.Floor(q * (o.Count - 1) + 0.5))]; };
                double heat = pct(winners.Select(e => Math.Max(0, e.Entry - e.TroughAfterEntry)).ToList(), 0.8);
                double move = pct(winners.Select(e => Math.Max(0, e.PeakAfterEntry - e.Entry)).ToList(), 0.5);
                double pv = string.Equals(bySymbol.Key, "MGC", StringComparison.OrdinalIgnoreCase) ? 10.0 : 2.0; double qty = Math.Max(1, bySymbol.Average(e => e.Quantity));
                string text = "80% of winners never went more than " + heat.ToString("0.##", CultureInfo.InvariantCulture) + " pts against the entry; half of winners moved " + move.ToString("0.##", CultureInfo.InvariantCulture) + "+ pts in favour. Data-based start: STOP ≈ " + (heat * 1.1).ToString("0.#", CultureInfo.InvariantCulture) + " pts, TARGET ≈ " + move.ToString("0.#", CultureInfo.InvariantCulture) + " pts (" + qty.ToString("0", CultureInfo.InvariantCulture) + " contracts ≈ " + M(-heat * 1.1 * pv * qty) + " / +" + M(move * pv * qty) + ").";
                if (losers.Count >= 5)
                {
                    double loserUp = pct(losers.Select(e => Math.Max(0, e.PeakAfterEntry - e.Entry)).ToList(), 0.5);
                    text += " Half of the losers first moved +" + loserUp.ToString("0.##", CultureInfo.InvariantCulture) + " pts before stopping out" + (loserUp > 0 && loserUp < move ? " — a partial take-profit there would have saved many of them (estimate)." : ".");
                }
                Add(plan.Cards, "BEST", bySymbol.Key + " STOP / TARGET FROM PRICE MOVES", text);
            }
            // Account plan and strategy winner from the comparisons, when they were run.
            var bestAcc = accountRows == null ? null : accountRows.FirstOrDefault(r => r.Best);
            if (bestAcc != null) Add(plan.Cards, "BEST", "ACCOUNTS • " + bestAcc.Label, "Best of the account comparison: net " + M(bestAcc.Net) + ", " + bestAcc.Payouts + " payouts, " + bestAcc.Blowups + " blowups, ~" + bestAcc.TradesPerAccount.ToString("0", CultureInfo.InvariantCulture) + " trades per account" + (bestAcc.FirstPayout == DateTime.MinValue ? "." : ", first payout " + bestAcc.FirstPayout.ToString("yyyy-MM-dd") + "."));
            else if (accountRows == null || accountRows.Count == 0) Add(plan.Cards, "IDEA", "ACCOUNTS", "Press COMPARE ACCOUNTS in the lab to add the best account count / allocation to this plan.");
            var bestStrategy = strategyRows == null ? null : strategyRows.FirstOrDefault(r => r.Best);
            if (bestStrategy != null) Add(plan.Cards, "BEST", "STRATEGY • " + bestStrategy.Strategy, "Won the strategy comparison: " + (bestStrategy.PoolRan && bestStrategy.Net > 0 ? "net " + M(bestStrategy.Net) : "trade P/L " + M(bestStrategy.TradePnl)) + ", " + P(bestStrategy.WinRate) + " win, profit factor " + bestStrategy.ProfitFactor.ToString("0.00", CultureInfo.InvariantCulture) + ".");
            plan.Headline = (asian ? "PROP PLAN • ASIAN CYCLE: tune risk with the optimizer (no grades)" : "PROP PLAN • EVALUATION: " + (evalPick == null ? "no reliable filter" : evalPick.Label) + " • FUNDED: " + (fundedPick == null ? "no profitable filter" : fundedPick.Label)) + (bestAcc != null ? " • ACCOUNTS: " + bestAcc.Label : string.Empty) + (bestStrategy != null ? " • STRATEGY: " + bestStrategy.Strategy : string.Empty);
            return plan;
        }

        // GOLDEN SETUP: does the push down matter, BH vs FVG, and how big the stops are.
        private static void AddGoldenInsights(List<KeystoneArcInsight> list, List<KeystoneArcEvent> ev)
        {
            if (ev.Count == 0) return;
            Func<IEnumerable<KeystoneArcEvent>, string> line = delegate(IEnumerable<KeystoneArcEvent> set)
            {
                var l = set.ToList(); if (l.Count == 0) return "none";
                int w = l.Count(e => e.Outcome == "WIN"), lo = l.Count(e => e.Outcome != null && e.Outcome.StartsWith("LOSS"));
                return l.Count + " trades • " + w + " W / " + lo + " L / " + (l.Count - w - lo) + " end • " + P(100.0 * w / Math.Max(1, w + lo)) + " won • " + M(l.Sum(e => e.GrossPnl));
            };
            foreach (string sym in new[] { "MNQ", "MGC" })
            {
                var s = ev.Where(e => string.Equals(e.Symbol, sym, StringComparison.OrdinalIgnoreCase)).ToList(); if (s.Count == 0) continue;
                var aggr = s.Where(e => e.StrengthTag == "AGGR").ToList(); var calm = s.Where(e => e.StrengthTag != "AGGR").ToList();
                double wa = aggr.Count == 0 ? 0 : 100.0 * aggr.Count(e => e.Outcome == "WIN") / Math.Max(1, aggr.Count(e => e.Outcome == "WIN" || (e.Outcome ?? "").StartsWith("LOSS")));
                double wc = calm.Count == 0 ? 0 : 100.0 * calm.Count(e => e.Outcome == "WIN") / Math.Max(1, calm.Count(e => e.Outcome == "WIN" || (e.Outcome ?? "").StartsWith("LOSS")));
                Add(list, aggr.Sum(e => e.GrossPnl) > calm.Sum(e => e.GrossPnl) ? "GOOD" : "IDEA", sym + " • WITH vs WITHOUT A PUSH DOWN", "With aggression: " + line(aggr) + ". Without: " + line(calm) + "." + (aggr.Count >= 20 && calm.Count >= 20 ? (wa > wc + 5 ? " The push down clearly helps — try PUSH DOWN = REQUIRED." : wc > wa + 5 ? " Setups without a push down did better here." : " Little difference so far.") : " Needs more trades to judge."));
                Add(list, "IDEA", sym + " • BH vs FVG", "BH: " + line(s.Where(e => e.SetupClass == "BH")) + ". FVG: " + line(s.Where(e => e.SetupClass == "FVG")) + ". Both on one candle: " + line(s.Where(e => e.SetupClass == "DT")) + ".");
                var stops = s.Where(e => e.StopDistance > 0).Select(e => e.StopDistance).OrderBy(x => x).ToList();
                if (stops.Count > 0)
                {
                    double med = stops[stops.Count / 2], big = stops[Math.Min(stops.Count - 1, (int)(stops.Count * 0.9))];
                    var small = s.Where(e => e.StopDistance > 0 && e.StopDistance <= med).ToList(); var large = s.Where(e => e.StopDistance > med).ToList();
                    Add(list, "IDEA", sym + " • STOP SIZE", "Typical stop " + med.ToString("0.##", CultureInfo.InvariantCulture) + " pts (90% are under " + big.ToString("0.##", CultureInfo.InvariantCulture) + "). Small stops: " + line(small) + ". Big stops: " + line(large) + ". If big stops lose, set SKIP IF THE STOP IS BIGGER THAN.");
                }
                var byTry = s.GroupBy(e => e.SessionOrder).OrderBy(g => g.Key).ToList();
                if (byTry.Count > 1) Add(list, "IDEA", sym + " • FIRST vs LATER TRIES", string.Join(" • ", byTry.Select(g => (g.Key == 1 ? "1st" : g.Key == 2 ? "2nd" : g.Key + "th") + ": " + line(g))));
            }
        }

        public static List<KeystoneArcInsight> Analyze(List<KeystoneArcVirtualAccount> accounts, IEnumerable<KeystoneArcEvent> events, KeystoneArcRunConfig cfg, KeystoneArcCapitalPolicySummary capital)
        {
            var list = new List<KeystoneArcInsight>();
            if (cfg == null) return list;
            bool asian = string.Equals(cfg.StrategyCode, "ASIAN75", StringComparison.OrdinalIgnoreCase);
            bool fvg = string.Equals(cfg.StrategyCode, "FVG", StringComparison.OrdinalIgnoreCase);
            string unit = asian ? "night" : "day";
            var ev = (events ?? Enumerable.Empty<KeystoneArcEvent>()).Where(e => e != null && e.Outcome != "UNVERIFIED 1M" && string.Equals(e.ReviewState ?? "ACCEPTED", "ACCEPTED", StringComparison.OrdinalIgnoreCase)).ToList();
            var days = KeystoneArcScoreboard.Days(ev, cfg);
            var acc = accounts ?? new List<KeystoneArcVirtualAccount>();
            KeystoneArcPoolInsights x = acc.Count > 0 ? KeystoneArcPoolInsights.Build(acc, ev, cfg) : null;

            if (string.Equals(cfg.StrategyCode, "GLD", StringComparison.OrdinalIgnoreCase)) AddGoldenInsights(list, ev);
            // 1. Strategy edge (no accounts).
            if (days.Count > 0)
            {
                double total = days.Sum(d => d.Pnl); int win = days.Count(d => d.Pnl > 0);
                double eq = 0, peak = 0, dd = 0; foreach (var d in days) { eq += d.Pnl; peak = Math.Max(peak, eq); dd = Math.Max(dd, peak - eq); }
                Add(list, total > 0 ? "GOOD" : "BAD", "STRATEGY EDGE", "Over " + days.Count + " " + unit + "s the strategy made " + M(total) + " on one account before prop rules (" + P(100.0 * win / days.Count) + " winning " + unit + "s, average " + M(total / days.Count) + " per " + unit + "). Deepest drawdown " + M(-dd) + ".");
                if (cfg.CommissionPerContract <= 0 && cfg.SlippageTicks <= 0)
                {
                    // What the same trades would cost at a typical micro commission ($1.50 round
                    // trip per contract) and one tick of slippage each side.
                    var probe = cfg.ShallowCopy(); probe.CommissionPerContract = 1.5; probe.SlippageTicks = 1;
                    var traded = ev.Where(e => { string o = e.Outcome ?? string.Empty; return o == "WIN" || o.StartsWith("LOSS", StringComparison.OrdinalIgnoreCase) || o == "SESSION EXIT" || o == "BREAKEVEN"; }).ToList();
                    double realCost = traded.Sum(e => KeystoneArcEngine.TradingCost(e, probe));
                    if (traded.Count > 0)
                        Add(list, "BAD", "NO COSTS MODELLED", "Commission and slippage are both 0. The " + traded.Count.ToString("N0", CultureInfo.InvariantCulture) + " trades would cost about " + M(realCost) + " at $1.50 per contract round trip plus 1 tick slippage each side (" + M(total - realCost) + " after costs on one account). Set COMMISSION and SLIPPAGE in the lab and re-run before trusting the payouts.");
                }
                if (total < 0 && capital != null && capital.FullNetCashAfterAllCosts > 0)
                    Add(list, "BAD", "POOL PROFIT FROM A LOSING STRATEGY", "The strategy lost " + M(total) + " on one account, yet the pool shows " + M(capital.FullNetCashAfterAllCosts) + ". That money comes from payout rules collecting the lucky accounts' gains while the losing accounts are simply replaced — it depends on cheap accounts, unlimited replacements and payout rules being exactly as modelled. Real firms add consistency rules, payout caps and account limits that this does not survive reliably.");
                double accountRoom = Math.Abs(cfg.FundedFailure > 0 ? cfg.FundedFailure : cfg.EvaluationFailure);
                if (accountRoom > 0 && dd > accountRoom)
                    Add(list, "WARN", "DRAWDOWN BIGGER THAN THE ACCOUNT", "The strategy's own drawdown (" + M(-dd) + ") is larger than the account drawdown limit (" + M(accountRoom) + "), so blowups are expected. Smaller size, a tighter daily loss, or fewer reversals/setups per day reduce that.");
                // Edge over time: compare halves.
                var months = days.GroupBy(d => new DateTime(d.Day.Year, d.Day.Month, 1)).OrderBy(g => g.Key).Select(g => new { Month = g.Key, Pnl = g.Sum(d => d.Pnl) }).ToList();
                if (months.Count >= 4)
                {
                    int half = months.Count / 2;
                    double first = months.Take(half).Sum(m => m.Pnl), second = months.Skip(half).Sum(m => m.Pnl);
                    if (first > 0 && second < 0) Add(list, "WARN", "EDGE FADED", "The first " + half + " months made " + M(first) + " but the last " + (months.Count - half) + " months lost " + M(second) + ". Results are front-loaded; test a later range on its own before trusting these settings.");
                    else if (first < 0 && second > 0) Add(list, "IDEA", "EDGE IMPROVED LATER", "The first " + half + " months lost " + M(first) + ", the last " + (months.Count - half) + " made " + M(second) + ". Check whether the market changed or the early period was unusual.");
                    var best = months.OrderByDescending(m => m.Pnl).First(); var worst = months.OrderBy(m => m.Pnl).First();
                    Add(list, "IDEA", "BEST / WORST MONTH", "Best month " + best.Month.ToString("MMM yyyy", CultureInfo.InvariantCulture) + " " + M(best.Pnl) + ", worst " + worst.Month.ToString("MMM yyyy", CultureInfo.InvariantCulture) + " " + M(worst.Pnl) + ". " + months.Count(m => m.Pnl > 0) + " of " + months.Count + " months were positive.");
                }
                // Day of week.
                var dow = days.GroupBy(d => d.Day.DayOfWeek).Select(g => new { Day = g.Key, Pnl = g.Sum(d => d.Pnl), Count = g.Count() }).Where(g => g.Count >= 4).OrderBy(g => g.Pnl).ToList();
                if (dow.Count >= 3 && dow[0].Pnl < 0 && dow.Last().Pnl > 0)
                    Add(list, "IDEA", "DAY OF THE WEEK", dow.Last().Day + " was the best " + unit + " (" + M(dow.Last().Pnl) + " over " + dow.Last().Count + "), " + dow[0].Day + " the worst (" + M(dow[0].Pnl) + " over " + dow[0].Count + "). Worth testing without " + dow[0].Day + ".");
            }
            // 2. Instruments.
            var inst = KeystoneArcPoolInsights.InstrumentStats(ev, cfg);
            if (inst.Count == 2)
            {
                var good = inst.OrderByDescending(v => v.Pnl).First(); var bad = inst.OrderBy(v => v.Pnl).First();
                if (bad.Pnl < 0 && good.Pnl > 0) Add(list, "IDEA", "TRADE " + good.Symbol + " ONLY?", good.Symbol + " made " + M(good.Pnl) + " while " + bad.Symbol + " lost " + M(bad.Pnl) + ". Use the MNQ / MGC switch to see the pool with " + good.Symbol + " alone.");
                else Add(list, "IDEA", "INSTRUMENTS", string.Join(" • ", inst.Select(v => v.Symbol + " " + M(v.Pnl) + " (" + P(v.WinRate) + " win)")) + ".");
            }
            // 3. Money and accounts.
            if (x != null && capital != null)
            {
                if (!capital.FirstPayoutReached) Add(list, "BAD", "NO PAYOUT", "No account reached a payout in this range; " + M(x.Cost) + " was spent on accounts. The strategy or the prop rules (payout balance " + M(cfg.PayoutThreshold) + ", drawdown " + M(cfg.FundedFailure) + ") do not fit together yet.");
                else
                {
                    double extra = capital.InvestmentThroughFirstPayoutDate - capital.InitialEvaluationInvestment;
                    Add(list, extra <= 0.5 ? "GOOD" : "WARN", "MONEY TO FIRST PAYOUT", "First payout " + capital.FirstPayoutDate.ToString("yyyy-MM-dd") + " after " + M(capital.InvestmentThroughFirstPayoutDate) + " spent" + (extra <= 0.5 ? " — the initial investment alone was enough." : " — " + M(extra) + " more than the initial " + M(capital.InitialEvaluationInvestment) + "."));
                    Add(list, x.Net > 0 ? "GOOD" : "BAD", "NET RESULT", "To your bank " + M(x.CashAfterShare) + ", all accounts cost " + M(x.Cost) + ", net " + M(x.Net) + (capital.ProfitabilityReached ? " • profitable from " + capital.ProfitabilityDate.ToString("yyyy-MM-dd") : " • never paid back") + ".");
                    if (x.Payouts > 0) Add(list, "IDEA", "COST PER PAYOUT", "Each payout cost " + M(x.Cost / x.Payouts) + " in accounts on average; every $1 spent returned " + (x.Cost > 0 ? (x.CashAfterShare / x.Cost).ToString("0.0", CultureInfo.InvariantCulture) + "×" : "—") + ". " + x.PaidAccounts + " of " + x.Accounts + " slots were paid at least once.");
                }
                if (x.BlowupEvents > 0)
                {
                    string where = x.EvaluationFails >= x.FundedBlowups ? "mostly during evaluations (" + x.EvaluationFails + " of " + x.BlowupEvents + ")" : "mostly on funded accounts (" + x.FundedBlowups + " of " + x.BlowupEvents + ")";
                    Add(list, x.BlowupEvents > x.Payouts ? "WARN" : "IDEA", "BLOWUPS", x.BlowupEvents + " blowups, " + where + ". " + (x.FundedBlowups > x.EvaluationFails ? "Funded accounts blow before reaching the payout balance: a lower payout balance or smaller size would convert more of them." : "Evaluations fail more than they pass: consider passing evaluations with a steadier setting and trading the funded stage with this one."));
                }
                KeystoneArcFundedEpisodes funded = KeystoneArcFundedEpisodes.Build(acc, cfg);
                if (funded.Episodes > 0) Add(list, funded.NeverPaid > funded.Paid ? "WARN" : "IDEA", "FUNDED BUT NEVER PAID", funded.Line(cfg) + (funded.NeverPaid > funded.Paid && funded.AveragePeakPercent < 60 ? ". Funded accounts die far from the payout balance: the strategy's drawdown is bigger than the funded room — smaller size or a lower-risk setting for the funded stage." : funded.NeverPaid > funded.Paid ? ". They get close and then blow: a lower payout balance / earlier withdrawal or a daily profit cap near the target would convert more of them." : "."));
                if (cfg.EvaluationEnabled > 0 && x.EvaluationPurchases > 0)
                    Add(list, "IDEA", "PASS RATE", P(100.0 * x.EvaluationPasses / x.EvaluationPurchases) + " of bought evaluations passed (" + x.EvaluationPasses + " / " + x.EvaluationPurchases + "). Compare with START = DIRECT FUNDED to see the cost of the evaluation stage.");
            }
            // 4. Strategy-specific.
            if (fvg && ev.Count >= 10)
            {
                var aggr = ev.Where(e => e.StrengthTag == "AGGR").ToList(); var baseSet = ev.Where(e => e.StrengthTag != "AGGR").ToList();
                if (aggr.Count >= 5 && baseSet.Count >= 5)
                {
                    double wa = 100.0 * aggr.Count(e => e.Outcome == "WIN") / aggr.Count, wb = 100.0 * baseSet.Count(e => e.Outcome == "WIN") / baseSet.Count;
                    Add(list, "IDEA", "AGGRESSION BEFORE THE BOX", "Aggressive boxes: " + aggr.Count + " entries, " + P(wa) + " win, " + M(aggr.Sum(e => e.GrossPnl)) + ". Other boxes: " + baseSet.Count + ", " + P(wb) + " win, " + M(baseSet.Sum(e => e.GrossPnl)) + "." + (wa > wb + 5 ? " Your instinct holds: try AGGRESSION = REQUIRED." : ""));
                }
                var byGap = ev.Where(e => e.FvgGap > 0).OrderBy(e => e.FvgGap).ToList();
                if (byGap.Count >= 12)
                {
                    int third = byGap.Count / 3; var small = byGap.Take(third).ToList(); var large = byGap.Skip(byGap.Count - third).ToList();
                    Add(list, "IDEA", "BOX SIZE", "Smallest third of boxes (≤ " + small.Last().FvgGap.ToString("0.##", CultureInfo.InvariantCulture) + " pts): " + M(small.Sum(e => e.GrossPnl)) + ". Largest third (≥ " + large.First().FvgGap.ToString("0.##", CultureInfo.InvariantCulture) + " pts): " + M(large.Sum(e => e.GrossPnl)) + "." + (large.Sum(e => e.GrossPnl) > small.Sum(e => e.GrossPnl) ? " Bigger boxes did better: try a minimum box size near " + byGap[third].FvgGap.ToString("0.##", CultureInfo.InvariantCulture) + "." : ""));
                }
                var second = ev.Where(e => e.FvgVisit >= 2).ToList();
                if (second.Count >= 5) Add(list, "IDEA", "REPEAT VISITS", "Entries on the 2nd+ visit of a box: " + second.Count + ", " + M(second.Sum(e => e.GrossPnl)) + ".");
            }
            var graded = ev.Where(e => e.QualityTier == "A" || e.QualityTier == "B" || e.QualityTier == "C").ToList();
            if (graded.Count >= 20)
            {
                var parts = new List<string>();
                foreach (string tier in new[] { "A", "B", "C" })
                {
                    var t = graded.Where(e => e.QualityTier == tier).ToList(); if (t.Count == 0) continue;
                    parts.Add(tier + ": " + t.Count + " setups, " + P(100.0 * t.Count(e => e.Outcome == "WIN") / t.Count) + " win, " + M(t.Sum(e => e.GrossPnl)));
                }
                var a = graded.Where(e => e.QualityTier == "A").ToList(); var c = graded.Where(e => e.QualityTier == "C").ToList();
                bool works = a.Count >= 5 && c.Count >= 5 && a.Sum(e => e.GrossPnl) / a.Count > c.Sum(e => e.GrossPnl) / c.Count;
                Add(list, works ? "GOOD" : "IDEA", "SETUP GRADES (LEARNED WALK-FORWARD)", string.Join(" • ", parts) + "." + (works ? " Grade A earns more per setup than C: try FUNDED TRADES = GRADE A + B." : " Grades do not separate winners yet on this range; keep ALL or test a longer range."));
            }
            if (!asian && ev.Count >= 20)
            {
                var hours = ev.GroupBy(e => e.TriggerTime.Hour).Select(g => new { Hour = g.Key, Pnl = g.Sum(e => e.GrossPnl), Count = g.Count() }).Where(h => h.Count >= 5).OrderByDescending(h => h.Pnl).ToList();
                if (hours.Count >= 3) Add(list, "IDEA", "BEST HOURS (NY TIME)", "Best: " + string.Join(", ", hours.Take(2).Select(h => h.Hour.ToString("00") + ":00 " + M(h.Pnl))) + ". Worst: " + string.Join(", ", hours.Skip(Math.Max(0, hours.Count - 2)).Select(h => h.Hour.ToString("00") + ":00 " + M(h.Pnl))) + ". A narrower session window may help.");
            }
            if (asian && ev.Any(e => e.AsianLegNumber > 0))
            {
                var nights = ev.GroupBy(e => e.ReferenceTime.Date).ToList();
                int deep = nights.Count(n => n.Max(e => e.AsianLegNumber) >= Math.Max(2, cfg.AsianMaxReversalsPerInstrument));
                double deepPnl = nights.Where(n => n.Max(e => e.AsianLegNumber) >= Math.Max(2, cfg.AsianMaxReversalsPerInstrument)).Sum(n => n.Sum(e => e.GrossPnl));
                if (nights.Count > 0) Add(list, deepPnl < 0 ? "WARN" : "IDEA", "DEEP REVERSAL NIGHTS", deep + " of " + nights.Count + " nights used the last reversal legs; together they made " + M(deepPnl) + "." + (deepPnl < 0 ? " Try one reversal fewer or a smaller daily loss." : ""));
            }
            return list;
        }
    }
    // =====================================================================================
    // HELIX ODDS LAB • rotation basket math for prop accounts
    // One basket (MNQ + MGC together, any direction per leg) is opened on one account at a
    // time. The basket closes on its combined $ target or $ stop; after a pause the next
    // account in the rotation opens the next basket. Every account runs the full prop life:
    // evaluation (optional) → funded → payouts → liquidation → replacement, with every cost.
    // Everything is simulated on verified 1-minute bars (close-stamped, New York time).
    // =====================================================================================
    // ---- GOLDEN ENTRY STUDY (Build 30s) ------------------------------------------------------------
    // Not prop rules, not money management: every GOLDEN entry held until its target or stop, then the
    // filters, the MNQ / MGC / BOTH comparison, what the winners have in common, a target × stop grid
    // per year and one plain account with the strategy's own contracts.
    public sealed class KeystoneGoldenFilter
    {
        public string Setup = "ALL";                       // ALL • BH • FVG • DT (BH + FVG on the same candle)
        public double MnqMinDrop, MgcMinDrop;              // push down before the entry, points (0 = any)
        public int MinRed;                                 // red candles in a row before the pattern (0 = any)
        public double MnqMinGap, MgcMinGap;                // FVG gap, points (BH setups have no gap and pass)
        public double MnqMaxStop, MgcMaxStop;              // pattern stop, points (0 = any)
        public bool SkipStopOverTarget;
        public int FromHhmm = 0, ToHhmm = 2359;            // entry clock (ET); From > To wraps past midnight
        public bool[] Weekdays = { true, true, true, true, true, true, true };   // index = DayOfWeek
        public int MaxTries = 5;
        public bool StrictFirst = true;                    // a filtered try ends that instrument's day
        public bool OnePositionPerInstrument = true;
        public double StartBalance = 5000;
        public KeystoneGoldenFilter Copy() { var c = (KeystoneGoldenFilter)MemberwiseClone(); c.Weekdays = (bool[])Weekdays.Clone(); return c; }
        public string Key()
        {
            return string.Join("|", new object[] { Setup, MnqMinDrop, MgcMinDrop, MinRed, MnqMinGap, MgcMinGap, MnqMaxStop, MgcMaxStop, SkipStopOverTarget, FromHhmm, ToHhmm, string.Join("", Weekdays.Select(w => w ? "1" : "0")), MaxTries, StrictFirst, OnePositionPerInstrument, StartBalance }.Select(o => Convert.ToString(o, CultureInfo.InvariantCulture)));
        }
    }

    public sealed class KeystoneGoldenStats
    {
        public string Label = string.Empty;
        public int Entries, Wins, Losses, Open, Overnight;
        public double NetPoints, NetCash, WinPoints, LossPoints, RunBeforeStopSum, DrawBeforeTargetSum, HoldHoursSum;
        public double WinRate { get { return Wins + Losses == 0 ? 0 : 100.0 * Wins / (Wins + Losses); } }
        public double AvgWinPoints { get { return Wins == 0 ? 0 : WinPoints / Wins; } }
        public double AvgLossPoints { get { return Losses == 0 ? 0 : LossPoints / Losses; } }
        public double AvgRunBeforeStop { get { return Losses == 0 ? 0 : RunBeforeStopSum / Losses; } }
        public double AvgDrawBeforeTarget { get { return Wins == 0 ? 0 : DrawBeforeTargetSum / Wins; } }
        public double AvgHoldHours { get { return Wins + Losses == 0 ? 0 : HoldHoursSum / (Wins + Losses); } }
        public double CashPerEntry { get { return Entries == 0 ? 0 : NetCash / Entries; } }
    }

    public sealed class KeystoneGoldenGroup { public string Group = string.Empty; public int Order; public KeystoneGoldenStats Mnq = new KeystoneGoldenStats(), Mgc = new KeystoneGoldenStats(), Both = new KeystoneGoldenStats(); }
    public sealed class KeystoneGoldenBreakdown { public string Title = string.Empty, Note = string.Empty; public List<KeystoneGoldenGroup> Rows = new List<KeystoneGoldenGroup>(); }
    public sealed class KeystoneGoldenCell { public double Stop, Target; public bool Pattern; public int Wins, Losses, Open; public double NetPoints, NetCash; public double WinRate { get { return Wins + Losses == 0 ? 0 : 100.0 * Wins / (Wins + Losses); } } }
    public sealed class KeystoneGoldenGrid { public string Symbol = string.Empty, Year = "ALL"; public int Entries; public double[] Stops = new double[0], Targets = new double[0]; public KeystoneGoldenCell[,] Cells; public KeystoneGoldenCell Best, Yours; }
    public sealed class KeystoneGoldenInsight { public string Text = string.Empty; public double Lift; public bool Good; }

    public sealed class KeystoneGoldenAccount
    {
        public double Start, End, Peak, MaxDrawdown, MaxDrawdownPercent;
        public int Trades, Wins, Losses, Open, SkippedOpen;
        public List<KeystoneArcEvent> Taken = new List<KeystoneArcEvent>();
        public List<Tuple<DateTime, double>> Equity = new List<Tuple<DateTime, double>>();
        public List<Tuple<DateTime, double, int, int>> Months = new List<Tuple<DateTime, double, int, int>>();   // month, P/L, wins, losses
    }

    public sealed class KeystoneGoldenStudyResult
    {
        public List<KeystoneArcEvent> All = new List<KeystoneArcEvent>(), Kept = new List<KeystoneArcEvent>();
        public Dictionary<KeystoneArcEvent, string> Reasons = new Dictionary<KeystoneArcEvent, string>();
        public KeystoneGoldenStats Mnq, Mgc, Both;
        public KeystoneGoldenAccount AccountMnq, AccountMgc, AccountBoth;
        public List<KeystoneGoldenBreakdown> Breakdowns = new List<KeystoneGoldenBreakdown>();
        public List<KeystoneGoldenGrid> Grids = new List<KeystoneGoldenGrid>();   // per symbol: ALL years first, then each year
        public List<KeystoneGoldenInsight> Insights = new List<KeystoneGoldenInsight>();
        public Dictionary<string, int> FilteredOut = new Dictionary<string, int>();
