    // ---- MOVE STUDY (build 10-03e) -----------------------------------------------------------------
    // No fixed target or stop: every detected entry is followed to the session close and measured — how far price went
    // for us, against us, against us before the best point, where it closed. Compared by entry set × instrument × year,
    // against a no-setup baseline (buy at the start time every day). The target / stop in points (and dollars) are then
    // chosen FROM those movements, per year and overall; the best sets are explained by their features (why).
    // ---- ROTATION TESTER (build 10-03f) -------------------------------------------------------------
    // The live rotation tool replayed on history: MNQ and MGC opened together (BUY BUY / SELL SELL / random / a fast
    // confirmation), one combined target and stop per rotation, a 3-tier profit lock, a pause, then the next account takes
    // the next rotation. Each account has a daily target, a daily stop and a two-loss lock, and is a prop evaluation
    // (target, trailing EOD drawdown that stops at +100, consistency). Real 1-minute bars, both instruments on the same
    // minute; inside a minute the worst combined price (both at their adverse extremes) counts before the best.
    public sealed class KeystoneRotationConfig
    {
        public int StartHhmm = 930, EndHhmm = 1555, MnqQty = 20, MgcQty = 20, PauseMinutes = 1, Accounts = 20, MaxLossesPerDay = 2, Seed = 7;
        public string Direction = "BUY";           // BUY • SELL • RANDOM • FOLLOW5 (both instruments' last 5 min agree → that way) • FADE5 (against it)
        public double RotationTarget = 1000, RotationStop = 500, DailyTarget = 2000, DailyStop = 2000;
        public string LockTiers = "500:150,700:350,900:750";   // peak trigger : locked profit
        public double CommissionPerSide = 0.62; public int SlippageTicks = 1;
        public KeystonePropRules Rules = new KeystonePropRules();
        public KeystoneRotationConfig Copy() { var c = (KeystoneRotationConfig)MemberwiseClone(); c.Rules = Rules.Copy(); return c; }
        public List<Tuple<double, double>> Tiers()
        {
            var list = new List<Tuple<double, double>>();
            foreach (var part in (LockTiers ?? "").Split(new[] { ',', ';', ' ' }, StringSplitOptions.RemoveEmptyEntries))
            {
                var kv = part.Split(':'); double a, b;
                if (kv.Length == 2 && double.TryParse(kv[0], NumberStyles.Any, CultureInfo.InvariantCulture, out a) && double.TryParse(kv[1], NumberStyles.Any, CultureInfo.InvariantCulture, out b) && a > 0 && b < a) list.Add(Tuple.Create(a, b));
            }
            return list.OrderBy(t => t.Item1).ToList();
        }
        public string Describe()
        {
            Func<double, string> m = v => "$" + v.ToString("N0", CultureInfo.InvariantCulture);
            return KeystoneRotation.DirectionName(Direction) + " • " + MnqQty + " MNQ + " + MgcQty + " MGC • rotation +" + m(RotationTarget) + " / −" + m(RotationStop) + (Tiers().Count > 0 ? " • locks " + LockTiers : "") + " • pause " + PauseMinutes + " min • " + KeystoneBracket.Hm(StartHhmm) + "–" + KeystoneBracket.Hm(EndHhmm) + " • " + Accounts + " accounts • day +" + m(DailyTarget) + " / −" + m(DailyStop) + (MaxLossesPerDay > 0 ? " / " + MaxLossesPerDay + " losses" : "");
        }
    }

    public sealed class KeystoneRotationTrade { public DateTime Entry, Exit; public int Account, Dir; public double Pnl, Peak; public string Reason = string.Empty; }

    public sealed class KeystoneRotationDay { public DateTime Day; public int Rotations, Wins, Losses, Passed, Blown, Bought; public double Net, Costs; }

    public sealed class KeystoneRotationResult
    {
        public KeystoneRotationConfig Config; public List<KeystoneRotationDay> Days = new List<KeystoneRotationDay>(); public List<KeystoneRotationTrade> Trades = new List<KeystoneRotationTrade>();
        public int Bought, Passed, Blown; public double Spent, Net, Costs; public List<int> DaysToPass = new List<int>();
        public string Label = string.Empty;
        public int RotCount, WinCount; public double PnlSum;   // kept when the trade list is dropped (optimizer)
        public int Rotations { get { return RotCount; } }
        public double WinPct { get { return RotCount == 0 ? 0 : 100.0 * WinCount / RotCount; } }
        public double PerRotation { get { return RotCount == 0 ? 0 : PnlSum / RotCount; } }
        public double CostPerPass { get { return Passed == 0 ? double.PositiveInfinity : Spent / Passed; } }
        public double PassRate { get { return Bought == 0 ? 0 : 100.0 * Passed / Bought; } }
        public Dictionary<int, double[]> ByYear = new Dictionary<int, double[]>();   // year → { bought, passed, spent, net, rotations }
    }

    public static class KeystoneRotation
    {
        public static readonly string[] Directions = { "BUY", "SELL", "RANDOM", "FOLLOW5", "FADE5" };
        public static string DirectionName(string d) { switch (d) { case "BUY": return "BUY BUY"; case "SELL": return "SELL SELL"; case "RANDOM": return "RANDOM BUY BUY / SELL SELL"; case "FOLLOW5": return "CONFIRM: BOTH UP 5 MIN → BUY, BOTH DOWN → SELL"; case "FADE5": return "CONFIRM: BOTH UP 5 MIN → SELL, BOTH DOWN → BUY"; } return d; }

        sealed class Acct { public double Bal, Hwm, Best, DayPnl; public int DayLosses, Days, Id; public bool Locked, Dead, Passed, TradedToday; public DateTime Started; }

        static double Threshold(Acct a, KeystonePropRules r) { return r.Drawdown == "STATIC" ? -r.MaxDrawdown : Math.Min(a.Hwm - r.MaxDrawdown, r.LockAt); }

        public static KeystoneRotationResult Run(List<KeystoneHelixMinute> minutes, KeystoneRotationConfig c)
        {
            var res = new KeystoneRotationResult { Config = c }; var r = c.Rules; var rng = new Random(c.Seed); var tiers = c.Tiers();
            double km = 2.0 * c.MnqQty, kg = 10.0 * c.MgcQty;
            double cost = 2 * c.CommissionPerSide * (c.MnqQty + c.MgcQty), slip = c.SlippageTicks * (0.25 * km + 0.1 * kg);
            int sm = c.StartHhmm / 100 * 60 + c.StartHhmm % 100, em = c.EndHhmm / 100 * 60 + c.EndHhmm % 100;
            var accts = new List<Acct>(); int nextId = 1;
            Func<DateTime, Acct> buy = day => { var a = new Acct { Id = nextId++, Started = day }; res.Bought++; res.Spent += r.EvalCost; return a; };
            int turn = 0;
            foreach (var g in minutes.Where(x => x.HasMnq && x.HasMgc).GroupBy(x => x.Time.Date).OrderBy(x => x.Key))
            {
                var day = new KeystoneRotationDay { Day = g.Key }; int boughtBefore = res.Bought;
                // replace dead or passed accounts, keep the pool at its size
                for (int i = accts.Count - 1; i >= 0; i--) if (accts[i].Dead || accts[i].Passed) accts.RemoveAt(i);
                while (accts.Count < Math.Max(1, c.Accounts)) accts.Add(buy(g.Key));
                foreach (var a in accts) { a.DayPnl = 0; a.DayLosses = 0; a.Locked = false; a.TradedToday = false; }
                var bars = g.Where(x => { int m = x.Time.Hour * 60 + x.Time.Minute; return m > sm && m <= em; }).OrderBy(x => x.Time).ToList();
                var all = g.OrderBy(x => x.Time).ToList(); var at = new Dictionary<DateTime, int>(); for (int q = 0; q < all.Count; q++) at[all[q].Time] = q;
                int i0 = 0; DateTime nextAllowed = DateTime.MinValue;
                while (i0 < bars.Count)
                {
                    var b0 = bars[i0];
                    if (b0.Time < nextAllowed) { i0++; continue; }
                    // next account in turn that can still trade today
                    Acct acct = null; for (int k = 0; k < accts.Count; k++) { var a = accts[(turn + k) % accts.Count]; if (!a.Locked && !a.Dead && !a.Passed) { acct = a; turn = (turn + k + 1) % accts.Count; break; } }
                    if (acct == null) break;
                    // direction
                    int dir = 1;
                    if (c.Direction == "SELL") dir = -1; else if (c.Direction == "RANDOM") dir = rng.NextDouble() < 0.5 ? 1 : -1;
                    else if (c.Direction == "FOLLOW5" || c.Direction == "FADE5")
                    {
                        int j; if (!at.TryGetValue(b0.Time, out j) || j < 5) { i0++; continue; }
                        double dm = all[j - 1].MnqC - all[j - 5].MnqO, dg = all[j - 1].MgcC - all[j - 5].MgcO;
                        if (Math.Sign(dm) == 0 || Math.Sign(dm) != Math.Sign(dg)) { i0++; continue; }   // no agreement → wait a minute
                        dir = Math.Sign(dm) * (c.Direction == "FADE5" ? -1 : 1);
                    }
                    double eM = b0.MnqO, eG = b0.MgcO;
                    Func<double, double, double> val = (pm, pg) => dir * ((pm - eM) * km + (pg - eG) * kg);
                    // the daily target is net of costs: what is left of it plus this rotation's commission
                    double target = Math.Min(c.RotationTarget, c.DailyTarget > 0 ? c.DailyTarget - acct.DayPnl + cost : double.MaxValue);
                    if (target <= 2 * cost) { acct.Locked = true; continue; }   // nothing worth a rotation left today
                    double stop = Math.Min(c.RotationStop, c.DailyStop > 0 ? c.DailyStop + acct.DayPnl : double.MaxValue);
                    double room = acct.Bal - Threshold(acct, r) - cost; stop = Math.Min(stop, Math.Max(1, room));
                    double peak = 0, floor = -stop, pnl = 0; string reason = null; int i = i0; DateTime exitT = b0.Time;
                    for (; i < bars.Count; i++)
                    {
                        var b = bars[i];
                        double worst = dir > 0 ? val(b.MnqL, b.MgcL) : val(b.MnqH, b.MgcH), best = dir > 0 ? val(b.MnqH, b.MgcH) : val(b.MnqL, b.MgcL), close = val(b.MnqC, b.MgcC);
                        if (worst <= floor + 1e-9) { pnl = floor - slip; reason = floor > -stop + 1e-9 ? "LOCK" : "STOP"; exitT = b.Time; break; }
                        peak = Math.Max(peak, best);
                        foreach (var t in tiers) if (peak >= t.Item1 - 1e-9) floor = Math.Max(floor, t.Item2);
                        if (best >= target - 1e-9) { pnl = target; reason = "TARGET"; exitT = b.Time; break; }
                        if (close <= floor + 1e-9) { pnl = floor - slip; reason = "LOCK"; exitT = b.Time; break; }
                        if (i == bars.Count - 1) { pnl = close - slip; reason = "SESSION END"; exitT = b.Time; break; }
                    }
                    if (reason == null) break;
                    pnl -= cost; res.Costs += cost + (reason == "TARGET" ? 0 : slip); day.Costs += cost;
                    res.Trades.Add(new KeystoneRotationTrade { Entry = b0.Time, Exit = exitT, Account = acct.Id, Dir = dir, Pnl = pnl, Peak = peak, Reason = reason });
                    day.Rotations++; if (pnl > 0) day.Wins++; else { day.Losses++; acct.DayLosses++; }
                    acct.DayPnl += pnl; acct.Bal += pnl; acct.TradedToday = true; day.Net += pnl;
                    if (acct.Bal <= Threshold(acct, r) + 1e-6) { acct.Dead = true; res.Blown++; day.Blown++; }
                    if ((c.DailyTarget > 0 && acct.DayPnl >= c.DailyTarget - 2 * cost - 1e-6) || (c.DailyStop > 0 && acct.DayPnl <= -c.DailyStop + 1e-6) || (c.MaxLossesPerDay > 0 && acct.DayLosses >= c.MaxLossesPerDay)) acct.Locked = true;
                    nextAllowed = exitT.AddMinutes(Math.Max(1, c.PauseMinutes));
                    i0 = i + 1;
                }
                // end of day: trailing floor, pass check
                foreach (var a in accts.Where(x => x.TradedToday && !x.Dead))
                {
                    a.Days++; a.Best = Math.Max(a.Best, a.DayPnl); a.Hwm = Math.Max(a.Hwm, a.Bal);
                    bool consistent = r.Consistency <= 0 || a.Best <= r.Consistency / 100.0 * a.Bal + 1e-9;
                    if (a.Bal >= r.Target && a.Days >= Math.Max(1, r.MinDays) && consistent) { a.Passed = true; res.Passed++; day.Passed++; res.DaysToPass.Add(a.Days); }
                }
                day.Bought = res.Bought - boughtBefore; res.Days.Add(day);
                double[] y; if (!res.ByYear.TryGetValue(g.Key.Year, out y)) { y = new double[5]; res.ByYear[g.Key.Year] = y; }
                y[0] += day.Bought; y[1] += day.Passed; y[2] += day.Bought * r.EvalCost; y[3] += day.Net; y[4] += day.Rotations;
            }
            res.Net = res.Trades.Sum(t => t.Pnl); res.RotCount = res.Trades.Count; res.WinCount = res.Trades.Count(t => t.Pnl > 0); res.PnlSum = res.Net;
            res.Label = c.Describe();
            return res;
        }

        // Search: direction × window × contracts × target / stop × pause, ranked by the cost of one passed evaluation (all CPU cores).
        public static List<KeystoneRotationResult> Optimize(List<KeystoneHelixMinute> minutes, KeystoneRotationConfig basis, Action<string> progress) { return Optimize(minutes, basis, progress, null); }
        public static List<KeystoneRotationResult> Optimize(List<KeystoneHelixMinute> minutes, KeystoneRotationConfig basis, Action<string> progress, Func<bool> cancelled)
        {
            var configs = new List<KeystoneRotationConfig>();
            var windows = new[] { Tuple.Create(930, 1100), Tuple.Create(930, 1555), Tuple.Create(1000, 1200), Tuple.Create(1300, 1555), Tuple.Create(800, 930) };
            foreach (string d in Directions)
                foreach (var win in windows)
                    foreach (int q in new[] { 5, 10, 20 })
                        foreach (double tp in new[] { 500.0, 1000, 1500 })
                            foreach (double sl in new[] { 250.0, 500, 1000 })
                                foreach (int pause in new[] { 1, 5, 15 })
                                {
                                    var c = basis.Copy(); c.Direction = d; c.StartHhmm = win.Item1; c.EndHhmm = win.Item2; c.MnqQty = q; c.MgcQty = q; c.RotationTarget = tp; c.RotationStop = sl; c.PauseMinutes = pause;
                                    configs.Add(c);
                                }
            var results = new KeystoneRotationResult[configs.Count]; int done = 0;
            System.Threading.Tasks.Parallel.For(0, configs.Count, i =>
            {
                if (cancelled != null && cancelled()) return;
                var rr = Run(minutes, configs[i]); rr.Trades = new List<KeystoneRotationTrade>(); results[i] = rr;   // summary only (memory)
                int d = System.Threading.Interlocked.Increment(ref done); if (progress != null && d % 50 == 0) progress(d + " / " + configs.Count);
            });
            return results.Where(x => x != null).OrderBy(x => x.Passed >= 5 ? 0 : 1).ThenBy(x => x.CostPerPass).ThenByDescending(x => x.Passed).ToList();
        }

        // When do MNQ and MGC move together? Per 30-minute slot: % of 5-minute windows where both moved the same way,
        // and the average combined $ move (both legs, the chosen contracts) — the fuel a combined target needs.
        public static List<string[]> Together(List<KeystoneHelixMinute> minutes, int mnqQty, int mgcQty)
        {
            var rows = new List<string[]>(); var slots = new Dictionary<int, List<Tuple<bool, double>>>();
            foreach (var g in minutes.Where(x => x.HasMnq && x.HasMgc).GroupBy(x => x.Time.Date))
            {
                var list = g.OrderBy(x => x.Time).ToList();
                for (int i = 4; i < list.Count; i += 5)
                {
                    if ((list[i].Time - list[i - 4].Time).TotalMinutes > 4.5) continue;
                    double dm = list[i].MnqC - list[i - 4].MnqO, dg = list[i].MgcC - list[i - 4].MgcO;
                    int slot = (list[i - 4].Time.Hour * 60 + list[i - 4].Time.Minute - 1) / 30 * 30;
                    List<Tuple<bool, double>> s; if (!slots.TryGetValue(slot, out s)) { s = new List<Tuple<bool, double>>(); slots[slot] = s; }
                    s.Add(Tuple.Create(Math.Sign(dm) != 0 && Math.Sign(dm) == Math.Sign(dg), Math.Abs(dm * 2 * mnqQty) + Math.Abs(dg * 10 * mgcQty)));
                }
            }
            foreach (var kv in slots.OrderBy(k => k.Key))
            {
                if (kv.Value.Count < 20) continue;
                int h = kv.Key / 60, m = kv.Key % 60;
                rows.Add(new[] { h.ToString("00") + ":" + m.ToString("00") + "–" + ((kv.Key + 30) / 60 % 24).ToString("00") + ":" + ((kv.Key + 30) % 60).ToString("00"), kv.Value.Count.ToString(), (100.0 * kv.Value.Count(t => t.Item1) / kv.Value.Count).ToString("0") + "%", "$" + kv.Value.Average(t => t.Item2).ToString("N0", CultureInfo.InvariantCulture), "$" + kv.Value.Where(t => t.Item1).Select(t => t.Item2).DefaultIfEmpty(0).Average().ToString("N0", CultureInfo.InvariantCulture) });
            }
            return rows;
        }

        public static string Verdict(KeystoneRotationResult x)
        {
            Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            if (x.Passed == 0) return "NO EVALUATION PASSED • " + x.Bought + " bought (" + m(x.Spent) + ") • " + x.Rotations + " rotations, " + x.WinPct.ToString("0") + "% won, " + m(x.PerRotation) + " per rotation after costs.";
            return "1 PASSED EVALUATION COSTS " + m(x.CostPerPass) + " • " + x.Passed + " passed of " + x.Bought + " bought (" + x.PassRate.ToString("0") + "%) in " + (x.DaysToPass.Count == 0 ? 0 : x.DaysToPass.Average()).ToString("0.0") + " trading days on average • " + x.Rotations + " rotations, " + x.WinPct.ToString("0") + "% won, " + m(x.PerRotation) + " per rotation after costs (costs " + m(x.Costs) + ").";
        }
    }

    // ---- FIRST 5M FVG ENTRY STUDY (build 10-03h) -----------------------------------------------------
    // Per instrument and day: the FIRST bullish 5-minute FVG formed after the start time (all 3 candles after the start;
    // gap = candle 3 low above candle 1 high, at least MinGap points). Each entry variation is its own set:
    //   TOUCH (limit at the gap top) • 25% DIP • 50% DIP (limits inside the gap) • GREEN CLOSE + BREAK (a candle touches the gap
    //   without closing below it, a green 5M candle closes — after a red touch the next one must be green — the next 5M candle
    //   breaks that green high = entry at that high) • PRIOR FVG TOUCH / 50%: an FVG formed earlier (18:00 the evening before →
    //   the start) still untouched at the start, that the opening candles (first N minutes) dip into.
    // Fills on 1-minute bars (a limit fills at the level, or at the open when the minute opens through it). No BH. Every
    // entry is then measured to the close by the MOVE STUDY (the fill minute's favourable move is not counted — conservative).
    public sealed class KeystoneFvgStudyConfig
    {
        public int MnqStart = 930, MgcStart = 800, Close = 1555, PriorMinutes = 30;
        public double MnqMinGap = 5, MgcMinGap = 1, MnqAggr = 30, MgcAggr = 3;
        public bool OpenCandleGap = true;   // candle 1 may be the last candle before the start when candle 2 (the opening move) is after it
    }

    public static class KeystoneFvgEntryStudy
    {
        public const string Touch = "FIRST 5M FVG • TOUCH THE GAP TOP", Dip25 = "FIRST 5M FVG • 25% DIP INTO THE GAP", Dip50 = "FIRST 5M FVG • 50% DIP (GAP MIDDLE)", Break = "FIRST 5M FVG • GREEN CLOSE + BREAK OF ITS HIGH", PriorTouch = "PRIOR UNTOUCHED FVG • OPENING CANDLES TOUCH IT", Prior50 = "PRIOR UNTOUCHED FVG • OPENING CANDLES DIP TO 50%", FirstBh = "FIRST 5M BH • RED → GREEN → BREAK OF THE GREEN HIGH";
        public static readonly string[] Sets = { Touch, Dip25, Dip50, Break, PriorTouch, Prior50, FirstBh };

        sealed class Gap { public double Low, High; public DateTime Formed; public int Index; public double Height { get { return High - Low; } } }

        // 5-minute candles from close-stamped 1-minute bars (a 5M candle ends on a multiple of 5 minutes).
        public static List<KeystoneArcBar> FiveMinute(List<KeystoneArcBar> one)
        {
            var output = new List<KeystoneArcBar>(); KeystoneArcBar cur = null; DateTime curEnd = DateTime.MinValue;
            foreach (var b in one)
            {
                int m = b.Time.Minute % 5; DateTime end = m == 0 ? b.Time : b.Time.AddMinutes(5 - m);
                if (cur == null || end != curEnd) { if (cur != null) output.Add(cur); cur = new KeystoneArcBar { Symbol = b.Symbol, Time = end, Open = b.Open, High = b.High, Low = b.Low, Close = b.Close }; curEnd = end; }
                else { cur.High = Math.Max(cur.High, b.High); cur.Low = Math.Min(cur.Low, b.Low); cur.Close = b.Close; }
            }
            if (cur != null) output.Add(cur);
            return output;
        }

        static int FirstAfter(List<KeystoneArcBar> raw, DateTime t) { int lo = 0, hi = raw.Count; while (lo < hi) { int mid = (lo + hi) / 2; if (raw[mid].Time > t) hi = mid; else lo = mid + 1; } return lo; }

        // First 1-minute bar after `after` (up to `until`) that trades down to `level`: fill at the level or at the open if it opened below.
        static bool LimitFill(List<KeystoneArcBar> raw, DateTime after, DateTime until, double level, out int idx, out double fill)
        {
            idx = -1; fill = double.NaN;
            for (int i = FirstAfter(raw, after); i < raw.Count && raw[i].Time <= until; i++)
                if (raw[i].Low <= level + 1e-9) { idx = i; fill = Math.Min(level, raw[i].Open); return true; }
            return false;
        }

        public static Dictionary<string, List<KeystoneArcEvent>> Run(List<KeystoneArcBar> oneMinute, KeystoneFvgStudyConfig c)
        {
            var sets = Sets.ToDictionary(s => s, s => new List<KeystoneArcEvent>());
            if (oneMinute == null) return sets;
            foreach (var sg in oneMinute.GroupBy(b => (b.Symbol ?? "").ToUpperInvariant()))
            {
                string sym = sg.Key; if (sym != "MNQ" && sym != "MGC") continue;
                var raw = sg.OrderBy(b => b.Time).ToList(); var five = FiveMinute(raw);
                int startHhmm = sym == "MGC" ? c.MgcStart : c.MnqStart; double minGap = sym == "MGC" ? c.MgcMinGap : c.MnqMinGap, aggrPts = sym == "MGC" ? c.MgcAggr : c.MnqAggr;
                foreach (var day in raw.Select(b => b.Time.Date).Distinct().OrderBy(d => d))
                {
                    if (day.DayOfWeek == DayOfWeek.Saturday || day.DayOfWeek == DayOfWeek.Sunday) continue;
                    DateTime start = day.AddHours(startHhmm / 100).AddMinutes(startHhmm % 100), close = day.AddHours(c.Close / 100).AddMinutes(c.Close % 100), evening = day.AddDays(-1).AddHours(18);
                    if (close <= start) continue;
                    int s0 = five.FindIndex(b => b.Time > start); if (s0 < 0 || five[s0].Time > close) continue;
                    double startOpen = five[s0].Open;
                    // ---- the first FVG after the start (all three candles after it)
                    Gap first = null;
                    for (int i = Math.Max(2, c.OpenCandleGap ? s0 + 1 : s0 + 2); i < five.Count && five[i].Time <= close; i++)
                        if (five[i].Low > five[i - 2].High && five[i].Low - five[i - 2].High >= minGap - 1e-9) { first = new Gap { Low = five[i - 2].High, High = five[i].Low, Formed = five[i].Time, Index = i }; break; }
                    if (first != null)
                    {
                        double low = double.MaxValue; for (int q = s0; q <= first.Index - 2; q++) low = Math.Min(low, five[q].Low);
                        double drop = low == double.MaxValue ? 0 : Math.Max(0, startOpen - low);
                        Action<string, int, double, DateTime> add = (set, idx, fill, trig) =>
                        {
                            var e = new KeystoneArcEvent { Symbol = sym, Direction = "LONG", SetupClass = "FVG", TriggerTime = trig, EntryTime = raw[idx].Time, Entry = fill, FvgLower = first.Low, FvgUpper = first.High, FvgGap = first.Height, FvgDrop = drop, FvgFormedTime = first.Formed, StrengthTag = drop >= aggrPts ? "AGGR" : "BASE", ReviewNote = set };
                            KeystoneMoveStudy.Walk(e, raw, idx, 1, close, sym, true); if (e.MoveHeat != null) sets[set].Add(e);
                        };
                        int fi; double fp;
                        if (LimitFill(raw, first.Formed, close, first.High, out fi, out fp)) add(Touch, fi, fp, first.Formed);
                        if (LimitFill(raw, first.Formed, close, first.High - 0.25 * first.Height, out fi, out fp)) add(Dip25, fi, fp, first.Formed);
                        if (LimitFill(raw, first.Formed, close, first.High - 0.5 * first.Height, out fi, out fp)) add(Dip50, fi, fp, first.Formed);
                        // green close + break of its high (one attempt, like the lab's FVG rule)
                        for (int k = first.Index + 1; k < five.Count && five[k].Time <= close; k++)
                        {
                            var b = five[k]; if (b.Close < first.Low) break;
                            if (b.Low > first.High) continue;                          // not back in the gap yet
                            int refIdx = b.Close > b.Open ? k : (k + 1 < five.Count && five[k + 1].Close > five[k + 1].Open && five[k + 1].Close >= first.Low ? k + 1 : -1);
                            if (refIdx < 0 || refIdx + 1 >= five.Count || five[refIdx + 1].Time > close) break;
                            var refBar = five[refIdx]; var trig = five[refIdx + 1];
                            if (trig.High >= refBar.High)
                            {
                                for (int i = FirstAfter(raw, refBar.Time); i < raw.Count && raw[i].Time <= trig.Time; i++)
                                    if (raw[i].High >= refBar.High) { add(Break, i, Math.Max(refBar.High, raw[i].Open), trig.Time); break; }
                            }
                            break;
                        }
                    }
                    // ---- for comparison: the first 5M BH after the start (red candle → green reference → the next candle breaks the green high)
                    for (int i = s0 + 2; i < five.Count && five[i].Time <= close; i++)
                    {
                        var red = five[i - 2]; var grn = five[i - 1]; var trg = five[i];
                        if (!(red.Close < red.Open && grn.Close > grn.Open && trg.High >= grn.High)) continue;
                        double lowB = double.MaxValue; for (int q = s0; q <= i - 2; q++) lowB = Math.Min(lowB, five[q].Low);
                        double dropB = lowB == double.MaxValue ? 0 : Math.Max(0, startOpen - lowB);
                        for (int m = FirstAfter(raw, grn.Time); m < raw.Count && raw[m].Time <= trg.Time; m++)
                            if (raw[m].High >= grn.High)
                            {
                                var e = new KeystoneArcEvent { Symbol = sym, Direction = "LONG", SetupClass = "BH", TriggerTime = trg.Time, EntryTime = raw[m].Time, Entry = Math.Max(grn.High, raw[m].Open), FvgDrop = dropB, StrengthTag = dropB >= aggrPts ? "AGGR" : "BASE", ReviewNote = FirstBh };
                                KeystoneMoveStudy.Walk(e, raw, m, 1, close, sym, true); if (e.MoveHeat != null) sets[FirstBh].Add(e);
                                break;
                            }
                        break;
                    }
                    // ---- prior untouched FVG: formed 18:00 the evening before → the start, not traded into before the start
                    var prior = new List<Gap>();
                    for (int i = 2; i < five.Count && five[i].Time <= start; i++)
                    {
                        if (five[i - 2].Time - TimeSpan.FromMinutes(5) < evening) continue;
                        if (five[i].Low > five[i - 2].High && five[i].Low - five[i - 2].High >= minGap - 1e-9) prior.Add(new Gap { Low = five[i - 2].High, High = five[i].Low, Formed = five[i].Time, Index = i });
                    }
                    if (prior.Count > 0)
                    {
                        DateTime startRaw = start;
                        prior = prior.Where(g => { for (int q = g.Index + 1; q < five.Count && five[q].Time <= startRaw; q++) if (five[q].Low <= g.High) return false; return true; }).ToList();
                        // the opening candles: the first touch of any untouched prior gap within PriorMinutes after the start
                        DateTime until = start.AddMinutes(Math.Max(5, c.PriorMinutes));
                        for (int i = FirstAfter(raw, start); i < raw.Count && raw[i].Time <= until && prior.Count > 0; i++)
                        {
                            var hit = prior.Where(g => raw[i].Low <= g.High + 1e-9).OrderByDescending(g => g.High).FirstOrDefault();
                            if (hit == null) continue;
                            double drop = Math.Max(0, startOpen - raw[i].Low);
                            Action<string, int, double> addPrior = (set, idx, fill) =>
                            {
                                var e = new KeystoneArcEvent { Symbol = sym, Direction = "LONG", SetupClass = "PRIOR FVG", TriggerTime = raw[idx].Time, EntryTime = raw[idx].Time, Entry = fill, FvgLower = hit.Low, FvgUpper = hit.High, FvgGap = hit.Height, FvgDrop = drop, FvgFormedTime = hit.Formed, StrengthTag = drop >= aggrPts ? "AGGR" : "BASE", ReviewNote = set };
                                KeystoneMoveStudy.Walk(e, raw, idx, 1, close, sym, true); if (e.MoveHeat != null) sets[set].Add(e);
                            };
                            addPrior(PriorTouch, i, Math.Min(hit.High, raw[i].Open));
                            int fi; double fp; if (LimitFill(raw, raw[i].Time.AddMinutes(-1), until, hit.High - 0.5 * hit.Height, out fi, out fp)) addPrior(Prior50, fi, fp);
                            break;
                        }
                    }
                }
            }
            return sets;
        }
    }

    // ---- REPLAY TRADER engine: a session replayed tick by tick from the loaded 1-minute bars ------------------------------
    // Inside each minute the price walks open → the nearer-in-time extreme → the other extreme → close (a down-closing
    // minute visits its high first, an up-closing minute its low first) in small steps. That path is SIMULATED: 1-minute
    // bars do not record the order of the ticks inside the minute. Buy / sell at the current price, optional stop / target in
    // points (checked on every step), flat at the end of the session; costs = commission both sides + 1 tick per contract.
    public sealed class KeystoneReplayOrder { public int Id, Dir, Qty; public string Type = "LIMIT"; public double Price; public string Label { get { return (Dir > 0 ? "BUY " : "SELL ") + Type + " " + Qty; } } }

    // A strategy signal shown on the replay chart (only once the replay clock has reached its entry time).
    public sealed class KeystoneReplaySignal
    {
        public DateTime Time, Exit; public int Dir; public double Entry, Stop = double.NaN, Target = double.NaN; public string Tag = string.Empty, Tier = string.Empty; public bool Taken;
        // tested opening-range rules: Order = "STOP" → a stop order at Entry from Time until CancelAt (one of a pair, Group = OCO);
        // the stop / target are distances from the fill (StopDist / TargetDist, 0 = none); Exit = flat by this time
        public string Order = "MARKET"; public double StopDist, TargetDist; public DateTime CancelAt = DateTime.MaxValue; public int Group; public string Why = string.Empty;
    }

    // The opening-range rules that survived the 6-year walk-forward research (docs/research, research/*.cs):
    // settings chosen on 2020–2023, judged on 2024–2026. One trade a day, flat by 15:55, conservative fills.
    public sealed class KeystoneOrbRule
    {
        public string Name = "", Short = ""; public int OpenHhmm = 930, Minutes = 10, EntryWindow = 150, ExitHhmm = 1555;
        public string Mode = "CANDLE";       // CANDLE = market order in the direction of the opening candle • BREAK = stop orders at the range high / low (first one wins)
        public double StopAtr = 0.25;        // stop = this × the 14-day average 09:30–16:00 range (0 = the opening range itself)
        public double TargetR = 4;           // target = this × the stop (0 = none, hold to the exit time)
        public bool SkipNews = true;         // no trade on FOMC and payrolls days
        public int Side = 0;                 // 1 = buys only, −1 = sells only, 0 = both
        public string Evidence = "";
        public KeystoneOrbRule Copy() { return (KeystoneOrbRule)MemberwiseClone(); }
        public string Describe()
        {
            return Name + " • opening range " + (OpenHhmm / 100).ToString("00") + ":" + (OpenHhmm % 100).ToString("00") + " + " + Minutes + " min • " + (Mode == "CANDLE" ? "market order in the direction of that candle" : "stop orders at its high and low (first one wins, until " + EntryWindow + " min later)")
                + " • stop " + (StopAtr > 0 ? StopAtr.ToString("0.##", CultureInfo.InvariantCulture) + " × 14-day range" : "the other side of the range") + " • target " + (TargetR > 0 ? TargetR.ToString("0.#", CultureInfo.InvariantCulture) + "R" : "none") + " • flat " + (ExitHhmm / 100).ToString("00") + ":" + (ExitHhmm % 100).ToString("00") + (SkipNews ? " • no trade on FOMC / payrolls days" : "");
        }
    }

    // KEYSTONE REPORT (.kreport.json, format "keystone-report-1"): a study made outside the studio (docs/research) —
    // summary, tables and every labelled day with its markers / trades. The REPORTS window imports it and draws a day on the chart.
    public sealed class KeystoneReport
    {
        public string Title = "", Subtitle = "", Instrument = "MNQ", Method = "", Generated = "", FilePath = "";
        public List<string[]> Summary = new List<string[]>();
        public List<Section> Sections = new List<Section>();
        public List<Day> Days = new List<Day>();
        public sealed class Section { public string Title = "", Note = ""; public List<string> Columns = new List<string>(); public List<List<string>> Rows = new List<List<string>>(); }
        public sealed class Marker { public TimeSpan Time; public double Price = double.NaN; public string Text = "", Kind = "info"; }
        public sealed class Trade { public int Dir; public TimeSpan EntryTime, ExitTime; public double Entry = double.NaN, Stop = double.NaN, Target = double.NaN, Exit = double.NaN, Pnl = double.NaN; public string Why = ""; }
        public sealed class Day { public DateTime Date; public string Label = "", Color = "", Note = ""; public Dictionary<string, string> Fields = new Dictionary<string, string>(); public List<Marker> Markers = new List<Marker>(); public List<Trade> Trades = new List<Trade>(); }

        public static KeystoneReport Load(string path) { var r = Parse(File.ReadAllText(path)); r.FilePath = path; return r; }

        public static KeystoneReport Parse(string json)
        {
            int i = 0; var root = Value(json, ref i) as Dictionary<string, object>;
            if (root == null) throw new FormatException("not a report (no JSON object)");
            if (Str(root, "format") != "keystone-report-1") throw new FormatException("not a Keystone report (format must be keystone-report-1)");
            var r = new KeystoneReport { Title = Str(root, "title"), Subtitle = Str(root, "subtitle"), Instrument = Str(root, "instrument") == "" ? "MNQ" : Str(root, "instrument").ToUpperInvariant(), Method = Str(root, "method"), Generated = Str(root, "generated") };
            foreach (var o in List(root, "summary").OfType<Dictionary<string, object>>()) r.Summary.Add(new[] { Str(o, "label"), Str(o, "value"), Str(o, "note") });
            foreach (var o in List(root, "sections").OfType<Dictionary<string, object>>())
            {
                var s = new Section { Title = Str(o, "title"), Note = Str(o, "note") };
                s.Columns.AddRange(List(o, "columns").Select(x => Convert.ToString(x, CultureInfo.InvariantCulture)));
                foreach (var row in List(o, "rows").OfType<List<object>>()) s.Rows.Add(row.Select(x => Convert.ToString(x, CultureInfo.InvariantCulture)).ToList());
                r.Sections.Add(s);
            }
            foreach (var o in List(root, "days").OfType<Dictionary<string, object>>())
            {
                DateTime dt; if (!DateTime.TryParseExact(Str(o, "date"), "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out dt)) continue;
                var d = new Day { Date = dt, Label = Str(o, "label"), Color = Str(o, "color"), Note = Str(o, "note") };
                object f; if (o.TryGetValue("fields", out f) && f is Dictionary<string, object>) foreach (var kv in (Dictionary<string, object>)f) d.Fields[kv.Key] = Convert.ToString(kv.Value, CultureInfo.InvariantCulture);
                foreach (var m in List(o, "markers").OfType<Dictionary<string, object>>()) d.Markers.Add(new Marker { Time = Hm(Str(m, "time")), Price = Num(m, "price"), Text = Str(m, "text"), Kind = Str(m, "kind") == "" ? "info" : Str(m, "kind") });
                foreach (var t in List(o, "trades").OfType<Dictionary<string, object>>()) d.Trades.Add(new Trade { Dir = (int)Math.Sign(Num(t, "dir")), EntryTime = Hm(Str(t, "entryTime")), ExitTime = Hm(Str(t, "exitTime")), Entry = Num(t, "entry"), Stop = Num(t, "stop"), Target = Num(t, "target"), Exit = Num(t, "exit"), Pnl = Num(t, "pnl"), Why = Str(t, "why") });
                r.Days.Add(d);
            }
            r.Days = r.Days.OrderBy(d => d.Date).ToList();
            return r;
        }

        static TimeSpan Hm(string s) { TimeSpan t; return TimeSpan.TryParseExact(s ?? "", new[] { @"hh\:mm", @"h\:mm", @"hh\:mm\:ss" }, CultureInfo.InvariantCulture, out t) ? t : TimeSpan.Zero; }
        static string Str(Dictionary<string, object> o, string k) { object v; return o.TryGetValue(k, out v) && v != null ? Convert.ToString(v, CultureInfo.InvariantCulture) : ""; }
        static double Num(Dictionary<string, object> o, string k) { object v; return o.TryGetValue(k, out v) && v is double ? (double)v : double.NaN; }
        static List<object> List(Dictionary<string, object> o, string k) { object v; return o.TryGetValue(k, out v) && v is List<object> ? (List<object>)v : new List<object>(); }

        // a small JSON reader (objects, arrays, strings, numbers, true / false / null) — no extra assembly needed
        static object Value(string s, ref int i)
        {
            Ws(s, ref i); if (i >= s.Length) throw new FormatException("unexpected end of the file");
            char c = s[i];
            if (c == '{')
            {
                var o = new Dictionary<string, object>(); i++; Ws(s, ref i);
                if (s[i] == '}') { i++; return o; }
                while (true) { Ws(s, ref i); string k = (string)Value(s, ref i); Ws(s, ref i); if (s[i] != ':') throw new FormatException("':' expected at " + i); i++; o[k] = Value(s, ref i); Ws(s, ref i); if (s[i] == ',') { i++; continue; } if (s[i] == '}') { i++; return o; } throw new FormatException("',' or '}' expected at " + i); }
            }
            if (c == '[')
            {
                var l = new List<object>(); i++; Ws(s, ref i);
                if (s[i] == ']') { i++; return l; }
                while (true) { l.Add(Value(s, ref i)); Ws(s, ref i); if (s[i] == ',') { i++; continue; } if (s[i] == ']') { i++; return l; } throw new FormatException("',' or ']' expected at " + i); }
            }
            if (c == '"')
            {
                var b = new StringBuilder(); i++;
                while (s[i] != '"')
                {
                    if (s[i] == '\\') { i++; char e = s[i]; if (e == 'n') b.Append('\n'); else if (e == 't') b.Append('\t'); else if (e == 'u') { b.Append((char)Convert.ToInt32(s.Substring(i + 1, 4), 16)); i += 4; } else b.Append(e); i++; }
                    else b.Append(s[i++]);
                }
                i++; return b.ToString();
            }
            if (string.CompareOrdinal(s, i, "true", 0, 4) == 0) { i += 4; return true; }
            if (string.CompareOrdinal(s, i, "false", 0, 5) == 0) { i += 5; return false; }
            if (string.CompareOrdinal(s, i, "null", 0, 4) == 0) { i += 4; return null; }
            int a = i; while (i < s.Length && "+-0123456789.eE".IndexOf(s[i]) >= 0) i++;
            if (a == i) throw new FormatException("unexpected '" + c + "' at " + i);
            return double.Parse(s.Substring(a, i - a), NumberStyles.Float, CultureInfo.InvariantCulture);
        }
        static void Ws(string s, ref int i) { while (i < s.Length && char.IsWhiteSpace(s[i])) i++; }
    }

    public static class KeystoneOpeningRange
    {
        public static List<KeystoneOrbRule> Presets()
        {
            return new List<KeystoneOrbRule>
            {
                new KeystoneOrbRule { Name = "OPENING DRIVE • 10M CANDLE", Short = "DRIVE", Minutes = 10, Mode = "CANDLE", StopAtr = 0.25, TargetR = 4, SkipNews = true,
                    Evidence = "MNQ 2020–23: 720 trades, $13.8 a trade per micro • 2024–26 (unseen): 677 trades, $17.9 a trade, every year 2021–2026 positive • 35% winners, wins ≈ 3× losses" },
                new KeystoneOrbRule { Name = "OPENING RANGE BREAK • 15M", Short = "ORB15", Minutes = 15, Mode = "BREAK", StopAtr = 0.25, TargetR = 4, EntryWindow = 150, SkipNews = true,
                    Evidence = "MNQ 2020–23: 721 trades, $18.4 a trade per micro • 2024–26 (unseen): $8.9 a trade (weaker) • best prop results (passes and keeps funded accounts alive)" },
                new KeystoneOrbRule { Name = "OPENING RANGE BREAK • 30M 1R", Short = "ORB30", Minutes = 30, Mode = "BREAK", StopAtr = 0, TargetR = 1, EntryWindow = 90, SkipNews = false,
                    Evidence = "MNQ 2020–23: 748 trades, $10.8 a trade per micro • 2024–26 (unseen): $15.2 a trade • every year 2021–2026 positive • ~55% winners" },
            };
        }

        static DateTime At(DateTime session, int hhmm) { return session.Date.AddHours(hhmm / 100).AddMinutes(hhmm % 100); }
        static DateTime Session(DateTime barTime) { var t = barTime.AddMinutes(-1); return t.Hour >= 18 ? t.Date.AddDays(1) : t.Date; }
        public static bool NewsDay(DateTime day)
        {
            string k = day.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
            return KeystoneNews.FomcDates.Contains(k) || KeystoneNews.NfpDate(day.Year, day.Month) == day.Date;
        }

        // average 09:30–16:00 range of the 14 full sessions before `day` (prior = earlier bars, any order)
        public static double RthAtr(List<KeystoneArcBar> prior, DateTime day)
        {
            if (prior == null || prior.Count == 0) return double.NaN;
            var ranges = new List<double>();
            foreach (var g in prior.GroupBy(b => Session(b.Time)).Where(g => g.Key < day.Date && g.Key.DayOfWeek != DayOfWeek.Saturday && g.Key.DayOfWeek != DayOfWeek.Sunday).OrderByDescending(g => g.Key))
            {
                var list = g.ToList(); if (list.Count < 800) continue;
                DateTime a = At(g.Key, 930), b = At(g.Key, 1600);
                var rth = list.Where(x => x.Time > a && x.Time <= b).ToList();
                if (rth.Count < 300 || !rth.Any(x => x.Time == a.AddMinutes(1)) || !rth.Any(x => x.Time >= b.AddMinutes(-2))) continue;
                ranges.Add(rth.Max(x => x.High) - rth.Min(x => x.Low)); if (ranges.Count == 14) break;
            }
            return ranges.Count == 14 ? ranges.Average() : double.NaN;
        }

        // the day's signal(s) for a rule; session = the day's 1-minute bars (Time = bar close, New York)
        public static List<KeystoneReplaySignal> Signals(KeystoneOrbRule rule, List<KeystoneArcBar> session, List<KeystoneArcBar> prior, string symbol)
        {
            var output = new List<KeystoneReplaySignal>(); if (session == null || session.Count < 60) return output;
            DateTime day = Session(session[0].Time); if (rule.SkipNews && NewsDay(day)) return output;
            double tick = KeystoneMoveStudy.IsMgc(symbol) ? 0.1 : 0.25;
            DateTime o = At(day, rule.OpenHhmm), orEnd = o.AddMinutes(rule.Minutes), exit = At(day, rule.ExitHhmm).AddMinutes(1);
            var range = session.Where(b => b.Time > o && b.Time <= orEnd).ToList(); if (range.Count == 0 || range[0].Time != o.AddMinutes(1)) return output;
            double hi = range.Max(b => b.High), lo = range.Min(b => b.Low), w = hi - lo; if (w < 4 * tick) return output;
            double atr = RthAtr(prior, day); if (rule.StopAtr > 0 && double.IsNaN(atr)) return output;
            double stopD = rule.StopAtr > 0 ? rule.StopAtr * atr : w, tgtD = rule.TargetR > 0 ? rule.TargetR * stopD : 0;
            string tag = rule.Short + " " + rule.Minutes + "M";
            if (rule.Mode == "CANDLE")
            {
                double op = range[0].Open, cl = range[range.Count - 1].Close; int dir = Math.Sign(cl - op); if (dir == 0 || (rule.Side != 0 && dir != rule.Side)) return output;
                output.Add(new KeystoneReplaySignal { Time = orEnd, Exit = exit, Dir = dir, Entry = cl, Stop = cl - dir * stopD, Target = tgtD > 0 ? cl + dir * tgtD : double.NaN, StopDist = stopD, TargetDist = tgtD, Tag = tag, Tier = "T",
                    Why = "first " + rule.Minutes + " min closed " + (dir > 0 ? "UP" : "DOWN") + " (" + op.ToString("0.##", CultureInfo.InvariantCulture) + " → " + cl.ToString("0.##", CultureInfo.InvariantCulture) + ") • stop " + stopD.ToString("0.#", CultureInfo.InvariantCulture) + " pts" });
                return output;
            }
            DateTime cancel = orEnd.AddMinutes(rule.EntryWindow); int grp = day.DayOfYear;
            foreach (int dir in new[] { 1, -1 })
            {
                if (rule.Side != 0 && dir != rule.Side) continue; double lvl = dir > 0 ? hi : lo;
                // the bar that trades through the level (for the chart arrow); the AUTO trader works the stop order itself
                var hit = session.FirstOrDefault(b => b.Time > orEnd && b.Time <= cancel && (dir > 0 ? b.High >= hi + tick : b.Low <= lo - tick));
                output.Add(new KeystoneReplaySignal { Time = orEnd, Exit = exit, Dir = dir, Entry = lvl + dir * tick, Stop = lvl + dir * tick - dir * stopD, Target = tgtD > 0 ? lvl + dir * tick + dir * tgtD : double.NaN, StopDist = stopD, TargetDist = tgtD,
                    Order = "STOP", CancelAt = cancel, Group = grp, Tag = tag + (dir > 0 ? " HIGH" : " LOW"), Tier = "T",
                    Why = "range " + lo.ToString("0.##", CultureInfo.InvariantCulture) + " – " + hi.ToString("0.##", CultureInfo.InvariantCulture) + " • " + (dir > 0 ? "buy stop above the high" : "sell stop below the low") + " until " + cancel.ToString("HH:mm") + (hit == null ? " (not reached)" : "") });
            }
            return output;
        }
    }

    public static class KeystoneReplaySignals
    {
        public static readonly string[] Names = { "MANUAL (NO SIGNALS)", "1M FVG • 50% LIMIT (BUY + SELL)", "5M FVG • 50% LIMIT (BUY + SELL)", "1M FVG • CANDLE CLOSE (BUY + SELL)", "FVG RETEST + BREAK (BUY + SELL)", "BH • BREAK OF HIGH / LOW", "GOLDEN • FIRST BH / FVG AFTER THE OPEN", "ASIAN 75 REVERSAL LEGS", "★ OPENING DRIVE • 10M CANDLE (TESTED)", "★ OPENING RANGE BREAK • 15M (TESTED • PROP PICK)", "★ OPENING RANGE BREAK • 30M 1R (TESTED)" };
        public static List<KeystoneOrbRule> Rules = KeystoneOpeningRange.Presets();   // kinds 8, 9, 10 (editable in the studio)

        // The day's signals for the chosen strategy on one instrument's session bars (detectors of the lab, both directions).
        // tpPts: the target for the FVG signals (0 = 30 MNQ / 3 MGC); their stop is beyond the FVG's first candle.
        public static List<KeystoneReplaySignal> Build(int kind, List<KeystoneArcBar> sessionBars, string symbol, KeystoneArcRunConfig basis, double tpPts)
        {
            return Build(kind, sessionBars, symbol, basis, tpPts, null);
        }

        // prior = earlier sessions: the setup grades (A / B / C) are learned from the setups before the replayed day.
        public static List<KeystoneReplaySignal> Build(int kind, List<KeystoneArcBar> sessionBars, string symbol, KeystoneArcRunConfig basis, double tpPts, List<KeystoneArcBar> prior)
        {
            var output = new List<KeystoneReplaySignal>(); if (kind <= 0 || sessionBars == null || sessionBars.Count < 10) return output;
            if (kind >= 8 && kind - 8 < Rules.Count) return KeystoneOpeningRange.Signals(Rules[kind - 8], sessionBars, prior, symbol);
            bool mgc = KeystoneMoveStudy.IsMgc(symbol); double tp = tpPts > 0 ? tpPts : (mgc ? 3 : 30), gap = mgc ? 0.3 : 3;
            if (kind <= 3)
            {
                int tf = kind == 2 ? 5 : 1; string fill = kind == 3 ? "CLOSE" : "50";
                foreach (var t in KeystoneIdeas.FvgTrades(sessionBars, symbol, tf, fill, 1800, 1700, -1, gap, tp, -1))
                    output.Add(new KeystoneReplaySignal { Time = t.EntryTime.AddMinutes(-1), Exit = t.ExitTime, Dir = t.Dir, Entry = t.Entry, Stop = t.Stop, Target = t.Target, Tag = tf + "M FVG" + (fill == "50" ? " 50%" : "") });
                return output;
            }
            var cfg = basis == null ? new KeystoneArcRunConfig() : basis.ShallowCopy();
            cfg.Scope = symbol; cfg.TradeSide = "BOTH"; cfg.SessionMode = "FULL_GLOBEX"; cfg.OutcomeModelEnabled = 1;
            DateTime dayStart = sessionBars[0].Time.AddMinutes(-1), dayEnd = sessionBars[sessionBars.Count - 1].Time;
            var all = prior != null && prior.Count > 0 && kind != 7 ? prior.Where(b => b.Time < sessionBars[0].Time).Concat(sessionBars).ToList() : sessionBars;
            cfg.Start = all[0].Time.AddMinutes(-1); cfg.End = dayEnd;
            if (kind == 4) { cfg.StrategyCode = "FVG"; cfg.EnableFvg = 1; cfg.SetupMinutes = 5; }
            else if (kind == 5) { cfg.StrategyCode = "BH"; cfg.EnableBh = 1; cfg.EnableFvg = 0; cfg.SetupMinutes = 5; }
            else if (kind == 6) { cfg.StrategyCode = "GLD"; cfg.SetupMinutes = 5; cfg.GoldenTakeAll = 1; cfg.GoldenMaxTradesPerDay = 5; }
            else { cfg.StrategyCode = "ASIAN75"; cfg.SetupMinutes = 1; }
            var setup = cfg.SetupMinutes <= 1 ? all : KeystoneArcEngine.ToSetupBars(all, symbol, cfg.SetupMinutes);
            List<KeystoneArcEvent> ev;
            try { ev = KeystoneArcEngine.DetectAndResolve(all, setup, cfg); } catch { ev = new List<KeystoneArcEvent>(); }
            foreach (var e in ev.Where(x => x.EntryTime != DateTime.MinValue && x.EntryTime > dayStart && x.EntryTime <= dayEnd && !double.IsNaN(x.Entry) && string.Equals(x.Symbol, symbol, StringComparison.OrdinalIgnoreCase)))
                output.Add(new KeystoneReplaySignal { Time = e.EntryTime.AddMinutes(-1), Exit = e.ExitTime, Dir = e.Direction == "SHORT" ? -1 : 1, Entry = e.Entry, Stop = e.Stop, Target = e.Target, Tag = e.SetupClass ?? cfg.StrategyCode, Tier = e.QualityTier ?? string.Empty });
            return output.OrderBy(x => x.Time).ToList();
        }
    }

    public sealed class KeystoneReplayFill { public DateTime EntryTime, ExitTime; public string Symbol = string.Empty, Side = string.Empty, Reason = string.Empty; public int Qty; public double Entry, Exit, Points, Net, Gross, Fee; }

    public sealed class KeystoneReplayTrader
    {
        public readonly List<KeystoneArcBar> Bars; public readonly string Symbol; public readonly int StepsPerBar;
        public int BarIndex, Step; public double Price; public DateTime Time;
        public int Position; public double AvgPrice, StopPts, TargetPts, Realized; public DateTime PositionTime;
        public List<KeystoneReplayFill> Fills = new List<KeystoneReplayFill>();
        public List<KeystoneReplayOrder> Orders = new List<KeystoneReplayOrder>(); int nextOrderId = 1;
        public double Tick { get { return tick; } }
        readonly double pv, cost, tick;
        public bool Live { get; private set; }   // LIVE: bars arrive from NinjaTrader's real-time feed (the last one is forming); no replay clock
        // LINKED to a real account (KeystoneAccountLink): the account is the truth — no simulated fills, no simulated stop / target /
        // order execution; your actions only change the intent, which the link sends to the account
        public bool Slave;
        public void Adopt(int qty, double avg, DateTime now) { if (Position == 0 && qty != 0) PositionTime = Time; Position = qty; AvgPrice = qty == 0 ? 0 : avg; }   // the chart's clock (the bars' time zone)
        public void AddRealFill(KeystoneReplayFill f) { if (f == null) return; Fills.Add(f); Realized += f.Net; }

        // LIVE: the session so far (last bar = the forming one); prices then come in through LiveUpdate
        public static KeystoneReplayTrader LiveStart(List<KeystoneArcBar> sessionSoFar, string symbol, DateTime now)
        {
            var t = new KeystoneReplayTrader(new List<KeystoneArcBar>(sessionSoFar ?? new List<KeystoneArcBar>()), symbol, 4) { Live = true };
            t.BarIndex = Math.Max(0, t.Bars.Count - 1); t.Step = 1;
            if (t.Bars.Count > 0) t.Price = t.Bars[t.Bars.Count - 1].Close; t.Time = now;
            return t;
        }

        // LIVE: a new or updated 1-minute bar (bar.Time = its close time) and the current time; works orders and the bracket at the new price
        public void LiveUpdate(KeystoneArcBar bar, DateTime now)
        {
            if (!Live || bar == null) return;
            if (Bars.Count == 0 || bar.Time > Bars[Bars.Count - 1].Time) Bars.Add(new KeystoneArcBar { Symbol = bar.Symbol, Time = bar.Time, Open = bar.Open, High = bar.High, Low = bar.Low, Close = bar.Close, Volume = bar.Volume });
            else if (bar.Time == Bars[Bars.Count - 1].Time) { var l = Bars[Bars.Count - 1]; l.Open = bar.Open; l.High = bar.High; l.Low = bar.Low; l.Close = bar.Close; l.Volume = bar.Volume; }
            else return;   // an older bar: ignore
            BarIndex = Bars.Count - 1; Step = 1; Price = bar.Close; Time = now;
            if (!Slave) { CheckOrders(); CheckBracket(); }
        }

        public KeystoneReplayTrader(List<KeystoneArcBar> sessionBars, string symbol, int stepsPerBar)
        {
            Bars = sessionBars ?? new List<KeystoneArcBar>(); Symbol = (symbol ?? "MNQ").ToUpperInvariant(); StepsPerBar = Math.Max(4, stepsPerBar);
            pv = KeystoneMoveStudy.PointValue(Symbol); cost = KeystoneMoveStudy.Cost(Symbol); tick = KeystoneMoveStudy.IsMgc(Symbol) ? 0.1 : 0.25;
            BarIndex = 0; Step = 0; if (Bars.Count > 0) { Price = Bars[0].Open; Time = Bars[0].Time.AddMinutes(-1); }
        }

        public bool Finished { get { return BarIndex >= Bars.Count; } }
        public double Unrealized { get { return Position == 0 ? 0 : (Price - AvgPrice) * Position * pv; } }
        public double DayNet { get { return Realized + Unrealized; } }

        // The simulated price at step k (0 … StepsPerBar) of a 1-minute bar.
        public static double PathPrice(KeystoneArcBar b, int k, int steps, double tick)
        {
            bool highFirst = b.Close < b.Open || (b.Close == b.Open && b.High - b.Open < b.Open - b.Low);
            double a = highFirst ? b.High : b.Low, c = highFirst ? b.Low : b.High;
            double l0 = Math.Abs(a - b.Open), l1 = Math.Abs(c - a), l2 = Math.Abs(b.Close - c), total = l0 + l1 + l2, range = b.High - b.Low;
            if (total <= 0 || steps < 3) return b.Close;
            // the steps where the walk stands exactly on the first extreme (k1) and the second (k2)
            int k1 = Math.Max(1, Math.Min(steps - 2, (int)Math.Round(steps * l0 / total))), k2 = Math.Max(k1 + 1, Math.Min(steps - 1, (int)Math.Round(steps * (l0 + l1) / total)));
            if (k <= 0) return b.Open; if (k >= steps) return b.Close; if (k == k1) return a; if (k == k2) return c;
            double from, to; int ka, kb; int leg;
            if (k < k1) { from = b.Open; to = a; ka = 0; kb = k1; leg = 0; } else if (k < k2) { from = a; to = c; ka = k1; kb = k2; leg = 1; } else { from = c; to = b.Close; ka = k2; kb = steps; leg = 2; }
            double t = (k - ka) / (double)Math.Max(1, kb - ka), p = from + (to - from) * t;
            // realistic wiggle: smooth swings that vanish at the leg's ends + one-tick jitter (seeded by the minute, so a replay
            // is the same every time); kept inside the minute's real high / low, so the open, high, low and close stay exact
            unchecked
            {
                long seed = b.Time.Ticks / 600000000L * 31 + leg * 7 + 1; Func<long, double> rnd = n => { long x = (seed * 6364136223846793005L + n * 1442695040888963407L) >> 11; return (x & 0xFFFFF) / (double)0xFFFFF; };
                double f1 = 2 + 3 * rnd(1), f2 = 5 + 4 * rnd(2), ph1 = 6.283 * rnd(3), ph2 = 6.283 * rnd(4), amp = 0.22 * range;
                p += amp * Math.Sin(Math.PI * t) * (0.65 * Math.Sin(6.283 * f1 * t + ph1) + 0.35 * Math.Sin(6.283 * f2 * t + ph2));
                p += (rnd(100 + k) - 0.5) * 2 * tick;
            }
            double lo = Math.Min(from, to) - 0.2 * range, hi = Math.Max(from, to) + 0.2 * range;
            p = Math.Max(Math.Max(lo, b.Low), Math.Min(Math.Min(hi, b.High), p));
            return Math.Round(p / tick) * tick;
        }

        // The candles so far in the chosen timeframe, the last one still forming (its close = the current price).
        // one candle per trading session (18:00 New York → 17:00)
        public static List<KeystoneArcBar> DailyCandles(List<KeystoneArcBar> bars)
        {
            var outD = new List<KeystoneArcBar>(); if (bars == null || bars.Count == 0) return outD;
            foreach (var g in bars.GroupBy(b => KeystoneStudioStore.SessionOf(b.Time)).OrderBy(g => g.Key))
            {
                var l = g.OrderBy(b => b.Time).ToList();
                outD.Add(new KeystoneArcBar { Symbol = l[0].Symbol, Time = l[l.Count - 1].Time, Open = l[0].Open, High = l.Max(b => b.High), Low = l.Min(b => b.Low), Close = l[l.Count - 1].Close, Volume = l.Sum(b => b.Volume) });
            }
            return outD;
        }
        public List<KeystoneArcBar> Candles(int minutes)
        {
            var done = Live ? Bars.ToList() : Bars.Take(BarIndex).ToList();
            if (!Live && !Finished && Step > 0) { var b = Bars[BarIndex]; var part = new KeystoneArcBar { Symbol = b.Symbol, Time = b.Time, Open = b.Open, High = b.Open, Low = b.Open, Close = Price };
                for (int k = 0; k <= Step; k++) { double p = PathPrice(b, k, StepsPerBar, tick); part.High = Math.Max(part.High, p); part.Low = Math.Min(part.Low, p); } done.Add(part); }
            if (minutes >= 1440) return DailyCandles(done);
            return KeystoneEngLab.Candles(done, Math.Max(1, minutes));
        }

        // Working orders: a LIMIT buys at or below its price (sells at or above); a STOP buys once price reaches it from below
        // (sells from above). Filled at the order price on the step that reaches it.
        public KeystoneReplayOrder Place(string type, int dir, int qty, double price)
        {
            var o = new KeystoneReplayOrder { Id = nextOrderId++, Type = type == "STOP" ? "STOP" : "LIMIT", Dir = dir > 0 ? 1 : -1, Qty = Math.Max(1, qty), Price = Math.Round(price / tick) * tick };
            Orders.Add(o); return o;
        }
        public void CancelOrders() { Orders.Clear(); }
        void CheckOrders()
        {
            foreach (var o in Orders.ToList())
            {
                bool hit = o.Type == "LIMIT" ? (o.Dir > 0 ? Price <= o.Price + 1e-9 : Price >= o.Price - 1e-9) : (o.Dir > 0 ? Price >= o.Price - 1e-9 : Price <= o.Price + 1e-9);
                if (!hit) continue;
                Orders.Remove(o); double keep = Price; Price = o.Price; Trade(o.Dir * o.Qty); Price = keep;
            }
        }

        // One step forward; returns false at the end of the session (an open position is closed at the last price).
        public bool Advance()
        {
            if (Live) return true;   // LIVE: prices come from LiveUpdate
            if (Finished) return false;
            var b = Bars[BarIndex]; Step++;
            Price = PathPrice(b, Step, StepsPerBar, tick); Time = b.Time.AddMinutes(-1).AddSeconds(60.0 * Step / StepsPerBar);
            CheckOrders(); CheckBracket();
            if (Step >= StepsPerBar) { Step = 0; BarIndex++; Time = b.Time; }
            if (Finished) { Orders.Clear(); if (Position != 0) CloseAll("SESSION END"); }
            return !Finished;
        }

        // Advance until the replay clock reaches t (several instruments stay on one clock); false at the end of the session.
        public bool AdvanceTo(DateTime t, int maxSteps)
        {
            int n = 0; while (!Finished && Time < t && n < maxSteps) { Advance(); n++; }
            return !Finished;
        }

        public void JumpTo(DateTime t) { while (!Finished && Bars[BarIndex].Time <= t) { Step = 0; Price = Bars[BarIndex].Close; Time = Bars[BarIndex].Time; BarIndex++; if (Position != 0) CheckBracketBar(Bars[BarIndex - 1]); } }

        void CheckBracketBar(KeystoneArcBar b)
        {
            for (int k = 1; k <= StepsPerBar && Position != 0; k++) { Price = PathPrice(b, k, StepsPerBar, tick); CheckBracket(); }
            Price = b.Close;
        }

        void CheckBracket()
        {
            if (Position == 0) return; int dir = Math.Sign(Position);
            if (StopPts != 0 && dir * (Price - AvgPrice) <= -StopPts + 1e-9) { Price = AvgPrice - dir * StopPts; CloseAll(StopPts < 0 ? "PROFIT STOP" : "STOP"); return; }   // StopPts < 0 = a stop past the entry (locks profit)
            if (TargetPts > 0 && dir * (Price - AvgPrice) >= TargetPts - 1e-9) { Price = AvgPrice + dir * TargetPts; CloseAll("TARGET"); }
        }

        public void Buy(int qty) { Trade(Math.Max(1, qty)); }
        public void Sell(int qty) { Trade(-Math.Max(1, qty)); }

        void Trade(int signedQty)
        {
            if (Finished && Bars.Count > 0) return;
            if (Position != 0 && Math.Sign(Position) != Math.Sign(signedQty))
            {
                int closing = Math.Min(Math.Abs(Position), Math.Abs(signedQty));
                Record(closing, "MANUAL"); Position += Math.Sign(signedQty) * closing; signedQty -= Math.Sign(signedQty) * closing;
                if (Position == 0) AvgPrice = 0;
            }
            if (signedQty == 0) return;
            if (Position == 0) { PositionTime = Time; AvgPrice = Price; Position = signedQty; }
            else { AvgPrice = (AvgPrice * Math.Abs(Position) + Price * Math.Abs(signedQty)) / (Math.Abs(Position) + Math.Abs(signedQty)); Position += signedQty; }
        }

        public void CloseAll(string reason) { if (Position != 0) { Record(Math.Abs(Position), reason); Position = 0; AvgPrice = 0; } }

        void Record(int qty, string reason)
        {
            if (Slave) return;   // linked: the real fills make the trades
            int dir = Math.Sign(Position); double pts = dir * (Price - AvgPrice), net = pts * pv * qty - cost * qty;
            Realized += net;
            Fills.Add(new KeystoneReplayFill { Symbol = Symbol, Side = dir > 0 ? "BUY" : "SELL", Qty = qty, Entry = AvgPrice, Exit = Price, EntryTime = PositionTime, ExitTime = Time, Points = pts, Net = net, Reason = reason });
        }

        // The journal: one CSV line per finished trade (appended), so every replayed day is kept.
        public static string JournalLine(DateTime session, KeystoneReplayFill f)
        {
            return string.Join(",", session.ToString("yyyy-MM-dd"), f.Symbol, f.Side, f.Qty, f.EntryTime.ToString("yyyy-MM-dd HH:mm:ss"), f.Entry.ToString(CultureInfo.InvariantCulture), f.ExitTime.ToString("yyyy-MM-dd HH:mm:ss"), f.Exit.ToString(CultureInfo.InvariantCulture), f.Points.ToString("0.##", CultureInfo.InvariantCulture), f.Net.ToString("0.00", CultureInfo.InvariantCulture), f.Reason);
        }
        public const string JournalHeader = "session,symbol,side,qty,entry_time,entry,exit_time,exit,points,net,reason";
    }

    // ---- ACCOUNT LINK: the studio's live chart IS the real NinjaTrader account --------------------------------------------
    // The real account is the truth. Every tick the studio shows its position, average price, stop / target and working
    // orders — wherever they were placed (the studio, NinjaTrader's Chart Trader / DOM / ATM). What you do in the studio (BUY /
    // SELL / CLOSE, drag a stop / target / order, BE, ✕, AUTO) is turned into real orders — only while ARMED; unarmed the studio
    // only WATCHES (and refuses to trade). Every fill is turned into a trade (journal). Safety while armed: max contracts, day
    // loss limit and day profit cap (flatten + disarm), runaway guard, a rejected order disarms, minimum hold time.
    public sealed class KeystoneBrokerOrder
    {
        public string Id = string.Empty, Kind = "MARKET", Oco = string.Empty, Name = string.Empty;   // Kind: MARKET, LIMIT, STOP
        public int Side, Qty, Filled; public double Price; public bool Done, Rejected, CancelSent, Ours; public object Native;
    }
    public sealed class KeystoneExec { public string Id = string.Empty, Name = string.Empty; public DateTime Time; public int SignedQty; public double Price, Commission; }

    public interface IKeystoneBroker
    {
        bool Connected { get; }
        int Qty { get; }                                  // signed real position in this instrument
        double AvgPrice { get; }
        double DayPnl { get; }                            // the account's realized + open P/L today
        double Tick { get; }
        List<KeystoneBrokerOrder> Working();              // every working order on this instrument (the studio's and NinjaTrader's)
        List<KeystoneExec> Executions();                  // this instrument's executions (any order)
        KeystoneBrokerOrder Submit(string kind, int signedQty, double price, string oco, bool automated);   // null = refused
        void ChangePrice(KeystoneBrokerOrder o, double price);
        void Cancel(KeystoneBrokerOrder o);
        void Flatten();
    }

    // Executions → finished trades (average price, partial closes and reversals included).
    public sealed class KeystoneTradeBuilder
    {
        public int Pos; public double Avg, PosComm; public DateTime Since; readonly HashSet<string> seen = new HashSet<string>(); bool realFees;
        readonly string symbol; readonly double pv, cost;
        public KeystoneTradeBuilder(string sym) { symbol = (sym ?? "MNQ").ToUpperInvariant(); pv = KeystoneMoveStudy.PointValue(symbol); cost = KeystoneMoveStudy.Cost(symbol); }
        // executions already there when the link starts: they set the position, they are not new trades
        public void Prime(IEnumerable<KeystoneExec> list) { foreach (var e in (list ?? new List<KeystoneExec>()).OrderBy(x => x.Time)) { if (e == null || !seen.Add(e.Id)) continue; Apply(e, null); } }
        public List<KeystoneReplayFill> Add(IEnumerable<KeystoneExec> list)
        {
            var output = new List<KeystoneReplayFill>();
            foreach (var e in (list ?? new List<KeystoneExec>()).OrderBy(x => x.Time)) { if (e == null || e.SignedQty == 0 || !seen.Add(e.Id)) continue; Apply(e, output); }
            return output;
        }
        public void Anchor(int qty, double avg, DateTime now) { if (qty == Pos && (qty == 0 || Math.Abs(avg - Avg) < 1e-9)) return; if (Pos == 0 && qty != 0) Since = now; Pos = qty; Avg = qty == 0 ? 0 : avg; }
        void Apply(KeystoneExec e, List<KeystoneReplayFill> output)
        {
            int q = e.SignedQty; int all = Math.Abs(q); if (e.Commission > 0) realFees = true;
            if (Pos != 0 && Math.Sign(q) != Math.Sign(Pos))
            {
                int closing = Math.Min(Math.Abs(Pos), Math.Abs(q)); int dir = Math.Sign(Pos); double pts = dir * (e.Price - Avg);
                // fees: the commissions NinjaTrader reported (the entry's share + this exit's share); an estimate only when none were reported
                double entryShare = PosComm * closing / Math.Abs(Pos), fee = realFees ? entryShare + e.Commission * closing / all : cost * closing; PosComm -= entryShare;
                if (output != null) output.Add(new KeystoneReplayFill { Symbol = symbol, Side = dir > 0 ? "BUY" : "SELL", Qty = closing, Entry = Avg, Exit = e.Price, EntryTime = Since, ExitTime = e.Time, Points = pts, Net = pts * pv * closing - fee, Gross = pts * pv * closing, Fee = fee, Reason = "REAL • " + (e.Name.StartsWith("KEYSTONE") ? "STUDIO" : "NINJATRADER") });
                Pos += Math.Sign(q) * closing; q -= Math.Sign(q) * closing; if (Pos == 0) { Avg = 0; PosComm = 0; }
            }
            if (q == 0) return;
            PosComm += e.Commission * Math.Abs(q) / all;
            if (Pos == 0) { Pos = q; Avg = e.Price; Since = e.Time; }
            else { Avg = (Avg * Math.Abs(Pos) + e.Price * Math.Abs(q)) / (Math.Abs(Pos) + Math.Abs(q)); Pos += q; }
        }
    }

    public sealed class KeystoneAccountLink
    {
        public readonly IKeystoneBroker Broker; public readonly KeystoneTradeBuilder Trades;
        public bool Armed { get; private set; }
        public int MaxContracts = 2, MinHoldSeconds; public double DayLossLimit = 500, DayProfitCap; public bool Automated, AutoStop; public double DefaultStopPts;
        public bool Locked, LockFlatten;
        public bool AutoOco = true;   // one cancels the other for EVERY order on the account (also NinjaTrader's): a closed position cancels its stop / target, a filled entry cancels the other entries
        HashSet<KeystoneBrokerOrder> protSeen = new HashSet<KeystoneBrokerOrder>(), entrySeen = new HashSet<KeystoneBrokerOrder>();   // LOCKED FOR TODAY: the studio places nothing; LockFlatten = a position opened anyway (e.g. in NinjaTrader) is closed
        public bool Connected { get; private set; }
        DateTime lockFlatAt = DateTime.MinValue;
        public string State = "WATCHING", Warning = ""; public bool Pulled; public readonly List<string> Log = new List<string>();
        public readonly List<KeystoneReplayFill> NewFills = new List<KeystoneReplayFill>();   // real trades not yet saved by the UI
        public Action<string> Disarmed;
        // the state both sides agreed on last (studio == real); a difference on the studio side = something you did in the studio
        int sQty; double sStop, sTgt; readonly Dictionary<int, KeystoneBrokerOrder> map = new Dictionary<int, KeystoneBrokerOrder>(); readonly Dictionary<int, double> sPrice = new Dictionary<int, double>();
        int? pendingQty; bool bracketWanted; DateTime waitUntil = DateTime.MinValue; readonly List<DateTime> sends = new List<DateTime>(); int ocoSeq; DateTime realSince = DateTime.MinValue; int lastReal;
        readonly HashSet<string> protective = new HashSet<string>(); readonly List<KeystoneBrokerOrder> ours = new List<KeystoneBrokerOrder>(); DateTime bracketWait = DateTime.MinValue;

        public KeystoneAccountLink(IKeystoneBroker broker, string symbol) { Broker = broker; Trades = new KeystoneTradeBuilder(symbol); try { Trades.Prime(broker.Executions()); } catch { } }

        public string Arm(DateTime now)
        {
            if (Broker == null || !Broker.Connected) return "THE ACCOUNT IS NOT CONNECTED IN NINJATRADER";
            if (MaxContracts < 1) return "MAX CONTRACTS MUST BE 1 OR MORE";
            if (Math.Abs(Broker.Qty) > MaxContracts) return "THE ACCOUNT HOLDS " + Math.Abs(Broker.Qty) + " — MORE THAN MAX QTY " + MaxContracts;
            Armed = true; sends.Clear(); Note(now, "ARMED • max " + MaxContracts + " • day loss $" + DayLossLimit.ToString("0", CultureInfo.InvariantCulture) + (DayProfitCap > 0 ? " • day cap $" + DayProfitCap.ToString("0", CultureInfo.InvariantCulture) : "") + (MinHoldSeconds > 0 ? " • min hold " + MinHoldSeconds + "s" : ""));
            return null;
        }
        public void Disarm(string why, DateTime now, bool flatten)
        {
            if (!Armed) return; Armed = false; pendingQty = null; bracketWanted = false;
            if (flatten) { try { Broker.Flatten(); } catch { } }
            Note(now, "DISARMED • " + why + (flatten ? " • FLATTENED" : "")); State = "WATCHING • " + why;
            if (Disarmed != null) Disarmed(why);
        }
        void Note(DateTime now, string s) { Log.Add(now.ToString("HH:mm:ss", CultureInfo.InvariantCulture) + " " + s); if (Log.Count > 300) Log.RemoveAt(0); }
        double Tk { get { return Broker.Tick > 0 ? Broker.Tick : 0.25; } }
        double Round(double p) { return Math.Round(p / Tk) * Tk; }
        static string Px(double p) { return p.ToString("0.00", CultureInfo.InvariantCulture); }
        bool Guard(DateTime now) { sends.RemoveAll(x => (now - x).TotalSeconds > 60); if (sends.Count >= 8) { Disarm("RUNAWAY GUARD: 8 ORDERS IN A MINUTE", now, true); return false; } sends.Add(now); return true; }
        KeystoneBrokerOrder Send(string kind, int signedQty, double price, string oco, DateTime now, string what)
        {
            if (!Guard(now)) return null;
            var o = Broker.Submit(kind, signedQty, price, oco, Automated);
            if (o == null) { Disarm("NINJATRADER REFUSED THE ORDER (" + what + ")", now, false); return null; }
            o.Ours = true; ours.Add(o); if (ours.Count > 200) ours.RemoveAt(0); Note(now, what); return o;
        }

        // protective orders: the working orders on the other side of the position (stop orders = stop, limit orders = target)
        void Classify(int real, List<KeystoneBrokerOrder> work, out KeystoneBrokerOrder stop, out KeystoneBrokerOrder tgt, out List<KeystoneBrokerOrder> entries)
        {
            stop = null; tgt = null; entries = new List<KeystoneBrokerOrder>(); int dir = Math.Sign(real);
            var studioWorking = new HashSet<KeystoneBrokerOrder>(map.Values);   // the studio's own working orders (e.g. TAKE PROFIT steps) are never the bracket
            foreach (var o in work)
            {
                if (studioWorking.Contains(o)) { entries.Add(o); continue; }
                if (real != 0 && o.Side == -dir && o.Kind == "STOP") { if (stop == null || Math.Abs(o.Price - Broker.AvgPrice) < Math.Abs(stop.Price - Broker.AvgPrice)) stop = o; }
                else if (real != 0 && o.Side == -dir && o.Kind == "LIMIT") { if (tgt == null || Math.Abs(o.Price - Broker.AvgPrice) < Math.Abs(tgt.Price - Broker.AvgPrice)) tgt = o; }
                else entries.Add(o);
            }
        }

        public void Tick(KeystoneReplayTrader t, DateTime now)
        {
            Pulled = false; Warning = "";
            if (t == null) return;
            Connected = Broker.Connected;
            // 1. real fills → trades (the studio's trade list + the journal)
            try { foreach (var f in Trades.Add(Broker.Executions())) { t.AddRealFill(f); NewFills.Add(f); } } catch { }
            int real = Broker.Qty; double avg = Broker.AvgPrice; Trades.Anchor(real, avg, now); int prevReal = lastReal;
            if (real != 0 && lastReal == 0) realSince = now; lastReal = real;
            var work = Broker.Working().Where(o => !o.Done && !o.CancelSent).ToList();
            if (AutoOco && Connected)
            {
                // one cancels the other: the trade closed → its leftover stop / target goes; an entry filled → the other entries go
                var stale = new List<KeystoneBrokerOrder>();
                if (real == 0 && prevReal != 0) stale.AddRange(protSeen.Where(work.Contains));
                if (real != 0 && prevReal == 0) stale.AddRange(entrySeen.Where(work.Contains));
                foreach (var o in stale) { Broker.Cancel(o); Note(now, "ONE-CANCELS-OTHER • cancelled " + (o.Side > 0 ? "BUY " : "SELL ") + o.Kind + " @ " + Px(o.Price)); }
                if (stale.Count > 0) work = work.Where(o => !stale.Contains(o)).ToList();
            }
            if (real != 0) { protSeen = new HashSet<KeystoneBrokerOrder>(work.Where(o => o.Side == -Math.Sign(real) && o.Kind != "MARKET")); entrySeen.Clear(); }
            else { entrySeen = new HashSet<KeystoneBrokerOrder>(work.Where(o => o.Kind != "MARKET")); protSeen.Clear(); }
            KeystoneBrokerOrder rStop, rTgt; List<KeystoneBrokerOrder> rEntries; Classify(real, work, out rStop, out rTgt, out rEntries);
            if (real == 0) foreach (var o in work.Where(o => protective.Contains(o.Id)).ToList()) { Broker.Cancel(o); protective.Remove(o.Id); }   // a leftover leg of our bracket
            // the position got smaller (a TAKE PROFIT step or a partial exit filled): a stop / target still sized for more would open a reverse
            // position when it fills — cancel the pair and rebuild it for what is left
            if (Armed && Connected && !Locked && real != 0 && ((rStop != null && rStop.Qty - rStop.Filled > Math.Abs(real)) || (rTgt != null && rTgt.Qty - rTgt.Filled > Math.Abs(real))))
            {
                if (rStop != null) Broker.Cancel(rStop); if (rTgt != null && !rTgt.CancelSent) Broker.Cancel(rTgt);
                Note(now, "POSITION NOW " + Math.Abs(real) + " • stop / target resized"); bracketWanted = true; bracketWait = now.AddSeconds(2);
                rStop = null; rTgt = null;
            }
            if (map.Values.Any(b => b.Ours && b.Done && b.Filled > 0) && real != 0) bracketWanted = true;   // a studio entry order filled: its stop / target follow
            if (!Connected || Locked) pendingQty = null;
            // 2. limits
            double pnl = Broker.DayPnl;
            if (Armed && Connected && DayLossLimit > 0 && pnl <= -Math.Abs(DayLossLimit)) { Disarm("DAY LOSS LIMIT $" + DayLossLimit.ToString("0", CultureInfo.InvariantCulture) + " REACHED", now, true); return; }
            if (Armed && Connected && DayProfitCap > 0 && pnl >= DayProfitCap) { Disarm("DAY PROFIT CAP $" + DayProfitCap.ToString("0", CultureInfo.InvariantCulture) + " REACHED (consistency rule) — done for today", now, true); return; }
            if (Armed && ours.Any(o => o.Rejected)) { Disarm("AN ORDER WAS REJECTED BY THE BROKER", now, true); return; }
            if (!Armed && DayProfitCap > 0 && pnl >= DayProfitCap) Warning = "DAY CAP REACHED — stop trading today (consistency)";
            if (!Armed && DayLossLimit > 0 && pnl <= -Math.Abs(DayLossLimit)) Warning = "DAY LOSS LIMIT REACHED — stop trading today";

            // 3. a size change waiting for its bracket to be cancelled first (reduce / reverse), or for the minimum hold
            if (pendingQty.HasValue && Armed && Connected && !Locked)
            {
                int want = pendingQty.Value; bool exiting = real != 0 && (want == 0 || Math.Sign(want) != Math.Sign(real) || Math.Abs(want) < Math.Abs(real));
                if (exiting && MinHoldSeconds > 0 && (now - realSince).TotalSeconds < MinHoldSeconds) { State = "ARMED • HOLDING " + Math.Ceiling(MinHoldSeconds - (now - realSince).TotalSeconds) + "s (min hold; the stop protects)"; return; }
                if (want == real) pendingQty = null;
                else if (want == 0) { if (!Guard(now)) return; Broker.Flatten(); Note(now, "FLATTEN"); waitUntil = now.AddSeconds(4); bracketWanted = false; pendingQty = null; State = "ARMED • FLATTENING"; return; }
                else if (exiting && (rStop != null || rTgt != null)) { if (rStop != null) Broker.Cancel(rStop); if (rTgt != null && !rTgt.CancelSent) Broker.Cancel(rTgt); State = "ARMED • CANCELLING THE BRACKET FIRST"; return; }
                else { Send("MARKET", want - real, 0, "", now, (want - real > 0 ? "BUY " : "SELL ") + Math.Abs(want - real) + " MARKET → " + want); waitUntil = now.AddSeconds(4); pendingQty = null; bracketWanted = t.StopPts != 0 || t.TargetPts > 0; State = "ARMED • ORDER SENT"; return; }
            }
            // waiting for the broker: until the real position matches what was sent (max 4 s), the studio keeps your intent
            if (Connected && !Locked && now < waitUntil && real != sQty) { State = Armed ? "ARMED • WAITING FOR THE FILL" : State; return; }

            // 4. what changed in the studio since the last agreement?
            bool qtyCh = t.Position != sQty, stopCh = Math.Abs(t.StopPts - sStop) > Tk / 2, tgtCh = Math.Abs(t.TargetPts - sTgt) > Tk / 2;
            var studioIds = new HashSet<int>(t.Orders.Select(o => o.Id));
            var newOrders = t.Orders.Where(o => !map.ContainsKey(o.Id)).ToList();
            var goneOrders = map.Keys.Where(id => !studioIds.Contains(id)).ToList();
            var moved = t.Orders.Where(o => map.ContainsKey(o.Id) && sPrice.ContainsKey(o.Id) && Math.Abs(sPrice[o.Id] - o.Price) > Tk / 2).ToList();
            bool studioActed = qtyCh || stopCh || tgtCh || newOrders.Count > 0 || goneOrders.Count > 0 || moved.Count > 0;
            if (!Connected) { pendingQty = null; State = "CONNECTION LOST • stops / targets stay at the broker"; Warning = "CONNECTION LOST — orders blocked until it is back"; Pull(t, real, avg, rStop, rTgt, rEntries, now); return; }
            if (Locked)
            {
                pendingQty = null; State = "LOCKED FOR TODAY";
                if (real != 0 && LockFlatten && (now - lockFlatAt).TotalSeconds > 5) { lockFlatAt = now; Broker.Flatten(); Note(now, "LOCKED → FLATTEN"); Warning = "LOCKED FOR TODAY — the position was closed"; }
                else if (studioActed) Warning = "LOCKED FOR TODAY — no trading on this account until 18:00 NY";
                Pull(t, real, avg, rStop, rTgt, rEntries, now); return;
            }
            if (studioActed && !Armed) { Warning = "NOT ARMED — the studio only watches; press ARM to trade from here"; Pull(t, real, avg, rStop, rTgt, rEntries, now); return; }
            if (studioActed)
            {
                // working orders
                foreach (var o in newOrders) { var b = Send(o.Type == "STOP" ? "STOP" : "LIMIT", o.Dir * Math.Min(o.Qty, MaxContracts), o.Price, "", now, (o.Dir > 0 ? "BUY " : "SELL ") + o.Type + " " + Math.Min(o.Qty, MaxContracts) + " @ " + Px(o.Price)); if (b == null) return; map[o.Id] = b; sPrice[o.Id] = o.Price; }
                foreach (var id in goneOrders) { var b = map[id]; if (!b.Done && !b.CancelSent) { Broker.Cancel(b); Note(now, "CANCEL " + b.Kind + " @ " + Px(b.Price)); } map.Remove(id); sPrice.Remove(id); }
                foreach (var o in moved) { Broker.ChangePrice(map[o.Id], Round(o.Price)); sPrice[o.Id] = o.Price; Note(now, "ORDER MOVED → " + Px(o.Price)); }
                // position
                if (qtyCh)
                {
                    int want = Math.Sign(t.Position) * Math.Min(Math.Abs(t.Position), MaxContracts); pendingQty = want; sQty = want; sStop = t.StopPts; sTgt = t.TargetPts;
                    if (want != t.Position) { t.Adopt(want, t.AvgPrice, now); Warning = "CAPPED AT MAX QTY " + MaxContracts; }
                    State = "ARMED • SENDING"; return;   // sent on the next tick (after the bracket is out of the way when needed)
                }
                // stop / target of the open position
                if (real != 0 && (stopCh || tgtCh)) SetBracket(t.StopPts, t.TargetPts, real, avg, rStop, rTgt, now);
                sStop = t.StopPts; sTgt = t.TargetPts; State = "ARMED • SENT"; return;
            }
            // 5. the bracket the studio asked for, once its entry filled
            if (Armed && bracketWanted && real != 0 && rStop == null && rTgt == null && (t.StopPts != 0 || t.TargetPts > 0)) { bracketWanted = false; SetBracket(t.StopPts, t.TargetPts, real, avg, null, null, now); return; }
            if (real != 0 && (rStop != null || rTgt != null)) bracketWanted = false;
            // 6. no stop on a real position (e.g. opened in NinjaTrader)
            if (real != 0 && rStop == null)
            {
                if (Armed && AutoStop && !bracketWanted && DefaultStopPts > 0 && now >= bracketWait) { int dir = Math.Sign(real); var s = Send("STOP", -dir * Math.Abs(real), Round(avg - dir * DefaultStopPts), "", now, "AUTO STOP " + Px(Round(avg - dir * DefaultStopPts))); if (s != null) protective.Add(s.Id); return; }
                Warning = "NO STOP ON THE REAL POSITION";
            }
            Pull(t, real, avg, rStop, rTgt, rEntries, now);
            State = (Armed ? "ARMED" : "WATCHING") + (real == 0 ? " • FLAT" : " • " + (real > 0 ? "LONG " : "SHORT ") + Math.Abs(real) + " @ " + Px(avg)) + (rEntries.Count > 0 ? " • " + rEntries.Count + " working" : "");
        }

        // places / moves / removes the real stop and target for the studio's distances (from the REAL average price)
        void SetBracket(double stopPts, double tgtPts, int real, double avg, KeystoneBrokerOrder rStop, KeystoneBrokerOrder rTgt, DateTime now)
        {
            int dir = Math.Sign(real), q = Math.Abs(real);
            bool holdTarget = MinHoldSeconds > 0 && (now - realSince).TotalSeconds < MinHoldSeconds;
            double sp = stopPts != 0 ? Round(avg - dir * stopPts) : double.NaN, tp = tgtPts > 0 && !holdTarget ? Round(avg + dir * tgtPts) : double.NaN;
            // a leg added or removed: rebuild the pair (cancelling one leg of a one-cancels-other pair cancels both)
            bool structure = (rStop == null) != double.IsNaN(sp) || (rTgt == null) != double.IsNaN(tp);
            if (structure && (rStop != null || rTgt != null))
            {
                if (rStop != null) Broker.Cancel(rStop); if (rTgt != null && !rTgt.CancelSent) Broker.Cancel(rTgt);
                Note(now, "BRACKET CHANGED • rebuilding"); bracketWanted = !double.IsNaN(sp) || !double.IsNaN(tp); bracketWait = now.AddSeconds(4); return;
            }
            if (structure)
            {
                string oco = !double.IsNaN(sp) && !double.IsNaN(tp) ? "KA" + now.ToString("HHmmss", CultureInfo.InvariantCulture) + "-" + (++ocoSeq) : "";
                if (!double.IsNaN(sp)) { var s = Send("STOP", -dir * q, sp, oco, now, "STOP " + Px(sp)); if (s != null) protective.Add(s.Id); }
                if (!double.IsNaN(tp)) { var g = Send("LIMIT", -dir * q, tp, oco, now, "TARGET " + Px(tp)); if (g != null) protective.Add(g.Id); }
                bracketWait = now.AddSeconds(4); return;
            }
            if (rStop != null && Math.Abs(rStop.Price - sp) > Tk / 2) { Broker.ChangePrice(rStop, sp); Note(now, "STOP MOVED → " + Px(sp)); }
            if (rTgt != null && Math.Abs(rTgt.Price - tp) > Tk / 2) { Broker.ChangePrice(rTgt, tp); Note(now, "TARGET MOVED → " + Px(tp)); }
        }

        // the studio takes the real account's state (position, stop / target distances, working orders)
        void Pull(KeystoneReplayTrader t, int real, double avg, KeystoneBrokerOrder rStop, KeystoneBrokerOrder rTgt, List<KeystoneBrokerOrder> rEntries, DateTime now)
        {
            int dir = Math.Sign(real);
            double sp = real != 0 && rStop != null ? Math.Round(dir * (avg - rStop.Price) / Tk) * Tk : 0, tp = real != 0 && rTgt != null ? Math.Round(dir * (rTgt.Price - avg) / Tk) * Tk : 0;
            if (t.Position != real || (real != 0 && Math.Abs(t.AvgPrice - avg) > Tk / 4)) { t.Adopt(real, avg, now); Pulled = true; }
            // flat: the studio's SL / TP stay as the distances for the next entry; a studio entry waiting for its bracket keeps them too
            bool keepIntent = real == 0 || (bracketWanted && rStop == null && rTgt == null);
            if (!keepIntent && (Math.Abs(t.StopPts - sp) > Tk / 4 || Math.Abs(t.TargetPts - tp) > Tk / 4)) { t.StopPts = sp; t.TargetPts = tp; Pulled = true; }
            // working entry orders: the studio shows exactly the real ones
            var byReal = map.ToDictionary(kv => kv.Value, kv => kv.Key);
            foreach (var b in rEntries)
            {
                int id; KeystoneReplayOrder so;
                if (byReal.TryGetValue(b, out id) && (so = t.Orders.FirstOrDefault(o => o.Id == id)) != null) { if (Math.Abs(so.Price - b.Price) > Tk / 4 || so.Qty != b.Qty - b.Filled) { so.Price = b.Price; so.Qty = Math.Max(1, b.Qty - b.Filled); Pulled = true; } sPrice[id] = so.Price; continue; }
                so = t.Place(b.Kind == "STOP" ? "STOP" : "LIMIT", b.Side, Math.Max(1, b.Qty - b.Filled), b.Price); map[so.Id] = b; sPrice[so.Id] = so.Price; Pulled = true;
            }
            var live = new HashSet<KeystoneBrokerOrder>(rEntries);
            foreach (var kv in map.Where(kv => !live.Contains(kv.Value)).ToList()) { t.Orders.RemoveAll(o => o.Id == kv.Key); map.Remove(kv.Key); sPrice.Remove(kv.Key); Pulled = true; }
            sQty = real; sStop = t.StopPts; sTgt = t.TargetPts;
        }
    }

    // ---- COPIER: the chart's account (the leader) copied to follower accounts ------------------------------------------------
    // Each follower has its own account link (its own limits, arm, lock) and a mirror trader whose "intent" is the leader's REAL
    // position × the follower's multiplier (capped at its max) with the leader's stop / target distances. Followers enter at
    // market when the leader's position appears, follow its stop / target moves, and close when the leader is flat. If a
    // follower's own stop / target closes it while the leader is still in, it sits that trade out (never re-enters it).
    public sealed class KeystoneCopyFollower
    {
        public string Account = ""; public double Multiplier = 1; public int MaxQty = 2; public bool Paused;
        public KeystoneAccountLink Link; public KeystoneReplayTrader Mirror; public string Status = "";
        public string DoneTrade = "", Copying = ""; public int LastReal;
    }
    public static class KeystoneCopier
    {
        public static string TradeId(KeystoneReplayTrader leader) { return leader == null || leader.Position == 0 ? "" : leader.PositionTime.Ticks + "|" + Math.Sign(leader.Position); }
        public static int Desired(int leaderQty, double mult, int max)
        {
            if (leaderQty == 0 || mult <= 0) return 0; int q = (int)Math.Round(Math.Abs(leaderQty) * mult, MidpointRounding.AwayFromZero);
            return Math.Sign(leaderQty) * Math.Max(1, Math.Min(Math.Max(1, max), q));
        }
        // sets the follower's intent from the leader, then lets its link do the rest (only places orders while the link is armed)
        public static void Tick(KeystoneReplayTrader leader, KeystoneCopyFollower f, DateTime now)
        {
            if (leader == null || f == null || f.Link == null || f.Mirror == null) return;
            var m = f.Mirror; m.Price = leader.Price; m.Time = leader.Time;
            string id = TradeId(leader); int real = 0; try { real = f.Link.Broker.Qty; } catch { }
            if (id == "") f.DoneTrade = "";
            if (f.Copying != "" && f.Copying == id && real == 0 && f.LastReal != 0 && leader.Position != 0) f.DoneTrade = id;   // its own stop / target closed it: sit out
            f.LastReal = real;
            if (!f.Paused && !f.Link.Locked)
            {
                int want = id == "" || f.DoneTrade == id ? 0 : Desired(leader.Position, f.Multiplier, f.MaxQty);
                if (want != 0) f.Copying = id;
                if (m.Position != want) m.Adopt(want, leader.AvgPrice, now);
                if (want != 0) { m.StopPts = leader.StopPts; m.TargetPts = leader.TargetPts; }
            }
            f.Link.Tick(m, now);
            int target = !f.Paused && id != "" && f.DoneTrade != id ? Desired(leader.Position, f.Multiplier, f.MaxQty) : 0;
            f.Status = f.Link.Locked ? "LOCKED" : f.Paused ? "PAUSED" : !f.Link.Connected ? "NOT CONNECTED" : !f.Link.Armed ? "NOT ARMED (watching)" : f.DoneTrade != "" && f.DoneTrade == id ? "SAT OUT (its stop / target hit)" : f.Link.Broker.Qty == target ? (target == 0 ? "IN SYNC • flat" : "IN SYNC • " + (target > 0 ? "LONG " : "SHORT ") + Math.Abs(target)) : "SYNCING → " + target;
        }
        // saved: one line per leader account: leader|follower:mult:max:paused;...
        public static string Serialize(string leader, IEnumerable<KeystoneCopyFollower> fs) { return (leader ?? "").Replace("|", "/") + "|" + string.Join(";", fs.Select(f => f.Account.Replace(";", "/").Replace(":", "/") + ":" + f.Multiplier.ToString(CultureInfo.InvariantCulture) + ":" + f.MaxQty + ":" + (f.Paused ? "1" : "0"))); }
        public static Tuple<string, List<KeystoneCopyFollower>> Parse(string line)
        {
            var a = (line ?? "").Split('|'); if (a.Length < 2) return null; var list = new List<KeystoneCopyFollower>();
            foreach (var p in a[1].Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries))
            {
                var b = p.Split(':'); if (b.Length < 4) continue; double mu; int mx; double.TryParse(b[1], NumberStyles.Float, CultureInfo.InvariantCulture, out mu); int.TryParse(b[2], out mx);
                list.Add(new KeystoneCopyFollower { Account = b[0], Multiplier = mu > 0 ? mu : 1, MaxQty = mx > 0 ? mx : 1, Paused = b[3] == "1" });
            }
            return Tuple.Create(a[0], list);
        }
    }

    // ---- THE POOL: your own record of every account you trade — kept for good (also after you stop trading it) ---------------
    public sealed class KeystonePoolAccount
    {
        public string Account = "", Nick = "", Firm = "", Status = "EVAL", Notes = ""; public DateTime Started = DateTime.MinValue; public double Cost;
        public List<Tuple<DateTime, double>> Payouts = new List<Tuple<DateTime, double>>();
        public double PaidOut { get { return Payouts.Sum(p => p.Item2); } }
        public bool Archived { get { return Status == "BLOWN" || Status == "CLOSED"; } }
    }
    public sealed class KeystonePoolStats { public int Days, Trades, Wins; public double Pnl, BestDayPct, LastBalance, Fees; }
    public static class KeystonePool
    {
        public static readonly string[] Statuses = { "EVAL", "PASSED", "FUNDED", "PAYOUT", "BLOWN", "CLOSED" };
        public static string Serialize(IEnumerable<KeystonePoolAccount> list)
        {
            var sb = new StringBuilder(); Func<string, string> c = x => (x ?? "").Replace("|", "/").Replace("\n", " ");
            foreach (var a in list)
            {
                sb.AppendLine(string.Join("|", "ACC", c(a.Account), c(a.Nick), c(a.Firm), c(a.Status), a.Started == DateTime.MinValue ? "" : a.Started.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture), a.Cost.ToString(CultureInfo.InvariantCulture), c(a.Notes)));
                foreach (var p in a.Payouts) sb.AppendLine(string.Join("|", "PAY", c(a.Account), p.Item1.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture), p.Item2.ToString(CultureInfo.InvariantCulture)));
            }
            return sb.ToString();
        }
        public static List<KeystonePoolAccount> Parse(string text)
        {
            var list = new List<KeystonePoolAccount>(); var by = new Dictionary<string, KeystonePoolAccount>(StringComparer.OrdinalIgnoreCase);
            foreach (var line in (text ?? "").Split(new[] { '\n', '\r' }, StringSplitOptions.RemoveEmptyEntries))
            {
                var a = line.Split('|'); double v; DateTime d;
                if (a[0] == "ACC" && a.Length >= 8)
                {
                    var x = new KeystonePoolAccount { Account = a[1], Nick = a[2], Firm = a[3], Status = a[4], Notes = a[7] };
                    if (DateTime.TryParseExact(a[5], "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out d)) x.Started = d;
                    if (double.TryParse(a[6], NumberStyles.Float, CultureInfo.InvariantCulture, out v)) x.Cost = v;
                    list.Add(x); by[x.Account] = x;
                }
                else if (a[0] == "PAY" && a.Length >= 4 && by.ContainsKey(a[1]) && DateTime.TryParseExact(a[2], "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out d) && double.TryParse(a[3], NumberStyles.Float, CultureInfo.InvariantCulture, out v))
                    by[a[1]].Payouts.Add(Tuple.Create(d, v));
            }
            return list;
        }
        // the account's numbers from its daily closes and its journal rows (account,symbol,side,qty,entry_time,entry,exit_time,exit,points,net,…)
        public static KeystonePoolStats Stats(KeystoneAccountWatch w, IEnumerable<string[]> journal)
        {
            var st = new KeystonePoolStats();
            if (w != null && w.Closes.Count > 0) { var dp = w.DayProfits(); st.Days = dp.Count(x => Math.Abs(x) > 0.005); st.LastBalance = w.Closes.Values.Last(); st.Pnl = st.LastBalance - w.StartBalance; st.BestDayPct = w.ConsistencyPct(); }
            foreach (var r in journal ?? new List<string[]>())
            {
                double net; if (r.Length < 10 || !double.TryParse(r[9], NumberStyles.Float, CultureInfo.InvariantCulture, out net)) continue;
                st.Trades++; if (net > 0) st.Wins++;
            }
            return st;
        }
    }

    // ---- LIVE TRADING tools: level fade (NEAR mode), missing-minute finder + merge (refill after a disconnect), day locks ----
    public static class KeystoneLiveTools
    {
        // a level line's opacity: OFF 0, ALWAYS 1, NEAR = fades in as price comes within `near` points (1 at the level)
        public const int Off = 0, Near = 1, Always = 2;
        public static double LevelOpacity(int mode, double price, double level, double near)
        {
            if (mode <= Off || double.IsNaN(level) || double.IsNaN(price)) return 0; if (mode >= Always) return 1;
            double d = Math.Abs(price - level); return near <= 0 || d >= near ? 0 : 1 - d / near;
        }
        // CME futures (NY time): open Sunday 18:00 → Friday 17:00, with the daily break 17:00 → 18:00
        public static bool MarketOpen(DateTime ny)
        {
            var d = ny.DayOfWeek; int m = ny.Hour * 60 + ny.Minute;
            if (d == DayOfWeek.Saturday) return false; if (d == DayOfWeek.Sunday) return m >= 18 * 60; if (d == DayOfWeek.Friday) return m < 17 * 60;
            return m < 17 * 60 || m >= 18 * 60;
        }
        // runs of at least `minMissing` minutes with the market open and no bar, between `from` and `to` (bar Time = its close)
        public static List<Tuple<DateTime, DateTime>> Gaps(IList<KeystoneArcBar> bars, DateTime from, DateTime to, int minMissing)
        {
            var output = new List<Tuple<DateTime, DateTime>>(); if (bars == null) return output;
            var have = new HashSet<DateTime>(bars.Where(b => b != null).Select(b => b.Time));
            DateTime start = new DateTime(from.Year, from.Month, from.Day, from.Hour, from.Minute, 0).AddMinutes(1), runStart = DateTime.MinValue; int run = 0;
            for (var t = start; t <= to; t = t.AddMinutes(1))
            {
                bool missing = MarketOpen(t.AddMinutes(-1)) && !have.Contains(t);
                if (missing) { if (run == 0) runStart = t; run++; }
                else { if (run >= minMissing) output.Add(Tuple.Create(runStart, t.AddMinutes(-1))); run = 0; }
            }
            if (run >= minMissing) output.Add(Tuple.Create(runStart, to));
            return output;
        }
        // adds the bars whose minute is missing (keeps time order); returns how many were added
        public static int MergeBars(List<KeystoneArcBar> target, IEnumerable<KeystoneArcBar> add)
        {
            if (target == null || add == null) return 0; var have = new HashSet<DateTime>(target.Select(b => b.Time)); int n = 0;
            foreach (var b in add.Where(x => x != null).OrderBy(x => x.Time))
            {
                if (!have.Add(b.Time)) continue; n++;
                int i = target.Count; while (i > 0 && target[i - 1].Time > b.Time) i--; target.Insert(i, b);
            }
            return n;
        }
    }

    // LOCK FOR TODAY: an account refuses trading until the next session opens (18:00 NY; Friday → Sunday 18:00). Kept on disk.
    public sealed class KeystoneDayLocks
    {
        public readonly Dictionary<string, DateTime> Until = new Dictionary<string, DateTime>(StringComparer.OrdinalIgnoreCase);
        public static DateTime NextOpen(DateTime ny)
        {
            var t = ny.Date.AddHours(18); if (ny >= t) t = t.AddDays(1);
            while (t.DayOfWeek == DayOfWeek.Friday || t.DayOfWeek == DayOfWeek.Saturday) t = t.AddDays(1);   // Friday 18:00 is closed → Sunday
            return t;
        }
        public DateTime Lock(string account, DateTime ny) { var u = NextOpen(ny); Until[account ?? ""] = u; return u; }
        public void Unlock(string account) { Until.Remove(account ?? ""); }
        public bool IsLocked(string account, DateTime ny) { DateTime u; return account != null && Until.TryGetValue(account, out u) && ny < u; }
        public string Serialize() { return string.Join("\n", Until.Select(kv => kv.Key.Replace("|", "/") + "|" + kv.Value.ToString("yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture))); }
        public static KeystoneDayLocks Parse(string text)
        {
            var l = new KeystoneDayLocks();
            foreach (var line in (text ?? "").Split(new[] { '\n', '\r' }, StringSplitOptions.RemoveEmptyEntries)) { var a = line.Split('|'); DateTime u; if (a.Length == 2 && DateTime.TryParseExact(a[1], "yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture, DateTimeStyles.None, out u)) l.Until[a[0]] = u; }
            return l;
        }
    }

