        public static KeystoneFirmPreset Find(string name) { return Presets.FirstOrDefault(p => string.Equals(p.Name, name, StringComparison.OrdinalIgnoreCase)); }

        // a sensible preset from the account's name (MFFU…, TAKEPROFIT…, LT… / LUCID…, Sim…)
        public static KeystoneFirmPreset Guess(string account)
        {
            string a = (account ?? "").ToUpperInvariant();
            if (a.StartsWith("MFFU") && a.Contains("EOD")) return Find("MFFU RAPID EOD 50K");
            if (a.StartsWith("MFFU")) return Find("MFFU RAPID EOD 50K");
            if (a.StartsWith("TAKEPROFIT") || a.StartsWith("TPT")) return Find("TAKE PROFIT TRADER 50K");
            if (a.StartsWith("LUCID") || a.StartsWith("LT")) return Find("LUCID FLEX 50K");
            if (a.StartsWith("SIM") || a.StartsWith("DEMO") || a.StartsWith("PLAYBACK")) return Find("PRACTICE (SIM)");
            return null;
        }
    }

    // ---- ACCOUNT WATCH: what the firm measures, kept day by day from the balances NinjaTrader reports ----------------------
    // Each session's closing balance is kept, so the end-of-day trailing floor (highest close − drawdown), the profit per day
    // and the consistency share (best day ÷ total profit) can be shown while trading. An estimate: the firm's dashboard rules.
    public sealed class KeystoneAccountWatch
    {
        public string Account = ""; public double StartBalance; public SortedDictionary<DateTime, double> Closes = new SortedDictionary<DateTime, double>();

        public void Observe(DateTime session, double balance)
        {
            if (balance <= 0) return; if (StartBalance <= 0) StartBalance = balance;
            Closes[session.Date] = balance;   // the last balance seen in a session = its close
        }
        // highest end-of-day balance BEFORE today (the EOD floor only moves at the close)
        public double PeakEod(DateTime today) { double p = StartBalance; foreach (var kv in Closes) if (kv.Key < today.Date) p = Math.Max(p, kv.Value); return p; }
        public double Floor(DateTime today, double dd, bool stopsAtStart) { double f = PeakEod(today) - dd; if (stopsAtStart && StartBalance > 0 && f > StartBalance) f = StartBalance; return f; }
        public List<double> DayProfits()
        {
            var list = new List<double>(); double prev = StartBalance;
            foreach (var kv in Closes) { list.Add(kv.Value - prev); prev = kv.Value; }
            return list;
        }
        // best day ÷ total profit (0 when there is no profit yet)
        public double ConsistencyPct() { var d = DayProfits(); double total = d.Sum(); return total <= 0 ? 0 : 100.0 * d.Max() / total; }

        public string Serialize() { return Account.Replace("|", "/") + "|" + StartBalance.ToString(CultureInfo.InvariantCulture) + "|" + string.Join(";", Closes.Select(kv => kv.Key.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture) + "=" + kv.Value.ToString(CultureInfo.InvariantCulture))); }
        public static KeystoneAccountWatch Parse(string line)
        {
            var a = (line ?? "").Split('|'); if (a.Length < 3) return null; var w = new KeystoneAccountWatch { Account = a[0] };
            double.TryParse(a[1], NumberStyles.Float, CultureInfo.InvariantCulture, out w.StartBalance);
            foreach (var p in a[2].Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries))
            {
                var kv = p.Split('='); DateTime d; double v;
                if (kv.Length == 2 && DateTime.TryParseExact(kv[0], "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out d) && double.TryParse(kv[1], NumberStyles.Float, CultureInfo.InvariantCulture, out v)) w.Closes[d] = v;
            }
            return w;
        }
    }

    // ---- IDEAS: one typed line → every combination on the loaded 1-minute bars ---------------------------------------
    // Examples: MNQ AT 0930 BUY,SELL TP 25,50,100,150,200 SL 25,50,100,NONE EXIT 1555
    //           MNQ MGC AT 0930 ORB 15,30 BUY,SELL TP 50,100 SL 50 MGCTP 5,10 MGCSL 5 QTY 1,2
    //           BOTH FVG 1 EITHER,BUY,SELL SESSION NY,LONDON GAP 2,5 TP 10,20,40 SL C1,10,20 ACCOUNTS 1,3,5
    // Words: MNQ / MGC / BOTH (instruments) • AT hhmm[,hhmm] (entry time, New York) • BUY / SELL / EITHER • ENTRY: (nothing) = at the
    // time, ORB n = the first break of the n-minute range after the time (up = BUY, down = SELL), FADE n = against that break,
    // FVG n = every n-minute fair value gap • FILL CLOSE,50 (FVG: in when candle 3 closes, or a limit at the gap's middle for 60 min) •
    // GAP / MGCGAP minimum gap points • SESSION ASIA,LONDON,NY,ALL or FROM hhmm TO hhmm (FVG) • ACCOUNTS n (FVG: each new setup goes to
    // the next free account; nothing against the open direction until every open trade is done) • TP / SL points for MNQ (SL NONE = no
    // stop, SL C1 = beyond the FVG's first candle) • MGCTP / MGCSL for gold (default: MNQ ÷ 10) • EXIT hhmm (default 1555; FVG: the
    // session end) • QTY contracts.
    // ---- STUDIO DATA STORE: the Backtest Studio's own 1-minute bars on disk, independent of the lab's Step 1 ---------------
    // One file per instrument and session month (Studio\MNQ\2026-09.bars). A session (18:00 → 17:00 New York) lives in ONE file,
    // and a merge replaces whole sessions only (never single minutes), so two futures contracts are never mixed inside a day.
    // A new copy of a session replaces the stored one only when it has at least as many minutes (a thin contract never
    // overwrites a good day). The header lists each session and its minute count, so the session list loads without bars.
    public static class KeystoneStudioStore
    {
        const string Version = "studio1";
        public static DateTime SessionOf(DateTime barTime) { return KeystoneIdeas.SessionDay(barTime.AddMinutes(-1)); }
        static string SymbolFolder(string folder, string symbol) { return Path.Combine(folder, (symbol ?? "MNQ").ToUpperInvariant()); }
        static string MonthFile(string folder, string symbol, DateTime month) { return Path.Combine(SymbolFolder(folder, symbol), month.ToString("yyyy-MM", CultureInfo.InvariantCulture) + ".bars"); }
        static readonly object gate = new object();

        static bool Read(string file, string symbol, Dictionary<DateTime, int> counts, List<KeystoneArcBar> bars)
        {
            if (!File.Exists(file)) return false;
            using (var reader = new BinaryReader(File.OpenRead(file)))
            {
                var key = reader.ReadString().Split('|'); if (key.Length < 2 || key[0] != Version) return false;
                int days = reader.ReadInt32();
                for (int i = 0; i < days; i++) { var d = new DateTime(reader.ReadInt64()); int c = reader.ReadInt32(); if (counts != null) counts[d] = c; }
                if (bars == null) return true;
                int n = reader.ReadInt32(); bars.Capacity = bars.Count + n;
                for (int i = 0; i < n; i++) bars.Add(new KeystoneArcBar { Time = new DateTime(reader.ReadInt64()), Symbol = symbol, Open = reader.ReadDouble(), High = reader.ReadDouble(), Low = reader.ReadDouble(), Close = reader.ReadDouble(), Volume = reader.ReadInt64() });
            }
            return true;
        }

        static void Write(string file, string symbol, DateTime month, List<KeystoneArcBar> bars)
        {
            Directory.CreateDirectory(Path.GetDirectoryName(file)); string temp = file + ".tmp";
            var counts = bars.GroupBy(b => SessionOf(b.Time)).OrderBy(g => g.Key).Select(g => Tuple.Create(g.Key, g.Count())).ToList();
            using (var writer = new BinaryWriter(File.Create(temp)))
            {
                writer.Write(Version + "|" + symbol + "|" + month.ToString("yyyy-MM", CultureInfo.InvariantCulture));
                writer.Write(counts.Count); foreach (var c in counts) { writer.Write(c.Item1.Ticks); writer.Write(c.Item2); }
                writer.Write(bars.Count); foreach (var b in bars) { writer.Write(b.Time.Ticks); writer.Write(b.Open); writer.Write(b.High); writer.Write(b.Low); writer.Write(b.Close); writer.Write(b.Volume); }
            }
            if (File.Exists(file)) File.Delete(file);
            File.Move(temp, file);
        }

        // Merges bars into the store. Returns the number of sessions added or replaced.
        public static int Merge(string folder, string symbol, IEnumerable<KeystoneArcBar> incoming)
        {
            if (incoming == null) return 0; symbol = (symbol ?? "MNQ").ToUpperInvariant(); int changed = 0;
            var valid = incoming.Where(b => b != null && b.High >= b.Low && b.Open > 0 && b.Close > 0).GroupBy(b => b.Time).Select(g => g.Last()).ToList();
            lock (gate)
            {
                foreach (var monthGroup in valid.GroupBy(b => { var s = SessionOf(b.Time); return new DateTime(s.Year, s.Month, 1); }))
                {
                    string file = MonthFile(folder, symbol, monthGroup.Key); var stored = new List<KeystoneArcBar>(); var storedCounts = new Dictionary<DateTime, int>();
                    try { if (!Read(file, symbol, storedCounts, stored)) { stored.Clear(); storedCounts.Clear(); } } catch { stored.Clear(); storedCounts.Clear(); }
                    var bySession = stored.GroupBy(b => SessionOf(b.Time)).ToDictionary(g => g.Key, g => g.ToList()); bool any = false;
                    foreach (var day in monthGroup.GroupBy(b => SessionOf(b.Time)))
                    {
                        List<KeystoneArcBar> old; int newCount = day.Count();
                        if (bySession.TryGetValue(day.Key, out old) && old.Count > newCount) continue;
                        if (old != null && old.Count == newCount && old.Zip(day.OrderBy(b => b.Time), (a, b) => a.Time == b.Time && a.Close == b.Close && a.High == b.High && a.Low == b.Low).All(x => x)) continue;
                        bySession[day.Key] = day.Select(b => new KeystoneArcBar { Time = b.Time, Symbol = symbol, Open = b.Open, High = b.High, Low = b.Low, Close = b.Close, Volume = b.Volume }).OrderBy(b => b.Time).ToList(); any = true; changed++;
                    }
                    if (any) Write(file, symbol, monthGroup.Key, bySession.OrderBy(k => k.Key).SelectMany(k => k.Value).ToList());
                }
            }
            return changed;
        }

        // Minutes stored per session (from the file headers only).
        public static SortedDictionary<DateTime, int> Sessions(string folder, string symbol)
        {
            var all = new SortedDictionary<DateTime, int>(); string dir = SymbolFolder(folder, symbol); if (!Directory.Exists(dir)) return all;
            lock (gate)
                foreach (var f in Directory.GetFiles(dir, "*.bars"))
                {
                    var counts = new Dictionary<DateTime, int>();
                    try { if (Read(f, symbol, counts, null)) foreach (var kv in counts) all[kv.Key] = kv.Value; } catch { }
                }
            return all;
        }

        // The bars of the sessions from → to (both included).
        public static List<KeystoneArcBar> Load(string folder, string symbol, DateTime fromSession, DateTime toSession)
        {
            symbol = (symbol ?? "MNQ").ToUpperInvariant(); var bars = new List<KeystoneArcBar>();
            lock (gate)
                for (var m = new DateTime(fromSession.Year, fromSession.Month, 1); m <= toSession; m = m.AddMonths(1))
                {
                    var part = new List<KeystoneArcBar>();
                    try { if (Read(MonthFile(folder, symbol, m), symbol, null, part)) bars.AddRange(part.Where(b => { var s = SessionOf(b.Time); return s >= fromSession.Date && s <= toSession.Date; })); } catch { }
                }
            return bars.OrderBy(b => b.Time).ToList();
        }

        // New York day (09:30 → 16:00) of each session of one month: range (high − low) and change (close − open) in points.
        public static Dictionary<DateTime, Tuple<int, double, double>> DayStats(string folder, string symbol, DateTime month)
        {
            var result = new Dictionary<DateTime, Tuple<int, double, double>>(); var m = new DateTime(month.Year, month.Month, 1);
            foreach (var g in Load(folder, symbol, m, m.AddMonths(1).AddDays(-1)).GroupBy(b => SessionOf(b.Time)))
            {
                var rth = g.Where(b => b.Time.TimeOfDay > new TimeSpan(9, 30, 0) && b.Time.TimeOfDay <= new TimeSpan(16, 0, 0)).ToList();
                result[g.Key] = rth.Count == 0 ? Tuple.Create(g.Count(), 0.0, 0.0) : Tuple.Create(g.Count(), rth.Max(b => b.High) - rth.Min(b => b.Low), rth[rth.Count - 1].Close - rth[0].Open);
            }
            return result;
        }

        public static long SizeBytes(string folder, string symbol)
        {
            string dir = SymbolFolder(folder, symbol); if (!Directory.Exists(dir)) return 0;
            return Directory.GetFiles(dir, "*.bars").Sum(f => new FileInfo(f).Length);
        }

        // Weekdays (Mon–Fri) between from and to with no stored session or fewer than minBars minutes. Holidays show up too.
        public static List<DateTime> Missing(SortedDictionary<DateTime, int> sessions, DateTime from, DateTime to, int minBars)
        {
            var list = new List<DateTime>();
            for (var d = from.Date; d <= to.Date; d = d.AddDays(1))
            {
                if (d.DayOfWeek == DayOfWeek.Saturday || d.DayOfWeek == DayOfWeek.Sunday) continue;
                int c; if (!sessions.TryGetValue(d, out c) || c < minBars) list.Add(d);
            }
            return list;
        }

        // Download chunks: Sunday → Saturday weeks (a week holds Sunday 18:00 → Friday 17:00) clipped to from → to.
        public static List<Tuple<DateTime, DateTime>> Weeks(DateTime from, DateTime to)
        {
            var list = new List<Tuple<DateTime, DateTime>>(); if (to < from) return list;
            var start = from.Date.AddDays(-(int)from.Date.DayOfWeek);
            for (var w = start; w <= to.Date; w = w.AddDays(7))
            {
                var a = w < from.Date.AddDays(-1) ? from.Date.AddDays(-1) : w; var b = w.AddDays(7).AddMinutes(-1); if (b > to.Date.AddDays(1).AddMinutes(-1)) b = to.Date.AddDays(1).AddMinutes(-1);
                if (b > a) list.Add(Tuple.Create(a, b));
            }
            return list;
        }

        // Weeks already asked for (so a holiday week is not asked again and again). Only finished weeks are remembered.
        public static HashSet<DateTime> Requested(string folder, string symbol)
        {
            var set = new HashSet<DateTime>(); string file = Path.Combine(SymbolFolder(folder, symbol), "requested.txt");
            try { if (File.Exists(file)) foreach (var l in File.ReadAllLines(file)) { DateTime d; if (DateTime.TryParseExact(l.Trim(), "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out d)) set.Add(d); } } catch { }
            return set;
        }
        public static void MarkRequested(string folder, string symbol, DateTime weekStart)
        {
            try { Directory.CreateDirectory(SymbolFolder(folder, symbol)); lock (gate) File.AppendAllText(Path.Combine(SymbolFolder(folder, symbol), "requested.txt"), weekStart.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture) + Environment.NewLine); } catch { }
        }
        public static DateTime WeekKey(DateTime chunkStart) { var d = chunkStart.Date; return d.AddDays(-(int)d.DayOfWeek); }

        // Several sources for the same sessions (old lab caches of different contracts): per session keep the one with the most minutes.
        public static List<KeystoneArcBar> BestPerSession(IEnumerable<List<KeystoneArcBar>> sources)
        {
            var best = new Dictionary<DateTime, List<KeystoneArcBar>>();
            foreach (var src in sources)
            {
                if (src == null) continue;
                foreach (var g in src.GroupBy(b => SessionOf(b.Time))) { List<KeystoneArcBar> have; var l = g.ToList(); if (!best.TryGetValue(g.Key, out have) || l.Count > have.Count) best[g.Key] = l; }
            }
            return best.OrderBy(k => k.Key).SelectMany(k => k.Value).ToList();
        }
    }

    // ---- HIGH-IMPACT NEWS: built-in FOMC dates + rule-based NFP, your News.csv, and the ForexFactory week feed -------------
    // All times are New York. A day's news = the events of its session (18:00 the evening before → 17:00).
    public sealed class KeystoneNewsEvent { public DateTime Time; public string Title = string.Empty, Currency = "USD", Impact = "HIGH", Source = string.Empty; }
    // ---- AI COACH engine: a tiny JSON reader / writer and the Claude Messages API request / answer (raw HTTPS; NinjaScript cannot reference the SDK)
    public static class KeystoneJson
    {
        public static string Str(string v)
        {
            var sb = new StringBuilder("\""); foreach (char c in v ?? "")
            {
                if (c == '"') sb.Append("\\\""); else if (c == '\\') sb.Append("\\\\"); else if (c == '\n') sb.Append("\\n"); else if (c == '\r') sb.Append("\\r"); else if (c == '\t') sb.Append("\\t");
                else if (c < 32) sb.Append("\\u").Append(((int)c).ToString("x4")); else sb.Append(c);
            }
            return sb.Append('"').ToString();
        }
        // objects → Dictionary<string, object>, arrays → List<object>, numbers → double, true / false → bool, null → null
        public static object Parse(string json) { int i = 0; var v = Value(json ?? "", ref i); return v; }
        static void Ws(string s, ref int i) { while (i < s.Length && char.IsWhiteSpace(s[i])) i++; }
        static object Value(string s, ref int i)
        {
            Ws(s, ref i); if (i >= s.Length) throw new FormatException("end of JSON");
            char c = s[i];
            if (c == '{') { i++; var d = new Dictionary<string, object>(); Ws(s, ref i); if (s[i] == '}') { i++; return d; } while (true) { Ws(s, ref i); string k = (string)Value(s, ref i); Ws(s, ref i); if (s[i] != ':') throw new FormatException("':' expected"); i++; d[k] = Value(s, ref i); Ws(s, ref i); if (s[i] == ',') { i++; continue; } if (s[i] == '}') { i++; return d; } throw new FormatException("',' or '}' expected"); } }
            if (c == '[') { i++; var l = new List<object>(); Ws(s, ref i); if (s[i] == ']') { i++; return l; } while (true) { l.Add(Value(s, ref i)); Ws(s, ref i); if (s[i] == ',') { i++; continue; } if (s[i] == ']') { i++; return l; } throw new FormatException("',' or ']' expected"); } }
            if (c == '"')
            {
                i++; var sb = new StringBuilder();
                while (i < s.Length && s[i] != '"')
                {
                    if (s[i] == '\\' && i + 1 < s.Length)
                    {
                        char e = s[++i];
                        if (e == 'n') sb.Append('\n'); else if (e == 't') sb.Append('\t'); else if (e == 'r') sb.Append('\r'); else if (e == 'b') sb.Append('\b'); else if (e == 'f') sb.Append('\f');
                        else if (e == 'u' && i + 4 < s.Length) { sb.Append((char)Convert.ToInt32(s.Substring(i + 1, 4), 16)); i += 4; }
                        else sb.Append(e);
                        i++;
                    }
                    else sb.Append(s[i++]);
                }
                i++; return sb.ToString();
            }
            if (s.Substring(i).StartsWith("true")) { i += 4; return true; }
            if (s.Substring(i).StartsWith("false")) { i += 5; return false; }
            if (s.Substring(i).StartsWith("null")) { i += 4; return null; }
            int st = i; while (i < s.Length && "+-0123456789.eE".IndexOf(s[i]) >= 0) i++;
            return double.Parse(s.Substring(st, i - st), NumberStyles.Float, CultureInfo.InvariantCulture);
        }
    }
    public sealed class KeystoneCoachAnswer { public bool Ok; public string Text = string.Empty, Error = string.Empty, StopReason = string.Empty; public int InTokens, OutTokens; }
    public static class KeystoneAiCoach
    {
        public const string Url = "https://api.anthropic.com/v1/messages", Model = "claude-opus-5-5", Beta = "server-side-fallback-2026-07-01";
        public const string System = "You are the trading coach inside KEYSTONE ARC, a futures trading platform for prop-firm accounts (micro contracts: MNQ $2 a point, MGC $10 a point). "
            + "You get the live chart state (recent candles, levels, open gaps, the trader's position, today's P/L and the account's limits) and one question. "
            + "Answer like an experienced, calm desk mentor: plain words, short, specific numbers (price, points, dollars for the contracts held). "
            + "When asked about an entry: say BUY, SELL or WAIT, why in one or two reasons from the data, the entry price, the stop, the target and the risk in dollars; say WAIT when the edge is not clear or a high-impact news release is near. "
            + "Protect the account first: never suggest sizing beyond the stated max contracts, warn when the day's loss or the profit cap (consistency) is close, and never suggest moving a stop further away. "
            + "You only advise; the trader decides and places every order. Never claim certainty. At most 8 short lines, no markdown tables.";
        // the request body: the chart state as the first block, the question after it
        public static string Request(string context, string question, IList<Tuple<string, string>> history)
        {
            var sb = new StringBuilder();
            sb.Append("{\"model\":").Append(KeystoneJson.Str(Model)).Append(",\"max_tokens\":16000,\"fallbacks\":\"default\",\"system\":").Append(KeystoneJson.Str(System)).Append(",\"messages\":[");
            bool first = true;
            if (history != null) foreach (var h in history.Skip(Math.Max(0, history.Count - 6)))
            {
                if (!first) sb.Append(','); first = false;
                sb.Append("{\"role\":\"user\",\"content\":").Append(KeystoneJson.Str(h.Item1)).Append("},{\"role\":\"assistant\",\"content\":").Append(KeystoneJson.Str(h.Item2)).Append('}');
            }
            if (!first) sb.Append(',');
            sb.Append("{\"role\":\"user\",\"content\":").Append(KeystoneJson.Str("CHART STATE (live, New York time)\n" + (context ?? "") + "\n\nQUESTION: " + (question ?? ""))).Append("}]}");
            return sb.ToString();
        }
        // MY CLAUDE PLAN: one plain-text prompt for Claude Code ("claude -p"), the same instructions + history + chart state + question
        public static string CliPrompt(string context, string question, IList<Tuple<string, string>> history)
        {
            var sb = new StringBuilder(System).Append("\nAnswer in plain text only; do not use any tools, files or commands.\n");
            if (history != null) foreach (var h in history.Skip(Math.Max(0, history.Count - 4))) sb.Append("\nEARLIER QUESTION: ").Append(h.Item1).Append("\nYOUR EARLIER ANSWER: ").Append(h.Item2).Append('\n');
            return sb.Append("\nCHART STATE (live, New York time)\n").Append(context ?? "").Append("\n\nQUESTION: ").Append(question ?? "").ToString();
        }
        // the answer: the text blocks; a refusal, an API error or an unreadable reply become a clear message
        public static KeystoneCoachAnswer Answer(string json)
        {
            var a = new KeystoneCoachAnswer();
            try
            {
                var d = KeystoneJson.Parse(json) as Dictionary<string, object>; if (d == null) { a.Error = "unreadable reply"; return a; }
                object o;
                if (d.TryGetValue("type", out o) && (o as string) == "error")
                {
                    var e = d.TryGetValue("error", out o) ? o as Dictionary<string, object> : null; object m = null, t = null;
                    a.Error = e != null && e.TryGetValue("message", out m) ? (e.TryGetValue("type", out t) ? t + ": " : "") + m : "API error"; return a;
                }
                a.StopReason = d.TryGetValue("stop_reason", out o) ? (o as string ?? "") : "";
                if (a.StopReason == "refusal") { a.Error = "the AI declined this question (safety filter) — try asking it differently"; return a; }
                var parts = new List<string>();
                if (d.TryGetValue("content", out o) && o is List<object>)
                    foreach (var b in (List<object>)o) { var bd = b as Dictionary<string, object>; object ty, tx; if (bd != null && bd.TryGetValue("type", out ty) && (ty as string) == "text" && bd.TryGetValue("text", out tx)) parts.Add(tx as string ?? ""); }
                if (d.TryGetValue("usage", out o) && o is Dictionary<string, object>) { var u = (Dictionary<string, object>)o; object n; if (u.TryGetValue("input_tokens", out n) && n is double) a.InTokens = (int)(double)n; if (u.TryGetValue("output_tokens", out n) && n is double) a.OutTokens = (int)(double)n; }
                a.Text = string.Join("\n", parts).Trim();
                if (a.Text == "") { a.Error = a.StopReason == "max_tokens" ? "the answer was cut off — ask a shorter question" : "no answer text"; return a; }
                a.Ok = true;
            }
            catch (Exception ex) { a.Error = "unreadable reply (" + ex.Message + ")"; }
            return a;
        }
    }

    public static class KeystoneNews
    {
        // FOMC statement days (14:00 NY, press conference 14:30), 2019 → 2026, from the Fed's published calendars.
        public static readonly string[] FomcDates =
        {
            "2019-01-30", "2019-03-20", "2019-05-01", "2019-06-19", "2019-07-31", "2019-09-18", "2019-10-30", "2019-12-11",
            "2020-01-29", "2020-04-29", "2020-06-10", "2020-07-29", "2020-09-16", "2020-11-05", "2020-12-16",
            "2021-01-27", "2021-03-17", "2021-04-28", "2021-06-16", "2021-07-28", "2021-09-22", "2021-11-03", "2021-12-15",
            "2022-01-26", "2022-03-16", "2022-05-04", "2022-06-15", "2022-07-27", "2022-09-21", "2022-11-02", "2022-12-14",
            "2023-02-01", "2023-03-22", "2023-05-03", "2023-06-14", "2023-07-26", "2023-09-20", "2023-11-01", "2023-12-13",
            "2024-01-31", "2024-03-20", "2024-05-01", "2024-06-12", "2024-07-31", "2024-09-18", "2024-11-07", "2024-12-18",
            "2025-01-29", "2025-03-19", "2025-05-07", "2025-06-18", "2025-07-30", "2025-09-17", "2025-10-29", "2025-12-10",
            "2026-01-28", "2026-03-18", "2026-04-29", "2026-06-17", "2026-07-29", "2026-09-16", "2026-10-28", "2026-12-09"
        };
        static DateTime D(string s) { return DateTime.ParseExact(s, "yyyy-MM-dd", CultureInfo.InvariantCulture); }

        // Non-farm payrolls: the third Friday after the week (Sun → Sat) that holds the 12th of the month before; Jan 1 moves a
        // week later, a July 3 / 4 holiday moves it to the Thursday before. Your News.csv overrides it (shutdowns, delays).
        public static DateTime NfpDate(int year, int month)
        {
            var prev = new DateTime(year, month, 1).AddMonths(-1); var twelfth = new DateTime(prev.Year, prev.Month, 12);
            var weekEnd = twelfth.AddDays(6 - (int)twelfth.DayOfWeek); var d = weekEnd.AddDays(20);
            if (d.Month == 1 && d.Day == 1) d = d.AddDays(7);
            if (d.Month == 7 && (d.Day == 4 || (d.Day == 3 && new DateTime(d.Year, 7, 4).DayOfWeek == DayOfWeek.Saturday))) d = d.AddDays(-1);
            return d;
        }

        public static List<KeystoneNewsEvent> BuiltIn(DateTime from, DateTime to)
        {
            var list = new List<KeystoneNewsEvent>();
            foreach (var s in FomcDates)
            {
                var d = D(s); if (d < from.Date || d > to.Date) continue;
                list.Add(new KeystoneNewsEvent { Time = d.AddHours(14), Title = "FOMC RATE DECISION", Source = "BUILT-IN" });
                list.Add(new KeystoneNewsEvent { Time = d.AddHours(14).AddMinutes(30), Title = "FOMC PRESS CONFERENCE", Source = "BUILT-IN" });
            }
            foreach (var e in new[] { Tuple.Create("2020-03-03 10:00", "FED EMERGENCY RATE CUT"), Tuple.Create("2020-03-15 17:00", "FED EMERGENCY RATE CUT") })
            {
                var t = DateTime.ParseExact(e.Item1, "yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture); if (t >= from.Date && t <= to.Date.AddDays(1)) list.Add(new KeystoneNewsEvent { Time = t, Title = e.Item2, Source = "BUILT-IN" });
            }
            for (var m = new DateTime(from.Year, from.Month, 1); m <= to; m = m.AddMonths(1))
            {
                var d = NfpDate(m.Year, m.Month); if (d < from.Date || d > to.Date) continue;
                list.Add(new KeystoneNewsEvent { Time = d.AddHours(8).AddMinutes(30), Title = "NON-FARM PAYROLLS (date by rule)", Source = "RULE" });
            }
            return list.OrderBy(e => e.Time).ToList();
        }

        // News.csv: date,time (NY),currency,impact,title — e.g. 2026-10-14,08:30,USD,HIGH,CPI. Lines starting with # are notes.
        public static List<KeystoneNewsEvent> ParseCsv(IEnumerable<string> lines)
        {
            var list = new List<KeystoneNewsEvent>();
            foreach (var raw in lines ?? new string[0])
            {
                var l = (raw ?? string.Empty).Trim(); if (l == "" || l.StartsWith("#")) continue;
                var a = l.Split(','); if (a.Length < 5) continue; DateTime t;
                if (!DateTime.TryParseExact(a[0].Trim() + " " + a[1].Trim(), new[] { "yyyy-MM-dd HH:mm", "yyyy-MM-dd H:mm" }, CultureInfo.InvariantCulture, DateTimeStyles.None, out t)) continue;
                list.Add(new KeystoneNewsEvent { Time = t, Currency = a[2].Trim().ToUpperInvariant(), Impact = a[3].Trim().ToUpperInvariant(), Title = string.Join(",", a.Skip(4)).Trim(), Source = "FILE" });
            }
            return list;
        }
        public static string ToCsv(KeystoneNewsEvent e) { return e.Time.ToString("yyyy-MM-dd,HH:mm", CultureInfo.InvariantCulture) + "," + e.Currency + "," + e.Impact + "," + (e.Title ?? string.Empty).Replace(",", " "); }

        // The ForexFactory week feed (JSON array of {title, country, date with offset, impact}). toNy converts the offset time.
        public static List<KeystoneNewsEvent> ParseForexFactory(string json, Func<DateTimeOffset, DateTime> toNy)
        {
            var list = new List<KeystoneNewsEvent>(); if (string.IsNullOrEmpty(json)) return list;
            foreach (System.Text.RegularExpressions.Match m in System.Text.RegularExpressions.Regex.Matches(json, "\\{[^{}]*\\}"))
            {
                var f = new Dictionary<string, string>();
                foreach (System.Text.RegularExpressions.Match kv in System.Text.RegularExpressions.Regex.Matches(m.Value, "\"(\\w+)\"\\s*:\\s*\"((?:[^\"\\\\]|\\\\.)*)\""))
                    f[kv.Groups[1].Value] = kv.Groups[2].Value.Replace("\\/", "/").Replace("\\\"", "\"");
                string date, title, country, impact; DateTimeOffset at;
                if (!f.TryGetValue("date", out date) || !f.TryGetValue("title", out title) || !DateTimeOffset.TryParse(date, CultureInfo.InvariantCulture, DateTimeStyles.None, out at)) continue;
                f.TryGetValue("country", out country); f.TryGetValue("impact", out impact);
                list.Add(new KeystoneNewsEvent { Time = toNy(at), Title = title, Currency = (country ?? "").ToUpperInvariant(), Impact = (impact ?? "").ToUpperInvariant(), Source = "FOREXFACTORY" });
            }
            return list;
        }

        // Built-in + file: a file / feed event at the same minute replaces a built-in one; any payrolls line in a month replaces the rule date.
        public static List<KeystoneNewsEvent> Combine(List<KeystoneNewsEvent> builtIn, List<KeystoneNewsEvent> file)
        {
            file = file ?? new List<KeystoneNewsEvent>();
            Func<string, bool> isNfp = t => { var u = (t ?? "").ToUpperInvariant(); return u.Contains("NON-FARM") || u.Contains("NONFARM") || u.Contains("NFP"); };
            var nfpMonths = new HashSet<DateTime>(file.Where(e => isNfp(e.Title)).Select(e => new DateTime(e.Time.Year, e.Time.Month, 1)));
            var fileMinutes = new HashSet<DateTime>(file.Select(e => e.Time));
            var keep = (builtIn ?? new List<KeystoneNewsEvent>()).Where(e => !(e.Source == "RULE" && nfpMonths.Contains(new DateTime(e.Time.Year, e.Time.Month, 1))) && !fileMinutes.Contains(e.Time));
            return keep.Concat(file).GroupBy(e => e.Time.Ticks + "|" + (e.Title ?? "").ToUpperInvariant() + "|" + e.Currency).Select(g => g.Last()).OrderBy(e => e.Time).ToList();
        }

        // The BLS news-release archive pages (bls.gov/bls/news-release/cpi.htm, ppi.htm, empsit.htm) link every past release as
        // /news.release/archives/cpi_MMDDYYYY.htm — the file name is the release day; BLS releases these at 08:30 New York.
        public static List<KeystoneNewsEvent> ParseBlsArchive(string html, string prefix, string title)
        {
            var list = new List<KeystoneNewsEvent>(); if (string.IsNullOrEmpty(html)) return list; var seen = new HashSet<DateTime>();
            foreach (System.Text.RegularExpressions.Match m in System.Text.RegularExpressions.Regex.Matches(html, prefix + "_(\\d{8})\\.htm", System.Text.RegularExpressions.RegexOptions.IgnoreCase))
            {
                DateTime d; if (!DateTime.TryParseExact(m.Groups[1].Value, "MMddyyyy", CultureInfo.InvariantCulture, DateTimeStyles.None, out d) || !seen.Add(d)) continue;
                list.Add(new KeystoneNewsEvent { Time = d.AddHours(8).AddMinutes(30), Title = title, Currency = "USD", Impact = "HIGH", Source = "BLS" });
            }
            return list.OrderBy(e => e.Time).ToList();
        }

        // A short tag per news: FOMC, NFP, CPI, PPI, GDP, RETAIL, PCE, ISM, JOLTS, NEWS
        public static string Tag(KeystoneNewsEvent e)
        {
            var t = (e == null ? "" : e.Title ?? "").ToUpperInvariant();
            if (t.Contains("FOMC") || t.Contains("FEDERAL FUNDS") || t.StartsWith("FED ")) return "FOMC";
            if (t.Contains("NON-FARM") || t.Contains("NONFARM") || t.Contains("NFP")) return "NFP";
            if (t.Contains("CPI")) return "CPI"; if (t.Contains("PPI")) return "PPI"; if (t.Contains("GDP")) return "GDP"; if (t.Contains("RETAIL")) return "RETAIL";
            if (t.Contains("PCE")) return "PCE"; if (t.Contains("ISM")) return "ISM"; if (t.Contains("JOLTS")) return "JOLTS";
            return "NEWS";
        }
        public static List<string> Tags(IEnumerable<KeystoneNewsEvent> events)
        {
            string[] order = { "FOMC", "NFP", "CPI", "PPI", "GDP", "RETAIL", "PCE", "ISM", "JOLTS", "NEWS" };
            var set = new HashSet<string>((events ?? new KeystoneNewsEvent[0]).Select(Tag));
            return order.Where(set.Contains).ToList();
        }

        public static List<KeystoneNewsEvent> ForSession(List<KeystoneNewsEvent> all, DateTime session, bool highOnly)
        {
            DateTime a = session.Date.AddDays(-1).AddHours(18), b = session.Date.AddHours(17);
            return (all ?? new List<KeystoneNewsEvent>()).Where(e => e.Time >= a && e.Time <= b && (e.Currency == "USD" || e.Currency == "ALL") && (!highOnly || e.Impact == "HIGH")).OrderBy(e => e.Time).ToList();
        }
    }

    // ---- LIVE DESK math: drawdown room and target progress of a prop account from YOUR firm settings (an estimate) ----------
    public static class KeystoneLiveMath
    {
        // Trailing floor = highest balance − max drawdown; "stops at start" = the floor never rises above the starting balance.
        public static double Floor(double peak, double size, double maxDd, bool stopsAtStart) { double f = peak - maxDd; if (stopsAtStart && size > 0 && f > size) f = size; return f; }
        public static double Room(double balance, double peak, double size, double maxDd, bool stopsAtStart) { return balance - Floor(Math.Max(peak, balance), size, maxDd, stopsAtStart); }
        // 0 → 1 toward the profit target (target = profit over the start, e.g. 3000 on a 50K)
        public static double Progress(double balance, double size, double target) { return target <= 0 ? 0 : Math.Max(0, Math.Min(1, (balance - size) / target)); }
    }

    // ---- SETUP COACH: how the chosen strategy's entries did on earlier days (no look-ahead: only days before the replayed one) --
    // For every earlier entry: the best move in its favour in R (R = the distance to its own stop) before the stop was touched
    // (a minute that touches both counts as the stop), and where it stood at the session end. From that: the target in R that
    // made the most per trade, how often it was reached first, and contracts for a $ risk.
    public sealed class KeystoneCoachReport
    {
        public int Days, Signals; public bool Ready; public double BestR, HitRate, Expectancy, BuyExpectancy, SellExpectancy; public int Buys, Sells;
        public Dictionary<double, double> ExpectancyByR = new Dictionary<double, double>();
    }
    public static class KeystoneSetupCoach
    {
        public static readonly double[] Targets = { 0.5, 1, 1.5, 2, 2.5, 3 };
        public const int MinSignals = 8;

        // (max favourable R before the stop, R at the session end, stopped?) — null when the entry has no stop
        public static Tuple<double, double, bool> Walk(KeystoneReplaySignal sg, List<KeystoneArcBar> bars)
        {
            if (sg == null || bars == null || double.IsNaN(sg.Stop) || double.IsNaN(sg.Entry)) return null;
            double risk = Math.Abs(sg.Entry - sg.Stop); if (risk <= 0) return null;
            double maxR = 0, endR = 0; bool stopped = false; DateTime from = sg.Time.AddMinutes(1);
            foreach (var b in bars)
            {
                if (b.Time <= from) continue;
                double adverse = sg.Dir > 0 ? (sg.Entry - b.Low) / risk : (b.High - sg.Entry) / risk;
                if (adverse >= 1) { stopped = true; endR = -1; break; }
                double fav = sg.Dir > 0 ? (b.High - sg.Entry) / risk : (sg.Entry - b.Low) / risk; if (fav > maxR) maxR = fav;
                endR = sg.Dir > 0 ? (b.Close - sg.Entry) / risk : (sg.Entry - b.Close) / risk;
            }
            return Tuple.Create(maxR, endR, stopped);
        }
        public static double ResultR(Tuple<double, double, bool> w, double target) { return w.Item1 >= target ? target : (w.Item3 ? -1 : w.Item2); }

        public static KeystoneCoachReport Learn(IEnumerable<Tuple<List<KeystoneReplaySignal>, List<KeystoneArcBar>>> days)
        {
            var rep = new KeystoneCoachReport(); var walks = new List<Tuple<int, Tuple<double, double, bool>>>();
            foreach (var d in days ?? new Tuple<List<KeystoneReplaySignal>, List<KeystoneArcBar>>[0])
            {
                rep.Days++;
                foreach (var sg in d.Item1 ?? new List<KeystoneReplaySignal>()) { var wk = Walk(sg, d.Item2); if (wk != null) walks.Add(Tuple.Create(sg.Dir, wk)); }
            }
            rep.Signals = walks.Count; rep.Buys = walks.Count(x => x.Item1 > 0); rep.Sells = rep.Signals - rep.Buys; if (walks.Count == 0) return rep;
            double best = double.MinValue;
            foreach (var t in Targets)
            {
                double e = walks.Average(x => ResultR(x.Item2, t)); rep.ExpectancyByR[t] = e;
                if (e > best + 1e-9) { best = e; rep.BestR = t; }
            }
            rep.Expectancy = best; rep.HitRate = walks.Count(x => x.Item2.Item1 >= rep.BestR) / (double)walks.Count;
            rep.BuyExpectancy = rep.Buys == 0 ? 0 : walks.Where(x => x.Item1 > 0).Average(x => ResultR(x.Item2, rep.BestR));
            rep.SellExpectancy = rep.Sells == 0 ? 0 : walks.Where(x => x.Item1 < 0).Average(x => ResultR(x.Item2, rep.BestR));
            rep.Ready = rep.Signals >= MinSignals; return rep;
        }

        public static int Contracts(double riskDollars, double riskPts, double pointValue, int max)
        {
            if (riskPts <= 0 || pointValue <= 0) return 1;
            return Math.Max(1, Math.Min(Math.Max(1, max), (int)Math.Floor(riskDollars / (riskPts * pointValue))));
        }
    }

    // ---- PATTERN ENGINE ("similar moments"): every past moment as a fingerprint of how price got there, and what came next ----
    // Fingerprint at a minute (only bars up to that minute): the path of the last 30 minutes (10 points), the last six 5-minute
    // moves, where price sits in the day's range, the move since the session open, and how busy the market is — all in units of
    // the recent 1-minute range (ATR), so 2020 and 2026 compare fairly. Outcome: in the next 30 minutes, did price move
    // +3 ATR before −3 ATR (up first), the other way (down first), or neither (a minute touching both = neither).
    // A query only uses moments from EARLIER days at a similar time of day — never the future.
    public sealed class KeystoneAnalogIndex
    {
        public string Symbol = "MNQ"; public int Dim = KeystoneAnalog.Dim, Sessions;
        public readonly List<float> Feats = new List<float>(); public readonly List<int> Tod = new List<int>(), DayKey = new List<int>(); public readonly List<sbyte> Outcome = new List<sbyte>(); public readonly List<float> EndMove = new List<float>(), Barrier = new List<float>();
        public readonly List<int>[] Buckets = Enumerable.Range(0, 288).Select(i => new List<int>()).ToArray();   // 5-minute buckets of the 24 h day
        public int Count { get { return Tod.Count; } }
    }
    public sealed class KeystoneAnalogAnswer { public List<int> Ids = new List<int>(); public List<double> Dist = new List<double>(); public int Neighbors, Up, Down, None, PoolUp, PoolDown, Pool; public double AvgEnd, AvgBarrier; public double UpShare { get { return Up + Down == 0 ? 0.5 : Up / (double)(Up + Down); } } public double BaseUp { get { return PoolUp + PoolDown == 0 ? 0.5 : PoolUp / (double)(PoolUp + PoolDown); } } }
    public sealed class KeystoneAnalogYear { public int Year, Calls, Wins, Losses; public double R, BaseHit; public double Hit { get { return Wins + Losses == 0 ? 0 : Wins / (double)(Wins + Losses); } } }
    public sealed class KeystoneAnalogReport
    {
        public int Queries, Calls, Wins, Losses, TrainSamples; public double R, BaseHit; public string Verdict = string.Empty;
        public List<KeystoneAnalogYear> Years = new List<KeystoneAnalogYear>();
        public double[] CalPredicted = new double[10], CalRealized = new double[10]; public int[] CalCount = new int[10];
        public double Hit { get { return Wins + Losses == 0 ? 0 : Wins / (double)(Wins + Losses); } }
    }
    public static class KeystoneAnalog
    {
        public const int Lookback = 30, Horizon = 30, Dim = 20; public static int Step = 2; public static double BarrierAtr = 3.0;
        static int TodOf(DateTime t) { var m = (int)((t.TimeOfDay.TotalMinutes + 360) % 1440); return m; }   // minutes since 18:00 New York
        public static int DayKeyOf(DateTime session) { return session.Year * 10000 + session.Month * 100 + session.Day; }
        // the session day and New York minute of a stored moment
        public static DateTime SessionOfKey(int key) { return new DateTime(key / 10000, key / 100 % 100, key % 100); }
        public static DateTime TimeOf(KeystoneAnalogIndex idx, int id) { return SessionOfKey(idx.DayKey[id]).AddDays(-1).AddHours(18).AddMinutes(idx.Tod[id]); }
        public static double Atr(List<KeystoneArcBar> s, int i) { double sum = 0; int n = 0; for (int k = Math.Max(0, i - Lookback + 1); k <= i; k++) { sum += s[k].High - s[k].Low; n++; } return n == 0 ? 0 : sum / n; }

        // the fingerprint of minute i of a session (bars 0 … i only); null before 30 minutes of the session
        public static float[] Fingerprint(List<KeystoneArcBar> s, int i)
        {
            if (s == null || i < Lookback || i >= s.Count) return null;
            double atr = Math.Max(1e-6, Atr(s, i)), c = s[i].Close; var f = new float[Dim]; int n = 0;
            for (int k = 3; k <= 30; k += 3) f[n++] = (float)((s[i - k].Close - c) / atr / 4);                 // the path: 10 points
            for (int k = 0; k < 6; k++) { int a = i - 5 * k, b = a - 5; f[n++] = b >= 0 ? (float)((s[a].Close - s[b].Close) / atr / 3) : 0; }   // six 5-minute moves
            double hi = double.MinValue, lo = double.MaxValue; for (int k = 0; k <= i; k++) { hi = Math.Max(hi, s[k].High); lo = Math.Min(lo, s[k].Low); }
            f[n++] = (float)(hi > lo ? (c - lo) / (hi - lo) * 2 - 1 : 0);                                          // where in the day's range
            f[n++] = (float)Math.Max(-3, Math.Min(3, (c - s[0].Open) / atr / 20));                                 // move since the session open
            double atrDay = 0; for (int k = 0; k <= i; k++) atrDay += s[k].High - s[k].Low; atrDay /= (i + 1);
            f[n++] = (float)Math.Max(-2, Math.Min(2, Math.Log(atr / Math.Max(1e-6, atrDay))));                     // busier / quieter than today so far
            f[n++] = (float)((s[i].Close - s[i].Open) / atr / 2);                                                   // the last candle
            return f;
        }
        // +1 up first, −1 down first, 0 neither (or both in one minute); endMove = the close after the horizon, in barriers
        public static int Outcome(List<KeystoneArcBar> s, int i, double barrier, out double endMove)
        {
            endMove = 0; double c = s[i].Close; int last = Math.Min(s.Count - 1, i + Horizon);
            for (int k = i + 1; k <= last; k++)
            {
                bool up = s[k].High >= c + barrier, dn = s[k].Low <= c - barrier;
                if (up && dn) { endMove = (s[last].Close - c) / barrier; return 0; }
                if (up) { endMove = 1; return 1; }
                if (dn) { endMove = -1; return -1; }
            }
            endMove = last > i ? (s[last].Close - c) / barrier : 0; return 0;
        }
        // adds one session (call in date order); only moments with a full horizon ahead
        public static void AddSession(KeystoneAnalogIndex idx, List<KeystoneArcBar> s, DateTime session)
        {
            if (s == null || s.Count < Lookback + Horizon + 5) return; idx.Sessions++; int key = DayKeyOf(session);
            for (int i = Lookback; i + Horizon < s.Count; i += Step)
            {
                var f = Fingerprint(s, i); if (f == null) continue; double barrier = BarrierAtr * Math.Max(1e-6, Atr(s, i)), end; int o = Outcome(s, i, barrier, out end);
                int id = idx.Count; idx.Feats.AddRange(f); idx.Tod.Add(TodOf(s[i].Time)); idx.DayKey.Add(key); idx.Outcome.Add((sbyte)o); idx.EndMove.Add((float)end); idx.Barrier.Add((float)barrier);
                idx.Buckets[idx.Tod[id] / 5].Add(id);
            }
        }
        // the k nearest moments of earlier days within ±window minutes of the time of day
        public static KeystoneAnalogAnswer Query(KeystoneAnalogIndex idx, float[] f, DateTime at, int beforeDayKey, int k, int window)
        {
            var ans = new KeystoneAnalogAnswer(); if (idx == null || f == null) return ans; int tod = TodOf(at);
            var bestD = new double[k]; var bestI = new int[k]; int filled = 0; double worst = double.MaxValue;
            for (int b = (tod - window) / 5 - 1; b <= (tod + window) / 5 + 1; b++)
            {
                var list = idx.Buckets[((b % 288) + 288) % 288];
                foreach (int id in list)
                {
                    if (idx.DayKey[id] >= beforeDayKey) break;                 // days were added in order: the rest are not earlier
                    int dt = Math.Abs(idx.Tod[id] - tod); if (Math.Min(dt, 1440 - dt) > window) continue;
                    ans.Pool++; if (idx.Outcome[id] > 0) ans.PoolUp++; else if (idx.Outcome[id] < 0) ans.PoolDown++;
                    double d = 0; int o = id * idx.Dim; for (int j = 0; j < idx.Dim; j++) { double x = idx.Feats[o + j] - f[j]; d += x * x; if (filled == k && d >= worst) break; }
                    if (filled < k) { bestD[filled] = d; bestI[filled] = id; filled++; if (filled == k) worst = bestD.Max(); }
                    else if (d < worst) { int wi = Array.IndexOf(bestD, worst); bestD[wi] = d; bestI[wi] = id; worst = bestD.Max(); }
                }
            }
            ans.Neighbors = filled;
            foreach (var n in Enumerable.Range(0, filled).OrderBy(x => bestD[x])) { ans.Ids.Add(bestI[n]); ans.Dist.Add(Math.Sqrt(bestD[n])); }
            for (int n = 0; n < filled; n++) { int id = bestI[n]; if (idx.Outcome[id] > 0) ans.Up++; else if (idx.Outcome[id] < 0) ans.Down++; else ans.None++; ans.AvgEnd += idx.EndMove[id]; ans.AvgBarrier += idx.Barrier[id]; }
            if (filled > 0) { ans.AvgEnd /= filled; ans.AvgBarrier /= filled; }
            return ans;
        }
        // walk forward: every moment of a later day is judged only from the days before it. A call = up share ≥ threshold (buy) or
        // ≤ 1 − threshold (sell) with enough resolved neighbours; win = the called side came first. Baseline = the same side's share in the
        // time-of-day pool (what you would get by always calling that side at that time).
        public static KeystoneAnalogReport WalkForward(KeystoneAnalogIndex idx, int queryEveryMin, double threshold, int k, int window, int minTrainDays, int fromTod, int toTod, Action<int, int> progress)
        {
            var rep = new KeystoneAnalogReport(); if (idx == null || idx.Count == 0) return rep;
            var days = idx.DayKey.Distinct().ToList(); var firstTest = days.Count > minTrainDays ? days[minTrainDays] : int.MaxValue;
            var years = new Dictionary<int, KeystoneAnalogYear>(); double baseSum = 0; int every = Math.Max(1, queryEveryMin / Step);
            int total = 0; for (int id = 0; id < idx.Count; id++) if (idx.DayKey[id] >= firstTest) total++;
            int done = 0, lastDay = -1, sinceDay = 0;
            for (int id = 0; id < idx.Count; id++)
            {
                if (idx.DayKey[id] < firstTest) continue; done++;
                if (idx.DayKey[id] != lastDay) { lastDay = idx.DayKey[id]; sinceDay = 0; } else sinceDay++;
                if (sinceDay % every != 0) continue; int tod = idx.Tod[id]; if (tod < fromTod || tod > toTod) continue;
                var f = new float[idx.Dim]; for (int j = 0; j < idx.Dim; j++) f[j] = idx.Feats[id * idx.Dim + j];
                var at = new DateTime(2000, 1, 1).AddMinutes(tod + 18 * 60);
                var a = Query(idx, f, at, idx.DayKey[id], k, window); rep.Queries++;
                if (a.Up + a.Down < k / 3) continue;
                double p = a.UpShare; int bin = Math.Max(0, Math.Min(9, (int)(p * 10)));
                rep.CalCount[bin]++; rep.CalPredicted[bin] += p; if (idx.Outcome[id] > 0) rep.CalRealized[bin] += 1; else if (idx.Outcome[id] == 0) rep.CalRealized[bin] += 0.5;
                int call = p >= threshold ? 1 : p <= 1 - threshold ? -1 : 0; if (call == 0) continue;
                int o = idx.Outcome[id]; double r = o == call ? 1 : o == -call ? -1 : call * idx.EndMove[id];
                double baseHit = call > 0 ? a.BaseUp : 1 - a.BaseUp;
                rep.Calls++; rep.R += r; baseSum += baseHit; if (o == call) rep.Wins++; else if (o == -call) rep.Losses++;
                int y = idx.DayKey[id] / 10000; KeystoneAnalogYear yr; if (!years.TryGetValue(y, out yr)) years[y] = yr = new KeystoneAnalogYear { Year = y };
                yr.Calls++; yr.R += r; yr.BaseHit += baseHit; if (o == call) yr.Wins++; else if (o == -call) yr.Losses++;
                if (progress != null && rep.Queries % 200 == 0) progress(done, total);
            }
            rep.TrainSamples = idx.Count; rep.BaseHit = rep.Calls == 0 ? 0 : baseSum / rep.Calls;
            foreach (var yr in years.Values) yr.BaseHit = yr.Calls == 0 ? 0 : yr.BaseHit / yr.Calls;
            rep.Years = years.Values.OrderBy(x => x.Year).ToList();
            for (int b = 0; b < 10; b++) if (rep.CalCount[b] > 0) { rep.CalPredicted[b] /= rep.CalCount[b]; rep.CalRealized[b] /= rep.CalCount[b]; }
            double edge = rep.Hit - rep.BaseHit; int goodYears = rep.Years.Count(x => x.Calls >= 20 && x.Hit > x.BaseHit && x.R > 0), judgedYears = rep.Years.Count(x => x.Calls >= 20);
            rep.Verdict = rep.Calls < 100 ? "NOT ENOUGH CALLS TO JUDGE (" + rep.Calls + ") — load more history or lower the threshold"
                : edge >= 0.02 && rep.R > 0 && goodYears * 2 > judgedYears ? "PROMISING • similar moments beat the baseline by " + (100 * edge).ToString("0.0") + " points and made " + (rep.R / rep.Calls).ToString("+0.00;-0.00") + "R a call, positive in " + goodYears + " of " + judgedYears + " years"
                : "NO RELIABLE EDGE • hit " + (100 * rep.Hit).ToString("0.0") + "% vs baseline " + (100 * rep.BaseHit).ToString("0.0") + "% • " + (rep.Calls == 0 ? 0 : rep.R / rep.Calls).ToString("+0.00;-0.00") + "R a call — the history does not predict this horizon better than chance";
            return rep;
        }
    }

    public sealed class KeystoneIdea
    {
        public List<string> Symbols = new List<string>(); public List<int> Times = new List<int>(); public List<string> Dirs = new List<string>();
        public string Entry = "AT"; public List<int> Ranges = new List<int> { 0 };
        public List<double> MnqTp = new List<double>(), MnqSl = new List<double>(), MgcTp = new List<double>(), MgcSl = new List<double>(); public List<int> Qty = new List<int> { 1 };
        public List<string> Fills = new List<string>(); public List<double> MnqGap = new List<double>(), MgcGap = new List<double>(); public List<int> Accounts = new List<int>();
        public List<Tuple<string, int, int>> Windows = new List<Tuple<string, int, int>>();
        public List<double> MnqBe = new List<double>(), MgcBe = new List<double>(), MnqPartial = new List<double>(), MgcPartial = new List<double>(), DayTarget = new List<double>(), DayStop = new List<double>();
        public bool Strict;
        public int Exit = 1555; public bool ExitSet; public string Error = string.Empty, Text = string.Empty;
        public bool IsFvg { get { return Entry == "FVG"; } }
    }

    public static class KeystoneIdeas
    {
        public const int LimitMinutes = 60;   // FILL 50: the limit at the gap's middle waits this long
        static List<double> Nums(string s) { var l = new List<double>(); foreach (var p in s.Split(',')) { double v; string q = p.Trim().ToUpperInvariant(); if (q == "NONE") l.Add(0); else if (q == "C1") l.Add(-1); else if (double.TryParse(q, System.Globalization.NumberStyles.Any, CultureInfo.InvariantCulture, out v) && v >= 0) l.Add(v); } return l.Distinct().ToList(); }
        static int Hhmm(string s) { s = s.Replace(":", ""); int v; return s.Length >= 3 && int.TryParse(s, out v) && v >= 0 && v <= 2359 && v % 100 < 60 ? v : -1; }
        static bool IsNums(string s) { return s.Length > 0 && s.Split(',').All(p => { double v; return double.TryParse(p, System.Globalization.NumberStyles.Any, CultureInfo.InvariantCulture, out v); }); }
        public static string Hm(int hhmm) { return (hhmm / 100).ToString("00") + ":" + (hhmm % 100).ToString("00"); }
        static string Pts(double v) { return v.ToString("0.##", CultureInfo.InvariantCulture); }
        public static string StopName(double v) { return v < 0 ? "SL C1" : v == 0 ? "NO STOP" : "SL " + Pts(v); }
        public static readonly Tuple<string, int, int>[] Sessions = { Tuple.Create("ASIA", 1800, 300), Tuple.Create("LONDON", 300, 930), Tuple.Create("NY", 930, 1555), Tuple.Create("ALL", 1800, 1555) };

        public static KeystoneIdea Parse(string line)
        {
            var idea = new KeystoneIdea { Text = (line ?? string.Empty).Trim() };
            var w = idea.Text.ToUpperInvariant().Replace(", ", ",").Replace(" ,", ",").Split(new[] { ' ', '\t', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
            int from = -1;
            for (int i = 0; i < w.Length; i++)
            {
                string t = w[i]; Func<string> next = () => i + 1 < w.Length ? w[++i] : string.Empty;
                if (t == "MNQ" || t == "MGC") { if (!idea.Symbols.Contains(t)) idea.Symbols.Add(t); }
                else if (t == "BOTH") { idea.Symbols = new List<string> { "MNQ", "MGC" }; }
                else if (t.Split(',').All(x => x == "BUY" || x == "SELL" || x == "EITHER")) { foreach (var d in t.Split(',')) if (!idea.Dirs.Contains(d)) idea.Dirs.Add(d); }
                else if (t == "AT") { foreach (var p in next().Split(',')) { int h = Hhmm(p); if (h < 0) idea.Error = "AT needs a time like 0930"; else idea.Times.Add(h); } }
                else if (t == "ORB" || t == "FADE") { idea.Entry = t; idea.Ranges = Nums(next()).Select(v => (int)v).Where(v => v > 0).ToList(); if (idea.Ranges.Count == 0) idea.Error = t + " needs minutes, e.g. ORB 15"; }
                else if (t == "FVG") { idea.Entry = "FVG"; idea.Ranges = i + 1 < w.Length && IsNums(w[i + 1]) ? Nums(next()).Select(v => (int)v).Where(v => v >= 1 && v <= 240).Distinct().ToList() : new List<int> { 1 }; if (idea.Ranges.Count == 0) idea.Error = "FVG needs candle minutes, e.g. FVG 1 or FVG 1,5"; }
                else if (t == "FILL") { foreach (var p in next().Split(',')) { string f = p.TrimEnd('%'); if (f == "CLOSE" || f == "BREAK" || f == "25" || f == "40" || f == "50") { if (!idea.Fills.Contains(f)) idea.Fills.Add(f); } else idea.Error = "FILL is CLOSE, 25, 40, 50 or BREAK"; } }
                else if (t == "STRICT") idea.Strict = true;
                else if (t == "BE") idea.MnqBe = Nums(next()).Where(v => v >= 0).ToList();
                else if (t == "MGCBE") idea.MgcBe = Nums(next()).Where(v => v >= 0).ToList();
                else if (t == "PARTIAL") idea.MnqPartial = Nums(next()).Where(v => v >= 0).ToList();
                else if (t == "MGCPARTIAL") idea.MgcPartial = Nums(next()).Where(v => v >= 0).ToList();
                else if (t == "DAYTARGET") idea.DayTarget = Nums(next()).Where(v => v >= 0).ToList();
                else if (t == "DAYSTOP") idea.DayStop = Nums(next()).Where(v => v >= 0).ToList();
                else if (t == "GAP") idea.MnqGap = Nums(next()).Where(v => v >= 0).ToList();
                else if (t == "MGCGAP") idea.MgcGap = Nums(next()).Where(v => v >= 0).ToList();
                else if (t == "ACCOUNTS" || t == "ACCOUNT") idea.Accounts = Nums(next()).Select(v => Math.Max(1, Math.Min(20, (int)v))).Distinct().ToList();
                else if (t == "SESSION" || t == "SESSIONS") { foreach (var p in next().Split(',')) { var s = Sessions.FirstOrDefault(x => x.Item1 == (p == "NEWYORK" || p == "NYC" ? "NY" : p)); if (s == null) idea.Error = "SESSION is ASIA, LONDON, NY or ALL"; else if (!idea.Windows.Contains(s)) idea.Windows.Add(s); } }
                else if (t == "FROM") { from = Hhmm(next()); if (from < 0) idea.Error = "FROM needs a time like 0930"; }
                else if (t == "TO") { int to = Hhmm(next()); if (to < 0 || from < 0) idea.Error = "write FROM hhmm TO hhmm"; else idea.Windows.Add(Tuple.Create(Hm(from) + "–" + Hm(to), from, to)); }
                else if (t == "TP") idea.MnqTp = Nums(next()).Where(v => v > 0).ToList();
                else if (t == "SL") idea.MnqSl = Nums(next());
                else if (t == "MGCTP") idea.MgcTp = Nums(next()).Where(v => v > 0).ToList();
                else if (t == "MGCSL") idea.MgcSl = Nums(next());
                else if (t == "EXIT") { int h = Hhmm(next()); if (h < 0) idea.Error = "EXIT needs a time like 1555"; else { idea.Exit = h; idea.ExitSet = true; } }
                else if (t == "QTY" || t == "CONTRACTS") idea.Qty = Nums(next()).Select(v => Math.Max(1, (int)v)).Distinct().ToList();
                else idea.Error = "I don't know the word \"" + t + "\" (use MNQ MGC BOTH AT BUY SELL EITHER ORB FADE FVG FILL STRICT GAP SESSION FROM TO ACCOUNTS DAYTARGET DAYSTOP TP SL BE PARTIAL MGCTP MGCSL MGCBE MGCPARTIAL EXIT QTY)";
            }
            if (idea.Symbols.Count == 0) idea.Symbols = new List<string> { "MNQ" };
            if (idea.Times.Count == 0) idea.Times.Add(930);
            bool hasTp = idea.MnqTp.Count > 0, hasSl = idea.MnqSl.Count > 0, hasGap = idea.MnqGap.Count > 0, hasMgcGap = idea.MgcGap.Count > 0, hasBe = idea.MnqBe.Count > 0, hasPartial = idea.MnqPartial.Count > 0;
            if (idea.IsFvg)
            {
                if (idea.Dirs.Count == 0) idea.Dirs = new List<string> { "EITHER", "BUY", "SELL" };
                if (idea.Fills.Count == 0) idea.Fills.Add("CLOSE");
                if (idea.MnqGap.Count == 0) idea.MnqGap = new List<double> { 2, 5 };
                if (idea.MgcGap.Count == 0 || (!hasMgcGap && hasGap)) idea.MgcGap = idea.MnqGap.Select(v => v / 10.0).ToList();
                if (idea.Accounts.Count == 0) idea.Accounts = new List<int> { 1, 3, 5 };
                if (idea.Windows.Count == 0) idea.Windows.Add(Sessions[2]);
                if (idea.MnqTp.Count == 0) idea.MnqTp = new List<double> { 10, 20, 40 };
                if (idea.MnqSl.Count == 0) idea.MnqSl = new List<double> { -1, 10, 20 };
            }
            else
            {
                if (idea.Dirs.Contains("EITHER")) idea.Error = "EITHER (both directions with the lock) is for FVG ideas; for AT / ORB / FADE write BUY,SELL";
                if (idea.Dirs.Count == 0) idea.Dirs = new List<string> { "BUY", "SELL" };
                if (idea.MnqTp.Count == 0) idea.MnqTp = new List<double> { 25, 50, 100, 150 };
                if (idea.MnqSl.Count == 0) idea.MnqSl = new List<double> { 25, 50, 100 };
                if (idea.MnqSl.Contains(-1) || idea.MgcSl.Contains(-1)) idea.Error = "SL C1 (beyond the FVG's first candle) is for FVG ideas";
                if (idea.Accounts.Count == 0) idea.Accounts = new List<int> { 1 };
            }
            bool goldOnly = idea.Symbols.Count == 1 && idea.Symbols[0] == "MGC";   // MGC alone: TP / SL / GAP are gold points
            if (idea.MgcTp.Count == 0) idea.MgcTp = goldOnly && hasTp ? idea.MnqTp.ToList() : idea.MnqTp.Select(v => v / 10.0).ToList();
            if (idea.MgcSl.Count == 0) idea.MgcSl = goldOnly && hasSl ? idea.MnqSl.ToList() : idea.MnqSl.Select(v => v < 0 ? -1 : v / 10.0).ToList();
            if (idea.IsFvg && goldOnly && hasGap && !hasMgcGap) idea.MgcGap = idea.MnqGap.ToList();
            if (idea.MnqBe.Count == 0) idea.MnqBe.Add(0); if (idea.MnqPartial.Count == 0) idea.MnqPartial.Add(0);
            if (idea.MgcBe.Count == 0) idea.MgcBe = goldOnly && hasBe ? idea.MnqBe.ToList() : idea.MnqBe.Select(v => v / 10.0).ToList();
            if (idea.MgcPartial.Count == 0) idea.MgcPartial = goldOnly && hasPartial ? idea.MnqPartial.ToList() : idea.MnqPartial.Select(v => v / 10.0).ToList();
            if (idea.DayTarget.Count == 0) idea.DayTarget.Add(0); if (idea.DayStop.Count == 0) idea.DayStop.Add(0);
            if (!idea.IsFvg && (idea.DayTarget.Any(v => v > 0) || idea.DayStop.Any(v => v > 0))) idea.Error = "DAYTARGET / DAYSTOP are for FVG ideas (several trades a day)";
            if (!idea.IsFvg && idea.Fills.Count > 0) idea.Error = "FILL is for FVG ideas";
            if (idea.Entry == "AT") idea.Ranges = new List<int> { 0 };
            if (idea.MnqTp.Count == 0 || idea.MgcTp.Count == 0) idea.Error = "TP needs at least one target above 0";
            return idea;
        }

        public static string Describe(KeystoneIdea i)
        {
            string sl = string.Join(",", i.MnqSl.Select(v => StopName(v).Replace("SL ", "").Replace("NO STOP", "NONE"))), msl = string.Join(",", i.MgcSl.Select(v => StopName(v).Replace("SL ", "").Replace("NO STOP", "NONE")));
            string entry = i.IsFvg ? "every " + string.Join("/", i.Ranges) + "-minute FVG (gap ≥ " + string.Join("/", i.MnqGap.Select(Pts)) + (i.Symbols.Contains("MGC") ? ", gold ≥ " + string.Join("/", i.MgcGap.Select(Pts)) : "") + ") • fill " + string.Join("/", i.Fills.Select(f => f == "CLOSE" ? "candle-3 close" : f == "BREAK" ? "back in the gap, close our way, then the break" : f + "% limit")) + " • " + string.Join(", ", i.Windows.Select(x => x.Item1 + " " + Hm(x.Item2) + "–" + Hm(x.Item3))) + " • " + string.Join("/", i.Accounts) + " account(s) rotating"
                : (i.Entry == "AT" ? "enter at " : i.Entry + " " + string.Join("/", i.Ranges) + " min after ") + string.Join(", ", i.Times.Select(Hm));
            return string.Join(" + ", i.Symbols) + " • " + entry + " • " + string.Join(" / ", i.Dirs) + " • MNQ TP " + string.Join(",", i.MnqTp.Select(Pts)) + " SL " + sl
                + (i.Symbols.Contains("MGC") ? " • MGC TP " + string.Join(",", i.MgcTp.Select(Pts)) + " SL " + msl : "") + " • exit " + (i.IsFvg && !i.ExitSet ? "session end" : Hm(i.Exit)) + " • " + string.Join(",", i.Qty) + " contract(s)"
                + (i.MnqBe.Any(v => v > 0) ? " • breakeven after +" + string.Join("/", i.MnqBe.Select(v => v == 0 ? "OFF" : Pts(v))) : "") + (i.MnqPartial.Any(v => v > 0) ? " • half off at +" + string.Join("/", i.MnqPartial.Select(v => v == 0 ? "OFF" : Pts(v))) : "")
                + (i.DayTarget.Any(v => v > 0) || i.DayStop.Any(v => v > 0) ? " • each account stops for the day at +$" + string.Join("/", i.DayTarget.Select(v => v == 0 ? "OFF" : v.ToString("0"))) + " / −$" + string.Join("/", i.DayStop.Select(v => v == 0 ? "OFF" : v.ToString("0"))) : "") + (i.Strict ? " • STRICT limit fills (price must trade 1 tick through)" : "");
        }

        static int After(List<KeystoneArcBar> raw, DateTime t) { int lo = 0, hi = raw.Count - 1, f = -1; while (lo <= hi) { int m = (lo + hi) / 2; if (raw[m].Time > t) { f = m; hi = m - 1; } else lo = m + 1; } return f; }

        // The prop / journal day: a trade from 18:00 on belongs to the next date's session.
        public static DateTime SessionDay(DateTime t) { return t.Hour >= 18 ? t.Date.AddDays(1) : t.Date; }
        static KeystoneLabTrade Dated(KeystoneLabTrade t) { t.Day = SessionDay(t.EntryTime.AddMinutes(-1)); return t; }

        // The trades of one instrument × time × entry × range × direction × target × stop (1 contract).
        public static List<KeystoneLabTrade> Trades(List<KeystoneArcBar> raw, string sym, int hhmm, string entry, int range, string dir, double tp, double sl, int exitHhmm)
        {
            return Trades(raw, sym, hhmm, entry, range, dir, tp, sl, exitHhmm, 0, 0);
        }

        public static List<KeystoneLabTrade> Trades(List<KeystoneArcBar> raw, string sym, int hhmm, string entry, int range, string dir, double tp, double sl, int exitHhmm, double be, double partial)
        {
            var output = new List<KeystoneLabTrade>(); if (raw == null || raw.Count == 0) return output;
            double stop = sl > 0 ? sl : 1e9;
            foreach (var day in raw.Select(b => b.Time.Date).Distinct())
            {
                if (day.DayOfWeek == DayOfWeek.Saturday) continue;
                DateTime at = day.AddHours(hhmm / 100).AddMinutes(hhmm % 100), close = day.AddHours(exitHhmm / 100).AddMinutes(exitHhmm % 100); if (close <= at) close = close.AddDays(1);
                int k = After(raw, at); if (k < 0 || raw[k].Time > at.AddMinutes(15)) continue;          // no bar at the time (holiday / no data)
                if (entry == "AT")
                {
                    int d = dir == "BUY" ? 1 : -1;
                    output.Add(Dated(KeystoneLab.Bracket(raw, k, raw[k].Open, d, tp, stop, close, sym, true, be, partial)));
                    continue;
                }
                DateTime rangeEnd = at.AddMinutes(range); double hi = double.MinValue, lo = double.MaxValue; int j = k;
                for (; j < raw.Count && raw[j].Time <= rangeEnd; j++) { hi = Math.Max(hi, raw[j].High); lo = Math.Min(lo, raw[j].Low); }
                if (hi == double.MinValue) continue;
                for (; j < raw.Count && raw[j].Time <= close; j++)
                {
                    var b = raw[j]; bool up = b.High > hi, down = b.Low < lo; if (!up && !down) continue;
                    bool breakUp = up && (!down || b.Open >= (hi + lo) / 2);   // both in one minute: the side it opened nearer
                    if (entry == "ORB")
                    {
                        if ((breakUp && dir != "BUY") || (!breakUp && dir != "SELL")) break;      // the first break decides the day
                        double px = breakUp ? Math.Max(hi, b.Open) : Math.Min(lo, b.Open);
                        output.Add(Dated(KeystoneLab.Bracket(raw, j, px, breakUp ? 1 : -1, tp, stop, close, sym, false, be, partial)));
                    }
                    else
                    {
                        if ((breakUp && dir != "SELL") || (!breakUp && dir != "BUY")) break;      // FADE: sell the break up, buy the break down
                        double px = breakUp ? Math.Max(hi, b.Open) : Math.Min(lo, b.Open);
                        output.Add(Dated(KeystoneLab.Bracket(raw, j, px, breakUp ? -1 : 1, tp, stop, close, sym, false, be, partial)));
                    }
                    break;
                }
            }
            return output;
        }

        // Is the moment inside the window (from < t ≤ to, overnight windows allowed)? end = that window's end.
        public static bool InWindow(DateTime t, int from, int to, out DateTime end)
        {
            int m = t.Hour * 60 + t.Minute, f = from / 100 * 60 + from % 100, e = to / 100 * 60 + to % 100; end = DateTime.MinValue;
            if (f < e) { if (m > f && m <= e) { end = t.Date.AddMinutes(e); return true; } return false; }
            if (m > f) { end = t.Date.AddDays(1).AddMinutes(e); return true; }
            if (m <= e) { end = t.Date.AddMinutes(e); return true; }
            return false;
        }

        // Every fair value gap of the n-minute candles inside the window, both directions, each as its own bracket trade
        // (1 contract): bullish = candle 3's low above candle 1's high by ≥ gap (bearish = the mirror). FILL CLOSE = market at the
        // open of the minute after candle 3 closes; FILL 50 = a limit at the gap's middle for 60 minutes (the fill minute cannot
        // reach the target). SL C1 = just beyond candle 1 (its low for a buy). Out at the target, the stop or the exit time.
        public static List<KeystoneLabTrade> FvgTrades(List<KeystoneArcBar> raw, string sym, int tf, string fill, int from, int to, int exitHhmm, double gap, double tp, double sl)
        {
            return FvgTrades(raw, sym, tf, fill, from, to, exitHhmm, gap, tp, sl, 0, 0, false);
        }

        // FILL: CLOSE = market when candle 3 closes • 25 / 40 / 50 = a limit that far into the gap (from its near edge), waiting
        // 60 minutes, while the candle is still moving • BREAK = price comes back into the gap, a candle closes our way, then the
        // break of its high (low for a sell) — cancelled if price goes beyond candle 1 first. STRICT = a limit fills only when
        // price trades one tick through it. be / partial: see KeystoneLab.Bracket.
        public static List<KeystoneLabTrade> FvgTrades(List<KeystoneArcBar> raw, string sym, int tf, string fill, int from, int to, int exitHhmm, double gap, double tp, double sl, double be, double partial, bool strict)
        {
            var output = new List<KeystoneLabTrade>(); if (raw == null || raw.Count < 3) return output;
            var c = KeystoneEngLab.Candles(raw, Math.Max(1, tf)); double tick = KeystoneMoveStudy.IsMgc(sym) ? 0.1 : 0.25;
            for (int i = 2; i < c.Count; i++)
            {
                var c1 = c[i - 2]; var c3 = c[i];
                if ((c3.Time - c1.Time).TotalMinutes > 2 * tf + 0.01) continue;                       // the three candles must be back to back
                DateTime end; if (!InWindow(c3.Time, from, to, out end)) continue;
                int dir = c3.Low - c1.High >= Math.Max(gap, 1e-9) ? 1 : c1.Low - c3.High >= Math.Max(gap, 1e-9) ? -1 : 0; if (dir == 0) continue;
                DateTime close = end;
                if (exitHhmm >= 0) { close = c3.Time.Date.AddHours(exitHhmm / 100).AddMinutes(exitHhmm % 100); if (close <= c3.Time) close = close.AddDays(1); }
                int k = After(raw, c3.Time); if (k < 0 || raw[k].Time > c3.Time.AddMinutes(15) || raw[k].Time > close) continue;
                double far = dir > 0 ? c1.Low : c1.High, near = dir > 0 ? c3.Low : c3.High, edge = dir > 0 ? c1.High : c1.Low;   // near = where price re-enters the gap
                Func<double, double> stopOf = px => sl < 0 ? dir * (px - far) : sl > 0 ? sl : 1e9;
                DateTime until = c3.Time.AddMinutes(LimitMinutes);
                if (fill == "CLOSE")
                {
                    double px = raw[k].Open, stop = stopOf(px);
                    if (stop > 0) output.Add(Dated(KeystoneLab.Bracket(raw, k, px, dir, tp, stop, close, sym, true, be, partial)));
                }
                else if (fill == "BREAK")
                {
                    bool touched = false; double trigger = double.NaN;
                    for (int j = k; j < raw.Count && raw[j].Time <= close && raw[j].Time <= until; j++)
                    {
                        var b = raw[j];
                        if (!double.IsNaN(trigger) && (dir > 0 ? b.High > trigger : b.Low < trigger))
                        {
                            double px = dir > 0 ? Math.Max(trigger, b.Open) : Math.Min(trigger, b.Open), stop = stopOf(px);
                            if (stop > 0) output.Add(Dated(KeystoneLab.Bracket(raw, j, px, dir, tp, stop, close, sym, false, be, partial)));
                            break;
                        }
                        if (dir > 0 ? b.Low < far : b.High > far) break;                               // beyond candle 1: the setup failed
                        if (dir > 0 ? b.Low <= near : b.High >= near) touched = true;
                        if (touched && (dir > 0 ? b.Close > b.Open : b.Close < b.Open)) trigger = dir > 0 ? b.High : b.Low;   // the latest candle closing our way
                    }
                }
                else
                {
                    double f = fill == "25" ? 0.25 : fill == "40" ? 0.40 : 0.50, level = near - dir * f * Math.Abs(near - edge), need = strict ? level - dir * tick : level;
                    for (int j = k; j < raw.Count && raw[j].Time <= close && raw[j].Time <= until; j++)
                    {
                        var b = raw[j]; if (dir > 0 ? b.Low > need + 1e-9 : b.High < need - 1e-9) continue;
                        double px = dir > 0 ? Math.Min(level, b.Open) : Math.Max(level, b.Open), stop = stopOf(px);
                        if (stop > 0) output.Add(Dated(KeystoneLab.Bracket(raw, j, px, dir, tp, stop, close, sym, false, be, partial)));
                        break;
                    }
                }
            }
            return output.OrderBy(t => t.EntryTime).ToList();
        }

        // Pick from the candidates in time order: BUY / SELL = that side only, EITHER = both sides but never against an open
        // trade (a sell waits until every open buy is done). Each taken setup goes to the next free account (round robin);
        // with every account busy the setup is skipped. slots[i] = the account (0-based) of the i-th taken trade.
        public static List<KeystoneLabTrade> Rotate(List<KeystoneLabTrade> candidates, string dir, int accounts, List<int> slots)
        {
            return Rotate(candidates, dir, accounts, slots, 1, 0, 0);
        }

        // dayTarget / dayStop ($, 0 = off, at qty contracts): an account that has banked +dayTarget (or lost dayStop) today takes no
        // more setups until the next session; the setup goes to the next free account instead.
        public static List<KeystoneLabTrade> Rotate(List<KeystoneLabTrade> candidates, string dir, int accounts, List<int> slots, int qty, double dayTarget, double dayStop)
        {
            var taken = new List<KeystoneLabTrade>(); var open = new List<Tuple<KeystoneLabTrade, int>>(); int next = 0; accounts = Math.Max(1, accounts);
            var today = new List<Tuple<KeystoneLabTrade, int>>(); DateTime day = DateTime.MinValue;
            foreach (var t in candidates)
            {
                if ((dir == "BUY" && t.Dir < 0) || (dir == "SELL" && t.Dir > 0)) continue;
                if (t.Day != day) { day = t.Day; today.Clear(); }
                open.RemoveAll(o => o.Item1.ExitTime < t.EntryTime);
                if (open.Any(o => o.Item1.Dir != t.Dir) || open.Count >= accounts) continue;
                for (int s = 0; s < accounts; s++)
                {
                    int slot = (next + s) % accounts; if (open.Any(o => o.Item2 == slot)) continue;
                    if (dayTarget > 0 || dayStop > 0)
                    {
                        double banked = today.Where(o => o.Item2 == slot && o.Item1.ExitTime < t.EntryTime).Sum(o => o.Item1.Net) * Math.Max(1, qty);
                        if ((dayTarget > 0 && banked >= dayTarget) || (dayStop > 0 && banked <= -dayStop)) continue;
                    }
                    today.Add(Tuple.Create(t, slot));
                    taken.Add(t); slots.Add(slot); open.Add(Tuple.Create(t, slot)); next = slot + 1; break;
                }
            }
            return taken;
        }

        public static List<KeystoneLabRow> Run(KeystoneIdea idea, List<KeystoneArcBar> oneMinute, KeystonePropRules rules, Action<int, int> progress, Func<bool> cancelled, out DateTime first, out DateTime last, out DateTime split, out int days)
        {
            var rows = new List<KeystoneLabRow>(); first = last = split = DateTime.MinValue; days = 0;
            var raws = (oneMinute ?? new List<KeystoneArcBar>()).GroupBy(b => (b.Symbol ?? "").ToUpperInvariant()).Where(g => idea.Symbols.Contains(g.Key)).ToDictionary(g => g.Key, g => g.OrderBy(b => b.Time).ToList());
            if (raws.Count == 0) return rows;
            var dates = raws.Values.SelectMany(l => l.Select(b => SessionDay(b.Time.AddMinutes(-1)))).Distinct().OrderBy(d => d).ToList();
            first = dates[0]; last = dates[dates.Count - 1]; split = dates[Math.Min(dates.Count - 1, (int)(dates.Count * 0.7))]; days = dates.Count;
            DateTime sp = split; Func<string, int, double> tpOf = (s, a) => s == "MGC" ? idea.MgcTp[a] : idea.MnqTp[a], slOf = (s, b) => s == "MGC" ? idea.MgcSl[b] : idea.MnqSl[b], gapOf = (s, g) => s == "MGC" ? idea.MgcGap[g] : idea.MnqGap[g];
            Func<string, int> nTp = s => s == "MGC" ? idea.MgcTp.Count : idea.MnqTp.Count, nSl = s => s == "MGC" ? idea.MgcSl.Count : idea.MnqSl.Count, nGap = s => !idea.IsFvg ? 1 : s == "MGC" ? idea.MgcGap.Count : idea.MnqGap.Count;
            // one job = one candidate trade list: sym, time or window, range / candle minutes, fill, direction (AT/ORB/FADE only), gap, tp, sl
            var jobs = new List<int[]>(); var syms = raws.Keys.OrderByDescending(s => s == "MNQ").ToList(); var fills = idea.IsFvg ? idea.Fills : new List<string> { "" };
            Func<string, int, double> beOf = (s, e) => s == "MGC" ? idea.MgcBe[e] : idea.MnqBe[e], partOf = (s, e) => s == "MGC" ? idea.MgcPartial[e] : idea.MnqPartial[e];
            for (int s = 0; s < syms.Count; s++)
                for (int t = 0; t < (idea.IsFvg ? idea.Windows.Count : idea.Times.Count); t++) for (int r = 0; r < idea.Ranges.Count; r++) for (int f = 0; f < fills.Count; f++)
                    for (int d = 0; d < (idea.IsFvg ? 1 : idea.Dirs.Count); d++) for (int g = 0; g < nGap(syms[s]); g++)
                        for (int a = 0; a < nTp(syms[s]); a++) for (int b = 0; b < nSl(syms[s]); b++) for (int e = 0; e < idea.MnqBe.Count; e++) for (int pa = 0; pa < idea.MnqPartial.Count; pa++)
                            jobs.Add(new[] { s, t, r, f, d, g, a, b, e, pa });
            var res = new List<KeystoneLabTrade>[jobs.Count]; int done = 0;
            System.Threading.Tasks.Parallel.For(0, jobs.Count, (i, state) =>
            {
                if (cancelled != null && cancelled()) { state.Stop(); return; }
                var j = jobs[i]; string sym = syms[j[0]];
                res[i] = idea.IsFvg
                    ? FvgTrades(raws[sym], sym, idea.Ranges[j[2]], fills[j[3]], idea.Windows[j[1]].Item2, idea.Windows[j[1]].Item3, idea.ExitSet ? idea.Exit : -1, gapOf(sym, j[5]), tpOf(sym, j[6]), slOf(sym, j[7]), beOf(sym, j[8]), partOf(sym, j[9]), idea.Strict)
                    : Trades(raws[sym], sym, idea.Times[j[1]], idea.Entry, idea.Ranges[j[2]], idea.Dirs[j[4]], tpOf(sym, j[6]), slOf(sym, j[7]), idea.Exit, beOf(sym, j[8]), partOf(sym, j[9]));
                int c = System.Threading.Interlocked.Increment(ref done); if (progress != null) progress(c, jobs.Count);
            });
            Func<int, string> entryName = r => idea.Entry == "AT" ? "AT" : idea.IsFvg ? "FVG " + r + "M" : idea.Entry + " " + r + "M";
            Func<string, string> fillName = f => f == "CLOSE" ? " CLOSE" : f == "BREAK" ? " CLOSE+BREAK" : " " + f + "%" + (idea.Strict ? " STRICT" : "");
            bool showBe = idea.MnqBe.Count > 1 || idea.MnqBe[0] > 0, showPartial = idea.MnqPartial.Count > 1 || idea.MnqPartial[0] > 0, showDay = idea.IsFvg && (idea.DayTarget.Count > 1 || idea.DayStop.Count > 1 || idea.DayTarget[0] > 0 || idea.DayStop[0] > 0);
            var dayLimits = idea.DayTarget.SelectMany(a => idea.DayStop.Select(b => Tuple.Create(a, b))).ToList();
            for (int i = 0; i < jobs.Count; i++)
            {
                if (res[i] == null || res[i].Count == 0) continue; var j = jobs[i]; string sym = syms[j[0]];
                double tp = tpOf(sym, j[6]), sl = slOf(sym, j[7]);
                foreach (string dir in idea.IsFvg ? idea.Dirs : new List<string> { idea.Dirs[j[4]] })
                    foreach (int n in idea.Accounts)
                        foreach (int q in idea.Qty)
                        foreach (var lim in idea.IsFvg ? dayLimits : new List<Tuple<double, double>> { Tuple.Create(0.0, 0.0) })
                        {
                            var slots = new List<int>(); var picked = idea.IsFvg ? Rotate(res[i], dir, n, slots, q, lim.Item1, lim.Item2) : res[i];
                            if (picked.Count == 0) continue;
                            var r = new KeystoneLabRow();
                            r.Settings.Add(Tuple.Create("INSTRUMENT", sym));
                            r.Settings.Add(idea.IsFvg ? Tuple.Create("SESSION", idea.Windows[j[1]].Item1) : Tuple.Create("TIME", idea.Times[j[1]].ToString("0000")));
                            r.Settings.Add(Tuple.Create("ENTRY", entryName(idea.Ranges[j[2]]) + (idea.IsFvg ? fillName(fills[j[3]]) : "")));
                            r.Settings.Add(Tuple.Create("DIRECTION", dir));
                            if (idea.IsFvg) r.Settings.Add(Tuple.Create("GAP", "GAP " + Pts(gapOf(sym, j[5]))));
                            r.Settings.Add(Tuple.Create("TARGET", "TP " + Pts(tp))); r.Settings.Add(Tuple.Create("STOP", StopName(sl)));
                            if (showBe) r.Settings.Add(Tuple.Create("BREAKEVEN", beOf(sym, j[8]) > 0 ? "BE +" + Pts(beOf(sym, j[8])) : "NO BE"));
                            if (showPartial) r.Settings.Add(Tuple.Create("PARTIAL", partOf(sym, j[9]) > 0 && partOf(sym, j[9]) < tp ? "HALF +" + Pts(partOf(sym, j[9])) : "NO PARTIAL"));
                            if (idea.IsFvg) r.Settings.Add(Tuple.Create("ACCOUNTS", n == 1 ? "1 ACCOUNT" : n + " ACCOUNTS"));
                            if (showDay) r.Settings.Add(Tuple.Create("DAY LIMIT", (lim.Item1 > 0 ? "+$" + lim.Item1.ToString("0") : "NO TARGET") + " / " + (lim.Item2 > 0 ? "−$" + lim.Item2.ToString("0") : "NO STOP")));
                            r.Settings.Add(Tuple.Create("CONTRACTS", q + "x"));
                            r.Trades = q == 1 ? picked : picked.Select(t => KeystoneLab.Scale(t, q)).ToList();
                            if (idea.IsFvg && n > 1) { r.Rotate = n; r.Slots = slots; }
                            r.PairKey = string.Join("|", j[1], j[2], j[3], dir, j[5], j[6], j[7], j[8], j[9], n, q, lim.Item1, lim.Item2);
                            KeystoneLab.Fill(r, rules, sp, false, 0);
                            rows.Add(r);
                        }
            }
            // BOTH: MNQ + MGC with the same time/session, entry, direction, accounts and the same position in the gap / target / stop lists
            if (raws.Count == 2)
                foreach (var g in rows.Where(r => r.Get("INSTRUMENT") == "MNQ").ToList())
                {
                    var m = rows.FirstOrDefault(r => r.Get("INSTRUMENT") == "MGC" && r.PairKey == g.PairKey); if (m == null) continue;
                    var b = new KeystoneLabRow { PairKey = g.PairKey, Rotate = g.Rotate };
                    foreach (var s in g.Settings)
                    {
                        string v = s.Item2, mv = m.Get(s.Item1);
                        if (s.Item1 == "INSTRUMENT") v = "BOTH";
                        else if (s.Item1 == "TARGET" || s.Item1 == "STOP" || s.Item1 == "GAP" || s.Item1 == "BREAKEVEN" || s.Item1 == "PARTIAL") v = v == mv ? v : v + " / " + mv.Replace("TP ", "").Replace("SL ", "").Replace("GAP ", "").Replace("BE +", "").Replace("HALF +", "");
                        b.Settings.Add(Tuple.Create(s.Item1, v));
                    }
                    var both = g.Trades.Select((t, k) => Tuple.Create(t, g.Slots.Count > k ? g.Slots[k] : 0)).Concat(m.Trades.Select((t, k) => Tuple.Create(t, m.Slots.Count > k ? m.Slots[k] : 0))).OrderBy(x => x.Item1.EntryTime).ToList();
                    b.Trades = both.Select(x => x.Item1).ToList(); if (b.Rotate > 1) b.Slots = both.Select(x => x.Item2).ToList();
                    KeystoneLab.Fill(b, rules, sp, false, 0);
                    rows.Add(b);
                }
            return rows.OrderByDescending(r => r.P.Net).ThenByDescending(r => r.P.PropNet).ToList();
        }

        // How far price went our way before it turned: on the losing trades (they reached the stop or closed red) how many were
        // first well in profit — the case for a breakeven stop or a partial — and the typical best move of all trades.
        public static string Reversal(KeystoneLabRow r)
        {
            var t = r.Trades.Where(x => !double.IsNaN(x.Target) && x.Target != x.Entry).ToList(); if (t.Count < 20) return null;
            Func<KeystoneLabTrade, double> best = x => x.Best / Math.Max(1e-9, KeystoneMoveStudy.PointValue(x.Symbol) * Math.Max(1, x.Qty)), tgt = x => Math.Abs(x.Target - x.Entry);
            var losers = t.Where(x => x.Net <= 0).ToList(); if (losers.Count == 0) return "no losing trades";
            double half = losers.Count(x => best(x) >= 0.5 * tgt(x)) * 100.0 / losers.Count, quarter = losers.Count(x => best(x) >= 0.25 * tgt(x)) * 100.0 / losers.Count;
            var lb = losers.Select(best).OrderBy(v => v).ToList(); double med = lb[lb.Count / 2], tp = t.Select(tgt).OrderBy(v => v).ElementAt(t.Count / 2);
            return quarter.ToString("0") + "% of the " + losers.Count + " losing trades were first +" + Pts(0.25 * tp) + " pts (¼ of the target) in profit, " + half.ToString("0") + "% were +" + Pts(0.5 * tp) + " (½) • median best move of a loser +" + Pts(med) + " pts"
                + (half >= 30 ? " → a breakeven or a partial near +" + Pts(Math.Round(0.5 * tp, 1)) + " is worth testing (BE / PARTIAL)" : quarter < 20 ? " → losers rarely go our way first: breakeven would not help much" : "");
        }

        // How busy a row is: trades per trading day, per account, and the average win / loss.
        public static string Pace(KeystoneLabRow r)
        {
            int days = r.Trades.Select(t => t.Day.Date).Distinct().Count(); if (days == 0) return "no trades";
            double perDay = r.Trades.Count / (double)days; int n = Math.Max(1, r.Rotate);
            return perDay.ToString("0.0", CultureInfo.InvariantCulture) + " trades a day on the days it traded" + (n > 1 ? " (" + (perDay / n).ToString("0.0", CultureInfo.InvariantCulture) + " per account × " + n + " accounts)" : "")
                + ", avg win " + (r.AvgWin < 0 ? "−$" : "$") + Math.Abs(r.AvgWin).ToString("N0", CultureInfo.InvariantCulture) + " / avg loss −$" + Math.Abs(r.AvgLoss).ToString("N0", CultureInfo.InvariantCulture);
        }

        public static List<string> Advice(List<KeystoneLabRow> rows)
        {
            var lines = new List<string>(); if (rows.Count == 0) return lines;
            Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            foreach (string inst in rows.Select(r => r.Get("INSTRUMENT")).Distinct().OrderBy(x => x))
            {
                var q = rows.Where(r => r.Get("INSTRUMENT") == inst).ToList();
                var best = q.OrderByDescending(r => r.P.Net).First(); var prop = q.OrderByDescending(r => r.P.PropNet).First();
                lines.Add(inst + " • MOST MONEY: " + best.Label + " → " + m(best.P.Net) + " (" + best.Trades.Count + " trades, " + Pace(best) + ", worst drawdown " + m(best.P.MaxDrawdown) + ") • by year " + string.Join(" ", best.P.NetByYear.OrderBy(k => k.Key).Select(k => k.Key + " " + m(k.Value))));
                lines.Add(inst + " • MOST MONEY FOR PROP: " + prop.Label + " → " + m(prop.P.PropNet) + " (" + prop.P.Passed + " passed / " + prop.P.Bought + ", " + prop.P.Payouts + " payouts" + (prop.P.Stats.HasPayout ? ", 1st payout " + prop.P.Stats.CalendarDaysToFirstPayout + " d" : "") + " • " + Pace(prop) + ")");
                foreach (string key in new[] { "DIRECTION", "SESSION", "TIME", "ENTRY", "GAP", "ACCOUNTS" })
                {
                    var groups = q.GroupBy(r => r.Get(key)).Where(g => g.Key != string.Empty).OrderBy(g => g.Key).ToList(); if (groups.Count < 2 && key != "DIRECTION") continue;
                    foreach (var g in groups)
                    {
                        var b = g.OrderByDescending(r => r.P.Net).First(); var bp = g.OrderByDescending(r => r.P.PropNet).First(); var med = g.Select(r => r.P.Net).OrderBy(v => v).ToList();
                        lines.Add(inst + " • " + key + " " + g.Key + ": best plain " + m(b.P.Net) + " (" + b.Get("TARGET") + ", " + b.Get("STOP") + ") • best prop " + m(bp.P.PropNet) + " • median row " + m(med[med.Count / 2]) + " • " + g.Count(r => r.P.Net > 0) + "/" + g.Count() + " rows made money");
                    }
                }
                var robust = q.Where(r => r.P.Net > 0 && r.InSampleNet > 0 && r.OutSampleNet > 0 && r.P.NetByYear.Count > 0 && r.P.NetByYear.Values.All(v => v > 0)).OrderByDescending(r => r.P.Net).FirstOrDefault();
                var rev = Reversal(best); if (rev != null) lines.Add(inst + " • BEFORE THE REVERSAL (" + best.Label + "): " + rev);
                lines.Add(robust != null ? inst + " • STRONGEST (money EVERY year and in both halves): " + robust.Label + " → " + m(robust.P.Net) + " plain, " + m(robust.P.PropNet) + " prop" : inst + " • No row made money in every year — this idea is not proven for " + inst + ".");
            }
            if (rows.Any(r => r.Rotate > 1)) lines.Add("ACCOUNTS n: every account is its own evaluation → funded life with only the setups it was given; the prop numbers add the accounts up. The plain-account numbers are every trade on one account.");
            return lines;
        }
    }

    // ---- GENERIC MATH LAB pieces (one trade list per setting row → plain account, prop accounts, years, walk-forward) ----
    public sealed class KeystoneLabTrade { public DateTime Day, EntryTime, ExitTime; public string Symbol = string.Empty, Outcome = string.Empty; public double Entry, Exit, Points, Net, Worst, Best, Target, Stop; public int Qty = 1, Dir = 1; }

    public sealed class KeystoneLabRow
    {
        public List<Tuple<string, string>> Settings = new List<Tuple<string, string>>();
        public List<KeystoneLabTrade> Trades = new List<KeystoneLabTrade>(); public KeystoneMicroRow P = new KeystoneMicroRow();
        public int Wins, Losses, Closes, YearsUp, Years; public double InSampleNet, OutSampleNet, AvgWin, AvgLoss;
        public int Rotate; public List<int> Slots = new List<int>(); public string PairKey = string.Empty;   // IDEAS: n accounts in rotation, the account of each trade
        public string Get(string k) { var t = Settings.FirstOrDefault(x => x.Item1 == k); return t == null ? string.Empty : t.Item2; }
        public string Label { get { return string.Join(" • ", Settings.Select(s => s.Item2)); } }
        public string GroupKey(params string[] except) { return string.Join("|", Settings.Where(s => !except.Contains(s.Item1)).Select(s => s.Item2)); }
    }

    public sealed class KeystoneLabWalkYear { public int Year; public KeystoneLabRow Chosen, Hindsight; public double ChosenPlain, ChosenProp, HindProp; public int ChosenPassed, ChosenPayouts, Trades; }
    public sealed class KeystoneLabWalk { public List<KeystoneLabWalkYear> Years = new List<KeystoneLabWalkYear>(); public KeystoneMicroRow Adaptive = new KeystoneMicroRow(), BestFixed; public KeystoneLabRow BestFixedRow; public int Lookback, YearsUp; }

    public static class KeystoneLab
    {
        // One prop day from its trades. The worst (best) open point of the day follows the real path: what was already banked
        // before a trade started plus the worst (best) points of every trade open at the same time — not the sum of every trade's
        // worst point, which would pretend 30 scalps all hit their low at the same moment.
        public static KeystonePropDay Day(DateTime day, List<KeystoneLabTrade> l)
        {
            double worst = 0, best = 0;
            foreach (var k in l)
            {
                double banked = 0, w = 0, b = 0;
                foreach (var j in l)
                {
                    if (j.ExitTime <= k.EntryTime && j != k && j.ExitTime != DateTime.MinValue) banked += j.Net;
                    else if (j.EntryTime <= k.EntryTime && (j.ExitTime > k.EntryTime || j == k || j.ExitTime == DateTime.MinValue)) { w += j.Worst; b += j.Best; }
                }
                worst = Math.Min(worst, banked + w); best = Math.Max(best, banked + b);
            }
            return new KeystonePropDay { Day = day, Pnl = l.Sum(t => t.Net), Worst = Math.Min(0, worst), Best = Math.Max(0, best), Traded = true };
        }

        public static KeystoneMicroRow Prop(IEnumerable<KeystoneLabTrade> trades, KeystonePropRules rules, bool detail, int randomLives)
        {
            var p = new KeystoneMicroRow();
            p.Days = trades.GroupBy(t => t.Day.Date).OrderBy(g => g.Key).Select(g => Day(g.Key, g.ToList())).ToList();
            p.Trades = trades.Count(); p.Wins = trades.Count(t => t.Net > 0);
            KeystoneMicroADay.FillDays(p, rules, randomLives, 1, 1, detail);
            return p;
        }

        public static void Fill(KeystoneLabRow r, KeystonePropRules rules, DateTime splitAt, bool detail, int randomLives)
        {
            r.P = Prop(r.Trades, rules, detail, randomLives); r.P.Direction = "LAB"; r.P.Instruments = r.Get("INSTRUMENT"); r.P.TakeProfit = r.Label;
            r.Wins = r.Trades.Count(t => t.Outcome == "TARGET"); r.Losses = r.Trades.Count(t => t.Outcome == "STOP"); r.Closes = r.Trades.Count(t => t.Outcome == "CLOSE");
            var w = r.Trades.Where(t => t.Net > 0).ToList(); var l = r.Trades.Where(t => t.Net <= 0).ToList(); r.AvgWin = w.Count == 0 ? 0 : w.Average(t => t.Net); r.AvgLoss = l.Count == 0 ? 0 : l.Average(t => t.Net);
            r.InSampleNet = r.Trades.Where(t => t.Day < splitAt).Sum(t => t.Net); r.OutSampleNet = r.Trades.Where(t => t.Day >= splitAt).Sum(t => t.Net);
            r.Years = r.P.PropByYear.Count; r.YearsUp = r.P.PropByYear.Values.Count(v => v > 0);
            if (r.Rotate > 1 && r.Slots.Count == r.Trades.Count) { Rotation(r, rules, detail); r.Years = r.P.PropByYear.Count; r.YearsUp = r.P.PropByYear.Values.Count(v => v > 0); }
        }

        // ROTATION: account k is its own evaluation → funded life with only the trades given to it (r.Slots); the prop numbers,
        // accounts, ledger and first-payout stats are the sum of the accounts on one shared calendar.
        static void Rotation(KeystoneLabRow r, KeystonePropRules rules, bool detail)
        {
            var p = r.P; var all = r.Trades.Select(t => t.Day.Date).Distinct().OrderBy(d => d).ToList(); if (all.Count == 0) return;
            var pos = new Dictionary<DateTime, int>(); for (int i = 0; i < all.Count; i++) pos[all[i]] = i;
            p.Bought = p.Passed = p.Payouts = p.FundedLost = 0; p.Spent = p.Cash = 0; p.PropByYear = new Dictionary<int, double>(); p.PassRate = p.ValuePerEval = p.AvgDaysToPass = p.FundedValue = 0;
            var ledger = all.Select(d => new KeystoneMicroLedger { Day = d }).ToList(); var curve = new double[all.Count]; var accounts = new List<KeystoneMicroAccount>();
            var plan = new KeystonePropPlan { Source = "REAL", EvalSize = 1, FundSize = 1 };
            for (int s = 0; s < r.Rotate; s++)
            {
                var byDay = Enumerable.Range(0, r.Trades.Count).Where(i => r.Slots[i] == s).Select(i => r.Trades[i]).GroupBy(t => t.Day.Date).ToDictionary(g => g.Key, g => g.ToList());
                if (byDay.Count == 0) continue;
                int start = pos[byDay.Keys.Min()];
                var days = all.Skip(start).Select(d => { List<KeystoneLabTrade> l; return byDay.TryGetValue(d, out l) ? Day(d, l) : new KeystonePropDay { Day = d, Traded = false }; }).ToList();
                foreach (var y in KeystonePropPlanner.History(rules, plan, days))
                { p.Bought += y.Bought; p.Passed += y.Passed; p.Payouts += y.Payouts; p.FundedLost += y.Blown; p.Spent += y.Spent; p.Cash += y.Cash; double v; p.PropByYear.TryGetValue(y.Year, out v); p.PropByYear[y.Year] = v + y.Net; }
                var c = new List<Tuple<DateTime, double>>(); var L = new List<KeystoneMicroLedger>();
                foreach (var a in KeystoneMicroADay.Accounts(rules, days, c, L))
                { a.No = accounts.Count + 1; a.BoughtIndex += start; if (a.PassedIndex >= 0) a.PassedIndex += start; for (int k = 0; k < a.PayoutIndexes.Count; k++) a.PayoutIndexes[k] += start; accounts.Add(a); }
                for (int j = 0; j < L.Count; j++)
                {
                    var g = ledger[start + j]; var x = L[j];
                    g.Pnl += x.Pnl; g.Cash += x.Cash; g.Spent += x.Spent; g.Bought += x.Bought; g.Passed += x.Passed; g.Payouts += x.Payouts; g.Lost += x.Lost; g.Failed += x.Failed;
                    curve[start + j] += c[j].Item2;
                }
                double lastC = c.Count > 0 ? c[c.Count - 1].Item2 : 0; for (int j = start + L.Count; j < all.Count; j++) curve[j] += lastC;
            }
            p.Stats = KeystoneMicroADay.Stats(accounts, ledger); p.MoneyNeeded = Math.Max(0, -curve.DefaultIfEmpty(0).Min());
            if (detail) { p.Accounts = accounts; p.Ledger = ledger; p.PropCurve = all.Select((d, i) => Tuple.Create(d, curve[i])).ToList(); }
            else { p.Accounts = new List<KeystoneMicroAccount>(); p.Ledger = new List<KeystoneMicroLedger>(); p.PropCurve = new List<Tuple<DateTime, double>>(); }
        }

        public static int Blowups(KeystoneLabRow r) { return Math.Max(0, r.P.Bought - r.P.Passed - 1) + r.P.FundedLost; }

        public static KeystoneLabTrade Scale(KeystoneLabTrade t, int q) { return new KeystoneLabTrade { Day = t.Day, EntryTime = t.EntryTime, ExitTime = t.ExitTime, Symbol = t.Symbol, Outcome = t.Outcome, Entry = t.Entry, Exit = t.Exit, Points = t.Points, Net = t.Net * q, Worst = t.Worst * q, Best = t.Best * q, Qty = q, Dir = t.Dir, Target = t.Target, Stop = t.Stop }; }

        // One bracket trade from 1-minute bars, long (dir 1) or short (dir −1): target, stop or the close. A minute touching both
        // counts as the stop; a gap through the stop fills at the open. fillMinuteCanTarget = false for limit fills (the minute's
        // favourable extreme may have come before the fill).
        public static KeystoneLabTrade Bracket(List<KeystoneArcBar> raw, int idx, double entry, int dir, double target, double stop, DateTime close, string symbol, bool fillMinuteCanTarget)
        {
            return Bracket(raw, idx, entry, dir, target, stop, close, symbol, fillMinuteCanTarget, 0, 0);
        }

        // be > 0: once price has gone be points our way, the stop moves to the entry (from the next minute on).
        // partial > 0 (below the target): half the position is taken off at +partial points; the other half runs to the target,
        // the stop (or the entry after a breakeven move) or the close. A minute touching the stop and a profit level = the stop.
        public static KeystoneLabTrade Bracket(List<KeystoneArcBar> raw, int idx, double entry, int dir, double target, double stop, DateTime close, string symbol, bool fillMinuteCanTarget, double be, double partial)
        {
            double pv = KeystoneMoveStudy.PointValue(symbol), tp = entry + dir * target, sl = entry - dir * stop, mae = 0, mfe = 0; var t = new KeystoneLabTrade { Symbol = symbol, Entry = entry, EntryTime = raw[idx].Time, Day = raw[idx].Time.Date, Dir = dir, Target = tp, Stop = stop >= 1e8 ? double.NaN : sl };
            bool half = partial > 0 && partial < target, halfTaken = false;
            for (int i = idx; i < raw.Count && raw[i].Time <= close; i++)
            {
                var b = raw[i]; bool fill = i == idx; double adverse = dir > 0 ? b.Low : b.High, favour = dir > 0 ? b.High : b.Low;
                if (dir > 0 ? adverse <= sl + 1e-9 : adverse >= sl - 1e-9)
                {
                    bool gap = !fill && (dir > 0 ? b.Open < sl : b.Open > sl);
                    t.Exit = gap ? b.Open : sl; t.ExitTime = b.Time; t.Outcome = "STOP"; mae = Math.Max(mae, dir * (entry - t.Exit)); break;
                }
                mae = Math.Max(mae, dir * (entry - adverse));
                bool canFavour = fillMinuteCanTarget || !fill;
                if (canFavour && half && !halfTaken && dir * (favour - entry) >= partial - 1e-9) halfTaken = true;
                if (canFavour && (dir > 0 ? favour >= tp - 1e-9 : favour <= tp + 1e-9)) { t.Exit = tp; t.ExitTime = b.Time; t.Outcome = "TARGET"; mfe = Math.Max(mfe, target); break; }
                if (canFavour) mfe = Math.Max(mfe, dir * (favour - entry));
                if (be > 0 && canFavour && dir * (favour - entry) >= be - 1e-9) sl = dir > 0 ? Math.Max(sl, entry) : Math.Min(sl, entry);
                t.Exit = b.Close; t.ExitTime = b.Time; t.Outcome = "CLOSE";
            }
            if (t.Outcome == "") { t.Exit = entry; t.ExitTime = t.EntryTime; t.Outcome = "CLOSE"; }
            t.Points = halfTaken ? 0.5 * partial + 0.5 * dir * (t.Exit - entry) : dir * (t.Exit - entry); t.Net = t.Points * pv - KeystoneMoveStudy.Cost(symbol); t.Worst = -mae * pv; t.Best = mfe * pv;
            return t;
        }

        public sealed class Impact { public string Setting = string.Empty, Value = string.Empty; public int Rows, Profitable; public double Median, Best, MedianPlain, AvgFirstPayoutDays, AvgBlowups; }
        public static List<Impact> Impacts(List<KeystoneLabRow> rows)
        {
            var output = new List<Impact>(); if (rows.Count == 0) return output;
            foreach (string key in rows[0].Settings.Select(s => s.Item1))
            {
                var groups = rows.GroupBy(r => r.Get(key)).ToList(); if (groups.Count < 2) continue;
                foreach (var g in groups)
                {
                    var nets = g.Select(r => r.P.PropNet).OrderBy(v => v).ToList(); var plain = g.Select(r => r.P.Net).OrderBy(v => v).ToList(); var paid = g.Where(r => r.P.Stats.HasPayout).ToList();
                    output.Add(new Impact { Setting = key, Value = g.Key, Rows = nets.Count, Profitable = nets.Count(v => v > 0), Median = nets[nets.Count / 2], Best = nets[nets.Count - 1], MedianPlain = plain[plain.Count / 2], AvgFirstPayoutDays = paid.Count == 0 ? 0 : paid.Average(r => (double)r.P.Stats.CalendarDaysToFirstPayout), AvgBlowups = g.Average(r => (double)Blowups(r)) });
                }
            }
            return output;
        }

        // Each year: the row that did best on the earlier years only (prop, then plain) — traded that year. Never looks ahead.
        public static KeystoneLabWalk WalkForward(List<KeystoneLabRow> rows, KeystonePropRules rules, int lookback, Func<KeystoneLabRow, bool> filter = null)
        {
            var w = new KeystoneLabWalk { Lookback = lookback }; var pool = rows.Where(r => filter == null || filter(r)).ToList(); if (pool.Count == 0) return w;
            var years = pool.SelectMany(r => r.Trades).Select(t => t.Day.Year).Distinct().OrderBy(y => y).ToList();
            var stitched = new List<KeystoneLabTrade>();
            foreach (int y in years.Skip(1))
            {
                int from = lookback <= 0 ? years[0] : y - lookback;
                var scored = pool.Select(r => new { r, Train = r.Trades.Where(t => t.Day.Year >= from && t.Day.Year < y).ToList(), Test = r.Trades.Where(t => t.Day.Year == y).ToList() }).Where(x => x.Train.Count > 0).ToList();
                if (scored.Count == 0) continue;
                var pick = scored.Select(x => new { x.r, x.Test, P = Prop(x.Train, rules, false, 0) }).OrderByDescending(x => x.P.PropNet).ThenByDescending(x => x.P.Net).First();
                var test = Prop(pick.Test, rules, false, 0);
                var hind = scored.Select(x => new { x.r, P = Prop(x.Test, rules, false, 0) }).OrderByDescending(x => x.P.PropNet).ThenByDescending(x => x.P.Net).First();
                w.Years.Add(new KeystoneLabWalkYear { Year = y, Chosen = pick.r, ChosenPlain = test.Net, ChosenProp = test.PropNet, ChosenPassed = test.Passed, ChosenPayouts = test.Payouts, Trades = pick.Test.Count, Hindsight = hind.r, HindProp = hind.P.PropNet });
                stitched.AddRange(pick.Test);
            }
            w.YearsUp = w.Years.Count(x => x.ChosenProp > 0);
            w.Adaptive = Prop(stitched, rules, true, 0);
            if (w.Years.Count > 0)
            {
                var tested = new HashSet<int>(w.Years.Select(x => x.Year));
                var best = pool.Select(r => new { r, P = Prop(r.Trades.Where(t => tested.Contains(t.Day.Year)), rules, false, 0) }).OrderByDescending(x => x.P.PropNet).First();
                w.BestFixed = best.P; w.BestFixedRow = best.r;
            }
            return w;
        }

        public static string WalkVerdict(KeystoneLabWalk w)
        {
            if (w == null || w.Years.Count == 0) return "Load at least two calendar years: each year's settings are chosen from the years before it.";
            Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            string a = "ADAPTIVE (re-chosen every year from " + (w.Lookback <= 0 ? "all earlier years" : "the last " + w.Lookback + " year" + (w.Lookback == 1 ? "" : "s")) + ", never looking ahead): prop " + m(w.Adaptive.PropNet) + ", plain " + m(w.Adaptive.Net) + ", positive in " + w.YearsUp + " of " + w.Years.Count + " years. ";
            if (w.Adaptive.PropNet > 0 && w.YearsUp * 2 > w.Years.Count) a += "→ It ADAPTS: choosing from the past made money going forward.";
            else if (w.Adaptive.PropNet > 0) a += "→ Made money overall but lost in most years: fragile.";
            else a += "→ It does NOT adapt: what worked before did not work the next year. The RANKING's best rows are hindsight.";
            if (w.BestFixed != null) a += " Best fixed row in hindsight: " + m(w.BestFixed.PropNet) + " (" + w.BestFixedRow.Label + ").";
            return a;
        }
    }

    // ---- FLIP: a small live account from START to GOAL on a tested trade stream (any math-lab row) ----------------------
    // Sizing: RISK % of the balance per trade (contracts = balance × risk ÷ the worst loss one contract had in the stream, at least 1)
    // or FIXED contracts. A trade's worst open loss counts (the account dies intratrade, not only at the close).
    // REPLAY: the whole history in order — at GOAL withdraw (GOAL − START) and restart at START; below BUST re-deposit START.
    // ODDS: from every possible start trade, does it reach GOAL before BUST?
    public sealed class KeystoneFlipRow
    {
        public string Sizing = string.Empty; public double RiskPct; public int Fixed;
        public int Flips, Busts, Trades; public double Withdrawn, Deposited, MaxContracts; public List<double> DaysPerFlip = new List<double>();
        public double ReachPct, BustPct, OpenPct, MedianTradesToGoal, MedianDaysToGoal; public int Starts;
        public double Net { get { return Withdrawn - Deposited; } }
        public double MedianDaysPerFlip { get { if (DaysPerFlip.Count == 0) return 0; var s = DaysPerFlip.OrderBy(v => v).ToList(); return s[s.Count / 2]; } }
    }

    public static class KeystoneFlip
    {
        public sealed class Unit { public DateTime Time; public double Net, Worst; }

        public static List<Unit> Units(IEnumerable<KeystoneLabTrade> trades) { return trades.OrderBy(t => t.EntryTime).Select(t => new Unit { Time = t.EntryTime, Net = t.Net / Math.Max(1, t.Qty), Worst = Math.Min(t.Worst / Math.Max(1, t.Qty), t.Net / Math.Max(1, t.Qty)) }).ToList(); }

        static int Size(double balance, double riskPct, int fixedQty, double unitRisk, int maxQty)
        {
            if (fixedQty > 0) return fixedQty;
            return Math.Max(1, Math.Min(maxQty, (int)Math.Floor(balance * riskPct / 100.0 / Math.Max(1, unitRisk))));
        }

        // One account from trade index i: +1 reached the goal, −1 busted, 0 ran out of data; trades and days used.
        static int From(List<Unit> u, int i, double start, double goal, double bust, double riskPct, int fixedQty, double unitRisk, int maxQty, out int used, out double days, out double maxQ)
        {
            double bal = start; used = 0; days = 0; maxQ = 0;
            for (int k = i; k < u.Count; k++)
            {
                int q = Size(bal, riskPct, fixedQty, unitRisk, maxQty); maxQ = Math.Max(maxQ, q); used++;
                if (bal + q * u[k].Worst <= bust) { days = (u[k].Time - u[i].Time).TotalDays; return -1; }
                bal += q * u[k].Net;
                if (bal <= bust) { days = (u[k].Time - u[i].Time).TotalDays; return -1; }
                if (bal >= goal) { days = (u[k].Time - u[i].Time).TotalDays; return 1; }
            }
            return 0;
        }

        public static KeystoneFlipRow Run(List<Unit> u, double start, double goal, double bust, double riskPct, int fixedQty, int maxQty = 50)
        {
            var row = new KeystoneFlipRow { RiskPct = riskPct, Fixed = fixedQty, Sizing = fixedQty > 0 ? fixedQty + " micro" + (fixedQty == 1 ? "" : "s") + " fixed" : riskPct.ToString("0.#", CultureInfo.InvariantCulture) + "% risk per trade" };
            if (u == null || u.Count == 0 || goal <= start || bust >= start) return row;
            double unitRisk = Math.Max(1, -u.Min(x => x.Worst));
            // replay: flip after flip through the whole history
            int i = 0; row.Deposited = start;
            while (i < u.Count)
            {
                int used; double days, mq; int r = From(u, i, start, goal, bust, riskPct, fixedQty, unitRisk, maxQty, out used, out days, out mq);
                row.MaxContracts = Math.Max(row.MaxContracts, mq); row.Trades += used;
                if (r == 1) { row.Flips++; row.Withdrawn += goal - start; row.DaysPerFlip.Add(days); }
                else if (r == -1) { row.Busts++; row.Deposited += start; }
                else { row.Withdrawn += 0; break; }
                i += Math.Max(1, used);
            }
            // odds from every start (sampled to at most 400 starts)
            int step = Math.Max(1, u.Count / 400); var tToGoal = new List<double>(); var dToGoal = new List<double>(); int reach = 0, bustN = 0, open = 0;
            for (int s = 0; s < u.Count; s += step)
            {
                int used; double days, mq; int r = From(u, s, start, goal, bust, riskPct, fixedQty, unitRisk, maxQty, out used, out days, out mq);
                if (r == 1) { reach++; tToGoal.Add(used); dToGoal.Add(days); } else if (r == -1) bustN++; else open++;
            }
            row.Starts = reach + bustN + open;
            if (row.Starts > 0) { row.ReachPct = 100.0 * reach / row.Starts; row.BustPct = 100.0 * bustN / row.Starts; row.OpenPct = 100.0 * open / row.Starts; }
            if (tToGoal.Count > 0) { tToGoal.Sort(); dToGoal.Sort(); row.MedianTradesToGoal = tToGoal[tToGoal.Count / 2]; row.MedianDaysToGoal = dToGoal[dToGoal.Count / 2]; }
            // the replay deposit: the last account still running is counted as spent (honest), the withdrawn flips as cash
            return row;
        }

        public static List<KeystoneFlipRow> Grid(List<Unit> u, double start, double goal, double bust, IEnumerable<double> riskPcts, IEnumerable<int> fixedQtys)
        {
            var list = new List<KeystoneFlipRow>();
            foreach (double r in riskPcts.Where(x => x > 0).Distinct()) list.Add(Run(u, start, goal, bust, r, 0));
            foreach (int q in fixedQtys.Where(x => x > 0).Distinct()) list.Add(Run(u, start, goal, bust, 0, q));
            return list.OrderByDescending(x => x.Net).ToList();
        }
    }

    // ---- GOLDEN FVG MAP: every bullish FVG on the chart's candles with why it was (not) traded — so detection can be checked by eye ----
    public sealed class KeystoneFvgMapZone { public int C1, C3; public double Low, High; public DateTime Formed; public string Status = string.Empty; public bool Taken; }
    public static class KeystoneGoldenFvgMap
    {
        public static List<KeystoneFvgMapZone> Scan(List<KeystoneArcBar> bars, string symbol, KeystoneArcRunConfig cfg, List<KeystoneArcEvent> taken)
        {
            var output = new List<KeystoneFvgMapZone>(); if (bars == null || bars.Count < 3 || cfg == null) return output;
            bool mgc = (symbol ?? "").StartsWith("MGC", StringComparison.OrdinalIgnoreCase);
            double minGap = Math.Max(0, mgc ? cfg.GoldenMgcMinGap : cfg.GoldenMnqMinGap); int startHhmm = mgc ? cfg.GoldenMgcStart : cfg.GoldenMnqStart;
            var mine = (taken ?? new List<KeystoneArcEvent>()).Where(e => string.Equals(e.Symbol, symbol, StringComparison.OrdinalIgnoreCase) && e.EntryTime != DateTime.MinValue).OrderBy(e => e.EntryTime).ToList();
            for (int i = 2; i < bars.Count; i++)
            {
                var c1 = bars[i - 2]; var c3 = bars[i]; double gap = c3.Low - c1.High; if (gap <= 0) continue;
                DateTime day = KeystoneArcEngine.GoldenSessionDay(c3.Time), start = day.Date.AddHours(startHhmm / 100).AddMinutes(startHhmm % 100), last = day.Date.AddHours(cfg.GoldenLastEntry / 100).AddMinutes(cfg.GoldenLastEntry % 100);
                if (last <= start) last = last.AddDays(1);
                var z = new KeystoneFvgMapZone { C1 = i - 2, C3 = i, Low = c1.High, High = c3.Low, Formed = c3.Time };
                var dayTrades = mine.Where(e => KeystoneArcEngine.GoldenSessionDay(e.EntryTime) == day).ToList();
                var hit = dayTrades.FirstOrDefault(e => e.FvgFormedTime == c3.Time && e.SetupClass != "BH");
                if (hit != null) { z.Taken = true; z.Status = "TAKEN • entry " + hit.EntryTime.ToString("HH:mm"); }
                else if (gap < minGap - 1e-9) z.Status = "GAP " + gap.ToString("0.##", CultureInfo.InvariantCulture) + " < MIN " + minGap.ToString("0.##", CultureInfo.InvariantCulture);
                else if (c1.Time <= start && !(cfg.GoldenFvgOpenCandle == 1 && bars[i - 1].Time > start)) z.Status = "STARTED BEFORE " + (startHhmm / 100).ToString("00") + ":" + (startHhmm % 100).ToString("00") + (cfg.GoldenFvgOpenCandle == 1 ? "" : " (turn on OPENING CANDLE GAP)");
                else if (c3.Time > last) z.Status = "AFTER THE LAST ENTRY TIME";
                else if (dayTrades.Count > 0 && c3.Time >= dayTrades[0].EntryTime && cfg.GoldenTakeAll != 1) z.Status = "AFTER THE DAY'S TRADE (" + Math.Max(1, cfg.GoldenMaxTradesPerDay) + " a day)";
                else if (string.Equals(cfg.GoldenFvgMode, "CLOSE", StringComparison.OrdinalIgnoreCase)) z.Status = "NOT TAKEN • a filter (max stop / aggression / strict first)";
                else if (string.Equals(cfg.GoldenFvgMode, "DIP50", StringComparison.OrdinalIgnoreCase)) z.Status = "NOT TAPPED TO 50% (or closed below the gap first, or a filter)";
                else z.Status = dayTrades.Count > 0 ? "NO RETEST → GREEN CLOSE → BREAK BEFORE THE TRADE" : "NO RETEST → GREEN CLOSE → BREAK (or a filter)";
                output.Add(z);
            }
            return output;
        }
    }

    // ---- GOLDEN → PROP: the GOLDEN study's kept entries through evaluations, funded accounts and payouts ----------------
    // AS TESTED = each trade exactly as the study resolved it (may be held overnight). FLAT BY <close> = a trade still open at the
    // close of its entry day is closed at that minute's 1-minute close (what an intraday prop rule forces). Per 1 micro, × contracts.
    public static class KeystoneGoldenLab
    {
        public static KeystoneLabTrade Unit(KeystoneArcEvent e, bool flat, int closeHhmm, Func<string, DateTime, double?> closeAt)
        {
            if (!KeystoneGoldenStudy.Traded(e)) return null;
            string sym = (e.Symbol ?? "").ToUpperInvariant(); double pv = KeystoneMoveStudy.PointValue(sym), dir = e.Direction == "SHORT" ? -1 : 1;
            DateTime exitT = e.ExitTime; double exit = e.ExitPrice; string outcome = KeystoneGoldenStudy.IsWin(e) ? "TARGET" : KeystoneGoldenStudy.IsLoss(e) ? "STOP" : "CLOSE";
            DateTime close = e.EntryTime.Date.AddHours(closeHhmm / 100).AddMinutes(closeHhmm % 100);
            if (flat && exitT > close && e.EntryTime < close)
            {
                double? c = closeAt == null ? null : closeAt(sym, close);
                if (!c.HasValue) return null;
                exit = c.Value; exitT = close; outcome = "CLOSE";
            }
            double worstPts = double.IsNaN(e.TroughAfterEntry) || double.IsNaN(e.PeakAfterEntry) ? Math.Max(0, -dir * (exit - e.Entry)) : (dir > 0 ? e.Entry - e.TroughAfterEntry : e.PeakAfterEntry - e.Entry);
            var t = new KeystoneLabTrade { Symbol = sym, Day = exitT.Date, EntryTime = e.EntryTime, ExitTime = exitT, Entry = e.Entry, Exit = exit, Outcome = outcome, Qty = 1 };
            t.Points = dir * (exit - e.Entry); t.Net = t.Points * pv - KeystoneMoveStudy.Cost(sym); t.Worst = -Math.Max(0, worstPts) * pv; t.Best = Math.Max(0, dir > 0 ? e.PeakAfterEntry - e.Entry : e.Entry - e.TroughAfterEntry) * pv;
            if (double.IsNaN(t.Best)) t.Best = 0;
            return t;
        }

        public sealed class Grid
        {
            public List<string> Exits = new List<string> { "SAME DAY", "HOLD" };
            public List<double> MnqTargets = new List<double> { 50, 100, 150, 200 }, MgcTargets = new List<double> { 5, 10, 15, 20 };
            public List<double> MnqStops = new List<double> { 0, 50, 100, 150 }, MgcStops = new List<double> { 0, 5, 10, 15 };   // 0 = the PATTERN stop
            public List<int> Contracts = new List<int> { 1, 3, 5 };
            public List<int> PerDay = new List<int> { 1 };      // most trades a day: a win ends the day, a loss allows the next setup
            public List<string> Sides = new List<string> { "BUY" };   // BUY • SELL • EITHER (both, one position at a time)
            public int CloseHhmm = 1555;
        }

        // Every setup of every day (FVG only, BH only, FVG + BH) from the GOLDEN detector with your start times, gap and pattern
        // rules — all of them, not only the first (the replay below decides how many a day are taken).
        public static Dictionary<string, List<KeystoneArcEvent>> Candidates(Dictionary<string, List<KeystoneArcBar>> raws, Dictionary<string, List<KeystoneArcBar>> setups, KeystoneArcRunConfig basis, IEnumerable<string> setupKinds)
        {
            var output = new Dictionary<string, List<KeystoneArcEvent>>();
            foreach (string kind in setupKinds.Distinct())
            {
                var c = KeystoneGoldenStudy.UnfilteredConfig(basis); c.StrategyCode = "GLD"; c.GoldenTakeAll = 1; c.GoldenMaxTradesPerDay = 999; c.GoldenHold = 0;
                if (kind == "BH") { c.GoldenUseBh = 1; c.GoldenFvgMode = "OFF"; }
                else if (kind.StartsWith("FVG50")) { c.GoldenUseBh = kind == "FVG50+BH" ? 1 : 0; c.GoldenFvgMode = "DIP50"; }
                else { c.GoldenUseBh = kind == "FVG+BH" ? 1 : 0; if (string.Equals(c.GoldenFvgMode, "OFF", StringComparison.OrdinalIgnoreCase) || string.Equals(c.GoldenFvgMode, "DIP50", StringComparison.OrdinalIgnoreCase)) c.GoldenFvgMode = "BREAK"; }
                var list = new List<KeystoneArcEvent>();
                foreach (var kv in raws)
                {
                    List<KeystoneArcBar> set; if (!setups.TryGetValue(kv.Key, out set) || set == null || set.Count < 3) continue;
                    var cc = c.ShallowCopy(); cc.Scope = kv.Key;
                    list.AddRange(KeystoneArcEngine.DetectAndResolve(kv.Value, set, cc).Where(e => e.EntryTime != DateTime.MinValue && !double.IsNaN(e.Entry)));
                }
                output[kind] = list.OrderBy(e => e.EntryTime).ToList();
            }
            return output;
        }

        // Each set of entries replayed on its own 1-minute bars for every EXIT × TARGET × STOP × TRADES A DAY (same fill rule as the
        // labs: the entry minute cannot reach the target, a minute touching both = the stop). One position at a time; a win ends the
        // day; after a loss the next setup of the day is taken until the day's limit. SAME DAY = out at the close; HOLD = to the
        // target or the stop (a held trade blocks new entries until it ends).
        public static List<KeystoneLabRow> Rows(Dictionary<string, List<KeystoneArcEvent>> sets, KeystonePropRules rules, Grid g, Dictionary<string, List<KeystoneArcBar>> raws, Action<int, int> progress, Func<bool> cancelled, out DateTime first, out DateTime last, out DateTime split, out int days)
        {
            var rows = new List<KeystoneLabRow>(); first = last = split = DateTime.MinValue; days = 0;
            if (sets == null || raws == null) return rows;
            var all = sets.Values.SelectMany(l => l).Where(e => raws.ContainsKey((e.Symbol ?? "").ToUpperInvariant())).ToList(); if (all.Count == 0) return rows;
            var dates = all.Select(e => e.EntryTime.Date).Distinct().OrderBy(d => d).ToList();
            first = dates[0]; last = dates[dates.Count - 1]; split = dates[Math.Min(dates.Count - 1, (int)(dates.Count * 0.7))]; days = dates.Count;
            var idx = new Dictionary<KeystoneArcEvent, int>();
            foreach (var e in all)
            {
                var raw = raws[e.Symbol.ToUpperInvariant()]; int lo = 0, hi = raw.Count - 1, f = -1;
                while (lo <= hi) { int mid = (lo + hi) / 2; if (raw[mid].Time >= e.EntryTime) { f = mid; hi = mid - 1; } else lo = mid + 1; }
                if (f >= 0 && (raw[f].Time - e.EntryTime).TotalMinutes <= 5) idx[e] = f;
            }
            var jobs = new List<Tuple<string, string, string, double, double, int, string>>();
            bool anySell = all.Any(e => e.Direction == "SHORT"); var sides = anySell ? (g.Sides.Count == 0 ? new List<string> { "BUY" } : g.Sides.Distinct().ToList()) : new List<string> { "BUY" };
            foreach (var set in sets.Keys) foreach (string sym in new[] { "MNQ", "MGC" }) if (raws.ContainsKey(sym) && sets[set].Any(e => e.Symbol == sym))
                foreach (string ex in g.Exits.Distinct()) foreach (double tp in sym == "MGC" ? g.MgcTargets : g.MnqTargets) foreach (double sl in sym == "MGC" ? g.MgcStops : g.MnqStops) foreach (int pd in g.PerDay.Distinct()) foreach (string side in sides)
                    jobs.Add(Tuple.Create(set, sym, ex, tp, sl, Math.Max(1, pd), side));
            var perJob = new List<KeystoneLabTrade>[jobs.Count]; int done = 0;
            System.Threading.Tasks.Parallel.For(0, jobs.Count, (i, state) =>
            {
                if (cancelled != null && cancelled()) { state.Stop(); return; }
                var j = jobs[i]; var raw = raws[j.Item2]; var list = new List<KeystoneLabTrade>(); DateTime busy = DateTime.MinValue;
                foreach (var day in sets[j.Item1].Where(x => x.Symbol == j.Item2 && (j.Item7 == "EITHER" || (j.Item7 == "SELL") == (x.Direction == "SHORT"))).GroupBy(x => KeystoneArcEngine.GoldenSessionDay(x.EntryTime)).OrderBy(x => x.Key))
                {
                    int count = 0;
                    foreach (var e in day.OrderBy(x => x.EntryTime))
                    {
                        if (count >= j.Item6) break;
                        int k; if (!idx.TryGetValue(e, out k) || e.EntryTime < busy) continue;
                        int dirE = e.Direction == "SHORT" ? -1 : 1;
                        double stopPts = j.Item5 > 0 ? j.Item5 : (double.IsNaN(e.Stop) ? double.NaN : dirE * (e.Entry - e.Stop)); if (double.IsNaN(stopPts) || stopPts <= 0) continue;
                        DateTime close = j.Item3 == "HOLD" ? DateTime.MaxValue : e.EntryTime.Date.AddHours(g.CloseHhmm / 100).AddMinutes(g.CloseHhmm % 100);
                        if (e.EntryTime >= close) continue;
                        var t = KeystoneLab.Bracket(raw, k, e.Entry, dirE, j.Item4, stopPts, close, j.Item2, false);
                        t.Day = t.ExitTime.Date; list.Add(t); busy = t.ExitTime; count++;
                        if (t.Net > 0) break;                                              // a win ends the day
                    }
                }
                perJob[i] = list;
                int c = System.Threading.Interlocked.Increment(ref done); if (progress != null) progress(c, jobs.Count);
            });
            for (int i = 0; i < jobs.Count; i++)
            {
                if (perJob[i] == null || perJob[i].Count == 0) continue; var j = jobs[i];
                foreach (int q in g.Contracts.Distinct())
                {
                    var r = new KeystoneLabRow();
                    r.Settings.Add(Tuple.Create("INSTRUMENT", j.Item2)); if (anySell) r.Settings.Add(Tuple.Create("DIRECTION", j.Item7)); r.Settings.Add(Tuple.Create("SETUPS", j.Item1)); r.Settings.Add(Tuple.Create("TRADES A DAY", "MAX " + j.Item6 + "/DAY"));
                    r.Settings.Add(Tuple.Create("EXIT", j.Item3));
                    r.Settings.Add(Tuple.Create("TARGET", "TP " + j.Item4.ToString("0.##", CultureInfo.InvariantCulture))); r.Settings.Add(Tuple.Create("STOP", j.Item5 > 0 ? "SL " + j.Item5.ToString("0.##", CultureInfo.InvariantCulture) : "SL PATTERN"));
                    r.Settings.Add(Tuple.Create("CONTRACTS", q + "x"));
                    r.Trades = perJob[i].Select(t => KeystoneLab.Scale(t, q)).ToList();
                    KeystoneLab.Fill(r, rules, split, false, 0);
                    rows.Add(r);
                }
            }
            return rows.OrderByDescending(r => r.P.PropNet).ThenByDescending(r => r.P.Net).ToList();
        }

        public static List<string> Advice(List<KeystoneLabRow> rows, int days)
        {
            var lines = new List<string>(); if (rows.Count == 0) return lines;
            Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            foreach (string inst in rows.Select(r => r.Get("INSTRUMENT")).Distinct().OrderBy(x => x))
            {
                var q = rows.Where(r => r.Get("INSTRUMENT") == inst).ToList();
                var plain = q.OrderByDescending(r => r.P.Net).First(); var prop = q.OrderByDescending(r => r.P.PropNet).First();
                lines.Add(inst + " • MOST MONEY (plain account): " + plain.Label + " → " + m(plain.P.Net) + " • worst drawdown " + m(plain.P.MaxDrawdown) + " • years + " + plain.P.NetByYear.Values.Count(v => v > 0) + "/" + plain.P.NetByYear.Count + " • unseen 30% " + m(plain.OutSampleNet));
                lines.Add(inst + " • MOST MONEY (prop): " + prop.Label + " → " + m(prop.P.PropNet) + " (" + prop.P.Passed + " passed / " + prop.P.Bought + ", " + prop.P.Payouts + " payouts" + (prop.P.Stats.HasPayout ? ", 1st payout " + prop.P.Stats.CalendarDaysToFirstPayout + " d" : "") + ")");
                foreach (string key in new[] { "DIRECTION", "SETUPS", "TRADES A DAY" })
                    foreach (var grp in q.GroupBy(r => r.Get(key)).Where(x => x.Key != string.Empty).OrderBy(x => x.Key))
                    {
                        var bb = grp.OrderByDescending(r => r.P.Net).First(); var md = grp.Select(r => r.P.Net).OrderBy(v => v).ToList();
                        lines.Add(inst + " • " + key + " " + grp.Key + ": best " + m(bb.P.Net) + " plain / " + m(bb.P.PropNet) + " prop (" + bb.Trades.Count + " trades, " + bb.Label + ") • median " + m(md[md.Count / 2]));
                    }
                foreach (string ex in new[] { "SAME DAY", "HOLD" })
                {
                    var b = q.Where(r => r.Get("EXIT") == ex).OrderByDescending(r => r.P.Net).FirstOrDefault(); if (b == null) continue;
                    var med = q.Where(r => r.Get("EXIT") == ex).Select(r => r.P.Net).OrderBy(v => v).ToList();
                    lines.Add(inst + " • " + ex + ": best " + b.Label + " → plain " + m(b.P.Net) + ", prop " + m(b.P.PropNet) + " • median of all " + ex + " rows " + m(med[med.Count / 2]));
                }
                var sd = q.Where(r => r.Get("EXIT") == "SAME DAY").Select(r => r.P.Net).DefaultIfEmpty(double.MinValue).Max(); var hd = q.Where(r => r.Get("EXIT") == "HOLD").Select(r => r.P.Net).DefaultIfEmpty(double.MinValue).Max();
                if (sd > double.MinValue && hd > double.MinValue)
                    lines.Add(hd > sd ? inst + " • HOLD makes more (" + m(hd) + " vs " + m(sd) + ") — but most prop firms require flat at the close; use HOLD on a live account or a firm that allows it." : inst + " • SAME DAY makes as much or more (" + m(sd) + " vs " + m(hd) + ") — good for prop rules.");
                var robust = q.Where(r => r.P.Net > 0 && r.InSampleNet > 0 && r.OutSampleNet > 0 && r.P.NetByYear.Count > 0 && r.P.NetByYear.Values.All(v => v > 0)).OrderByDescending(r => r.P.Net).FirstOrDefault();
                lines.Add(robust != null ? inst + " • STRONGEST (plain profit EVERY year and in both halves): " + robust.Label + " → plain " + m(robust.P.Net) + ", prop " + m(robust.P.PropNet) : inst + " • No row made money in every year — check ADAPTS EACH YEAR? before trusting the best.");
            }
            return lines;
        }
    }

    // ---- 5M FVG MATH LAB: the first 5-minute FVG entries (each style) × target × stop × contracts, MNQ and MGC separately ----
    public sealed class KeystoneFvgLabGrid
    {
        public List<string> Symbols = new List<string> { "MNQ", "MGC" };
        public List<string> Sets = KeystoneFvgEntryStudy.Sets.ToList();
        public List<double> MnqTargets = new List<double> { 50, 75, 100, 150, 200 }, MgcTargets = new List<double> { 5, 7.5, 10, 15, 20 };
        public List<double> MnqStops = new List<double> { 25, 50, 75, 100 }, MgcStops = new List<double> { 2.5, 5, 7.5, 10 };
        public List<int> Contracts = new List<int> { 1, 2, 3 };
        public KeystoneFvgStudyConfig Study = new KeystoneFvgStudyConfig();
        public double InSampleShare = 0.7;
    }

    public sealed class KeystoneFvgLabResult { public List<KeystoneLabRow> Rows = new List<KeystoneLabRow>(); public KeystonePropRules Rules; public DateTime First, Last, SplitAt; public Dictionary<string, int> Entries = new Dictionary<string, int>(); public int Days; public bool Cancelled; }

    public static class KeystoneFvgLab
    {
        public static string Short(string set)
        {
            if (set == KeystoneFvgEntryStudy.Touch) return "TOUCH"; if (set == KeystoneFvgEntryStudy.Dip25) return "25% DIP"; if (set == KeystoneFvgEntryStudy.Dip50) return "50% DIP"; if (set == KeystoneFvgEntryStudy.Break) return "GREEN CLOSE + BREAK";
            if (set == KeystoneFvgEntryStudy.PriorTouch) return "PRIOR FVG TOUCH"; if (set == KeystoneFvgEntryStudy.Prior50) return "PRIOR FVG 50%"; if (set == KeystoneFvgEntryStudy.FirstBh) return "FIRST BH"; return set;
        }

        // One long trade: from the fill minute to the target, the stop or the close. Conservative like the MOVE STUDY: on the fill minute
        // only a stop can be hit (its high may have come before the fill); a minute touching both counts as the stop.
        public static KeystoneLabTrade Trade(List<KeystoneArcBar> raw, int idx, double entry, double target, double stop, DateTime close, string symbol) { return KeystoneLab.Bracket(raw, idx, entry, 1, target, stop, close, symbol, false); }

        public static KeystoneFvgLabResult Run(List<KeystoneArcBar> oneMinute, KeystoneFvgLabGrid g, KeystonePropRules rules, Action<int, int> progress, Func<bool> cancelled)
        {
            var res = new KeystoneFvgLabResult { Rules = rules }; if (oneMinute == null || oneMinute.Count == 0) return res;
            var bars = oneMinute.Where(b => g.Symbols.Contains((b.Symbol ?? "").ToUpperInvariant())).OrderBy(b => b.Time).ToList();
            var raws = bars.GroupBy(b => b.Symbol.ToUpperInvariant()).ToDictionary(x => x.Key, x => x.OrderBy(b => b.Time).ToList());
            var sets = KeystoneFvgEntryStudy.Run(bars, g.Study);
            var days = bars.Select(b => b.Time.Date).Distinct().OrderBy(d => d).ToList(); res.Days = days.Count;
            if (days.Count > 0) { res.First = days[0]; res.Last = days[days.Count - 1]; res.SplitAt = days[Math.Min(days.Count - 1, (int)(days.Count * g.InSampleShare))]; }
            var jobs = new List<Tuple<string, string, double, double>>();
            foreach (string set in g.Sets) foreach (string sym in g.Symbols)
            {
                if (!raws.ContainsKey(sym)) continue;
                List<KeystoneArcEvent> evs; if (!sets.TryGetValue(set, out evs)) continue;
                res.Entries[Short(set) + " • " + sym] = evs.Count(e => e.Symbol == sym);
                foreach (double tp in sym == "MGC" ? g.MgcTargets : g.MnqTargets) foreach (double sl in sym == "MGC" ? g.MgcStops : g.MnqStops) jobs.Add(Tuple.Create(set, sym, tp, sl));
            }
            var outRows = new List<KeystoneLabRow>[jobs.Count]; int done = 0;
            System.Threading.Tasks.Parallel.For(0, jobs.Count, new System.Threading.Tasks.ParallelOptions { MaxDegreeOfParallelism = Math.Max(1, Environment.ProcessorCount - 1) }, (i, state) =>
            {
                if (cancelled != null && cancelled()) { state.Stop(); return; }
                var j = jobs[i]; var raw = raws[j.Item2]; var list = new List<KeystoneLabTrade>();
                foreach (var e in sets[j.Item1].Where(x => x.Symbol == j.Item2).OrderBy(x => x.EntryTime))
                {
                    int lo = 0, hi = raw.Count - 1, idx = -1; while (lo <= hi) { int mid = (lo + hi) / 2; if (raw[mid].Time >= e.EntryTime) { idx = mid; hi = mid - 1; } else lo = mid + 1; }
                    if (idx < 0 || raw[idx].Time != e.EntryTime) continue;
                    DateTime close = e.EntryTime.Date.AddHours(g.Study.Close / 100).AddMinutes(g.Study.Close % 100);
                    list.Add(Trade(raw, idx, e.Entry, j.Item3, j.Item4, close, j.Item2));
                }
                var rows = new List<KeystoneLabRow>();
                foreach (int q in g.Contracts.Distinct())
                {
                    var r = new KeystoneLabRow();
                    r.Settings.Add(Tuple.Create("INSTRUMENT", j.Item2)); r.Settings.Add(Tuple.Create("ENTRY", Short(j.Item1)));
                    r.Settings.Add(Tuple.Create("TARGET", "TP " + j.Item3.ToString("0.##", CultureInfo.InvariantCulture))); r.Settings.Add(Tuple.Create("STOP", "SL " + j.Item4.ToString("0.##", CultureInfo.InvariantCulture)));
                    r.Settings.Add(Tuple.Create("CONTRACTS", q + "x"));
                    r.Trades = list.Select(t => KeystoneLab.Scale(t, q)).ToList();
                    Fill(r, rules, res.SplitAt);
                    rows.Add(r);
                }
                outRows[i] = rows;
                int k = System.Threading.Interlocked.Increment(ref done); if (progress != null) progress(k, jobs.Count);
            });
            res.Cancelled = cancelled != null && cancelled();
            res.Rows = outRows.Where(x => x != null).SelectMany(x => x).Where(r => r.Trades.Count > 0).OrderByDescending(r => r.P.PropNet).ThenByDescending(r => r.P.Net).ToList();
            return res;
        }

        static void Fill(KeystoneLabRow r, KeystonePropRules rules, DateTime splitAt) { KeystoneLab.Fill(r, rules, splitAt, false, 300); }

        public static List<string> Advice(KeystoneFvgLabResult res)
        {
            var lines = new List<string>(); if (res == null || res.Rows.Count == 0) return lines;
            Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            lines.Add(res.Rows.Count(r => r.P.PropNet > 0) + " of " + res.Rows.Count + " rows made money for prop • " + res.Rows.Count(r => r.P.Net > 0) + " on a plain account • " + res.Days + " days (" + res.First.ToString("yyyy-MM-dd") + " → " + res.Last.ToString("yyyy-MM-dd") + ").");
            foreach (string sym in res.Rows.Select(r => r.Get("INSTRUMENT")).Distinct().OrderBy(x => x))
            {
                var q = res.Rows.Where(r => r.Get("INSTRUMENT") == sym).ToList();
                var b = q.OrderByDescending(r => r.P.PropNet).First(); var bp = q.OrderByDescending(r => r.P.Net).First();
                var robust = q.Where(r => r.P.Net > 0 && r.InSampleNet > 0 && r.OutSampleNet > 0 && r.YearsUp == r.Years && r.Years > 0).OrderByDescending(r => r.P.PropNet).FirstOrDefault();
                lines.Add(sym + " • BEST FOR PROP: " + b.Label + " → " + m(b.P.PropNet) + " (" + b.P.Passed + " passed / " + b.P.Bought + ", " + b.P.Payouts + " payouts" + (b.P.Stats.HasPayout ? ", 1st payout " + b.P.Stats.CalendarDaysToFirstPayout + " d" : "") + ") • plain " + m(b.P.Net) + " • win " + (b.Trades.Count == 0 ? 0 : 100.0 * b.Wins / b.Trades.Count).ToString("0") + "% of " + b.Trades.Count);
                lines.Add(sym + " • BEST PLAIN: " + bp.Label + " → " + m(bp.P.Net) + ", early 70% " + m(bp.InSampleNet) + ", unseen 30% " + m(bp.OutSampleNet));
                lines.Add(robust != null ? sym + " • STRONGEST (plain profit in both halves AND prop positive every year): " + robust.Label + " → prop " + m(robust.P.PropNet) + ", plain " + m(robust.P.Net) : sym + " • No row was profitable in both halves and every year — no proven edge yet for " + sym + ".");
                var yours = q.Where(r => r.Get("TARGET") == (sym == "MGC" ? "TP 10" : "TP 100")).OrderByDescending(r => r.P.PropNet).FirstOrDefault();
                if (yours != null) lines.Add(sym + " • YOUR TARGET (" + yours.Get("TARGET") + "): best with it " + yours.Label + " → prop " + m(yours.P.PropNet) + ", plain " + m(yours.P.Net) + " • rank " + (q.IndexOf(yours) + 1) + " of " + q.Count + " for " + sym);
                foreach (var imp in KeystoneLab.Impacts(q).Where(x => x.Setting == "ENTRY").OrderByDescending(x => x.MedianPlain).Take(1))
                    lines.Add(sym + " • the best ENTRY style on the median: " + imp.Value + " (plain median " + m(imp.MedianPlain) + ", prop median " + m(imp.Median) + ")");
            }
            return lines;
        }
    }

    // ---- 123 ENGULFING MATH LAB: every timeframe × BUY / SELL / BOTH × signal strength × run × target × stop × contracts --------
    public sealed class KeystoneEngLabGrid
    {
        public List<string> Symbols = new List<string> { "MNQ", "MGC" };
        public List<int> Timeframes = new List<int> { 1, 5, 15, 30, 60 };
        public List<string> Directions = new List<string> { "BUY", "SELL", "BOTH" };
        public List<string> Strengths = new List<string> { "ALL", "SWEEP+WICK" };   // ALL • WICK (wick or sweep) • SWEEP • SWEEP+WICK
        public List<int> MinRuns = new List<int> { 2 };
        public List<double> MnqTargets = new List<double> { 25, 50, 100 }, MgcTargets = new List<double> { 3, 5, 10 };
        public List<double> MnqStops = new List<double> { 25, 50 }, MgcStops = new List<double> { 3, 5 };
        public List<int> Contracts = new List<int> { 1 };
        public int MnqStart = 930, MgcStart = 800, Close = 1555;
        public double MnqMinBody = 0, MgcMinBody = 0, InSampleShare = 0.7;
    }

    public sealed class KeystoneEngSignal { public string Symbol = string.Empty; public DateTime Time; public bool Buy, Wick, Sweep; public int Run; public double Body; }

    public sealed class KeystoneEngLabResult { public List<KeystoneLabRow> Rows = new List<KeystoneLabRow>(); public KeystonePropRules Rules; public DateTime First, Last, SplitAt; public int Days; public Dictionary<string, int> Signals = new Dictionary<string, int>(); public bool Cancelled; }

    public static class KeystoneEngLab
    {
        // Close-stamped N-minute candles from close-stamped 1-minute bars (a candle ends on a multiple of N minutes of the day).
        public static List<KeystoneArcBar> Candles(List<KeystoneArcBar> one, int minutes)
        {
            if (minutes <= 1) return one;
            var output = new List<KeystoneArcBar>(); KeystoneArcBar cur = null; DateTime curEnd = DateTime.MinValue;
            foreach (var b in one)
            {
                int m = (int)b.Time.TimeOfDay.TotalMinutes, r = m % minutes; DateTime end = r == 0 ? b.Time : b.Time.AddMinutes(minutes - r);
                if (cur == null || end != curEnd) { if (cur != null) output.Add(cur); cur = new KeystoneArcBar { Symbol = b.Symbol, Time = end, Open = b.Open, High = b.High, Low = b.Low, Close = b.Close }; curEnd = end; }
                else { cur.High = Math.Max(cur.High, b.High); cur.Low = Math.Min(cur.Low, b.Low); cur.Close = b.Close; }
            }
            if (cur != null) output.Add(cur);
            return output;
        }

        // The lab's 123 ENGULFING rule (same as the lab detector): a run of ≥1 opposite candles, then a candle closing beyond the
        // last run candle's open (body engulf); WICK = closes beyond its high/low; SWEEP = trades beyond the last two candles' extreme.
        public static List<KeystoneEngSignal> Signals(List<KeystoneArcBar> bars, string symbol, double minBody, int startHhmm, int closeHhmm)
        {
            var output = new List<KeystoneEngSignal>();
            for (int i = 2; i < bars.Count; i++)
            {
                var c = bars[i]; int hhmm = c.Time.Hour * 100 + c.Time.Minute; if (hhmm < startHhmm || hhmm >= closeHhmm) continue;   // same window as the lab detector; a signal at the close cannot be filled
                bool up = c.Close > c.Open, down = c.Close < c.Open; if (!up && !down) continue; bool buy = up;
                if (Math.Abs(c.Close - c.Open) < minBody) continue;
                int run = 0; for (int k = i - 1; k >= 0; k--) { bool red = bars[k].Close < bars[k].Open, green = bars[k].Close > bars[k].Open; if (buy ? red : green) run++; else break; }
                if (run < 1) continue;
                var last = bars[i - 1]; var prev = bars[i - 2];
                if (buy ? c.Close <= last.Open : c.Close >= last.Open) continue;
                output.Add(new KeystoneEngSignal { Symbol = symbol, Time = c.Time, Buy = buy, Run = run, Body = Math.Abs(c.Close - c.Open), Wick = buy ? c.Close > last.High : c.Close < last.Low, Sweep = buy ? c.Low < Math.Min(last.Low, prev.Low) : c.High > Math.Max(last.High, prev.High) });
            }
            return output;
        }

        static bool Pass(KeystoneEngSignal s, string dir, string strength, int minRun)
        {
            if ((dir == "BUY" && !s.Buy) || (dir == "SELL" && s.Buy)) return false;
            if (s.Run < minRun) return false;
            if (strength == "WICK") return s.Wick || s.Sweep; if (strength == "SWEEP") return s.Sweep; if (strength == "SWEEP+WICK") return s.Sweep && s.Wick;
            return true;
        }

        public static KeystoneEngLabResult Run(List<KeystoneArcBar> oneMinute, KeystoneEngLabGrid g, KeystonePropRules rules, Action<int, int> progress, Func<bool> cancelled)
        {
            var res = new KeystoneEngLabResult { Rules = rules }; if (oneMinute == null || oneMinute.Count == 0) return res;
            var raws = oneMinute.Where(b => g.Symbols.Contains((b.Symbol ?? "").ToUpperInvariant())).GroupBy(b => b.Symbol.ToUpperInvariant()).ToDictionary(x => x.Key, x => x.OrderBy(b => b.Time).ToList());
            var days = raws.Values.SelectMany(l => l.Select(b => b.Time.Date)).Distinct().OrderBy(d => d).ToList(); res.Days = days.Count;
            if (days.Count > 0) { res.First = days[0]; res.Last = days[days.Count - 1]; res.SplitAt = days[Math.Min(days.Count - 1, (int)(days.Count * g.InSampleShare))]; }
            var jobs = new List<Tuple<string, int>>(); foreach (string sym in raws.Keys) foreach (int tf in g.Timeframes.Distinct()) jobs.Add(Tuple.Create(sym, tf));
            var outRows = new List<KeystoneLabRow>[jobs.Count]; int done = 0; var sigCount = new System.Collections.Concurrent.ConcurrentDictionary<string, int>();
            System.Threading.Tasks.Parallel.For(0, jobs.Count, new System.Threading.Tasks.ParallelOptions { MaxDegreeOfParallelism = Math.Max(1, Environment.ProcessorCount - 1) }, (ji, state) =>
            {
                if (cancelled != null && cancelled()) { state.Stop(); return; }
                string sym = jobs[ji].Item1; int tf = jobs[ji].Item2; var raw = raws[sym]; bool mgc = sym == "MGC";
                int start = mgc ? g.MgcStart : g.MnqStart;
                var sigs = Signals(Candles(raw, tf), sym, mgc ? g.MgcMinBody : g.MnqMinBody, start, g.Close);
                sigCount[sym + " " + tf + "M"] = sigs.Count;
                // the fill: the next 1-minute bar's open after the signal candle closed
                var fills = new List<Tuple<KeystoneEngSignal, int>>();
                foreach (var s in sigs) { int lo = 0, hi = raw.Count - 1, idx = -1; while (lo <= hi) { int mid = (lo + hi) / 2; if (raw[mid].Time > s.Time) { idx = mid; hi = mid - 1; } else lo = mid + 1; } if (idx >= 0 && raw[idx].Time.Date == s.Time.Date) fills.Add(Tuple.Create(s, idx)); }
                var rows = new List<KeystoneLabRow>();
                foreach (double tp in mgc ? g.MgcTargets : g.MnqTargets) foreach (double sl in mgc ? g.MgcStops : g.MnqStops)
                {
                    var trades = fills.Select(f => KeystoneLab.Bracket(raw, f.Item2, raw[f.Item2].Open, f.Item1.Buy ? 1 : -1, tp, sl, f.Item1.Time.Date.AddHours(g.Close / 100).AddMinutes(g.Close % 100), sym, true)).ToList();
                    foreach (string dir in g.Directions.Distinct()) foreach (string st in g.Strengths.Distinct()) foreach (int mr in g.MinRuns.Distinct())
                    {
                        // one position at a time: a signal is taken only when the previous trade has ended
                        var taken = new List<KeystoneLabTrade>(); DateTime busyUntil = DateTime.MinValue;
                        for (int k = 0; k < fills.Count; k++)
                        {
                            if (!Pass(fills[k].Item1, dir, st, mr)) continue; var t = trades[k];
                            if (t.EntryTime < busyUntil) continue; taken.Add(t); busyUntil = t.ExitTime.AddMinutes(1);
                        }
                        if (taken.Count == 0) continue;
                        foreach (int q in g.Contracts.Distinct())
                        {
                            var r = new KeystoneLabRow();
                            r.Settings.Add(Tuple.Create("INSTRUMENT", sym)); r.Settings.Add(Tuple.Create("TIMEFRAME", tf + "M")); r.Settings.Add(Tuple.Create("DIRECTION", dir));
                            r.Settings.Add(Tuple.Create("SIGNAL", st)); r.Settings.Add(Tuple.Create("RUN", "RUN ≥" + mr));
                            r.Settings.Add(Tuple.Create("TARGET", "TP " + tp.ToString("0.##", CultureInfo.InvariantCulture))); r.Settings.Add(Tuple.Create("STOP", "SL " + sl.ToString("0.##", CultureInfo.InvariantCulture))); r.Settings.Add(Tuple.Create("CONTRACTS", q + "x"));
                            r.Trades = taken.Select(t => KeystoneLab.Scale(t, q)).ToList();
                            KeystoneLab.Fill(r, rules, res.SplitAt, false, 0);
                            rows.Add(r);
                        }
                    }
                }
                outRows[ji] = rows;
                int kk = System.Threading.Interlocked.Increment(ref done); if (progress != null) progress(kk, jobs.Count);
            });
            res.Cancelled = cancelled != null && cancelled();
            foreach (var kv in sigCount.OrderBy(k => k.Key)) res.Signals[kv.Key] = kv.Value;
            res.Rows = outRows.Where(x => x != null).SelectMany(x => x).OrderByDescending(r => r.P.PropNet).ThenByDescending(r => r.P.Net).ToList();
            return res;
        }

        public static List<string> Advice(KeystoneEngLabResult res)
        {
            var lines = new List<string>(); if (res == null || res.Rows.Count == 0) return lines;
            Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            lines.Add(res.Rows.Count(r => r.P.PropNet > 0) + " of " + res.Rows.Count + " rows made money for prop • " + res.Rows.Count(r => r.P.Net > 0) + " on a plain account • " + res.Days + " days (" + res.First.ToString("yyyy-MM-dd") + " → " + res.Last.ToString("yyyy-MM-dd") + ").");
            foreach (string sym in res.Rows.Select(r => r.Get("INSTRUMENT")).Distinct().OrderBy(x => x))
            {
                var q = res.Rows.Where(r => r.Get("INSTRUMENT") == sym).ToList();
                var b = q.OrderByDescending(r => r.P.PropNet).First();
                lines.Add(sym + " • BEST FOR PROP: " + b.Label + " → " + m(b.P.PropNet) + " (" + b.P.Passed + " passed / " + b.P.Bought + ", " + b.P.Payouts + " payouts" + (b.P.Stats.HasPayout ? ", 1st payout " + b.P.Stats.CalendarDaysToFirstPayout + " d" : "") + ") • plain " + m(b.P.Net) + " • " + b.Trades.Count + " trades");
                foreach (string dir in new[] { "BUY", "SELL", "BOTH" })
                {
                    var d = q.Where(r => r.Get("DIRECTION") == dir).OrderByDescending(r => r.P.Net).FirstOrDefault(); if (d == null) continue;
                    var med = q.Where(r => r.Get("DIRECTION") == dir).Select(r => r.P.Net).OrderBy(v => v).ToList();
                    lines.Add(sym + " • " + dir + ": best plain " + d.Label + " → " + m(d.P.Net) + " (unseen 30% " + m(d.OutSampleNet) + ") • median of all " + dir + " rows " + m(med[med.Count / 2]));
                }
                var tfBest = q.GroupBy(r => r.Get("TIMEFRAME")).Select(gr => new { Tf = gr.Key, Med = gr.Select(r => r.P.Net).OrderBy(v => v).ElementAt(gr.Count() / 2), Best = gr.Max(r => r.P.Net) }).OrderByDescending(x => x.Med).ToList();
                lines.Add(sym + " • TIMEFRAMES by median plain result: " + string.Join(" • ", tfBest.Select(x => x.Tf + " " + m(x.Med) + " (best " + m(x.Best) + ")")));
                var robust = q.Where(r => r.P.Net > 0 && r.InSampleNet > 0 && r.OutSampleNet > 0 && r.YearsUp == r.Years && r.Years > 0).OrderByDescending(r => r.P.PropNet).FirstOrDefault();
                lines.Add(robust != null ? sym + " • STRONGEST (plain profit in both halves AND prop positive every year): " + robust.Label + " → prop " + m(robust.P.PropNet) + ", plain " + m(robust.P.Net) : sym + " • No row was profitable in both halves and every year — no proven edge yet for " + sym + ".");
            }
            return lines;
        }
    }

    // ---- MICRO A DAY • COMPARE ------------------------------------------------------------------------
    // Every version on the same loaded days: BUY / SELL × MNQ / MGC / BOTH × take profit (or hold to the close).
    // Per version: the plain 1-micro account (net, worst drawdown, longest time under water) and one prop account slot
    // walking the days in order (evaluations bought, passed, payouts, funded accounts lost, cash − spent), per year.
    public sealed class KeystoneMicroRow
    {
        public string Direction = "BUY", Instruments = "MNQ", TakeProfit = string.Empty; public double MnqTp, MgcTp;
        public int Trades, Wins; public double Net, MaxDrawdown, AvgWorst, WorstDay, BestDay; public int LongestUnderwaterDays;
        public int Bought, Passed, Payouts, FundedLost; public double Spent, Cash, MoneyNeeded;
        public double PassRate, ValuePerEval, AvgDaysToPass, FundedValue;     // random order of the same days (2,000 evaluations)
        public Dictionary<int, double> NetByYear = new Dictionary<int, double>(), PropByYear = new Dictionary<int, double>();
        public List<KeystoneMicroTrade> TradeList = new List<KeystoneMicroTrade>();
        public List<KeystonePropDay> Days = new List<KeystonePropDay>();
        public List<KeystoneMicroAccount> Accounts = new List<KeystoneMicroAccount>();
        public List<Tuple<DateTime, double>> PropCurve = new List<Tuple<DateTime, double>>();
        public List<KeystoneMicroLedger> Ledger = new List<KeystoneMicroLedger>(); public KeystoneMicroStats Stats = new KeystoneMicroStats();
        public double PropNet { get { return Cash - Spent; } }
        public bool EveryYear { get { return PropByYear.Count > 0 && PropByYear.Values.All(v => v > 0); } }
        public string Label { get { return Direction + " • " + Instruments + " • " + TakeProfit; } }
    }

    public sealed class KeystoneMicroSession { public string Symbol = string.Empty; public DateTime Open, Close; public int From, To; public double Entry; }

    public sealed class KeystoneMicroTrade
    {
        public string Symbol = string.Empty; public bool Sell, Hit; public DateTime Open, ExitTime; public double Entry, Exit, Tp, Points, Net, Worst, Best; public int Qty = 1;
        public string Outcome { get { return Hit ? "TAKE PROFIT" : "CLOSE"; } }
    }

    public sealed class KeystoneMicroAccount { public int No; public DateTime Bought, PassedOn = DateTime.MinValue, Ended = DateTime.MinValue; public int EvalDays, FundedDays, Payouts, BoughtIndex, PassedIndex = -1; public double Cash, Spent, PayoutGross; public string Status = "OPEN"; public List<DateTime> PayoutDates = new List<DateTime>(); public List<int> PayoutIndexes = new List<int>(); }

    // One session of the prop slot: what happened that day (for months, profit vs expenses).
    public sealed class KeystoneMicroLedger { public DateTime Day; public double Pnl, Cash, Spent; public int Bought, Passed, Payouts, Lost, Failed; }

    // The questions that decide a prop plan: how long and how much until the first payout, payouts in a row, months.
    public sealed class KeystoneMicroStats
    {
        public bool HasPayout; public DateTime FirstPayout; public int CalendarDaysToFirstPayout, SessionsToFirstPayout, EvalsToFirstPayout; public double SpentToFirstPayout, FirstPayoutCash;
        public double AvgSessionsBuyToFirstPayout, AvgSessionsPassToFirstPayout, AvgSessionsBetweenPayouts, AvgPayout, BiggestPayout;
        public int MostPayoutsOneAccount, PayoutsInARow, LongestFailStreak, FundedWithoutPayout; public double AvgEvalSessionsToPass, AvgFundedLife;
        public int MonthsPositive, Months; public double BestMonth, WorstMonth;
    }

    public sealed class KeystoneMicroTpRow { public string Symbol = string.Empty, Direction = string.Empty; public double Tp; public int Trades, Hits; public double Net, MaxDrawdown, PropNet; public int Passed, Payouts, Bought; public Dictionary<int, double> NetByYear = new Dictionary<int, double>(); public bool EveryYear { get { return NetByYear.Count > 0 && NetByYear.Values.All(v => v > 0); } } }

    public sealed class KeystoneMicroMove { public string Symbol = string.Empty, Name = string.Empty; public bool Hour; public int Days, Up; public double SumPts, AbsPts; public double AvgPts { get { return Days == 0 ? 0 : SumPts / Days; } } public double UpPct { get { return Days == 0 ? 0 : 100.0 * Up / Days; } } }

    public sealed class KeystoneMicroSlots { public string Mode = string.Empty; public int Slots; public int Bought, Passed, Payouts, FundedLost; public double Spent, Cash, MoneyNeeded; public double Net { get { return Cash - Spent; } } }

    public sealed class KeystoneMicroResult
    {
        public List<KeystoneMicroRow> Rows = new List<KeystoneMicroRow>(); public List<KeystoneMicroTpRow> Grid = new List<KeystoneMicroTpRow>(); public List<KeystoneMicroMove> Moves = new List<KeystoneMicroMove>();
        public int Sessions; public DateTime First, Last; public KeystonePropRules Rules; public double EvalK = 1, FundK = 1;
    }

    public static class KeystoneMicroADay
    {
        public static readonly double[] MnqTps = { 0, 25, 50, 75, 100, 150 }, MgcTps = { 0, 5, 10, 15, 20, 30 };
        public static double[] GridTps(string symbol) { var list = new List<double>(); for (int i = 0; i <= 30; i++) list.Add(KeystoneMoveStudy.IsMgc(symbol) ? i * 2.0 : i * 10.0); return list.ToArray(); }

        // The sessions the detector trades: open = first 1-minute bar after the open time (within 15 minutes), close = the last bar ≤ close time.
        public static List<KeystoneMicroSession> Sessions(List<KeystoneArcBar> raw, KeystoneArcRunConfig cfg, string symbol)
        {
            var output = new List<KeystoneMicroSession>(); if (raw == null || raw.Count == 0) return output;
            int openM = cfg.MadOpenHhmm / 100 * 60 + cfg.MadOpenHhmm % 100, closeM = cfg.MadCloseHhmm / 100 * 60 + cfg.MadCloseHhmm % 100; bool overnight = closeM <= openM;
            var days = raw.Select(b => { var o = b.Time.Date.AddMinutes(openM); return b.Time > o ? o : (overnight ? o.AddDays(-1) : o); }).Distinct().OrderBy(d => d).ToList();
            int idx = 0;
            foreach (DateTime open in days)
            {
                DateTime close = open.Date.AddDays(overnight ? 1 : 0).AddMinutes(closeM);
                if (open < cfg.Start.AddMinutes(-1) || close > cfg.End.AddDays(1)) continue;
                while (idx < raw.Count && raw[idx].Time <= open) idx++;
                if (idx >= raw.Count) break;
                if (raw[idx].Time > open.AddMinutes(15) || raw[idx].Time > close) continue;
                int j = idx; while (j + 1 < raw.Count && raw[j + 1].Time <= close) j++;
                output.Add(new KeystoneMicroSession { Symbol = symbol, Open = open, Close = close, From = idx, To = j, Entry = raw[idx].Open });
                idx = j;
            }
            return output;
        }

        // One trade on one session: the same walk as the detector (take profit on the touch, else the last close), net of costs.
        public static KeystoneMicroTrade Trade(List<KeystoneArcBar> raw, KeystoneMicroSession s, bool sell, double tp, int qty)
        {
            double sign = sell ? -1 : 1, pv = KeystoneMoveStudy.PointValue(s.Symbol), target = s.Entry + sign * tp, hi = raw[s.From].High, lo = raw[s.From].Low, exit = s.Entry; DateTime at = raw[s.From].Time; bool hit = false;
            for (int j = s.From; j <= s.To; j++)
            {
                var b = raw[j]; hi = Math.Max(hi, b.High); lo = Math.Min(lo, b.Low);
                if (tp > 0 && (sell ? b.Low <= target : b.High >= target)) { exit = target; at = b.Time; hit = true; break; }
                exit = b.Close; at = b.Time;
            }
            var t = new KeystoneMicroTrade { Symbol = s.Symbol, Sell = sell, Hit = hit, Open = s.Open, ExitTime = at, Entry = s.Entry, Exit = exit, Tp = tp, Qty = qty, Points = sign * (exit - s.Entry) };
            t.Net = t.Points * pv * qty - qty * KeystoneMoveStudy.Cost(s.Symbol);
            t.Worst = -(sell ? hi - s.Entry : s.Entry - lo) * pv * qty; t.Best = (sell ? s.Entry - lo : hi - s.Entry) * pv * qty;
            return t;
        }

        // Session days for the prop simulation: both instruments of one session added together (the day = the session's trading date).
        public static List<KeystonePropDay> DaysOf(IEnumerable<KeystoneMicroTrade> trades)
        {
            return trades.GroupBy(t => t.Open).OrderBy(g => g.Key).Select(g => new KeystonePropDay { Day = g.Key.Date.AddDays(1), Pnl = g.Sum(t => t.Net), Worst = Math.Min(0, g.Sum(t => t.Worst)), Best = Math.Max(0, g.Sum(t => t.Best)), Traded = true }).ToList();
        }

        // Every account one slot buys, walking the days in order (identical totals to KeystonePropPlanner.History). Curve = cash − spent after each day.
        public static List<KeystoneMicroAccount> Accounts(KeystonePropRules r, List<KeystonePropDay> days, List<Tuple<DateTime, double>> curve, List<KeystoneMicroLedger> ledger = null, double evalK = 1, double fundK = 1)
        {
            var list = new List<KeystoneMicroAccount>(); if (days == null || days.Count == 0) return list;
            var a = KeystonePropPlanner.NewEval(r); var acc = new KeystoneMicroAccount { No = 1, Bought = days[0].Day, Spent = r.EvalCost, BoughtIndex = 0 }; list.Add(acc);
            double cum = -r.EvalCost;
            for (int i = 0; i < days.Count; i++)
            {
                var d = days[i]; var L = new KeystoneMicroLedger { Day = d.Day, Pnl = d.Pnl };
                if (i == 0) { L.Bought++; L.Spent += r.EvalCost; }
                bool wasFunded = a.Funded; double before = a.Spent;
                double got = KeystonePropPlanner.Step(a, r, KeystonePropPlanner.Scale(d, a.Funded ? fundK : evalK, 0));
                if (got > 0) { acc.Payouts++; acc.Cash += got; acc.PayoutGross += got / Math.Max(0.01, r.Split / 100.0); cum += got; acc.PayoutDates.Add(d.Day); acc.PayoutIndexes.Add(i); L.Payouts++; L.Cash += got; }
                if (!wasFunded && a.Funded) { acc.PassedOn = d.Day; acc.PassedIndex = i; acc.Spent += a.Spent - before; cum -= a.Spent - before; L.Passed++; L.Spent += a.Spent - before; }
                acc.EvalDays = a.Days; acc.FundedDays = a.FundedDays;
                if (a.Dead)
                {
                    acc.Ended = d.Day; acc.Status = a.Funded ? (r.MaxPayouts > 0 && a.Payouts >= r.MaxPayouts ? "MAX PAYOUTS" : "FUNDED LOST") : "FAILED EVALUATION";
                    if (acc.Status == "FUNDED LOST") L.Lost++; else if (acc.Status == "FAILED EVALUATION") L.Failed++;
                    a = KeystonePropPlanner.NewEval(r); acc = new KeystoneMicroAccount { No = list.Count + 1, Bought = d.Day, Spent = r.EvalCost, BoughtIndex = i + 1 }; list.Add(acc); cum -= r.EvalCost; L.Bought++; L.Spent += r.EvalCost;
                }
                else acc.Status = a.Funded ? "FUNDED (OPEN)" : "IN EVALUATION";
                if (curve != null) curve.Add(Tuple.Create(d.Day, cum));
                if (ledger != null) ledger.Add(L);
            }
            return list;
        }

        public static KeystoneMicroStats Stats(List<KeystoneMicroAccount> accounts, List<KeystoneMicroLedger> ledger)
        {
            var s = new KeystoneMicroStats(); if (accounts == null || accounts.Count == 0 || ledger == null || ledger.Count == 0) return s;
            var firstAcc = accounts.Where(a => a.PayoutIndexes.Count > 0).OrderBy(a => a.PayoutIndexes[0]).FirstOrDefault();
            if (firstAcc != null)
            {
                int idx = firstAcc.PayoutIndexes[0]; s.HasPayout = true; s.FirstPayout = ledger[idx].Day;
                s.CalendarDaysToFirstPayout = (int)(ledger[idx].Day - ledger[0].Day).TotalDays; s.SessionsToFirstPayout = idx + 1;
                s.SpentToFirstPayout = ledger.Take(idx + 1).Sum(l => l.Spent); s.EvalsToFirstPayout = accounts.Count(a => a.BoughtIndex <= idx); s.FirstPayoutCash = ledger[idx].Cash;
            }
            var paid = accounts.Where(a => a.PayoutIndexes.Count > 0).ToList();
            s.AvgSessionsBuyToFirstPayout = paid.Count == 0 ? 0 : paid.Average(a => (double)(a.PayoutIndexes[0] - a.BoughtIndex + 1));
            s.AvgSessionsPassToFirstPayout = paid.Count == 0 ? 0 : paid.Average(a => (double)(a.PayoutIndexes[0] - a.PassedIndex));
            var gaps = accounts.SelectMany(a => a.PayoutIndexes.Skip(1).Select((v, k) => (double)(v - a.PayoutIndexes[k]))).ToList(); s.AvgSessionsBetweenPayouts = gaps.Count == 0 ? 0 : gaps.Average();
            var cashes = ledger.Where(l => l.Payouts > 0).Select(l => l.Cash).ToList(); s.AvgPayout = cashes.Count == 0 ? 0 : cashes.Average(); s.BiggestPayout = cashes.Count == 0 ? 0 : cashes.Max();
            s.MostPayoutsOneAccount = accounts.Max(a => a.Payouts);
            int run = 0; foreach (var l in ledger) { if (l.Payouts > 0) { run += l.Payouts; s.PayoutsInARow = Math.Max(s.PayoutsInARow, run); } if (l.Lost > 0) run = 0; }
            int fails = 0; foreach (var a in accounts) { if (a.Status == "FAILED EVALUATION") { fails++; s.LongestFailStreak = Math.Max(s.LongestFailStreak, fails); } else if (a.PassedIndex >= 0) fails = 0; }
            s.FundedWithoutPayout = accounts.Count(a => a.PassedIndex >= 0 && a.Payouts == 0 && a.Status == "FUNDED LOST");
            var passed = accounts.Where(a => a.PassedIndex >= 0).ToList(); s.AvgEvalSessionsToPass = passed.Count == 0 ? 0 : passed.Average(a => (double)a.EvalDays);
            var ended = passed.Where(a => a.Status == "FUNDED LOST").ToList(); s.AvgFundedLife = ended.Count == 0 ? 0 : ended.Average(a => (double)a.FundedDays);
            var months = ledger.GroupBy(l => new DateTime(l.Day.Year, l.Day.Month, 1)).Select(g => g.Sum(l => l.Cash - l.Spent)).ToList();
            s.Months = months.Count; s.MonthsPositive = months.Count(v => v > 0); s.BestMonth = months.Count == 0 ? 0 : months.Max(); s.WorstMonth = months.Count == 0 ? 0 : months.Min();
            return s;
        }

        // Several accounts: COPY = every account takes the same trades from the same day (one account × n) •
        // STAGGERED = account k starts k × gap sessions later, so the accounts are at different points of their life.
        public static KeystoneMicroSlots Slots(KeystonePropRules r, List<KeystonePropDay> days, string mode, int n, int gap, double evalK = 1, double fundK = 1)
        {
            var res = new KeystoneMicroSlots { Mode = mode, Slots = n }; if (days == null || days.Count == 0) return res;
            var total = new double[days.Count]; int slots = mode == "COPY" ? 1 : n; double mult = mode == "COPY" ? n : 1;
            for (int k = 0; k < slots; k++)
            {
                int start = Math.Min(days.Count - 1, k * Math.Max(1, gap)); var curve = new List<Tuple<DateTime, double>>();
                var accts = Accounts(r, days.Skip(start).ToList(), curve, null, evalK, fundK);
                for (int i = 0; i < days.Count; i++) total[i] += mult * (i < start ? 0 : curve[i - start].Item2);
                res.Bought += (int)mult * accts.Count; res.Passed += (int)mult * accts.Count(x => x.PassedOn != DateTime.MinValue); res.Payouts += (int)mult * accts.Sum(x => x.Payouts);
                res.FundedLost += (int)mult * accts.Count(x => x.Status == "FUNDED LOST"); res.Spent += mult * accts.Sum(x => x.Spent); res.Cash += mult * accts.Sum(x => x.Cash);
            }
            res.MoneyNeeded = Math.Max(0, -total.DefaultIfEmpty(0).Min());
            return res;
        }

        static void Fill(KeystoneMicroRow row, KeystonePropRules rules, bool random, double evalK = 1, double fundK = 1)
        {
            row.Days = DaysOf(row.TradeList);
            row.Trades = row.TradeList.Count; row.Wins = row.TradeList.Count(t => t.Net > 0);
            FillDays(row, rules, random ? 2000 : 0, evalK, fundK, true);
        }

        // Plain account + prop history from ready-made days (one per session). detail = keep the account list, the day
        // ledger and the curve (for the selected row); without it only the totals and the payout facts are kept (rankings).
        public static void FillDays(KeystoneMicroRow row, KeystonePropRules rules, int randomLives, double evalK, double fundK, bool detail)
        {
            row.NetByYear = new Dictionary<int, double>(); row.PropByYear = new Dictionary<int, double>(); row.MaxDrawdown = 0;
            row.Bought = row.Passed = row.Payouts = row.FundedLost = 0; row.Spent = row.Cash = 0;
            double eq = 0, peak = 0; DateTime peakDay = DateTime.MinValue; int longest = 0;
            foreach (var d in row.Days)
            {
                eq += d.Pnl; double y; row.NetByYear.TryGetValue(d.Day.Year, out y); row.NetByYear[d.Day.Year] = y + d.Pnl;
                if (eq >= peak) { peak = eq; peakDay = d.Day; } else { row.MaxDrawdown = Math.Max(row.MaxDrawdown, peak - eq); if (peakDay != DateTime.MinValue) longest = Math.Max(longest, (int)(d.Day - peakDay).TotalDays); }
            }
            row.Net = eq; row.LongestUnderwaterDays = longest; row.AvgWorst = row.Days.Count == 0 ? 0 : row.Days.Average(d => d.Worst);
            row.WorstDay = row.Days.Count == 0 ? 0 : row.Days.Min(d => d.Pnl); row.BestDay = row.Days.Count == 0 ? 0 : row.Days.Max(d => d.Pnl);
            var plan = new KeystonePropPlan { Source = "REAL", EvalSize = evalK, FundSize = fundK };
            foreach (var y in KeystonePropPlanner.History(rules, plan, row.Days))
            { row.Bought += y.Bought; row.Passed += y.Passed; row.Payouts += y.Payouts; row.FundedLost += y.Blown; row.Spent += y.Spent; row.Cash += y.Cash; row.PropByYear[y.Year] = y.Net; }
            var curve = new List<Tuple<DateTime, double>>(); var ledger = new List<KeystoneMicroLedger>();
            var accounts = Accounts(rules, row.Days, curve, ledger, evalK, fundK);
            row.Stats = Stats(accounts, ledger);
            row.MoneyNeeded = Math.Max(0, -curve.Select(p => p.Item2).DefaultIfEmpty(0).Min());
            if (detail) { row.Accounts = accounts; row.Ledger = ledger; row.PropCurve = curve; }
            else { row.Accounts = new List<KeystoneMicroAccount>(); row.Ledger = new List<KeystoneMicroLedger>(); row.PropCurve = new List<Tuple<DateTime, double>>(); }
            if (randomLives > 0 && row.Days.Count >= 10)
            {
                var ev = KeystonePropPlanner.Evaluate(rules, plan, row.Days, randomLives, 7);
                row.PassRate = ev.PassRate; row.ValuePerEval = ev.ValuePerEval; row.AvgDaysToPass = ev.AvgDaysToPass; row.FundedValue = ev.FundedValue;
            }
        }

        public static List<KeystoneMicroRow> Compare(List<KeystoneArcBar> oneMinute, KeystoneArcRunConfig basis, KeystonePropRules rules) { return Run(oneMinute, basis, rules).Rows; }

        // SIZE & SPEED: the same days traded with more micros in the evaluation and in the funded account.
        public sealed class SizeRow { public double EvalK, FundK; public KeystoneMicroRow Row; }
        public static readonly double[] EvalSizes = { 1, 2, 3, 5, 8, 10, 15 }, FundSizes = { 1, 2, 3, 5 };
        public static List<SizeRow> Sizes(KeystoneMicroRow basis, KeystonePropRules rules)
        {
            var combos = EvalSizes.SelectMany(e => FundSizes.Select(f => Tuple.Create(e, f))).ToList(); var output = new SizeRow[combos.Count];
            System.Threading.Tasks.Parallel.For(0, combos.Count, i =>
            {
                var row = new KeystoneMicroRow { Direction = basis.Direction, Instruments = basis.Instruments, TakeProfit = basis.TakeProfit, MnqTp = basis.MnqTp, MgcTp = basis.MgcTp, TradeList = basis.TradeList };
                Fill(row, rules, true, combos[i].Item1, combos[i].Item2);
                output[i] = new SizeRow { EvalK = combos[i].Item1, FundK = combos[i].Item2, Row = row };
            });
            return output.ToList();
        }

        public static KeystoneMicroResult Run(List<KeystoneArcBar> oneMinute, KeystoneArcRunConfig basis, KeystonePropRules rules, double evalK = 1, double fundK = 1)
        {
            var res = new KeystoneMicroResult { Rules = rules, EvalK = evalK, FundK = fundK }; if (oneMinute == null || oneMinute.Count == 0) return res;
            int qty = Math.Max(1, basis.MadQty);
            var bars = oneMinute.GroupBy(b => b.Symbol).ToDictionary(g => g.Key, g => g.OrderBy(b => b.Time).ToList());
            var sessions = bars.ToDictionary(kv => kv.Key, kv => Sessions(kv.Value, basis, kv.Key));
            bool hasMnq = sessions.ContainsKey("MNQ") && sessions["MNQ"].Count > 0, hasMgc = sessions.ContainsKey("MGC") && sessions["MGC"].Count > 0;
            var allOpens = sessions.Values.SelectMany(l => l.Select(s => s.Open)).Distinct().OrderBy(d => d).ToList();
            res.Sessions = allOpens.Count; if (allOpens.Count > 0) { res.First = allOpens[0]; res.Last = allOpens[allOpens.Count - 1]; }
            Func<string, bool, double, List<KeystoneMicroTrade>> trades = (sym, sell, tp) => { List<KeystoneMicroSession> ss; return sessions.TryGetValue(sym, out ss) ? ss.Select(s => Trade(bars[sym], s, sell, tp, qty)).ToList() : new List<KeystoneMicroTrade>(); };
            // 36 versions
            var combos = new List<Tuple<string, string, int>>();
            foreach (string dir in new[] { "BUY", "SELL" })
                foreach (string inst in new[] { "MNQ", "MGC", "BOTH" })
                {
                    if ((inst == "MNQ" && !hasMnq) || (inst == "MGC" && !hasMgc) || (inst == "BOTH" && !(hasMnq && hasMgc))) continue;
                    for (int t = 0; t < MnqTps.Length; t++) combos.Add(Tuple.Create(dir, inst, t));
                }
            var rows = new KeystoneMicroRow[combos.Count];
            System.Threading.Tasks.Parallel.For(0, combos.Count, i =>
            {
                var c = combos[i]; bool sell = c.Item1 == "SELL";
                var row = new KeystoneMicroRow { Direction = c.Item1, Instruments = c.Item2, MnqTp = MnqTps[c.Item3], MgcTp = MgcTps[c.Item3] };
                row.TakeProfit = c.Item3 == 0 ? "HOLD TO THE CLOSE" : (c.Item2 == "MNQ" ? "TP +" + row.MnqTp + " PTS" : c.Item2 == "MGC" ? "TP +" + row.MgcTp + " PTS" : "TP MNQ +" + row.MnqTp + " / MGC +" + row.MgcTp);
                if (c.Item2 != "MGC") row.TradeList.AddRange(trades("MNQ", sell, row.MnqTp));
                if (c.Item2 != "MNQ") row.TradeList.AddRange(trades("MGC", sell, row.MgcTp));
                Fill(row, rules, true, evalK, fundK);
                rows[i] = row;
            });
            res.Rows = rows.Where(r => r != null).OrderByDescending(r => r.PropNet).ThenByDescending(r => r.Net).ToList();
            // take-profit grid: each instrument alone, 31 take profits each way
            var grid = new List<Tuple<string, bool, double>>();
            foreach (string sym in new[] { "MNQ", "MGC" }) if (sym == "MNQ" ? hasMnq : hasMgc) foreach (bool sell in new[] { false, true }) foreach (double tp in GridTps(sym)) grid.Add(Tuple.Create(sym, sell, tp));
            var gridRows = new KeystoneMicroTpRow[grid.Count];
            System.Threading.Tasks.Parallel.For(0, grid.Count, i =>
            {
                var g = grid[i]; var row = new KeystoneMicroRow(); row.TradeList = trades(g.Item1, g.Item2, g.Item3); Fill(row, rules, false, evalK, fundK);
                gridRows[i] = new KeystoneMicroTpRow { Symbol = g.Item1, Direction = g.Item2 ? "SELL" : "BUY", Tp = g.Item3, Trades = row.Trades, Hits = row.TradeList.Count(t => t.Hit), Net = row.Net, MaxDrawdown = row.MaxDrawdown, PropNet = row.PropNet, Passed = row.Passed, Payouts = row.Payouts, Bought = row.Bought, NetByYear = row.NetByYear };
            });
            res.Grid = gridRows.ToList();
            foreach (var kv in sessions) res.Moves.AddRange(Moves(bars[kv.Key], kv.Value, kv.Key));
            return res;
        }

        // Where the day's move happens (BUY points; SELL is the mirror): Asia (open → 03:00), London (03:00 → 09:30), New York (09:30 → close), and every hour.
        public static List<KeystoneMicroMove> Moves(List<KeystoneArcBar> raw, List<KeystoneMicroSession> sessions, string symbol)
        {
            var seg = new[] { new KeystoneMicroMove { Symbol = symbol, Name = "ASIA • OPEN → 03:00" }, new KeystoneMicroMove { Symbol = symbol, Name = "LONDON • 03:00 → 09:30" }, new KeystoneMicroMove { Symbol = symbol, Name = "NEW YORK • 09:30 → CLOSE" } };
            var hours = new Dictionary<int, KeystoneMicroMove>();
            foreach (var s in sessions)
            {
                DateTime day = s.Open.Date.AddDays(s.Open.Hour >= 12 ? 1 : 0); var cuts = new[] { day.AddHours(3), day.AddHours(9.5), s.Close };
                double last = s.Entry; int k = 0; double hourStart = s.Entry; int hourKey = s.Open.Hour; double prevClose = s.Entry;
                for (int j = s.From; j <= s.To; j++)
                {
                    var b = raw[j];
                    while (k < 2 && b.Time > cuts[k]) { if (cuts[k] > s.Open && cuts[k] < s.Close) Add(seg[k], prevClose - last); last = prevClose; k++; }
                    int h = (b.Time.AddMinutes(-1)).Hour;
                    if (h != hourKey) { AddHour(hours, symbol, hourKey, prevClose - hourStart); hourStart = prevClose; hourKey = h; }
                    prevClose = b.Close;
                }
                while (k < 2) { if (cuts[k] > s.Open && cuts[k] < s.Close) Add(seg[k], prevClose - last); last = prevClose; k++; }
                Add(seg[2], prevClose - last); AddHour(hours, symbol, hourKey, prevClose - hourStart);
            }
            var output = seg.ToList();
            int startHour = sessions.Count > 0 ? sessions[0].Open.Hour : 18;
            output.AddRange(hours.Values.OrderBy(h => (int.Parse(h.Name.Substring(0, 2)) - startHour + 24) % 24));
            return output;
        }
        static void Add(KeystoneMicroMove m, double pts) { m.Days++; if (pts > 0) m.Up++; m.SumPts += pts; m.AbsPts += Math.Abs(pts); }
        static void AddHour(Dictionary<int, KeystoneMicroMove> hours, string symbol, int h, double pts) { KeystoneMicroMove m; if (!hours.TryGetValue(h, out m)) { m = new KeystoneMicroMove { Symbol = symbol, Hour = true, Name = h.ToString("00") + ":00" }; hours[h] = m; } Add(m, pts); }
    }

    // ---- ASIAN MATH LAB: every combination of the Asian cycle on the loaded 1-minute bars, with prop accounts --------
    public sealed class KeystoneAsianLabGrid
    {
        public List<string> Scopes = new List<string> { "MNQ", "MGC", "BOTH" };
        public List<string> Directions = new List<string> { "LONG", "SHORT" };
        public bool MixedBoth;                       // BOTH also tries MNQ LONG / MGC SHORT and the reverse
        public List<int> Quantities = new List<int> { 1, 2 };
        public List<double> LegLosses = new List<double> { 75, 100, 150 };
        public List<int> Reversals = new List<int> { 2, 3, 4 };
        public List<double> Targets = new List<double> { 200, 350, 500 };
        public List<double> MaxLosses = new List<double> { 0 };   // 0 = AUTO (reversal legs × leg loss × instruments)
        public List<int> StartTimes = new List<int> { 1800 };
        public int EndHhmm = 1555;
        public double CostPerContract = 1.00;        // round trip per contract
        public double InSampleShare = 0.7;           // rows are judged again on the last 30% of nights they were not ranked on
        // TREND: when LONG and SHORT are both tested, extra rows pick each night's direction from the instrument's trend:
        // LONG when the price before the open is above the average of the previous N session closes, else SHORT (no look-ahead).
        public List<int> TrendDays = new List<int> { 20 };
    }

    public sealed class KeystoneAsianCoverage { public string Symbol = string.Empty; public int Year, DaysWithBars, NightsOpened; }

    public sealed class KeystoneAsianNight
    {
        public DateTime Date, EndTime; public double Net, Mnq, Mgc, Worst, Best; public int MnqLegs, MgcLegs, Contracts; public string End = string.Empty, Dir = string.Empty;
        public KeystoneAsianNight With(string dir) { var n = (KeystoneAsianNight)MemberwiseClone(); n.Dir = dir; return n; }
        public bool Target { get { return End == "TAKE PROFIT"; } }
    }

    public sealed class KeystoneAsianLabRow
    {
        public KeystoneArcAsianCombo Combo; public KeystoneMicroRow P = new KeystoneMicroRow(); public List<KeystoneAsianNight> Nights = new List<KeystoneAsianNight>();
        public double MnqNet, MgcNet, InSampleNet, OutSampleNet, AvgFullLoss; public int TargetNights, LossNights, AllStoppedNights, SessionEndNights, TargetAfterReversal, YearsUp, Years;
        public int[] EndLegs = new int[8];        // nights by the highest leg reached (either instrument), index 1..7
        public string Label { get { return KeystoneAsianLab.Name(Combo); } }
    }

    public sealed class KeystoneAsianNightSide { public string Symbol = string.Empty; public int Legs, MaxQty; public double Pnl, Peak, Low; public DateTime PeakTime, LowTime; }
    public sealed class KeystoneAsianNightSummary { public List<KeystoneAsianNightSide> Sides = new List<KeystoneAsianNightSide>(); public KeystoneAsianNightSide Combined = new KeystoneAsianNightSide { Symbol = "COMBINED" }; public string End = string.Empty; public DateTime EndTime; }

    public sealed class KeystoneAsianLabResult { public List<KeystoneAsianLabRow> Rows = new List<KeystoneAsianLabRow>(); public KeystonePropRules Rules; public int Combinations, Nights; public DateTime First, Last, SplitAt; public bool Cancelled; public List<KeystoneAsianCoverage> Coverage = new List<KeystoneAsianCoverage>(); }

    public static class KeystoneAsianLab
    {
        public static bool IsTrend(KeystoneArcAsianCombo c) { return c != null && ((c.MnqDirection ?? "").StartsWith("TREND") || (c.MgcDirection ?? "").StartsWith("TREND")); }
        static string DirName(string d) { return (d ?? "").StartsWith("TREND") ? "TREND " + d.Substring(5) + "d" : d; }

        public static string Name(KeystoneArcAsianCombo c)
        {
            string dir = c.Scope == "BOTH" ? (c.MnqDirection == c.MgcDirection ? DirName(c.MnqDirection) : "MNQ " + DirName(c.MnqDirection) + " / MGC " + DirName(c.MgcDirection)) : DirName(c.Scope == "MNQ" ? c.MnqDirection : c.MgcDirection);
            return c.Scope + " • " + dir + " • " + c.StartingQuantity + " micro" + (c.StartingQuantity == 1 ? "" : "s") + " • leg $" + c.LegLoss.ToString("0") + " • " + c.Reversals + " rev • TP $" + c.Target.ToString("0") + " • max loss " + (c.DailyLossLimit > 0 ? "$" + c.DailyLossLimit.ToString("0") : "AUTO") + (c.StartHhmm != 1800 ? " • " + c.StartHhmm.ToString("0000") : "");
        }

        public static List<KeystoneArcAsianCombo> Combos(KeystoneAsianLabGrid g, bool hasMnq, bool hasMgc)
        {
            var list = new List<KeystoneArcAsianCombo>();
            foreach (string scope in g.Scopes.Distinct())
            {
                if ((scope != "MGC" && !hasMnq) || (scope != "MNQ" && !hasMgc)) continue;
                var dirs = new List<Tuple<string, string>>();
                foreach (string d in g.Directions.Distinct()) dirs.Add(Tuple.Create(d, d));
                bool trendNeedsMixed = g.TrendDays != null && g.TrendDays.Count > 0 && g.Directions.Contains("LONG") && g.Directions.Contains("SHORT");
                if (scope == "BOTH" && (g.MixedBoth || trendNeedsMixed)) { dirs.Add(Tuple.Create("LONG", "SHORT")); dirs.Add(Tuple.Create("SHORT", "LONG")); }
                foreach (var d in dirs) foreach (int q in g.Quantities.Distinct()) foreach (double loss in g.LegLosses.Distinct()) foreach (int rev in g.Reversals.Distinct())
                foreach (double tp in g.Targets.Distinct()) foreach (double ml in g.MaxLosses.Distinct()) foreach (int st in g.StartTimes.Distinct())
                    list.Add(new KeystoneArcAsianCombo { Scope = scope, MnqDirection = d.Item1, MgcDirection = d.Item2, RiskMode = "CASH", LegLoss = loss, Reversals = rev, Target = tp, DailyLossLimit = ml, StartingQuantity = Math.Max(1, q), StartHhmm = st, EndHhmm = g.EndHhmm });
            }
            return list;
        }

        // One night per session from the cycle's legs (the engine's own events): net after costs, each instrument, legs, how it ended.
        public static List<KeystoneAsianNight> Nights(List<KeystoneArcEvent> events, double costPerContract)
        {
            var output = new List<KeystoneAsianNight>();
            foreach (var g in events.Where(e => e.SetupClass == "ASIA75").GroupBy(e => e.ReferenceTime.Date).OrderBy(g => g.Key))
            {
                var n = new KeystoneAsianNight { Date = g.Key };
                foreach (var e in g)
                {
                    double q = Math.Max(1, e.Quantity), net = e.GrossPnl - q * costPerContract; n.Net += net; n.Contracts += (int)Math.Round(q);
                    bool mgc = (e.Symbol ?? "").StartsWith("MGC", StringComparison.OrdinalIgnoreCase);
                    if (mgc) { n.Mgc += net; n.MgcLegs = Math.Max(n.MgcLegs, e.AsianLegNumber); } else { n.Mnq += net; n.MnqLegs = Math.Max(n.MnqLegs, e.AsianLegNumber); }
                    if (!double.IsNaN(e.AsianCycleWorstAtExit)) n.Worst = Math.Min(n.Worst, e.AsianCycleWorstAtExit); if (!double.IsNaN(e.AsianCyclePnlAtExit)) n.Best = Math.Max(n.Best, e.AsianCyclePnlAtExit);
                    if (e.ExitTime > n.EndTime) n.EndTime = e.ExitTime;
                }
                var closing = g.Where(e => !(e.ReviewNote ?? "").StartsWith("REVERSAL LOSS", StringComparison.OrdinalIgnoreCase)).OrderBy(e => e.ExitTime).FirstOrDefault();
                n.End = closing == null ? "ALL LEGS STOPPED" : closing.Outcome == "WIN" ? "TAKE PROFIT" : closing.Outcome == "SESSION EXIT" ? "SESSION END" : closing.Outcome == "BREAKEVEN GUARD" ? "BREAKEVEN" : "MAX LOSS";
                n.Worst = Math.Min(n.Worst - n.Contracts * costPerContract, n.Net);
                output.Add(n);
            }
            return output;
        }

        public static KeystoneAsianLabRow Row(KeystoneArcAsianCombo c, List<KeystoneAsianNight> nights, KeystonePropRules rules, DateTime splitAt, bool detail, int randomLives)
        {
            var row = new KeystoneAsianLabRow { Combo = c, Nights = nights };
            row.P.Direction = "ASIAN"; row.P.Instruments = c.StartHhmm.ToString("0000"); row.P.TakeProfit = Name(c);
            row.P.Days = nights.Select(n => new KeystonePropDay { Day = n.Date.AddDays(1), Pnl = n.Net, Worst = Math.Min(0, n.Worst), Best = Math.Max(0, n.Best), Traded = true }).ToList();
            row.P.Trades = nights.Count; row.P.Wins = nights.Count(n => n.Net > 0);
            KeystoneMicroADay.FillDays(row.P, rules, randomLives, 1, 1, detail);
            row.MnqNet = nights.Sum(n => n.Mnq); row.MgcNet = nights.Sum(n => n.Mgc);
            row.TargetNights = nights.Count(n => n.End == "TAKE PROFIT"); row.LossNights = nights.Count(n => n.End == "MAX LOSS"); row.AllStoppedNights = nights.Count(n => n.End == "ALL LEGS STOPPED"); row.SessionEndNights = nights.Count(n => n.End == "SESSION END");
            row.TargetAfterReversal = nights.Count(n => n.End == "TAKE PROFIT" && Math.Max(n.MnqLegs, n.MgcLegs) > 1);
            var full = nights.Where(n => n.End == "MAX LOSS" || n.End == "ALL LEGS STOPPED").ToList(); row.AvgFullLoss = full.Count == 0 ? 0 : full.Average(n => n.Net);
            foreach (var n in nights) row.EndLegs[Math.Min(7, Math.Max(1, Math.Max(n.MnqLegs, n.MgcLegs)))]++;
            row.InSampleNet = nights.Where(n => n.Date < splitAt).Sum(n => n.Net); row.OutSampleNet = nights.Where(n => n.Date >= splitAt).Sum(n => n.Net);
            row.Years = row.P.PropByYear.Count; row.YearsUp = row.P.PropByYear.Values.Count(v => v > 0);
            return row;
        }

        public static KeystoneAsianLabResult Run(List<KeystoneArcBar> oneMinute, KeystoneAsianLabGrid g, KeystonePropRules rules, Action<int, int> progress, Func<bool> cancelled)
        {
            var res = new KeystoneAsianLabResult { Rules = rules };
            var bars = (oneMinute ?? new List<KeystoneArcBar>()).Where(b => b != null).OrderBy(b => b.Time).ToList(); if (bars.Count == 0) return res;
            bool hasMnq = bars.Any(b => !(b.Symbol ?? "").StartsWith("MGC", StringComparison.OrdinalIgnoreCase)), hasMgc = bars.Any(b => (b.Symbol ?? "").StartsWith("MGC", StringComparison.OrdinalIgnoreCase));
            var combos = Combos(g, hasMnq, hasMgc); res.Combinations = combos.Count; if (combos.Count == 0) return res;
            var prepared = new Dictionary<string, List<KeystoneArcEngine.Asian75Session>>();
            foreach (var key in combos.Select(c => new { c.Scope, c.StartHhmm }).Distinct())
            {
                var cfg = new KeystoneArcAsianCombo { Scope = key.Scope, StartHhmm = key.StartHhmm, EndHhmm = g.EndHhmm, MnqDirection = "LONG", MgcDirection = "LONG", RiskMode = "CASH", LegLoss = 75, Reversals = 1, Target = 100, StartingQuantity = 1 }.Apply(new KeystoneArcRunConfig());
                prepared[key.Scope + "|" + key.StartHhmm] = KeystoneArcEngine.PrepareAsian75Sessions(bars, cfg);
            }
            var dates = prepared.Values.SelectMany(l => l.Where(x => x.OpeningComplete).Select(x => x.SessionDate)).Distinct().OrderBy(d => d).ToList();
            res.Nights = dates.Count; if (dates.Count > 0) { res.First = dates[0]; res.Last = dates[dates.Count - 1]; res.SplitAt = dates[Math.Min(dates.Count - 1, (int)(dates.Count * g.InSampleShare))]; }
            var rows = new KeystoneAsianLabRow[combos.Count]; int done = 0;
            var options = new System.Threading.Tasks.ParallelOptions { MaxDegreeOfParallelism = Math.Max(1, Environment.ProcessorCount - 1) };
            System.Threading.Tasks.Parallel.For(0, combos.Count, options, (i, state) =>
            {
                if (cancelled != null && cancelled()) { state.Stop(); return; }
                var c = combos[i]; var cfg = c.Apply(new KeystoneArcRunConfig());
                var events = KeystoneArcEngine.SimulateAsian75Sessions(prepared[c.Scope + "|" + c.StartHhmm], cfg);
                rows[i] = Row(c, Nights(events, g.CostPerContract), rules, res.SplitAt, false, 300);
                int k = System.Threading.Interlocked.Increment(ref done); if (progress != null) progress(k, combos.Count);
            });
            res.Cancelled = cancelled != null && cancelled();
            var all = rows.Where(r => r != null).ToList();
            if (!res.Cancelled) all.AddRange(TrendRows(all, bars, g, rules, res.SplitAt));
            if (!g.MixedBoth) all = all.Where(r => r.Combo.Scope != "BOTH" || r.Combo.MnqDirection == r.Combo.MgcDirection || IsTrend(r.Combo)).ToList();   // mixed rows were only helpers for TREND
            res.Rows = all.OrderByDescending(r => r.P.PropNet).ThenByDescending(r => r.P.Net).ToList();
            // data coverage per instrument and year: a missing instrument must be obvious, not silently tested on a few nights
            foreach (string sym in new[] { "MNQ", "MGC" })
            {
                if (sym == "MNQ" ? !hasMnq : !hasMgc) continue;
                var cfg = new KeystoneArcAsianCombo { Scope = sym, StartHhmm = g.StartTimes.Count > 0 ? g.StartTimes[0] : 1800, EndHhmm = g.EndHhmm, MnqDirection = "LONG", MgcDirection = "LONG", RiskMode = "CASH", LegLoss = 75, Reversals = 1, Target = 100, StartingQuantity = 1 }.Apply(new KeystoneArcRunConfig());
                foreach (var y in KeystoneArcEngine.PrepareAsian75Sessions(bars, cfg).GroupBy(x => x.SessionDate.Year).OrderBy(x => x.Key))
                    res.Coverage.Add(new KeystoneAsianCoverage { Symbol = sym, Year = y.Key, DaysWithBars = y.Count(), NightsOpened = y.Count(x => x.OpeningComplete) });
            }
            return res;
        }

        // Price just before each session's open, per instrument (last 1-minute close at or before the open).
        static Dictionary<DateTime, double> OpenPrices(List<KeystoneArcBar> bars, string symbol, IEnumerable<DateTime> nights, int startHhmm)
        {
            var list = bars.Where(b => string.Equals(b.Symbol, symbol, StringComparison.OrdinalIgnoreCase)).OrderBy(b => b.Time).ToList(); var output = new Dictionary<DateTime, double>();
            foreach (DateTime d in nights)
            {
                DateTime open = d.Date.AddHours(startHhmm / 100).AddMinutes(startHhmm % 100);
                int lo = 0, hi = list.Count - 1, f = -1; while (lo <= hi) { int mid = (lo + hi) / 2; if (list[mid].Time <= open) { f = mid; lo = mid + 1; } else hi = mid - 1; }
                if (f >= 0) output[d.Date] = list[f].Close;
            }
            return output;
        }

        // +1 LONG / −1 SHORT per night from the previous N nights' prices only.
        public static Dictionary<DateTime, int> TrendSignal(Dictionary<DateTime, double> prices, int n)
        {
            var output = new Dictionary<DateTime, int>(); var keys = prices.Keys.OrderBy(k => k).ToList();
            for (int i = n; i < keys.Count; i++)
            {
                double avg = 0; for (int k = i - n; k < i; k++) avg += prices[keys[k]]; avg /= n;
                output[keys[i]] = prices[keys[i]] >= avg ? 1 : -1;
            }
            return output;
        }

        // TREND rows: each night taken from the LONG or SHORT run of the same settings by the trend that night (cycles are independent per night).
        static List<KeystoneAsianLabRow> TrendRows(List<KeystoneAsianLabRow> rows, List<KeystoneArcBar> bars, KeystoneAsianLabGrid g, KeystonePropRules rules, DateTime splitAt)
        {
            var output = new List<KeystoneAsianLabRow>();
            if (g.TrendDays == null || g.TrendDays.Count == 0 || !g.Directions.Contains("LONG") || !g.Directions.Contains("SHORT")) return output;
            Func<KeystoneArcAsianCombo, string> baseKey = c => c.Scope + "|" + c.StartingQuantity + "|" + c.LegLoss + "|" + c.Reversals + "|" + c.Target + "|" + c.DailyLossLimit + "|" + c.StartHhmm;
            var byKey = rows.GroupBy(r => baseKey(r.Combo)).ToList();
            var dates = rows.SelectMany(r => r.Nights.Select(x => x.Date)).Distinct().OrderBy(d => d).ToList();
            foreach (int start in g.StartTimes.Distinct())
            {
                var mnqP = OpenPrices(bars, "MNQ", dates, start); var mgcP = OpenPrices(bars, "MGC", dates, start);
                foreach (int n in g.TrendDays.Where(x => x > 1).Distinct())
                {
                    var sMnq = TrendSignal(mnqP, n); var sMgc = TrendSignal(mgcP, n);
                    foreach (var grp in byKey.Where(k => k.First().Combo.StartHhmm == start))
                    {
                        var c0 = grp.First().Combo; var variants = grp.ToDictionary(r => r.Combo.MnqDirection + "/" + r.Combo.MgcDirection, r => r.Nights.ToDictionary(x => x.Date));
                        var nights = new List<KeystoneAsianNight>();
                        foreach (DateTime d in dates)
                        {
                            int sa, sb; bool hasA = sMnq.TryGetValue(d, out sa), hasB = sMgc.TryGetValue(d, out sb);
                            string mnqDir = c0.Scope == "MGC" ? "LONG" : (hasA ? (sa > 0 ? "LONG" : "SHORT") : null);
                            string mgcDir = c0.Scope == "MNQ" ? "LONG" : (hasB ? (sb > 0 ? "LONG" : "SHORT") : null);
                            if (mnqDir == null || mgcDir == null) continue;   // not enough history yet for the average: no trade
                            if (c0.Scope == "MNQ") mgcDir = mnqDir; if (c0.Scope == "MGC") mnqDir = mgcDir;
                            Dictionary<DateTime, KeystoneAsianNight> src; KeystoneAsianNight night;
                            if (variants.TryGetValue(mnqDir + "/" + mgcDir, out src) && src.TryGetValue(d, out night)) nights.Add(night.With(c0.Scope == "MNQ" ? mnqDir : c0.Scope == "MGC" ? mgcDir : (mnqDir == mgcDir ? mnqDir : "MNQ " + mnqDir + " / MGC " + mgcDir)));
                        }
                        if (nights.Count == 0) continue;
                        var tc = new KeystoneArcAsianCombo { Scope = c0.Scope, MnqDirection = c0.Scope == "MGC" ? "LONG" : "TREND" + n, MgcDirection = c0.Scope == "MNQ" ? "LONG" : "TREND" + n, RiskMode = "CASH", LegLoss = c0.LegLoss, Reversals = c0.Reversals, Target = c0.Target, DailyLossLimit = c0.DailyLossLimit, StartingQuantity = c0.StartingQuantity, StartHhmm = c0.StartHhmm, EndHhmm = c0.EndHhmm };
                        if (c0.Scope == "MNQ") tc.MgcDirection = tc.MnqDirection; if (c0.Scope == "MGC") tc.MnqDirection = tc.MgcDirection;
                        output.Add(Row(tc, nights, rules, splitAt, false, 300));
                    }
                }
            }
            return output;
        }

        // The selected row in full: every account, the day ledger and the curves, 2,000 random-order evaluations.
        public static void Detail(KeystoneAsianLabRow row, KeystonePropRules rules, DateTime splitAt) { var full = Row(row.Combo, row.Nights, rules, splitAt, true, 2000); row.P = full.P; }

        // The chart's night: legs, P/L, highest peak and lowest point per instrument and combined (marked on 1-minute closes).
        public static KeystoneAsianNightSummary NightSummary(List<KeystoneArcEvent> legs, Func<string, DateTime, double?> closeAt, IEnumerable<DateTime> minutes, DateTime until)
        {
            var s = new KeystoneAsianNightSummary(); var list = (legs ?? new List<KeystoneArcEvent>()).Where(e => e != null && e.SetupClass == "ASIA75").OrderBy(e => e.EntryTime).ToList(); if (list.Count == 0) return s;
            var symbols = list.Select(e => e.Symbol).Distinct().OrderBy(x => x).ToList();
            foreach (string sym in symbols) s.Sides.Add(new KeystoneAsianNightSide { Symbol = sym });
            DateTime first = list.Min(e => e.EntryTime), last = list.Max(e => e.ExitTime); if (until < last) last = until;
            var times = minutes.Where(t => t >= first && t <= last).Distinct().OrderBy(t => t).ToList(); if (times.Count == 0 || times[times.Count - 1] != last) times.Add(last);
            bool firstMark = true;
            foreach (DateTime t in times)
            {
                double combined = 0;
                foreach (var side in s.Sides)
                {
                    double v = 0;
                    foreach (var e in list.Where(e => e.Symbol == side.Symbol && e.EntryTime <= t))
                    {
                        if (e.ExitTime != DateTime.MinValue && e.ExitTime <= t) v += e.GrossPnl;
                        else { double? c = closeAt(side.Symbol, t); if (c.HasValue) v += (c.Value - e.Entry) * ((side.Symbol ?? "").StartsWith("MGC", StringComparison.OrdinalIgnoreCase) ? 10.0 : 2.0) * e.Quantity * (e.Direction == "SHORT" ? -1 : 1); }
                    }
                    if (firstMark || v > side.Peak) { side.Peak = v; side.PeakTime = t; } if (firstMark || v < side.Low) { side.Low = v; side.LowTime = t; }
                    side.Pnl = v; combined += v;
                }
                if (firstMark || combined > s.Combined.Peak) { s.Combined.Peak = combined; s.Combined.PeakTime = t; } if (firstMark || combined < s.Combined.Low) { s.Combined.Low = combined; s.Combined.LowTime = t; }
                s.Combined.Pnl = combined; firstMark = false;
            }
            foreach (var side in s.Sides)
            {
                var mine = list.Where(e => e.Symbol == side.Symbol && e.EntryTime <= until).ToList();
                side.Legs = mine.Count == 0 ? 0 : mine.Max(e => e.AsianLegNumber); side.MaxQty = mine.Count == 0 ? 0 : (int)mine.Max(e => e.Quantity);
            }
            s.Combined.Legs = s.Sides.Sum(x => x.Legs); s.Combined.MaxQty = s.Sides.Sum(x => x.MaxQty);
            var closing = list.Where(e => !(e.ReviewNote ?? "").StartsWith("REVERSAL LOSS", StringComparison.OrdinalIgnoreCase)).OrderBy(e => e.ExitTime).FirstOrDefault();
            if (list.Max(e => e.ExitTime) <= until) { s.EndTime = list.Max(e => e.ExitTime); s.End = closing == null ? "ALL LEGS STOPPED" : closing.Outcome == "WIN" ? "TAKE PROFIT" : closing.Outcome == "SESSION EXIT" ? "SESSION END" : closing.Outcome == "BREAKEVEN GUARD" ? "BREAKEVEN" : "MAX LOSS"; }
            else s.End = "RUNNING";
            return s;
        }

        // ---- WALK-FORWARD: does re-choosing the settings every year work? Each year uses ONLY the years before it. ----
        public sealed class WalkYear { public int Year; public KeystoneAsianLabRow Chosen, Hindsight; public double ChosenPlain, ChosenProp, HindPlain, HindProp, MinePlain, MineProp; public int ChosenPassed, ChosenPayouts, Nights; }
        public sealed class WalkResult { public List<WalkYear> Years = new List<WalkYear>(); public KeystoneMicroRow Adaptive = new KeystoneMicroRow(), Mine, BestFixed; public KeystoneAsianLabRow BestFixedRow; public int Lookback; public int YearsUp; }

        static KeystoneMicroRow Prop(IEnumerable<KeystoneAsianNight> nights, KeystonePropRules rules, bool detail)
        {
            var p = new KeystoneMicroRow { Days = nights.OrderBy(n => n.Date).Select(n => new KeystonePropDay { Day = n.Date.AddDays(1), Pnl = n.Net, Worst = Math.Min(0, n.Worst), Best = Math.Max(0, n.Best), Traded = true }).ToList() };
            p.Trades = p.Days.Count; p.Wins = p.Days.Count(d => d.Pnl > 0);
            KeystoneMicroADay.FillDays(p, rules, 0, 1, 1, detail);
            return p;
        }

        public static KeystoneAsianLabRow FindRow(KeystoneAsianLabResult res, KeystoneArcAsianCombo m)
        {
            if (res == null || m == null) return null;
            return res.Rows.FirstOrDefault(r => r.Combo.Scope == m.Scope && r.Combo.StartingQuantity == m.StartingQuantity && r.Combo.LegLoss == m.LegLoss && r.Combo.Reversals == m.Reversals && r.Combo.Target == m.Target
                && r.Combo.DailyLossLimit == m.DailyLossLimit && r.Combo.StartHhmm == m.StartHhmm && (m.Scope == "MGC" || r.Combo.MnqDirection == m.MnqDirection) && (m.Scope == "MNQ" || r.Combo.MgcDirection == m.MgcDirection));
        }

        // lookback = years of history used to choose (0 = every year before). The choice ranks by the prop result of a fresh
        // evaluation slot on those years, then plain net. The ADAPTIVE account trades each year's choice, one continuous slot.
        public static WalkResult WalkForward(KeystoneAsianLabResult res, KeystonePropRules rules, int lookback, KeystoneAsianLabRow mine)
        {
            var w = new WalkResult { Lookback = lookback }; if (res == null || res.Rows.Count == 0) return w;
            var years = res.Rows.SelectMany(r => r.Nights).Select(n => n.Date.Year).Distinct().OrderBy(y => y).ToList();
            var stitched = new List<KeystoneAsianNight>();
            foreach (int y in years.Skip(1))
            {
                int from = lookback <= 0 ? years[0] : y - lookback;
                var scored = res.Rows.Select(r => new { Row = r, Train = r.Nights.Where(n => n.Date.Year >= from && n.Date.Year < y).ToList(), Test = r.Nights.Where(n => n.Date.Year == y).ToList() }).Where(x => x.Train.Count > 0 && x.Test.Count > 0).ToList();
                if (scored.Count == 0) continue;
                var trained = scored.Select(x => new { x.Row, x.Test, P = Prop(x.Train, rules, false) }).OrderByDescending(x => x.P.PropNet).ThenByDescending(x => x.P.Net).ToList();
                var pick = trained[0];
                var test = Prop(pick.Test, rules, false);
                var hind = scored.Select(x => new { x.Row, P = Prop(x.Test, rules, false) }).OrderByDescending(x => x.P.PropNet).ThenByDescending(x => x.P.Net).First();
                var wy = new WalkYear { Year = y, Chosen = pick.Row, ChosenPlain = test.Net, ChosenProp = test.PropNet, ChosenPassed = test.Passed, ChosenPayouts = test.Payouts, Nights = pick.Test.Count, Hindsight = hind.Row, HindPlain = hind.P.Net, HindProp = hind.P.PropNet };
                if (mine != null) { var mt = Prop(mine.Nights.Where(n => n.Date.Year == y), rules, false); wy.MinePlain = mt.Net; wy.MineProp = mt.PropNet; }
                w.Years.Add(wy); stitched.AddRange(pick.Test);
            }
            w.YearsUp = w.Years.Count(x => x.ChosenProp > 0);
            w.Adaptive = Prop(stitched, rules, true);
            if (w.Years.Count > 0)
            {
                var tested = new HashSet<int>(w.Years.Select(x => x.Year));
                if (mine != null) w.Mine = Prop(mine.Nights.Where(n => tested.Contains(n.Date.Year)), rules, false);
                var fixedBest = res.Rows.Select(r => new { r, P = Prop(r.Nights.Where(n => tested.Contains(n.Date.Year)), rules, false) }).OrderByDescending(x => x.P.PropNet).First();
                w.BestFixed = fixedBest.P; w.BestFixedRow = fixedBest.r;
            }
            return w;
        }

        public static string WalkVerdict(WalkResult w)
        {
            if (w == null || w.Years.Count == 0) return "Load at least two calendar years: the walk-forward chooses each year's settings from the years before it.";
            Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            string a = "ADAPTIVE (re-chosen every year from " + (w.Lookback <= 0 ? "all earlier years" : "the last " + w.Lookback + " year" + (w.Lookback == 1 ? "" : "s")) + ", never looking ahead): prop " + m(w.Adaptive.PropNet) + ", plain " + m(w.Adaptive.Net) + ", positive in " + w.YearsUp + " of " + w.Years.Count + " years. ";
            if (w.Adaptive.PropNet > 0 && w.YearsUp * 2 > w.Years.Count) a += "→ The strategy ADAPTS: choosing the settings from the past would have made money going forward.";
            else if (w.Adaptive.PropNet > 0) a += "→ Made money overall but lost in most years: fragile, depends on one or two good years.";
            else a += "→ It does NOT adapt: the settings that worked last year did not work the next year. The best rows in RANKING are hindsight.";
            if (w.BestFixed != null) a += " For comparison, the single best fixed row in hindsight made " + m(w.BestFixed.PropNet) + " (" + w.BestFixedRow.Label + ") — you could only have known that afterwards.";
            if (w.Mine != null) a += " YOUR SETUP over the same years: prop " + m(w.Mine.PropNet) + ", plain " + m(w.Mine.Net) + ".";
            return a;
        }

        // Which value of each setting wins most often: count, % of rows that made money for prop, median and best prop net.
        public sealed class Impact { public string Setting = string.Empty, Value = string.Empty; public int Rows, Profitable; public double Median, Best, AvgFirstPayoutDays, AvgBlowups, AvgFullLossNights; }
        // Accounts lost: failed evaluations + funded accounts that hit the drawdown.
        public static int Blowups(KeystoneAsianLabRow r) { return Math.Max(0, r.P.Bought - r.P.Passed - 1) + r.P.FundedLost; }

        // REVERSALS × TAKE PROFIT: the best combination of each pair (over the other settings) — the trade-off in one table.
        public sealed class Cell { public int Reversals; public double Target; public KeystoneAsianLabRow Best; }
        public static List<Cell> Matrix(List<KeystoneAsianLabRow> rows)
        {
            return rows.GroupBy(r => new { r.Combo.Reversals, r.Combo.Target }).Select(g => new Cell { Reversals = g.Key.Reversals, Target = g.Key.Target, Best = g.OrderByDescending(r => r.P.PropNet).First() }).OrderBy(c => c.Reversals).ThenBy(c => c.Target).ToList();
        }

        public static List<Impact> Impacts(List<KeystoneAsianLabRow> rows)
        {
            var output = new List<Impact>();
            var settings = new List<Tuple<string, Func<KeystoneArcAsianCombo, string>>>
            {
                Tuple.Create("INSTRUMENTS", (Func<KeystoneArcAsianCombo, string>)(c => c.Scope)),
                Tuple.Create("DIRECTION", (Func<KeystoneArcAsianCombo, string>)(c => c.Scope == "MGC" ? c.MgcDirection : c.Scope == "MNQ" || c.MnqDirection == c.MgcDirection ? c.MnqDirection : "MIXED")),
                Tuple.Create("STARTING MICROS", (Func<KeystoneArcAsianCombo, string>)(c => c.StartingQuantity.ToString())),
                Tuple.Create("LEG LOSS $", (Func<KeystoneArcAsianCombo, string>)(c => c.LegLoss.ToString("0"))),
                Tuple.Create("REVERSALS", (Func<KeystoneArcAsianCombo, string>)(c => c.Reversals.ToString())),
                Tuple.Create("TAKE PROFIT $", (Func<KeystoneArcAsianCombo, string>)(c => c.Target.ToString("0"))),
                Tuple.Create("MAX LOSS $", (Func<KeystoneArcAsianCombo, string>)(c => c.DailyLossLimit > 0 ? c.DailyLossLimit.ToString("0") : "AUTO")),
                Tuple.Create("START", (Func<KeystoneArcAsianCombo, string>)(c => c.StartHhmm.ToString("0000"))),
            };
            foreach (var st in settings)
            {
                var groups = rows.GroupBy(r => st.Item2(r.Combo)).ToList(); if (groups.Count < 2) continue;
                foreach (var g in groups.OrderBy(g => g.Key.Length).ThenBy(g => g.Key))
                {
                    var nets = g.Select(r => r.P.PropNet).OrderBy(v => v).ToList(); var paid = g.Where(r => r.P.Stats.HasPayout).ToList();
                    output.Add(new Impact { Setting = st.Item1, Value = g.Key, Rows = nets.Count, Profitable = nets.Count(v => v > 0), Median = nets[nets.Count / 2], Best = nets[nets.Count - 1], AvgFirstPayoutDays = paid.Count == 0 ? 0 : paid.Average(r => (double)r.P.Stats.CalendarDaysToFirstPayout), AvgBlowups = g.Average(r => (double)Blowups(r)), AvgFullLossNights = g.Average(r => (double)(r.LossNights + r.AllStoppedNights)) });
                }
            }
            return output;
        }

        // Plain-language advice from the numbers (no guessing): the best rows, whether they held up, and which values win.
        public static List<string> Advice(KeystoneAsianLabResult res)
        {
            var lines = new List<string>(); if (res == null || res.Rows.Count == 0) return lines;
            Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            var cov = res.Coverage.GroupBy(c => c.Symbol).Select(g => new { Symbol = g.Key, Nights = g.Sum(x => x.NightsOpened), Years = g.Count() }).ToList();
            if (cov.Count == 2 && Math.Min(cov[0].Nights, cov[1].Nights) < 0.8 * Math.Max(cov[0].Nights, cov[1].Nights))
            {
                var low = cov.OrderBy(c => c.Nights).First(); var high = cov.OrderBy(c => c.Nights).Last();
                lines.Add("WARNING • DATA: " + low.Symbol + " has only " + low.Nights + " nights vs " + high.Nights + " for " + high.Symbol + " — every " + low.Symbol + " and BOTH result is measured on less data. See DATA COVERAGE below and reload " + low.Symbol + " before trusting those rows.");
            }
            var top = res.Rows[0];
            int profitable = res.Rows.Count(r => r.P.PropNet > 0);
            lines.Add(profitable + " of " + res.Rows.Count + " combinations made money for prop over " + res.Nights + " nights (" + res.First.ToString("yyyy-MM-dd") + " → " + res.Last.ToString("yyyy-MM-dd") + ").");
            lines.Add("BEST: " + top.Label + " → prop " + m(top.P.PropNet) + " (" + top.P.Passed + " passed of " + top.P.Bought + " evaluations, " + top.P.Payouts + " payouts" + (top.P.Stats.HasPayout ? ", first payout after " + top.P.Stats.CalendarDaysToFirstPayout + " days" : ", no payout") + ").");
            lines.Add(top.OutSampleNet > 0 ? "It also made money on the last 30% of nights (" + m(top.OutSampleNet) + ") — the ranking did not depend only on the early data." : "WARNING: on the last 30% of nights it lost " + m(top.OutSampleNet) + " — the best row may be a lucky fit to the early data.");
            lines.Add(top.YearsUp == top.Years ? "It made money in every year tested (" + top.Years + ")." : "It made money in " + top.YearsUp + " of " + top.Years + " years — check EACH YEAR before trusting it.");
            foreach (string sc in new[] { "MNQ", "MGC", "BOTH" })
            {
                var b = res.Rows.Where(r => r.Combo.Scope == sc).OrderByDescending(r => r.P.PropNet).FirstOrDefault();
                if (b != null) lines.Add("Best " + sc + ": " + b.Label + " → " + m(b.P.PropNet) + " • plain " + m(b.P.Net) + " • " + (b.P.Stats.HasPayout ? "first payout " + b.P.Stats.CalendarDaysToFirstPayout + " days" : "never paid"));
            }
            var robust = res.Rows.Where(r => r.P.PropNet > 0 && r.OutSampleNet > 0 && r.YearsUp == r.Years).OrderByDescending(r => r.P.PropNet).FirstOrDefault();
            lines.Add(robust != null ? "STRONGEST (profitable every year AND on the unseen last 30%): " + robust.Label + " → " + m(robust.P.PropNet) + "." : "No combination was profitable in every year AND on the unseen last 30% — nothing here is proven yet.");
            var trendBest = res.Rows.Where(r => IsTrend(r.Combo)).OrderByDescending(r => r.P.PropNet).FirstOrDefault();
            if (trendBest != null)
            {
                var same = res.Rows.Where(r => !IsTrend(r.Combo) && r.Combo.Scope == trendBest.Combo.Scope && r.Combo.StartingQuantity == trendBest.Combo.StartingQuantity && r.Combo.LegLoss == trendBest.Combo.LegLoss && r.Combo.Reversals == trendBest.Combo.Reversals && r.Combo.Target == trendBest.Combo.Target && r.Combo.DailyLossLimit == trendBest.Combo.DailyLossLimit && r.Combo.StartHhmm == trendBest.Combo.StartHhmm && (r.Combo.Scope != "BOTH" || r.Combo.MnqDirection == r.Combo.MgcDirection)).ToList();
                lines.Add("TREND (direction chosen every night from the trend): best " + trendBest.Label + " → prop " + m(trendBest.P.PropNet) + ", plain " + m(trendBest.P.Net) + ", years + " + trendBest.YearsUp + "/" + trendBest.Years + ", unseen 30% " + m(trendBest.OutSampleNet)
                    + (same.Count > 0 ? " • the same settings with a fixed direction: " + string.Join(" / ", same.Select(x => (x.Combo.Scope == "MGC" ? x.Combo.MgcDirection : x.Combo.MnqDirection) + " " + m(x.P.PropNet) + " (plain " + m(x.P.Net) + ")")) : ""));
                int trendWins = 0, pairs = 0;
                foreach (var t in res.Rows.Where(r => IsTrend(r.Combo)))
                {
                    var fixedRows = res.Rows.Where(r => !IsTrend(r.Combo) && r.Combo.Scope == t.Combo.Scope && r.Combo.StartingQuantity == t.Combo.StartingQuantity && r.Combo.LegLoss == t.Combo.LegLoss && r.Combo.Reversals == t.Combo.Reversals && r.Combo.Target == t.Combo.Target && r.Combo.DailyLossLimit == t.Combo.DailyLossLimit && r.Combo.StartHhmm == t.Combo.StartHhmm && (r.Combo.Scope != "BOTH" || r.Combo.MnqDirection == r.Combo.MgcDirection)).ToList();
                    if (fixedRows.Count == 0) continue; pairs++; if (t.P.Net > fixedRows.Max(x => x.P.Net)) trendWins++;
                }
                if (pairs > 0) lines.Add("TREND beat BOTH fixed directions (plain account) in " + trendWins + " of " + pairs + " settings.");
            }
            var byRev = res.Rows.GroupBy(r => r.Combo.Reversals).OrderBy(g => g.Key).Select(g => g.Key + " rev: median " + m(g.Select(r => r.P.PropNet).OrderBy(v => v).ElementAt(g.Count() / 2)) + ", " + g.Average(r => (double)Blowups(r)).ToString("0.0") + " accounts lost, " + g.Average(r => 100.0 * r.TargetNights / Math.Max(1, r.Nights.Count)).ToString("0") + "% take-profit nights").ToList();
            if (byRev.Count > 1) lines.Add("REVERSALS TRADE-OFF (more legs = more take-profit nights but bigger full losses): " + string.Join(" • ", byRev));
            foreach (var imp in Impacts(res.Rows).GroupBy(x => x.Setting))
            {
                var best = imp.OrderByDescending(x => x.Median).First(); var worst = imp.OrderBy(x => x.Median).First();
                lines.Add(imp.Key + ": " + best.Value + " is best on the median (" + m(best.Median) + ", " + best.Profitable + "/" + best.Rows + " profitable)" + (worst.Value != best.Value ? " • " + worst.Value + " is worst (" + m(worst.Median) + ")" : ""));
            }
            return lines;
        }
    }

    public sealed class KeystoneMoveRow
    {
        public string Set = string.Empty, Symbol = string.Empty, Kind = string.Empty; public bool Aggr; public DateTime Time; public int Year;
        public double Entry, Gap, Drop, Mfe, Mae, MaeBefore, Close, GapLow, GapHigh; public int MfeMinutes; public double[] Heat;
    }

    public sealed class KeystoneMoveStats
    {
        public string Label = string.Empty; public int N;
        public double UpPct, CloseMed, CloseAvg, MfeP25, MfeP50, MfeP75, MfeP90, MaeP50, MaeP75, MaeP90, BeforeP50, BeforeP75, MfeMinutesMed;
        public double[] ReachPct, HeatMed;
    }

    public sealed class KeystoneMoveBracket { public double Tp, Sl, PerTradePts, Dollars, WinPct, LossPct, ClosePct; public int N; }

    public sealed class KeystoneMoveGroup
    {
        public string Set = string.Empty, Symbol = string.Empty; public List<KeystoneMoveRow> Rows = new List<KeystoneMoveRow>();
        public KeystoneMoveStats All; public List<KeystoneMoveStats> Years = new List<KeystoneMoveStats>();
        public KeystoneMoveBracket Best; public Dictionary<int, KeystoneMoveBracket> BestByYear = new Dictionary<int, KeystoneMoveBracket>(), BestOnYear = new Dictionary<int, KeystoneMoveBracket>();
        public bool EveryYear; public double PerYearDollars, WorstYearDollars;
        public string Name { get { return KeystoneMoveStudy.SetName(Set) + " • " + Symbol; } }
    }

    public sealed class KeystoneMoveBucket { public string Factor = string.Empty, Bucket = string.Empty; public KeystoneMoveStats Stats; public double Dollars; }

    public static class KeystoneMoveStudy
    {
        static readonly double[] MnqLevels = { 10, 20, 25, 30, 40, 50, 60, 75, 100, 125, 150, 200, 250, 300 }, MgcLevels = { 1, 2, 3, 4, 5, 6, 8, 10, 12, 15, 20, 25, 30 };
        static readonly double[] MnqStops = { 10, 15, 20, 25, 30, 40, 50, 60, 75, 100, 150, 200 }, MgcStops = { 1, 1.5, 2, 3, 4, 5, 6, 8, 10, 15, 20 };
        public static bool IsMgc(string s) { return string.Equals(s, "MGC", StringComparison.OrdinalIgnoreCase); }
        public static double[] Levels(string symbol) { return IsMgc(symbol) ? MgcLevels : MnqLevels; }
        public static double[] Stops(string symbol) { return IsMgc(symbol) ? MgcStops : MnqStops; }
        public static double PointValue(string symbol) { return IsMgc(symbol) ? 10.0 : 2.0; }
        public static double Cost(string symbol) { return 2 * 0.62 + (IsMgc(symbol) ? 0.1 * 10 : 0.25 * 2); }   // per contract: commission both sides + 1 tick
        public static string F(string symbol, double v) { return double.IsNaN(v) ? "–" : v.ToString(IsMgc(symbol) ? "0.0" : "0.#", CultureInfo.InvariantCulture); }
        public const string Baseline = "BASELINE";
        public static string SetName(string set)
        {
            if (set == Baseline) return "NO SETUP • BUY AT THE START TIME";
            bool aggr = set.EndsWith("+AGGR"); string core = aggr ? set.Substring(0, set.Length - 5) : set;
            string name = KeystoneGoldenStudy.Universes.Contains(core) ? KeystoneGoldenStudy.UniverseName(core) : core;
            return aggr ? name + " • AGGRESSION ONLY" : name;
        }

        // The walk shared by every strategy: from the fill minute to the close, in the trade's direction (1 = long, −1 = short).
        public static void Walk(KeystoneArcEvent e, List<KeystoneArcBar> raw, int idx, int dir, DateTime closeLimit, string symbol, bool skipFillMinuteGain = false)
        {
            double[] levels = Levels(symbol); var heat = new double[levels.Length]; for (int k = 0; k < heat.Length; k++) heat[k] = double.NaN;
            double mfe = 0, mae = 0, maeBefore = 0, last = e.Entry; int mfeAt = 0, n = 0;
            for (int i = idx; i < raw.Count && raw[i].Time <= closeLimit; i++, n++)
            {
                var b = raw[i];
                double up = dir > 0 ? b.High - e.Entry : e.Entry - b.Low, down = dir > 0 ? e.Entry - b.Low : b.High - e.Entry;
                if (skipFillMinuteGain && i == idx) up = 0;   // a limit / stop fill: the minute's high may have come before the fill
                mae = Math.Max(mae, down);
                if (up > mfe) { mfe = up; maeBefore = mae; mfeAt = (int)(b.Time - raw[idx].Time).TotalMinutes + 1; }
                for (int k = 0; k < levels.Length; k++) if (double.IsNaN(heat[k]) && up >= levels[k] - 1e-9) heat[k] = mae;
                last = b.Close;
            }
            if (n == 0) return;
            e.MoveMfe = mfe; e.MoveMae = mae; e.MoveMaeBeforeMfe = maeBefore; e.MoveClose = dir * (last - e.Entry); e.MoveMfeMinutes = mfeAt; e.MoveHeat = heat;
        }

        static int FirstAtOrAfter(List<KeystoneArcBar> raw, DateTime t) { int lo = 0, hi = raw.Count; while (lo < hi) { int mid = (lo + hi) / 2; if (raw[mid].Time >= t) hi = mid; else lo = mid + 1; } return lo; }

        // ANY strategy's entries (BH, FVG, ASIAN legs, RECOIL…): measured from the entry minute to closeHhmm the same day
        // (New York), long or short. Entries already measured (GOLDEN) are kept.
        public static int MeasureAll(List<KeystoneArcEvent> events, List<KeystoneArcBar> oneMinute, int closeHhmm)
        {
            int measured = 0; if (events == null || oneMinute == null) return 0;
            var bySym = oneMinute.GroupBy(b => (b.Symbol ?? "").ToUpperInvariant()).ToDictionary(g => g.Key, g => g.OrderBy(b => b.Time).ToList());
            foreach (var e in events)
            {
                if (e == null || e.EntryTime == DateTime.MinValue || double.IsNaN(e.Entry) || e.Entry <= 0) continue;
                if (e.MoveHeat != null) { measured++; continue; }
                List<KeystoneArcBar> raw; if (!bySym.TryGetValue((e.Symbol ?? "").ToUpperInvariant(), out raw) || raw.Count == 0) continue;
                DateTime close = e.EntryTime.Date.AddHours(closeHhmm / 100).AddMinutes(closeHhmm % 100); if (close <= e.EntryTime) close = close.AddDays(1);
                int idx = FirstAtOrAfter(raw, e.EntryTime); if (idx >= raw.Count || raw[idx].Time > close) continue;
                Walk(e, raw, idx, string.Equals(e.Direction, "SHORT", StringComparison.OrdinalIgnoreCase) ? -1 : 1, close, e.Symbol);
                if (e.MoveHeat != null) measured++;
            }
            return measured;
        }

        public static KeystoneMoveRow Row(string set, KeystoneArcEvent e)
        {
            if (e == null || e.MoveHeat == null || double.IsNaN(e.MoveMfe)) return null;
            DateTime t = e.EntryTime == DateTime.MinValue ? e.TriggerTime : e.EntryTime;
            return new KeystoneMoveRow { Set = set, Symbol = e.Symbol, Kind = e.SetupClass ?? "", Aggr = e.StrengthTag == "AGGR", Time = t, Year = t.Year, Entry = e.Entry, Gap = e.FvgGap, GapLow = e.FvgLower, GapHigh = e.FvgUpper, Drop = e.FvgDrop, Mfe = e.MoveMfe, Mae = e.MoveMae, MaeBefore = e.MoveMaeBeforeMfe, Close = e.MoveClose, MfeMinutes = e.MoveMfeMinutes, Heat = e.MoveHeat };
        }

        // The same measurement with no setup: buy at the open of the first minute after the start time, every day.
        public static List<KeystoneMoveRow> BaselineRows(List<KeystoneArcBar> raw, string symbol, int startHhmm, int closeHhmm)
        {
            var output = new List<KeystoneMoveRow>(); if (raw == null) return output;
            double[] levels = Levels(symbol);
            int sm = startHhmm / 100 * 60 + startHhmm % 100, cm = closeHhmm / 100 * 60 + closeHhmm % 100;
            foreach (var g in raw.Where(b => string.Equals(b.Symbol, symbol, StringComparison.OrdinalIgnoreCase)).GroupBy(b => b.Time.Date).OrderBy(g => g.Key))
            {
                var list = g.Where(b => { int m = b.Time.Hour * 60 + b.Time.Minute; return m > sm && m <= cm; }).OrderBy(b => b.Time).ToList();
                if (list.Count < 10 || list[0].Time.Hour * 60 + list[0].Time.Minute != sm + 1) continue;      // the exact first minute must exist
                double entry = list[0].Open, mfe = 0, mae = 0, before = 0; int at = 0; var heat = new double[levels.Length]; for (int k = 0; k < heat.Length; k++) heat[k] = double.NaN;
                for (int i = 0; i < list.Count; i++)
                {
                    var b = list[i]; mae = Math.Max(mae, entry - b.Low); double up = b.High - entry;
                    if (up > mfe) { mfe = up; before = mae; at = i + 1; }
                    for (int k = 0; k < levels.Length; k++) if (double.IsNaN(heat[k]) && up >= levels[k] - 1e-9) heat[k] = mae;
                }
                output.Add(new KeystoneMoveRow { Set = Baseline, Symbol = symbol, Kind = "START", Time = list[0].Time, Year = list[0].Time.Year, Entry = entry, Mfe = mfe, Mae = mae, MaeBefore = before, Close = list[list.Count - 1].Close - entry, MfeMinutes = at, Heat = heat });
            }
            return output;
        }

        static double Pct(List<double> sorted, double p) { if (sorted.Count == 0) return double.NaN; double i = p * (sorted.Count - 1); int a = (int)Math.Floor(i), b = Math.Min(sorted.Count - 1, a + 1); return sorted[a] + (sorted[b] - sorted[a]) * (i - a); }

        public static KeystoneMoveStats Stats(string label, List<KeystoneMoveRow> rows, string symbol)
        {
            var s = new KeystoneMoveStats { Label = label, N = rows.Count }; double[] levels = Levels(symbol);
            s.ReachPct = new double[levels.Length]; s.HeatMed = new double[levels.Length];
            if (rows.Count == 0) { for (int k = 0; k < levels.Length; k++) s.HeatMed[k] = double.NaN; s.UpPct = s.CloseMed = s.CloseAvg = s.MfeP25 = s.MfeP50 = s.MfeP75 = s.MfeP90 = s.MaeP50 = s.MaeP75 = s.MaeP90 = s.BeforeP50 = s.BeforeP75 = s.MfeMinutesMed = double.NaN; return s; }
            Func<Func<KeystoneMoveRow, double>, List<double>> sorted = f => rows.Select(f).OrderBy(v => v).ToList();
            var mfe = sorted(r => r.Mfe); var mae = sorted(r => r.Mae); var close = sorted(r => r.Close); var before = sorted(r => r.MaeBefore); var mins = sorted(r => r.MfeMinutes);
            s.UpPct = 100.0 * rows.Count(r => r.Close > 0) / rows.Count; s.CloseMed = Pct(close, 0.5); s.CloseAvg = rows.Average(r => r.Close);
            s.MfeP25 = Pct(mfe, 0.25); s.MfeP50 = Pct(mfe, 0.5); s.MfeP75 = Pct(mfe, 0.75); s.MfeP90 = Pct(mfe, 0.9);
            s.MaeP50 = Pct(mae, 0.5); s.MaeP75 = Pct(mae, 0.75); s.MaeP90 = Pct(mae, 0.9); s.BeforeP50 = Pct(before, 0.5); s.BeforeP75 = Pct(before, 0.75); s.MfeMinutesMed = Pct(mins, 0.5);
            for (int k = 0; k < levels.Length; k++)
            {
                var reached = rows.Where(r => r.Heat != null && k < r.Heat.Length && !double.IsNaN(r.Heat[k])).Select(r => r.Heat[k]).OrderBy(v => v).ToList();
                s.ReachPct[k] = 100.0 * reached.Count / rows.Count; s.HeatMed[k] = Pct(reached, 0.5);
            }
            return s;
        }

        // Target tp / stop sl in points on these measured moves (stop first when the same minute reached both): win +tp, loss −sl,
        // otherwise closed at the session close. Dollars per 1 contract after costs.
        public static KeystoneMoveBracket Bracket(List<KeystoneMoveRow> rows, string symbol, double tp, double sl)
        {
            var b = new KeystoneMoveBracket { Tp = tp, Sl = sl, N = rows.Count }; if (rows.Count == 0) return b;
            int k = Array.IndexOf(Levels(symbol), tp); double sum = 0; int w = 0, l = 0, c = 0;
            foreach (var r in rows)
            {
                double h = k >= 0 && r.Heat != null && k < r.Heat.Length ? r.Heat[k] : double.NaN;
                if (!double.IsNaN(h) && h < sl - 1e-9) { sum += tp; w++; }
                else if (!double.IsNaN(h) || r.Mae >= sl - 1e-9) { sum -= sl; l++; }
                else { sum += Math.Max(-sl, r.Close); c++; }
            }
            b.PerTradePts = sum / rows.Count; b.Dollars = b.PerTradePts * PointValue(symbol) - Cost(symbol);
            b.WinPct = 100.0 * w / rows.Count; b.LossPct = 100.0 * l / rows.Count; b.ClosePct = 100.0 * c / rows.Count;
            return b;
        }

        public static KeystoneMoveBracket BestBracket(List<KeystoneMoveRow> rows, string symbol)
        {
            KeystoneMoveBracket best = null;
            foreach (double tp in Levels(symbol)) foreach (double sl in Stops(symbol)) { var b = Bracket(rows, symbol, tp, sl); if (best == null || b.Dollars > best.Dollars + 1e-9) best = b; }
            return best ?? new KeystoneMoveBracket();
        }

        public static KeystoneMoveGroup Group(string set, string symbol, List<KeystoneMoveRow> rows)
        {
            var g = new KeystoneMoveGroup { Set = set, Symbol = symbol, Rows = rows.OrderBy(r => r.Time).ToList() };
            g.All = Stats("ALL YEARS", g.Rows, symbol); g.Best = BestBracket(g.Rows, symbol);
            var years = g.Rows.Select(r => r.Year).Distinct().OrderBy(y => y).ToList(); bool every = true; double worst = double.MaxValue; int counted = 0;
            foreach (int y in years)
            {
                var yr = g.Rows.Where(r => r.Year == y).ToList();
                g.Years.Add(Stats(y.ToString(), yr, symbol)); g.BestByYear[y] = BestBracket(yr, symbol);
                var on = Bracket(yr, symbol, g.Best.Tp, g.Best.Sl); g.BestOnYear[y] = on;
                if (yr.Count >= 10) { counted++; if (on.Dollars <= 0) every = false; worst = Math.Min(worst, on.Dollars); }
            }
            g.EveryYear = every && counted > 0; g.WorstYearDollars = counted == 0 ? double.NaN : worst;
            double spanYears = g.Rows.Count < 2 ? 1 : Math.Max(0.25, (g.Rows[g.Rows.Count - 1].Time - g.Rows[0].Time).TotalDays / 365.25);
            g.PerYearDollars = g.Best.Dollars * g.Rows.Count / spanYears;
            return g;
        }

        // Every entry set × instrument (+ aggression-only versions) + the no-setup baseline; ranked: works every year first, then $ per year.
        public static List<KeystoneMoveGroup> Run(Dictionary<string, List<KeystoneArcEvent>> sets, List<KeystoneMoveRow> baseline)
        {
            var groups = new List<KeystoneMoveGroup>();
            foreach (var kv in sets ?? new Dictionary<string, List<KeystoneArcEvent>>())
            {
                var rows = (kv.Value ?? new List<KeystoneArcEvent>()).Select(e => Row(kv.Key, e)).Where(r => r != null).ToList();
                foreach (string sym in new[] { "MNQ", "MGC" })
                {
                    var mine = rows.Where(r => string.Equals(r.Symbol, sym, StringComparison.OrdinalIgnoreCase)).ToList(); if (mine.Count == 0) continue;
                    groups.Add(Group(kv.Key, sym, mine));
                    var aggr = mine.Where(r => r.Aggr).ToList();
                    if (aggr.Count >= 10 && aggr.Count < mine.Count) groups.Add(Group(kv.Key + "+AGGR", sym, aggr));
                }
            }
            foreach (string sym in new[] { "MNQ", "MGC" }) { var b = (baseline ?? new List<KeystoneMoveRow>()).Where(r => r.Symbol == sym).ToList(); if (b.Count > 0) groups.Add(Group(Baseline, sym, b)); }
            return groups.OrderByDescending(g => g.EveryYear && g.Rows.Count >= 20).ThenByDescending(g => g.PerYearDollars).ToList();
        }

        // WHY: the same group split by what was known at the entry, each bucket measured with the group's best target / stop.
        public static List<KeystoneMoveBucket> Why(KeystoneMoveGroup g)
        {
            var output = new List<KeystoneMoveBucket>(); var rows = g.Rows; string sym = g.Symbol; if (rows.Count == 0) return output;
            Action<string, Func<KeystoneMoveRow, string>, IEnumerable<string>> add = (factor, key, order) =>
            {
                foreach (string b in order)
                {
                    var part = rows.Where(r => key(r) == b).ToList(); if (part.Count == 0) continue;
                    output.Add(new KeystoneMoveBucket { Factor = factor, Bucket = b, Stats = Stats(b, part, sym), Dollars = Bracket(part, sym, g.Best.Tp, g.Best.Sl).Dollars });
                }
            };
            add("SETUP", r => r.Kind == "DT" ? "BH + FVG SAME CANDLE" : r.Kind, rows.Select(r => r.Kind == "DT" ? "BH + FVG SAME CANDLE" : r.Kind).Distinct().OrderBy(x => x));
            add("AGGRESSION (PUSH DOWN BEFORE)", r => r.Aggr ? "WITH AGGRESSION" : "WITHOUT", new[] { "WITH AGGRESSION", "WITHOUT" });
            add("ENTRY HOUR", r => r.Time.Hour.ToString("00") + ":00", rows.Select(r => r.Time.Hour.ToString("00") + ":00").Distinct().OrderBy(x => x));
            add("WEEKDAY", r => r.Time.DayOfWeek.ToString().ToUpperInvariant(), new[] { "MONDAY", "TUESDAY", "WEDNESDAY", "THURSDAY", "FRIDAY" });
            Action<string, Func<KeystoneMoveRow, double>> terciles = (factor, val) =>
            {
                var vals = rows.Select(val).Where(v => !double.IsNaN(v) && v > 0).OrderBy(v => v).ToList(); if (vals.Count < 15) return;
                double a = Pct(vals, 1.0 / 3), b = Pct(vals, 2.0 / 3);
                Func<KeystoneMoveRow, string> key = r => { double v = val(r); if (double.IsNaN(v) || v <= 0) return "NONE"; return v <= a ? "SMALL (≤ " + F(sym, a) + ")" : v <= b ? "MEDIUM (≤ " + F(sym, b) + ")" : "LARGE (> " + F(sym, b) + ")"; };
                add(factor, key, new[] { "SMALL (≤ " + F(sym, a) + ")", "MEDIUM (≤ " + F(sym, b) + ")", "LARGE (> " + F(sym, b) + ")", "NONE" });
            };
            terciles("FVG GAP SIZE (POINTS)", r => r.Gap);
            terciles("PUSH DOWN BEFORE THE SETUP (POINTS)", r => r.Drop);
            add("YEAR", r => r.Year.ToString(), rows.Select(r => r.Year.ToString()).Distinct().OrderBy(x => x));
            return output;
        }

        public static string Verdict(List<KeystoneMoveGroup> groups)
        {
            if (groups == null || groups.Count == 0) return "No measured entries yet.";
            var top = groups[0]; var bases = groups.Where(g => g.Set == Baseline).ToDictionary(g => g.Symbol);
            KeystoneMoveGroup b; string vsBase = bases.TryGetValue(top.Symbol, out b) ? " The no-setup baseline (buy at the start every day) makes " + (b.Best.Dollars < 0 ? "−$" : "$") + Math.Abs(b.Best.Dollars).ToString("N0", CultureInfo.InvariantCulture) + " per trade at its own best target / stop" + (top.Best.Dollars > b.Best.Dollars ? " — the setup adds " + (top.Best.Dollars - b.Best.Dollars).ToString("N0", CultureInfo.InvariantCulture) + " $ per trade." : " — the setup does NOT beat buying blindly.") : "";
            return (top.EveryYear ? "BEST: " : "NOTHING WORKED IN EVERY YEAR. HIGHEST: ") + top.Name + " • target +" + F(top.Symbol, top.Best.Tp) + " / stop −" + F(top.Symbol, top.Best.Sl) + " pts • " + (top.Best.Dollars < 0 ? "−$" : "$") + Math.Abs(top.Best.Dollars).ToString("N1", CultureInfo.InvariantCulture) + " per trade per contract • about " + (top.PerYearDollars < 0 ? "−$" : "$") + Math.Abs(top.PerYearDollars).ToString("N0", CultureInfo.InvariantCulture) + " a year per contract • ended up on " + top.All.UpPct.ToString("0") + "% of the days." + vsBase;
        }

        public static string Csv(List<KeystoneMoveGroup> groups)
        {
            var sb = new StringBuilder();
            var anyLevels = MnqLevels.Length >= MgcLevels.Length ? MnqLevels.Length : MgcLevels.Length;
            sb.Append("set,symbol,date,time,year,setup,aggression,entry,fvg_gap,push_down,max_for_us,max_against,against_before_best,close_vs_entry,minutes_to_best");
            for (int k = 0; k < anyLevels; k++) sb.Append(",level_").Append(k + 1).Append("_pts,level_").Append(k + 1).Append("_against_before");
            sb.AppendLine();
            foreach (var g in groups.Where(x => !x.Set.EndsWith("+AGGR")))
            {
                var lv = Levels(g.Symbol);
                foreach (var r in g.Rows)
                {
                    sb.Append(g.Set).Append(',').Append(g.Symbol).Append(',').Append(r.Time.ToString("yyyy-MM-dd")).Append(',').Append(r.Time.ToString("HH:mm")).Append(',').Append(r.Year).Append(',').Append(r.Kind).Append(',').Append(r.Aggr ? "AGGR" : "").Append(',')
                      .Append(r.Entry.ToString(CultureInfo.InvariantCulture)).Append(',').Append(r.Gap.ToString("0.##", CultureInfo.InvariantCulture)).Append(',').Append(r.Drop.ToString("0.##", CultureInfo.InvariantCulture)).Append(',')
                      .Append(r.Mfe.ToString("0.##", CultureInfo.InvariantCulture)).Append(',').Append(r.Mae.ToString("0.##", CultureInfo.InvariantCulture)).Append(',').Append(r.MaeBefore.ToString("0.##", CultureInfo.InvariantCulture)).Append(',').Append(r.Close.ToString("0.##", CultureInfo.InvariantCulture)).Append(',').Append(r.MfeMinutes);
                    for (int k = 0; k < anyLevels; k++) sb.Append(',').Append(k < lv.Length ? lv[k].ToString(CultureInfo.InvariantCulture) : "").Append(',').Append(k < lv.Length && r.Heat != null && k < r.Heat.Length && !double.IsNaN(r.Heat[k]) ? r.Heat[k].ToString("0.##", CultureInfo.InvariantCulture) : "");
                    sb.AppendLine();
                }
            }
            return sb.ToString();
        }

        public static string Html(List<KeystoneMoveGroup> groups, string range)
        {
            Func<string, string> e = s => (s ?? string.Empty).Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;");
            Func<double, string> m = v => double.IsNaN(v) ? "–" : (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N1", CultureInfo.InvariantCulture);
            Func<double, string> c = v => v > 0 ? "#3fd28b" : (v < 0 ? "#ff6b6b" : "#9aa4b2");
            var sb = new StringBuilder();
            sb.Append("<!doctype html><html><head><meta charset='utf-8'><title>Keystone Move Study</title><style>body{background:#0d1117;color:#e6edf3;font-family:Segoe UI,Arial,sans-serif;margin:0;padding:18px}h1{color:#f2c94c}h2{color:#56ccf2;margin:22px 0 6px}h3{color:#f2c94c;margin:14px 0 4px}.n{color:#9aa4b2;font-size:13px}.v{border:2px solid #f2c94c;border-radius:8px;padding:10px 14px;margin:10px 0;font-weight:600}table{border-collapse:collapse;width:100%;font-size:12.5px;margin-bottom:8px}th{color:#f2c94c;text-align:left;border-bottom:1px solid #30363d;padding:4px}td{padding:4px;border-bottom:1px solid #21262d}.wrap{overflow-x:auto}</style></head><body>");
            sb.Append("<h1>KEYSTONE ARC • MOVE STUDY</h1><div class='n'>").Append(e(range)).Append(" • every entry followed to the session close on 1-minute bars (no target, no stop) • dollars per 1 contract after costs (MNQ $").Append(Cost("MNQ").ToString("0.00")).Append(", MGC $").Append(Cost("MGC").ToString("0.00")).Append(" per round trip) • historical research only</div>");
            sb.Append("<div class='v'>").Append(e(Verdict(groups))).Append("</div>");
            sb.Append("<h2>RANKING • every entry set × instrument</h2><div class='wrap'><table><tr><th>#</th><th>ENTRIES</th><th>N</th><th>ENDED UP</th><th>MEDIAN FOR US</th><th>MEDIAN AGAINST</th><th>AGAINST BEFORE BEST</th><th>BEST TARGET / STOP</th><th>WIN / LOSS / CLOSED</th><th>$ / TRADE</th><th>$ / YEAR</th><th>SAME TARGET / STOP EACH YEAR</th></tr>");
            int i = 0;
            foreach (var g in groups) { i++; sb.Append("<tr><td>").Append(i).Append("</td><td>").Append(e(g.Name)).Append("</td><td>").Append(g.Rows.Count).Append("</td><td>").Append(g.All.UpPct.ToString("0")).Append("%</td><td>+").Append(F(g.Symbol, g.All.MfeP50)).Append("</td><td>−").Append(F(g.Symbol, g.All.MaeP50)).Append("</td><td>−").Append(F(g.Symbol, g.All.BeforeP50)).Append("</td><td>+").Append(F(g.Symbol, g.Best.Tp)).Append(" / −").Append(F(g.Symbol, g.Best.Sl)).Append("</td><td>").Append(g.Best.WinPct.ToString("0")).Append(" / ").Append(g.Best.LossPct.ToString("0")).Append(" / ").Append(g.Best.ClosePct.ToString("0")).Append("%</td><td style='color:").Append(c(g.Best.Dollars)).Append("'>").Append(m(g.Best.Dollars)).Append("</td><td style='color:").Append(c(g.PerYearDollars)).Append("'>").Append(m(g.PerYearDollars)).Append("</td><td style='color:").Append(g.EveryYear ? "#3fd28b" : "#ff6b6b").Append("'>").Append(g.EveryYear ? "✓ " : "✗ ").Append(e(string.Join(" • ", g.BestOnYear.Select(kv => kv.Key + " " + m(kv.Value.Dollars) + " (" + kv.Value.N + ")")))).Append("</td></tr>"); }
            sb.Append("</table></div>");
            foreach (var g in groups.Where(x => x.Set != Baseline).Take(6).Concat(groups.Where(x => x.Set == Baseline)))
            {
                sb.Append("<h2>").Append(e(g.Name)).Append("</h2><h3>YEAR BY YEAR (points)</h3><div class='wrap'><table><tr><th>YEAR</th><th>N</th><th>ENDED UP</th><th>CLOSE (MEDIAN)</th><th>FOR US 50% / 75% / 90%</th><th>AGAINST 50% / 75% / 90%</th><th>AGAINST BEFORE BEST 50% / 75%</th><th>BEST TARGET / STOP THAT YEAR</th><th>$ / TRADE THAT YEAR</th><th>OVERALL TARGET / STOP THAT YEAR</th></tr>");
                foreach (var s in new[] { g.All }.Concat(g.Years))
                {
                    int y; KeystoneMoveBracket by = null, on = null; if (int.TryParse(s.Label, out y)) { g.BestByYear.TryGetValue(y, out by); g.BestOnYear.TryGetValue(y, out on); } else { by = g.Best; on = g.Best; }
                    sb.Append("<tr><td>").Append(s.Label).Append("</td><td>").Append(s.N).Append("</td><td>").Append(s.UpPct.ToString("0")).Append("%</td><td>").Append(F(g.Symbol, s.CloseMed)).Append("</td><td>").Append(F(g.Symbol, s.MfeP50)).Append(" / ").Append(F(g.Symbol, s.MfeP75)).Append(" / ").Append(F(g.Symbol, s.MfeP90)).Append("</td><td>").Append(F(g.Symbol, s.MaeP50)).Append(" / ").Append(F(g.Symbol, s.MaeP75)).Append(" / ").Append(F(g.Symbol, s.MaeP90)).Append("</td><td>").Append(F(g.Symbol, s.BeforeP50)).Append(" / ").Append(F(g.Symbol, s.BeforeP75)).Append("</td><td>").Append(by == null ? "–" : "+" + F(g.Symbol, by.Tp) + " / −" + F(g.Symbol, by.Sl)).Append("</td><td style='color:").Append(by == null ? "#9aa4b2" : c(by.Dollars)).Append("'>").Append(by == null ? "–" : m(by.Dollars)).Append("</td><td style='color:").Append(on == null ? "#9aa4b2" : c(on.Dollars)).Append("'>").Append(on == null ? "–" : m(on.Dollars)).Append("</td></tr>");
                }
                sb.Append("</table></div><h3>HOW FAR DID IT GO</h3><div class='wrap'><table><tr><th>MOVE FOR US</th><th>REACHED (ALL)</th>");
                foreach (var s in g.Years) sb.Append("<th>").Append(s.Label).Append("</th>");
                sb.Append("<th>AGAINST US BEFORE REACHING IT (MEDIAN)</th></tr>");
                var lv = Levels(g.Symbol);
                for (int k = 0; k < lv.Length; k++) { sb.Append("<tr><td>+").Append(F(g.Symbol, lv[k])).Append("</td><td>").Append(g.All.ReachPct[k].ToString("0")).Append("%</td>"); foreach (var s in g.Years) sb.Append("<td>").Append(s.ReachPct[k].ToString("0")).Append("%</td>"); sb.Append("<td>−").Append(F(g.Symbol, g.All.HeatMed[k])).Append("</td></tr>"); }
                sb.Append("</table></div><h3>WHY • the same entries split by what was known at the entry ($ / trade at +").Append(F(g.Symbol, g.Best.Tp)).Append(" / −").Append(F(g.Symbol, g.Best.Sl)).Append(")</h3><div class='wrap'><table><tr><th>FACTOR</th><th>BUCKET</th><th>N</th><th>ENDED UP</th><th>FOR US (MEDIAN)</th><th>AGAINST (MEDIAN)</th><th>$ / TRADE</th></tr>");
                foreach (var w in Why(g)) sb.Append("<tr><td>").Append(e(w.Factor)).Append("</td><td>").Append(e(w.Bucket)).Append("</td><td>").Append(w.Stats.N).Append("</td><td>").Append(w.Stats.UpPct.ToString("0")).Append("%</td><td>+").Append(F(g.Symbol, w.Stats.MfeP50)).Append("</td><td>−").Append(F(g.Symbol, w.Stats.MaeP50)).Append("</td><td style='color:").Append(c(w.Dollars)).Append("'>").Append(m(w.Dollars)).Append("</td></tr>");
                sb.Append("</table></div>");
            }
            sb.Append("<h2>HOW TO READ IT</h2><p class='n'>FOR US = the highest point above the entry before the close • AGAINST = the lowest point below the entry before the close • AGAINST BEFORE BEST = how far it went against us before reaching its best point (the stop you needed to hold it) • ENDED UP = closed above the entry. BEST TARGET / STOP = the pair (from the measured moves) that made the most per trade: win if the target came before the stop, loss if the stop came first (the same minute counts as the stop), otherwise closed at the session close. SAME TARGET / STOP EACH YEAR = that overall pair applied to each year alone: ✓ if every year was positive. Compare every set with the NO SETUP baseline: a setup is only worth trading if it beats buying blindly at the start time.</p></body></html>");
            return sb.ToString();
        }
    }

    public static class KeystoneGoldenStudy
    {
        static readonly double[] MnqStops = { 10, 20, 30, 40, 50, 60, 80, 100, 150 }, MgcStops = { 1, 2, 3, 4, 5, 6, 8, 10, 15 };
        static readonly double[] MnqTargets = { 20, 30, 40, 50, 60, 80, 100, 120, 150, 200 }, MgcTargets = { 2, 3, 4, 5, 6, 8, 10, 12, 15, 20 };
        public static bool IsMgc(string s) { return string.Equals(s, "MGC", StringComparison.OrdinalIgnoreCase); }
        public static double[] StopLevels(string symbol) { return IsMgc(symbol) ? MgcStops : MnqStops; }
        public static double[] TargetLevels(string symbol) { return IsMgc(symbol) ? MgcTargets : MnqTargets; }
        public static double PointValue(string symbol) { return IsMgc(symbol) ? 10.0 : 2.0; }
        public static string Fmt(string symbol, double v) { return v.ToString(IsMgc(symbol) ? "0.0" : "0.##", CultureInfo.InvariantCulture); }

        // The detection settings that find every first setup with no filter, so the filters can be tried afterwards.
        public static KeystoneArcRunConfig UnfilteredConfig(KeystoneArcRunConfig cfg)
        {
            var c = cfg.ShallowCopy();
            // The FVG minimum gap stays: it defines what counts as an FVG (a sliver is not a setup and does not use up the day).
            c.GoldenSkipStopOverTarget = 0; c.GoldenMnqMaxStop = 0; c.GoldenMgcMaxStop = 0;
            if (string.Equals(c.GoldenAggression, "REQUIRED", StringComparison.OrdinalIgnoreCase)) c.GoldenAggression = "TAG";
            c.GoldenStrictFirst = 1;
            return c;
        }

        // Which entries the study looks at (each is its own detection run on the loaded bars).
        public static readonly string[] Universes = { "FIRST", "FIRST_BH", "FIRST_FVG", "EVERY_FVG" };
        public static string UniverseName(string u)
        {
            switch (u)
            {
                case "FIRST_BH": return "FIRST BH OF THE DAY";
                case "FIRST_FVG": return "FIRST 5M FVG OF THE DAY";
                case "EVERY_FVG": return "EVERY 5M FVG (all day)";
                default: return "FIRST SETUP OF THE DAY (BH or FVG, Step 1)";
            }
        }
        public static KeystoneArcRunConfig UniverseConfig(KeystoneArcRunConfig cfg, string u)
        {
            var c = UnfilteredConfig(cfg);
            if (u == "FIRST_BH") { c.GoldenUseBh = 1; c.GoldenFvgMode = "OFF"; }
            else if (u == "FIRST_FVG" || u == "EVERY_FVG")
            {
                c.GoldenUseBh = 0; if (string.Equals(c.GoldenFvgMode, "OFF", StringComparison.OrdinalIgnoreCase)) c.GoldenFvgMode = "BREAK";
                if (u == "EVERY_FVG") { c.GoldenTakeAll = 1; c.GoldenMaxTradesPerDay = 999; }
            }
            return c;
        }

        // The same filters on every set of entries, side by side (setup type is the set itself).
        public static List<KeystoneGoldenStudyResult> CompareUniverses(Dictionary<string, List<KeystoneArcEvent>> sets, KeystoneGoldenFilter f, KeystoneArcRunConfig cfg)
        {
            var output = new List<KeystoneGoldenStudyResult>();
            if (sets == null) return output;
            foreach (string u in Universes)
            {
                List<KeystoneArcEvent> list; if (!sets.TryGetValue(u, out list) || list == null) continue;
                var copy = f.Copy(); copy.Setup = "ALL";
                if (u == "EVERY_FVG") copy.MaxTries = 999;
                output.Add(Run(list, copy, cfg, u));
            }
            return output;
        }

        // The filters that match the Step 1 settings.
        public static KeystoneGoldenFilter FromConfig(KeystoneArcRunConfig cfg)
        {
            var f = new KeystoneGoldenFilter();
            if (cfg == null) return f;
            f.MnqMinGap = cfg.GoldenMnqMinGap; f.MgcMinGap = cfg.GoldenMgcMinGap;
            f.MnqMaxStop = cfg.GoldenMnqMaxStop; f.MgcMaxStop = cfg.GoldenMgcMaxStop;
            f.SkipStopOverTarget = cfg.GoldenSkipStopOverTarget == 1;
            if (string.Equals(cfg.GoldenAggression, "REQUIRED", StringComparison.OrdinalIgnoreCase)) { f.MnqMinDrop = cfg.GoldenMnqDropPoints; f.MgcMinDrop = cfg.GoldenMgcDropPoints; }
            f.MaxTries = Math.Max(1, cfg.GoldenMaxTradesPerDay);
            f.StrictFirst = cfg.GoldenStrictFirst == 1;
            return f;
        }

        public static bool IsWin(KeystoneArcEvent e) { return e.Outcome == "WIN"; }
        public static bool IsLoss(KeystoneArcEvent e) { return (e.Outcome ?? string.Empty).StartsWith("LOSS", StringComparison.Ordinal); }
        public static bool Traded(KeystoneArcEvent e) { return e != null && e.EntryTime != DateTime.MinValue && !double.IsNaN(e.ExitPrice) && e.ExitTime != DateTime.MinValue && (IsWin(e) || IsLoss(e) || e.Outcome == "SESSION EXIT" || e.Outcome == "BREAKEVEN"); }
        public static double Points(KeystoneArcEvent e) { return Traded(e) ? (e.ExitPrice - e.Entry) : 0; }
        public static double TargetPoints(KeystoneArcEvent e) { return e.Target - e.Entry; }
        public static double StopPoints(KeystoneArcEvent e) { return e.Entry - e.Stop; }
        public static bool HeldOvernight(KeystoneArcEvent e) { return Traded(e) && KeystoneArcEngine.GoldenSessionDay(e.ExitTime) != KeystoneArcEngine.GoldenSessionDay(e.EntryTime); }
        static DateTime EntryClock(KeystoneArcEvent e) { return e.EntryTime == DateTime.MinValue ? e.TriggerTime : e.EntryTime; }

        public static string Reason(KeystoneArcEvent e, KeystoneGoldenFilter f)
        {
            bool mgc = IsMgc(e.Symbol);
            string kind = e.SetupClass ?? string.Empty;
            if (f.Setup != "ALL" && !string.Equals(f.Setup, kind, StringComparison.OrdinalIgnoreCase)) return "SETUP TYPE";
            double minDrop = mgc ? f.MgcMinDrop : f.MnqMinDrop;
            if (minDrop > 0 && e.FvgDrop < minDrop - 1e-9) return "PUSH DOWN TOO SMALL";
            if (f.MinRed > 0 && e.FvgRedRun < f.MinRed) return "TOO FEW RED CANDLES";
            double minGap = mgc ? f.MgcMinGap : f.MnqMinGap;
            if (minGap > 0 && (kind == "FVG" || kind == "DT") && e.FvgGap < minGap - 1e-9) return "FVG GAP TOO SMALL";
            double maxStop = mgc ? f.MgcMaxStop : f.MnqMaxStop;
            if (maxStop > 0 && StopPoints(e) > maxStop + 1e-9) return "STOP TOO BIG";
            if (f.SkipStopOverTarget && StopPoints(e) > TargetPoints(e) + 1e-9) return "STOP BIGGER THAN TARGET";
            DateTime t = EntryClock(e); int hhmm = t.Hour * 100 + t.Minute;
            bool inHours = f.FromHhmm <= f.ToHhmm ? hhmm >= f.FromHhmm && hhmm <= f.ToHhmm : hhmm >= f.FromHhmm || hhmm <= f.ToHhmm;
            if (!inHours) return "OUTSIDE THE ENTRY HOURS";
            if (f.Weekdays != null && f.Weekdays.Length == 7 && !f.Weekdays[(int)KeystoneArcEngine.GoldenSessionDay(t).DayOfWeek]) return "WEEKDAY OFF";
            return string.Empty;
        }

        public static KeystoneGoldenStudyResult Run(List<KeystoneArcEvent> all, KeystoneGoldenFilter f, KeystoneArcRunConfig cfg, string universe = "FIRST")
        {
            var r = new KeystoneGoldenStudyResult { Universe = universe ?? "FIRST" };
            bool every = r.Universe == "EVERY_FVG";
            r.Hold = cfg == null || cfg.GoldenHold == 1;
            r.All = (all ?? new List<KeystoneArcEvent>()).Where(e => e != null && (e.RiskModel ?? string.Empty).StartsWith("GLD ", StringComparison.Ordinal)).OrderBy(EntryClock).ThenBy(e => e.Symbol).ToList();
            // Filters in the order the day happened: a filtered try ends that day (strictly first), and only the first N tries count.
            foreach (var day in r.All.GroupBy(e => (e.Symbol ?? string.Empty) + "|" + KeystoneArcEngine.GoldenSessionDay(EntryClock(e)).ToString("yyyyMMdd")))
            {
                bool ended = false; int tries = 0;
                foreach (var e in day.OrderBy(EntryClock))
                {
                    string why = ended && !every ? "DAY ALREADY USED" : Reason(e, f);
                    if (why.Length == 0 && !every && tries >= Math.Max(1, f.MaxTries)) why = "TRIES PER DAY";
                    if (why.Length == 0 && !Traded(e)) why = "NO FILL / NO 1M DATA";
                    if (why.Length > 0) { r.Reasons[e] = why; if (f.StrictFirst) ended = true; int c; r.FilteredOut.TryGetValue(why, out c); r.FilteredOut[why] = c + 1; continue; }
                    tries++; r.Kept.Add(e);
                }
            }
            r.Kept = r.Kept.OrderBy(EntryClock).ToList();
            r.Mnq = Stats("MNQ", r.Kept.Where(e => !IsMgc(e.Symbol)));
            r.Mgc = Stats("MGC", r.Kept.Where(e => IsMgc(e.Symbol)));
            r.Both = Stats("BOTH", r.Kept);
            r.AccountMnq = Account(r.Kept.Where(e => !IsMgc(e.Symbol)).ToList(), f);
            r.AccountMgc = Account(r.Kept.Where(e => IsMgc(e.Symbol)).ToList(), f);
            r.AccountBoth = Account(r.Kept, f);
            double mnqT = cfg == null ? 100 : cfg.GoldenMnqTargetPoints, mgcT = cfg == null ? 10 : cfg.GoldenMgcTargetPoints;
            r.Breakdowns = Breakdowns(r.Kept, mnqT, mgcT);
            // MONTH lists every month of the tested range, also months with no kept entry.
            var monthTable = r.Breakdowns.FirstOrDefault(b => b.Title == "MONTH");
            if (monthTable != null && r.All.Count > 0)
            {
                DateTime m0 = r.All.Min(EntryClock), m1 = r.All.Max(EntryClock);
                if (cfg != null && cfg.Start.Year > 1900 && cfg.Start < m0) m0 = cfg.Start;
                if (cfg != null && cfg.End.Year < 9000 && cfg.End > m1) m1 = cfg.End;
                for (DateTime m = new DateTime(m0.Year, m0.Month, 1); m <= m1; m = m.AddMonths(1))
                {
                    int key = m.Year * 100 + m.Month;
                    if (monthTable.Rows.Any(x => x.Order == key)) continue;
                    int found = r.All.Count(e => EntryClock(e).Year == m.Year && EntryClock(e).Month == m.Month);
                    monthTable.Rows.Add(new KeystoneGoldenGroup { Order = key, Group = m.ToString("yyyy-MM", CultureInfo.InvariantCulture) + (found == 0 ? "  (no setup found)" : "  (all " + found + " filtered out)") });
                }
                monthTable.Rows = monthTable.Rows.OrderBy(x => x.Order).ToList();
            }
            foreach (string sym in new[] { "MNQ", "MGC" })
            {
                var list = r.Kept.Where(e => string.Equals(e.Symbol, sym, StringComparison.OrdinalIgnoreCase) && e.GoldenRunBeforeStop != null).ToList();
                if (list.Count == 0) continue;
                r.Grids.Add(Grid(sym, "ALL", list, sym == "MGC" ? mgcT : mnqT));
                foreach (var y in list.GroupBy(e => EntryClock(e).Year).OrderBy(g => g.Key)) r.Grids.Add(Grid(sym, y.Key.ToString(CultureInfo.InvariantCulture), y.ToList(), sym == "MGC" ? mgcT : mnqT));
            }
            r.Insights = Insights(r);
            r.Verdict = Verdict(r);
            return r;
        }

        public static KeystoneGoldenStats Stats(string label, IEnumerable<KeystoneArcEvent> list)
        {
            var s = new KeystoneGoldenStats { Label = label };
            foreach (var e in list)
            {
                s.Entries++;
                double pts = Points(e);
                s.NetPoints += pts; s.NetCash += e.GrossPnl;
                if (IsWin(e))
                {
                    s.Wins++; s.WinPoints += pts;
                    if (!double.IsNaN(e.TroughAfterEntry)) s.DrawBeforeTargetSum += Math.Max(0, e.Entry - e.TroughAfterEntry);
                }
                else if (IsLoss(e))
                {
                    s.Losses++; s.LossPoints += pts;
                    if (!double.IsNaN(e.PeakAfterEntry)) s.RunBeforeStopSum += Math.Max(0, e.PeakAfterEntry - e.Entry);
                }
                else s.Open++;
                if (IsWin(e) || IsLoss(e)) s.HoldHoursSum += Math.Max(0, (e.ExitTime - e.EntryTime).TotalHours);
                if (HeldOvernight(e)) s.Overnight++;
            }
            return s;
        }

        // One plain account: start balance + each trade's own result (strategy contracts); optional one position per instrument.
        public static KeystoneGoldenAccount Account(List<KeystoneArcEvent> kept, KeystoneGoldenFilter f)
        {
            var a = new KeystoneGoldenAccount { Start = f.StartBalance };
            var openUntil = new Dictionary<string, DateTime>(StringComparer.OrdinalIgnoreCase);
            foreach (var e in kept.OrderBy(EntryClock))
            {
                DateTime busy;
                if (f.OnePositionPerInstrument && openUntil.TryGetValue(e.Symbol ?? string.Empty, out busy) && EntryClock(e) < busy) { a.SkippedOpen++; continue; }
                openUntil[e.Symbol ?? string.Empty] = e.ExitTime == DateTime.MinValue ? DateTime.MaxValue : e.ExitTime;
                a.Taken.Add(e); a.Trades++;
                if (IsWin(e)) a.Wins++; else if (IsLoss(e)) a.Losses++; else a.Open++;
            }
            double bal = a.Start, peak = a.Start;
            a.Equity.Add(Tuple.Create(a.Taken.Count == 0 ? DateTime.MinValue : EntryClock(a.Taken[0]), bal));
            foreach (var e in a.Taken.OrderBy(x => x.ExitTime))
            {
                bal += e.GrossPnl; peak = Math.Max(peak, bal);
                a.Equity.Add(Tuple.Create(e.ExitTime, bal));
                if (peak - bal > a.MaxDrawdown) { a.MaxDrawdown = peak - bal; a.MaxDrawdownPercent = peak <= 0 ? 0 : 100.0 * (peak - bal) / peak; }
            }
            a.End = bal; a.Peak = peak;
            foreach (var m in a.Taken.GroupBy(e => new DateTime(e.ExitTime.Year, e.ExitTime.Month, 1)).OrderBy(g => g.Key))
                a.Months.Add(Tuple.Create(m.Key, m.Sum(x => x.GrossPnl), m.Count(IsWin), m.Count(IsLoss)));
            return a;
        }

        static string Band(double v, double[] edges, string[] labels) { for (int i = 0; i < edges.Length; i++) if (v < edges[i] - 1e-9) return labels[i]; return labels[labels.Length - 1]; }

        public static List<KeystoneGoldenBreakdown> Breakdowns(List<KeystoneArcEvent> kept, double mnqTarget, double mgcTarget)
        {
            var output = new List<KeystoneGoldenBreakdown>();
            Func<KeystoneArcEvent, double> tgt = e => Math.Max(0.01, TargetPoints(e));
            string mq = mnqTarget.ToString("0.##", CultureInfo.InvariantCulture), mg = mgcTarget.ToString("0.##", CultureInfo.InvariantCulture);
            Func<double, string> both = pct => (mnqTarget * pct).ToString("0.##", CultureInfo.InvariantCulture) + " / " + (mgcTarget * pct).ToString("0.##", CultureInfo.InvariantCulture);
            Action<string, string, Func<KeystoneArcEvent, Tuple<int, string>>> add = (title, note, key) =>
            {
                var b = new KeystoneGoldenBreakdown { Title = title, Note = note };
                foreach (var g in kept.GroupBy(e => key(e)).OrderBy(g => g.Key.Item1).ThenBy(g => g.Key.Item2))
                    b.Rows.Add(new KeystoneGoldenGroup { Group = g.Key.Item2, Order = g.Key.Item1, Mnq = Stats("MNQ", g.Where(e => !IsMgc(e.Symbol))), Mgc = Stats("MGC", g.Where(e => IsMgc(e.Symbol))), Both = Stats("BOTH", g) });
                output.Add(b);
            };
            add("SETUP", "BH = red → green reference → break of its high • FVG = candle 3 low above candle 1 high • BH + FVG = both on the same candle", e => Tuple.Create(e.SetupClass == "BH" ? 0 : e.SetupClass == "FVG" ? 1 : 2, e.SetupClass == "DT" ? "BH + FVG" : e.SetupClass));
            double[] dropEdges = { 0.15, 0.30, 0.60, 1.0 };
            add("PUSH DOWN BEFORE THE ENTRY", "points from the start price down to the low before the setup, as a share of the target (MNQ / MGC points shown)", e =>
            {
                double r = e.FvgDrop / tgt(e); int i = 0; while (i < dropEdges.Length && r >= dropEdges[i] - 1e-9) i++;
                string[] names = { "UNDER " + both(0.15), both(0.15) + " – " + both(0.30), both(0.30) + " – " + both(0.60), both(0.60) + " – " + both(1.0), both(1.0) + " OR MORE" };
                return Tuple.Create(i, names[i]);
            });
            add("RED CANDLES IN A ROW BEFORE THE PATTERN", "the push down candles right before the setup", e => Tuple.Create(Math.Min(4, e.FvgRedRun), e.FvgRedRun >= 4 ? "4 OR MORE" : e.FvgRedRun.ToString(CultureInfo.InvariantCulture)));
            double[] gapEdges = { 0.05, 0.10, 0.20 };
            add("FVG GAP SIZE", "candle 3 low − candle 1 high, as a share of the target (MNQ / MGC points shown)", e =>
            {
                if (e.SetupClass == "BH") return Tuple.Create(-1, "BH (NO GAP)");
                double r = e.FvgGap / tgt(e); int i = 0; while (i < gapEdges.Length && r >= gapEdges[i] - 1e-9) i++;
                string[] names = { "UNDER " + both(0.05), both(0.05) + " – " + both(0.10), both(0.10) + " – " + both(0.20), both(0.20) + " OR MORE" };
                return Tuple.Create(i, names[i]);
            });
            double[] stopEdges = { 0.25, 0.50, 0.75, 1.0001 };
            add("STOP SIZE (vs THE TARGET)", "distance from the entry to the stop below the pattern", e =>
            {
                double r = StopPoints(e) / tgt(e); int i = 0; while (i < stopEdges.Length && r >= stopEdges[i] - 1e-9) i++;
                string[] names = { "UNDER 25% (" + both(0.25) + ")", "25–50%", "50–75%", "75–100%", "BIGGER THAN THE TARGET" };
                return Tuple.Create(i, names[i]);
            });
            add("ENTRY HOUR (ET)", "the clock hour of the entry", e => { DateTime t = EntryClock(e); int k = (t.Hour + 6) % 24; return Tuple.Create(k, t.Hour.ToString("00") + ":00"); });
            add("MINUTES AFTER THE START", "how long after the start time the setup came", e =>
            {
                double m = e.GoldenStartTime == DateTime.MinValue ? 0 : (EntryClock(e) - e.GoldenStartTime).TotalMinutes;
                double[] edges = { 15, 30, 60, 120, 240 }; string[] names = { "FIRST 15 MIN", "15–30 MIN", "30–60 MIN", "1–2 HOURS", "2–4 HOURS", "4+ HOURS" };
                int i = 0; while (i < edges.Length && m >= edges[i]) i++; return Tuple.Create(i, names[i]);
            });
            add("WEEKDAY", "the trading day of the entry", e => { var d = KeystoneArcEngine.GoldenSessionDay(EntryClock(e)).DayOfWeek; return Tuple.Create(((int)d + 6) % 7, d.ToString().ToUpperInvariant()); });
            add("TRY OF THE DAY", "1 = the first setup; 2+ = the next setup after a loss", e => Tuple.Create(Math.Max(1, e.SessionOrder), "TRY " + Math.Max(1, e.SessionOrder)));
            add("HOW IT ENDED", "same session, carried overnight, or still open when the data ended", e => Tuple.Create(!(IsWin(e) || IsLoss(e)) ? 2 : HeldOvernight(e) ? 1 : 0, !(IsWin(e) || IsLoss(e)) ? "STILL OPEN AT DATA END" : HeldOvernight(e) ? "CLOSED A LATER DAY" : "CLOSED THE SAME DAY"));
            add("YEAR", "volatility changes year to year", e => Tuple.Create(EntryClock(e).Year, EntryClock(e).Year.ToString(CultureInfo.InvariantCulture)));
            add("MONTH", "month of the entry", e => { DateTime t = EntryClock(e); return Tuple.Create(t.Year * 100 + t.Month, t.ToString("yyyy-MM", CultureInfo.InvariantCulture)); });
            return output;
        }

        // TARGET × STOP: every kept entry replayed on its own 1-minute path for each fixed stop (and the pattern stop) and target.
        public static KeystoneGoldenGrid Grid(string symbol, string year, List<KeystoneArcEvent> list, double yourTarget)
        {
            double[] stops = StopLevels(symbol), targets = TargetLevels(symbol);
            if (!targets.Any(t => Math.Abs(t - yourTarget) < 1e-9)) targets = targets.Concat(new[] { yourTarget }).OrderBy(t => t).ToArray();
            var g = new KeystoneGoldenGrid { Symbol = symbol, Year = year, Entries = list.Count, Stops = stops, Targets = targets, Cells = new KeystoneGoldenCell[stops.Length + 1, targets.Length] };
            for (int s = 0; s <= stops.Length; s++)
                for (int t = 0; t < targets.Length; t++)
                {
                    bool pattern = s == stops.Length;
                    var c = new KeystoneGoldenCell { Stop = pattern ? 0 : stops[s], Target = targets[t], Pattern = pattern };
                    foreach (var e in list)
                    {
                        if (e.GoldenRunBeforeStop == null || e.GoldenRunBeforeStop.Length != stops.Length + 1) continue;
                        double run = e.GoldenRunBeforeStop[s]; bool hit = e.GoldenStopHit[s];
                        double stopPts = pattern ? StopPoints(e) : stops[s];
                        double cash = PointValue(symbol) * Math.Max(1, e.Quantity);
                        if (run >= targets[t] - 1e-9) { c.Wins++; c.NetPoints += targets[t]; c.NetCash += targets[t] * cash; }
                        else if (hit) { c.Losses++; c.NetPoints -= stopPts; c.NetCash -= stopPts * cash; }
                        else c.Open++;
                    }
                    g.Cells[s, t] = c;
                    if (g.Best == null || c.NetCash > g.Best.NetCash) g.Best = c;
                    if (pattern && Math.Abs(targets[t] - yourTarget) < 1e-9) g.Yours = c;
                }
            return g;
        }

        static List<KeystoneGoldenInsight> Insights(KeystoneGoldenStudyResult r)
        {
            var output = new List<KeystoneGoldenInsight>();
            foreach (string sym in new[] { "MNQ", "MGC" })
            {
                var all = sym == "MNQ" ? r.Mnq : r.Mgc;
                if (all.Wins + all.Losses < 10) continue;
                foreach (var b in r.Breakdowns.Where(x => x.Title != "MONTH" && x.Title != "YEAR" && x.Title != "HOW IT ENDED"))   // conditions known at the entry only
                    foreach (var g in b.Rows)
                    {
                        var s = sym == "MNQ" ? g.Mnq : g.Mgc;
                        if (s.Wins + s.Losses < Math.Max(6, (all.Wins + all.Losses) / 12)) continue;
                        double lift = s.WinRate - all.WinRate;
                        if (Math.Abs(lift) < 8) continue;
                        output.Add(new KeystoneGoldenInsight
                        {
                            Lift = lift, Good = lift > 0,
                            Text = sym + " • " + b.Title + " = " + g.Group + " → wins " + s.WinRate.ToString("0", CultureInfo.InvariantCulture) + "% (" + s.Wins + "/" + (s.Wins + s.Losses) + ") vs " + all.WinRate.ToString("0", CultureInfo.InvariantCulture) + "% overall • net " + Cash(s.NetCash)
                        });
                    }
            }
            return output.OrderByDescending(i => Math.Abs(i.Lift)).Take(16).ToList();
        }

        public static string Cash(double v) { return (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture); }

        static string Verdict(KeystoneGoldenStudyResult r)
        {
            if (r.All.Count == 0) return "No GOLDEN entries in this range. Check the start times and that the data loaded.";
            var parts = new List<string>();
            foreach (var s in new[] { r.Mnq, r.Mgc }) if (s.Entries > 0)
                parts.Add(s.Label + ": " + s.Entries + " entries, wins " + s.WinRate.ToString("0", CultureInfo.InvariantCulture) + "% (" + s.Wins + " W / " + s.Losses + " L" + (s.Open > 0 ? " / " + s.Open + " open" : "") + "), net " + Fmt(s.Label, s.NetPoints) + " pts = " + Cash(s.NetCash));
            return string.Join("   •   ", parts) + (r.Kept.Count < r.All.Count ? "   •   filters removed " + (r.All.Count - r.Kept.Count) + " of " + r.All.Count + " first setups" : string.Empty);
        }

        // ---- export -------------------------------------------------------------------------------
        public static string Csv(KeystoneGoldenStudyResult r)
        {
            var sb = new StringBuilder();
            sb.AppendLine("kept,filtered_reason,symbol,session_day,entry_time,setup,try,push_down_pts,red_candles,fvg_gap_pts,entry,target,stop,target_pts,stop_pts,outcome,exit_time,exit_price,points,cash,run_up_before_exit_pts,drawdown_before_exit_pts,held_overnight,hold_hours");
            foreach (var e in r.All)
            {
                string why; r.Reasons.TryGetValue(e, out why);
                Func<double, string> n = v => double.IsNaN(v) ? "" : v.ToString("0.##", CultureInfo.InvariantCulture);
                sb.AppendLine(string.Join(",", new[]
                {
                    string.IsNullOrEmpty(why) ? "1" : "0", why ?? "", e.Symbol, KeystoneArcEngine.GoldenSessionDay(EntryClock(e)).ToString("yyyy-MM-dd"), EntryClock(e).ToString("yyyy-MM-dd HH:mm"), e.SetupClass == "DT" ? "BH+FVG" : e.SetupClass, e.SessionOrder.ToString(CultureInfo.InvariantCulture),
                    n(e.FvgDrop), e.FvgRedRun.ToString(CultureInfo.InvariantCulture), e.SetupClass == "BH" ? "" : n(e.FvgGap), n(e.Entry), n(e.Target), n(e.Stop), n(TargetPoints(e)), n(StopPoints(e)), e.Outcome,
                    e.ExitTime == DateTime.MinValue ? "" : e.ExitTime.ToString("yyyy-MM-dd HH:mm"), n(e.ExitPrice), n(Points(e)), n(e.GrossPnl),
                    double.IsNaN(e.PeakAfterEntry) ? "" : n(e.PeakAfterEntry - e.Entry), double.IsNaN(e.TroughAfterEntry) ? "" : n(e.Entry - e.TroughAfterEntry), HeldOvernight(e) ? "1" : "0", Traded(e) ? n((e.ExitTime - e.EntryTime).TotalHours) : ""
                }));
            }
            return sb.ToString();
        }

        static string H(string s) { return System.Net.WebUtility.HtmlEncode(s ?? string.Empty); }
        static string Pc(double v) { return v.ToString("0", CultureInfo.InvariantCulture) + "%"; }
        static string Cls(double v) { return v > 0 ? "g" : v < 0 ? "r" : "m"; }

        public static string Html(KeystoneGoldenStudyResult r, KeystoneGoldenFilter f, string title, List<KeystoneGoldenStudyResult> compare = null)
        {
            var sb = new StringBuilder();
            sb.Append("<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>GOLDEN entry study</title><style>")
              .Append("body{background:#0d1017;color:#e8e3d3;font-family:Segoe UI,Arial,sans-serif;margin:0;padding:18px}h1{color:#f2c14e;margin:0 0 4px}h2{color:#f2c14e;margin:26px 0 6px;font-size:17px}")
              .Append(".sub{color:#9aa4b5;font-size:13px}.cards{display:flex;flex-wrap:wrap;gap:10px;margin:12px 0}.card{background:#161b26;border:1.5px solid #2d3546;border-radius:8px;padding:10px 14px;min-width:200px}")
              .Append(".card b{display:block;font-size:12px;color:#9aa4b5}.card span{font-size:21px;font-weight:700}table{border-collapse:collapse;margin:6px 0 4px;font-size:12.5px}th{background:#1d2433;color:#f2c14e;padding:5px 8px;text-align:right}th:first-child,td:first-child{text-align:left}")
              .Append("td{padding:4px 8px;border-bottom:1px solid #222a39;text-align:right}.g{color:#38d682}.r{color:#ff5260}.m{color:#9aa4b5}.c{color:#5bc8f5}.note{color:#9aa4b5;font-size:12px}.hl{outline:2px solid #f2c14e}.best{outline:2px solid #38d682}.tagy{color:#f2c14e;font-size:10px;font-weight:bold}.tagb{color:#38d682;font-size:10px;font-weight:bold}.wrap{overflow-x:auto}</style></head><body>");
            sb.Append("<h1>GOLDEN ENTRY STUDY</h1><div class='sub'>").Append(H(title)).Append("<br>").Append(r.Hold ? "Every trade held until its target or its stop (overnight and later days); no prop rules." : "Trades closed at the session close time.").Append("</div>");
            sb.Append("<p><b>ENTRIES: ").Append(H(UniverseName(r.Universe))).Append("</b> • ").Append(H(r.Verdict)).Append("</p>");
            if (compare != null && compare.Count > 1)
            {
                sb.Append("<h2>WHICH ENTRIES • same filters, one live account</h2><div class='wrap'><table><tr><th>ENTRIES</th>");
                var rows = UniverseRows(compare);
                foreach (var c in compare) sb.Append("<th>").Append(H(UniverseName(c.Universe))).Append("</th>");
                sb.Append("</tr>");
                foreach (var row in rows) { sb.Append("<tr><td>").Append(H(row[0])).Append("</td>"); for (int i = 1; i < row.Length; i++) sb.Append("<td>").Append(H(row[i])).Append("</td>"); sb.Append("</tr>"); }
                sb.Append("</table></div>");
            }
            sb.Append("<h2>MNQ vs MGC vs BOTH</h2><div class='wrap'><table><tr><th></th><th>MNQ</th><th>MGC</th><th>BOTH</th></tr>");
            foreach (var row in CompareRows(r)) sb.Append("<tr><td>").Append(H(row[0])).Append("</td><td>").Append(H(row[1])).Append("</td><td>").Append(H(row[2])).Append("</td><td>").Append(H(row[3])).Append("</td></tr>");
            sb.Append("</table></div>");
            if (r.FilteredOut.Count > 0) { sb.Append("<p class='note'>Filtered out: ").Append(H(string.Join(" • ", r.FilteredOut.OrderByDescending(k => k.Value).Select(k => k.Key + " " + k.Value)))).Append("</p>"); }
            if (r.Insights.Count > 0)
            {
                sb.Append("<h2>WHAT MAKES THE DIFFERENCE</h2><ul>");
                foreach (var i in r.Insights) sb.Append("<li class='").Append(i.Good ? "g" : "r").Append("'>").Append(H(i.Text)).Append("</li>");
                sb.Append("</ul>");
            }
            foreach (var b in r.Breakdowns)
            {
                bool hasMnq = r.Mnq.Entries > 0, hasMgc = r.Mgc.Entries > 0, hasBoth = hasMnq && hasMgc;
                sb.Append("<h2>").Append(H(b.Title)).Append("</h2><div class='note'>").Append(H(b.Note)).Append("</div><div class='wrap'><table><tr><th>GROUP</th>");
                foreach (string name in new[] { hasMnq ? "MNQ" : null, hasMgc ? "MGC" : null, hasBoth ? "BOTH" : null }.Where(x => x != null))
                    sb.Append("<th>").Append(name).Append(" n</th><th>").Append(name).Append(" win</th><th>").Append(name).Append(" net</th>");
                sb.Append("</tr>");
                foreach (var g in b.Rows)
                {
                    sb.Append("<tr><td>").Append(H(g.Group)).Append("</td>");
                    foreach (var s in new[] { hasMnq ? g.Mnq : null, hasMgc ? g.Mgc : null, hasBoth ? g.Both : null }.Where(x => x != null))
                        sb.Append("<td>").Append(s.Entries).Append("</td><td class='").Append(s.Wins + s.Losses == 0 ? "m" : "c").Append("'>").Append(s.Wins + s.Losses == 0 ? "–" : Pc(s.WinRate)).Append("</td><td class='").Append(Cls(s.NetCash)).Append("'>").Append(s.Entries == 0 ? "–" : Cash(s.NetCash)).Append("</td>");
                    sb.Append("</tr>");
                }
                sb.Append("</table></div>");
            }
            sb.Append("<h2>TARGET × STOP (one account, the strategy's contracts)</h2><div class='note'>Each cell replays every kept entry on its own 1-minute path: a fixed stop in points (rows) or the pattern stop (last row) and a target in points (columns). Win % • net $. ◆ YOURS (gold outline) = the target and stop you ran; ★ BEST (green outline) = the most money in that table. Both are counted on the same entries — the best cell is chosen with hindsight, check it is best in most years before using it.</div>");
            foreach (var g in r.Grids)
            {
                sb.Append("<h3 class='c'>").Append(H(g.Symbol + " • " + (g.Year == "ALL" ? "ALL YEARS" : g.Year) + " • " + g.Entries + " entries")).Append(g.Best == null ? "" : H(" • best: target " + Fmt(g.Symbol, g.Best.Target) + " / stop " + (g.Best.Pattern ? "pattern" : Fmt(g.Symbol, g.Best.Stop)) + " = " + Cash(g.Best.NetCash))).Append(g.Yours == null ? "" : H(" • ◆ yours (target " + Fmt(g.Symbol, g.Yours.Target) + " / " + (g.Yours.Pattern ? "pattern stop" : "stop " + Fmt(g.Symbol, g.Yours.Stop)) + ") = " + Cash(g.Yours.NetCash))).Append("</h3>");
                if (g.Entries < 30) sb.Append("<div class='r'>Only ").Append(g.Entries).Append(" entries: too few to trust the best cell — one or two trades decide it. Use a longer range or fewer filters.</div>");
                sb.Append("<div class='wrap'><table><tr><th>STOP \\ TARGET</th>");
                foreach (double t in g.Targets) sb.Append("<th>+").Append(Fmt(g.Symbol, t)).Append("</th>");
                sb.Append("</tr>");
                for (int s = 0; s <= g.Stops.Length; s++)
                {
                    sb.Append("<tr><td>").Append(s == g.Stops.Length ? "PATTERN" : "−" + Fmt(g.Symbol, g.Stops[s])).Append("</td>");
                    for (int t = 0; t < g.Targets.Length; t++)
                    {
                        var c = g.Cells[s, t];
                        sb.Append("<td class='").Append(Cls(c.NetCash)).Append(c == g.Yours ? " hl" : c == g.Best ? " best" : "").Append("'>").Append(c == g.Yours ? "<span class='tagy'>◆ YOURS</span><br>" : "").Append(c == g.Best ? "<span class='tagb'>★ BEST</span><br>" : "").Append(Pc(c.WinRate)).Append("<br>").Append(Cash(c.NetCash)).Append("</td>");
                    }
                    sb.Append("</tr>");
                }
                sb.Append("</table></div>");
            }
            sb.Append("<h2>ONE ACCOUNT</h2><div class='note'>Start ").Append(Cash(f.StartBalance)).Append(f.OnePositionPerInstrument ? " • one position per instrument (a setup while a trade is still open is skipped)" : " • every entry taken").Append("</div><div class='wrap'><table><tr><th></th><th>START</th><th>END</th><th>TRADES</th><th>W / L</th><th>MAX DRAWDOWN</th><th>SKIPPED (OPEN)</th></tr>");
            foreach (var a in new[] { Tuple.Create("MNQ", r.AccountMnq), Tuple.Create("MGC", r.AccountMgc), Tuple.Create("BOTH", r.AccountBoth) })
                sb.Append("<tr><td>").Append(a.Item1).Append("</td><td>").Append(Cash(a.Item2.Start)).Append("</td><td class='").Append(Cls(a.Item2.End - a.Item2.Start)).Append("'>").Append(Cash(a.Item2.End)).Append("</td><td>").Append(a.Item2.Trades).Append("</td><td>").Append(a.Item2.Wins + " / " + a.Item2.Losses).Append("</td><td class='r'>").Append(Cash(-a.Item2.MaxDrawdown)).Append("</td><td>").Append(a.Item2.SkippedOpen).Append("</td></tr>");
            sb.Append("</table></div>");
            sb.Append("<h2>EVERY ENTRY</h2><div class='wrap'><table><tr><th>DATE</th><th>TIME</th><th>INST</th><th>SETUP</th><th>TRY</th><th>PUSH</th><th>RED</th><th>GAP</th><th>ENTRY</th><th>STOP PTS</th><th>RESULT</th><th>PTS</th><th>$</th><th>RUN UP</th><th>DRAW DOWN</th><th>EXIT</th><th>FILTER</th></tr>");
            foreach (var e in r.All)
            {
                string why; r.Reasons.TryGetValue(e, out why);
                sb.Append("<tr class='").Append(string.IsNullOrEmpty(why) ? "" : "m").Append("'><td>").Append(EntryClock(e).ToString("yyyy-MM-dd ddd")).Append("</td><td>").Append(EntryClock(e).ToString("HH:mm")).Append("</td><td>").Append(e.Symbol).Append("</td><td>").Append(e.SetupClass == "DT" ? "BH+FVG" : e.SetupClass).Append("</td><td>").Append(e.SessionOrder)
                  .Append("</td><td>").Append(Fmt(e.Symbol, e.FvgDrop)).Append("</td><td>").Append(e.FvgRedRun).Append("</td><td>").Append(e.SetupClass == "BH" ? "–" : Fmt(e.Symbol, e.FvgGap)).Append("</td><td>").Append(Fmt(e.Symbol, e.Entry)).Append("</td><td>").Append(Fmt(e.Symbol, StopPoints(e)))
                  .Append("</td><td class='").Append(IsWin(e) ? "g" : IsLoss(e) ? "r" : "m").Append("'>").Append(H(OutcomeText(e, r.Hold))).Append("</td><td class='").Append(Cls(Points(e))).Append("'>").Append(Fmt(e.Symbol, Points(e))).Append("</td><td class='").Append(Cls(e.GrossPnl)).Append("'>").Append(Cash(e.GrossPnl))
                  .Append("</td><td>").Append(double.IsNaN(e.PeakAfterEntry) ? "–" : Fmt(e.Symbol, e.PeakAfterEntry - e.Entry)).Append("</td><td>").Append(double.IsNaN(e.TroughAfterEntry) ? "–" : Fmt(e.Symbol, e.Entry - e.TroughAfterEntry)).Append("</td><td>").Append(e.ExitTime == DateTime.MinValue ? "–" : e.ExitTime.ToString("MM-dd HH:mm")).Append("</td><td class='m'>").Append(H(why ?? "")).Append("</td></tr>");
            }
            sb.Append("</table></div></body></html>");
            return sb.ToString();
        }

        public static string OutcomeText(KeystoneArcEvent e, bool hold)
        {
            if (IsWin(e)) return HeldOvernight(e) ? "WIN (NEXT DAY+)" : "WIN";
            if (IsLoss(e)) return HeldOvernight(e) ? "LOSS (NEXT DAY+)" : "LOSS";
            if (e.Outcome == "SESSION EXIT") return hold ? "STILL OPEN (DATA END)" : "CLOSED AT SESSION END";
            return e.Outcome ?? string.Empty;
        }

        public static List<string[]> CompareRows(KeystoneGoldenStudyResult r)
        {
            var s = new[] { r.Mnq, r.Mgc, r.Both }; var a = new[] { r.AccountMnq, r.AccountMgc, r.AccountBoth };
            var rows = new List<string[]>();
            Action<string, Func<KeystoneGoldenStats, int, string>> add = (name, fn) => rows.Add(new[] { name, fn(s[0], 0), fn(s[1], 1), fn(s[2], 2) });
            Func<int, string> sym = i => i == 1 ? "MGC" : "MNQ";
            add("ENTRIES", (x, i) => x.Entries.ToString(CultureInfo.InvariantCulture));
            add("WINS / LOSSES / OPEN", (x, i) => x.Wins + " / " + x.Losses + " / " + x.Open);
            add("WIN RATE", (x, i) => x.Wins + x.Losses == 0 ? "–" : Pc(x.WinRate));
            add("NET POINTS", (x, i) => i == 2 ? "–" : Fmt(sym(i), x.NetPoints));
            add("NET $ (strategy contracts)", (x, i) => Cash(x.NetCash));
            add("$ PER ENTRY", (x, i) => Cash(x.CashPerEntry));
            add("AVG WIN (POINTS)", (x, i) => i == 2 ? "–" : Fmt(sym(i), x.AvgWinPoints));
            add("AVG LOSS (POINTS)", (x, i) => i == 2 ? "–" : Fmt(sym(i), x.AvgLossPoints));
            add("LOSERS: BEST RUN UP BEFORE THE STOP", (x, i) => i == 2 ? "–" : Fmt(sym(i), x.AvgRunBeforeStop) + " pts");
            add("WINNERS: WORST DIP BEFORE THE TARGET", (x, i) => i == 2 ? "–" : Fmt(sym(i), x.AvgDrawBeforeTarget) + " pts");
            add("AVG TIME IN THE TRADE", (x, i) => x.AvgHoldHours.ToString("0.#", CultureInfo.InvariantCulture) + " h");
            add("CLOSED A LATER DAY", (x, i) => x.Overnight.ToString(CultureInfo.InvariantCulture));
            rows.Add(new[] { "ONE ACCOUNT: START → END", Cash(a[0].Start) + " → " + Cash(a[0].End), Cash(a[1].Start) + " → " + Cash(a[1].End), Cash(a[2].Start) + " → " + Cash(a[2].End) });
            rows.Add(new[] { "ONE ACCOUNT: MAX DRAWDOWN", Cash(-a[0].MaxDrawdown), Cash(-a[1].MaxDrawdown), Cash(-a[2].MaxDrawdown) });
            rows.Add(new[] { "ONE ACCOUNT: BEST / WORST MONTH", MonthText(a[0]), MonthText(a[1]), MonthText(a[2]) });
            return rows;
        }

        // Rows of the WHICH ENTRIES comparison: one column per set of entries.
        public static List<string[]> UniverseRows(List<KeystoneGoldenStudyResult> list)
        {
            var rows = new List<string[]>();
            Action<string, Func<KeystoneGoldenStudyResult, string>> add = (name, fn) => rows.Add(new[] { name }.Concat(list.Select(fn)).ToArray());
            add("ENTRIES KEPT / FOUND", x => x.Kept.Count + " / " + x.All.Count);
            add("WINS / LOSSES / OPEN", x => x.Both.Wins + " / " + x.Both.Losses + " / " + x.Both.Open);
            add("WIN RATE", x => x.Both.Wins + x.Both.Losses == 0 ? "–" : Pc(x.Both.WinRate));
            add("NEEDED TO BREAK EVEN", x => x.Both.Wins == 0 || x.Both.Losses == 0 ? "–" : Pc(100.0 * Math.Abs(x.Both.AvgLossPoints) / (Math.Abs(x.Both.AvgLossPoints) + x.Both.AvgWinPoints)));
            add("NET $ (every entry)", x => Cash(x.Both.NetCash));
            add("$ PER ENTRY", x => Cash(x.Both.CashPerEntry));
            add("MNQ • MGC NET", x => Cash(x.Mnq.NetCash) + " • " + Cash(x.Mgc.NetCash));
            add("ONE LIVE ACCOUNT: TRADES TAKEN", x => x.AccountBoth.Trades + (x.AccountBoth.SkippedOpen > 0 ? " (" + x.AccountBoth.SkippedOpen + " skipped: a trade was open)" : ""));
            add("ONE LIVE ACCOUNT: START → END", x => Cash(x.AccountBoth.Start) + " → " + Cash(x.AccountBoth.End));
            add("ONE LIVE ACCOUNT: MAX DRAWDOWN", x => Cash(-x.AccountBoth.MaxDrawdown));
            add("ONE LIVE ACCOUNT: BEST / WORST MONTH", x => MonthText(x.AccountBoth));
            return rows;
        }

        static string MonthText(KeystoneGoldenAccount a) { return a.Months.Count == 0 ? "–" : Cash(a.Months.Max(m => m.Item2)) + " / " + Cash(a.Months.Min(m => m.Item2)); }
    }

    public sealed class KeystoneHelixStageRules
    {
        public int MnqContracts = 10, MgcContracts = 10;
        public double RotationTarget = 1000, RotationStop = 500;
        // FIRST_WIN: the account stops for the day after its first winning basket.
        // FIRST_PROFIT: stops once its day P/L is above zero after a basket (recovery included).
        // DAILY_TARGET: stops once its day P/L reaches DailyTarget. NONE: never locks on profit.
        public string LockMode = "FIRST_WIN";
        public double DailyTarget = 1000;
        public int ShrinkTarget = 0;        // 1: a basket's target is cut to what is left of DailyTarget
        public int MaxLossesPerDay = 0;     // 0 = no limit (the account keeps trying until liquidated)
        public double DailyStop = 0;        // 0 = off; a basket stop never goes past the daily stop
        public KeystoneHelixStageRules Copy() { return (KeystoneHelixStageRules)MemberwiseClone(); }
        public string Label()
        {
            string lk = LockMode == "FIRST_WIN" ? "lock after first win" : LockMode == "FIRST_PROFIT" ? "lock once the day is positive" : LockMode == "DAILY_TARGET" ? "lock at day +" + DailyTarget.ToString("N0", CultureInfo.InvariantCulture) : "no profit lock";
            return MnqContracts + " MNQ + " + MgcContracts + " MGC • basket +" + RotationTarget.ToString("N0", CultureInfo.InvariantCulture) + " / −" + RotationStop.ToString("N0", CultureInfo.InvariantCulture) + " • " + lk
                + (MaxLossesPerDay > 0 ? " • stop after " + MaxLossesPerDay + " losses" : string.Empty) + (DailyStop > 0 ? " • day stop −" + DailyStop.ToString("N0", CultureInfo.InvariantCulture) : string.Empty);
        }
    }

    public sealed class KeystoneHelixConfig
    {
        public DateTime Start = DateTime.MinValue, End = DateTime.MaxValue;   // session dates, inclusive
        public int UseMnq = 1, UseMgc = 1;
        public string MnqDirection = "BUY", MgcDirection = "BUY";            // BUY, SELL, RANDOM, ALTERNATE
        public int LinkRandom = 0;                                           // RANDOM: both legs share one coin flip
        public int RandomSeed = 7;
        public int SessionStartHhmm = 930, LastEntryHhmm = 1545, SessionEndHhmm = 1600;
        public int PauseMinutes = 2;
        public string DayStart = "FIRST";                                    // FIRST account every day, or CONTINUE
        public string ExitModel = "STRICT";                                  // STRICT (stop first on both extremes) or NEUTRAL (minute closes)
        public double CommissionPerSide = 0.62;                              // $ per contract per side
        public double SlippageTicks = 1;                                     // ticks per leg per side
        public KeystoneHelixStageRules Eval = new KeystoneHelixStageRules();
        public KeystoneHelixStageRules Funded = new KeystoneHelixStageRules();
        public int Accounts = 10;
        public string StartMode = "DIRECT";                                  // DIRECT (bought funded) or EVAL
        public double EvalCost = 100, ActivationCost = 0, DirectCost = 500;
        public double EvalTarget = 3000, EvalMaxLoss = 2000; public string EvalDrawdown = "STATIC"; public int EvalMinDays = 2; public double EvalConsistency = 0;
        public double FundedMaxLoss = 2000; public string FundedDrawdown = "STATIC"; public double TrailStopAt = 100;
        public int FundedDelaySessions = 0;
        public int PayoutEverySessions = 5; public string PayoutCalendar = "POOL"; // POOL: every N pool sessions • ACCOUNT: N funded days since last payout
        public double PayoutMinProfit = 2000, PayoutFraction = 50, PayoutCap = 2000, PayoutSplit = 80, PayoutMinAmount = 0;
        public int PayoutMinDays = 0, MaxPayouts = 0;
        public int AutoReplace = 1; public string ReplaceTiming = "NEXT_REVIEW"; public int ReplaceDelaySessions = 1; public int MaxPurchases = 0;
        public string Label = "YOUR SETTINGS";
        public string Weekdays = "12345";                                    // days that trade: 1 = Monday … 5 = Friday
        public double MinRealBarShare = 0.6;                                 // a day is skipped when a used instrument has fewer real minutes than this

        public KeystoneHelixConfig Copy()
        {
            var c = (KeystoneHelixConfig)MemberwiseClone();
            c.Eval = Eval.Copy(); c.Funded = Funded.Copy();
            return c;
        }

        public string Describe()
        {
            string legs = (UseMnq == 1 ? "MNQ " + MnqDirection : string.Empty) + (UseMnq == 1 && UseMgc == 1 ? " + " : string.Empty) + (UseMgc == 1 ? "MGC " + MgcDirection : string.Empty);
            return legs + " • " + KeystoneHelix.Hhmm(SessionStartHhmm) + "–" + KeystoneHelix.Hhmm(SessionEndHhmm) + " ET (last entry " + KeystoneHelix.Hhmm(LastEntryHhmm) + ") • pause " + PauseMinutes + " min • "
                + Accounts + " accounts • " + (StartMode == "EVAL" ? "evaluation start" : "direct funded") + " • " + ExitModel + " fills • costs $" + CommissionPerSide.ToString("0.##", CultureInfo.InvariantCulture) + "/side + " + SlippageTicks.ToString("0.#", CultureInfo.InvariantCulture) + " tick";
        }
    }

