    public static class KeystoneHelix
    {
        public const double MnqPoint = 2.0, MgcPoint = 10.0, MnqTick = 0.25, MgcTick = 0.1;

        public static string Hhmm(int hhmm) { return (hhmm / 100).ToString("00") + ":" + (hhmm % 100).ToString("00"); }

        // One timeline of minutes. A leg without a bar in a minute carries its last close (flat)
        // so the basket can always be valued; HasMnq/HasMgc keep the truth for the audit.
        public static List<KeystoneHelixMinute> Align(List<KeystoneArcBar> mnq, List<KeystoneArcBar> mgc)
        {
            var output = new List<KeystoneHelixMinute>();
            var a = (mnq ?? new List<KeystoneArcBar>()).Where(b => b != null).OrderBy(b => b.Time).ToList();
            var g = (mgc ?? new List<KeystoneArcBar>()).Where(b => b != null).OrderBy(b => b.Time).ToList();
            int i = 0, j = 0; double lastA = double.NaN, lastG = double.NaN;
            while (i < a.Count || j < g.Count)
            {
                DateTime t = i < a.Count && (j >= g.Count || a[i].Time <= g[j].Time) ? a[i].Time : g[j].Time;
                var m = new KeystoneHelixMinute { Time = t };
                if (i < a.Count && a[i].Time == t) { var b = a[i++]; m.MnqO = b.Open; m.MnqH = b.High; m.MnqL = b.Low; m.MnqC = b.Close; m.HasMnq = true; lastA = b.Close; }
                else { m.MnqO = m.MnqH = m.MnqL = m.MnqC = lastA; }
                if (j < g.Count && g[j].Time == t) { var b = g[j++]; m.MgcO = b.Open; m.MgcH = b.High; m.MgcL = b.Low; m.MgcC = b.Close; m.HasMgc = true; lastG = b.Close; }
                else { m.MgcO = m.MgcH = m.MgcL = m.MgcC = lastG; }
                while (i < a.Count && a[i].Time <= t) i++;
                while (j < g.Count && g[j].Time <= t) j++;
                output.Add(m);
            }
            return output;
        }

        private static bool InWindow(DateTime closeStamp, int startHhmm, int endHhmm)
        {
            // A close-stamped minute belongs to the window when its interval starts at/after the
            // start and ends at/before the end: (start, end].
            int hhmm = closeStamp.Hour * 100 + closeStamp.Minute;
            if (startHhmm <= endHhmm) return hhmm > startHhmm && hhmm <= endHhmm;
            return hhmm > startHhmm || hhmm <= endHhmm;
        }

        public static DateTime SessionDate(DateTime closeStamp, int startHhmm, int endHhmm)
        {
            int hhmm = closeStamp.Hour * 100 + closeStamp.Minute;
            if (startHhmm > endHhmm && hhmm > startHhmm) return closeStamp.Date.AddDays(1);
            return closeStamp.Date;
        }

        private static DateTime Clock(DateTime day, int hhmm) { return day.Date.AddHours(hhmm / 100).AddMinutes(hhmm % 100); }

        // Session windows: (sessionDate, first index, last index) of minutes inside the window.
        public static List<int[]> SessionRanges(List<KeystoneHelixMinute> minutes, KeystoneHelixConfig cfg, List<DateTime> dates)
        {
            var ranges = new List<int[]>();
            DateTime current = DateTime.MinValue; int first = -1, last = -1;
            for (int k = 0; k < minutes.Count; k++)
            {
                var m = minutes[k];
                if (!InWindow(m.Time, cfg.SessionStartHhmm, cfg.SessionEndHhmm)) continue;
                DateTime d = SessionDate(m.Time, cfg.SessionStartHhmm, cfg.SessionEndHhmm);
                if (d < cfg.Start.Date || d > cfg.End.Date) continue;
                if (d.DayOfWeek == DayOfWeek.Saturday || d.DayOfWeek == DayOfWeek.Sunday) continue;
                if ((cfg.UseMnq == 1 && double.IsNaN(m.MnqO)) || (cfg.UseMgc == 1 && double.IsNaN(m.MgcO))) continue;
                if (d != current)
                {
                    if (first >= 0) { ranges.Add(new[] { first, last }); dates.Add(current); }
                    current = d; first = k;
                }
                last = k;
            }
            if (first >= 0) { ranges.Add(new[] { first, last }); dates.Add(current); }
            return ranges;
        }

        private sealed class Slot
        {
            public int Index, Instance;
            public KeystoneHelixLife Life;
            public bool Waiting; public int ReadySession;          // waiting for a replacement / funded start
            public bool Eval;
            public double Balance, Hwm, Start;
            public double DayPnl; public int DayLosses, DayWins; public bool DayLocked; public string LockReason = string.Empty;
            public int DaysTraded, DaysSincePayout, FundedSessions;
            public double BestDay;
            public bool TradedToday;
            public string LastResult = "FIRST";
        }

        private static double Threshold(Slot s, KeystoneHelixConfig cfg)
        {
            double maxLoss = s.Eval ? cfg.EvalMaxLoss : cfg.FundedMaxLoss;
            string mode = s.Eval ? cfg.EvalDrawdown : cfg.FundedDrawdown;
            if (mode == "STATIC") return s.Start - maxLoss;
            return Math.Min(s.Hwm - maxLoss, s.Start + cfg.TrailStopAt);
        }

        private static int Direction(string mode, System.Random rng, int rotationIndex, int coin)
        {
            string m = (mode ?? "BUY").ToUpperInvariant();
            if (m == "SELL") return -1;
            if (m == "RANDOM") return coin != 0 ? coin : (rng.NextDouble() < 0.5 ? 1 : -1);
            if (m == "ALTERNATE") return rotationIndex % 2 == 0 ? 1 : -1;
            return 1;
        }

        public static KeystoneHelixResult Run(List<KeystoneHelixMinute> minutes, KeystoneHelixConfig cfg)
        {
            var result = new KeystoneHelixResult { Config = cfg };
            if (minutes == null || minutes.Count == 0 || (cfg.UseMnq != 1 && cfg.UseMgc != 1)) { result.Notes.Add("No minutes or no instrument selected."); return result; }
            var dates = new List<DateTime>();
            var ranges = SessionRanges(minutes, cfg, dates);
            // Weekday filter and missing-data guard: a day where MNQ or MGC has too few real
            // 1-minute bars is not traded (its price would be carried flat and fake the basket).
            for (int k = ranges.Count - 1; k >= 0; k--)
            {
                DateTime d = dates[k]; int lo0 = ranges[k][0], hi0 = ranges[k][1], n = hi0 - lo0 + 1, realM = 0, realG = 0;
                for (int q = lo0; q <= hi0; q++) { if (minutes[q].HasMnq) realM++; if (minutes[q].HasMgc) realG++; }
                string why = null;
                int dow = d.DayOfWeek == DayOfWeek.Sunday ? 7 : (int)d.DayOfWeek;
                if (cfg.UseMnq == 1 && realM < n * cfg.MinRealBarShare) why = "MNQ has only " + realM + " of " + n + " minutes";
                else if (cfg.UseMgc == 1 && realG < n * cfg.MinRealBarShare) why = "MGC has only " + realG + " of " + n + " minutes";
                bool weekdayOff = (cfg.Weekdays ?? "12345").IndexOf((char)('0' + dow)) < 0;
                if (weekdayOff || why != null)
                {
                    if (why != null) result.SkippedDays.Insert(0, d.ToString("yyyy-MM-dd ddd", CultureInfo.InvariantCulture) + " • " + why + " • not traded");
                    ranges.RemoveAt(k); dates.RemoveAt(k);
                }
            }
            var rng = new System.Random(cfg.RandomSeed);
            var slots = new List<Slot>();
            int purchases = 0, rotationId = 0, pointer = 0;
            double expensesCounted = 0;
            Func<DateTime, int, Slot, bool> buy = null;
            buy = delegate(DateTime day, int session, Slot s)
            {
                if (cfg.MaxPurchases > 0 && purchases >= cfg.MaxPurchases) return false;
                purchases++;
                s.Instance++;
                bool eval = cfg.StartMode == "EVAL";
                s.Life = new KeystoneHelixLife { Slot = s.Index + 1, Instance = s.Instance, Id = "A" + (s.Index + 1).ToString("00") + "-I" + s.Instance.ToString("00"), StartMode = eval ? "EVAL" : "DIRECT", Bought = day, Status = eval ? "EVAL" : "FUNDED" };
                double cost = eval ? cfg.EvalCost : cfg.DirectCost;
                s.Life.Cost += cost;
                if (cost > 0) result.Expenses.Add(new KeystoneHelixExpense { Day = day, Account = s.Life.Id, Kind = eval ? "EVALUATION" : "DIRECT FUNDED", Amount = cost });
                if (!eval) s.Life.FundedDate = day;
                result.Lives.Add(s.Life);
                s.Eval = eval; s.Balance = 0; s.Hwm = 0; s.Start = 0; s.Waiting = false; s.DaysTraded = 0; s.DaysSincePayout = 0; s.FundedSessions = 0; s.BestDay = 0; s.LastResult = "FIRST";
                return true;
            };
            DateTime firstDay = dates.Count > 0 ? dates[0] : cfg.Start.Date;
            for (int k = 0; k < Math.Max(1, cfg.Accounts); k++) { var s = new Slot { Index = k }; slots.Add(s); buy(firstDay, 0, s); }
            int startingPurchases = purchases;

            for (int di = 0; di < ranges.Count; di++)
            {
                DateTime day = dates[di]; int session = di + 1;
                int lo = ranges[di][0], hi = ranges[di][1];
                var dayRow = new KeystoneHelixDay { Day = day };
                if (di == 0) dayRow.Purchases = startingPurchases;   // the starting accounts are bought on day 1
                // replacements / funded starts that become ready today
                foreach (var s in slots)
                {
                    if (!s.Waiting || s.ReadySession > session) continue;
                    if (s.Life != null && s.Life.PassDate != DateTime.MinValue && s.Life.Status == "PASSED")
                    {
                        s.Waiting = false; s.Eval = false; s.Balance = 0; s.Hwm = 0; s.Start = 0; s.DaysSincePayout = 0; s.FundedSessions = 0; s.BestDay = 0;
                        s.Life.Status = "FUNDED"; s.Life.FundedDate = day;
                    }
                    else if (s.Life != null && (s.Life.Status == "EVAL" || s.Life.Status == "FUNDED")) s.Waiting = false;   // replacement bought at a review
                    else if (cfg.AutoReplace == 1 && cfg.ReplaceTiming != "NEXT_REVIEW") { if (buy(day, session, s)) dayRow.Purchases++; }
                }
                foreach (var s in slots) { s.DayPnl = 0; s.DayLosses = 0; s.DayWins = 0; s.DayLocked = false; s.LockReason = string.Empty; s.TradedToday = false; }
                if (cfg.DayStart == "FIRST") pointer = 0;
                DateTime sessionOpen = minutes[lo].Time.AddMinutes(-1);
                DateTime nextEntry = Clock(day, cfg.SessionStartHhmm);
                if (cfg.SessionStartHhmm > cfg.SessionEndHhmm) nextEntry = nextEntry.AddDays(-1);
                DateTime lastEntry = Clock(day, cfg.LastEntryHhmm);
                if (cfg.SessionStartHhmm > cfg.SessionEndHhmm && cfg.LastEntryHhmm > cfg.SessionEndHhmm) lastEntry = lastEntry.AddDays(-1);
                int k0 = lo; int seq = 0;
                string endReason = "SESSION END";
                while (true)
                {
                    // next tradable account in rotation order
                    Slot slot = null;
                    for (int step = 0; step < slots.Count; step++)
                    {
                        var s = slots[(pointer + step) % slots.Count];
                        if (s.Waiting || s.Life == null || s.DayLocked) continue;
                        if (s.Life.Status != "EVAL" && s.Life.Status != "FUNDED") continue;
                        slot = s; break;
                    }
                    if (slot == null) { endReason = "ALL ACCOUNTS DONE"; break; }
                    while (k0 <= hi && minutes[k0].Time <= nextEntry) k0++;
                    if (k0 > hi) { endReason = "SESSION END"; break; }
                    if (minutes[k0].Time.AddMinutes(-1) > lastEntry) { endReason = "LAST ENTRY TIME"; break; }
                    var rules = slot.Eval ? cfg.Eval : cfg.Funded;
                    int qM = cfg.UseMnq == 1 ? Math.Max(0, rules.MnqContracts) : 0, qG = cfg.UseMgc == 1 ? Math.Max(0, rules.MgcContracts) : 0;
                    if (qM + qG == 0) { endReason = "NO CONTRACTS"; break; }
                    int coin = cfg.LinkRandom == 1 ? (rng.NextDouble() < 0.5 ? 1 : -1) : 0;
                    int dM = Direction(cfg.MnqDirection, rng, rotationId, coin), dG = Direction(cfg.MgcDirection, rng, rotationId, coin);
                    var entryBar = minutes[k0];
                    double slipM = cfg.SlippageTicks * MnqTick, slipG = cfg.SlippageTicks * MgcTick;
                    double eM = entryBar.MnqO + dM * slipM, eG = entryBar.MgcO + dG * slipG;
                    Func<double, double, double> value = delegate(double pM, double pG) { return (qM > 0 ? dM * (pM - eM) * MnqPoint * qM : 0) + (qG > 0 ? dG * (pG - eG) * MgcPoint * qG : 0); };
                    double exitSlip = cfg.SlippageTicks * (qM * MnqTick * MnqPoint + qG * MgcTick * MgcPoint);
                    double target = rules.RotationTarget;
                    if (rules.ShrinkTarget == 1 && rules.DailyTarget > 0) target = Math.Min(target, Math.Max(1, rules.DailyTarget - slot.DayPnl));
                    if (slot.Eval && cfg.EvalTarget > 0) target = Math.Min(target, Math.Max(1, cfg.EvalTarget - slot.Balance));
                    double stop = rules.RotationStop;
                    bool dayStopCaps = false;
                    if (rules.DailyStop > 0 && rules.DailyStop + slot.DayPnl < stop) { stop = Math.Max(0, rules.DailyStop + slot.DayPnl); dayStopCaps = true; }
                    double commission = cfg.CommissionPerSide * 2 * (qM + qG);
                    string reason = "SESSION END"; double exitValue = 0; int exitIndex = hi; bool ambiguous = false; double mfe = 0, mae = 0;
                    double hwmLocal = slot.Hwm;
                    bool trailingIntraday = (slot.Eval ? cfg.EvalDrawdown : cfg.FundedDrawdown) == "TRAILING_INTRADAY";
                    for (int k = k0; k <= hi; k++)
                    {
                        var m = minutes[k];
                        double open = value(m.MnqO, m.MgcO);
                        double best = value(dM > 0 ? m.MnqH : m.MnqL, dG > 0 ? m.MgcH : m.MgcL);
                        double worst = value(dM > 0 ? m.MnqL : m.MnqH, dG > 0 ? m.MgcL : m.MgcH);
                        double close = value(m.MnqC, m.MgcC);
                        if (trailingIntraday) hwmLocal = Math.Max(hwmLocal, slot.Balance + best - commission);
                        double threshold = trailingIntraday ? Math.Min(hwmLocal - (slot.Eval ? cfg.EvalMaxLoss : cfg.FundedMaxLoss), slot.Start + cfg.TrailStopAt) : Threshold(slot, cfg);
                        double liq = slot.Balance - commission - threshold;       // open P/L that liquidates the account
                        double effStop = Math.Min(stop, Math.Max(0, liq));
                        string stopReason = liq <= stop ? "LIQUIDATED" : (dayStopCaps ? "DAY STOP" : "STOP");
                        mfe = Math.Max(mfe, cfg.ExitModel == "NEUTRAL" ? close : best); mae = Math.Min(mae, cfg.ExitModel == "NEUTRAL" ? close : worst);
                        if (k > k0 && open <= -effStop) { reason = stopReason; exitValue = open; exitIndex = k; break; }
                        if (k > k0 && open >= target) { reason = "TARGET"; exitValue = open; exitIndex = k; break; }
                        if (cfg.ExitModel == "NEUTRAL")
                        {
                            if (close <= -effStop) { reason = stopReason; exitValue = close; exitIndex = k; break; }
                            if (close >= target) { reason = "TARGET"; exitValue = close; exitIndex = k; break; }
                        }
                        else
                        {
                            if (worst <= -effStop) { ambiguous = best >= target; reason = stopReason; exitValue = -effStop; exitIndex = k; break; }
                            if (best >= target) { reason = "TARGET"; exitValue = target; exitIndex = k; break; }
                        }
                        if (k == hi) { reason = "SESSION END"; exitValue = close; exitIndex = k; }
                    }
                    var exitBar = minutes[exitIndex];
                    double gross = exitValue - exitSlip;
                    double net = gross - commission;
                    // Leg split of the basket result (exact at the exit prices implied by the bar).
                    double mExit, gExit;
                    if (reason == "SESSION END" || cfg.ExitModel == "NEUTRAL" || (exitIndex > k0 && (Math.Abs(exitValue - value(exitBar.MnqO, exitBar.MgcO)) < 1e-6))) { bool atOpen = exitIndex > k0 && Math.Abs(exitValue - value(exitBar.MnqO, exitBar.MgcO)) < 1e-6 && reason != "SESSION END" && cfg.ExitModel != "NEUTRAL"; mExit = atOpen ? exitBar.MnqO : exitBar.MnqC; gExit = atOpen ? exitBar.MgcO : exitBar.MgcC; }
                    else
                    {
                        // Target/stop filled inside the bar: scale each leg between the entry and its extreme so the two legs add up to the basket fill.
                        double fm = reason == "TARGET" ? (dM > 0 ? exitBar.MnqH : exitBar.MnqL) : (dM > 0 ? exitBar.MnqL : exitBar.MnqH);
                        double fg = reason == "TARGET" ? (dG > 0 ? exitBar.MgcH : exitBar.MgcL) : (dG > 0 ? exitBar.MgcL : exitBar.MgcH);
                        double full = value(fm, fg), prev = value(exitBar.MnqO, exitBar.MgcO);
                        double w = Math.Abs(full - prev) < 1e-9 ? 1 : Math.Max(0, Math.Min(1, (exitValue - prev) / (full - prev)));
                        mExit = exitBar.MnqO + (fm - exitBar.MnqO) * w; gExit = exitBar.MgcO + (fg - exitBar.MgcO) * w;
                    }
                    double mPnl = qM > 0 ? dM * (mExit - eM) * MnqPoint * qM - cfg.SlippageTicks * MnqTick * MnqPoint * qM : 0;
                    double gPnl = qG > 0 ? dG * (gExit - eG) * MgcPoint * qG - cfg.SlippageTicks * MgcTick * MgcPoint * qG : 0;
                    var r = new KeystoneHelixRotation
                    {
                        Id = ++rotationId, Day = day, Slot = slot.Index + 1, Instance = slot.Instance, Account = slot.Life.Id, Stage = slot.Eval ? "EVAL" : "FUNDED", SeqInDay = ++seq, AccountTry = slot.DayWins + slot.DayLosses + 1,
                        EntryTime = entryBar.Time.AddMinutes(-1), ExitTime = exitBar.Time, MnqDir = qM > 0 ? dM : 0, MgcDir = qG > 0 ? dG : 0, MnqQty = qM, MgcQty = qG,
                        MnqEntry = eM, MgcEntry = eG, MnqExit = mExit, MgcExit = gExit, MnqPnl = mPnl, MgcPnl = gPnl, Gross = gross, Commission = commission, Net = net,
                        Target = target, Stop = stop, Reason = reason, Ambiguous = ambiguous, Mfe = mfe, Mae = mae, PrevResult = slot.LastResult
                    };
                    // context at entry (for the setup finder)
                    int back = k0; while (back > lo && minutes[back].Time > entryBar.Time.AddMinutes(-31)) back--;
                    double hiM = double.MinValue, loM = double.MaxValue, hiG = double.MinValue, loG = double.MaxValue;
                    for (int k = back; k < k0; k++) { hiM = Math.Max(hiM, minutes[k].MnqH); loM = Math.Min(loM, minutes[k].MnqL); hiG = Math.Max(hiG, minutes[k].MgcH); loG = Math.Min(loG, minutes[k].MgcL); }
                    if (k0 > back) { r.Prior30Mnq = entryBar.MnqO - minutes[back].MnqO; r.Prior30Mgc = entryBar.MgcO - minutes[back].MgcO; r.Range30Mnq = hiM - loM; r.Range30Mgc = hiG - loG; }
                    r.DayMoveMnq = entryBar.MnqO - minutes[lo].MnqO; r.DayMoveMgc = entryBar.MgcO - minutes[lo].MgcO;
                    // account update
                    slot.Balance += net; slot.DayPnl += net; slot.TradedToday = true;
                    string mode = slot.Eval ? cfg.EvalDrawdown : cfg.FundedDrawdown;
                    if (mode == "TRAILING_INTRADAY") slot.Hwm = Math.Max(slot.Hwm, hwmLocal);
                    slot.Life.Rotations++; slot.Life.TradingNet += net;
                    if (reason == "TARGET") { slot.DayWins++; slot.Life.Wins++; slot.LastResult = "WIN"; }
                    else if (net < 0) { slot.DayLosses++; slot.Life.Losses++; slot.LastResult = "LOSS"; }
                    else slot.LastResult = net > 0 ? "WIN" : "LOSS";
                    dayRow.Rotations++; dayRow.Gross += gross; dayRow.Commission += commission; dayRow.Net += net; dayRow.MnqPnl += mPnl; dayRow.MgcPnl += gPnl;
                    if (reason == "TARGET") dayRow.Wins++; else if (reason == "SESSION END") dayRow.Exits++; else dayRow.Losses++;
                    if (dayRow.FirstEntry == DateTime.MinValue) dayRow.FirstEntry = r.EntryTime;
                    dayRow.LastExit = r.ExitTime;
                    // liquidation / locks
                    if (slot.Balance <= Threshold(slot, cfg) + 0.005 || reason == "LIQUIDATED")
                    {
                        dayRow.Blowups++;
                        slot.Life.EndDate = day; slot.Life.Balance = slot.Balance;
                        if (slot.Eval) { slot.Life.Status = "FAILED EVAL"; slot.Life.EndReason = "evaluation max loss hit"; dayRow.EvalFails++; }
                        else { slot.Life.Status = "BLOWN"; slot.Life.EndReason = "funded max loss hit"; }
                        slot.Waiting = true; slot.ReadySession = cfg.ReplaceTiming == "NEXT_REVIEW" ? int.MaxValue : session + Math.Max(1, cfg.ReplaceDelaySessions);
                        r.After = slot.Eval ? "EVALUATION FAILED" : "ACCOUNT LIQUIDATED";
                    }
                    else
                    {
                        string lockReason = string.Empty;
                        if (slot.Eval && cfg.EvalTarget > 0 && slot.Balance >= cfg.EvalTarget) lockReason = "EVAL TARGET REACHED";
                        else if (rules.LockMode == "FIRST_WIN" && reason == "TARGET") lockReason = "LOCKED • FIRST WIN";
                        else if (rules.LockMode == "FIRST_PROFIT" && slot.DayPnl > 0) lockReason = "LOCKED • DAY POSITIVE";
                        else if (rules.LockMode == "DAILY_TARGET" && slot.DayPnl >= rules.DailyTarget - 0.005) lockReason = "LOCKED • DAILY TARGET";
                        else if (rules.MaxLossesPerDay > 0 && slot.DayLosses >= rules.MaxLossesPerDay) lockReason = "STOPPED • " + slot.DayLosses + " LOSSES";
                        else if (rules.DailyStop > 0 && slot.DayPnl <= -rules.DailyStop + 0.005) lockReason = "STOPPED • DAY STOP";
                        if (lockReason.Length > 0) { slot.DayLocked = true; slot.LockReason = lockReason; dayRow.Locks++; r.After = lockReason; }
                        else r.After = "NEXT ACCOUNT";
                    }
                    r.BalanceAfter = slot.Balance;
                    result.Rotations.Add(r);
                    pointer = (slot.Index + 1) % slots.Count;
                    nextEntry = exitBar.Time.AddMinutes(Math.Max(0, cfg.PauseMinutes));
                    k0 = exitIndex + 1;
                }
                dayRow.EndReason = endReason;
                // end of day: EOD trailing, evaluation checks, payouts, replacements
                bool review = cfg.PayoutCalendar == "POOL" ? (cfg.PayoutEverySessions <= 1 || session % cfg.PayoutEverySessions == 0) : true;
                dayRow.Review = cfg.PayoutCalendar == "POOL" && review;
                foreach (var s in slots)
                {
                    if (s.Waiting || s.Life == null) continue;
                    if (s.TradedToday) { s.DaysTraded++; s.Life.TradingDays++; s.DaysSincePayout++; s.BestDay = Math.Max(s.BestDay, s.DayPnl); }
                    string mode = s.Eval ? cfg.EvalDrawdown : cfg.FundedDrawdown;
                    if (mode == "TRAILING_EOD") s.Hwm = Math.Max(s.Hwm, s.Balance);
                    if (s.Life.Status == "BLOWN" || s.Life.Status == "FAILED EVAL") continue;
                    s.Life.Balance = s.Balance; s.Life.Peak = Math.Max(s.Life.Peak, s.Balance);
                    if (s.Eval)
                    {
                        bool consistent = cfg.EvalConsistency <= 0 || s.BestDay <= cfg.EvalConsistency / 100.0 * Math.Max(0.01, s.Balance) + 0.005;
                        if (s.Balance >= cfg.EvalTarget && s.DaysTraded >= cfg.EvalMinDays && consistent)
                        {
                            dayRow.EvalPasses++;
                            s.Life.PassDate = day; s.Life.Status = "PASSED";
                            if (cfg.ActivationCost > 0) { s.Life.Cost += cfg.ActivationCost; result.Expenses.Add(new KeystoneHelixExpense { Day = day, Account = s.Life.Id, Kind = "ACTIVATION", Amount = cfg.ActivationCost }); }
                            s.Waiting = true; s.ReadySession = session + 1 + Math.Max(0, cfg.FundedDelaySessions);
                        }
                        continue;
                    }
                    s.FundedSessions++;
                    bool accountReview = cfg.PayoutCalendar == "POOL" ? review : s.DaysSincePayout >= Math.Max(1, cfg.PayoutEverySessions);
                    if (!accountReview) continue;
                    if (cfg.MaxPayouts > 0 && s.Life.Payouts >= cfg.MaxPayouts) continue;
                    if (s.DaysSincePayout < cfg.PayoutMinDays) continue;
                    double profit = s.Balance - s.Start;
                    if (profit < cfg.PayoutMinProfit - 0.005) continue;
                    double threshold = Threshold(s, cfg);
                    double gross = Math.Min(cfg.PayoutCap > 0 ? cfg.PayoutCap : double.MaxValue, cfg.PayoutFraction / 100.0 * (s.Balance - threshold));
                    gross = Math.Min(gross, profit);
                    if (cfg.FundedDrawdown != "STATIC") gross = Math.Min(gross, s.Balance - threshold - 100);
                    gross = Math.Floor(Math.Max(0, gross));
                    if (gross <= 0 || gross < cfg.PayoutMinAmount) continue;
                    double cash = gross * cfg.PayoutSplit / 100.0;
                    s.Life.Payouts++; s.Life.PayoutGross += gross; s.Life.PayoutCash += cash; s.Life.LastPayout = day;
                    result.Payouts.Add(new KeystoneHelixPayout { Day = day, Account = s.Life.Id, Number = s.Life.Payouts, BalanceBefore = s.Balance, Gross = gross, Cash = cash, BalanceAfter = s.Balance - gross });
                    s.Balance -= gross; s.Life.Balance = s.Balance; s.DaysSincePayout = 0;
                    dayRow.Payouts++; dayRow.PayoutGross += gross; dayRow.PayoutCash += cash;
                }
                // replacements at the review (Manus style) or failed evaluations with a delay
                if (cfg.AutoReplace == 1 && cfg.ReplaceTiming == "NEXT_REVIEW" && (cfg.PayoutCalendar != "POOL" || review))
                    foreach (var s in slots.Where(x => x.Waiting && x.Life != null && (x.Life.Status == "BLOWN" || x.Life.Status == "FAILED EVAL")))
                    { if (buy(day, session, s)) { dayRow.Purchases++; s.Waiting = true; s.ReadySession = session + 1; s.Life.Bought = day; } }
                double expensesNow = result.Expenses.Sum(e => e.Amount);
                dayRow.Expenses = expensesNow - expensesCounted; expensesCounted = expensesNow;   // day 1 carries the starting purchases
                dayRow.ActiveEnd = slots.Count(s => !s.Waiting && s.Life != null && (s.Life.Status == "EVAL" || s.Life.Status == "FUNDED"));
                dayRow.FundedEnd = slots.Count(s => s.Life != null && s.Life.Status == "FUNDED" && !s.Waiting);
                dayRow.EvalEnd = slots.Count(s => s.Life != null && s.Life.Status == "EVAL" && !s.Waiting);
                dayRow.WaitingEnd = slots.Count(s => s.Waiting);
                dayRow.EquityEnd = slots.Where(s => s.Life != null && !s.Waiting).Sum(s => s.Balance - Threshold(s, cfg));
                result.Days.Add(dayRow);
            }
            foreach (var s in slots)
                if (s.Life != null && (s.Life.Status == "EVAL" || s.Life.Status == "FUNDED" || s.Life.Status == "PASSED")) { s.Life.Balance = s.Balance; s.Life.Status = s.Life.Status == "PASSED" ? "PASSED • WAITING" : s.Life.Status; s.Life.EndReason = "still active at the end of the test"; }
            result.MinutesUsed = ranges.Sum(r => r[1] - r[0] + 1);
            result.FilledMinutes = 0;
            foreach (var rg in ranges) for (int k = rg[0]; k <= rg[1]; k++) if ((cfg.UseMnq == 1 && !minutes[k].HasMnq) || (cfg.UseMgc == 1 && !minutes[k].HasMgc)) result.FilledMinutes++;
            return result;
        }

        public static List<KeystoneHelixMonth> Months(KeystoneHelixResult r)
        {
            var map = new SortedDictionary<DateTime, KeystoneHelixMonth>();
            Func<DateTime, KeystoneHelixMonth> get = delegate(DateTime d) { var k = new DateTime(d.Year, d.Month, 1); KeystoneHelixMonth m; if (!map.TryGetValue(k, out m)) { m = new KeystoneHelixMonth { Month = k }; map[k] = m; } return m; };
            foreach (var d in r.Days) { var m = get(d.Day); m.Sessions++; m.Rotations += d.Rotations; m.Wins += d.Wins; m.Losses += d.Losses; m.TradingNet += d.Net; m.MnqPnl += d.MnqPnl; m.MgcPnl += d.MgcPnl; m.PayoutCash += d.PayoutCash; m.Expenses += d.Expenses; m.Payouts += d.Payouts; m.Blowups += d.Blowups; m.Purchases += d.Purchases; if (d.Net > 0) m.PositiveDays++; }
            return map.Values.ToList();
        }

        // Rotation buckets: the same rules checked on the first 2/3 of the dates and the last 1/3.
        public static List<KeystoneHelixBucket> Buckets(KeystoneHelixResult r)
        {
            var list = new List<KeystoneHelixBucket>();
            var rot = r.Rotations.Where(x => x.Reason != "SESSION END").ToList();
            if (rot.Count == 0) return list;
            var days = rot.Select(x => x.Day).Distinct().OrderBy(x => x).ToList();
            DateTime split = days[Math.Min(days.Count - 1, (int)(days.Count * 2.0 / 3.0))];
            double rangeM1 = Quantile(rot.Select(x => x.Range30Mnq).ToList(), 1.0 / 3), rangeM2 = Quantile(rot.Select(x => x.Range30Mnq).ToList(), 2.0 / 3);
            double rangeG1 = Quantile(rot.Select(x => x.Range30Mgc).ToList(), 1.0 / 3), rangeG2 = Quantile(rot.Select(x => x.Range30Mgc).ToList(), 2.0 / 3);
            var keys = new List<Func<KeystoneHelixRotation, string[]>>
            {
                x => new[] { "ENTRY HOUR", x.EntryTime.ToString("HH", CultureInfo.InvariantCulture) + ":00" },
                x => new[] { "ENTRY HALF-HOUR", x.EntryTime.ToString("HH", CultureInfo.InvariantCulture) + ":" + (x.EntryTime.Minute < 30 ? "00" : "30") },
                x => new[] { "WEEKDAY", x.Day.DayOfWeek.ToString().ToUpperInvariant() },
                x => new[] { "MNQ LAST 30 MIN", x.Prior30Mnq > 5 ? "UP > 5 PTS" : x.Prior30Mnq < -5 ? "DOWN > 5 PTS" : "FLAT" },
                x => new[] { "MGC LAST 30 MIN", x.Prior30Mgc > 1 ? "UP > 1 PT" : x.Prior30Mgc < -1 ? "DOWN > 1 PT" : "FLAT" },
                x => new[] { "BOTH LAST 30 MIN", (x.Prior30Mnq >= 0 ? "MNQ UP" : "MNQ DOWN") + " / " + (x.Prior30Mgc >= 0 ? "MGC UP" : "MGC DOWN") },
                x => new[] { "DAY SO FAR", (x.DayMoveMnq >= 0 ? "MNQ UP" : "MNQ DOWN") + " / " + (x.DayMoveMgc >= 0 ? "MGC UP" : "MGC DOWN") },
                x => new[] { "MNQ 30-MIN RANGE", x.Range30Mnq <= rangeM1 ? "QUIET" : x.Range30Mnq <= rangeM2 ? "NORMAL" : "WILD" },
                x => new[] { "MGC 30-MIN RANGE", x.Range30Mgc <= rangeG1 ? "QUIET" : x.Range30Mgc <= rangeG2 ? "NORMAL" : "WILD" },
                x => new[] { "ACCOUNT TRY TODAY", x.AccountTry >= 4 ? "4TH+" : x.AccountTry == 1 ? "1ST" : x.AccountTry == 2 ? "2ND" : "3RD" },
                x => new[] { "POOL BASKET # TODAY", x.SeqInDay <= 5 ? "1–5" : x.SeqInDay <= 10 ? "6–10" : x.SeqInDay <= 20 ? "11–20" : "21+" },
                x => new[] { "ACCOUNT'S LAST BASKET", x.PrevResult },
                x => new[] { "STAGE", x.Stage },
                x => new[] { "DIRECTION", (x.MnqDir > 0 ? "MNQ BUY" : x.MnqDir < 0 ? "MNQ SELL" : "NO MNQ") + " / " + (x.MgcDir > 0 ? "MGC BUY" : x.MgcDir < 0 ? "MGC SELL" : "NO MGC") }
            };
            foreach (var key in keys)
                foreach (var g in rot.GroupBy(x => key(x)[1]))
                {
                    var b = new KeystoneHelixBucket { Group = key(g.First())[0], Name = g.Key };
                    foreach (var x in g)
                    {
                        bool win = x.Reason == "TARGET";
                        b.Count++; b.Net += x.Net; if (win) b.Wins++;
                        if (x.Day < split) { b.EarlyCount++; b.EarlyNet += x.Net; if (win) b.EarlyWins++; } else { b.LateCount++; b.LateNet += x.Net; if (win) b.LateWins++; }
                    }
                    list.Add(b);
                }
            double avgTarget = rot.Average(x => x.Target), avgStop = rot.Average(x => x.Stop);
            double breakEven = avgStop / Math.Max(1, avgTarget + avgStop);
            double overall = r.WinRate;
            foreach (var b in list)
            {
                if (b.Count < 30 || b.EarlyCount < 15 || b.LateCount < 10) { b.Verdict = "TOO FEW"; continue; }
                bool earlyBetter = b.EarlyRate > overall + 0.02 && b.EarlyNet > 0, lateBetter = b.LateRate > breakEven && b.LateNet > 0;
                bool earlyWorse = b.EarlyRate < overall - 0.02 && b.EarlyNet < 0, lateWorse = b.LateRate < breakEven && b.LateNet < 0;
                b.Verdict = earlyBetter && lateBetter ? "STRONGER • HOLDS" : earlyWorse && lateWorse ? "WEAKER • AVOID" : earlyBetter ? "FADED LATER" : earlyWorse ? "RECOVERED LATER" : "NO DIFFERENCE";
            }
            return list;
        }

        private static double Quantile(List<double> v, double q)
        {
            if (v.Count == 0) return 0;
            v.Sort(); return v[Math.Max(0, Math.Min(v.Count - 1, (int)(q * (v.Count - 1))))];
        }

        public static double BreakEvenWinRate(KeystoneHelixResult r)
        {
            var rot = r.Rotations.Where(x => x.Reason == "TARGET" || x.Reason == "STOP").ToList();
            if (rot.Count == 0) return r.Config == null ? 0 : r.Config.Funded.RotationStop / Math.Max(1, r.Config.Funded.RotationTarget + r.Config.Funded.RotationStop);
            double win = rot.Where(x => x.Reason == "TARGET").Select(x => x.Net).DefaultIfEmpty(r.Config.Funded.RotationTarget).Average();
            double loss = -rot.Where(x => x.Reason == "STOP").Select(x => x.Net).DefaultIfEmpty(-r.Config.Funded.RotationStop).Average();
            return loss / Math.Max(1, win + loss);
        }

        // With no trading edge at all, the rules alone: an account needs +G before it loses its cushion C.
        // A fair coin reaches +G first about C/(C+G) of the time; each payout returns it near its start.
        public static double ZeroEdgeValuePerAccount(KeystoneHelixConfig c, out double reachFirst, out double expectedPayouts)
        {
            double cushion = Math.Max(1, c.FundedMaxLoss), need = Math.Max(1, c.PayoutMinProfit);
            reachFirst = cushion / (cushion + need);
            double gross = Math.Min(c.PayoutCap > 0 ? c.PayoutCap : double.MaxValue, c.PayoutFraction / 100.0 * (cushion + need));
            gross = Math.Min(gross, need);
            expectedPayouts = reachFirst >= 0.999 ? 50 : reachFirst / (1 - reachFirst);
            if (c.MaxPayouts > 0) expectedPayouts = Math.Min(expectedPayouts, c.MaxPayouts);
            double cost = c.StartMode == "EVAL" ? c.EvalCost + c.ActivationCost : c.DirectCost;
            if (c.StartMode == "EVAL")
            {
                double passChance = Math.Max(1, c.EvalMaxLoss) / (Math.Max(1, c.EvalMaxLoss) + Math.Max(1, c.EvalTarget));
                return passChance * (expectedPayouts * gross * c.PayoutSplit / 100.0 - c.ActivationCost) - c.EvalCost;
            }
            return expectedPayouts * gross * c.PayoutSplit / 100.0 - cost;
        }

        public static KeystoneHelixProofRow Row(string group, string label, KeystoneHelixResult r, string note)
        {
            return new KeystoneHelixProofRow { Group = group, Label = label, Note = note ?? string.Empty, NetCash = r.NetCash, PayoutCash = r.PayoutCash, Expenses = r.ExpenseTotal, TradingNet = r.TradingNet, WinRate = r.WinRate, Payouts = r.Payouts.Count, Blowups = r.Blowups, Rotations = r.Rotations.Count, Purchases = r.Lives.Count, Low = r.NetCash, High = r.NetCash };
        }

        // Proof tests: is the result the method, the market's direction, luck, costs or the period?
        public static List<KeystoneHelixProofRow> Proof(List<KeystoneHelixMinute> minutes, KeystoneHelixConfig baseCfg, KeystoneHelixResult baseResult, int randomRuns, Action<string> progress)
        {
            var rows = new List<KeystoneHelixProofRow>();
            Func<string, string, KeystoneHelixConfig, string, KeystoneHelixProofRow> run = delegate(string group, string label, KeystoneHelixConfig c, string note)
            {
                if (progress != null) progress(group + " • " + label);
                var row = Row(group, label, Run(minutes, c), note); rows.Add(row); return row;
            };
            var b = Row("BASE", "YOUR SETTINGS", baseResult ?? Run(minutes, baseCfg), baseCfg.Describe()); b.IsBase = true; rows.Add(b);
            KeystoneHelixConfig c1;
            c1 = baseCfg.Copy(); c1.MnqDirection = "BUY"; c1.MgcDirection = "BUY"; run("DIRECTION", "BUY MNQ + BUY MGC", c1, "the Manus 9:30 LL basket");
            c1 = baseCfg.Copy(); c1.MnqDirection = "SELL"; c1.MgcDirection = "SELL"; run("DIRECTION", "SELL MNQ + SELL MGC", c1, "mirror image: if BUY wins and SELL loses by the same, the edge is market direction");
            c1 = baseCfg.Copy(); c1.MnqDirection = "BUY"; c1.MgcDirection = "SELL"; run("DIRECTION", "BUY MNQ + SELL MGC", c1, "one long, one short (allowed: different instruments)");
            c1 = baseCfg.Copy(); c1.MnqDirection = "SELL"; c1.MgcDirection = "BUY"; run("DIRECTION", "SELL MNQ + BUY MGC", c1, string.Empty);
            // truly random directions, many coin sequences
            var nets = new List<KeystoneHelixProofRow>();
            for (int s = 1; s <= Math.Max(3, randomRuns); s++)
            {
                c1 = baseCfg.Copy(); c1.MnqDirection = "RANDOM"; c1.MgcDirection = "RANDOM"; c1.RandomSeed = 1000 + s;
                if (progress != null) progress("RANDOM DIRECTIONS • run " + s + " of " + Math.Max(3, randomRuns));
                nets.Add(Row("RANDOM", "run " + s, Run(minutes, c1), string.Empty));
            }
            nets = nets.OrderBy(x => x.NetCash).ToList();
            var median = nets[nets.Count / 2];
            var rr = new KeystoneHelixProofRow { Group = "RANDOM", Label = "RANDOM DIRECTIONS • " + nets.Count + " RUNS (MEDIAN)", NetCash = median.NetCash, PayoutCash = median.PayoutCash, Expenses = median.Expenses, TradingNet = median.TradingNet, WinRate = nets.Average(x => x.WinRate), Payouts = median.Payouts, Blowups = median.Blowups, Rotations = median.Rotations, Purchases = median.Purchases, Low = nets[(int)(nets.Count * 0.1)].NetCash, High = nets[Math.Min(nets.Count - 1, (int)(nets.Count * 0.9))].NetCash, Note = "the zero-edge baseline • range = worst 10% to best 10% of coin sequences" };
            rows.Add(rr);
            if (baseCfg.UseMnq == 1 && baseCfg.UseMgc == 1)
            {
                c1 = baseCfg.Copy(); c1.UseMgc = 0; run("INSTRUMENT", "MNQ ONLY", c1, "same contracts and $ target/stop");
                c1 = baseCfg.Copy(); c1.UseMnq = 0; run("INSTRUMENT", "MGC ONLY", c1, "same contracts and $ target/stop");
            }
            c1 = baseCfg.Copy(); c1.ExitModel = baseCfg.ExitModel == "STRICT" ? "NEUTRAL" : "STRICT"; run("EXECUTION", c1.ExitModel + " FILLS", c1, c1.ExitModel == "NEUTRAL" ? "exits on minute closes (no stop-first assumption)" : "stop first when a minute touches both");
            c1 = baseCfg.Copy(); c1.CommissionPerSide = 0; c1.SlippageTicks = 0; run("EXECUTION", "NO COSTS", c1, "what Manus modelled (no commission, no slippage)");
            c1 = baseCfg.Copy(); c1.CommissionPerSide *= 2; c1.SlippageTicks = Math.Max(1, c1.SlippageTicks * 2); run("EXECUTION", "COSTS × 2", c1, "bad fills stress test");
            var days = minutes.Select(m => m.Time.Date).Distinct().Where(d => d >= baseCfg.Start.Date && d <= baseCfg.End.Date).OrderBy(d => d).ToList();
            if (days.Count > 20)
            {
                DateTime mid = days[days.Count / 2];
                c1 = baseCfg.Copy(); c1.End = mid.AddDays(-1); run("PERIOD", "FIRST HALF " + days[0].ToString("yyyy-MM-dd") + " → " + mid.AddDays(-1).ToString("yyyy-MM-dd"), c1, "fresh accounts");
                c1 = baseCfg.Copy(); c1.Start = mid; run("PERIOD", "SECOND HALF " + mid.ToString("yyyy-MM-dd") + " → " + days[days.Count - 1].ToString("yyyy-MM-dd"), c1, "fresh accounts");
            }
            foreach (int start in new[] { 800, 830, 900, 930, 945, 1000, 1030, 1100, 1200, 1300, 1400 })
            {
                if (start >= baseCfg.SessionEndHhmm - 30 && baseCfg.SessionStartHhmm < baseCfg.SessionEndHhmm) continue;
                c1 = baseCfg.Copy(); c1.SessionStartHhmm = start; if (c1.LastEntryHhmm <= start) c1.LastEntryHhmm = Math.Max(start + 15, baseCfg.LastEntryHhmm);
                run("START TIME", "START " + Hhmm(start), c1, start == baseCfg.SessionStartHhmm ? "your start" : string.Empty);
            }
            foreach (int pause in new[] { 0, 1, 2, 3, 5, 10 })
            {
                c1 = baseCfg.Copy(); c1.PauseMinutes = pause;
                run("PAUSE", "PAUSE " + pause + " MIN", c1, pause == baseCfg.PauseMinutes ? "your pause" : string.Empty);
            }
            foreach (int n in new[] { 5, 10, 20, 40 })
            {
                c1 = baseCfg.Copy(); c1.Accounts = n;
                run("ACCOUNTS", n + " ACCOUNTS", c1, n == baseCfg.Accounts ? "your pool" : string.Empty);
            }
            return rows;
        }

        // Manus workbook (9:30 LL, 10 accounts) day rows • "yyyyMMdd,pnl,locks,stops,liquidations,attempts;..."
        public static List<KeystoneHelixManusDay> ParseManus(string packed)
        {
            var list = new List<KeystoneHelixManusDay>();
            if (string.IsNullOrEmpty(packed)) return list;
            foreach (string item in packed.Split(';'))
            {
                string[] p = item.Split(',');
                if (p.Length < 6) continue;
                DateTime d;
                if (!DateTime.TryParseExact(p[0], "yyyyMMdd", CultureInfo.InvariantCulture, DateTimeStyles.None, out d)) continue;
                list.Add(new KeystoneHelixManusDay { Day = d, Pnl = double.Parse(p[1], CultureInfo.InvariantCulture), Locks = int.Parse(p[2], CultureInfo.InvariantCulture), Stops = int.Parse(p[3], CultureInfo.InvariantCulture), Liquidations = int.Parse(p[4], CultureInfo.InvariantCulture), Attempts = int.Parse(p[5], CultureInfo.InvariantCulture) });
            }
            return list;
        }

        public static List<KeystoneHelixManusCompareRow> CompareManus(KeystoneHelixResult r, List<KeystoneHelixManusDay> manus)
        {
            var map = new SortedDictionary<DateTime, KeystoneHelixManusCompareRow>();
            DateTime from = r.Days.Count == 0 ? DateTime.MinValue : r.Days[0].Day, to = r.Days.Count == 0 ? DateTime.MaxValue : r.Days[r.Days.Count - 1].Day;
            foreach (var m in manus.Where(x => x.Day >= from && x.Day <= to)) map[m.Day] = new KeystoneHelixManusCompareRow { Day = m.Day, Manus = m.Pnl, ManusWins = m.Locks, ManusLosses = m.Stops, HasManus = true };
            foreach (var d in r.Days)
            {
                KeystoneHelixManusCompareRow row;
                if (!map.TryGetValue(d.Day, out row)) { row = new KeystoneHelixManusCompareRow { Day = d.Day }; map[d.Day] = row; }
                row.Keystone = d.Gross; row.KeystoneWins = d.Wins; row.KeystoneLosses = d.Losses; row.HasKeystone = true;
            }
            return map.Values.ToList();
        }

        public static KeystoneHelixConfig ManusPreset(DateTime start, DateTime end, int accounts)
        {
            var c = new KeystoneHelixConfig { Start = start, End = end, Label = "MANUS 9:30 LL", MnqDirection = "BUY", MgcDirection = "BUY", SessionStartHhmm = 930, LastEntryHhmm = 1559, SessionEndHhmm = 1600, PauseMinutes = 2, DayStart = "FIRST", ExitModel = "STRICT", CommissionPerSide = 0, SlippageTicks = 0, Accounts = accounts, StartMode = "DIRECT", DirectCost = 500, FundedMaxLoss = 2000, FundedDrawdown = "STATIC", PayoutEverySessions = 5, PayoutCalendar = "POOL", PayoutMinProfit = 2000, PayoutFraction = 50, PayoutCap = 2000, PayoutSplit = 80, PayoutMinAmount = 0, AutoReplace = 1, ReplaceTiming = "NEXT_REVIEW" };
            c.Funded = new KeystoneHelixStageRules { MnqContracts = 10, MgcContracts = 10, RotationTarget = 1000, RotationStop = 500, LockMode = "FIRST_WIN", DailyTarget = 1000, MaxLossesPerDay = 0, DailyStop = 0 };
            c.Eval = c.Funded.Copy();
            return c;
        }
    }

    // Manus workbook "NinjaTrader.xlsx" (9:30 AM LL pools, NOT confirmed): per day
    // yyyyMMdd,pnl,target locks,rotation stops,liquidations,attempts. Used only by the MANUS CHECK.
    // ---- RECOIL • ADD TO LOSERS (Build 30w) ------------------------------------------------------
    // From the start time the instrument must move TRIGGER points away from its start price; then we
    // enter AGAINST the move (down → BUY, up → SELL) and add contracts every STEP points further against
    // us, up to MAX ENTRIES. Every contract keeps its own fill price: P/L = direction × Σ (price − fill) ×
    // qty × $ per point. The ladder closes at its profit target, at the maximum drawdown, or at the close.
    // Fills on 1-minute bars, conservatively: entries / adds are limit orders (a gap fills at the open,
    // never better than the bar allows), the stop is checked before the target inside a minute, and a
    // target after an add in the same minute only counts when the minute CLOSES beyond it.
    public sealed class KeystoneRecoilConfig
    {
        public DateTime Start = DateTime.MinValue, End = DateTime.MaxValue;   // session dates, inclusive
        public int UseMnq = 1, UseMgc = 0;
        public int MnqStartHhmm = 930, MgcStartHhmm = 930, LastEntryHhmm = 1500, CloseHhmm = 1600;
        public double MnqTrigger = 100, MgcTrigger = 20, MnqStep = 100, MgcStep = 20;
        public string Ladder = "ONE";                 // ONE: +1 contract per add (1,2,3,4) • STEP: add 1,2,3,4 (1,3,6,10) • DOUBLE: 1,1,2,4 (1,2,4,8)
        public int MaxEntries = 4, BaseQty = 1;
        public string TargetMode = "DOLLARS";         // DOLLARS for the whole ladder • POINTS from the average price
        public double TargetDollars = 400, MnqTargetPoints = 50, MgcTargetPoints = 10;
        public string DrawdownMode = "SHARED";        // SHARED: MNQ + MGC together (and the day's closed cycles) • SPLIT: each instrument its own
        public double MaxDrawdown = 2000, MnqMaxDrawdown = 2000, MgcMaxDrawdown = 2000;
        public int CyclesPerDay = 1;                  // after a win a new cycle starts from the exit price
        public string Mode = "ADD";                   // ADD: add to the loser • REVERSE: after STEP points against, close and reverse with the next size (1 → 2 → 3 → 4)
        public double MnqPointValue = 2, MgcPointValue = 10;   // $ per point per contract (CFD: $ per point per lot)
        public double CommissionPerSide = 0.62, SlippageTicks = 1;
        public string Weekdays = "12345";
        public KeystoneRecoilConfig Copy() { return (KeystoneRecoilConfig)MemberwiseClone(); }
        public static string Hhmm(int v) { return (v / 100).ToString("00") + ":" + (v % 100).ToString("00"); }
        public string Instruments() { return UseMnq == 1 && UseMgc == 1 ? "MNQ + MGC" : UseMgc == 1 ? "MGC" : "MNQ"; }
        public string LadderText()
        {
            var q = new List<int>(); int tot = 0;
            for (int k = 0; k < Math.Max(1, MaxEntries); k++) { tot += KeystoneRecoil.AddQty(this, k); q.Add(Mode == "REVERSE" ? KeystoneRecoil.ReverseQty(this, k) : tot); }
            return string.Join(" → ", q.Select(x => x.ToString(CultureInfo.InvariantCulture))) + " contracts";
        }
        public string Describe()
        {
            Func<double, string> n = v => v.ToString("0.##", CultureInfo.InvariantCulture);
            return (Mode == "REVERSE" ? "STOP AND REVERSE • " : "ADD TO LOSERS • ") + Instruments() + " • start " + (UseMnq == 1 ? "MNQ " + Hhmm(MnqStartHhmm) : "") + (UseMnq == 1 && UseMgc == 1 ? " / " : "") + (UseMgc == 1 ? "MGC " + Hhmm(MgcStartHhmm) : "") + " • last entry " + Hhmm(LastEntryHhmm) + " • close " + Hhmm(CloseHhmm)
                + " • trigger / add every " + (UseMnq == 1 ? "MNQ " + n(MnqTrigger) + "/" + n(MnqStep) : "") + (UseMnq == 1 && UseMgc == 1 ? " • " : "") + (UseMgc == 1 ? "MGC " + n(MgcTrigger) + "/" + n(MgcStep) : "") + " pts • " + (Mode == "REVERSE" ? "sizes " + LadderText().Replace(" contracts", "") + " (each step the other way)" : "ladder " + LadderText())
                + " • target " + (TargetMode == "POINTS" ? "+" + n(MnqTargetPoints) + " / " + n(MgcTargetPoints) + " pts from the average" : "$" + n(TargetDollars)) + " • max drawdown " + (DrawdownMode == "SPLIT" && UseMnq == 1 && UseMgc == 1 ? "MNQ $" + n(MnqMaxDrawdown) + " / MGC $" + n(MgcMaxDrawdown) : "$" + n(MaxDrawdown) + (UseMnq == 1 && UseMgc == 1 ? (Mode == "REVERSE" ? " each" : " shared") : ""))
                + " • " + CyclesPerDay + " cycle(s)/day • costs $" + n(CommissionPerSide) + "/side + " + n(SlippageTicks) + " tick on market exits";
        }
    }

    public sealed class KeystoneRecoilFill { public DateTime Time; public double Price, Level, Avg, TargetPrice, StopPrice; public int Qty, TotalQty, Dir; public bool Gap; }

    public sealed class KeystoneRecoilCycle
    {
        public int Id, CycleInDay, Dir;
        public string Mode = "ADD";        // ADD or REVERSE (each fill is then one step, the other way, closing the step before it)
        public DateTime Day, AnchorTime, ExitTime = DateTime.MinValue, LowestTime = DateTime.MinValue, BestAfterLowestTime = DateTime.MinValue;
        public string Symbol = string.Empty, Reason = string.Empty;
        public double AnchorPrice, TriggerLevel, ExitPrice, Gross, Commission, Slippage, Net, PointValue, Step, MaeValue, MfeValue, AvgAtExit;
        public double LowestPrice = double.NaN, BestAfterLowest = double.NaN, FullLadderAtLowest, FullLadderAtBest; public int FullLadderEntries;
        public bool Ambiguous;
        public List<KeystoneRecoilFill> Fills = new List<KeystoneRecoilFill>();
        public int Entries { get { return Fills.Count; } }
        public int MaxQty { get { return Fills.Count == 0 ? 0 : Fills[Fills.Count - 1].TotalQty; } }
        public bool Win { get { return Reason == "TARGET"; } }
        public bool Blown { get { return Reason == "BLOWUP"; } }
        public DateTime EntryTime { get { return Fills.Count == 0 ? DateTime.MinValue : Fills[0].Time; } }
        public string Side { get { return Dir > 0 ? "BUY" : "SELL"; } }
    }

    public sealed class KeystoneRecoilResult
    {
        public KeystoneRecoilConfig Config;
        public List<KeystoneRecoilCycle> Cycles = new List<KeystoneRecoilCycle>();
        public List<DateTime> Days = new List<DateTime>();
        public Dictionary<string, int> NoTriggerDays = new Dictionary<string, int>();
        public List<string> SkippedDays = new List<string>();
        public List<string> Notes = new List<string>();
        public double Net { get { return Cycles.Sum(c => c.Net); } }
        public int Wins { get { return Cycles.Count(c => c.Win); } }
        public int Blowups { get { return Cycles.Count(c => c.Blown); } }
        public int SessionEnds { get { return Cycles.Count(c => c.Reason == "SESSION END"); } }
    }

    public static class KeystoneRecoil
    {
        public const double MnqTick = 0.25, MgcTick = 0.1;

        public static int AddQty(KeystoneRecoilConfig c, int k)
        {
            int b = Math.Max(1, c.BaseQty);
            string m = (c.Ladder ?? "ONE").ToUpperInvariant();
            if (m == "STEP") return b * (k + 1);
            if (m == "DOUBLE") return k == 0 ? b : b * (1 << Math.Min(20, k - 1));
            return b;
        }

        static DateTime Clock(DateTime day, int hhmm) { return day.Date.AddHours(hhmm / 100).AddMinutes(hhmm % 100); }

        // One open ladder.
        sealed class Leg
        {
            public string Symbol; public bool Mgc; public double Pv, Tick, Trigger, Step, OwnDd, TargetPts;
            public int StartHhmm;
            public bool Active, Waiting, DayDone; public int CyclesToday;
            public double Anchor; public DateTime AnchorTime;
            public KeystoneRecoilCycle Cycle;
            public double S, Q;               // Σ price×qty and Σ qty of the fills (REVERSE: the open step only)
            public double Realized, RevComm, RevSlip;   // REVERSE: P/L, commission and slippage of the closed steps
            public double Avg { get { return Q <= 0 ? double.NaN : S / Q; } }
            public int NextAdd { get { return Cycle == null ? 0 : Cycle.Fills.Count; } }
        }

        static double O(KeystoneHelixMinute m, Leg l) { return l.Mgc ? m.MgcO : m.MnqO; }
        static double H(KeystoneHelixMinute m, Leg l) { return l.Mgc ? m.MgcH : m.MnqH; }
        static double L(KeystoneHelixMinute m, Leg l) { return l.Mgc ? m.MgcL : m.MnqL; }
        static double C(KeystoneHelixMinute m, Leg l) { return l.Mgc ? m.MgcC : m.MnqC; }
        static bool Real(KeystoneHelixMinute m, Leg l) { return l.Mgc ? m.HasMgc : m.HasMnq; }

        // P/L of the ladder at a price: direction × Σ (price − fill) × qty × $/point.
        public static double Value(KeystoneRecoilCycle c, double price) { return Value(c, price, DateTime.MaxValue); }
        // P/L at a price counting only the fills made by time t. REVERSE: every step before the last was closed at the next step's price.
        public static double Value(KeystoneRecoilCycle c, double price, DateTime t)
        {
            var fs = c.Fills.Where(f => f.Time <= t).ToList();
            double v = 0;
            if (c.Mode == "REVERSE")
            {
                for (int k = 0; k < fs.Count; k++) { var f = fs[k]; double exit = k + 1 < fs.Count ? fs[k + 1].Price : price; v += f.Dir * (exit - f.Price) * f.Qty * c.PointValue; }
                return v;
            }
            foreach (var f in fs) v += c.Dir * (price - f.Price) * f.Qty * c.PointValue; return v;
        }
        // STOP AND REVERSE sizes: step k uses the ladder's k-th total (1, 2, 3, 4 with +1 each).
        public static int ReverseQty(KeystoneRecoilConfig c, int k) { int t = 0; for (int i = 0; i <= k; i++) t += AddQty(c, i); return t; }
        static double Value(Leg l, double price) { return l.Cycle.Dir * (l.Q * price - l.S) * l.Pv; }
        static double LevelOf(Leg l, int k) { return l.Cycle.Fills[0].Price - l.Cycle.Dir * k * l.Step; }
        static double TargetPrice(Leg l, KeystoneRecoilConfig c)
        {
            if (c.TargetMode == "POINTS") return l.Avg + l.Cycle.Dir * l.TargetPts;
            return l.Avg + l.Cycle.Dir * c.TargetDollars / (l.Q * l.Pv);
        }
        // Price where the ladder (with every add that fills on the way) reaches −dd: S, Q advance through the add levels.
        static double StopPrice(Leg l, KeystoneRecoilConfig c, double dd, out int addsBefore)
        {
            double S = l.S, Q = l.Q; int k = l.NextAdd; addsBefore = 0; int dir = l.Cycle.Dir;
            while (true)
            {
                double s = (S - dir * dd / l.Pv) / Q;
                if (k < c.MaxEntries)
                {
                    double lv = LevelOf(l, k);
                    if (dir * (s - lv) <= 0) { int q = AddQty(c, k); S += lv * q; Q += q; k++; addsBefore++; continue; }
                }
                return s;
            }
        }
        static void AddFill(Leg l, KeystoneRecoilConfig c, DateTime t, double price, double level, bool gap)
        {
            int q = AddQty(c, l.Cycle.Fills.Count);
            l.S += price * q; l.Q += q;
            var f = new KeystoneRecoilFill { Time = t, Price = price, Level = level, Qty = q, TotalQty = (int)l.Q, Dir = l.Cycle.Dir, Avg = l.Avg, Gap = gap };
            l.Cycle.Fills.Add(f);
            f.TargetPrice = TargetPrice(l, c);
            int ignored; f.StopPrice = c.DrawdownMode == "SHARED" && c.UseMnq == 1 && c.UseMgc == 1 ? double.NaN : StopPrice(l, c, l.OwnDd, out ignored);
        }
        // Adds whose level the price reached (adverse side), filled at their level (or at the open on a gap).
        static void FillAddsTo(Leg l, KeystoneRecoilConfig c, DateTime t, double price, bool atOpen)
        {
            while (l.NextAdd < c.MaxEntries)
            {
                double lv = LevelOf(l, l.NextAdd);
                if (l.Cycle.Dir * (price - lv) > 0) break;
                AddFill(l, c, t, atOpen ? price : lv, lv, atOpen);
            }
        }
        static void Track(Leg l, double adv, double fav)
        {
            l.Cycle.MaeValue = Math.Min(l.Cycle.MaeValue, Value(l, adv));
            l.Cycle.MfeValue = Math.Max(l.Cycle.MfeValue, Value(l, fav));
        }

        // ---- STOP AND REVERSE -------------------------------------------------------------------
        // Step k: ReverseQty(k) contracts in direction (−1)^k × the first direction. Stop STEP points against (never past the
        // max drawdown left); the target makes the WHOLE cycle +TARGET $ (it covers the closed steps' losses).
        static void AddReverseFill(Leg l, KeystoneRecoilConfig c, DateTime t, double price, int dir, bool gap)
        {
            int k = l.Cycle.Fills.Count, q = ReverseQty(c, k);
            l.S = price * q; l.Q = q;
            double room = l.OwnDd + l.Realized;
            double stopPts = Math.Min(l.Step, Math.Max(0, room) / (q * l.Pv));
            var f = new KeystoneRecoilFill { Time = t, Price = price, Level = price, Qty = q, TotalQty = q, Dir = dir, Avg = price, Gap = gap };
            f.TargetPrice = c.TargetMode == "POINTS" ? price + dir * l.TargetPts : price + dir * (c.TargetDollars - l.Realized) / (q * l.Pv);
            f.StopPrice = price - dir * stopPts;
            l.Cycle.Fills.Add(f);
        }
        static double RevValue(Leg l, double price) { var f = l.Cycle.Fills[l.Cycle.Fills.Count - 1]; return l.Realized + f.Dir * (price - f.Price) * f.Qty * l.Pv; }
        // The open step is stopped at a price: book it; reverse with the next size, or end the cycle (BLOWUP) when no step is left.
        static bool ReverseStep(Leg l, KeystoneRecoilConfig c, DateTime t, double price, bool gap, KeystoneRecoilResult r)
        {
            var f = l.Cycle.Fills[l.Cycle.Fills.Count - 1];
            bool last = l.Cycle.Fills.Count >= c.MaxEntries || l.OwnDd + RevValue(l, price) <= 1e-6;
            if (last) { CloseReverse(l, c, t, price, "BLOWUP", true, r); return false; }
            l.Realized += f.Dir * (price - f.Price) * f.Qty * l.Pv;
            l.RevComm += c.CommissionPerSide * 2 * f.Qty; l.RevSlip += c.SlippageTicks * l.Tick * l.Pv * f.Qty;
            AddReverseFill(l, c, t, price, -f.Dir, gap);
            return true;
        }
        static void CloseReverse(Leg l, KeystoneRecoilConfig c, DateTime t, double price, string reason, bool market, KeystoneRecoilResult r)
        {
            var cy = l.Cycle; var f = cy.Fills[cy.Fills.Count - 1];
            cy.ExitTime = t; cy.ExitPrice = price; cy.Reason = reason; cy.AvgAtExit = f.Price;
            cy.Gross = RevValue(l, price);
            cy.Commission = l.RevComm + c.CommissionPerSide * 2 * f.Qty;
            cy.Slippage = l.RevSlip + (market ? c.SlippageTicks * l.Tick * l.Pv * f.Qty : 0);
            cy.Net = cy.Gross - cy.Commission - cy.Slippage;
            r.Cycles.Add(cy);
            l.Active = false; l.Cycle = null; l.S = 0; l.Q = 0; l.Realized = 0; l.RevComm = 0; l.RevSlip = 0; l.CyclesToday++;
            if (reason == "TARGET" && l.CyclesToday < Math.Max(1, c.CyclesPerDay)) { l.Waiting = true; l.Anchor = price; l.AnchorTime = t; }
            else l.DayDone = true;
        }
        // One minute of an open STOP AND REVERSE cycle, walked along the minute's price path: open → the extreme nearer the
        // open → the other extreme → close. On each straight piece the open step's stop (adverse) or target (favourable) is
        // hit at its exact price; a stop reverses there and the rest of the piece continues with the new step.
        static void ReverseMinute(Leg l, KeystoneRecoilConfig c, KeystoneHelixMinute m, bool entryMinute, KeystoneRecoilResult r)
        {
            double o = O(m, l), hi = H(m, l), lo = L(m, l), cl = C(m, l);
            bool lowFirst = Math.Abs(o - lo) < Math.Abs(hi - o);
            double e1 = lowFirst ? lo : hi, e2 = lowFirst ? hi : lo;
            double cur; var path = new List<double>();
            if (entryMinute)
            {
                var f0 = l.Cycle.Fills[0];
                bool trigByE1 = f0.Dir > 0 ? lowFirst : !lowFirst;   // a BUY was triggered on the way to the low
                cur = f0.Price;
                if (f0.Gap) { path.Add(e1); path.Add(e2); path.Add(cl); }
                else if (trigByE1) { path.Add(e1); path.Add(e2); path.Add(cl); }
                else { path.Add(e2); path.Add(cl); }
            }
            else
            {
                while (l.Active)
                {
                    var f = l.Cycle.Fills[l.Cycle.Fills.Count - 1];
                    if (f.Dir * (o - f.StopPrice) <= 0) { if (!ReverseStep(l, c, m.Time, o, true, r)) return; continue; }
                    if (f.Dir * (o - f.TargetPrice) >= 0) { CloseReverse(l, c, m.Time, o, "TARGET", false, r); return; }
                    break;
                }
                cur = o; path.Add(e1); path.Add(e2); path.Add(cl);
            }
            foreach (double p in path) { if (!ReverseWalk(l, c, m, cur, p, r)) return; cur = p; }
        }
        static bool ReverseWalk(Leg l, KeystoneRecoilConfig c, KeystoneHelixMinute m, double a, double b, KeystoneRecoilResult r)
        {
            int guard = 0;
            while (l.Active && guard++ < 50)
            {
                var f = l.Cycle.Fills[l.Cycle.Fills.Count - 1]; int d = f.Dir;
                if (d * (b - a) < 0)
                {
                    if (d * (b - f.StopPrice) <= 0 && d * (a - f.StopPrice) >= 0)
                    {
                        l.Cycle.MaeValue = Math.Min(l.Cycle.MaeValue, RevValue(l, f.StopPrice));
                        if (!ReverseStep(l, c, m.Time, f.StopPrice, false, r)) return false;
                        a = l.Cycle.Fills[l.Cycle.Fills.Count - 1].Price; continue;
                    }
                    l.Cycle.MaeValue = Math.Min(l.Cycle.MaeValue, RevValue(l, b)); return true;
                }
                if (d * (b - f.TargetPrice) >= 0 && d * (a - f.TargetPrice) <= 0)
                {
                    l.Cycle.MfeValue = Math.Max(l.Cycle.MfeValue, RevValue(l, f.TargetPrice));
                    CloseReverse(l, c, m.Time, f.TargetPrice, "TARGET", false, r); return false;
                }
                l.Cycle.MfeValue = Math.Max(l.Cycle.MfeValue, RevValue(l, b)); return true;
            }
            return l.Active;
        }

        static void Close(Leg l, KeystoneRecoilConfig c, DateTime t, double price, string reason, bool market, KeystoneRecoilResult r)
        {
            var cy = l.Cycle;
            cy.ExitTime = t; cy.ExitPrice = price; cy.Reason = reason; cy.AvgAtExit = l.Avg;
            cy.Gross = Value(l, price);
            cy.Commission = c.CommissionPerSide * 2 * l.Q;
            cy.Slippage = market ? c.SlippageTicks * l.Tick * l.Pv * l.Q : 0;
            cy.Net = cy.Gross - cy.Commission - cy.Slippage;
            r.Cycles.Add(cy);
            l.Active = false; l.Cycle = null; l.S = 0; l.Q = 0; l.CyclesToday++;
            if (reason == "TARGET" && l.CyclesToday < Math.Max(1, c.CyclesPerDay)) { l.Waiting = true; l.Anchor = price; l.AnchorTime = t; }
            else l.DayDone = true;
        }

        public static KeystoneRecoilResult Run(List<KeystoneHelixMinute> minutes, KeystoneRecoilConfig cfg)
        {
            var r = new KeystoneRecoilResult { Config = cfg };
            if (minutes == null || minutes.Count == 0 || (cfg.UseMnq != 1 && cfg.UseMgc != 1)) { r.Notes.Add("No minutes or no instrument selected."); return r; }
            bool both = cfg.UseMnq == 1 && cfg.UseMgc == 1, shared = both && cfg.DrawdownMode != "SPLIT" && cfg.Mode != "REVERSE";
            int firstStart = Math.Min(cfg.UseMnq == 1 ? cfg.MnqStartHhmm : 2359, cfg.UseMgc == 1 ? cfg.MgcStartHhmm : 2359);
            int id = 0;
            r.NoTriggerDays["MNQ"] = 0; r.NoTriggerDays["MGC"] = 0;
            int k0 = 0;
            while (k0 < minutes.Count)
            {
                DateTime day = minutes[k0].Time.Date;
                int k1 = k0; while (k1 < minutes.Count && minutes[k1].Time.Date == day) k1++;
                int dow = day.DayOfWeek == DayOfWeek.Sunday ? 7 : (int)day.DayOfWeek;
                bool tradeDay = day >= cfg.Start.Date && day <= cfg.End.Date && (cfg.Weekdays ?? "12345").IndexOf((char)('0' + dow)) >= 0;
                if (tradeDay) RunDay(minutes, k0, k1, day, cfg, shared, firstStart, r, ref id);
                k0 = k1;
            }
            return r;
        }

        static void RunDay(List<KeystoneHelixMinute> minutes, int lo, int hi, DateTime day, KeystoneRecoilConfig cfg, bool shared, int firstStart, KeystoneRecoilResult r, ref int id)
        {
            DateTime close = Clock(day, cfg.CloseHhmm), lastEntry = Clock(day, cfg.LastEntryHhmm);
            var legs = new List<Leg>();
            if (cfg.UseMnq == 1) legs.Add(new Leg { Symbol = "MNQ", Mgc = false, Pv = cfg.MnqPointValue, Tick = MnqTick, Trigger = cfg.MnqTrigger, Step = cfg.MnqStep, OwnDd = shared ? cfg.MaxDrawdown : (cfg.UseMgc == 1 ? cfg.MnqMaxDrawdown : cfg.MaxDrawdown), TargetPts = cfg.MnqTargetPoints, StartHhmm = cfg.MnqStartHhmm });
            if (cfg.UseMgc == 1) legs.Add(new Leg { Symbol = "MGC", Mgc = true, Pv = cfg.MgcPointValue, Tick = MgcTick, Trigger = cfg.MgcTrigger, Step = cfg.MgcStep, OwnDd = shared ? cfg.MaxDrawdown : (cfg.UseMnq == 1 ? cfg.MgcMaxDrawdown : cfg.MaxDrawdown), TargetPts = cfg.MgcTargetPoints, StartHhmm = cfg.MgcStartHhmm });
            // A day counts only when every used instrument has real minutes after its start.
            bool any = false; var noData = new HashSet<string>();
            foreach (var l in legs)
            {
                DateTime st = Clock(day, l.StartHhmm);
                int a = -1; for (int k = lo; k < hi; k++) if (minutes[k].Time > st && minutes[k].Time <= close && Real(minutes[k], l)) { a = k; break; }
                if (a < 0) { l.DayDone = true; noData.Add(l.Symbol); continue; }
                any = true;
                // Start price: the open of the first minute after the start time.
                l.Anchor = O(minutes[a], l); l.AnchorTime = minutes[a].Time.AddMinutes(-1); l.Waiting = true;
            }
            if (!any) return;
            if (legs.Any(l => l.DayDone)) { r.SkippedDays.Add(day.ToString("yyyy-MM-dd ddd", CultureInfo.InvariantCulture) + " • " + string.Join(", ", legs.Where(l => l.DayDone).Select(l => l.Symbol)) + " has no data after the start"); if (legs.All(l => l.DayDone)) return; }
            r.Days.Add(day);
            double dayRealized = 0;
            var triggered = new HashSet<string>();
            int lastIdx = lo; for (int k = lo; k < hi; k++) if (minutes[k].Time <= close) lastIdx = k;
            for (int k = lo; k < hi; k++)
            {
                var m = minutes[k];
                if (m.Time > close) break;
                bool isLast = k == lastIdx;
                // 1. waiting legs: the trigger
                foreach (var l in legs)
                {
                    if (!l.Waiting || l.DayDone || !Real(m, l)) continue;
                    if (m.Time <= Clock(day, l.StartHhmm) || m.Time <= l.AnchorTime) continue;
                    if (m.Time.AddMinutes(-1) >= lastEntry) { l.Waiting = false; l.DayDone = true; continue; }
                    double up = l.Anchor + l.Trigger, dn = l.Anchor - l.Trigger, o = O(m, l);
                    int dir = 0; double price = double.NaN, level = double.NaN; bool gap = false, amb = false;
                    if (o >= up) { dir = -1; price = o; level = up; gap = true; }
                    else if (o <= dn) { dir = 1; price = o; level = dn; gap = true; }
                    else
                    {
                        bool hu = H(m, l) >= up, hd = L(m, l) <= dn;
                        if (hu && hd) { amb = true; if (Math.Abs(o - up) <= Math.Abs(o - dn)) hd = false; else hu = false; }
                        if (hu) { dir = -1; price = up; level = up; } else if (hd) { dir = 1; price = dn; level = dn; }
                    }
                    if (dir == 0) continue;
                    l.Waiting = false; l.Active = true; triggered.Add(l.Symbol);
                    l.Cycle = new KeystoneRecoilCycle { Id = ++id, Day = day, Symbol = l.Symbol, Dir = dir, Mode = cfg.Mode == "REVERSE" ? "REVERSE" : "ADD", AnchorTime = l.AnchorTime, AnchorPrice = l.Anchor, TriggerLevel = level, PointValue = l.Pv, Step = l.Step, CycleInDay = l.CyclesToday + 1, Ambiguous = amb };
                    l.S = 0; l.Q = 0; l.Realized = 0; l.RevComm = 0; l.RevSlip = 0;
                    if (cfg.Mode == "REVERSE") { AddReverseFill(l, cfg, m.Time, price, dir, gap); ReverseMinute(l, cfg, m, true, r); continue; }
                    AddFill(l, cfg, m.Time, price, level, gap);
                    // Rest of the entry minute: the move that triggered us continues to the bar's extreme
                    // (adds on the way); a target only if the minute closes beyond it.
                    double adv = dir > 0 ? L(m, l) : H(m, l);
                    if (!shared)
                    {
                        int before; double sp = StopPrice(l, cfg, l.OwnDd, out before);
                        if (dir * (adv - sp) <= 0) { for (int q = 0; q < before; q++) AddFill(l, cfg, m.Time, LevelOf(l, l.NextAdd), LevelOf(l, l.NextAdd), false); Track(l, sp, price); Close(l, cfg, m.Time, sp - dir * cfg.SlippageTicks * 0, "BLOWUP", true, r); continue; }
                    }
                    FillAddsTo(l, cfg, m.Time, adv, false);
                    Track(l, adv, C(m, l));
                    double tp = TargetPrice(l, cfg);
                    if (dir * (C(m, l) - tp) >= 0) { Close(l, cfg, m.Time, tp, "TARGET", false, r); dayRealized += r.Cycles[r.Cycles.Count - 1].Net; }
                }
                // 2. open ladders (the per-minute steps skip the minute a ladder started: it was handled above)
                if (cfg.Mode == "REVERSE")
                {
                    foreach (var l in legs.Where(x => x.Active && x.Cycle != null && x.Cycle.Fills[0].Time < m.Time && Real(m, x)).ToList()) ReverseMinute(l, cfg, m, false, r);
                    if (isLast) foreach (var l in legs.Where(x => x.Active && x.Cycle != null).ToList()) CloseReverse(l, cfg, m.Time, Real(m, l) ? C(m, l) : LastPrice(minutes, k, l), "SESSION END", true, r);
                    continue;
                }
                var open = legs.Where(l => l.Active && l.Cycle != null && l.Cycle.Fills.Count > 0 && l.Cycle.Fills[0].Time < m.Time && Real(m, l)).ToList();
                if (legs.Any(l => l.Active && l.Cycle != null))
                {
                    // gaps at the open: adds fill at the open
                    foreach (var l in open) FillAddsTo(l, cfg, m.Time, O(m, l), true);
                    if (shared)
                    {
                        var all = legs.Where(l => l.Active && l.Cycle != null).ToList();
                        Func<Leg, double> openRef = l => open.Contains(l) ? O(m, l) : (l.Cycle.Fills[0].Time == m.Time ? l.Cycle.Fills[0].Price : LastPrice(minutes, k, l));
                        double openSum = all.Sum(l => Value(l, openRef(l))) + dayRealized;
                        if (openSum <= -cfg.MaxDrawdown)
                        {
                            foreach (var l in all.ToList()) { double px = openRef(l); Track(l, px, px); Close(l, cfg, m.Time, px, "BLOWUP", true, r); }
                            continue;
                        }
                        // worst case inside the minute: every leg at its adverse extreme, adds filled on the way
                        var worst = new Dictionary<Leg, double>();
                        foreach (var l in all)
                        {
                            if (!Real(m, l)) { worst[l] = Value(l, LastPrice(minutes, k, l)); continue; }
                            double adv = l.Cycle.Dir > 0 ? L(m, l) : H(m, l);
                            double S = l.S, Q = l.Q; int n = l.NextAdd;
                            while (n < cfg.MaxEntries) { double lv = LevelOf(l, n); if (l.Cycle.Dir * (adv - lv) > 0) break; int q = AddQty(cfg, n); S += lv * q; Q += q; n++; }
                            worst[l] = l.Cycle.Dir * (Q * adv - S) * l.Pv;
                        }
                        double worstSum = worst.Values.Sum() + dayRealized;
                        if (worstSum <= -cfg.MaxDrawdown)
                        {
                            // Both closed when the two together reach −MAX DRAWDOWN; each leg's share of the loss follows its worst case.
                            // A leg still positive at its worst keeps that value; the rest of the loss is split by the losing legs' worst case.
                            double lossToShare = -cfg.MaxDrawdown - dayRealized, negSum = worst.Values.Where(v => v < 0).Sum(), posSum = worst.Values.Where(v => v >= 0).Sum();
                            foreach (var l in all.ToList())
                            {
                                if (Real(m, l)) FillAddsTo(l, cfg, m.Time, l.Cycle.Dir > 0 ? L(m, l) : H(m, l), false);
                                double share = worst[l] >= 0 ? worst[l] : (negSum < 0 ? (lossToShare - posSum) * worst[l] / negSum : 0);
                                double px = (l.S + l.Cycle.Dir * share / l.Pv) / l.Q;
                                Track(l, px, px); Close(l, cfg, m.Time, px, "BLOWUP", true, r);
                            }
                            continue;
                        }
                    }
                    foreach (var l in open)
                    {
                        if (!l.Active) continue;
                        int dir = l.Cycle.Dir; double o = O(m, l), adv = dir > 0 ? L(m, l) : H(m, l), fav = dir > 0 ? H(m, l) : L(m, l), cl = C(m, l);
                        if (!shared)
                        {
                            if (Value(l, o) <= -l.OwnDd) { Track(l, o, o); Close(l, cfg, m.Time, o, "BLOWUP", true, r); continue; }
                        }
                        double tpOpen = TargetPrice(l, cfg);
                        if (dir * (o - tpOpen) >= 0) { Track(l, o, o); Close(l, cfg, m.Time, o, "TARGET", false, r); dayRealized += r.Cycles[r.Cycles.Count - 1].Net; continue; }
                        if (!shared)
                        {
                            int before; double sp = StopPrice(l, cfg, l.OwnDd, out before);
                            if (dir * (adv - sp) <= 0)
                            {
                                for (int q = 0; q < before; q++) { double lv = LevelOf(l, l.NextAdd); AddFill(l, cfg, m.Time, lv, lv, false); }
                                Track(l, sp, fav); Close(l, cfg, m.Time, sp, "BLOWUP", true, r); continue;
                            }
                        }
                        // high-first (target before any add) …
                        double tpBefore = TargetPrice(l, cfg);
                        if (dir * (fav - tpBefore) >= 0) { Track(l, o, tpBefore); Close(l, cfg, m.Time, tpBefore, "TARGET", false, r); dayRealized += r.Cycles[r.Cycles.Count - 1].Net; continue; }
                        // … else the adds on the way down, and a target after them only if the minute closes beyond it
                        int had = l.NextAdd;
                        FillAddsTo(l, cfg, m.Time, adv, false);
                        Track(l, adv, fav);
                        if (l.NextAdd > had)
                        {
                            double tpAfter = TargetPrice(l, cfg);
                            if (dir * (cl - tpAfter) >= 0) { Close(l, cfg, m.Time, tpAfter, "TARGET", false, r); dayRealized += r.Cycles[r.Cycles.Count - 1].Net; continue; }
                        }
                    }
                }
                // 3. the close
                if (isLast)
                    foreach (var l in legs.Where(x => x.Active && x.Cycle != null).ToList())
                    {
                        double px = Real(m, l) ? C(m, l) : LastPrice(minutes, k, l);
                        Close(l, cfg, m.Time, px - l.Cycle.Dir * 0, "SESSION END", true, r);
                    }
            }
            foreach (var l in legs) if (!triggered.Contains(l.Symbol) && !noData.Contains(l.Symbol)) r.NoTriggerDays[l.Symbol] = r.NoTriggerDays[l.Symbol] + 1;
            // Bounce study: from the entry to the close, the worst price, the best price after it and what the
            // full ladder (every add the worst price reached, no stop) would have been worth there.
            foreach (var cy in r.Cycles.Where(c => c.Day == day && c.Mode != "REVERSE"))
            {
                bool mg = cy.Symbol == "MGC"; double worst = double.NaN, best = double.NaN; DateTime wt = DateTime.MinValue, bt = DateTime.MinValue;
                for (int k = lo; k < hi; k++)
                {
                    var m = minutes[k]; if (m.Time > close) break; if (m.Time < cy.EntryTime || !(mg ? m.HasMgc : m.HasMnq)) continue;
                    double adv = cy.Dir > 0 ? (mg ? m.MgcL : m.MnqL) : (mg ? m.MgcH : m.MnqH);
                    if (double.IsNaN(worst) || cy.Dir * (adv - worst) < 0) { worst = adv; wt = m.Time; best = double.NaN; bt = DateTime.MinValue; }
                    double fav = cy.Dir > 0 ? (mg ? m.MgcH : m.MnqH) : (mg ? m.MgcL : m.MnqL);
                    if (m.Time > wt && (double.IsNaN(best) || cy.Dir * (fav - best) > 0)) { best = fav; bt = m.Time; }
                }
                cy.LowestPrice = worst; cy.LowestTime = wt; cy.BestAfterLowest = best; cy.BestAfterLowestTime = bt;
                if (!double.IsNaN(worst) && cy.Fills.Count > 0)
                {
                    double S = 0, Q = 0; int n = 0;
                    for (; n < cfg.MaxEntries; n++)
                    {
                        double lv = n == 0 ? cy.Fills[0].Price : cy.Fills[0].Price - cy.Dir * n * cy.Step;
                        if (n > 0 && cy.Dir * (worst - lv) > 0) break;
                        int q = AddQty(cfg, n); S += (n < cy.Fills.Count ? cy.Fills[n].Price : lv) * q; Q += q;
                    }
                    cy.FullLadderEntries = n;
                    cy.FullLadderAtLowest = cy.Dir * (Q * worst - S) * cy.PointValue;
                    cy.FullLadderAtBest = double.IsNaN(best) ? cy.FullLadderAtLowest : cy.Dir * (Q * best - S) * cy.PointValue;
                }
            }
        }

        static double LastPrice(List<KeystoneHelixMinute> minutes, int k, Leg l)
        {
            for (int q = k; q >= 0; q--) if (Real(minutes[q], l)) return C(minutes[q], l);
            return l.Avg;
        }
    }

    // ---- RECOIL study: setups only, steps reached, bounces, risk grid, one live account -----------------
    public sealed class KeystoneRecoilStats
    {
        public string Label = string.Empty;
        public int Cycles, Wins, Blowups, SessionEnds, Days, NoTrigger;
        public double Net, WinNet, LossNet, Commission;
        public double WinRate { get { return Wins + Blowups + SessionEnds == 0 ? 0 : 100.0 * Wins / (Wins + Blowups + SessionEnds); } }
        public double AvgWin { get { return Wins == 0 ? 0 : WinNet / Wins; } }
        public double AvgLoss { get { int n = Cycles - Wins; return n == 0 ? 0 : LossNet / n; } }
        public double BreakEven { get { double w = AvgWin, l = Math.Abs(AvgLoss); return w + l <= 0 ? 0 : 100.0 * l / (w + l); } }
        public double PerCycle { get { return Cycles == 0 ? 0 : Net / Cycles; } }
    }
    public sealed class KeystoneRecoilStepRow { public int Entries; public int Cycles, Wins, Blowups, SessionEnds; public double Net, AvgBounce, AvgFullAtBest, AvgWorst; }
    public sealed class KeystoneRecoilGroup { public string Group = string.Empty; public int Order; public KeystoneRecoilStats Stats; }
    public sealed class KeystoneRecoilBreakdown { public string Title = string.Empty, Note = string.Empty; public List<KeystoneRecoilGroup> Rows = new List<KeystoneRecoilGroup>(); }
    public sealed class KeystoneRecoilGridCell { public double Distance, Target; public int Cycles, Wins, Blowups; public double Net, WorstDay; public double WinRate { get { return Cycles == 0 ? 0 : 100.0 * Wins / Cycles; } } }
    public sealed class KeystoneRecoilGrid { public string Symbol = string.Empty, Year = "ALL"; public double[] Distances = new double[0], Targets = new double[0]; public KeystoneRecoilGridCell[,] Cells; public KeystoneRecoilGridCell Best, Yours; }
    public sealed class KeystoneRecoilAccount
    {
        public double Start, End, Peak, MaxDrawdown, Low; public int Trades, Wins, Blowups; public bool Ruined; public DateTime RuinDate = DateTime.MinValue;
        public List<Tuple<DateTime, double>> Equity = new List<Tuple<DateTime, double>>();
        public List<Tuple<DateTime, double, int, int>> Months = new List<Tuple<DateTime, double, int, int>>();
    }

    public static class KeystoneRecoilStudy
    {
        public static string Cash(double v) { return (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture); }
        public static string Pc(double v) { return v.ToString("0", CultureInfo.InvariantCulture) + "%"; }

        public static KeystoneRecoilStats Stats(string label, IEnumerable<KeystoneRecoilCycle> cycles, int days = 0, int noTrigger = 0)
        {
            var s = new KeystoneRecoilStats { Label = label, Days = days, NoTrigger = noTrigger };
            foreach (var c in cycles)
            {
                s.Cycles++; s.Net += c.Net; s.Commission += c.Commission + c.Slippage;
                if (c.Win) { s.Wins++; s.WinNet += c.Net; } else { s.LossNet += c.Net; if (c.Blown) s.Blowups++; else s.SessionEnds++; }
            }
            return s;
        }

        public static List<KeystoneRecoilStepRow> Steps(List<KeystoneRecoilCycle> cycles, int maxEntries)
        {
            var rows = new List<KeystoneRecoilStepRow>();
            for (int n = 1; n <= Math.Max(1, maxEntries); n++)
            {
                var g = cycles.Where(c => c.Entries == n).ToList();
                rows.Add(new KeystoneRecoilStepRow
                {
                    Entries = n, Cycles = g.Count, Wins = g.Count(c => c.Win), Blowups = g.Count(c => c.Blown), SessionEnds = g.Count(c => c.Reason == "SESSION END"), Net = g.Sum(c => c.Net),
                    AvgBounce = g.Where(c => !double.IsNaN(c.BestAfterLowest)).Select(c => c.Dir * (c.BestAfterLowest - c.LowestPrice)).DefaultIfEmpty(0).Average(),
                    AvgFullAtBest = g.Select(c => c.FullLadderAtBest).DefaultIfEmpty(0).Average(),
                    AvgWorst = g.Select(c => c.MaeValue).DefaultIfEmpty(0).Average()
                });
            }
            return rows;
        }

        public static List<KeystoneRecoilBreakdown> Breakdowns(List<KeystoneRecoilCycle> cycles)
        {
            var output = new List<KeystoneRecoilBreakdown>();
            Action<string, string, Func<KeystoneRecoilCycle, Tuple<int, string>>> add = (title, note, key) =>
            {
                var b = new KeystoneRecoilBreakdown { Title = title, Note = note };
                foreach (var g in cycles.GroupBy(key).OrderBy(g => g.Key.Item1).ThenBy(g => g.Key.Item2)) b.Rows.Add(new KeystoneRecoilGroup { Group = g.Key.Item2, Order = g.Key.Item1, Stats = Stats(g.Key.Item2, g) });
                output.Add(b);
            };
            add("INSTRUMENT", "each instrument's own ladders", c => Tuple.Create(c.Symbol == "MNQ" ? 0 : 1, c.Symbol));
            add("SIDE", "BUY = the market fell first • SELL = it rose first", c => Tuple.Create(c.Dir > 0 ? 0 : 1, c.Dir > 0 ? "BUY (after a drop)" : "SELL (after a rise)"));
            add("ENTRIES USED", "how deep the ladder went", c => Tuple.Create(c.Entries, c.Entries + (c.Entries == 1 ? " entry" : " entries") + " (" + c.MaxQty + " contracts)"));
            add("TRIGGER HOUR (ET)", "when the first entry filled", c => Tuple.Create(c.EntryTime.Hour, c.EntryTime.ToString("HH") + ":00"));
            add("WEEKDAY", "trading day", c => Tuple.Create(((int)c.Day.DayOfWeek + 6) % 7, c.Day.DayOfWeek.ToString().ToUpperInvariant()));
            add("CYCLE OF THE DAY", "1 = the first ladder of the day", c => Tuple.Create(c.CycleInDay, "CYCLE " + c.CycleInDay));
            add("YEAR", "volatility changes year to year", c => Tuple.Create(c.Day.Year, c.Day.Year.ToString(CultureInfo.InvariantCulture)));
            add("MONTH", "month", c => Tuple.Create(c.Day.Year * 100 + c.Day.Month, c.Day.ToString("yyyy-MM", CultureInfo.InvariantCulture)));
            return output;
        }

        public static double[] Distances(string symbol, double yours)
        {
            var d = symbol == "MGC" ? new double[] { 10, 15, 20, 25, 30, 40 } : new double[] { 50, 75, 100, 125, 150, 200 };
            return d.Contains(yours) || yours <= 0 ? d : d.Concat(new[] { yours }).OrderBy(x => x).ToArray();
        }
        public static double[] Targets(double yours)
        {
            var t = new double[] { 100, 200, 300, 400, 600, 800, 1000 };
            return t.Contains(yours) || yours <= 0 ? t : t.Concat(new[] { yours }).OrderBy(x => x).ToArray();
        }

        // Re-run the ladder for every trigger/add distance × $ target on one instrument (all years, then each year).
        public static List<KeystoneRecoilGrid> Grids(List<KeystoneHelixMinute> minutes, KeystoneRecoilConfig cfg, string symbol)
        {
            bool mgc = symbol == "MGC";
            double yourD = mgc ? cfg.MgcStep : cfg.MnqStep, yourT = cfg.TargetDollars;
            double[] ds = Distances(symbol, yourD), ts = Targets(yourT);
            var runs = new KeystoneRecoilResult[ds.Length, ts.Length];
            var years = new SortedSet<int>();
            for (int a = 0; a < ds.Length; a++)
                for (int b = 0; b < ts.Length; b++)
                {
                    var c = cfg.Copy(); c.UseMnq = mgc ? 0 : 1; c.UseMgc = mgc ? 1 : 0; c.TargetMode = "DOLLARS"; c.TargetDollars = ts[b];
                    if (mgc) { c.MgcTrigger = ds[a] * (cfg.MgcStep <= 0 ? 1 : cfg.MgcTrigger / cfg.MgcStep); c.MgcStep = ds[a]; } else { c.MnqTrigger = ds[a] * (cfg.MnqStep <= 0 ? 1 : cfg.MnqTrigger / cfg.MnqStep); c.MnqStep = ds[a]; }
                    if (c.DrawdownMode == "SPLIT") c.MaxDrawdown = mgc ? cfg.MgcMaxDrawdown : cfg.MnqMaxDrawdown;
                    runs[a, b] = KeystoneRecoil.Run(minutes, c);
                    foreach (var cy in runs[a, b].Cycles) years.Add(cy.Day.Year);
                }
            var output = new List<KeystoneRecoilGrid>();
            foreach (string year in new[] { "ALL" }.Concat(years.Select(y => y.ToString(CultureInfo.InvariantCulture))))
            {
                var g = new KeystoneRecoilGrid { Symbol = symbol, Year = year, Distances = ds, Targets = ts, Cells = new KeystoneRecoilGridCell[ds.Length, ts.Length] };
                for (int a = 0; a < ds.Length; a++)
                    for (int b = 0; b < ts.Length; b++)
                    {
                        var list = runs[a, b].Cycles.Where(x => year == "ALL" || x.Day.Year.ToString(CultureInfo.InvariantCulture) == year).ToList();
                        var cell = new KeystoneRecoilGridCell { Distance = ds[a], Target = ts[b], Cycles = list.Count, Wins = list.Count(x => x.Win), Blowups = list.Count(x => x.Blown), Net = list.Sum(x => x.Net), WorstDay = list.GroupBy(x => x.Day).Select(d => d.Sum(x => x.Net)).DefaultIfEmpty(0).Min() };
                        g.Cells[a, b] = cell;
                        if (g.Best == null || cell.Net > g.Best.Net) g.Best = cell;
                        if (Math.Abs(ds[a] - yourD) < 1e-9 && Math.Abs(ts[b] - yourT) < 1e-9) g.Yours = cell;
                    }
                output.Add(g);
            }
            return output;
        }

        // One live account: every ladder's net added when it closes; the account is lost at zero.
        public static KeystoneRecoilAccount Account(List<KeystoneRecoilCycle> cycles, double start)
        {
            var a = new KeystoneRecoilAccount { Start = start, Low = start };
            double bal = start, peak = start;
            foreach (var c in cycles.OrderBy(x => x.ExitTime))
            {
                if (a.Ruined) break;
                bal += c.Net; a.Trades++; if (c.Win) a.Wins++; if (c.Blown) a.Blowups++;
                peak = Math.Max(peak, bal); a.MaxDrawdown = Math.Max(a.MaxDrawdown, peak - bal); a.Low = Math.Min(a.Low, bal);
                a.Equity.Add(Tuple.Create(c.ExitTime, bal));
                if (bal <= 0) { a.Ruined = true; a.RuinDate = c.ExitTime; }
            }
            a.End = bal; a.Peak = peak;
            foreach (var m in cycles.Where(c => a.Equity.Count > 0 && c.ExitTime <= a.Equity[a.Equity.Count - 1].Item1).GroupBy(c => new DateTime(c.Day.Year, c.Day.Month, 1)).OrderBy(g => g.Key))
                a.Months.Add(Tuple.Create(m.Key, m.Sum(x => x.Net), m.Count(x => x.Win), m.Count(x => x.Blown)));
            return a;
        }

        public static string Verdict(KeystoneRecoilResult r, KeystoneRecoilStats s)
        {
            if (r.Cycles.Count == 0) return "NO LADDERS • the trigger move never came in the loaded data (or the window has no bars). Check the dates, start time and trigger distance.";
            string edge = s.WinRate > s.BreakEven + 1 ? "wins MORE often than it needs to" : s.WinRate < s.BreakEven - 1 ? "wins LESS often than it needs to" : "wins about as often as it needs to";
            return s.Cycles + " ladders on " + s.Days + " days (" + (r.NoTriggerDays.Values.Sum()) + " instrument-days without the trigger move) • won " + Pc(s.WinRate) + " (" + s.Wins + "), blown " + s.Blowups + ", closed at the end " + s.SessionEnds
                + " • average win " + Cash(s.AvgWin) + " vs average loss " + Cash(s.AvgLoss) + " → break-even " + Pc(s.BreakEven) + ": it " + edge + " • net " + Cash(s.Net) + " (" + Cash(s.PerCycle) + " a ladder).";
        }

        static string H(string s) { return System.Net.WebUtility.HtmlEncode(s ?? string.Empty); }
        static string Cl(double v) { return v > 0 ? "g" : v < 0 ? "r" : "m"; }
        static string Sg(double v) { return (v > 0 ? "+" : "") + Cash(v); }

        // The full RECOIL report: verdict, MNQ/MGC/BOTH, steps, blowups and bounces, the grid per year, one live account, breakdowns, every ladder.
        public static string Html(KeystoneRecoilResult r, List<KeystoneRecoilGrid> grids, List<Tuple<string, KeystoneRecoilStats, KeystoneRecoilAccount>> compare, double startBalance)
        {
            var c = r.Config; var s = Stats("ALL", r.Cycles, r.Days.Count, r.NoTriggerDays.Values.Sum()); var a = Account(r.Cycles, startBalance);
            var sb = new StringBuilder();
            sb.Append("<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>RECOIL report</title><style>")
              .Append("body{background:#0d1017;color:#e8e3d3;font-family:Segoe UI,Arial,sans-serif;margin:0;padding:18px}h1{color:#f2c14e;margin:0 0 4px}h2{color:#f2c14e;margin:26px 0 6px;font-size:17px}h3{color:#5bc8f5}")
              .Append(".sub{color:#9aa4b5;font-size:13px}.cards{display:flex;flex-wrap:wrap;gap:10px;margin:12px 0}.card{background:#161b26;border:1.5px solid #2d3546;border-radius:8px;padding:10px 14px;min-width:200px}.card b{display:block;font-size:12px;color:#9aa4b5}.card span{font-size:21px;font-weight:700}")
              .Append("table{border-collapse:collapse;margin:6px 0 4px;font-size:12.5px}th{background:#1d2433;color:#f2c14e;padding:5px 8px;text-align:right}th:first-child,td:first-child{text-align:left}td{padding:4px 8px;border-bottom:1px solid #222a39;text-align:right}")
              .Append(".g{color:#38d682}.r{color:#ff5260}.m{color:#9aa4b5}.c{color:#5bc8f5}.note{color:#9aa4b5;font-size:12px}.hl{outline:2px solid #f2c14e}.best{outline:2px solid #38d682}.wrap{overflow-x:auto}.verdict{background:#161b26;border-left:5px solid #f2c14e;padding:10px 14px;border-radius:6px}</style></head><body>");
            sb.Append("<h1>RECOIL • ADD TO LOSERS</h1><div class='sub'>Historical research only • generated ").Append(DateTime.Now.ToString("yyyy-MM-dd HH:mm")).Append("<br>").Append(H(c.Describe())).Append("</div>");
            sb.Append("<div class='cards'>");
            Action<string, string, string> card = (t, v, cls) => sb.Append("<div class='card'><b>").Append(H(t)).Append("</b><span class='").Append(cls).Append("'>").Append(H(v)).Append("</span></div>");
            card("LADDERS", s.Cycles + " on " + s.Days + " days", "c"); card("WON • NEEDED", Pc(s.WinRate) + " • " + Pc(s.BreakEven), s.WinRate >= s.BreakEven ? "g" : "r"); card("BLOWN", s.Blowups.ToString(), "r"); card("NET AFTER COSTS", Sg(s.Net), Cl(s.Net)); card("ONE LIVE ACCOUNT", Cash(a.Start) + " → " + Cash(a.End), Cl(a.End - a.Start));
            sb.Append("</div><p class='verdict'>").Append(H(Verdict(r, s))).Append("</p>");
            if (compare != null && compare.Count > 0)
            {
                sb.Append("<h2>MNQ ONLY vs MGC ONLY vs BOTH</h2><div class='wrap'><table><tr><th></th>"); foreach (var x in compare) sb.Append("<th>").Append(H(x.Item1)).Append("</th>"); sb.Append("</tr>");
                Action<string, Func<KeystoneRecoilStats, KeystoneRecoilAccount, string>> row = (n, f) => { sb.Append("<tr><td>").Append(H(n)).Append("</td>"); foreach (var x in compare) sb.Append("<td>").Append(H(f(x.Item2, x.Item3))).Append("</td>"); sb.Append("</tr>"); };
                row("LADDERS", (x, y) => x.Cycles.ToString()); row("WON / BLOWN / AT CLOSE", (x, y) => x.Wins + " / " + x.Blowups + " / " + x.SessionEnds); row("WIN RATE • NEEDED", (x, y) => Pc(x.WinRate) + " • " + Pc(x.BreakEven));
                row("NET AFTER COSTS", (x, y) => Sg(x.Net)); row("AVG WIN • AVG LOSS", (x, y) => Sg(x.AvgWin) + " • " + Sg(x.AvgLoss)); row("ONE LIVE ACCOUNT", (x, y) => Cash(y.Start) + " → " + Cash(y.End)); row("MAX DRAWDOWN", (x, y) => Cash(-y.MaxDrawdown) + (y.Ruined ? " • LOST" : ""));
                sb.Append("</table></div>");
            }
            sb.Append("<h2>HOW DEEP THE LADDERS WENT</h2><div class='note'>BOUNCE = points from the worst price to the best price after it (until the close). FULL LADDER AT BEST = the position with every add the worst price reached, no stop, valued at that best price.</div><div class='wrap'><table><tr><th>ENTRIES</th><th>LADDERS</th><th>WON</th><th>BLOWN</th><th>AT CLOSE</th><th>NET</th><th>AVG BOUNCE PTS</th><th>FULL LADDER AT BEST</th></tr>");
            foreach (var x in Steps(r.Cycles, c.MaxEntries)) sb.Append("<tr><td>").Append(x.Entries).Append("</td><td>").Append(x.Cycles).Append("</td><td class='g'>").Append(x.Wins).Append("</td><td class='r'>").Append(x.Blowups).Append("</td><td>").Append(x.SessionEnds).Append("</td><td class='").Append(Cl(x.Net)).Append("'>").Append(Sg(x.Net)).Append("</td><td>").Append(x.AvgBounce.ToString("0.#", CultureInfo.InvariantCulture)).Append("</td><td class='").Append(Cl(x.AvgFullAtBest)).Append("'>").Append(Sg(x.AvgFullAtBest)).Append("</td></tr>");
            sb.Append("</table></div>");
            var blown = r.Cycles.Where(x => x.Blown).ToList();
            sb.Append("<h2>EVERY BLOWUP AND WHAT CAME AFTER</h2>");
            if (blown.Count == 0) sb.Append("<p class='note'>No ladder was blown.</p>");
            else
            {
                sb.Append("<div class='wrap'><table><tr><th>DAY</th><th>INST</th><th>SIDE</th><th>BLOWN AT</th><th>WORST</th><th>BEST AFTER</th><th>FULL LADDER WORST</th><th>FULL LADDER BEST</th></tr>");
                foreach (var x in blown) sb.Append("<tr><td>").Append(x.Day.ToString("yyyy-MM-dd ddd")).Append("</td><td>").Append(x.Symbol).Append("</td><td>").Append(x.Side).Append("</td><td class='r'>").Append(x.ExitTime.ToString("HH:mm")).Append(" ").Append(x.ExitPrice.ToString("0.##", CultureInfo.InvariantCulture)).Append("</td><td>").Append(double.IsNaN(x.LowestPrice) ? "—" : x.LowestPrice.ToString("0.##", CultureInfo.InvariantCulture)).Append("</td><td>").Append(double.IsNaN(x.BestAfterLowest) ? "—" : x.BestAfterLowest.ToString("0.##", CultureInfo.InvariantCulture)).Append("</td><td class='r'>").Append(Sg(x.FullLadderAtLowest)).Append("</td><td class='").Append(Cl(x.FullLadderAtBest)).Append("'>").Append(Sg(x.FullLadderAtBest)).Append("</td></tr>");
                sb.Append("</table></div>");
            }
            if (grids != null && grids.Count > 0)
            {
                sb.Append("<h2>RISK GRID • ADD DISTANCE × TARGET</h2><div class='note'>Every add distance (rows) × $ target (columns) re-run on the same minutes. Cell: ladders • win % • blowups, then net after costs. Gold = your setting, green = best.</div>");
                foreach (var g in grids)
                {
                    sb.Append("<h3>").Append(H(g.Symbol + " • " + (g.Year == "ALL" ? "ALL YEARS" : g.Year))).Append(g.Best == null ? "" : H(" • best: add every " + g.Best.Distance.ToString("0.##", CultureInfo.InvariantCulture) + " pts, target " + Cash(g.Best.Target) + " = " + Sg(g.Best.Net))).Append("</h3><div class='wrap'><table><tr><th>ADD EVERY \\ TARGET</th>");
                    foreach (double t in g.Targets) sb.Append("<th>").Append(Cash(t)).Append("</th>"); sb.Append("</tr>");
                    for (int d = 0; d < g.Distances.Length; d++)
                    {
                        sb.Append("<tr><td>").Append(g.Distances[d].ToString("0.##", CultureInfo.InvariantCulture)).Append(" pts</td>");
                        for (int t = 0; t < g.Targets.Length; t++) { var x = g.Cells[d, t]; sb.Append("<td class='").Append(Cl(x.Net)).Append(x == g.Yours ? " hl" : x == g.Best ? " best" : "").Append("'>").Append(x.Cycles == 0 ? "no ladder" : x.Cycles + " • " + Pc(x.WinRate) + " • " + x.Blowups + "✕<br>" + Sg(x.Net)).Append("</td>"); }
                        sb.Append("</tr>");
                    }
                    sb.Append("</table></div>");
                }
            }
            sb.Append("<h2>ONE LIVE ACCOUNT</h2><p>").Append(H("Start " + Cash(a.Start) + " → end " + Cash(a.End) + " • max drawdown " + Cash(-a.MaxDrawdown) + " • lowest balance " + Cash(a.Low) + (a.Ruined ? " • LOST on " + a.RuinDate.ToString("yyyy-MM-dd") : ""))).Append("</p><div class='wrap'><table><tr><th>MONTH</th><th>NET</th><th>WON</th><th>BLOWN</th></tr>");
            foreach (var m in a.Months) sb.Append("<tr><td>").Append(m.Item1.ToString("MMM yyyy", CultureInfo.InvariantCulture)).Append("</td><td class='").Append(Cl(m.Item2)).Append("'>").Append(Sg(m.Item2)).Append("</td><td>").Append(m.Item3).Append("</td><td>").Append(m.Item4).Append("</td></tr>");
            sb.Append("</table></div>");
            foreach (var b in Breakdowns(r.Cycles))
            {
                sb.Append("<h2>").Append(H(b.Title)).Append("</h2><div class='note'>").Append(H(b.Note)).Append("</div><div class='wrap'><table><tr><th>GROUP</th><th>LADDERS</th><th>WON</th><th>BLOWN</th><th>WIN %</th><th>NET</th></tr>");
                foreach (var g in b.Rows) sb.Append("<tr><td>").Append(H(g.Group)).Append("</td><td>").Append(g.Stats.Cycles).Append("</td><td>").Append(g.Stats.Wins).Append("</td><td>").Append(g.Stats.Blowups).Append("</td><td>").Append(Pc(g.Stats.WinRate)).Append("</td><td class='").Append(Cl(g.Stats.Net)).Append("'>").Append(Sg(g.Stats.Net)).Append("</td></tr>");
                sb.Append("</table></div>");
            }
            sb.Append("<h2>EVERY LADDER</h2><div class='wrap'><table><tr><th>DAY</th><th>INST</th><th>SIDE</th><th>START</th><th>FILLS</th><th>AVERAGE</th><th>EXIT</th><th>RESULT</th><th>NET</th><th>WORST OPEN</th></tr>");
            foreach (var x in r.Cycles.OrderBy(x => x.EntryTime))
                sb.Append("<tr><td>").Append(x.Day.ToString("yyyy-MM-dd ddd")).Append("</td><td>").Append(x.Symbol).Append("</td><td>").Append(x.Side).Append("</td><td>").Append(x.AnchorPrice.ToString("0.##", CultureInfo.InvariantCulture)).Append("</td><td>").Append(H(string.Join(" • ", x.Fills.Select(z => z.Time.ToString("HH:mm") + " " + z.Qty + "@" + z.Price.ToString("0.##", CultureInfo.InvariantCulture))))).Append("</td><td>").Append(x.AvgAtExit.ToString("0.##", CultureInfo.InvariantCulture)).Append("</td><td>").Append(x.ExitTime.ToString("HH:mm")).Append(" ").Append(x.ExitPrice.ToString("0.##", CultureInfo.InvariantCulture)).Append("</td><td class='").Append(x.Win ? "g" : x.Blown ? "r" : "c").Append("'>").Append(x.Win ? "TARGET" : x.Reason).Append("</td><td class='").Append(Cl(x.Net)).Append("'>").Append(Sg(x.Net)).Append("</td><td class='r'>").Append(Sg(x.MaeValue)).Append("</td></tr>");
            sb.Append("</table></div></body></html>");
            return sb.ToString();
        }

        public static string Csv(KeystoneRecoilResult r)
        {
            var sb = new StringBuilder();
            sb.AppendLine("id,day,symbol,cycle,side,start_price,trigger_level,entries,max_contracts,fills,avg_at_exit,exit_time,exit_price,reason,gross,costs,net,worst_open_pl,best_open_pl,lowest,lowest_time,best_after_lowest,best_time,full_ladder_at_lowest,full_ladder_at_best");
            Func<double, string> n = v => double.IsNaN(v) ? "" : v.ToString("0.##", CultureInfo.InvariantCulture);
            foreach (var c in r.Cycles)
                sb.AppendLine(string.Join(",", new[] { c.Id.ToString(), c.Day.ToString("yyyy-MM-dd"), c.Symbol, c.CycleInDay.ToString(), c.Side, n(c.AnchorPrice), n(c.TriggerLevel), c.Entries.ToString(), c.MaxQty.ToString(),
                    "\"" + string.Join(" | ", c.Fills.Select(f => f.Time.ToString("HH:mm") + " " + f.Qty + "@" + n(f.Price))) + "\"", n(c.AvgAtExit), c.ExitTime.ToString("yyyy-MM-dd HH:mm"), n(c.ExitPrice), c.Reason, n(c.Gross), n(c.Commission + c.Slippage), n(c.Net),
                    n(c.MaeValue), n(c.MfeValue), n(c.LowestPrice), c.LowestTime == DateTime.MinValue ? "" : c.LowestTime.ToString("HH:mm"), n(c.BestAfterLowest), c.BestAfterLowestTime == DateTime.MinValue ? "" : c.BestAfterLowestTime.ToString("HH:mm"), n(c.FullLadderAtLowest), n(c.FullLadderAtBest) }));
            return sb.ToString();
        }
    }

    // ---- RECOIL prop simulation (Build 30x): evaluation fees, funded accounts, payouts, copy / rotation, groups by session ----
    // The money that counts is your cash: payouts you receive minus every evaluation / activation / account you buy.
    // A ladder's loss only matters through the account it blows (and the fee to replace it).
    public sealed class KeystoneRecoilAccountGroup
    {
        public string Name = "A"; public int Enabled = 1, Accounts = 5;
        public string Mode = "SINGLE";       // SINGLE: one account trades the whole day's ladders, the next account the next day • COPY: every account copies every ladder • ROTATION: each entry / add goes to the next account
        public int StartHhmm = 930, LastEntryHhmm = 1500, CloseHhmm = 1600;
        public KeystoneRecoilAccountGroup Copy() { return (KeystoneRecoilAccountGroup)MemberwiseClone(); }
        public string Label() { return Name + " • " + Accounts + " accounts • " + (Mode == "COPY" ? "COPY TRADING" : Mode == "ROTATION" ? "ROTATION (each add → next account)" : "ONE ACCOUNT A DAY") + " • " + KeystoneRecoilConfig.Hhmm(StartHhmm) + "–" + KeystoneRecoilConfig.Hhmm(CloseHhmm); }
    }

    public sealed class KeystoneRecoilPropConfig
    {
        public string StartMode = "EVAL";    // EVAL (buy an evaluation, pass it, then funded) • DIRECT (buy a funded account)
        public double EvalCost = 100, ActivationCost = 0, DirectCost = 500;
        public double EvalTarget = 3000, EvalMaxLoss = 2000; public string EvalDrawdown = "EOD"; public int EvalMinDays = 1; public double EvalConsistency = 0;
        public double FundedMaxLoss = 2000; public string FundedDrawdown = "EOD"; public double TrailLockAt = 100; public double DailyLossLimit = 0;
        public int PayoutEveryDays = 5; public double PayoutMinProfit = 1000, PayoutPercent = 50, PayoutCap = 2000, PayoutSplit = 90, PayoutMinAmount = 500; public int MaxPayouts = 0;
        public int AutoReplace = 1, MaxPurchases = 0;
        public double RotationTarget = 0;    // ROTATION: $ target of each account's own position (0 = the ladder target)
        public List<KeystoneRecoilAccountGroup> Groups = new List<KeystoneRecoilAccountGroup> { new KeystoneRecoilAccountGroup() };
        public KeystoneRecoilPropConfig Copy() { var c = (KeystoneRecoilPropConfig)MemberwiseClone(); c.Groups = Groups.Select(g => g.Copy()).ToList(); return c; }
        public string Describe()
        {
            Func<double, string> m = v => "$" + v.ToString("N0", CultureInfo.InvariantCulture);
            return (StartMode == "EVAL" ? "evaluation " + m(EvalCost) + (ActivationCost > 0 ? " + activation " + m(ActivationCost) : "") + " • pass +" + m(EvalTarget) + " (max loss " + m(EvalMaxLoss) + " " + EvalDrawdown + (EvalMinDays > 1 ? ", " + EvalMinDays + " days min" : "") + (EvalConsistency > 0 ? ", best day ≤ " + EvalConsistency.ToString("0") + "%" : "") + ")" : "funded account " + m(DirectCost))
                + " • funded max loss " + m(FundedMaxLoss) + " " + FundedDrawdown + (FundedDrawdown != "STATIC" ? " (locks at +" + m(TrailLockAt) + ")" : "") + (DailyLossLimit > 0 ? " • daily loss " + m(DailyLossLimit) : "")
                + " • payout every " + PayoutEveryDays + " trading days when profit ≥ " + m(PayoutMinProfit) + ": " + PayoutPercent.ToString("0") + "% up to " + m(PayoutCap) + " (min " + m(PayoutMinAmount) + "), you keep " + PayoutSplit.ToString("0") + "%" + (MaxPayouts > 0 ? " • max " + MaxPayouts + " payouts" : "")
                + " • " + (AutoReplace == 1 ? "replace lost accounts" + (MaxPurchases > 0 ? " (max " + MaxPurchases + " purchases)" : "") : "no replacement");
        }
    }

    public sealed class KeystoneRecoilLife
    {
        public string Id = string.Empty, Group = string.Empty, Status = "EVAL", EndReason = string.Empty;
        public int Slot, Instance, Payouts, Trades, Wins, Losses, TradingDays;
        public DateTime Bought, PassDate = DateTime.MinValue, FundedDate = DateTime.MinValue, EndDate = DateTime.MinValue;
        public double Cost, PayoutGross, PayoutCash, Balance, TradingNet;
    }
    public sealed class KeystoneRecoilPropTrade { public DateTime Day, Entry, Exit; public string Account = string.Empty, Group = string.Empty, Symbol = string.Empty, Stage = string.Empty, Reason = string.Empty; public int LadderId, FillIndex = -1, Qty; public double Pnl, Worst, BalanceAfter; public bool Liquidated; }
    public sealed class KeystoneRecoilPropMoney { public DateTime Day; public string Account = string.Empty, Kind = string.Empty; public double Amount, Gross; }
    public sealed class KeystoneRecoilPropDay { public DateTime Day; public double Trading, PayoutCash, Expenses; public int Trades, Blowups, Passes, Payouts, Purchases, Active; }

    public sealed class KeystoneRecoilPropResult
    {
        public KeystoneRecoilPropConfig Config;
        public List<KeystoneRecoilLife> Lives = new List<KeystoneRecoilLife>();
        public List<KeystoneRecoilPropTrade> Trades = new List<KeystoneRecoilPropTrade>();
        public List<KeystoneRecoilPropMoney> Payouts = new List<KeystoneRecoilPropMoney>(), Expenses = new List<KeystoneRecoilPropMoney>();
        public List<KeystoneRecoilPropDay> Days = new List<KeystoneRecoilPropDay>();
        public List<string> Notes = new List<string>();
        public double PayoutCash { get { return Payouts.Sum(p => p.Amount); } }
        public double PayoutGross { get { return Payouts.Sum(p => p.Gross); } }
        public double ExpenseTotal { get { return Expenses.Sum(e => e.Amount); } }
        public double NetCash { get { return PayoutCash - ExpenseTotal; } }
        public int Purchases { get { return Lives.Count; } }
        public int Passes { get { return Lives.Count(l => l.PassDate != DateTime.MinValue); } }
        public int EvalFails { get { return Lives.Count(l => l.Status == "FAILED EVAL"); } }
        public int FundedBlowups { get { return Lives.Count(l => l.Status == "BLOWN"); } }
        public int Paid { get { return Lives.Count(l => l.Payouts > 0); } }
        public double PerPurchase { get { return Purchases == 0 ? 0 : NetCash / Purchases; } }
        public double LowestCash() { double run = 0, low = 0; foreach (var d in Days) { run += d.PayoutCash - d.Expenses; low = Math.Min(low, run); } return low; }
    }

    public sealed class KeystoneRecoilSingle { public DateTime Exit = DateTime.MinValue; public double ExitPrice, Pnl, Worst, Best; public string Reason = string.Empty; }

    public static class KeystoneRecoilProp
    {
        sealed class Acct
        {
            public KeystoneRecoilLife Life; public string GroupName; public int Slot;
            public bool Eval, Waiting; public double Balance, HwmEod, HwmIntra, BestDay, DayPnl, ProfitDays; public int DaysTraded, DaysSincePayout; public bool TradedToday;
            public DateTime BusyUntil = DateTime.MinValue;
            public bool Active { get { return Life != null && !Waiting && (Life.Status == "EVAL" || Life.Status == "FUNDED"); } }
        }

        static double Threshold(Acct a, KeystoneRecoilPropConfig c)
        {
            double maxLoss = a.Eval ? c.EvalMaxLoss : c.FundedMaxLoss; string mode = a.Eval ? c.EvalDrawdown : c.FundedDrawdown;
            if (mode == "STATIC") return -maxLoss;
            double hwm = mode == "INTRADAY" ? a.HwmIntra : a.HwmEod;
            return Math.Min(hwm - maxLoss, c.TrailLockAt);
        }
        // Room before the account is liquidated (and before its daily loss limit).
        static double Room(Acct a, KeystoneRecoilPropConfig c)
        {
            double room = a.Balance - Threshold(a, c);
            if (c.DailyLossLimit > 0) room = Math.Min(room, c.DailyLossLimit + a.DayPnl);
            return Math.Max(0, room);
        }

        // A single position on its own (ROTATION): its own $ target and stop, the same conservative minute rules as the ladder.
        public static KeystoneRecoilSingle ResolveSingle(List<KeystoneHelixMinute> minutes, string symbol, int dir, double price, int qty, double pv, DateTime fillTime, double targetDollars, double stopDollars, DateTime close, double commissionPerSide, double slipTicks)
        {
            var r = new KeystoneRecoilSingle();
            bool mg = symbol == "MGC"; double tick = mg ? KeystoneRecoil.MgcTick : KeystoneRecoil.MnqTick;
            double tp = price + dir * targetDollars / (qty * pv), sp = price - dir * stopDollars / (qty * pv);
            Func<double, double> val = px => dir * (px - price) * qty * pv;
            int lo = 0, hi = minutes.Count - 1, k0 = minutes.Count;
            while (lo <= hi) { int mid = (lo + hi) / 2; if (minutes[mid].Time >= fillTime) { k0 = mid; hi = mid - 1; } else lo = mid + 1; }
            double comm = commissionPerSide * 2 * qty, slip = slipTicks * tick * pv * qty;
            DateTime lastT = fillTime; double lastC = price;
            for (int k = k0; k < minutes.Count; k++)
            {
                var m = minutes[k]; if (m.Time > close) break;
                if (!(mg ? m.HasMgc : m.HasMnq)) continue;
                double o = mg ? m.MgcO : m.MnqO, h = mg ? m.MgcH : m.MnqH, l = mg ? m.MgcL : m.MnqL, cl = mg ? m.MgcC : m.MnqC;
                double adv = dir > 0 ? l : h, fav = dir > 0 ? h : l;
                bool entryMinute = m.Time == fillTime;
                r.Worst = Math.Min(r.Worst, val(adv)); r.Best = Math.Max(r.Best, val(entryMinute ? cl : fav));
                if (!entryMinute)
                {
                    if (dir * (o - sp) <= 0) { r.Exit = m.Time; r.ExitPrice = o; r.Reason = "STOP"; r.Pnl = val(o) - comm - slip; return r; }
                    if (dir * (o - tp) >= 0) { r.Exit = m.Time; r.ExitPrice = o; r.Reason = "TARGET"; r.Pnl = val(o) - comm; return r; }
                }
                if (dir * (adv - sp) <= 0) { r.Exit = m.Time; r.ExitPrice = sp; r.Reason = "STOP"; r.Pnl = val(sp) - comm - slip; return r; }
                if (entryMinute ? dir * (cl - tp) >= 0 : dir * (fav - tp) >= 0) { r.Exit = m.Time; r.ExitPrice = tp; r.Reason = "TARGET"; r.Pnl = val(tp) - comm; return r; }
                lastT = m.Time; lastC = cl;
            }
            r.Exit = lastT; r.ExitPrice = lastC; r.Reason = "SESSION END"; r.Pnl = val(lastC) - comm - slip; return r;
        }

        public static KeystoneRecoilPropResult Run(List<Tuple<KeystoneRecoilAccountGroup, KeystoneRecoilResult>> runs, KeystoneRecoilPropConfig c, List<KeystoneHelixMinute> minutes)
        {
            var res = new KeystoneRecoilPropResult { Config = c };
            var groups = runs.Where(x => x.Item1.Enabled == 1 && x.Item1.Accounts > 0).ToList();
            if (groups.Count == 0) { res.Notes.Add("No account group is switched on."); return res; }
            var days = groups.SelectMany(x => x.Item2.Days).Distinct().OrderBy(d => d).ToList();
            var slots = new Dictionary<string, List<Acct>>();
            var pointers = new Dictionary<string, int>();
            int purchases = 0;
            Func<Acct, DateTime, bool> buy = (a, day) =>
            {
                if (c.MaxPurchases > 0 && purchases >= c.MaxPurchases) return false;
                purchases++;
                int inst = res.Lives.Count(l => l.Group == a.GroupName && l.Slot == a.Slot + 1) + 1;
                bool eval = c.StartMode == "EVAL";
                a.Life = new KeystoneRecoilLife { Id = a.GroupName + (a.Slot + 1).ToString("00") + "-" + inst.ToString("00"), Group = a.GroupName, Slot = a.Slot + 1, Instance = inst, Bought = day, Status = eval ? "EVAL" : "FUNDED", Cost = eval ? c.EvalCost : c.DirectCost };
                if (!eval) a.Life.FundedDate = day;
                res.Lives.Add(a.Life);
                res.Expenses.Add(new KeystoneRecoilPropMoney { Day = day, Account = a.Life.Id, Kind = eval ? "EVALUATION" : "FUNDED ACCOUNT", Amount = a.Life.Cost });
                a.Eval = eval; a.Waiting = false; a.Balance = 0; a.HwmEod = 0; a.HwmIntra = 0; a.BestDay = 0; a.DaysTraded = 0; a.DaysSincePayout = 0; a.BusyUntil = DateTime.MinValue;
                return true;
            };
            DateTime first = days.Count > 0 ? days[0] : DateTime.Today;
            foreach (var g in groups)
            {
                var list = new List<Acct>();
                for (int k = 0; k < g.Item1.Accounts; k++) { var a = new Acct { GroupName = g.Item1.Name, Slot = k }; buy(a, first); list.Add(a); }
                slots[g.Item1.Name] = list; pointers[g.Item1.Name] = 0;
            }
            foreach (var day in days)
            {
                var row = new KeystoneRecoilPropDay { Day = day };
                foreach (var list in slots.Values) foreach (var a in list) { a.DayPnl = 0; a.TradedToday = false; if (a.Waiting && a.Life != null && a.Life.Status == "PASSED") { a.Waiting = false; a.Eval = false; a.Life.Status = "FUNDED"; a.Life.FundedDate = day; a.Balance = 0; a.HwmEod = 0; a.HwmIntra = 0; a.DaysSincePayout = 0; if (c.ActivationCost > 0) { a.Life.Cost += c.ActivationCost; res.Expenses.Add(new KeystoneRecoilPropMoney { Day = day, Account = a.Life.Id, Kind = "ACTIVATION", Amount = c.ActivationCost }); row.Expenses += c.ActivationCost; } } }
                if (day == first) row.Expenses += res.Expenses.Where(e => e.Day == day && e.Kind != "ACTIVATION").Sum(e => e.Amount);
                foreach (var g in groups)
                {
                    var grp = g.Item1; var list = slots[grp.Name];
                    var ladders = g.Item2.Cycles.Where(x => x.Day == day && x.Fills.Count > 0).OrderBy(x => x.EntryTime).ToList();
                    if (ladders.Count == 0) continue;
                    Action<Acct, KeystoneRecoilPropTrade> book = (a, t) =>
                    {
                        a.Balance += t.Pnl; a.DayPnl += t.Pnl; a.Life.TradingNet += t.Pnl; a.Life.Trades++; if (t.Pnl > 0) a.Life.Wins++; else a.Life.Losses++; a.TradedToday = true;
                        t.BalanceAfter = a.Balance; t.Stage = a.Eval ? "EVAL" : "FUNDED"; res.Trades.Add(t); row.Trading += t.Pnl; row.Trades++;
                        if (t.Liquidated)
                        {
                            a.Life.Status = a.Eval ? "FAILED EVAL" : "BLOWN"; a.Life.EndDate = day; a.Life.EndReason = t.Reason; a.Life.Balance = a.Balance; row.Blowups++;
                            a.Waiting = true;
                        }
                    };
                    if (grp.Mode == "ROTATION")
                    {
                        // Every fill of every ladder goes to the next free account; each holds its own position.
                        var fills = ladders.SelectMany(x => x.Fills.Select((f, i) => Tuple.Create(x, f, i))).OrderBy(t => t.Item2.Time).ToList();
                        foreach (var f in fills)
                        {
                            Acct a = null; int p = pointers[grp.Name];
                            for (int s = 0; s < list.Count; s++) { var cand = list[(p + s) % list.Count]; if (cand.Active && cand.BusyUntil <= f.Item2.Time) { a = cand; pointers[grp.Name] = (p + s + 1) % list.Count; break; } }
                            if (a == null) { res.Notes.Add(day.ToString("yyyy-MM-dd") + " " + grp.Name + " • fill " + f.Item2.Time.ToString("HH:mm") + " skipped: no free account"); continue; }
                            var cy = f.Item1; double room = Room(a, c);
                            double target = c.RotationTarget > 0 ? c.RotationTarget : g.Item2.Config.TargetDollars;
                            var one = ResolveSingle(minutes, cy.Symbol, cy.Dir, f.Item2.Price, f.Item2.Qty, cy.PointValue, f.Item2.Time, target, room, day.AddHours(grp.CloseHhmm / 100).AddMinutes(grp.CloseHhmm % 100), g.Item2.Config.CommissionPerSide, g.Item2.Config.SlippageTicks);
                            a.BusyUntil = one.Exit;
                            if ((a.Eval ? c.EvalDrawdown : c.FundedDrawdown) == "INTRADAY") a.HwmIntra = Math.Max(a.HwmIntra, a.Balance + one.Best);
                            bool liq = one.Reason == "STOP";
                            book(a, new KeystoneRecoilPropTrade { Day = day, Entry = f.Item2.Time, Exit = one.Exit, Account = a.Life.Id, Group = grp.Name, Symbol = cy.Symbol, LadderId = cy.Id, FillIndex = f.Item3, Qty = f.Item2.Qty, Pnl = one.Pnl, Worst = one.Worst, Reason = liq ? "LIQUIDATED" : one.Reason, Liquidated = liq });
                        }
                        continue;
                    }
                    // SINGLE: today's account trades every ladder of the day • COPY: every active account trades every ladder.
                    List<Acct> takers;
                    if (grp.Mode == "COPY") takers = list.Where(a => a.Active).ToList();
                    else
                    {
                        Acct a = null; int p = pointers[grp.Name];
                        for (int s = 0; s < list.Count; s++) { var cand = list[(p + s) % list.Count]; if (cand.Active) { a = cand; pointers[grp.Name] = (p + s + 1) % list.Count; break; } }
                        takers = a == null ? new List<Acct>() : new List<Acct> { a };
                    }
                    // Ladders that overlap in time are one exposure: the account's worst moment is the SUM of their worst moments (a safe overestimate).
                    var clusters = new List<List<KeystoneRecoilCycle>>();
                    foreach (var x in ladders.OrderBy(x => x.EntryTime)) { if (clusters.Count > 0 && clusters[clusters.Count - 1].Any(y => y.ExitTime > x.EntryTime)) clusters[clusters.Count - 1].Add(x); else clusters.Add(new List<KeystoneRecoilCycle> { x }); }
                    foreach (var a in takers)
                        foreach (var cl in clusters)
                        {
                            if (!a.Active) break;
                            double worst = cl.Sum(x => x.MaeValue), best = cl.Sum(x => x.MfeValue), room = Room(a, c);
                            if ((a.Eval ? c.EvalDrawdown : c.FundedDrawdown) == "INTRADAY") { a.HwmIntra = Math.Max(a.HwmIntra, a.Balance + best); room = Room(a, c); }
                            if (worst <= -room)
                            {
                                double costs = cl.Sum(x => x.Commission + x.Slippage);
                                book(a, new KeystoneRecoilPropTrade { Day = day, Entry = cl[0].EntryTime, Exit = cl.Max(x => x.ExitTime), Account = a.Life.Id, Group = grp.Name, Symbol = string.Join("+", cl.Select(x => x.Symbol).Distinct()), LadderId = cl[0].Id, Qty = cl.Sum(x => x.MaxQty), Pnl = -room - costs, Worst = worst, Reason = "LIQUIDATED", Liquidated = true });
                                break;
                            }
                            foreach (var x in cl)
                                book(a, new KeystoneRecoilPropTrade { Day = day, Entry = x.EntryTime, Exit = x.ExitTime, Account = a.Life.Id, Group = grp.Name, Symbol = x.Symbol, LadderId = x.Id, Qty = x.MaxQty, Pnl = x.Net, Worst = x.MaeValue, Reason = x.Win ? "TARGET" : x.Reason });
                        }
                }
                // End of day: trailing drawdown, evaluation pass, payouts, replacements.
                foreach (var list in slots.Values)
                    foreach (var a in list)
                    {
                        if (a.Life == null) continue;
                        if (a.Active)
                        {
                            if (a.TradedToday) { a.DaysTraded++; a.Life.TradingDays++; a.DaysSincePayout++; if (a.DayPnl > a.BestDay) a.BestDay = a.DayPnl; }
                            a.HwmEod = Math.Max(a.HwmEod, a.Balance); a.HwmIntra = Math.Max(a.HwmIntra, a.Balance);
                            if (a.Eval)
                            {
                                bool consistent = c.EvalConsistency <= 0 || a.Balance <= 0 || a.BestDay <= a.Balance * c.EvalConsistency / 100.0;
                                if (a.Balance >= c.EvalTarget && a.DaysTraded >= Math.Max(1, c.EvalMinDays) && consistent) { a.Life.Status = "PASSED"; a.Life.PassDate = day; a.Waiting = true; row.Passes++; }
                            }
                            else if (a.DaysSincePayout >= Math.Max(1, c.PayoutEveryDays) && a.Balance >= c.PayoutMinProfit)
                            {
                                double gross = Math.Min(c.PayoutCap > 0 ? c.PayoutCap : double.MaxValue, a.Balance * c.PayoutPercent / 100.0);
                                if (gross >= c.PayoutMinAmount && gross > 0)
                                {
                                    double cash = gross * c.PayoutSplit / 100.0;
                                    a.Balance -= gross; a.DaysSincePayout = 0; a.Life.Payouts++; a.Life.PayoutGross += gross; a.Life.PayoutCash += cash;
                                    res.Payouts.Add(new KeystoneRecoilPropMoney { Day = day, Account = a.Life.Id, Kind = "PAYOUT " + a.Life.Payouts, Amount = cash, Gross = gross });
                                    row.PayoutCash += cash; row.Payouts++;
                                    if (c.MaxPayouts > 0 && a.Life.Payouts >= c.MaxPayouts) { a.Life.Status = "DONE"; a.Life.EndReason = "MAX PAYOUTS"; a.Life.EndDate = day; a.Waiting = true; }
                                }
                            }
                            a.Life.Balance = a.Balance;
                        }
                        // a lost / finished account is replaced for the next session
                        if (a.Waiting && a.Life.Status != "PASSED" && c.AutoReplace == 1)
                        {
                            double before = res.ExpenseTotal;
                            if (buy(a, day)) { row.Purchases++; row.Expenses += res.ExpenseTotal - before; }
                        }
                    }
                row.Active = slots.Values.Sum(l => l.Count(a => a.Active));
                res.Days.Add(row);
            }
            return res;
        }

        public static string Verdict(KeystoneRecoilPropResult r)
        {
            if (r.Days.Count == 0) return "NO PROP RESULT • no ladders on the loaded days.";
            Func<double, string> m = KeystoneRecoilStudy.Cash;
            return (r.NetCash > 0 ? "PROFITABLE • " : "NOT PROFITABLE • ") + "you end " + (r.NetCash >= 0 ? "+" : "") + m(r.NetCash) + " after buying " + r.Purchases + " accounts (" + m(r.ExpenseTotal) + ") and receiving " + r.Payouts.Count + " payouts (" + m(r.PayoutCash) + ")"
                + " • per account bought " + (r.PerPurchase >= 0 ? "+" : "") + m(r.PerPurchase) + " • " + r.Passes + " evaluations passed, " + r.EvalFails + " failed, " + r.FundedBlowups + " funded accounts blown, " + r.Paid + " accounts ever paid • the most you were down: " + m(r.LowestCash()) + ".";
        }
    }

    // ---- PROP PLANNER (build 10-03) -----------------------------------------------------------------
    // A business calculator for prop firms: evaluations are expenses, payouts are revenue. It simulates the whole
    // life of every evaluation you buy (evaluation → funded → payouts → blown / retired → buy again) under a firm's
    // rules and your daily plan, with days from a coin flip (no strategy) or from a real strategy run (RECOIL days).
    // ---- REAL BRACKET (build 10-03c) ---------------------------------------------------------------
    // One trade a day with fixed rules: at the entry time (New York) buy or sell at the next minute's open, attach a
    // target and a stop in points, close at the close time if neither is hit. Every day is replayed on real 1-minute
    // bars; when one minute touches both the target and the stop, the STOP counts first. Days without the exact entry
    // minute or the direction candle are no-trade days (no price is ever invented).
    public sealed class KeystoneBracketMinuteDay
    {
        public DateTime Day; public string Symbol = string.Empty;
        public int[] Minute;                       // minute of the day of each bar's close stamp (e.g. 9:31 → 571)
        public double[] O, H, L, C;
    }

    public sealed class KeystoneBracketPath
    {
        public DateTime Day; public bool Ok; public int Dir; public double Entry, CloseMove; public int N;
        public double[] Fav, Adv;                  // running best / worst excursion in points (in the trade's direction) up to each minute
        public string Why = string.Empty;
    }

    public sealed class KeystoneBracketSet
    {
        public string Symbol = "MNQ"; public int EntryHhmm = 935, CloseHhmm = 1555; public string Direction = "FOLLOW5";
        public List<KeystoneBracketPath> Days = new List<KeystoneBracketPath>();
        public double PointValue { get { return Symbol == "MGC" ? 10 : 2; } }
        public double Tick { get { return Symbol == "MGC" ? 0.1 : 0.25; } }
        public double CostPerContract { get { return 2 * 0.62 + Tick * PointValue; } }   // commission both sides + 1 tick slippage
        public int Traded { get { return Days.Count(d => d.Ok); } }
        public KeystoneBracketSet Subset(Func<KeystoneBracketPath, bool> keep) { var s = (KeystoneBracketSet)MemberwiseClone(); s.Days = Days.Where(keep).ToList(); return s; }
        public string RuleText() { return Symbol + " • enter at " + KeystoneBracket.Hm(EntryHhmm) + " ET • " + KeystoneBracket.DirectionText(Direction) + " • close at " + KeystoneBracket.Hm(CloseHhmm) + " if nothing is hit"; }
    }

    public static class KeystoneBracket
    {
        public static readonly string[] Directions = { "FOLLOW5", "FADE5", "FOLLOW30", "FADE30", "LONG", "SHORT" };
        public static string DirectionText(string d)
        {
            switch (d)
            {
                case "FOLLOW5": return "same way as the last 5-minute candle (green = buy, red = sell)";
                case "FADE5": return "against the last 5-minute candle (green = sell, red = buy)";
                case "FOLLOW30": return "same way as the last 30 minutes";
                case "FADE30": return "against the last 30 minutes";
                case "LONG": return "always buy";
                case "SHORT": return "always sell";
            }
            return d;
        }
        public static string DirectionShort(string d) { switch (d) { case "FOLLOW5": return "FOLLOW 5M CANDLE"; case "FADE5": return "FADE 5M CANDLE"; case "FOLLOW30": return "FOLLOW LAST 30 MIN"; case "FADE30": return "FADE LAST 30 MIN"; case "LONG": return "ALWAYS BUY"; case "SHORT": return "ALWAYS SELL"; } return d; }
        public static string Hm(int hhmm) { return (hhmm / 100).ToString("00") + ":" + (hhmm % 100).ToString("00"); }
        static int Min(int hhmm) { return hhmm / 100 * 60 + hhmm % 100; }

        // Group close-stamped 1-minute bars of one symbol by New York date.
        public static List<KeystoneBracketMinuteDay> Days(IEnumerable<KeystoneArcBar> bars, string symbol)
        {
            var output = new List<KeystoneBracketMinuteDay>();
            foreach (var g in bars.Where(b => b != null).GroupBy(b => b.Time.Date).OrderBy(g => g.Key))
            {
                var list = g.OrderBy(b => b.Time).ToList();
                output.Add(new KeystoneBracketMinuteDay
                {
                    Day = g.Key, Symbol = symbol, Minute = list.Select(b => b.Time.Hour * 60 + b.Time.Minute).ToArray(),
                    O = list.Select(b => b.Open).ToArray(), H = list.Select(b => b.High).ToArray(), L = list.Select(b => b.Low).ToArray(), C = list.Select(b => b.Close).ToArray()
                });
            }
            return output;
        }

        // Is this a 1-minute series? (median gap between bars of the same day = 1 minute)
        public static bool IsOneMinute(List<KeystoneArcBar> bars)
        {
            if (bars == null || bars.Count < 30) return false;
            var gaps = new List<double>();
            for (int i = 1; i < Math.Min(bars.Count, 400); i++) if (bars[i].Time.Date == bars[i - 1].Time.Date) gaps.Add((bars[i].Time - bars[i - 1].Time).TotalMinutes);
            if (gaps.Count < 20) return false; gaps.Sort(); return Math.Abs(gaps[gaps.Count / 2] - 1) < 0.01;
        }

        public static KeystoneBracketPath Path(KeystoneBracketMinuteDay d, int entryHhmm, int closeHhmm, string direction)
        {
            var p = new KeystoneBracketPath { Day = d.Day };
            int em = Min(entryHhmm), cm = Min(closeHhmm);
            int e = Array.IndexOf(d.Minute, em + 1);          // the bar from entry → entry + 1 minute (we fill at its open)
            if (e < 0) { p.Why = "no " + Hm(entryHhmm) + " minute"; return p; }
            int dir = 0;
            if (direction == "LONG") dir = 1; else if (direction == "SHORT") dir = -1;
            else
            {
                int span = direction.EndsWith("30") ? 30 : 5;
                int a = Array.IndexOf(d.Minute, em - span + 1), z = Array.IndexOf(d.Minute, em);
                if (a < 0 || z < 0 || z < a) { p.Why = "no complete candle before " + Hm(entryHhmm); return p; }
                double move = d.C[z] - d.O[a];
                if (Math.Abs(move) < 1e-9) { p.Why = "flat candle"; return p; }
                dir = Math.Sign(move); if (direction.StartsWith("FADE")) dir = -dir;
            }
            int last = -1; for (int i = e; i < d.Minute.Length && d.Minute[i] <= cm; i++) last = i;
            if (last < e) { p.Why = "no bars before " + Hm(closeHhmm); return p; }
            int n = last - e + 1; p.Fav = new double[n]; p.Adv = new double[n];
            double entry = d.O[e], fav = double.MinValue, adv = double.MinValue;
            for (int i = 0; i < n; i++)
            {
                double f = dir > 0 ? d.H[e + i] - entry : entry - d.L[e + i], a = dir > 0 ? entry - d.L[e + i] : d.H[e + i] - entry;
                fav = Math.Max(fav, f); adv = Math.Max(adv, a); p.Fav[i] = fav; p.Adv[i] = adv;
            }
            p.Ok = true; p.Dir = dir; p.Entry = entry; p.N = n; p.CloseMove = dir * (d.C[last] - entry);
            return p;
        }

        public static KeystoneBracketSet Build(List<KeystoneBracketMinuteDay> days, string symbol, int entryHhmm, int closeHhmm, string direction)
        {
            var s = new KeystoneBracketSet { Symbol = symbol, EntryHhmm = entryHhmm, CloseHhmm = closeHhmm, Direction = direction };
            foreach (var d in days) s.Days.Add(Path(d, entryHhmm, closeHhmm, direction));
            return s;
        }

        static int First(double[] runningMax, double level) { int lo = 0, hi = runningMax.Length; while (lo < hi) { int mid = (lo + hi) / 2; if (runningMax[mid] >= level - 1e-9) hi = mid; else lo = mid + 1; } return lo; }

        // One day of the bracket: +target / −stop in points, else the close. Returns P/L in points and the worst / best open points.
        public static void Resolve(KeystoneBracketPath p, double target, double stop, out double pts, out double worst, out double best, out string how)
        {
            int iS = First(p.Adv, stop), iT = First(p.Fav, target);
            if (iS < p.N && iS <= iT) { pts = -stop; worst = -stop; best = Math.Min(target, Math.Max(0, p.Fav[iS])); how = "STOP"; return; }
            if (iT < p.N) { pts = target; worst = -Math.Max(0, p.Adv[iT]); best = target; how = "TARGET"; return; }
            pts = p.CloseMove; worst = -Math.Max(0, p.Adv[p.N - 1]); best = Math.Max(0, p.Fav[p.N - 1]); how = "CLOSE";
        }

        public static double Points(double dollars, int contracts, KeystoneBracketSet s, bool up)
        {
            double raw = dollars / (Math.Max(1, contracts) * s.PointValue) / s.Tick;
            return Math.Max(1, up ? Math.Ceiling(raw - 1e-9) : Math.Floor(raw + 1e-9)) * s.Tick;
        }
        static double RoundTick(double pts, KeystoneBracketSet s) { return Math.Max(1, Math.Round(pts / s.Tick)) * s.Tick; }

        // The day for an account in its state: evaluation or funded size; on the evaluation's last day aim only for what is
        // left; never risk more than the room left above the floor.
        public static KeystonePropDay Day(KeystoneBracketPath p, KeystonePropRules r, KeystonePropPlan plan, KeystonePropPlanner.Account a)
        {
            var s = plan.Bracket;
            if (p == null || !p.Ok) return new KeystonePropDay { Day = p == null ? DateTime.MinValue : p.Day, Traded = false };
            int c = Math.Max(1, a.Funded ? plan.FundContracts : plan.EvalContracts);
            double k = c * s.PointValue, cost = c * s.CostPerContract;
            double tPts = RoundTick((a.Funded ? plan.FundTarget : plan.EvalTarget) / k, s), sPts = RoundTick((a.Funded ? plan.FundStop : plan.EvalStop) / k, s);
            if (!a.Funded)
            {
                double left = r.Target - a.Bal;
                if (left > 0 && left < tPts * k)
                {
                    double need = Points(left + cost, c, s, true);
                    bool consistent = r.Consistency <= 0 || Math.Max(a.Best, need * k - cost) <= r.Consistency / 100.0 * Math.Max(r.Target, a.Bal + need * k - cost) + 1e-9;
                    if (consistent) tPts = Math.Min(tPts, need);
                }
            }
            double room = a.Room(r) - cost;
            if (sPts * k > room) sPts = Math.Max(s.Tick, Math.Floor(room / k / s.Tick) * s.Tick);
            double pts, worst, best; string how; Resolve(p, tPts, sPts, out pts, out worst, out best, out how);
            return new KeystonePropDay { Day = p.Day, Pnl = pts * k - cost, Worst = worst * k - cost, Best = best * k, Traded = true };
        }

        // How the days end with one size: target / stop / closed at the close time, and the average close.
        public static string Tally(KeystoneBracketSet s, double targetDollars, double stopDollars, int contracts)
        {
            int t = 0, st = 0, cl = 0; double closeSum = 0; double k = Math.Max(1, contracts) * s.PointValue;
            double tp = Math.Max(1, Math.Round(targetDollars / k / s.Tick)) * s.Tick, sp = Math.Max(1, Math.Round(stopDollars / k / s.Tick)) * s.Tick;
            foreach (var p in s.Days.Where(d => d.Ok)) { double pts, w, b; string how; Resolve(p, tp, sp, out pts, out w, out b, out how); if (how == "TARGET") t++; else if (how == "STOP") st++; else { cl++; closeSum += pts * k; } }
            int n = Math.Max(1, t + st + cl);
            return "+" + tp.ToString("0.##", CultureInfo.InvariantCulture) + " / −" + sp.ToString("0.##", CultureInfo.InvariantCulture) + " pts: target " + t + " days (" + (100.0 * t / n).ToString("0") + "%) • stop " + st + " (" + (100.0 * st / n).ToString("0") + "%) • closed at " + Hm(s.CloseHhmm) + " " + cl + " (" + (100.0 * cl / n).ToString("0") + "%, average " + (cl == 0 ? "$0" : (closeSum / cl < 0 ? "−$" : "+$") + Math.Abs(closeSum / cl).ToString("N0", CultureInfo.InvariantCulture)) + ")";
        }

        public static string PlanText(KeystonePropPlan p)
        {
            var s = p.Bracket; if (s == null) return "REAL BRACKET (no data)";
            Func<double, int, string> leg = (dollars, c) => RoundTick(dollars / (Math.Max(1, c) * s.PointValue), s).ToString(s.Symbol == "MGC" ? "0.0" : "0.##", CultureInfo.InvariantCulture);
            Func<double, string> m = v => "$" + v.ToString("N0", CultureInfo.InvariantCulture);
            return s.Symbol + " • " + Hm(s.EntryHhmm) + " • " + DirectionShort(s.Direction) + " • evaluation " + p.EvalContracts + " × +" + leg(p.EvalTarget, p.EvalContracts) + " / −" + leg(p.EvalStop, p.EvalContracts) + " pts (" + m(p.EvalTarget) + " / " + m(p.EvalStop) + ") • funded " + p.FundContracts + " × +" + leg(p.FundTarget, p.FundContracts) + " / −" + leg(p.FundStop, p.FundContracts) + " pts (" + m(p.FundTarget) + " / " + m(p.FundStop) + ")";
        }

        // The rule written as steps a person can follow.
        public static List<string> RuleSteps(KeystonePropPlan p)
        {
            var s = p.Bracket; var steps = new List<string>(); if (s == null) return steps;
            Func<double, int, string> leg = (dollars, c) => RoundTick(dollars / (Math.Max(1, c) * s.PointValue), s).ToString(s.Symbol == "MGC" ? "0.0" : "0.##", CultureInfo.InvariantCulture);
            Func<double, string> m = v => "$" + v.ToString("N0", CultureInfo.InvariantCulture);
            steps.Add("1. Instrument " + s.Symbol + ". One trade a day. Nothing before " + Hm(s.EntryHhmm) + " New York time.");
            steps.Add("2. At " + Hm(s.EntryHhmm) + ": " + DirectionText(s.Direction) + ". Market order.");
            steps.Add("3. EVALUATION: " + p.EvalContracts + " contracts • target +" + leg(p.EvalTarget, p.EvalContracts) + " points (" + m(p.EvalTarget) + ") • stop −" + leg(p.EvalStop, p.EvalContracts) + " points (" + m(p.EvalStop) + "). If you need less than the target to pass, aim only for what is left. Never set the stop past the account's floor.");
            steps.Add("4. FUNDED: " + p.FundContracts + " contract" + (p.FundContracts == 1 ? "" : "s") + " • target +" + leg(p.FundTarget, p.FundContracts) + " points (" + m(p.FundTarget) + ") • stop −" + leg(p.FundStop, p.FundContracts) + " points (" + m(p.FundStop) + ").");
            steps.Add("5. If neither is hit, close at " + Hm(s.CloseHhmm) + ". Do not move the stop or the target. Done for the day.");
            steps.Add("6. Payout when allowed. Account lost → buy the next evaluation the next day.");
            return steps;
        }

        // Entry times tried by the sweet spot.
        public static int[] Times(string symbol) { return symbol == "MGC" ? new[] { 800, 830, 900, 935, 1000, 1030, 1100, 1300 } : new[] { 935, 945, 1000, 1030, 1100, 1300, 1400 }; }
        public static int[] EvalContracts(string symbol) { return symbol == "MGC" ? new[] { 1, 2, 3 } : new[] { 2, 3, 5 }; }
        public static int[] FundContracts(string symbol) { return symbol == "MGC" ? new[] { 1, 2 } : new[] { 1, 2, 4 }; }
        // Funded day targets: small safe days ($200 / $300) up to the MAX-PAYOUT pace: $2,000 cap = 50% of $4,000 → $800 a day for 5 days.
        public static readonly double[] FundTargets = { 200, 300, 500, 800 };

        // SWEET SPOT on real prices: (1) every entry time × direction with your plan's sizes → the best rules;
        // (2) for the best rules every evaluation and funded size → ranked by the value of one evaluation, with the value per year.
        public static List<KeystonePropPlanResult> SweetSpot(List<KeystoneBracketMinuteDay> days, string symbol, int closeHhmm, KeystonePropRules r, KeystonePropPlan basePlan, int n, int seed, Action<string> progress)
        {
            // (1) entry rules, all CPU cores (every simulation has its own random stream → same answer every time)
            var rules = new List<Tuple<int, string>>(); foreach (int t in Times(symbol)) foreach (string dir in Directions) rules.Add(Tuple.Create(t, dir));
            var sets = new KeystoneBracketSet[rules.Count]; var values = new double[rules.Count]; int done = 0;
            int nA = Math.Max(300, n / 3);
            System.Threading.Tasks.Parallel.For(0, rules.Count, i =>
            {
                var set = Build(days, symbol, rules[i].Item1, closeHhmm, rules[i].Item2); values[i] = double.MinValue;
                if (set.Traded >= 10) { var p = basePlan.Copy(); p.Source = "BRACKET"; p.Bracket = set; sets[i] = set; values[i] = KeystonePropPlanner.Evaluate(r, p, null, nA, seed).ValuePerEval; }
                int d = System.Threading.Interlocked.Increment(ref done); if (progress != null) progress("entry rules " + d + " / " + rules.Count);
            });
            // (2) sizes for the best 4 rules
            var plans = new List<KeystonePropPlan>();
            foreach (int i in Enumerable.Range(0, rules.Count).Where(i => sets[i] != null).OrderByDescending(i => values[i]).Take(3))
                foreach (int ec in EvalContracts(symbol))
                    foreach (double eT in new[] { 1000.0, 1500 })
                        foreach (double eS in new[] { 1000.0, 1500, 2000 })
                            foreach (int fc in FundContracts(symbol))
                                foreach (double fT in FundTargets)
                                    foreach (double fS in new[] { 300.0, 600, 1000 })
                                    {
                                        if (eS > r.MaxDrawdown || fS > r.MaxDrawdown) continue;
                                        var p = basePlan.Copy(); p.Source = "BRACKET"; p.Bracket = sets[i]; p.EvalContracts = ec; p.EvalTarget = eT; p.EvalStop = eS; p.FundContracts = fc; p.FundTarget = fT; p.FundStop = fS;
                                        plans.Add(p);
                                    }
            var results = new KeystonePropPlanResult[plans.Count]; done = 0;
            int nB = Math.Max(250, n / 4);
            System.Threading.Tasks.Parallel.For(0, plans.Count, i =>
            {
                var res = KeystonePropPlanner.Evaluate(r, plans[i], null, nB, seed); res.Label = PlanText(plans[i]); results[i] = res;
                int d = System.Threading.Interlocked.Increment(ref done); if (progress != null && d % 25 == 0) progress("sizes " + d + " / " + plans.Count);
            });
            var output = results.OrderByDescending(x => x.ValuePerEval).ToList();
            if (progress != null) progress("checking the best 25 year by year");
            var top = output.Take(25).ToList();
            System.Threading.Tasks.Parallel.ForEach(top, res => YearCheck(res, r, Math.Max(250, n / 4), seed));
            return output;
        }


        // ---- PROOF TEST: rules found by a sweet spot, saved, then re-run on data they never saw ----
        public sealed class SavedRule
        {
            public string Symbol = "MNQ", Direction = "FOLLOW5", FoundRange = string.Empty, FoundYears = string.Empty; public int Entry = 935, Close = 1555, EvalC = 2, FundC = 1;
            public double ET = 1500, ES = 2000, FT = 300, FS = 1000, FoundValue; public bool FoundEveryYear; public int Rank;
            public string ToLine() { return string.Join(";", new[] { Symbol, Entry.ToString(CultureInfo.InvariantCulture), Close.ToString(CultureInfo.InvariantCulture), Direction, EvalC.ToString(CultureInfo.InvariantCulture), ET.ToString(CultureInfo.InvariantCulture), ES.ToString(CultureInfo.InvariantCulture), FundC.ToString(CultureInfo.InvariantCulture), FT.ToString(CultureInfo.InvariantCulture), FS.ToString(CultureInfo.InvariantCulture), FoundValue.ToString("0.##", CultureInfo.InvariantCulture), FoundEveryYear ? "1" : "0", FoundRange.Replace(";", ","), FoundYears.Replace(";", ","), Rank.ToString(CultureInfo.InvariantCulture) }); }
            public static SavedRule FromLine(string line)
            {
                var f = (line ?? string.Empty).Split(';'); if (f.Length < 15) return null;
                try
                {
                    Func<int, double> d = i => double.Parse(f[i], CultureInfo.InvariantCulture);
                    return new SavedRule { Symbol = f[0], Entry = (int)d(1), Close = (int)d(2), Direction = f[3], EvalC = (int)d(4), ET = d(5), ES = d(6), FundC = (int)d(7), FT = d(8), FS = d(9), FoundValue = d(10), FoundEveryYear = f[11] == "1", FoundRange = f[12], FoundYears = f[13], Rank = (int)d(14) };
                }
                catch { return null; }
            }
            public static SavedRule From(KeystonePropPlanResult r, string range, int rank)
            {
                var p = r.Plan; var s = p.Bracket;
                return new SavedRule { Symbol = s.Symbol, Entry = s.EntryHhmm, Close = s.CloseHhmm, Direction = s.Direction, EvalC = p.EvalContracts, ET = p.EvalTarget, ES = p.EvalStop, FundC = p.FundContracts, FT = p.FundTarget, FS = p.FundStop, FoundValue = r.ValuePerEval, FoundEveryYear = r.EveryYear, FoundRange = range, FoundYears = r.YearText, Rank = rank };
            }
            public KeystonePropPlan Plan(KeystonePropPlan basePlan, List<KeystoneBracketMinuteDay> days)
            {
                var p = basePlan.Copy(); p.Source = "BRACKET"; p.Bracket = Build(days, Symbol, Entry, Close, Direction);
                p.EvalContracts = EvalC; p.EvalTarget = ET; p.EvalStop = ES; p.FundContracts = FundC; p.FundTarget = FT; p.FundStop = FS; return p;
            }
        }

        public static string RangeText(List<KeystoneBracketMinuteDay> days) { return days == null || days.Count == 0 ? "" : days[0].Day.ToString("yyyy-MM-dd") + " → " + days[days.Count - 1].Day.ToString("yyyy-MM-dd"); }

        // Do two "yyyy-MM-dd → yyyy-MM-dd" ranges overlap? (then the proof is not on new data)
        public static bool Overlaps(string a, string b)
        {
            DateTime a0, a1, b0, b1;
            if (!ParseRange(a, out a0, out a1) || !ParseRange(b, out b0, out b1)) return false;
            return a0 <= b1 && b0 <= a1;
        }
        static bool ParseRange(string s, out DateTime x, out DateTime y)
        {
            x = y = DateTime.MinValue; var parts = (s ?? string.Empty).Split(new[] { " → " }, StringSplitOptions.None); if (parts.Length != 2) return false;
            return DateTime.TryParseExact(parts[0].Trim(), "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out x) && DateTime.TryParseExact(parts[1].Trim(), "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out y);
        }

        // Every saved rule on the days loaded now (all CPU cores), with the value per year.
        public static List<Tuple<SavedRule, KeystonePropPlanResult>> ProofTest(List<KeystoneBracketMinuteDay> days, List<SavedRule> saved, KeystonePropRules r, KeystonePropPlan basePlan, int n, int seed)
        {
            var res = new KeystonePropPlanResult[saved.Count];
            System.Threading.Tasks.Parallel.For(0, saved.Count, i =>
            {
                var p = saved[i].Plan(basePlan, days);
                var x = KeystonePropPlanner.Evaluate(r, p, null, n, seed); x.Label = PlanText(p); YearCheck(x, r, n, seed); res[i] = x;
            });
            return Enumerable.Range(0, saved.Count).Select(i => Tuple.Create(saved[i], res[i])).ToList();
        }

        // One row per loaded day: what the rule did with the evaluation size and with the funded size (no account state).
        public static string DayCsv(KeystonePropPlan p)
        {
            var s = p.Bracket; var sb = new StringBuilder();
            sb.AppendLine("date,traded,why_no_trade,direction,entry_price,eval_result,eval_points,eval_dollars,funded_result,funded_points,funded_dollars,worst_points_before_exit_eval");
            if (s == null) return sb.ToString();
            Func<double, int, double> pts = (dollars, c) => RoundTick(dollars / (Math.Max(1, c) * s.PointValue), s);
            double eT = pts(p.EvalTarget, p.EvalContracts), eS = pts(p.EvalStop, p.EvalContracts), fT = pts(p.FundTarget, p.FundContracts), fS = pts(p.FundStop, p.FundContracts);
            foreach (var d in s.Days.OrderBy(x => x.Day))
            {
                if (!d.Ok) { sb.Append(d.Day.ToString("yyyy-MM-dd")).Append(",0,").Append((d.Why ?? "").Replace(",", " ")).AppendLine(",,,,,,,,,"); continue; }
                double ep, ew, eb, fp, fw, fb; string eh, fh; Resolve(d, eT, eS, out ep, out ew, out eb, out eh); Resolve(d, fT, fS, out fp, out fw, out fb, out fh);
                sb.Append(d.Day.ToString("yyyy-MM-dd")).Append(",1,,").Append(d.Dir > 0 ? "BUY" : "SELL").Append(',').Append(d.Entry.ToString(CultureInfo.InvariantCulture))
                  .Append(',').Append(eh).Append(',').Append(ep.ToString("0.##", CultureInfo.InvariantCulture)).Append(',').Append((ep * p.EvalContracts * s.PointValue - p.EvalContracts * s.CostPerContract).ToString("0.00", CultureInfo.InvariantCulture))
                  .Append(',').Append(fh).Append(',').Append(fp.ToString("0.##", CultureInfo.InvariantCulture)).Append(',').Append((fp * p.FundContracts * s.PointValue - p.FundContracts * s.CostPerContract).ToString("0.00", CultureInfo.InvariantCulture))
                  .Append(',').Append(ew.ToString("0.##", CultureInfo.InvariantCulture)).AppendLine();
            }
            return sb.ToString();
        }

        // Value of one evaluation using only each year's days (the same rule must work in every year, not only overall).
        public static void YearCheck(KeystonePropPlanResult res, KeystonePropRules r, int n, int seed)
        {
            var p = res.Plan; if (p == null || p.Bracket == null) return;
            var parts = new List<string>(); bool every = true;
            foreach (int y in p.Bracket.Days.Where(d => d.Ok).Select(d => d.Day.Year).Distinct().OrderBy(y => y))
            {
                var q = p.Copy(); q.Bracket = p.Bracket.Subset(d => d.Day.Year == y);
                if (q.Bracket.Traded < 10) continue;
                double v = KeystonePropPlanner.Evaluate(r, q, null, n, seed).ValuePerEval;
                res.YearValues[y] = v; if (v <= 0) every = false;
                parts.Add(y + " " + (v < 0 ? "−$" : "+$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture));
            }
            res.EveryYear = every && parts.Count > 0; res.YearText = string.Join(" • ", parts);
        }
    }

    public sealed class KeystonePropRules
    {
        public string Name = "50K • 50% CONSISTENCY";
        public double EvalCost = 120, Activation = 0, Target = 3000, MaxDrawdown = 2000, LockAt = 100;
        public string Drawdown = "EOD";            // EOD (trails the best end-of-day balance) • INTRADAY (trails the best open balance) • STATIC
        public double Consistency = 50;            // % — the best day may be at most this share of the total profit (0 = no rule)
        public int MinDays = 2;
        public double DailyLoss = 0;               // firm daily loss limit (0 = none)
        public int PayoutDays = 5; public double QualifyingDay = 150, PayoutPercent = 50, PayoutCap = 2000, PayoutMin = 0, Split = 90; public int MaxPayouts = 0;
        public KeystonePropRules Copy() { return (KeystonePropRules)MemberwiseClone(); }
        public static List<KeystonePropRules> Presets()
        {
            return new List<KeystonePropRules>
            {
                new KeystonePropRules { Name = "50K • 50% CONSISTENCY", Consistency = 50, MinDays = 2 },
                new KeystonePropRules { Name = "50K • 40% CONSISTENCY", Consistency = 40, MinDays = 3 },
                new KeystonePropRules { Name = "50K • 35% CONSISTENCY", Consistency = 35, MinDays = 3 },
                new KeystonePropRules { Name = "25K • 1,250 DD / 1,500 TARGET", EvalCost = 90, Target = 1500, MaxDrawdown = 1250, Consistency = 50, MinDays = 2, PayoutCap = 1000 },
            };
        }
        public string Describe()
        {
            Func<double, string> m = v => "$" + v.ToString("N0", CultureInfo.InvariantCulture);
            return Name + " • evaluation " + m(EvalCost) + (Activation > 0 ? " + activation " + m(Activation) : "") + " • target " + m(Target) + " • max drawdown " + m(MaxDrawdown) + " " + Drawdown + (Drawdown != "STATIC" ? " (stops trailing at +" + m(LockAt) + ")" : "")
                + (Consistency > 0 ? " • best day ≤ " + Consistency.ToString("0") + "% of the profit" : "") + (MinDays > 1 ? " • " + MinDays + " days min" : "") + (DailyLoss > 0 ? " • daily loss " + m(DailyLoss) : "")
                + " • payout after " + PayoutDays + " days of ≥ " + m(QualifyingDay) + ": " + PayoutPercent.ToString("0") + "% of the profit up to " + m(PayoutCap) + ", you keep " + Split.ToString("0") + "%" + (MaxPayouts > 0 ? " • max " + MaxPayouts + " payouts" : "");
        }
    }

    public sealed class KeystonePropPlan
    {
        public string Source = "COIN";             // COIN (no strategy) • REAL (days from a real strategy run) • BRACKET (one bracket trade a day on real 1-minute bars)
        public KeystoneBracketSet Bracket;         // BRACKET: the entry rule replayed on every loaded day
        public int EvalContracts = 5, FundContracts = 1;   // BRACKET: contracts; EvalTarget / EvalStop / FundTarget / FundStop are the dollar sizes
        public double EvalTarget = 1500, EvalStop = 2000, FundTarget = 200, FundStop = 1000;   // COIN: the day ends at +target or −stop (the stop never goes past the account's room)
        public double Edge = 0;                    // COIN: extra win chance in % points (0 = pure luck)
        public double DayCost = 5;                 // commission / slippage per trading day
        public double EvalSize = 1, FundSize = 1, EvalDayStop = 0, FundDayStop = 0;   // REAL: size multiplier and an optional day stop (0 = none)
        public KeystonePropPlan Copy() { return (KeystonePropPlan)MemberwiseClone(); }
        public string Describe()
        {
            Func<double, string> m = v => "$" + v.ToString("N0", CultureInfo.InvariantCulture);
            if (Source == "BRACKET") return "REAL BRACKET • " + KeystoneBracket.PlanText(this);
            if (Source == "REAL") return "REAL DAYS • evaluation size ×" + EvalSize.ToString("0.##") + (EvalDayStop > 0 ? " (day stop " + m(EvalDayStop) + ")" : "") + " • funded size ×" + FundSize.ToString("0.##") + (FundDayStop > 0 ? " (day stop " + m(FundDayStop) + ")" : "");
            return "COIN FLIP" + (Edge != 0 ? " + " + Edge.ToString("0.#") + "% edge" : " (no edge)") + " • evaluation days +" + m(EvalTarget) + " / −" + m(EvalStop) + " • funded days +" + m(FundTarget) + " / −" + m(FundStop) + " • costs " + m(DayCost) + "/day";
        }
    }

