        private void UpdateFvgPointsPreview()
        {
            if (fvgPointsPreview == null) return;
            string scope = scopeBox == null ? "MGC" : Convert.ToString(scopeBox.SelectedItem ?? "MGC");
            double qty = Math.Max(1, Number(quantityBox, 10));
            var parts = new List<string>();
            string[] names = { "DT", "A", "B", "C" };
            foreach (string sym in scope == "BOTH" ? new[] { "MGC", "MNQ" } : new[] { scope })
            {
                double pv = sym == "MGC" ? 10 : 2;
                var one = new List<string>();
                for (int g = 0; g < 4; g++)
                {
                    double sp = Number(fvgPtsBoxes[g * 2], 5), tp = Number(fvgPtsBoxes[g * 2 + 1], 10);
                    one.Add(names[g] + " −" + Cash(sp * pv * qty) + " / +" + Cash(tp * pv * qty) + " (" + (tp / Math.Max(0.01, sp)).ToString("0.#", CultureInfo.InvariantCulture) + "R)");
                }
                parts.Add(qty.ToString("0") + " " + sym + ": " + string.Join(" • ", one));
            }
            fvgPointsPreview.Text = "WITH YOUR STEP 2 CONTRACTS • " + string.Join("   |   ", parts);
        }

        private bool IsFvgSelected()
        {
            return strategyBox != null && Convert.ToString(strategyBox.SelectedItem ?? string.Empty).StartsWith("FVG", StringComparison.OrdinalIgnoreCase);
        }

        private bool IsRelaySelected() { return strategyBox != null && Convert.ToString(strategyBox.SelectedItem ?? string.Empty).StartsWith("LAST-HOUR RELAY", StringComparison.OrdinalIgnoreCase); }
        private bool IsVwapSelected() { return strategyBox != null && Convert.ToString(strategyBox.SelectedItem ?? string.Empty).StartsWith("VWAP SNAP-BACK", StringComparison.OrdinalIgnoreCase); }

        private bool IsEngulfingSelected()
        {
            return strategyBox != null && Convert.ToString(strategyBox.SelectedItem ?? string.Empty).StartsWith("123 ENGULFING", StringComparison.OrdinalIgnoreCase);
        }

        private bool IsAsian75Selected()
        {
            return strategyBox != null && Convert.ToString(strategyBox.SelectedItem ?? string.Empty).StartsWith("ASIAN 75", StringComparison.OrdinalIgnoreCase);
        }

        private void RefreshStrategyInputState()
        {
            bool asian = IsAsian75Selected();
            bool helix = IsHelixSelected();
            for (int i = 0; i < bhStrategyControls.Count; i++) if (bhStrategyControls[i] != null) bhStrategyControls[i].Visibility = asian || helix ? Visibility.Collapsed : Visibility.Visible;
            for (int i = 0; i < helixStrategyControls.Count; i++) if (helixStrategyControls[i] != null) helixStrategyControls[i].Visibility = helix ? Visibility.Visible : Visibility.Collapsed;
            bool golden = IsGoldenSelected();
            for (int i = 0; i < goldenStrategyControls.Count; i++) if (goldenStrategyControls[i] != null) goldenStrategyControls[i].Visibility = golden ? Visibility.Visible : Visibility.Collapsed;
            if (golden) for (int i = 0; i < bhStrategyControls.Count; i++) if (bhStrategyControls[i] != null) bhStrategyControls[i].Visibility = Visibility.Collapsed;
            bool recoil = IsRecoilSelected();
            for (int i = 0; i < recoilStrategyControls.Count; i++) if (recoilStrategyControls[i] != null) recoilStrategyControls[i].Visibility = recoil ? Visibility.Visible : Visibility.Collapsed;
            if (recoil) for (int i = 0; i < bhStrategyControls.Count; i++) if (bhStrategyControls[i] != null) bhStrategyControls[i].Visibility = Visibility.Collapsed;
            bool mad = IsMadSelected();
            for (int i = 0; i < madStrategyControls.Count; i++) if (madStrategyControls[i] != null) madStrategyControls[i].Visibility = mad ? Visibility.Visible : Visibility.Collapsed;
            if (mad) for (int i = 0; i < bhStrategyControls.Count; i++) if (bhStrategyControls[i] != null) bhStrategyControls[i].Visibility = Visibility.Collapsed;
            bool bracket = IsBracketSelected();
            for (int i = 0; i < bracketStrategyControls.Count; i++) if (bracketStrategyControls[i] != null) bracketStrategyControls[i].Visibility = bracket ? Visibility.Visible : Visibility.Collapsed;
            if (bracket) for (int i = 0; i < bhStrategyControls.Count; i++) if (bhStrategyControls[i] != null) bhStrategyControls[i].Visibility = Visibility.Collapsed;
            if (bracket && !bracketDefaultsApplied) { if (scopeBox != null) scopeBox.SelectedIndex = 2; bracketDefaultsApplied = true; }
            if (!bracket) bracketDefaultsApplied = false;
            if (golden && !goldenDefaultsApplied) { if (scopeBox != null) scopeBox.SelectedIndex = 2; if (timeframeBox != null) timeframeBox.SelectedIndex = 1; if (liveFixedBox != null) liveFixedBox.IsChecked = true; goldenDefaultsApplied = true; }
            if (!golden) goldenDefaultsApplied = false;
            for (int i = 0; i < asianStrategyControls.Count; i++) if (asianStrategyControls[i] != null) asianStrategyControls[i].Visibility = asian ? Visibility.Visible : Visibility.Collapsed;
            bool fvg = IsFvgSelected();
            for (int i = 0; i < fvgStrategyControls.Count; i++) if (fvgStrategyControls[i] != null) fvgStrategyControls[i].Visibility = fvg ? Visibility.Visible : Visibility.Collapsed;
            bool eng = IsEngulfingSelected();
            for (int i = 0; i < engStrategyControls.Count; i++) if (engStrategyControls[i] != null) engStrategyControls[i].Visibility = eng ? Visibility.Visible : Visibility.Collapsed;
            bool relay = IsRelaySelected(), vwapPick = IsVwapSelected();
            for (int i = 0; i < relayStrategyControls.Count; i++) if (relayStrategyControls[i] != null) relayStrategyControls[i].Visibility = relay ? Visibility.Visible : Visibility.Collapsed;
            for (int i = 0; i < vwapStrategyControls.Count; i++) if (vwapStrategyControls[i] != null) vwapStrategyControls[i].Visibility = vwapPick ? Visibility.Visible : Visibility.Collapsed;
            // Relay needs the evening Globex open → default FULL GLOBEX; VWAP snap-back is an NY-day strategy.
            if (relay && !relaySessionDefaultApplied && sessionBox != null) { sessionBox.SelectedIndex = 4; relaySessionDefaultApplied = true; }
            if (!relay) relaySessionDefaultApplied = false;
            if (vwapPick && !vwapSessionDefaultApplied && sessionBox != null) { sessionBox.SelectedIndex = 0; vwapSessionDefaultApplied = true; }
            if (!vwapPick) vwapSessionDefaultApplied = false;
            // BH stop modes belong to BH only; the other strategies have their own stop choices.
            if (stopModeRowRef != null) stopModeRowRef.Visibility = asian || fvg || eng || relay || vwapPick || helix || golden || recoil || bracket || mad ? Visibility.Collapsed : Visibility.Visible;
            // FVG default window: pre-NY 08:00 ET to the 16:55 ET close (editable custom range).
            if (fvg && !fvgSessionDefaultApplied && sessionBox != null && customStartBox != null && endTimeBox != null) { sessionBox.SelectedIndex = 6; customStartBox.Text = "800"; endTimeBox.Text = "1655"; fvgSessionDefaultApplied = true; }
            if (!fvg) fvgSessionDefaultApplied = false;
            // Asian defaults to the combined MNQ + MGC study, but a backtest may intentionally
            // isolate MNQ or MGC.  The scope selector therefore remains active after the first
            // Asian default is applied; the report and data-request path use that exact scope.
            if (scopeBox != null)
            {
                if (asian && !asianScopeDefaultApplied) { scopeBox.SelectedIndex = 2; asianScopeDefaultApplied = true; }
                if (!asian) asianScopeDefaultApplied = false;
                scopeBox.IsEnabled = true;
            }
            if (timeframeBox != null) { if (asian || helix || recoil || bracket || mad) timeframeBox.SelectedIndex = 0; timeframeBox.IsEnabled = !asian && !helix && !recoil && !bracket && !mad; }
            // HELIX always loads both instruments on 1-minute bars; its own window decides the session.
            if (helix && scopeBox != null) { scopeBox.SelectedIndex = 2; scopeBox.IsEnabled = false; }
            if (sessionBox != null)
            {
                if (asian && sessionBox.SelectedIndex != 7) sessionBox.SelectedIndex = 7;
                if (!asian && sessionBox.SelectedIndex == 7) sessionBox.SelectedIndex = 0;
                sessionBox.IsEnabled = !asian;
            }
            if (strategyRuleText != null)
            {
                strategyRuleText.Foreground = asian || IsFvgSelected() ? Orchid : Gold;
                strategyRuleText.Text = IsFvgSelected()
                    ? "FVG RULE: a bullish gap forms when candle 3's low is above candle 1's high (box = candle 1 high → candle 3 low, any colours). Later a candle dips into the box (depth setting) without closing below it; the first green close after the dip is the reference; the next candle breaking that green high is the long entry at that high. A close below the box kills it; running far above retires it. Everything is on the chosen timeframe, New York time."
                    : asian
                    ? "ASIAN CYCLE BACKTEST: default scope is BOTH, but MNQ or MGC may be selected alone. Every selected instrument uses validated direct 1-minute bars, enters at the selected exact minute (18:00 ET by default) in the selected direction, reverses on the next minute after its fixed loss, and adds one micro per reversal. The automatic loss ceiling uses selected instruments × reversal legs × cash loss; the combined profit target closes the daily cycle."
                    : "BH RULE: after the chosen session begins, a red candle is followed by a bullish reference candle; the immediately next bar breaks that bullish high. Every valid long BH setup is detected and eligible by default. No contract month is required.";
            }
            if (confirmConfigurationButton != null) confirmConfigurationButton.Content = asian ? "START BACKTEST • LOAD + RUN CYCLES" : "START RESEARCH • LOAD + DETECT";
            RefreshStartButtonLabel();
            if (strategyWorkflowText != null)
            {
                strategyWorkflowText.Text = asian
                    ? "ASIAN = no setup search. At the exact selected 1-minute opening bar, every selected instrument enters in the selected direction. A fixed reversal loss closes that leg; the next one-minute open reverses direction and adds one micro. The combined target, daily loss, or session end closes the cycle. For BOTH, MNQ and MGC must both have the exact opening bar—Keystone never substitutes a nearby price or silently tests only one instrument."
                    : "BH = red candle → bullish reference → next high break. Every detected setup is automatically included in the research ledger and virtual pool. The review screen is for chart inspection or excluding a specific setup only.";
            }
            if (relay || vwapPick)
            {
                if (strategyRuleText != null) { strategyRuleText.Foreground = Orchid; strategyRuleText.Text = relay ? "LAST-HOUR RELAY RULE: how the day starts tends to show how it ends. Strong move from the Globex open to 10:00 → trade the same direction from 15:25 to 15:55. One decision a day." : "VWAP SNAP-BACK RULE: midday stretches far beyond VWAP usually snap partway back once the push fails. Stretch beyond the band → no new extreme → enter back toward VWAP."; }
                if (strategyWorkflowText != null) strategyWorkflowText.Text = "Every entry (buy and sell) is kept in the ledger, drawn on the chart, resolved on 1-minute data and runs through the same pool, payouts, months & sessions, live account and reports. Prop pools never trade the same instrument long and short at the same time.";
            }
            if (golden)
            {
                if (strategyRuleText != null) { strategyRuleText.Foreground = Gold; strategyRuleText.Text = "GOLDEN RULE: MNQ from 09:30, MGC from 08:00 (editable). The FIRST bullish setup whose candles all form after the start — BH (red → green reference → next candle breaks its high) or a bullish 5-minute FVG (candle 3 low above candle 1 high) — is the one trade of the day. Target MNQ +100 pts, MGC +10 pts; stop below the pattern's low. The push down before it (points from the start price + red candles in a row) is measured on every setup."; }
                if (strategyWorkflowText != null) strategyWorkflowText.Text = "GOLDEN = one trade a day per instrument. Every entry is kept in the ledger with its push down, drawn on the chart, resolved on 1-minute data and runs through the same pool, payouts, months & sessions and reports. RESEARCH FINDINGS compares setups with and without the push down, BH vs FVG, and stop sizes.";
            }
            if (recoil)
            {
                if (strategyRuleText != null) { strategyRuleText.Foreground = Orchid; strategyRuleText.Text = "RECOIL RULE: from the start time wait for a move of TRIGGER points; enter AGAINST it (down → BUY, up → SELL) and add every STEP points further against you (1 → 2 → 3 → 4 contracts by default). Out at the profit target, at the max drawdown (the blowup) or at the close. MNQ only, MGC only or BOTH (shared or split drawdown). 1-minute bars, New York time."; }
                if (strategyWorkflowText != null) strategyWorkflowText.Text = "RECOIL = add to losers. START loads 1-minute bars and runs every ladder; Step 3 switches to the RECOIL view (overview, steps & bounces, risk grid, one live account, every ladder, breakdowns). Change the settings and press RE-RUN in Step 3 — no reload. Prop accounts (evaluation, payouts, copy, rotation, groups by session) come next.";
            }
            if (helix)
            {
                if (strategyRuleText != null) { strategyRuleText.Foreground = Orchid; strategyRuleText.Text = "HELIX RULE: no setup search. From the first basket time, one account at a time opens MNQ + MGC together; the basket closes on its combined $ target or $ stop, then after the pause the next account opens the next basket. Accounts lock for the day by your profit-lock rule and are replaced when liquidated. Scope = BOTH, 1-minute bars, session from the HELIX panel."; }
                if (strategyWorkflowText != null) strategyWorkflowText.Text = "HELIX = rotation math. START loads MNQ + MGC 1-minute bars and runs every session; Step 3 switches to the HELIX view (baskets, days & times, accounts & payouts, expenses, the math, proof tests, setup finder, Manus check). Change HELIX settings and press RE-RUN in Step 3 — no reload.";
            }
            if (eng)
            {
                if (strategyRuleText != null) { strategyRuleText.Foreground = Orchid; strategyRuleText.Text = "123 ENGULFING RULE: a run of 2+ candles of one colour, then a candle of the other colour closes beyond the last run candle's body. Closing beyond its wick is stronger; a wick that also takes the last 2 lows (buy) / highs (sell) is a SWEEP — the strongest. Entry at the close of the engulfing candle; stop beyond its wick (auto size) or your fixed / points stop. Works on every timeframe, MNQ and MGC."; }
                if (strategyWorkflowText != null) strategyWorkflowText.Text = "ENGULFING = run → engulfing close → enter at the close. Every entry (buy and sell) is kept in the ledger, drawn on the chart, resolved on 1-minute data and runs through the same pool, payouts and reports. Prop pools never trade the same instrument long and short at the same time.";
            }
            if (IsFvgSelected())
            {
                if (confirmConfigurationButton != null) confirmConfigurationButton.Content = "START RESEARCH • LOAD + FIND FVG ENTRIES";
                if (strategyWorkflowText != null) strategyWorkflowText.Text = "FVG = gap box → dip into the box → first green close → next candle breaks the green high. Every entry is kept in the ledger, drawn on the chart with its box, resolved on 1-minute data, and runs through the same account pool, payouts and reports as BH.";
            }
            RefreshSessionInputs();
            RefreshStopModelInputState();
            RefreshAsianRiskInputState();
            RefreshInstrumentSourceText();
            if (poolBox != null) RefreshLifecycleInputState();
        }

        private void RefreshAsianRiskInputState()
        {
            bool price = asianRiskModeBox != null && Convert.ToString(asianRiskModeBox.SelectedItem).StartsWith("PRICE", StringComparison.OrdinalIgnoreCase);
            for (int i = 0; i < asianCashRiskControls.Count; i++) if (asianCashRiskControls[i] != null) asianCashRiskControls[i].Visibility = price ? Visibility.Collapsed : Visibility.Visible;
            for (int i = 0; i < asianPriceRiskControls.Count; i++) if (asianPriceRiskControls[i] != null) asianPriceRiskControls[i].Visibility = price ? Visibility.Visible : Visibility.Collapsed;
        }

        private bool asianDailyLossManual, asianDailyLossUpdating;
        private void RefreshAsianDerivedInputs()
        {
            if (asianDailyLossBox == null) return;
            double loss = Number(asianReversalLossBox, 75);
            int reversals = Math.Max(1, Integer(asianMaxReversalsBox, 4));
            string scope = scopeBox == null ? "BOTH" : Convert.ToString(scopeBox.SelectedItem ?? "BOTH");
            bool price = asianRiskModeBox != null && Convert.ToString(asianRiskModeBox.SelectedItem).StartsWith("PRICE", StringComparison.OrdinalIgnoreCase);
            double combined = KeystoneArcEngine.AsianAutoDailyLossLimit(price ? "PRICE" : "CASH", (scope ?? "BOTH").ToUpperInvariant(), loss, Number(asianMnqPriceMoveBox, 37.5), Number(asianMgcPriceMoveBox, 7.5), reversals);
            if (!asianDailyLossManual) { asianDailyLossUpdating = true; try { asianDailyLossBox.Text = combined.ToString("0.##", CultureInfo.InvariantCulture); } finally { asianDailyLossUpdating = false; } }
            if (asianMnqMaxReversalsBox != null) asianMnqMaxReversalsBox.Text = reversals.ToString(CultureInfo.InvariantCulture);
            if (asianMgcMaxReversalsBox != null) asianMgcMaxReversalsBox.Text = reversals.ToString(CultureInfo.InvariantCulture);
        }

        private void RefreshDateInputs()
        {
            if (dateModeBox == null || startBox == null || endBox == null) return;
            bool oneDay = string.Equals(Convert.ToString(dateModeBox.SelectedItem), "ONE DAY", StringComparison.OrdinalIgnoreCase);
            if (oneDay) { endBox.Text = startBox.Text; endBox.IsEnabled = false; }
            else endBox.IsEnabled = true;
        }

        private void RefreshBhAggressionInputState()
        {
            bool stronger = bhFilterBox != null && string.Equals(Convert.ToString(bhFilterBox.SelectedItem), "STRONGER BH • USE THRESHOLDS BELOW", StringComparison.OrdinalIgnoreCase);
            for (int i = 0; i < strongerBhControls.Count; i++)
                if (strongerBhControls[i] != null) strongerBhControls[i].Visibility = stronger ? Visibility.Visible : Visibility.Collapsed;
        }

        private void RefreshResearchModeState()
        {
            if (accountPathBox != null) accountPathBox.SelectedIndex = 0;
            if (stopModeBox != null && Convert.ToString(stopModeBox.SelectedItem).StartsWith("LIVE", StringComparison.OrdinalIgnoreCase)) stopModeBox.SelectedIndex = 0;
            for (int i = 0; i < personalOnlyControls.Count; i++) if (personalOnlyControls[i] != null) personalOnlyControls[i].Visibility = Visibility.Collapsed;
            for (int i = 0; i < liveConfigurationControls.Count; i++) if (liveConfigurationControls[i] != null) liveConfigurationControls[i].Visibility = Visibility.Collapsed;
            for (int i = 0; i < propConfigurationControls.Count; i++) if (propConfigurationControls[i] != null) propConfigurationControls[i].Visibility = Visibility.Visible;
            RefreshStopModelInputState();
        }

        private void RefreshStopModelInputState()
        {
            string selected = stopModeBox == null ? string.Empty : Convert.ToString(stopModeBox.SelectedItem);
            bool low = selected.IndexOf("BELOW 3-CANDLE LOW", StringComparison.OrdinalIgnoreCase) >= 0 && !IsAsian75Selected() && !IsFvgSelected() && !IsEngulfingSelected() && !IsRelaySelected() && !IsVwapSelected();
            bool autoRiskLot = false;
            for (int i = 0; i < lowStopControls.Count; i++)
                if (lowStopControls[i] != null) lowStopControls[i].Visibility = low ? Visibility.Visible : Visibility.Collapsed;
            for (int i = 0; i < autoRiskLotControls.Count; i++)
                if (autoRiskLotControls[i] != null) autoRiskLotControls[i].Visibility = Visibility.Visible;
                else if (autoRiskLotControls[i] != null) autoRiskLotControls[i].Visibility = Visibility.Collapsed;
            if (breakEvenMoveBox != null) breakEvenMoveBox.IsEnabled = breakEvenBox != null && breakEvenBox.IsChecked == true;
        }

        private void SetOneDay(DateTime day)
        {
            if (dateModeBox != null) dateModeBox.SelectedIndex = 0;
            if (startBox != null) startBox.Text = day.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
            if (endBox != null) endBox.Text = day.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
            RefreshDateInputs(); InvalidateConfigurationApproval();
        }

        private void RefreshSessionInputs()
        {
            if (sessionBox == null || customStartBox == null || endTimeBox == null) return;
            string display = Convert.ToString(sessionBox.SelectedItem ?? "NY OPEN 09:30-15:55");
            bool editable = display == "CUSTOM RANGE";
            if (display == "NY OPEN 09:30-15:55") { customStartBox.Text = "930"; endTimeBox.Text = "1555"; }
            if (display == "NY EARLY 08:00-15:55") { customStartBox.Text = "800"; endTimeBox.Text = "1555"; }
            if (display == "ASIA 19:00-03:00") { customStartBox.Text = "1900"; endTimeBox.Text = "300"; }
            if (display == "LONDON 03:00-11:30") { customStartBox.Text = "300"; endTimeBox.Text = "1130"; }
            if (display == "FULL GLOBEX 18:00-16:55") { customStartBox.Text = "1800"; endTimeBox.Text = "1655"; }
            if (display == "ASIAN CYCLE • CONFIGURED TIME") { customStartBox.Text = "1800"; endTimeBox.Text = "1555"; }
            customStartBox.IsEnabled = editable;
            endTimeBox.IsEnabled = editable;
            for (int i = 0; i < customSessionControls.Count; i++)
                if (customSessionControls[i] != null) customSessionControls[i].Visibility = editable ? Visibility.Visible : Visibility.Collapsed;
            if (sessionHintText == null) return;
            if (display == "FULL GLOBEX 18:00-16:55") sessionHintText.Text = "FULL GLOBEX: the whole trading day, 18:00 ET → the 17:00 ET close next day (last 5M bar 16:55–17:00). The 17:00-18:00 CME maintenance break is outside this research window.";
            else if (display == "ASIAN CYCLE • CONFIGURED TIME") sessionHintText.Text = "ASIAN CYCLE BACKTEST: set the exact entry and end HHMM in the Asian parameter panel. Each chosen time uses direct 1-minute data; no prior-close or nearest-bar substitute is used.";
            else if (display == "ASIA 19:00-03:00") sessionHintText.Text = "ASIA: fixed 19:00 ET → 03:00 ET next day. This is a named research label; it is not an exchange-defined quality rating.";
            else if (display == "LONDON 03:00-11:30") sessionHintText.Text = "LONDON: fixed 03:00 ET → 11:30 ET. Use CUSTOM around the U.S./UK daylight-saving transition weeks if exact London-local alignment is needed.";
            else if (display == "INSTRUMENT DEFAULT") sessionHintText.Text = "INSTRUMENT DEFAULT: MNQ starts 09:30; MGC starts 08:00; both end 15:55.";
            else if (display == "CUSTOM RANGE") sessionHintText.Text = "CUSTOM RANGE: enter an exact Eastern-Time start and end in HHMM. An end earlier than the start continues into the next calendar day.";
            else if (display == "NY EARLY 08:00-15:55") sessionHintText.Text = "NY EARLY: fixed 08:00 ET → 15:55 ET. It includes pre-open, NY open, and the regular U.S. session through the selected close.";
            else sessionHintText.Text = "NY OPEN: fixed 09:30 ET → 15:55 ET. The first 09:30 setup bar is included.";
        }

        private void InvalidateConfigurationApproval()
        {
            configurationApproved = false;
            configurationApprovalKey = string.Empty;
            // A real input change creates a new candidate configuration; it may be submitted
            // after the user confirms that the old in-memory research should be cleared.
            researchSubmissionLocked = false;
            UpdateWorkflowState();
        }

        private void WatchConfigurationInput(TextBox input)
        {
            if (input == null) return;
            input.LostFocus += delegate { InvalidateConfigurationApproval(); };
        }

