                {
                    // TradingView habit: double-click resets the view (time + price scale, latest candles).
                    evidenceHorizontalZoom = 1.0; evidenceVerticalZoom = 1.0; evidenceZoom = 1.0; evidencePriceCenter = double.NaN;
                    UpdateEvidenceZoomText();
