        // STUDIO STRATEGY SETTINGS: the parameters each studio strategy shows (label • target object • field • choices)
        private static List<string[]> StudioStrategyParams(int kind)
        {
            var l = new List<string[]>();
            Action<string, string, string, string> p = (label, target, field, choices) => l.Add(new[] { label, target, field, choices ?? "" });
            if (kind >= 1 && kind <= 3) { p("TARGET PTS • MNQ (0 = 30)", "fvg", "MNQ", null); p("TARGET PTS • MGC (0 = 3)", "fvg", "MGC", null); }
            else if (kind == 4) { p("MIN DIP INTO THE BOX %", "cfg", "FvgMinDepthPercent", null); p("MIN GAP • MNQ PTS", "cfg", "FvgMnqMinGap", null); p("MIN GAP • MGC PTS", "cfg", "FvgMgcMinGap", null); p("TRIES PER BOX", "cfg", "FvgMaxEntriesPerBox", null); p("STOP", "cfg", "FvgStopMode", "FORMATION_LOW,BOX,GREEN_LOW,FIXED"); }
            else if (kind == 5) { p("TARGET MOVE • MNQ PTS", "cfg", "MnqTargetMove", null); p("TARGET MOVE • MGC PTS", "cfg", "MgcTargetMove", null); p("STOP MOVE • MNQ PTS", "cfg", "MnqStandardStopMove", null); p("STOP MOVE • MGC PTS", "cfg", "MgcStandardStopMove", null); p("STOP OFFSET • MNQ PTS", "cfg", "MnqStopOffsetPoints", null); p("STOP OFFSET • MGC PTS", "cfg", "MgcStopOffsetPoints", null); }
            else if (kind == 6) { p("STOP", "cfg", "GoldenStopMode", "PATTERN,FIXED"); p("TARGET MOVE • MNQ PTS", "cfg", "MnqTargetMove", null); p("TARGET MOVE • MGC PTS", "cfg", "MgcTargetMove", null); }
            else if (kind == 7)
            {
                p("START (HHMM, NY)", "cfg", "AsianStartHhmm", null); p("END (HHMM, NY)", "cfg", "AsianEndHhmm", null);
                p("FIRST LEG • MNQ", "cfg", "AsianMnqInitialDirection", "LONG,SHORT"); p("FIRST LEG • MGC", "cfg", "AsianMgcInitialDirection", "LONG,SHORT");
                p("REVERSE AFTER A LOSS OF $", "cfg", "AsianReversalLossDollars", null); p("REVERSAL MOVE • MNQ PTS", "cfg", "AsianMnqReversalPriceMove", null); p("REVERSAL MOVE • MGC PTS", "cfg", "AsianMgcReversalPriceMove", null);
                p("CYCLE TARGET $", "cfg", "AsianCycleTargetDollars", null); p("MAX REVERSALS • MNQ", "cfg", "AsianMnqMaxReversals", null); p("MAX REVERSALS • MGC", "cfg", "AsianMgcMaxReversals", null);
                p("MAX LEGS PER INSTRUMENT", "cfg", "AsianMaxTotalLegsPerInstrument", null); p("STARTING CONTRACTS", "cfg", "AsianStartingQuantity", null);
                p("COMBINED STOP $", "cfg", "AsianCombinedStopLossDollars", null); p("DAILY LOSS LIMIT $", "cfg", "AsianDailyLossLimitDollars", null);
            }
            else if (kind >= 8)
            {
                string r = "rule" + (kind - 8);
                p("OPENING TIME (HHMM, NY)", r, "OpenHhmm", null); p("RANGE MINUTES", r, "Minutes", null); p("ENTRY", r, "Mode", "CANDLE,BREAK");
                p("STOP × 14-DAY RANGE (0 = THE RANGE)", r, "StopAtr", null); p("TARGET R (0 = NONE)", r, "TargetR", null); p("ENTRY WINDOW MIN (BREAK)", r, "EntryWindow", null);
                p("FLAT BY (HHMM)", r, "ExitHhmm", null); p("SKIP FOMC / PAYROLLS DAYS", r, "SkipNews", "True,False"); p("SIDE (0 BOTH • 1 BUYS • -1 SELLS)", r, "Side", null);
            }
            return l;
        }

        private static string GetParam(object target, string field)
        {
            var f = target == null ? null : target.GetType().GetField(field); if (f == null) return "";
            return Convert.ToString(f.GetValue(target), CultureInfo.InvariantCulture);
        }

        private static bool SetParam(object target, string field, string value)
        {
            var f = target == null ? null : target.GetType().GetField(field); if (f == null) return false;
            try
            {
                object v;
                if (f.FieldType == typeof(int)) v = (int)Math.Round(double.Parse(value, CultureInfo.InvariantCulture));
                else if (f.FieldType == typeof(double)) v = double.Parse(value, CultureInfo.InvariantCulture);
                else if (f.FieldType == typeof(bool)) v = value.Trim().ToUpperInvariant() == "TRUE" || value.Trim() == "1";
                else v = value.Trim();
                f.SetValue(target, v); return true;
            }
            catch { return false; }
        }

        private static void PaintBtn(Button b, Brush brush) { b.Background = brush; b.Foreground = IsLightBrush(brush) ? Bg : Text; }   // toggles: the text colour follows the background (gold → dark text, dark → light text)
        private static Button Btn(string text, Brush brush) { var b = new Button { Content = text, Background = brush, Foreground = IsLightBrush(brush) ? Bg : Text, FontWeight = FontWeights.SemiBold, Height = 32, Margin = new Thickness(4), Cursor = System.Windows.Input.Cursors.Hand }; try { b.Template = KeyButtonTemplate(); } catch { } return b; }
        // KEYSTONE buttons: rounded, a soft top sheen, a hairline edge; hover lightens, press darkens, disabled fades (not the NinjaTrader skin)
        private static ControlTemplate keyButtonTemplate;
        private static ControlTemplate KeyButtonTemplate()
        {
            if (keyButtonTemplate != null) return keyButtonTemplate;
            var bd = new FrameworkElementFactory(typeof(Border), "bd");
            bd.SetValue(Border.CornerRadiusProperty, new CornerRadius(7)); bd.SetValue(Border.BackgroundProperty, new TemplateBindingExtension(Control.BackgroundProperty));
            bd.SetValue(Border.BorderBrushProperty, new SolidColorBrush(Color.FromArgb(70, 255, 255, 255))); bd.SetValue(Border.BorderThicknessProperty, new Thickness(1));
            var g = new FrameworkElementFactory(typeof(Grid));
            var sheen = new FrameworkElementFactory(typeof(Border)); sheen.SetValue(Border.CornerRadiusProperty, new CornerRadius(6)); sheen.SetValue(Border.BackgroundProperty, new LinearGradientBrush(Color.FromArgb(55, 255, 255, 255), Color.FromArgb(0, 255, 255, 255), 90));
            var hover = new FrameworkElementFactory(typeof(Border), "hover"); hover.SetValue(Border.CornerRadiusProperty, new CornerRadius(6)); hover.SetValue(Border.BackgroundProperty, System.Windows.Media.Brushes.Transparent);
            var cp = new FrameworkElementFactory(typeof(ContentPresenter)); cp.SetValue(FrameworkElement.HorizontalAlignmentProperty, HorizontalAlignment.Center); cp.SetValue(FrameworkElement.VerticalAlignmentProperty, VerticalAlignment.Center); cp.SetValue(FrameworkElement.MarginProperty, new Thickness(10, 0, 10, 0));
            g.AppendChild(sheen); g.AppendChild(hover); g.AppendChild(cp); bd.AppendChild(g);
            var t = new ControlTemplate(typeof(Button)) { VisualTree = bd };
            var over = new Trigger { Property = UIElement.IsMouseOverProperty, Value = true }; over.Setters.Add(new Setter(Border.BackgroundProperty, new SolidColorBrush(Color.FromArgb(40, 255, 255, 255)), "hover")); over.Setters.Add(new Setter(Border.BorderBrushProperty, new SolidColorBrush(Color.FromArgb(150, 255, 255, 255)), "bd"));
            var press = new Trigger { Property = Button.IsPressedProperty, Value = true }; press.Setters.Add(new Setter(Border.BackgroundProperty, new SolidColorBrush(Color.FromArgb(70, 0, 0, 0)), "hover"));
            var off = new Trigger { Property = UIElement.IsEnabledProperty, Value = false }; off.Setters.Add(new Setter(UIElement.OpacityProperty, 0.4, "bd"));
            t.Triggers.Add(over); t.Triggers.Add(press); t.Triggers.Add(off);
            keyButtonTemplate = t; return t;
        }
        // KEYSTONE dialogs: every question / message in our own design (title bar, coloured badge, rounded buttons); Enter = the main button, Esc = cancel
        private static MessageBoxResult KBox(string text) { return KBox(null, text, "KEYSTONE ARC", MessageBoxButton.OK, MessageBoxImage.Information); }
        private static MessageBoxResult KBox(string text, string caption) { return KBox(null, text, caption, MessageBoxButton.OK, MessageBoxImage.Information); }
        private static MessageBoxResult KBox(string text, string caption, MessageBoxButton buttons) { return KBox(null, text, caption, buttons, MessageBoxImage.Question); }
        private static MessageBoxResult KBox(string text, string caption, MessageBoxButton buttons, MessageBoxImage image) { return KBox(null, text, caption, buttons, image); }
        private static MessageBoxResult KBox(Window owner, string text, string caption, MessageBoxButton buttons, MessageBoxImage image)
        {
            if (Application.Current == null) return MessageBox.Show(text, caption, buttons, image);   // no WPF app (the tests): the plain box
            MessageBoxResult result = buttons == MessageBoxButton.OK ? MessageBoxResult.OK : buttons == MessageBoxButton.YesNo ? MessageBoxResult.No : MessageBoxResult.Cancel;
            // our own dialog, never the grey system box: 1st with the Keystone frame on its owner, 2nd without an owner (e.g. the owner is
            // closing), 3rd a plain borderless window with the same design; the system box only if all three fail (the reason is logged)
            var errors = new List<string>();
            for (int attempt = 0; attempt < 3; attempt++)
            try
            {
                if (attempt == 0 && owner == null) owner = Application.Current.Windows.OfType<Window>().FirstOrDefault(x => x.IsActive && x.IsVisible);
                if (attempt > 0) owner = null;
                bool warn = image == MessageBoxImage.Warning, err = image == MessageBoxImage.Error, ask = image == MessageBoxImage.Question;
                var accent = new SolidColorBrush(err ? Color.FromRgb(255, 69, 96) : warn ? Color.FromRgb(255, 184, 0) : ask ? Color.FromRgb(0, 229, 255) : Color.FromRgb(124, 140, 255));
                string cap = (caption ?? "").Replace("KEYSTONE ARC • ", "").Replace("KEYSTONE • ", "").Replace("KEYSTONE ARC", "").Trim();
                Window d = attempt < 2 ? new KeystoneWindow() : new Window { WindowStyle = WindowStyle.None };
                d.Title = "KEYSTONE ARC" + (cap == "" ? "" : " • " + cap); d.SizeToContent = SizeToContent.WidthAndHeight; d.ResizeMode = ResizeMode.NoResize; d.WindowStartupLocation = owner != null ? WindowStartupLocation.CenterOwner : WindowStartupLocation.CenterScreen; d.Background = Bg; d.Foreground = Text; d.ShowInTaskbar = owner == null; d.Topmost = owner == null;
                if (owner != null) d.Owner = owner;
                var body = new StackPanel { Margin = new Thickness(26, 22, 26, 20), MaxWidth = 520 };
                var top = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 0, 0, 12) };
                var badge = new Border { Width = 34, Height = 34, CornerRadius = new CornerRadius(17), Background = new SolidColorBrush(Color.FromArgb(40, accent.Color.R, accent.Color.G, accent.Color.B)), BorderBrush = accent, BorderThickness = new Thickness(1.6), Margin = new Thickness(0, 0, 12, 0),
                    Child = new TextBlock { Text = err ? "✕" : warn ? "!" : ask ? "?" : "i", Foreground = accent, FontSize = 17, FontWeight = FontWeights.Bold, HorizontalAlignment = HorizontalAlignment.Center, VerticalAlignment = VerticalAlignment.Center } };
                top.Children.Add(badge);
                top.Children.Add(new TextBlock { Text = cap == "" ? (ask ? "Please confirm" : warn ? "Attention" : "Keystone Arc") : cap, Foreground = accent, FontSize = 18, FontWeight = FontWeights.Bold, VerticalAlignment = VerticalAlignment.Center, TextWrapping = TextWrapping.Wrap, MaxWidth = 440 });
                body.Children.Add(top);
                body.Children.Add(new TextBlock { Text = text ?? "", Foreground = Text, FontSize = 13.5, TextWrapping = TextWrapping.Wrap, LineHeight = 20, Margin = new Thickness(46, 0, 0, 20) });
                var row = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right };
                Action<MessageBoxResult> done = r0 => { result = r0; d.Close(); };
                Func<string, bool, MessageBoxResult, Border> button = (label, primary, r0) =>
                {
                    var tb = new TextBlock { Text = label, Foreground = primary ? Bg : Text, FontSize = 13, FontWeight = FontWeights.Bold, HorizontalAlignment = HorizontalAlignment.Center };
                    var b = new Border { MinWidth = 104, Padding = new Thickness(18, 8, 18, 9), Margin = new Thickness(10, 0, 0, 0), CornerRadius = new CornerRadius(9), Cursor = System.Windows.Input.Cursors.Hand, Child = tb,
                        Background = primary ? (Brush)new LinearGradientBrush(accent.Color, Color.FromRgb((byte)(accent.Color.R * 0.75), (byte)(accent.Color.G * 0.75), (byte)(accent.Color.B * 0.75)), 90) : Card, BorderBrush = primary ? accent : new SolidColorBrush(Color.FromArgb(80, 255, 255, 255)), BorderThickness = new Thickness(1) };
                    b.MouseEnter += delegate { b.Opacity = 0.85; }; b.MouseLeave += delegate { b.Opacity = 1; };
                    b.MouseLeftButtonUp += delegate { done(r0); };
                    row.Children.Add(b); return b;
                };
                MessageBoxResult enter = MessageBoxResult.OK, esc = result;
                if (buttons == MessageBoxButton.OK) { button("OK", true, MessageBoxResult.OK); enter = esc = MessageBoxResult.OK; }
                else if (buttons == MessageBoxButton.OKCancel) { button("Cancel", false, MessageBoxResult.Cancel); button("OK", true, MessageBoxResult.OK); enter = MessageBoxResult.OK; }
                else if (buttons == MessageBoxButton.YesNo) { button("No", false, MessageBoxResult.No); button("Yes", true, MessageBoxResult.Yes); enter = MessageBoxResult.Yes; }
                else { button("Cancel", false, MessageBoxResult.Cancel); button("No", false, MessageBoxResult.No); button("Yes", true, MessageBoxResult.Yes); enter = MessageBoxResult.Yes; }
                body.Children.Add(row);
                if (attempt < 2) d.Content = new Border { Background = Bg, Child = body };
                else
                {
                    // borderless: our own slim title strip (drag to move) and an accent edge
                    var outer = new DockPanel { LastChildFill = true };
                    var strip = new DockPanel { Height = 30, Background = new LinearGradientBrush(Color.FromRgb(8, 11, 22), Color.FromRgb(16, 22, 44), 0) };
                    strip.Children.Add(new TextBlock { Text = "KEYSTONE ARC" + (cap == "" ? "" : "  •  " + cap), Foreground = new SolidColorBrush(Color.FromRgb(150, 165, 195)), FontSize = 12, FontWeight = FontWeights.Bold, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(12, 0, 12, 0) });
                    var dd0 = d; strip.MouseLeftButtonDown += delegate { try { dd0.DragMove(); } catch { } };
                    DockPanel.SetDock(strip, Dock.Top); outer.Children.Add(strip); outer.Children.Add(body);
                    d.Content = new Border { Background = Bg, BorderBrush = accent, BorderThickness = new Thickness(1.2), Child = outer };
                }
                d.PreviewKeyDown += (s0, e0) => { if (e0.Key == System.Windows.Input.Key.Enter) { e0.Handled = true; done(enter); } else if (e0.Key == System.Windows.Input.Key.Escape) { e0.Handled = true; done(esc); } };
                d.ShowDialog();
                return result;
            }
            catch (Exception ex) { errors.Add("attempt " + attempt + ": " + ex.GetType().Name + " " + ex.Message); }
            try { var lf = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments), "KeystoneArcData", "dialog_errors.log"); Directory.CreateDirectory(Path.GetDirectoryName(lf)); File.AppendAllLines(lf, new[] { DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss") + " • " + caption + " • " + string.Join(" | ", errors) }); } catch { }
            return MessageBox.Show(text, caption, buttons, image);
        }
        // Light buttons (gold, cyan, green, blue, orchid) get dark text; dark and red ones keep light text.
        private static bool IsLightBrush(Brush brush)
        {
            var solid = brush as SolidColorBrush; if (solid == null) return false;
            Color c = solid.Color;
            return (0.299 * c.R + 0.587 * c.G + 0.114 * c.B) / 255.0 > 0.52;
        }
