            var export = Btn("EXPORT STUDY (HTML + CSV)", Gold); export.ToolTip = "Writes the full study (every table and every entry) as an HTML report and a CSV of every entry.";
            var chart = Btn("ENTRIES ON THE CHART", Blue);
            var verify = Btn("ENTRY LIST (STEP 2)", Cyan);
            foreach (var b in new[] { reset, export, chart, verify }) { b.Height = 30; b.FontSize = 11; actions.Children.Add(b); }
            reset.Click += delegate { LoadGoldenFilter(KeystoneGoldenStudy.FromConfig(goldenStudyConfig ?? config)); RunGoldenStudy(); };
            export.Click += delegate { ExportGoldenStudy(); };
            chart.Click += delegate { OpenGoldenEntryChart(null); };
            verify.Click += delegate { if (workspaceTabs != null) workspaceTabs.SelectedIndex = 1; };
            Grid.SetColumn(actions, 1); head.Children.Add(actions);
            goldenVerdictCard = new Border { Background = Card, BorderBrush = Gold, BorderThickness = new Thickness(5, 1.5, 1.5, 1.5), CornerRadius = new CornerRadius(6), Padding = new Thickness(12, 8, 10, 8), Margin = new Thickness(2, 2, 2, 4), Child = head };
            g.Children.Add(goldenVerdictCard);
            // filters
            gfSetupBox = Select("ALL SETUPS", "BH ONLY", "FVG ONLY", "BH + FVG SAME CANDLE ONLY"); gfSetupBox.SelectedIndex = 0;
            gfMnqDropBox = Input("0"); gfMgcDropBox = Input("0"); gfRedBox = Input("0");
            gfMnqGapBox = Input("0"); gfMgcGapBox = Input("0"); gfMnqStopBox = Input("0"); gfMgcStopBox = Input("0");
            gfFromBox = Input("0000"); gfToBox = Input("2359"); gfTriesBox = Input("5"); gfStartBox = Input("5000");
            gfSkipBox = new CheckBox { Content = "SKIP A SETUP WHOSE STOP IS BIGGER THAN ITS TARGET", Foreground = Text, Margin = new Thickness(6), VerticalAlignment = VerticalAlignment.Center };
            gfOneBox = new CheckBox { Content = "ONE TRADE OPEN PER INSTRUMENT", IsChecked = true, Foreground = Text, Margin = new Thickness(6), VerticalAlignment = VerticalAlignment.Center };
            var days = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
            string[] dayNames = { "SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT" };
            gfDayBoxes = new CheckBox[7];
            for (int d = 0; d < 7; d++)
            {
                gfDayBoxes[d] = new CheckBox { Content = dayNames[d], IsChecked = true, Foreground = Text, Margin = new Thickness(3, 6, 3, 6) };
                if (d >= 1 && d <= 5) days.Children.Add(gfDayBoxes[d]);
            }
            foreach (TextBox box in new[] { gfMnqDropBox, gfMgcDropBox, gfRedBox, gfMnqGapBox, gfMgcGapBox, gfMnqStopBox, gfMgcStopBox, gfFromBox, gfToBox, gfTriesBox, gfStartBox }) box.TextChanged += delegate { QueueGoldenStudy(); };
            gfSetupBox.SelectionChanged += delegate { QueueGoldenStudy(); };
            foreach (CheckBox box in new[] { gfSkipBox, gfOneBox }.Concat(gfDayBoxes)) { box.Checked += delegate { QueueGoldenStudy(); }; box.Unchecked += delegate { QueueGoldenStudy(); }; }
            var filters = new UniformGrid { Columns = 4 };
            filters.Children.Add(Row("MNQ PUSH DOWN AT LEAST", gfMnqDropBox));
            filters.Children.Add(Row("MGC PUSH DOWN AT LEAST", gfMgcDropBox));
            filters.Children.Add(Row("RED CANDLES IN A ROW AT LEAST", gfRedBox));
            filters.Children.Add(Row("MNQ FVG GAP AT LEAST", gfMnqGapBox));
            filters.Children.Add(Row("MGC FVG GAP AT LEAST", gfMgcGapBox));
            filters.Children.Add(Row("MNQ STOP AT MOST (0 = ANY)", gfMnqStopBox));
            filters.Children.Add(Row("MGC STOP AT MOST (0 = ANY)", gfMgcStopBox));
            filters.Children.Add(Row("ENTRY FROM (HHMM ET)", gfFromBox));
            filters.Children.Add(Row("ENTRY UNTIL (HHMM ET)", gfToBox));
            filters.Children.Add(Row("TRIES A DAY (UP TO STEP 1)", gfTriesBox));
            filters.Children.Add(Row("ONE ACCOUNT START $", gfStartBox));
            // Choices with long names sit on one line of their own so nothing is cut off.
            var choices = new WrapPanel { Margin = new Thickness(0, 2, 0, 0) };
            Func<string, UIElement, UIElement> pair = (label, control) =>
            {
                var sp = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(4, 0, 18, 0) };
                sp.Children.Add(new TextBlock { Text = label, Foreground = Muted, FontSize = 10, FontWeight = FontWeights.Bold, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 4, 0) });
                sp.Children.Add(control); return sp;
            };
            gfSetupBox.MinWidth = 230;
            gfUniverseBox = Select(KeystoneGoldenStudy.Universes.Select(KeystoneGoldenStudy.UniverseName).ToArray()); gfUniverseBox.SelectedIndex = 0; gfUniverseBox.MinWidth = 330;
            gfUniverseBox.SelectionChanged += delegate { QueueGoldenStudy(); };
            choices.Children.Add(pair("ENTRIES", gfUniverseBox));
            choices.Children.Add(pair("SETUP", gfSetupBox));
            choices.Children.Add(pair("WEEKDAYS", days));
            choices.Children.Add(pair("RISK", gfSkipBox));
            choices.Children.Add(pair("ONE ACCOUNT", gfOneBox));
            var filterStack = new StackPanel();
            filterStack.Children.Add(new TextBlock { Text = "FILTERS • change any value and every table below updates (no reload, no new detection)", Foreground = Cyan, FontSize = 11, FontWeight = FontWeights.Bold, Margin = new Thickness(4, 0, 4, 2) });
            filterStack.Children.Add(choices);
            filterStack.Children.Add(filters);
            goldenFilterNote = new TextBlock { Foreground = Muted, FontSize = 10, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(6, 2, 6, 0) };
            filterStack.Children.Add(goldenFilterNote);
            var filterCard = new Border { Background = Panel, BorderBrush = Cyan, BorderThickness = new Thickness(1.5), CornerRadius = new CornerRadius(6), Padding = new Thickness(6), Margin = new Thickness(2, 0, 2, 4), Child = filterStack };
            Grid.SetRow(filterCard, 1); g.Children.Add(filterCard); goldenFilterCard = filterCard;
            goldenTiles = new WrapPanel { Margin = new Thickness(0, 0, 0, 2) };
            Grid.SetRow(goldenTiles, 2); g.Children.Add(goldenTiles);
            // Slim bar: the summary in one line + the button that gives the tables the whole screen.
            var slim = new Grid { Margin = new Thickness(2, 0, 2, 2) };
            slim.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto }); slim.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) }); slim.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            var goldenPropButton = Btn("PROP SIMULATION • EVALS • PAYOUTS • FLIP", Green); goldenPropButton.Height = 28; goldenPropButton.FontSize = 11; goldenPropButton.Padding = new Thickness(12, 0, 12, 0);
            goldenPropButton.Click += delegate { OpenGoldenPropLab(true); }; Grid.SetColumn(goldenPropButton, 2); slim.Children.Add(goldenPropButton);
            goldenSummaryToggle = Btn("▲ FULL SCREEN TABLES", Cyan); goldenSummaryToggle.Height = 28; goldenSummaryToggle.FontSize = 11; goldenSummaryToggle.Padding = new Thickness(12, 0, 12, 0);
            goldenSummaryToggle.Click += delegate { SetGoldenSummaryHidden(!goldenSummaryHidden); };
            slim.Children.Add(goldenSummaryToggle);
            goldenSlimText = new TextBlock { Foreground = Gold, FontSize = 12, FontWeight = FontWeights.Bold, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(10, 0, 4, 0), TextTrimming = TextTrimming.CharacterEllipsis };
            Grid.SetColumn(goldenSlimText, 1); slim.Children.Add(goldenSlimText);
            Grid.SetRow(slim, 3); g.Children.Add(slim);
            goldenTabs = new TabControl { Background = Panel, BorderBrush = Gold, BorderThickness = new Thickness(1), Margin = new Thickness(0, 2, 0, 0), TabStripPlacement = Dock.Top, VerticalContentAlignment = VerticalAlignment.Stretch, HorizontalContentAlignment = HorizontalAlignment.Stretch };
            Brush[] tabColors = { Red, Gold, Green, Cyan, Blue, Orchid };
            string[] tabNames = { "WHICH ENTRIES", "MNQ • MGC • BOTH", "WHAT MAKES WINNERS", "TARGET × STOP", "ONE ACCOUNT", "EVERY ENTRY" };
            for (int i = 0; i < tabNames.Length; i++)
                goldenTabs.Items.Add(new TabItem { Header = tabNames[i], Background = tabColors[i], Foreground = Bg, FontWeight = FontWeights.Bold, Content = Txt("Run GOLDEN SETUP to fill this tab.", Muted, 11, FontWeights.Normal) });
            Grid.SetRow(goldenTabs, 4); g.Children.Add(goldenTabs);
            // Clicking a tab gives the tables the whole screen (filters and summary fold away).
            foreach (TabItem t in goldenTabs.Items) t.PreviewMouseLeftButtonDown += delegate { if (!goldenSummaryHidden) SetGoldenSummaryHidden(true); };
            goldenResultsHost = g;
            return g;
        }

        private void SetGoldenSummaryHidden(bool hide)
        {
            goldenSummaryHidden = hide;
            Visibility v = hide ? Visibility.Collapsed : Visibility.Visible;
            if (goldenVerdictCard != null) goldenVerdictCard.Visibility = v;
            if (goldenFilterCard != null) goldenFilterCard.Visibility = v;
            if (goldenTiles != null) goldenTiles.Visibility = v;
            if (resultsTopPanel != null && goldenResultsMode) resultsTopPanel.Visibility = v;
            if (goldenSummaryToggle != null) goldenSummaryToggle.Content = hide ? "▼ SHOW FILTERS & SUMMARY" : "▲ FULL SCREEN TABLES";
            if (resultsPageScroll != null) resultsPageScroll.ScrollToTop();
            SizeGoldenHost();
        }

        private void SetGoldenTab(string name, UIElement content)
        {
            if (goldenTabs == null) return;
            foreach (TabItem t in goldenTabs.Items) if (Convert.ToString(t.Header) == name) { t.Content = HelixScroll(content); return; }
        }

        private void LoadGoldenFilter(KeystoneGoldenFilter f)
        {
            if (gfSetupBox == null || f == null) return;
            goldenFilterLoading = true;
            gfSetupBox.SelectedIndex = f.Setup == "BH" ? 1 : f.Setup == "FVG" ? 2 : f.Setup == "DT" ? 3 : 0;
            Func<double, string> n = v => v.ToString("0.##", CultureInfo.InvariantCulture);
            gfMnqDropBox.Text = n(f.MnqMinDrop); gfMgcDropBox.Text = n(f.MgcMinDrop); gfRedBox.Text = f.MinRed.ToString(CultureInfo.InvariantCulture);
            gfMnqGapBox.Text = n(f.MnqMinGap); gfMgcGapBox.Text = n(f.MgcMinGap); gfMnqStopBox.Text = n(f.MnqMaxStop); gfMgcStopBox.Text = n(f.MgcMaxStop);
            gfFromBox.Text = f.FromHhmm.ToString("0000", CultureInfo.InvariantCulture); gfToBox.Text = f.ToHhmm.ToString("0000", CultureInfo.InvariantCulture);
            gfTriesBox.Text = f.MaxTries.ToString(CultureInfo.InvariantCulture); gfStartBox.Text = n(f.StartBalance);
            gfSkipBox.IsChecked = f.SkipStopOverTarget; gfOneBox.IsChecked = f.OnePositionPerInstrument;
            for (int d = 0; d < 7; d++) gfDayBoxes[d].IsChecked = f.Weekdays[d];
            goldenFilterLoading = false;
        }

        private KeystoneGoldenFilter ReadGoldenFilter()
        {
            var f = new KeystoneGoldenFilter();
            if (gfSetupBox == null) return f;
            f.Setup = new[] { "ALL", "BH", "FVG", "DT" }[Math.Max(0, Math.Min(3, gfSetupBox.SelectedIndex))];
            f.MnqMinDrop = NumberAllowZero(gfMnqDropBox, 0); f.MgcMinDrop = NumberAllowZero(gfMgcDropBox, 0); f.MinRed = Math.Max(0, Integer(gfRedBox, 0));
            f.MnqMinGap = NumberAllowZero(gfMnqGapBox, 0); f.MgcMinGap = NumberAllowZero(gfMgcGapBox, 0);
            f.MnqMaxStop = NumberAllowZero(gfMnqStopBox, 0); f.MgcMaxStop = NumberAllowZero(gfMgcStopBox, 0);
            int from = Integer(gfFromBox, 0), to = Integer(gfToBox, 2359);
            f.FromHhmm = IsValidHhmm(from) ? from : 0; f.ToHhmm = IsValidHhmm(to) ? to : 2359;
            f.MaxTries = Math.Max(1, Integer(gfTriesBox, 5));
            f.StartBalance = Math.Max(1, NumberAllowZero(gfStartBox, 5000));
            f.SkipStopOverTarget = gfSkipBox.IsChecked == true; f.OnePositionPerInstrument = gfOneBox.IsChecked == true;
            for (int d = 0; d < 7; d++) f.Weekdays[d] = gfDayBoxes[d].IsChecked == true;
            f.StrictFirst = goldenStudyConfig == null || goldenStudyConfig.GoldenStrictFirst == 1;
            return f;
        }

        private void QueueGoldenStudy()
        {
            if (goldenFilterLoading || !goldenResultsMode) return;
            if (goldenFilterTimer == null)
            {
                goldenFilterTimer = new DispatcherTimer { Interval = TimeSpan.FromMilliseconds(350) };
                goldenFilterTimer.Tick += delegate { goldenFilterTimer.Stop(); RunGoldenStudy(); };
            }
            goldenFilterTimer.Stop(); goldenFilterTimer.Start();
        }

        // Called when a GOLDEN run finishes: the entries with no filter, then the Step 1 filters on top.
        private void ShowGoldenStudy(Dictionary<string, List<KeystoneArcEvent>> sets, KeystoneArcRunConfig runConfig)
        {
            goldenStudySets = sets ?? new Dictionary<string, List<KeystoneArcEvent>>();
            List<KeystoneArcEvent> first; goldenStudyAll = goldenStudySets.TryGetValue("FIRST", out first) && first != null ? first : new List<KeystoneArcEvent>();
            if (gfUniverseBox != null) { goldenFilterLoading = true; gfUniverseBox.SelectedIndex = 0; goldenFilterLoading = false; }
            goldenStudyConfig = runConfig;
            goldenGridIndex = 0;
            SetGoldenResultsMode(true);
            LoadGoldenFilter(KeystoneGoldenStudy.FromConfig(runConfig));
            RunGoldenStudy();
        }

        private void RunGoldenStudy()
        {
            if (goldenTabs == null) return;
            try
            {
                var f = ReadGoldenFilter();
                string u = KeystoneGoldenStudy.Universes[Math.Max(0, Math.Min(KeystoneGoldenStudy.Universes.Length - 1, gfUniverseBox == null ? 0 : gfUniverseBox.SelectedIndex))];
                List<KeystoneArcEvent> set;
                if (!goldenStudySets.TryGetValue(u, out set) || set == null) { set = goldenStudyAll; u = "FIRST"; }
                goldenStudy = KeystoneGoldenStudy.Run(set, f, goldenStudyConfig ?? config, u);
                goldenCompare = KeystoneGoldenStudy.CompareUniverses(goldenStudySets, f, goldenStudyConfig ?? config);
                RenderGoldenStudy(goldenStudy, f);
            }
            catch (Exception ex) { if (goldenVerdictSub != null) { goldenVerdictSub.Text = "GOLDEN STUDY ERROR • " + ex.Message; goldenVerdictSub.Foreground = Red; } }
        }

        private void RenderGoldenStudy(KeystoneGoldenStudyResult r, KeystoneGoldenFilter f)
        {
            var c = goldenStudyConfig ?? config;
            bool any = r.Kept.Count > 0;
            double net = r.Both.NetCash;
            goldenVerdictHead.Text = r.All.Count == 0 ? "NO GOLDEN ENTRIES" : KeystoneGoldenStudy.UniverseName(r.Universe) + "  •  " + r.Kept.Count + " ENTRIES  •  WINS " + GPct(r.Both.WinRate) + "  •  NET " + (net > 0 ? "+" : string.Empty) + Cash(net);
            goldenVerdictHead.Foreground = !any ? Gold : (net > 0 ? Green : Red);
            goldenVerdictCard.BorderBrush = goldenVerdictHead.Foreground;
            if (goldenSlimText != null) { goldenSlimText.Text = goldenVerdictHead.Text + "   •   " + r.Verdict; goldenSlimText.Foreground = goldenVerdictHead.Foreground; }
            goldenVerdictSub.Foreground = Text;
            goldenVerdictSub.Text = r.Verdict + "\n" + (r.Hold ? "Every trade is held until its target or its stop — overnight and into the next days, like a live account. A trade still open when the data ends is counted at its last price."
                : "Trades are closed at " + (c == null ? 1555 : c.GoldenClose).ToString("00:00", CultureInfo.InvariantCulture) + " (Step 1 setting). Choose HOLD in Step 1 to let them run to the target or stop.")
                + "  Target MNQ +" + (c == null ? 100 : c.GoldenMnqTargetPoints).ToString("0.##", CultureInfo.InvariantCulture) + " / MGC +" + (c == null ? 10 : c.GoldenMgcTargetPoints).ToString("0.##", CultureInfo.InvariantCulture) + " pts • stop " + (c != null && c.GoldenStopMode == "FIXED" ? "fixed" : "below the pattern") + " • MNQ " + (c == null ? 5 : c.GoldenMnqQuantity) + " / MGC " + (c == null ? 10 : c.GoldenMgcQuantity) + " contracts.";
            goldenFilterNote.Text = (f.StrictFirst ? "STRICTLY THE FIRST SETUP: a setup the filters skip uses up that instrument's day (the next setup is not taken). " : "")
                + "The FVG minimum gap of Step 1 defines what counts as an FVG; here it can only be raised. "
                + (r.FilteredOut.Count == 0 ? "Nothing filtered out." : "Filtered out: " + string.Join(" • ", r.FilteredOut.OrderByDescending(k => k.Value).Select(k => k.Key + " " + k.Value)) + ".");
            goldenTiles.Children.Clear();
            foreach (var s in new[] { r.Mnq, r.Mgc, r.Both })
            {
                if (s.Label != "BOTH" && s.Entries == 0) continue;
                Brush accent = s.Label == "MNQ" ? Blue : s.Label == "MGC" ? Gold : Green;
                goldenTiles.Children.Add(HelixCard(s.Label + " • " + s.Entries + " ENTRIES", (s.Wins + s.Losses == 0 ? "–" : GPct(s.WinRate)) + "  " + Cash(s.NetCash), s.Wins + " W / " + s.Losses + " L" + (s.Open > 0 ? " / " + s.Open + " open" : "") + (s.Label == "BOTH" ? string.Empty : " • net " + KeystoneGoldenStudy.Fmt(s.Label, s.NetPoints) + " pts"), accent, 250));
            }
            var acct = r.AccountBoth;
            goldenTiles.Children.Add(HelixCard("ONE ACCOUNT • " + (r.Mnq.Entries > 0 && r.Mgc.Entries > 0 ? "MNQ + MGC" : r.Mnq.Entries > 0 ? "MNQ" : "MGC"), Cash(acct.Start) + " → " + Cash(acct.End), "max drawdown " + Cash(-acct.MaxDrawdown) + " • " + acct.Trades + " trades" + (acct.SkippedOpen > 0 ? " • " + acct.SkippedOpen + " skipped (a trade was open)" : string.Empty), MoneyBrush(acct.End - acct.Start), 300));
            goldenTiles.Children.Add(HelixCard("FILTERED OUT", (r.All.Count - r.Kept.Count) + " / " + r.All.Count, "first setups the filters removed", Orchid, 190));
            SetGoldenTab("WHICH ENTRIES", GoldenUniverseView(r));
            SetGoldenTab("MNQ • MGC • BOTH", GoldenCompareView(r));
            SetGoldenTab("WHAT MAKES WINNERS", GoldenWinnersView(r));
            SetGoldenTab("TARGET × STOP", GoldenGridView(r));
            SetGoldenTab("ONE ACCOUNT", GoldenAccountView(r, f));
            SetGoldenTab("EVERY ENTRY", GoldenEntriesView(r));
            SizeGoldenHost();
        }

        private UIElement GoldenUniverseView(KeystoneGoldenStudyResult r)
        {
            var root = new StackPanel { Margin = new Thickness(4) };
            root.Children.Add(HelixTitle("WHICH ENTRIES • the same filters on each set, one live account", Gold));
            root.Children.Add(HelixNote("FIRST SETUP = the day's first BH or FVG (Step 1 rule). FIRST BH / FIRST FVG = the first of that kind each day, even if the other came earlier. EVERY 5M FVG = every bullish FVG of the day is an entry. Every trade is held to its target or stop. ONE LIVE ACCOUNT takes them in time order with the strategy's contracts; " + (gfOneBox != null && gfOneBox.IsChecked == true ? "a new entry while that instrument still has a trade open is skipped (untick ONE TRADE OPEN to take them all)." : "every entry is taken, even while another is open.") + " The SETUP filter does not apply here (each column is one setup type). Pick a set in ENTRIES above to open it in every other tab."));
            if (goldenCompare == null || goldenCompare.Count == 0) { root.Children.Add(HelixNote("Run GOLDEN SETUP again to fill this comparison.")); return root; }
            var w = new List<double> { 300 }; var head = new List<string> { "" };
            foreach (var c in goldenCompare) { w.Add(250); head.Add(KeystoneGoldenStudy.UniverseName(c.Universe)); }
            root.Children.Add(HelixHeader(head.ToArray(), w.ToArray()));
            foreach (var row in KeystoneGoldenStudy.UniverseRows(goldenCompare))
            {
                var colors = new List<Brush> { Muted };
                for (int i = 0; i < goldenCompare.Count; i++)
                {
                    var c = goldenCompare[i];
                    Brush b = Text;
                    if (row[0].StartsWith("NET", StringComparison.Ordinal)) b = MoneyBrush(c.Both.NetCash);
                    else if (row[0].StartsWith("$ PER", StringComparison.Ordinal)) b = MoneyBrush(c.Both.CashPerEntry);
                    else if (row[0].Contains("START → END")) b = MoneyBrush(c.AccountBoth.End - c.AccountBoth.Start);
                    else if (row[0].Contains("DRAWDOWN")) b = Red;
                    else if (row[0] == "WIN RATE") b = Cyan;
                    if (c.Universe == r.Universe && b == Text) b = Gold;
                    colors.Add(b);
                }
                root.Children.Add(HelixRow(row, colors.ToArray(), w.ToArray(), Card, null));
            }
            var best = goldenCompare.Where(c => c.Kept.Count >= 20).OrderByDescending(c => c.AccountBoth.End).FirstOrDefault();
            root.Children.Add(HelixTitle(best == null ? "Fewer than 20 entries in every set — load a longer range before choosing." : "BEST ONE-ACCOUNT RESULT: " + KeystoneGoldenStudy.UniverseName(best.Universe) + " → " + Cash(best.AccountBoth.End) + " (from " + Cash(best.AccountBoth.Start) + ", max drawdown " + Cash(-best.AccountBoth.MaxDrawdown) + ")", best == null ? Gold : MoneyBrush(best.AccountBoth.End - best.AccountBoth.Start)));
            root.Children.Add(HelixNote("A set is only an edge if its win rate is above the BREAK EVEN row and it holds in each year (TARGET × STOP tab → per year)."));
            return root;
        }

        private UIElement GoldenCompareView(KeystoneGoldenStudyResult r)
        {
            var root = new StackPanel { Margin = new Thickness(4) };
            root.Children.Add(HelixTitle("MNQ vs MGC vs BOTH", Gold));
            root.Children.Add(HelixNote("Same filters, same period. Run with INSTRUMENT = BOTH in Step 1 to fill the MNQ and MGC columns together."));
            double[] w = { 300, 200, 200, 200 };
            root.Children.Add(HelixHeader(new[] { "", "MNQ", "MGC", "BOTH" }, w));
            foreach (var row in KeystoneGoldenStudy.CompareRows(r))
            {
                Brush[] colors = { Muted, Blue, Gold, Green };
                if (row[0].StartsWith("NET $", StringComparison.Ordinal) || row[0].StartsWith("$ PER", StringComparison.Ordinal))
                {
                    var s = new[] { r.Mnq, r.Mgc, r.Both };
                    for (int i = 0; i < 3; i++) colors[i + 1] = MoneyBrush(row[0].StartsWith("NET", StringComparison.Ordinal) ? s[i].NetCash : s[i].CashPerEntry);
                }
                root.Children.Add(HelixRow(row, colors, w, Card, null));
            }
            root.Children.Add(HelixTitle("WHAT MAKES THE DIFFERENCE (win rate of a group vs all entries)", Green));
            if (r.Insights.Count == 0) root.Children.Add(HelixNote("Not enough entries yet for a clear difference (each group needs at least 6 finished trades and a gap of 8+ points of win rate). Load a longer range."));
            foreach (var i in r.Insights)
                root.Children.Add(new Border { Background = Card, BorderBrush = i.Good ? Green : Red, BorderThickness = new Thickness(4, 1, 1, 1), CornerRadius = new CornerRadius(4), Margin = new Thickness(2, 1, 2, 1), Padding = new Thickness(8, 4, 8, 4),
                    Child = new TextBlock { Text = (i.Good ? "▲ " : "▼ ") + i.Text, Foreground = i.Good ? Green : Red, FontSize = 11.5, FontWeight = FontWeights.Bold, TextWrapping = TextWrapping.Wrap } });
            return root;
        }

        private UIElement GoldenWinnersView(KeystoneGoldenStudyResult r)
        {
            var root = new StackPanel { Margin = new Thickness(4) };
            root.Children.Add(HelixNote("Every kept entry grouped by one condition at a time. Win % counts finished trades (target or stop). Net $ uses the strategy's contracts. Green = better than that instrument's average, red = worse."));
            // Only the instruments that have entries get columns (BOTH only when MNQ and MGC both traded).
            var sets = new List<Tuple<string, Func<KeystoneGoldenGroup, KeystoneGoldenStats>, KeystoneGoldenStats>>();
            if (r.Mnq.Entries > 0) sets.Add(Tuple.Create("MNQ", (Func<KeystoneGoldenGroup, KeystoneGoldenStats>)(g => g.Mnq), r.Mnq));
            if (r.Mgc.Entries > 0) sets.Add(Tuple.Create("MGC", (Func<KeystoneGoldenGroup, KeystoneGoldenStats>)(g => g.Mgc), r.Mgc));
            if (r.Mnq.Entries > 0 && r.Mgc.Entries > 0) sets.Add(Tuple.Create("BOTH", (Func<KeystoneGoldenGroup, KeystoneGoldenStats>)(g => g.Both), r.Both));
            if (sets.Count == 0) { root.Children.Add(HelixNote("No entries kept by the filters.")); return root; }
            var w = new List<double> { 280 }; var head = new List<string> { "GROUP" };
            foreach (var t in sets) { w.AddRange(new double[] { 90, 90, 120 }); head.AddRange(new[] { t.Item1 + " ENTRIES", "WIN %", "NET $" }); }
            foreach (var b in r.Breakdowns)
            {
                if (b.Rows.Count == 0) continue;
                root.Children.Add(HelixTitle(b.Title, Cyan));
                root.Children.Add(HelixNote(b.Note));
                root.Children.Add(HelixHeader(head.ToArray(), w.ToArray()));
                foreach (var g in b.Rows)
                {
                    var cells = new List<string> { g.Group }; var colors = new List<Brush> { Text };
                    foreach (var t in sets)
                    {
                        var st = t.Item2(g); var all = t.Item3;
                        cells.Add(st.Entries.ToString()); colors.Add(st.Entries == 0 ? Muted : Text);
                        cells.Add(st.Wins + st.Losses == 0 ? "–" : GPct(st.WinRate)); colors.Add(st.Wins + st.Losses == 0 ? Muted : (st.WinRate >= all.WinRate + 5 ? Green : (st.WinRate <= all.WinRate - 5 ? Red : Text)));
                        cells.Add(st.Entries == 0 ? "–" : Cash(st.NetCash)); colors.Add(MoneyBrush(st.NetCash));
                    }
                    var main = sets[sets.Count - 1].Item2(g);
                    root.Children.Add(HelixRow(cells.ToArray(), colors.ToArray(), w.ToArray(), main.NetCash > 0 ? Green : (main.NetCash < 0 ? Red : Card), null));
                }
            }
            return root;
        }

        private UIElement GoldenGridView(KeystoneGoldenStudyResult r)
        {
            var root = new StackPanel { Margin = new Thickness(4) };
            root.Children.Add(HelixNote("Every kept entry replayed on its own 1-minute path with a fixed stop (rows, points below the entry) or the pattern stop (last row) and a target (columns, points above). Each cell: win % and net $ for one account with the strategy's contracts, held until the target or the stop. The gold cell is your Step 1 setting; the green outline is the best cell."));
            if (r.Grids.Count == 0) { root.Children.Add(HelixNote("No entries with a 1-minute path yet.")); return root; }
            // best per year
            root.Children.Add(HelixTitle("BEST TARGET / STOP PER YEAR (volatility changes)", Gold));
            double[] bw = { 130, 70, 110, 110, 70, 110, 140 };
            root.Children.Add(HelixHeader(new[] { "INSTRUMENT", "ENTRIES", "BEST TARGET", "BEST STOP", "WIN %", "BEST NET", "YOUR SETTING NET" }, bw));
            foreach (var g in r.Grids)
            {
                if (g.Best == null) continue;
                string[] cells = { g.Symbol + " • " + (g.Year == "ALL" ? "ALL YEARS" : g.Year), g.Entries.ToString(), "+" + KeystoneGoldenStudy.Fmt(g.Symbol, g.Best.Target), g.Best.Pattern ? "PATTERN" : "−" + KeystoneGoldenStudy.Fmt(g.Symbol, g.Best.Stop), GPct(g.Best.WinRate), Cash(g.Best.NetCash), g.Yours == null ? "–" : Cash(g.Yours.NetCash) };
                Brush[] colors = { g.Symbol == "MNQ" ? Blue : Gold, Muted, Cyan, Cyan, Text, MoneyBrush(g.Best.NetCash), g.Yours == null ? Muted : MoneyBrush(g.Yours.NetCash) };
                root.Children.Add(HelixRow(cells, colors, bw, g.Year == "ALL" ? Gold : Card, null));
            }
            // one grid at a time
            var pick = Select(r.Grids.Select(g => g.Symbol + " • " + (g.Year == "ALL" ? "ALL YEARS" : g.Year) + " • " + g.Entries + " entries").ToArray());
            pick.Width = 320; pick.HorizontalAlignment = HorizontalAlignment.Left;
            var gridHost = new StackPanel();
            Action draw = delegate
            {
                gridHost.Children.Clear();
                int idx = Math.Max(0, Math.Min(r.Grids.Count - 1, pick.SelectedIndex));
                goldenGridIndex = idx;
                gridHost.Children.Add(GoldenGridTable(r.Grids[idx]));
            };
            pick.SelectedIndex = Math.Max(0, Math.Min(r.Grids.Count - 1, goldenGridIndex));
            pick.SelectionChanged += delegate { draw(); };
            root.Children.Add(HelixTitle("TARGET × STOP TABLE", Cyan));
            root.Children.Add(Row("SHOW", pick));
            root.Children.Add(gridHost);
            draw();
            return root;
        }

        private UIElement GoldenGridTable(KeystoneGoldenGrid g)
        {
            var table = new Grid { Margin = new Thickness(2, 4, 2, 4), HorizontalAlignment = HorizontalAlignment.Left };
            table.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(96) });
            foreach (double t in g.Targets) table.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(84) });
            for (int s = 0; s <= g.Stops.Length + 1; s++) table.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            Action<UIElement, int, int> put = (el, row, col) => { Grid.SetRow(el, row); Grid.SetColumn(el, col); table.Children.Add(el); };
            put(new TextBlock { Text = "STOP \\ TARGET", Foreground = Gold, FontSize = 10, FontWeight = FontWeights.Bold, Margin = new Thickness(4) }, 0, 0);
            for (int t = 0; t < g.Targets.Length; t++) put(new TextBlock { Text = "+" + KeystoneGoldenStudy.Fmt(g.Symbol, g.Targets[t]), Foreground = Green, FontSize = 11, FontWeight = FontWeights.Bold, Margin = new Thickness(4), HorizontalAlignment = HorizontalAlignment.Center }, 0, t + 1);
            double maxAbs = 1; foreach (var c in g.Cells) if (c != null) maxAbs = Math.Max(maxAbs, Math.Abs(c.NetCash));
            for (int s = 0; s <= g.Stops.Length; s++)
            {
                put(new TextBlock { Text = s == g.Stops.Length ? "PATTERN" : "−" + KeystoneGoldenStudy.Fmt(g.Symbol, g.Stops[s]), Foreground = Red, FontSize = 11, FontWeight = FontWeights.Bold, Margin = new Thickness(4), VerticalAlignment = VerticalAlignment.Center }, s + 1, 0);
                for (int t = 0; t < g.Targets.Length; t++)
                {
                    var c = g.Cells[s, t];
                    bool yours = c == g.Yours, best = c == g.Best;
                    var cell = new Border
                    {
                        Background = Card, BorderBrush = yours ? Gold : (best ? Green : Panel), BorderThickness = new Thickness(yours || best ? 2.5 : 1), CornerRadius = new CornerRadius(3), Margin = new Thickness(1), Padding = new Thickness(2, 3, 2, 3),
                        ToolTip = "stop " + (c.Pattern ? "below the pattern" : KeystoneGoldenStudy.Fmt(g.Symbol, c.Stop) + " pts") + " • target +" + KeystoneGoldenStudy.Fmt(g.Symbol, c.Target) + " pts\n" + c.Wins + " wins • " + c.Losses + " losses" + (c.Open > 0 ? " • " + c.Open + " still open" : "") + "\nnet " + KeystoneGoldenStudy.Fmt(g.Symbol, c.NetPoints) + " pts = " + Cash(c.NetCash) + (yours ? "\nYOUR STEP 1 SETTING" : "") + (best ? "\nBEST CELL" : "")
                    };
                    var st = new StackPanel();
                    st.Children.Add(new TextBlock { Text = c.Wins + c.Losses == 0 ? "–" : GPct(c.WinRate), Foreground = Text, FontSize = 10, HorizontalAlignment = HorizontalAlignment.Center });
                    st.Children.Add(new TextBlock { Text = Cash(c.NetCash), Foreground = MoneyBrush(c.NetCash), FontSize = 11, FontWeight = FontWeights.Bold, HorizontalAlignment = HorizontalAlignment.Center, Opacity = 0.55 + 0.45 * Math.Abs(c.NetCash) / maxAbs });
                    cell.Child = st;
                    put(cell, s + 1, t + 1);
                }
            }
            var wrap = new StackPanel();
            if (g.Entries < 30) wrap.Children.Add(new TextBlock { Text = "ONLY " + g.Entries + " ENTRIES • too few to trust the best cell (one or two trades decide it). Use a longer range or fewer filters.", Foreground = Red, FontSize = 11, FontWeight = FontWeights.Bold, Margin = new Thickness(6, 2, 6, 2), TextWrapping = TextWrapping.Wrap });
            wrap.Children.Add(HelixNote(g.Symbol + " • " + (g.Year == "ALL" ? "all years" : g.Year) + " • " + g.Entries + " entries" + (g.Best == null ? "" : " • best: +" + KeystoneGoldenStudy.Fmt(g.Symbol, g.Best.Target) + " / " + (g.Best.Pattern ? "pattern stop" : "−" + KeystoneGoldenStudy.Fmt(g.Symbol, g.Best.Stop)) + " = " + Cash(g.Best.NetCash)) + (g.Yours == null ? "" : " • your setting = " + Cash(g.Yours.NetCash))));
            wrap.Children.Add(table);
            return wrap;
        }

        private UIElement GoldenAccountView(KeystoneGoldenStudyResult r, KeystoneGoldenFilter f)
        {
            var root = new StackPanel { Margin = new Thickness(4) };
            root.Children.Add(HelixNote("One plain trading account: start " + Cash(f.StartBalance) + " + every kept entry's own result with the strategy's contracts (MNQ " + (goldenStudyConfig == null ? 5 : goldenStudyConfig.GoldenMnqQuantity) + ", MGC " + (goldenStudyConfig == null ? 10 : goldenStudyConfig.GoldenMgcQuantity) + "). No evaluation, payout or prop rule. " + (f.OnePositionPerInstrument ? "One trade open per instrument: a new setup while the last one is still open (held overnight) is skipped; MNQ and MGC can be open together." : "Every entry is taken, even while another is open.")));
            var cards = new WrapPanel();
            foreach (var t in new[] { Tuple.Create("MNQ", r.AccountMnq, Blue), Tuple.Create("MGC", r.AccountMgc, Gold), Tuple.Create("BOTH", r.AccountBoth, Green) })
            {
                var a = t.Item2; if (a.Trades == 0 && t.Item1 != "BOTH") continue;
                cards.Children.Add(HelixCard(t.Item1 + " ACCOUNT", Cash(a.Start) + " → " + Cash(a.End), a.Trades + " trades • " + a.Wins + " W / " + a.Losses + " L" + (a.Open > 0 ? " / " + a.Open + " open" : "") + " • max drawdown " + Cash(-a.MaxDrawdown) + " (" + a.MaxDrawdownPercent.ToString("0.#", CultureInfo.InvariantCulture) + "%)" + (a.SkippedOpen > 0 ? " • skipped " + a.SkippedOpen : ""), t.Item3, 330));
            }
            root.Children.Add(cards);
            root.Children.Add(HelixTitle("BALANCE AFTER EVERY CLOSED TRADE", Cyan));
            root.Children.Add(GoldenEquityChart(r));
            root.Children.Add(HelixTitle("MONTHS", Gold));
            double[] w = { 120, 110, 80, 110, 80, 200, 80 };
            root.Children.Add(HelixHeader(new[] { "MONTH", "MNQ", "W / L", "MGC", "W / L", "BOTH", "W / L" }, w));
            // Every month of the tested range, also the ones with no kept trade (shown as NO TRADES).
            var months = new List<DateTime>();
            var c0 = goldenStudyConfig ?? config;
            DateTime m0 = r.All.Count > 0 ? r.All.Min(e => e.TriggerTime) : (c0 == null ? DateTime.Today : c0.Start);
            DateTime m1 = r.All.Count > 0 ? r.All.Max(e => e.ExitTime == DateTime.MinValue ? e.TriggerTime : e.ExitTime) : m0;
            if (c0 != null && c0.Start > DateTime.MinValue.AddYears(1) && c0.Start < m0) m0 = c0.Start;
            if (c0 != null && c0.End < DateTime.MaxValue.AddYears(-1) && c0.End > m1) m1 = c0.End;
            for (DateTime m = new DateTime(m0.Year, m0.Month, 1); m <= m1 && months.Count < 600; m = m.AddMonths(1)) months.Add(m);
            foreach (var m in months)
            {
                Func<KeystoneGoldenAccount, Tuple<DateTime, double, int, int>> at = a => a.Months.FirstOrDefault(x => x.Item1 == m);
                var q = at(r.AccountMnq); var g = at(r.AccountMgc); var b = at(r.AccountBoth);
                int found = r.All.Count(e => e.TriggerTime.Year == m.Year && e.TriggerTime.Month == m.Month), kept = r.Kept.Count(e => e.TriggerTime.Year == m.Year && e.TriggerTime.Month == m.Month);
                string none = found == 0 ? "NO SETUP FOUND" : (kept == 0 ? "ALL " + found + " FILTERED OUT" : "–");
                string[] cells = { m.ToString("MMM yyyy", CultureInfo.InvariantCulture), q == null ? "–" : Cash(q.Item2), q == null ? "" : q.Item3 + " / " + q.Item4, g == null ? "–" : Cash(g.Item2), g == null ? "" : g.Item3 + " / " + g.Item4, b == null ? none : Cash(b.Item2), b == null ? "" : b.Item3 + " / " + b.Item4 };
                Brush[] colors = { Text, q == null ? Muted : MoneyBrush(q.Item2), Muted, g == null ? Muted : MoneyBrush(g.Item2), Muted, b == null ? Muted : MoneyBrush(b.Item2), Muted };
                if (b == null) colors[5] = Muted;
                root.Children.Add(HelixRow(cells, colors, w, b == null ? Card : (b.Item2 >= 0 ? Green : Red), null));
            }
            return root;
        }

        private UIElement GoldenEquityChart(KeystoneGoldenStudyResult r)
        {
            double width = 900, height = 220, padL = 70, padR = 12, padT = 10, padB = 24;
            var canvas = new Canvas { Width = width, Height = height, Background = Card, HorizontalAlignment = HorizontalAlignment.Left, Margin = new Thickness(2) };
            var series = new[] { Tuple.Create(r.AccountMnq, (Brush)Blue, "MNQ"), Tuple.Create(r.AccountMgc, (Brush)Gold, "MGC"), Tuple.Create(r.AccountBoth, (Brush)Green, "BOTH") }.Where(s => s.Item1.Trades > 0).ToList();
            if (series.Count == 0) { canvas.Children.Add(new TextBlock { Text = "No trades.", Foreground = Muted, Margin = new Thickness(10) }); return canvas; }
            var pts = series.SelectMany(s => s.Item1.Equity.Where(e => e.Item1 != DateTime.MinValue)).ToList();
            DateTime t0 = pts.Min(p => p.Item1), t1 = pts.Max(p => p.Item1); if (t1 <= t0) t1 = t0.AddDays(1);
            double lo = series.Min(s => s.Item1.Equity.Min(e => e.Item2)), hi = series.Max(s => s.Item1.Equity.Max(e => e.Item2)); if (hi - lo < 1) { hi += 1; lo -= 1; }
            Func<DateTime, double> X = t => padL + (width - padL - padR) * (t - t0).TotalSeconds / (t1 - t0).TotalSeconds;
            Func<double, double> Y = v => padT + (height - padT - padB) * (hi - v) / (hi - lo);
            for (int k = 0; k <= 4; k++)
            {
                double v = lo + (hi - lo) * k / 4.0;
                var tb = new TextBlock { Text = Cash(v), Foreground = Muted, FontSize = 9 }; Canvas.SetLeft(tb, 4); Canvas.SetTop(tb, Y(v) - 7); canvas.Children.Add(tb);
                canvas.Children.Add(new System.Windows.Shapes.Line { X1 = padL, X2 = width - padR, Y1 = Y(v), Y2 = Y(v), Stroke = Panel, StrokeThickness = 1 });
            }
            double start = series[0].Item1.Start;
            canvas.Children.Add(new System.Windows.Shapes.Line { X1 = padL, X2 = width - padR, Y1 = Y(start), Y2 = Y(start), Stroke = Muted, StrokeThickness = 1, StrokeDashArray = new DoubleCollection { 4, 3 } });
            foreach (var s in series)
            {
                var line = new System.Windows.Shapes.Polyline { Stroke = s.Item2, StrokeThickness = 2, Points = new PointCollection() };
                double prevY = Y(s.Item1.Start);
                line.Points.Add(new Point(padL, prevY));
                foreach (var e in s.Item1.Equity.Where(e => e.Item1 != DateTime.MinValue)) { line.Points.Add(new Point(X(e.Item1), prevY)); prevY = Y(e.Item2); line.Points.Add(new Point(X(e.Item1), prevY)); }
                canvas.Children.Add(line);
            }
            double lx = padL + 6;
            foreach (var s in series) { var tb = new TextBlock { Text = "■ " + s.Item3 + " " + Cash(s.Item1.End), Foreground = s.Item2, FontSize = 10, FontWeight = FontWeights.Bold }; Canvas.SetLeft(tb, lx); Canvas.SetTop(tb, padT); canvas.Children.Add(tb); lx += 130; }
            var a = new TextBlock { Text = t0.ToString("MMM d, yyyy", CultureInfo.InvariantCulture), Foreground = Muted, FontSize = 9 }; Canvas.SetLeft(a, padL); Canvas.SetTop(a, height - 16); canvas.Children.Add(a);
            var z = new TextBlock { Text = t1.ToString("MMM d, yyyy", CultureInfo.InvariantCulture), Foreground = Muted, FontSize = 9 }; Canvas.SetLeft(z, width - padR - 70); Canvas.SetTop(z, height - 16); canvas.Children.Add(z);
            return canvas;
        }

        private UIElement GoldenEntriesView(KeystoneGoldenStudyResult r)
        {
            var root = new StackPanel { Margin = new Thickness(4) };
            root.Children.Add(HelixNote("Every first setup the detector found (and the next tries after a loss). Grey rows were removed by the filters, with the reason. RUN UP = best points above the entry before the exit • DIP = worst points below the entry before the exit. Click a row to open that day on the chart."));
            double[] w = { 112, 50, 46, 70, 38, 64, 40, 54, 84, 60, 150, 70, 90, 62, 56, 96, 170 };
            string[] head = { "DAY", "TIME", "INST", "SETUP", "TRY", "PUSH", "RED", "GAP", "ENTRY", "STOP", "RESULT", "PTS", "$", "RUN UP", "DIP", "EXIT", "FILTERED OUT BECAUSE" };
            var rows = r.All;
            root.Children.Add(HelixPaged(head, w, rows.Count, i =>
            {
                var e = rows[i]; string why; r.Reasons.TryGetValue(e, out why); bool kept = string.IsNullOrEmpty(why);
                DateTime t = e.EntryTime == DateTime.MinValue ? e.TriggerTime : e.EntryTime;
                string sym = e.Symbol ?? string.Empty;
                bool win = KeystoneGoldenStudy.IsWin(e), loss = KeystoneGoldenStudy.IsLoss(e);
                string[] cells =
                {
                    KeystoneArcEngine.GoldenSessionDay(t).ToString("yyyy-MM-dd ddd", CultureInfo.InvariantCulture), t.ToString("HH:mm"), sym, e.SetupClass == "DT" ? "BH+FVG" : e.SetupClass, e.SessionOrder.ToString(),
                    KeystoneGoldenStudy.Fmt(sym, e.FvgDrop), e.FvgRedRun.ToString(), e.SetupClass == "BH" ? "–" : KeystoneGoldenStudy.Fmt(sym, e.FvgGap), KeystoneGoldenStudy.Fmt(sym, e.Entry), KeystoneGoldenStudy.Fmt(sym, KeystoneGoldenStudy.StopPoints(e)),
                    KeystoneGoldenStudy.OutcomeText(e, r.Hold), KeystoneGoldenStudy.Fmt(sym, KeystoneGoldenStudy.Points(e)), Cash(e.GrossPnl),
                    double.IsNaN(e.PeakAfterEntry) ? "–" : KeystoneGoldenStudy.Fmt(sym, e.PeakAfterEntry - e.Entry), double.IsNaN(e.TroughAfterEntry) ? "–" : KeystoneGoldenStudy.Fmt(sym, e.Entry - e.TroughAfterEntry),
                    e.ExitTime == DateTime.MinValue ? "–" : e.ExitTime.ToString("MM-dd HH:mm"), why ?? string.Empty
                };
                Brush res = win ? Green : (loss ? Red : Cyan);
                Brush[] colors = cells.Select(x => kept ? Text : Muted).ToArray();
                if (kept) { colors[2] = sym == "MGC" ? Gold : Blue; colors[10] = res; colors[11] = MoneyBrush(KeystoneGoldenStudy.Points(e)); colors[12] = MoneyBrush(e.GrossPnl); }
                colors[16] = Orchid;
                var row = HelixRow(cells, colors, w, kept ? res : Panel, () => OpenGoldenEntryChart(e));
                if (!kept) row.Opacity = 0.62;
                return row;
            }, 60, false));
            return root;
        }

        private void OpenGoldenEntryChart(KeystoneArcEvent e)
        {
            if (events.Count == 0 && goldenStudyAll.Count == 0) { UpdateUi("RUN GOLDEN SETUP FIRST", Gold); return; }
            if (e != null && reviewList != null)
            {
                int idx = reviewRows.FindIndex(x => x.TriggerTime == e.TriggerTime && string.Equals(x.Symbol, e.Symbol, StringComparison.OrdinalIgnoreCase));
                if (idx >= 0) reviewList.SelectedIndex = idx;
            }
            if (e != null && evidenceWindow != null && evidenceWindow.IsVisible)
            {
                SelectEvidenceSessionDate(KeystoneArcEngine.SessionGroupingDate(e.TriggerTime, config).ToString("yyyy-MM-dd"), true);
                evidenceWindow.Activate(); return;
            }
            OpenEvidenceChart();
        }

        private void ExportGoldenStudy()
        {
            if (goldenStudy == null) { UpdateUi("RUN GOLDEN SETUP FIRST", Gold); return; }
            try
            {
                string dir = DataDirectory(); Directory.CreateDirectory(dir);
                string stamp = DateTime.Now.ToString("yyyyMMdd_HHmmss");
                var c = goldenStudyConfig ?? config;
                string title = (c == null ? "" : c.Scope + " • " + c.Start.ToString("yyyy-MM-dd") + " → " + c.End.ToString("yyyy-MM-dd") + " • start MNQ " + c.GoldenMnqStart.ToString("0000") + " / MGC " + c.GoldenMgcStart.ToString("0000") + " • target MNQ +" + c.GoldenMnqTargetPoints.ToString("0.##", CultureInfo.InvariantCulture) + " / MGC +" + c.GoldenMgcTargetPoints.ToString("0.##", CultureInfo.InvariantCulture)) + " • generated " + DateTime.Now.ToString("yyyy-MM-dd HH:mm");
                string html = Path.Combine(dir, "KeystoneArc_Golden_Study_" + stamp + ".html");
                string csv = Path.Combine(dir, "KeystoneArc_Golden_Entries_" + stamp + ".csv");
                File.WriteAllText(html, KeystoneGoldenStudy.Html(goldenStudy, ReadGoldenFilter(), title, goldenCompare), Encoding.UTF8);
                File.WriteAllText(csv, KeystoneGoldenStudy.Csv(goldenStudy), Encoding.UTF8);
                UpdateUi("EXPORTED GOLDEN STUDY • " + html + " • entries CSV " + csv, Green);
            }
            catch (Exception ex) { UpdateUi("GOLDEN EXPORT ERROR • " + ex.Message, Red); }
        }

        // ---- Step 3 HELIX view -------------------------------------------------------------------
        private void SetHelixResultsMode(bool on)
        {
            if (helixResultsHost == null) return;
            if (on && !helixResultsMode && oneDayPoolMetrics != null) oneDayMetricsVisibilityBeforeHelix = oneDayPoolMetrics.Visibility;
            helixResultsMode = on;
            Visibility normal = on ? Visibility.Collapsed : Visibility.Visible;
            helixResultsHost.Visibility = on ? Visibility.Visible : Visibility.Collapsed;
            if (poolLifecycleMetrics != null) poolLifecycleMetrics.Visibility = normal;
            if (oneDayPoolMetrics != null) oneDayPoolMetrics.Visibility = on ? Visibility.Collapsed : oneDayMetricsVisibilityBeforeHelix;
            if (resultViewTabs != null) resultViewTabs.Visibility = normal;
            if (normalResultActions != null) normalResultActions.Visibility = normal;
            if (normalResultClearRow != null) normalResultClearRow.Visibility = normal;
            if (poolResultBanner != null) poolResultBanner.Visibility = normal;
            if (instrumentSplitText != null && on) instrumentSplitText.Visibility = Visibility.Collapsed;
            if (resultsHeadingText != null) resultsHeadingText.Text = on ? "HELIX ROTATION • RESULTS" : "PROP VIRTUAL-POOL RESULTS • ALL ELIGIBLE SETUPS";
            SizeHelixHost();
        }

        // The HELIX view is exactly one window tall: its tab strip is always on screen and only the
        // inside of a tab scrolls.
        private void SizeHelixHost()
        {
            if (helixResultsHost == null || !helixResultsMode) return;
            double page = resultsPageScroll == null ? 0 : resultsPageScroll.ActualHeight, top = resultsTopPanel == null ? 0 : resultsTopPanel.ActualHeight;
            helixResultsHost.Height = page > 200 ? Math.Max(420, page - top - 18) : 640;
        }

        private UIElement BuildHelixResultsHost()
        {
            var g = new Grid { Visibility = Visibility.Collapsed };
            for (int i = 0; i < 3; i++) g.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            g.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            // verdict + actions
            var head = new Grid(); head.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) }); head.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            var verdictStack = new StackPanel();
            helixVerdictHead = new TextBlock { Text = "RUN HELIX", Foreground = Gold, FontSize = 22, FontWeight = FontWeights.Bold };
            helixVerdictSub = new TextBlock { Text = "Choose HELIX ROTATION in Step 1 and press START.", Foreground = Text, FontSize = 11, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 2, 0, 0) };
            helixWarningText = new TextBlock { Text = string.Empty, Foreground = Gold, FontSize = 10, FontWeight = FontWeights.Bold, TextWrapping = TextWrapping.Wrap, Visibility = Visibility.Collapsed };
            verdictStack.Children.Add(helixVerdictHead); verdictStack.Children.Add(helixVerdictSub); verdictStack.Children.Add(helixWarningText);
            head.Children.Add(verdictStack);
            var actions = new UniformGrid { Columns = 2, Margin = new Thickness(8, 0, 0, 0), Width = 430 };
            helixRerunButton = Btn("RE-RUN WITH STEP 1 SETTINGS", Green); helixRerunButton.ToolTip = "Reads the HELIX settings in Step 1 again and re-runs on the bars already loaded (no reload).";
            helixProofButton = Btn("RUN PROOF TESTS", Orchid); helixProofButton.ToolTip = "BUY/SELL/RANDOM directions, instruments, fills, costs, halves of the period, start times, pauses and account counts.";
            helixChartButton = Btn("BASKETS ON THE CHART", Blue);
            helixReportButton = Btn("EXPORT REPORT", Gold);
            foreach (var b in new[] { helixRerunButton, helixProofButton, helixChartButton, helixReportButton }) { b.Height = 30; b.FontSize = 11; actions.Children.Add(b); }
            helixRerunButton.Click += delegate { RunHelix(); };
            helixProofButton.Click += delegate { RunHelixProof(); };
            helixChartButton.Click += delegate { OpenHelixChart(null); };
            helixReportButton.Click += delegate { ExportHelixReport(); };
            Grid.SetColumn(actions, 1); head.Children.Add(actions);
            helixVerdictCard = new Border { Background = Card, BorderBrush = Gold, BorderThickness = new Thickness(5, 1.5, 1.5, 1.5), CornerRadius = new CornerRadius(6), Padding = new Thickness(12, 8, 10, 8), Margin = new Thickness(2, 2, 2, 4), Child = head };
            g.Children.Add(helixVerdictCard);
            var tiles = new UniformGrid { Columns = 6, Margin = new Thickness(0, 0, 0, 2) };
            helixCashTile = MetricTile(tiles, "CASH IN", "$0", "your share of every payout", Green, 58, 19);
            helixSpentTile = MetricTile(tiles, "SPENT ON ACCOUNTS", "$0", "every account bought", Red, 58, 19);
            helixAccountsTile = MetricTile(tiles, "ACCOUNTS", "0", "bought • liquidated • paid", Orchid, 58, 19);
            helixBasketTile = MetricTile(tiles, "BASKETS WON", "0%", "vs the win rate needed", Cyan, 58, 19);
            helixTradingTile = MetricTile(tiles, "TRADING P/L", "$0", "MNQ + MGC, all accounts", Blue, 58, 19);
            helixLowTile = MetricTile(tiles, "MONEY NEEDED", "$0", "deepest point of your cash", Gold, 58, 19);
            Grid.SetRow(tiles, 1); g.Children.Add(tiles);
            helixTabs = new TabControl { Background = Panel, BorderBrush = Orchid, BorderThickness = new Thickness(1), Margin = new Thickness(0, 2, 0, 0), TabStripPlacement = Dock.Top, VerticalContentAlignment = VerticalAlignment.Stretch, HorizontalContentAlignment = HorizontalAlignment.Stretch };
            Brush[] tabColors = { Cyan, Blue, Gold, Green, Red, Orchid, Orchid, Green, Gold };
            string[] tabNames = { "OVERVIEW", "BASKETS", "DAYS & TIMES", "ACCOUNTS & PAYOUTS", "EXPENSES & CASH", "THE MATH", "PROOF TESTS", "SETUP FINDER", "MANUS CHECK" };
            for (int i = 0; i < tabNames.Length; i++)
                helixTabs.Items.Add(new TabItem { Header = tabNames[i], Background = tabColors[i], Foreground = Bg, FontWeight = FontWeights.Bold, Content = Txt("Run HELIX to fill this tab.", Muted, 11, FontWeights.Normal) });
            Grid.SetRow(helixTabs, 3); g.Children.Add(helixTabs);
            helixResultsHost = g;
            return g;
        }

        // Card, table and page helpers (same look as the other result tabs).
        private static Border HelixCard(string title, string value, string sub, Brush accent, double width)
        {
            var st = new StackPanel { Margin = new Thickness(2) };
            st.Children.Add(new TextBlock { Text = title, Foreground = accent, FontSize = 9.5, FontWeight = FontWeights.Bold, TextWrapping = TextWrapping.Wrap });
            st.Children.Add(new TextBlock { Text = value, Foreground = accent, FontSize = 18, FontWeight = FontWeights.Bold, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 1, 0, 1) });
            if (!string.IsNullOrEmpty(sub)) st.Children.Add(new TextBlock { Text = sub, Foreground = Text, FontSize = 9.5, TextWrapping = TextWrapping.Wrap, Opacity = 0.85 });
            return new Border { Background = Card, BorderBrush = accent, BorderThickness = new Thickness(1.5), CornerRadius = new CornerRadius(6), Padding = new Thickness(8, 5, 8, 6), Margin = new Thickness(3), Width = width, Child = st };
        }

        private static TextBlock HelixTitle(string text, Brush brush)
        {
            return new TextBlock { Text = text, Foreground = brush, FontSize = 13, FontWeight = FontWeights.Bold, Margin = new Thickness(4, 10, 4, 3), TextWrapping = TextWrapping.Wrap };
        }

        private static TextBlock HelixNote(string text) { return new TextBlock { Text = text, Foreground = Muted, FontSize = 10, Margin = new Thickness(6, 0, 6, 4), TextWrapping = TextWrapping.Wrap }; }

        private static ScrollViewer HelixScroll(UIElement content) { return new ScrollViewer { VerticalScrollBarVisibility = ScrollBarVisibility.Auto, HorizontalScrollBarVisibility = ScrollBarVisibility.Auto, Content = content, Padding = new Thickness(4) }; }

        private Border HelixRow(string[] cells, Brush[] colors, double[] widths, Brush accent, Action onClick)
        {
            var row = new Border { Background = Panel, BorderBrush = accent, BorderThickness = new Thickness(4, 1, 1, 1), CornerRadius = new CornerRadius(4), Margin = new Thickness(2, 1, 2, 1), Child = TableRow(cells, colors, widths, false) };
            if (onClick != null) { row.Cursor = System.Windows.Input.Cursors.Hand; row.ToolTip = "Click to open this day on the chart"; row.MouseLeftButtonUp += delegate { onClick(); }; }
            return row;
        }

        private UIElement HelixHeader(string[] head, double[] widths) { return TableRow(head, head.Select(h => (Brush)Gold).ToArray(), widths, true); }

        // A table of any length shown one page at a time (fast even with thousands of rows).
        private UIElement HelixPaged(string[] head, double[] widths, int count, Func<int, Border> row, int pageSize, bool startAtEnd)
        {
            var wrap = new StackPanel();
            var body = new StackPanel();
            int pages = Math.Max(1, (count + pageSize - 1) / pageSize);
            int page = startAtEnd ? pages - 1 : 0;
            var label = new TextBlock { Foreground = Cyan, FontSize = 10.5, FontWeight = FontWeights.Bold, Margin = new Thickness(10, 7, 6, 0) };
            var first = Btn("⏮", Card); var prev = Btn("◀ PREVIOUS", Card); var next = Btn("NEXT ▶", Card); var last = Btn("⏭", Card);
            foreach (var b in new[] { first, prev, next, last }) { b.Height = 26; b.FontSize = 10; b.Padding = new Thickness(10, 0, 10, 0); }
            Action draw = null;
            draw = delegate
            {
                body.Children.Clear(); body.Children.Add(HelixHeader(head, widths));
                int a = page * pageSize, z = Math.Min(count, a + pageSize);
                for (int i = a; i < z; i++) body.Children.Add(row(i));
                label.Text = count == 0 ? "NO ROWS" : "ROWS " + (a + 1).ToString("N0") + "–" + z.ToString("N0") + " OF " + count.ToString("N0") + " • PAGE " + (page + 1) + " / " + pages;
                first.IsEnabled = prev.IsEnabled = page > 0; next.IsEnabled = last.IsEnabled = page < pages - 1;
            };
            first.Click += delegate { page = 0; draw(); }; prev.Click += delegate { if (page > 0) { page--; draw(); } };
            next.Click += delegate { if (page < pages - 1) { page++; draw(); } }; last.Click += delegate { page = pages - 1; draw(); };
            if (pages > 1) { var nav = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(2, 2, 2, 2) }; nav.Children.Add(first); nav.Children.Add(prev); nav.Children.Add(next); nav.Children.Add(last); nav.Children.Add(label); wrap.Children.Add(nav); }
            else wrap.Children.Add(label);
            wrap.Children.Add(body);
            draw();
            return wrap;
        }

        private static Brush MoneyBrush(double v) { return v > 0 ? Green : (v < 0 ? Red : Muted); }

        private void RenderHelixResults()
        {
            var r = helixResult; if (r == null || helixTabs == null) return;
            var c = r.Config;
            double be = KeystoneHelix.BreakEvenWinRate(r);
            bool profit = r.NetCash > 0;
            int months = Math.Max(1, KeystoneHelix.Months(r).Count);
            int paid = r.Lives.Count(l => l.Payouts > 0);
            helixVerdictHead.Text = (r.Rotations.Count == 0 ? "NO BASKETS" : profit ? "PROFITABLE  •  " : "NOT PROFITABLE  •  ") + (r.Rotations.Count == 0 ? string.Empty : (r.NetCash > 0 ? "+" : string.Empty) + Cash(r.NetCash));
            helixVerdictHead.Foreground = r.Rotations.Count == 0 ? Gold : (profit ? Green : Red);
            helixVerdictCard.BorderBrush = helixVerdictHead.Foreground;
            helixVerdictSub.Text = r.Rotations.Count == 0 ? HelixVerdict(r)
                : r.Days.Count + " sessions (" + r.Days[0].Day.ToString("MMM d, yyyy", CultureInfo.InvariantCulture) + " → " + r.Days[r.Days.Count - 1].Day.ToString("MMM d, yyyy", CultureInfo.InvariantCulture) + ") • about " + Cash(r.NetCash / months) + " a month • " + r.Lives.Count + " accounts bought, " + r.FundedBlowups + " liquidated, " + paid + " ever paid • baskets won " + Pct(r.WinRate) + " (need " + Pct(be) + ")"
                  + (r.TradingNet <= 0 && profit ? " • the trades lost: the profit comes from the payout rules" : string.Empty) + " • press RUN PROOF TESTS before trusting it.";
            var warn = new List<string>();
            if (r.SkippedDays.Count > 0) warn.Add("⚠ " + r.SkippedDays.Count + " day(s) not traded because MNQ or MGC data is missing: " + string.Join(" | ", r.SkippedDays.Take(4)) + (r.SkippedDays.Count > 4 ? " …" : string.Empty));
            if (r.Days.Count > 0 && r.Days.Count < 60) warn.Add("⚠ only " + r.Days.Count + " sessions: too short to judge — test at least a year.");
            helixWarningText.Text = string.Join("\n", warn); helixWarningText.Visibility = warn.Count > 0 ? Visibility.Visible : Visibility.Collapsed;
            UpdateMetricTile(helixCashTile, "CASH IN • " + r.Payouts.Count + " PAYOUTS", Cash(r.PayoutCash), "gross " + Cash(r.PayoutGross) + " • you keep " + N0(c.PayoutSplit) + "%", Green);
            UpdateMetricTile(helixSpentTile, "SPENT • " + r.Lives.Count + " ACCOUNTS", Cash(r.ExpenseTotal), "first " + Math.Min(r.Lives.Count, c.Accounts) + " + " + Math.Max(0, r.Lives.Count - c.Accounts) + " replacements", Red);
            UpdateMetricTile(helixAccountsTile, "ACCOUNTS BLOWN / PAID", r.FundedBlowups + r.EvalFails + " / " + paid, (c.StartMode == "EVAL" ? r.EvalPasses + " evaluations passed • " : string.Empty) + r.Lives.Count(l => l.Status == "FUNDED") + " funded at the end", Orchid);
            UpdateMetricTile(helixBasketTile, "BASKETS WON", Pct(r.WinRate), r.Wins + " W / " + r.Losses + " L • need " + Pct(be), r.WinRate > be ? Green : Red);
            UpdateMetricTile(helixTradingTile, "TRADING P/L", Cash(r.TradingNet), "MNQ " + Cash(r.Rotations.Sum(x => x.MnqPnl)) + " • MGC " + Cash(r.Rotations.Sum(x => x.MgcPnl)), MoneyBrush(r.TradingNet));
            UpdateMetricTile(helixLowTile, "MONEY NEEDED", Cash(-r.LowestCash()), r.FirstPayout == DateTime.MinValue ? "no payout yet" : "first payout " + r.FirstPayout.ToString("MMM d", CultureInfo.InvariantCulture), Gold);
            SetHelixTab("OVERVIEW", HelixOverview(r));
            SetHelixTab("BASKETS", HelixBasketsView(r, "ALL"));
            SetHelixTab("DAYS & TIMES", HelixDaysView(r));
            SetHelixTab("ACCOUNTS & PAYOUTS", HelixAccountsView(r));
            SetHelixTab("EXPENSES & CASH", HelixExpensesView(r));
            SetHelixTab("THE MATH", HelixMathView(r));
            SetHelixTab("PROOF TESTS", HelixProofView());
            SetHelixTab("SETUP FINDER", HelixFinderView());
            SetHelixTab("MANUS CHECK", HelixManusView(r));
            SizeHelixHost();
        }

        private UIElement HelixOverview(KeystoneHelixResult r)
        {
            var root = new StackPanel { Margin = new Thickness(4) };
            var c = r.Config;
            root.Children.Add(HelixNote("SETTINGS • " + c.Describe() + " • funded basket " + c.Funded.Label() + " • payout check " + (c.PayoutCalendar == "POOL" ? "every " + c.PayoutEverySessions + " sessions" : "each account after " + c.PayoutEverySessions + " days") + ", needs +" + Cash(c.PayoutMinProfit) + ", cap " + Cash(c.PayoutCap)));
            // where the money went
            root.Children.Add(HelixTitle("WHERE THE MONEY WENT", Cyan));
            var flow = new WrapPanel();
            flow.Children.Add(HelixCard("1 • TRADING (ALL ACCOUNTS)", Cash(r.TradingNet), "MNQ " + Cash(r.Rotations.Sum(x => x.MnqPnl)) + " • MGC " + Cash(r.Rotations.Sum(x => x.MgcPnl)) + (r.CommissionTotal > 0 ? " • commission " + Cash(-r.CommissionTotal) : string.Empty), MoneyBrush(r.TradingNet), 220));
            flow.Children.Add(HelixCard("2 • WITHDRAWN", Cash(r.PayoutGross), r.Payouts.Count + " payouts from the accounts", Gold, 200));
            flow.Children.Add(HelixCard("3 • YOUR CASH", Cash(r.PayoutCash), "your " + N0(c.PayoutSplit) + "% share", Green, 200));
            flow.Children.Add(HelixCard("4 • ACCOUNTS BOUGHT", "−" + Cash(r.ExpenseTotal), r.Lives.Count + " × " + Cash(r.Lives.Count == 0 ? 0 : r.ExpenseTotal / r.Lives.Count), Red, 200));
            flow.Children.Add(HelixCard("= NET", Cash(r.NetCash), "about " + Cash(r.NetCash / Math.Max(1, KeystoneHelix.Months(r).Count)) + " a month", MoneyBrush(r.NetCash), 200));
            root.Children.Add(flow);
            // cash curve
            root.Children.Add(HelixTitle("YOUR CASH DAY BY DAY (green) • TRADING P/L OF ALL ACCOUNTS (blue)", Green));
            var canvas = new Canvas { Width = 1000, Height = 230, Background = EvidenceBg, Margin = new Thickness(4) };
            var cashLine = new System.Windows.Shapes.Polyline { Stroke = Green, StrokeThickness = 2.4, Points = new PointCollection() };
            var tradeLine = new System.Windows.Shapes.Polyline { Stroke = Blue, StrokeThickness = 1.3, Opacity = 0.85, Points = new PointCollection() };
            double run = 0, trade = 0; var cashVals = new List<double>(); var tradeVals = new List<double>();
            foreach (var d in r.Days) { run += d.PayoutCash - d.Expenses; trade += d.Net; cashVals.Add(run); tradeVals.Add(trade); }
            if (cashVals.Count > 1)
            {
                double min = Math.Min(0, Math.Min(cashVals.Min(), tradeVals.Min())), max = Math.Max(1, Math.Max(cashVals.Max(), tradeVals.Max()));
                Func<double, double> y = v => 14 + (max - v) / Math.Max(1, max - min) * 196;
                for (int i = 0; i < cashVals.Count; i++) { double x = 70 + i * 900.0 / Math.Max(1, cashVals.Count - 1); cashLine.Points.Add(new Point(x, y(cashVals[i]))); tradeLine.Points.Add(new Point(x, y(tradeVals[i]))); }
                canvas.Children.Add(new System.Windows.Shapes.Line { X1 = 70, X2 = 970, Y1 = y(0), Y2 = y(0), Stroke = Muted, StrokeThickness = 1, StrokeDashArray = new DoubleCollection { 3, 3 } });
                canvas.Children.Add(tradeLine); canvas.Children.Add(cashLine);
                Action<string, double, double, Brush> label = delegate(string t, double x, double yy, Brush b) { var tb = new TextBlock { Text = t, Foreground = b, FontSize = 10, FontWeight = FontWeights.Bold }; Canvas.SetLeft(tb, x); Canvas.SetTop(tb, yy); canvas.Children.Add(tb); };
                label(Cash(max), 4, 8, Muted); label("$0", 4, y(0) - 7, Muted); label(Cash(min), 4, 204, Muted);
                label("cash " + Cash(cashVals[cashVals.Count - 1]), 880, y(cashVals[cashVals.Count - 1]) - 16, Green);
                label(r.Days[0].Day.ToString("MMM d", CultureInfo.InvariantCulture), 70, 214, Muted); label(r.Days[r.Days.Count - 1].Day.ToString("MMM d, yyyy", CultureInfo.InvariantCulture), 900, 214, Muted);
            }
            root.Children.Add(canvas);
            // months
            var months = KeystoneHelix.Months(r);
            root.Children.Add(HelixTitle("MONTH BY MONTH", Gold));
            double[] w = { 90, 70, 80, 70, 100, 100, 100, 80, 100, 80, 100, 110 };
            string[] head = { "MONTH", "SESSIONS", "BASKETS", "WON", "MNQ", "MGC", "TRADING", "PAYOUTS", "CASH IN", "BOUGHT", "SPENT", "NET CASH" };
            root.Children.Add(HelixHeader(head, w));
            foreach (var m in months)
            {
                double wr = m.Wins + m.Losses == 0 ? 0 : (double)m.Wins / (m.Wins + m.Losses);
                root.Children.Add(HelixRow(new[] { m.Month.ToString("MMM yyyy", CultureInfo.InvariantCulture), m.Sessions.ToString(), m.Rotations.ToString(), Pct(wr), Cash(m.MnqPnl), Cash(m.MgcPnl), Cash(m.TradingNet), m.Payouts.ToString(), Cash(m.PayoutCash), m.Purchases.ToString(), Cash(m.Expenses), Cash(m.NetCash) },
                    new[] { Gold, Text, Text, Text, MoneyBrush(m.MnqPnl), MoneyBrush(m.MgcPnl), MoneyBrush(m.TradingNet), Gold, Green, Text, Red, MoneyBrush(m.NetCash) }, w, MoneyBrush(m.NetCash), null));
            }
            return HelixScroll(root);
        }

        private UIElement HelixBasketsView(KeystoneHelixResult r, string filter)
        {
            var root = new StackPanel { Margin = new Thickness(4) };
            var all = r.Rotations;
            var rot = filter == "WINS" ? all.Where(x => x.Reason == "TARGET").ToList() : filter == "LOSSES" ? all.Where(x => x.Reason != "TARGET" && x.Reason != "SESSION END").ToList() : filter == "SESSION END" ? all.Where(x => x.Reason == "SESSION END").ToList() : filter == "LIQUIDATIONS" ? all.Where(x => x.Reason == "LIQUIDATED").ToList() : all;
            var cards = new WrapPanel();
            var wins = all.Where(x => x.Reason == "TARGET").ToList(); var losses = all.Where(x => x.Reason != "TARGET" && x.Reason != "SESSION END").ToList();
            cards.Children.Add(HelixCard("BASKETS", all.Count.ToString("N0"), Math.Round((double)all.Count / Math.Max(1, r.Days.Count), 1) + " a day", Cyan, 150));
            cards.Children.Add(HelixCard("WINS", wins.Count.ToString("N0"), "avg " + Cash(wins.Select(x => x.Net).DefaultIfEmpty(0).Average()) + " in " + wins.Select(x => (double)x.Minutes).DefaultIfEmpty(0).Average().ToString("0") + " min", Green, 170));
            cards.Children.Add(HelixCard("LOSSES", losses.Count.ToString("N0"), "avg " + Cash(losses.Select(x => x.Net).DefaultIfEmpty(0).Average()) + " in " + losses.Select(x => (double)x.Minutes).DefaultIfEmpty(0).Average().ToString("0") + " min", Red, 170));
            cards.Children.Add(HelixCard("LIQUIDATIONS", all.Count(x => x.Reason == "LIQUIDATED").ToString(), "baskets that ended an account", Red, 170));
            cards.Children.Add(HelixCard("TOUCHED BOTH IN 1 MINUTE", all.Count(x => x.Ambiguous).ToString(), r.Config.ExitModel == "STRICT" ? "counted as losses (STRICT)" : "judged on minute closes", Gold, 190));
            root.Children.Add(cards);
            var filters = new WrapPanel { Margin = new Thickness(2, 4, 2, 2) };
            foreach (string f in new[] { "ALL", "WINS", "LOSSES", "LIQUIDATIONS", "SESSION END" })
            {
                string pick = f; var b = Btn(f, f == filter ? Cyan : Card); b.Height = 26; b.FontSize = 10; b.Padding = new Thickness(12, 0, 12, 0);
                b.Click += delegate { SetHelixTab("BASKETS", HelixBasketsView(helixResult, pick)); };
                filters.Children.Add(b);
            }
            filters.Children.Add(HelixNote("click a basket to open its day on the chart • newest page first"));
            root.Children.Add(filters);
            double[] w = { 60, 118, 76, 44, 104, 50, 50, 84, 84, 92, 104, 150, 86 };
            string[] head = { "#", "DAY", "ACCOUNT", "TRY", "IN → OUT", "MIN", "DIR", "MNQ", "MGC", "BASKET", "RESULT", "THEN", "BALANCE" };
            root.Children.Add(HelixPaged(head, w, rot.Count, i =>
            {
                var x = rot[i];
                Brush res = x.Reason == "TARGET" ? Green : (x.Reason == "SESSION END" ? ExitIce : Red);
                return HelixRow(new[] { x.Id.ToString(), x.Day.ToString("MMM d ddd", CultureInfo.InvariantCulture), x.Account, x.AccountTry.ToString(), Hm(x.EntryTime) + " → " + Hm(x.ExitTime), x.Minutes.ToString(), (x.MnqDir > 0 ? "B" : x.MnqDir < 0 ? "S" : "-") + " " + (x.MgcDir > 0 ? "B" : x.MgcDir < 0 ? "S" : "-"), Cash(x.MnqPnl), Cash(x.MgcPnl), Cash(x.Net), x.Reason + (x.Ambiguous ? " *" : string.Empty), x.After, Cash(x.BalanceAfter) },
                    new[] { Muted, Text, Gold, Text, Text, Muted, Cyan, MoneyBrush(x.MnqPnl), MoneyBrush(x.MgcPnl), MoneyBrush(x.Net), res, x.After.StartsWith("ACCOUNT LIQ") ? Red : (x.After.StartsWith("LOCKED") ? Green : Muted), Text }, w, res, delegate { OpenHelixChart(x); });
            }, 150, true));
            return HelixScroll(root);
        }

        private WrapPanel HelixBucketCards(string group, Func<string, string> rename, double be)
        {
            var wrap = new WrapPanel();
            var b = helixBuckets.Where(x => x.Group == group).OrderBy(x => x.Name).ToList();
            foreach (var x in b)
            {
                Brush accent = x.Count < 10 ? Muted : (x.Net > 0 && x.WinRate > be ? Green : (x.Net < 0 ? Red : Gold));
                wrap.Children.Add(HelixCard(rename == null ? x.Name : rename(x.Name), Pct(x.WinRate) + " won", x.Count + " baskets • " + Cash(x.Net) + " • avg " + Cash(x.AvgNet), accent, 170));
            }
            return wrap;
        }

        private UIElement HelixDaysView(KeystoneHelixResult r)
        {
            var root = new StackPanel { Margin = new Thickness(4) };
            double be = KeystoneHelix.BreakEvenWinRate(r);
            root.Children.Add(HelixNote("GREEN = won more often than needed (" + Pct(be) + ") and made money • RED = lost money • GOLD = in between • GREY = too few baskets"));
            root.Children.Add(HelixTitle("BY START TIME (half hour of the basket's entry)", Cyan)); root.Children.Add(HelixBucketCards("ENTRY HALF-HOUR", null, be));
            root.Children.Add(HelixTitle("BY WEEKDAY", Gold)); root.Children.Add(HelixBucketCards("WEEKDAY", n => n.Substring(0, 1) + n.Substring(1).ToLowerInvariant(), be));
            root.Children.Add(HelixTitle("BY THE ACCOUNT'S TRY OF THE DAY", Orchid)); root.Children.Add(HelixBucketCards("ACCOUNT TRY TODAY", n => n + " TRY", be));
            root.Children.Add(HelixTitle("BY THE POOL'S BASKET NUMBER OF THE DAY", Blue)); root.Children.Add(HelixBucketCards("POOL BASKET # TODAY", n => "BASKET " + n, be));
            if (r.SkippedDays.Count > 0) { root.Children.Add(HelixTitle("DAYS NOT TRADED (MISSING DATA)", Red)); foreach (var s in r.SkippedDays) root.Children.Add(HelixNote(s)); }
            var days = r.Days;
            root.Children.Add(HelixTitle("EVERY SESSION • " + days.Count + " • positive " + days.Count(d => d.Net > 0) + " • negative " + days.Count(d => d.Net < 0) + " • best " + Cash(days.Select(d => d.Net).DefaultIfEmpty(0).Max()) + " • worst " + Cash(days.Select(d => d.Net).DefaultIfEmpty(0).Min()), Green));
            double[] w = { 118, 66, 70, 90, 90, 96, 60, 60, 70, 90, 90, 118, 150 };
            string[] head = { "DAY", "BASKETS", "W / L", "MNQ", "MGC", "NET", "LOCKS", "LIQ", "PAYOUTS", "CASH IN", "SPENT", "FIRST → LAST", "DAY ENDED" };
            root.Children.Add(HelixPaged(head, w, days.Count, i =>
            {
                var d = days[i];
                return HelixRow(new[] { d.Day.ToString("MMM d ddd", CultureInfo.InvariantCulture), d.Rotations.ToString(), d.Wins + " / " + d.Losses, Cash(d.MnqPnl), Cash(d.MgcPnl), Cash(d.Net), d.Locks.ToString(), d.Blowups.ToString(), d.Payouts.ToString(), Cash(d.PayoutCash), Cash(d.Expenses), Hm(d.FirstEntry) + " → " + Hm(d.LastExit), d.EndReason },
                    new[] { Gold, Text, Text, MoneyBrush(d.MnqPnl), MoneyBrush(d.MgcPnl), MoneyBrush(d.Net), Green, d.Blowups > 0 ? Red : Muted, Gold, Green, d.Expenses > 0 ? Red : Muted, Text, Muted }, w, MoneyBrush(d.Net), delegate { var f = r.Rotations.FirstOrDefault(x => x.Day == d.Day); if (f != null) OpenHelixChart(f); });
            }, 60, true));
            return HelixScroll(root);
        }

        private UIElement HelixAccountsView(KeystoneHelixResult r)
        {
            var root = new StackPanel { Margin = new Thickness(4) };
            var lives = r.Lives; int paid = lives.Count(l => l.Payouts > 0);
            var ended = lives.Where(l => l.Status == "BLOWN" || l.Status == "FAILED EVAL").ToList();
            var cards = new WrapPanel();
            cards.Children.Add(HelixCard("ACCOUNTS BOUGHT", lives.Count.ToString(), Math.Min(lives.Count, r.Config.Accounts) + " at the start + " + Math.Max(0, lives.Count - r.Config.Accounts) + " replacements", Cyan, 190));
            cards.Children.Add(HelixCard("EVER PAID", paid + " (" + Pct(lives.Count == 0 ? 0 : (double)paid / lives.Count) + ")", r.Payouts.Count + " payouts • " + (lives.Count == 0 ? 0 : (double)r.Payouts.Count / lives.Count).ToString("0.00") + " per account", Green, 190));
            cards.Children.Add(HelixCard("LIQUIDATED", r.FundedBlowups.ToString(), ended.Count(l => l.Payouts == 0) + " never paid anything", Red, 180));
            if (r.Config.StartMode == "EVAL") cards.Children.Add(HelixCard("EVALUATIONS", r.EvalPasses + " passed / " + r.EvalFails + " failed", "pass rate " + Pct(r.EvalPasses + r.EvalFails == 0 ? 0 : (double)r.EvalPasses / (r.EvalPasses + r.EvalFails)), Orchid, 200));
            cards.Children.Add(HelixCard("AVERAGE LIFE", (ended.Count == 0 ? 0 : ended.Average(l => l.TradingDays)).ToString("0.0") + " days", "trading days until liquidation • longest " + lives.Select(l => l.TradingDays).DefaultIfEmpty(0).Max(), Gold, 190));
            cards.Children.Add(HelixCard("NET PER ACCOUNT", Cash(lives.Count == 0 ? 0 : r.NetCash / lives.Count), "cash " + Cash(lives.Count == 0 ? 0 : r.PayoutCash / lives.Count) + " − price " + Cash(lives.Count == 0 ? 0 : r.ExpenseTotal / lives.Count), MoneyBrush(r.NetCash), 190));
            root.Children.Add(cards);
            root.Children.Add(HelixTitle("EVERY ACCOUNT • GREEN paid and alive • GOLD paid then liquidated • RED liquidated without a payout • BLUE alive, no payout yet", Cyan));
            var wrap = new WrapPanel();
            foreach (var l in lives.Take(400))
            {
                bool blown = l.Status == "BLOWN" || l.Status == "FAILED EVAL";
                Brush accent = blown ? (l.Payouts > 0 ? Gold : Red) : (l.Payouts > 0 ? Green : Blue);
                string life = l.Bought.ToString("MMM d", CultureInfo.InvariantCulture) + (blown ? " → " + l.EndDate.ToString("MMM d", CultureInfo.InvariantCulture) : " → still trading");
                wrap.Children.Add(HelixCard(l.Id + " • " + (blown ? (l.Status == "FAILED EVAL" ? "FAILED EVAL" : "LIQUIDATED") : l.Status), Cash(l.PayoutCash - l.Cost), life + " (" + l.TradingDays + " days)\n" + l.Rotations + " baskets • " + l.Wins + " W / " + l.Losses + " L\n" + l.Payouts + " payouts • cash " + Cash(l.PayoutCash) + " • price " + Cash(l.Cost), accent, 205));
            }
            root.Children.Add(wrap);
            if (lives.Count > 400) root.Children.Add(HelixNote("First 400 accounts shown; the report lists all " + lives.Count + "."));
            root.Children.Add(HelixTitle("EVERY PAYOUT • " + r.Payouts.Count + " • gross " + Cash(r.PayoutGross) + " • your cash " + Cash(r.PayoutCash), Green));
            double[] w = { 130, 90, 60, 110, 100, 100, 110 };
            string[] head = { "DAY", "ACCOUNT", "NO.", "BALANCE BEFORE", "GROSS", "YOUR CASH", "LEFT IN ACCOUNT" };
            var pays = r.Payouts;
            root.Children.Add(HelixPaged(head, w, pays.Count, i => { var p = pays[i]; return HelixRow(new[] { p.Day.ToString("MMM d ddd, yyyy", CultureInfo.InvariantCulture), p.Account, "#" + p.Number, Cash(p.BalanceBefore), Cash(p.Gross), Cash(p.Cash), Cash(p.BalanceAfter) }, new[] { Gold, Text, Muted, Text, Gold, Green, Text }, w, Green, null); }, 80, false));
            return HelixScroll(root);
        }

