        private static SolidColorBrush Tint(SolidColorBrush b, byte alpha) { var x = new SolidColorBrush(Color.FromArgb(alpha, b.Color.R, b.Color.G, b.Color.B)); x.Freeze(); return x; }

        // a dark, clear confirmation (OK / CANCEL) for actions that close trades
        private bool StyledConfirm(Window owner, string title, string body, string okText, Brush accent)
        {
            bool ok = false;
            var d = new KeystoneWindow { Title = "KEYSTONE ARC", SizeToContent = SizeToContent.WidthAndHeight, ResizeMode = ResizeMode.NoResize, WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = owner, Background = Bg, Foreground = Text, ShowInTaskbar = false, Topmost = true };
            var sp = new StackPanel { Margin = new Thickness(26, 20, 26, 20), MaxWidth = 480 };
            sp.Children.Add(new TextBlock { Text = title, Foreground = accent, FontSize = 21, FontWeight = FontWeights.Bold });
            sp.Children.Add(new TextBlock { Text = body, Foreground = Text, FontSize = 13.5, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 10, 0, 18) });
            var row = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right };
            var cancel = Btn("CANCEL", Card); cancel.Height = 34; cancel.MinWidth = 110; cancel.Margin = new Thickness(0, 0, 10, 0); cancel.Click += delegate { d.Close(); };
            var go = Btn(okText, accent); go.Height = 34; go.MinWidth = 150; go.Click += delegate { ok = true; d.Close(); };
            row.Children.Add(cancel); row.Children.Add(go); sp.Children.Add(row);
            d.Content = new Border { BorderBrush = accent, BorderThickness = new Thickness(0, 4, 0, 0), Child = sp };
            d.ShowDialog(); return ok;
        }
        private static bool IsPracticeAccount(string name) { var n = (name ?? "").ToUpperInvariant(); return n.StartsWith("SIM") || n.StartsWith("PLAYBACK") || n.StartsWith("DEMO") || n == "BACKTEST"; }
        private bool studioIsLive;   // the open studio window: LIVE TRADING (real-time data, real accounts) or BACKTEST STUDIO (history)
        private void OpenReplayTrader() { OpenStudio(false); }
        private void OpenLiveTrading() { OpenStudio(true); }
        private void OpenStudio(bool liveWindow)
        {
            if (replayTraderWindow != null)
            {
                if (studioIsLive == liveWindow) { replayTraderWindow.Activate(); return; }
                // one chart window at a time (they share the workspace, drawings and journal)
                string other = studioIsLive ? "LIVE TRADING" : "BACKTEST STUDIO";
                if (KBox(other + " is open. Close it and open " + (liveWindow ? "LIVE TRADING" : "the BACKTEST STUDIO") + "?", "KEYSTONE ARC", MessageBoxButton.YesNo, MessageBoxImage.Question) != MessageBoxResult.Yes) { replayTraderWindow.Activate(); return; }
                var old = replayTraderWindow; old.Close(); if (replayTraderWindow != null) return;   // closing was cancelled
            }
            studioIsLive = liveWindow;
            // the studio's own data (Data Library): the lab's loaded 1-minute bars are copied in, the first open also brings in every
            // 1-minute file the lab saved earlier (in the background)
            string sfolder = StudioFolder(); string[] studioSymbols = { "MNQ", "MGC" };
            bool firstOpen = studioSymbols.All(x => KeystoneStudioStore.Sessions(sfolder, x).Count == 0);
            string labImport = ImportLabBarsIntoStudio();
            Func<List<DateTime>> listSessions = () => studioSymbols.SelectMany(x => KeystoneStudioStore.Sessions(sfolder, x).Where(kv => kv.Value >= 60).Select(kv => kv.Key)).Distinct().OrderByDescending(d => d).ToList();
            var ws = ReadStudioWorkspace(); Func<string, string, string> wsGet = (k, d) => { string v; return ws.TryGetValue(k, out v) && v != "" ? v : d; };
            // the studio's own strategy settings (⚙ SETTINGS): a copy of the lab's settings + the tested rules, saved as p.<target>.<field>
            var studioCfg = CloneConfig(config); var stratParams = new Dictionary<string, string>(); var fvgTp = new Dictionary<string, double>();
            Func<string, object> paramTarget = t => t == "cfg" ? (object)studioCfg : t.StartsWith("rule") ? (object)KeystoneReplaySignals.Rules[Math.Max(0, Math.Min(KeystoneReplaySignals.Rules.Count - 1, ParseStudioInt(t.Substring(4), 0)))] : null;
            Action<string, string> applyParam = (key, value) =>
            {
                var parts = key.Split('.'); if (parts.Length != 3) return;
                if (parts[1] == "fvg") { double tpv; if (double.TryParse(value, NumberStyles.Float, CultureInfo.InvariantCulture, out tpv)) fvgTp[parts[2]] = tpv; stratParams[key] = value; return; }
                if (SetParam(paramTarget(parts[1]), parts[2], value)) stratParams[key] = value;
            };
            KeystoneReplaySignals.Rules = KeystoneOpeningRange.Presets();
            foreach (var kv in ws.Where(x => x.Key.StartsWith("p.")).ToList()) applyParam(kv.Key, kv.Value);
            var w = new KeystoneWindow { Title = liveWindow ? "KEYSTONE ARC • LIVE TRADING" : "KEYSTONE ARC • BACKTEST STUDIO", Width = 1600, Height = 960, MinWidth = 900, MinHeight = 600, Background = Bg, Foreground = Text, WindowStartupLocation = WindowStartupLocation.CenterScreen, ShowInTaskbar = true, WindowState = WindowState.Maximized };
            replayTraderWindow = w;
            var root = new Grid { Margin = new Thickness(6) };
            for (int i = 0; i < 3; i++) root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            Action<string, UIElement, System.Windows.Controls.Panel> add = (l, e, p) => { var sp = new StackPanel { Margin = new Thickness(2, 0, 6, 0) }; sp.Children.Add(new TextBlock { Text = l, Foreground = Muted, FontSize = 9, FontWeight = FontWeights.Bold }); sp.Children.Add(e); p.Children.Add(sp); };
            Func<string, Brush, Button> small = (t, b) => { var x = Btn(t, b); x.Height = 28; x.FontSize = 11; x.Margin = new Thickness(3, 12, 3, 0); x.Padding = new Thickness(10, 0, 10, 0); return x; };
            var liveBtn = small("● GO LIVE", Red); liveBtn.ToolTip = "LIVE: NinjaTrader's real-time data on this chart (today + yesterday). With no active prop account you trade a SIMULATED account on the live prices.";
            // ---- top bar: day, speed, account, day limits, strategy
