            var soundBox = new CheckBox { Content = "SOUND", IsChecked = wsGet("sound", "1") == "1", Foreground = Text, Margin = new Thickness(4, 16, 6, 0), ToolTip = "A sound when a setup of the chosen strategy appears." };
