                        if (!int.TryParse(a[9], out o) || !int.TryParse(a[3], out sd) || !double.TryParse(a[6], NumberStyles.Any, CultureInfo.InvariantCulture, out up) || !double.TryParse(a[7], NumberStyles.Any, CultureInfo.InvariantCulture, out bu)) continue;
