            Action<PredRecord, int, double> writePred = (pr, outcome, endMove) =>
            {
                if (outcome == pr.Side) predRight++; else if (outcome == -pr.Side) predWrong++; else predNeither++; predExpected += pr.Side > 0 ? pr.BaseUp : 1 - pr.BaseUp;
