            // resolves a pane's open predictions with the bars the replay clock has passed (never beyond)
            Action<ReplayPane> resolvePreds = pn =>
            {
                var r = pn.Trader; if (r == null) return;
                foreach (var pr in pn.Pending.ToList())
                {
                    if (!pr.Taken && Math.Sign(r.Position) == pr.Side && r.Time <= pr.Time.AddMinutes(3)) pr.Taken = true;
                    int last = Math.Min(r.BarIndex - 1, r.Bars.Count - 1); int outcome = 0; bool done = false; double end = 0;
                    for (int k = pr.BarIndex + 1; k <= last; k++)
                    {
                        var b = r.Bars[k]; bool up = b.High >= pr.Entry + pr.Barrier, dn = b.Low <= pr.Entry - pr.Barrier;
                        if (up || dn) { outcome = up && dn ? 0 : up ? 1 : -1; end = up && dn ? 0 : outcome; done = true; break; }
                        if (b.Time >= pr.Time.AddMinutes(KeystoneAnalog.Horizon)) { end = (b.Close - pr.Entry) / pr.Barrier; done = true; break; }
                    }
                    if (!done && r.Finished) { done = true; end = last >= 0 ? (r.Bars[last].Close - pr.Entry) / pr.Barrier : 0; }
                    if (done) { pn.Pending.Remove(pr); writePred(pr, outcome, end); }
                }
            };
            var themes = ChartThemeDefs.Select(t => t[1] == "" ? new ChartTheme { Name = t[0], Bg = Panel, Grid = Tint(Card, 160), Up = Green, Down = Red, Text = Muted } : new ChartTheme { Name = t[0], Bg = HexBrush(t[1]), Grid = HexBrush(t[2]), Up = HexBrush(t[3]), Down = HexBrush(t[4]), Text = HexBrush(t[5]), Hollow = t[6] == "1", Style = t.Length > 7 ? t[7] : "" }).ToList();
            int themeIndex = Math.Max(0, themes.FindIndex(t => t.Name == wsGet("theme", "TRADINGVIEW DARK"))); bool hollowUp = wsGet("hollow", "0") == "1";
            // LIVE TRADING layers: every level ALWAYS / NEAR (fades in near price, flashing) / OFF; setups, news, drawings on / off
            var layerModes = new Dictionary<string, int>();
            if (liveWindow) foreach (var lk0 in new[] { "PDH", "PDL", "PDC", "ONH", "ONL", "HOD", "LOD" }) layerModes[lk0] = KeystoneLiveTools.Off;   // highs / lows lines start OFF every time (LAYERS turns them on)
            Func<string, int, int> layerOf = (k, d) => { int v; if (layerModes.TryGetValue(k, out v)) return v; string sv; v = ws.TryGetValue("layer." + k, out sv) && int.TryParse(sv, out v) ? v : d; layerModes[k] = v; return v; };
            // TIME ZONE for the clock and the time axis (the data stays New York time inside)
            string[] tzNames = { "NY", "CHICAGO", "LONDON", "UTC", "MY PC" }; string[] tzIds = { "", "Central Standard Time", "GMT Standard Time", "UTC", "LOCAL" };
            TimeZoneInfo tzEastern = null; try { tzEastern = TimeZoneInfo.FindSystemTimeZoneById("Eastern Standard Time"); } catch { }
            var tzCache = new Dictionary<int, TimeZoneInfo>();
            Func<DateTime, DateTime> tzShow = t =>
            {
                int k = layerOf("TZ", 0); if (k <= 0 || k >= tzIds.Length || tzEastern == null) return t;
                try
                {
                    TimeZoneInfo dst; if (!tzCache.TryGetValue(k, out dst)) { dst = tzIds[k] == "LOCAL" ? TimeZoneInfo.Local : tzIds[k] == "UTC" ? TimeZoneInfo.Utc : TimeZoneInfo.FindSystemTimeZoneById(tzIds[k]); tzCache[k] = dst; }
                    return TimeZoneInfo.ConvertTime(DateTime.SpecifyKind(t, DateTimeKind.Unspecified), tzEastern, dst);
                }
                catch { return t; }
            };
            // every indicated entry (FVG, MATCHES, strategy setups) is written once when it is decided → SetupLog.csv (taken by you or not)
            string setupLogFile = Path.Combine(StudioFolder(), "SetupLog.csv"); var setupLogged = new HashSet<string>();
            try { if (File.Exists(setupLogFile)) foreach (var l0 in File.ReadAllLines(setupLogFile).Skip(1)) { var a0 = l0.Split(','); if (a0.Length >= 17) setupLogged.Add(a0[16]); } } catch { }
            Action<string, string[]> logSetup = (key0, cols) =>
            {
                if (!liveWindow) key0 = "R|" + key0;
                if (setupLogged.Contains(key0)) return; setupLogged.Add(key0);
                if (!liveWindow && cols.Length > 14) cols[14] = "REPLAY " + cols[14];   // backtest-studio replays are kept apart from the live record
                try { Directory.CreateDirectory(StudioFolder()); bool hh = !File.Exists(setupLogFile); var row = string.Join(",", cols.Select(c0 => (c0 ?? "").Replace(",", ";")).Concat(new[] { key0 }));
                    File.AppendAllLines(setupLogFile, hh ? new[] { "session,symbol,timeframe,source,side,formed,entry_rule,entry,stop,target,reached,closed,result,setup_usd_micro,you,your_net,key", row } : new[] { row }); } catch { }
            };
            Func<double, string> inv = v => v.ToString("0.##", CultureInfo.InvariantCulture);
            // how an indicated entry played out on the 1-minute bars up to now: entryKind 0 = at once (market), 1 = limit (price comes back
            // to it), 2 = stop (price breaks through it); stop checked before the target inside a bar (conservative); null = not decided yet
            Func<List<KeystoneArcBar>, DateTime, DateTime, DateTime, DateTime, int, int, double, double, double, Tuple<string, DateTime, DateTime, double>> playOut = (bars, from, entryUntil, exitBy, now, dir, entryKind, ent, stp, tgt) =>
            {
                DateTime et = DateTime.MinValue; bool inT = entryKind == 0; if (inT) et = from;
                foreach (var b in bars)
                {
                    if (b.Time <= from) continue; if (b.Time > now) return null;
                    if (!inT)
                    {
                        if (b.Time > entryUntil) return Tuple.Create("NO ENTRY", DateTime.MinValue, b.Time, 0.0);
                        bool hitE = entryKind == 1 ? (dir > 0 ? b.Low <= ent : b.High >= ent) : (dir > 0 ? b.High >= ent : b.Low <= ent);
                        if (!hitE) { if (dir > 0 ? b.Low <= stp : b.High >= stp) return Tuple.Create("NO ENTRY", DateTime.MinValue, b.Time, 0.0); continue; }
                        inT = true; et = b.Time;
                    }
                    if (dir > 0 ? b.Low <= stp : b.High >= stp) return Tuple.Create("LOSS", et, b.Time, dir * (stp - ent));
                    if (dir > 0 ? b.High >= tgt : b.Low <= tgt) return Tuple.Create("WIN", et, b.Time, dir * (tgt - ent));
                    if (b.Time >= exitBy) { double pts = dir * (b.Close - ent); return Tuple.Create(pts >= 0 ? "WIN" : "LOSS", et, b.Time, pts); }   // out at the time limit
                }
                return null;
            };
            // writes one decided entry (with whether YOU traded it) to SetupLog.csv
            Action<ReplayPane, string, string, int, DateTime, string, double, double, double, Tuple<string, DateTime, DateTime, double>> logPlayed = (p0, source, key0, dir, formed, rule, ent, stp, tgt, res0) =>
            {
                if (res0 == null || p0 == null || p0.IsSplit || p0.Trader == null) return;
                string fullKey = p0.Symbol + "|" + source + "|" + key0; if (setupLogged.Contains((liveWindow ? "" : "R|") + fullKey)) return;
                double risk = Math.Abs(ent - stp); KeystoneReplayFill mine = null;
                if (res0.Item1 != "NO ENTRY") mine = p0.Trader.Fills.FirstOrDefault(f => f.Side == (dir > 0 ? "BUY" : "SELL") && f.EntryTime >= res0.Item2.AddMinutes(-3) && f.EntryTime <= res0.Item3.AddMinutes(1) && Math.Abs(f.Entry - ent) <= Math.Max(4 * p0.Trader.Tick, risk));
                string you = mine != null ? "TAKEN" : "NOT TAKEN";
                logSetup(fullKey, new[] { KeystoneStudioStore.SessionOf(formed).ToString("yyyy-MM-dd"), p0.Symbol, p0.Tf + "m", source, dir > 0 ? "BUY" : "SELL", formed.ToString("yyyy-MM-dd HH:mm"), rule, inv(ent), inv(stp), inv(tgt),
                    res0.Item2 > DateTime.MinValue ? res0.Item2.ToString("yyyy-MM-dd HH:mm") : "", res0.Item3.ToString("yyyy-MM-dd HH:mm"), res0.Item1, (res0.Item4 * KeystoneMoveStudy.PointValue(p0.Symbol)).ToString("0.00", CultureInfo.InvariantCulture), you, mine != null ? mine.Net.ToString("0.00", CultureInfo.InvariantCulture) : "" });
            };
