                            st0.Children.Add(new TextBlock { Text = ls[k], Foreground = title || result ? ih.Item4 : Text, FontSize = title ? 13.5 : result ? 16 : 11.5, FontWeight = title || result ? FontWeights.Bold : FontWeights.Normal, FontFamily = result ? new FontFamily("Consolas") : new FontFamily("Segoe UI"), Margin = new Thickness(0, title ? 0 : 2, 0, title ? 4 : 0) });
                        }
                        var ib = new Border { Background = Tint(th.Bg, 248), BorderBrush = ih.Item4, BorderThickness = new Thickness(1.6), CornerRadius = new CornerRadius(8), Padding = new Thickness(12, 8, 14, 10), Child = st0 };
                        ib.Effect = new System.Windows.Media.Effects.DropShadowEffect { BlurRadius = 14, ShadowDepth = 0, Opacity = 0.6, Color = ((SolidColorBrush)ih.Item4).Color };
                        double bx = ih.Item1[2] + 10, by = ih.Item1[1] - 20; if (bx > pn.PlotW - 330) bx = Math.Max(4, ih.Item1[0] - 340); by = Math.Max(pn.Top + 4, Math.Min(pn.Top + pn.PlotH - 120, by));
                        System.Windows.Controls.Canvas.SetLeft(ib, bx); System.Windows.Controls.Canvas.SetTop(ib, by); cv.Children.Add(ib);
