                    var tb0 = new Border { Background = Tint(Bg, 240), BorderBrush = bad ? Orange : Gold, BorderThickness = new Thickness(1.5), CornerRadius = new CornerRadius(6), Padding = new Thickness(12, 5, 12, 6), Child = new TextBlock { Text = pn.Toast, Foreground = bad ? Orange : Gold, FontSize = 12.5, FontWeight = FontWeights.Bold } };
                    System.Windows.Controls.Canvas.SetLeft(tb0, Math.Max(6, pn.PlotW / 2 - 4 * pn.Toast.Length)); System.Windows.Controls.Canvas.SetTop(tb0, pn.Top + 8); cv.Children.Add(tb0);
                }
