                            string headF = d.Text == "bullish" ? "▲ BULL FVG" : d.Text == "bearish" ? "▼ BEAR FVG" : "FVG";
                            var fvt = new TextBlock { Text = headF + (hovF ? "  " + fmt(Math.Min(d.P1, d.P2)) + " – " + fmt(Math.Max(d.P1, d.P2)) + (string.IsNullOrEmpty(d.Text) || d.Text == "bullish" || d.Text == "bearish" ? "" : " • " + d.Text) : ""), Foreground = System.Windows.Media.Brushes.White, FontSize = 9.5, FontWeight = FontWeights.Bold };
                            var fvl = new Border { Background = Tint(Bg, 225), BorderBrush = dc, BorderThickness = new Thickness(1, 1, 3, 1), CornerRadius = new CornerRadius(3), Padding = new Thickness(4, 0, 4, 1), Child = fvt, Opacity = hovF ? 1 : 0.85 };
                            fvl.Measure(new Size(double.PositiveInfinity, double.PositiveInfinity));
                            double fw = fvl.DesiredSize.Width > 0 ? fvl.DesiredSize.Width : 64, fh = fvl.DesiredSize.Height > 0 ? fvl.DesiredSize.Height : 15;
                            double fx = left - fw - 4 - pn.Spacing / 2; if (fx < 2) fx = left + 4;   // no room on the left: inside the box, at its start
                            System.Windows.Controls.Canvas.SetLeft(fvl, fx); System.Windows.Controls.Canvas.SetTop(fvl, (yTopF + yBotF) / 2 - fh / 2); cv.Children.Add(fvl);
                        }
                    }
                    else if (d.Kind == "FIB")
                    {
                        double left = Math.Min(x1, x2), right = Math.Max(Math.Max(x1, x2), left + 80);
                        foreach (var lv in new[] { 0, 0.236, 0.382, 0.5, 0.618, 0.786, 1 })
                        {
                            double pr = d.P2 + (d.P1 - d.P2) * lv, yy = yOf(pn, pr);
                            cv.Children.Add(new System.Windows.Shapes.Line { X1 = left, X2 = right, Y1 = yy, Y2 = yy, Stroke = dc, StrokeThickness = lv == 0.5 || lv == 0.618 ? dw + 0.5 : 1, Opacity = lv == 0 || lv == 1 ? 1 : 0.8 });
                            label(right + 4, yy - 8, lv.ToString("0.###", CultureInfo.InvariantCulture) + " (" + fmt(pr) + ")", 10);
                        }
                        rect(left, yOf(pn, d.P2 + (d.P1 - d.P2) * 0.5), right, yOf(pn, d.P2 + (d.P1 - d.P2) * 0.618), dc, 0.12);
                    }
