                            var hd = new Border { Width = hsz, Height = hsz, CornerRadius = new CornerRadius(corner), Background = hv ? dc : (Brush)System.Windows.Media.Brushes.White, BorderBrush = hv ? System.Windows.Media.Brushes.White : dc, BorderThickness = new Thickness(1.6) };
                            System.Windows.Controls.Canvas.SetLeft(hd, h0.Item1 - hsz / 2); System.Windows.Controls.Canvas.SetTop(hd, h0.Item2 - hsz / 2); cv.Children.Add(hd);
