                // an imported report's day (REPORTS window): its markers and trades, drawn once the replay reaches them
                if (pn.ReportDay != null && pn.ReportDay.Date == session.Date && !cleanChart)
                {
                    Func<string, Brush> kindBrush = k => k == "buy" ? Cyan : k == "sell" ? Orchid : k == "exit" ? Text : Gold;
                    foreach (var mk in pn.ReportDay.Markers)
                    {
                        var at = session.Date + mk.Time; if (at.AddMinutes(1) > r.Time) continue;
                        double mx = xOfIndex(pn, indexOfTime(pn, at.AddMinutes(1))); if (mx < 0 || mx > pn.PlotW) continue;
                        double my = double.IsNaN(mk.Price) ? pn.Top + 14 : yOf(pn, mk.Price) + (mk.Kind == "sell" ? -14 : 14);
                        var dot = new System.Windows.Shapes.Ellipse { Width = 9, Height = 9, Fill = kindBrush(mk.Kind), Stroke = System.Windows.Media.Brushes.White, StrokeThickness = 1 };
                        System.Windows.Controls.Canvas.SetLeft(dot, mx - 4.5); System.Windows.Controls.Canvas.SetTop(dot, my - 4.5); cv.Children.Add(dot);
                        var lb = new Border { Background = Tint(Bg, 210), BorderBrush = kindBrush(mk.Kind), BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(3), Padding = new Thickness(4, 1, 4, 1), Child = new TextBlock { Text = mk.Text, Foreground = kindBrush(mk.Kind), FontSize = 10.5, FontWeight = FontWeights.Bold } };
                        System.Windows.Controls.Canvas.SetLeft(lb, mx + 7); System.Windows.Controls.Canvas.SetTop(lb, my - 9); cv.Children.Add(lb);
                    }
                    foreach (var rt in pn.ReportDay.Trades)
                    {
                        var tin = session.Date + rt.EntryTime; if (tin.AddMinutes(1) > r.Time || double.IsNaN(rt.Entry)) continue;
                        double x1 = xOfIndex(pn, indexOfTime(pn, tin.AddMinutes(1))), y1 = yOf(pn, rt.Entry); var tout = session.Date + rt.ExitTime; bool closed = tout <= r.Time && !double.IsNaN(rt.Exit);
                        var tri = new System.Windows.Shapes.Polygon { Fill = rt.Dir > 0 ? Cyan : Orchid, Points = new PointCollection { new System.Windows.Point(x1, y1), new System.Windows.Point(x1 - 6, y1 + (rt.Dir > 0 ? 10 : -10)), new System.Windows.Point(x1 + 6, y1 + (rt.Dir > 0 ? 10 : -10)) } }; cv.Children.Add(tri);
                        if (!closed) continue;
                        double x2 = xOfIndex(pn, indexOfTime(pn, tout)), y2 = yOf(pn, rt.Exit);
                        cv.Children.Add(new System.Windows.Shapes.Line { X1 = x1, Y1 = y1, X2 = x2, Y2 = y2, Stroke = MoneyBrush(rt.Pnl), StrokeThickness = 1.5, StrokeDashArray = new DoubleCollection { 3, 2 } });
                        var pl = new TextBlock { Text = "REPORT " + (rt.Dir > 0 ? "LONG" : "SHORT") + " " + Signed(rt.Pnl) + (rt.Why != "" ? " • " + rt.Why : ""), Foreground = MoneyBrush(rt.Pnl), FontSize = 10.5, FontWeight = FontWeights.Bold };
                        System.Windows.Controls.Canvas.SetLeft(pl, x2 + 6); System.Windows.Controls.Canvas.SetTop(pl, y2 - 8); cv.Children.Add(pl);
                    }
                }
                // LIVE: the setup arrows take the two colours furthest from this theme's candles; ONLY NEW hides the ones formed before the window opened
                Brush buyC = Cyan, sellC = Orchid;
                if (liveWindow)
                {
                    Func<Brush, Color> colOf = b0 => { var sb = b0 as SolidColorBrush; return sb != null ? sb.Color : Color.FromRgb(128, 128, 128); };
                    Color cu = colOf(th.Up), cd = colOf(th.Down);
                    Func<string, double> farness = hx => { var c0 = colorOf(hx).Color; Func<Color, double> dist = c1 => Math.Sqrt(Math.Pow(c0.R - c1.R, 2) + Math.Pow(c0.G - c1.G, 2) + Math.Pow(c0.B - c1.B, 2)); return Math.Min(dist(cu), dist(cd)); };
                    var ranked = new[] { "#FFEA00", "#FF9100", "#FFFFFF", "#76FF03", "#2979FF", "#00E5FF", "#E040FB" }.OrderByDescending(farness).ToList();
                    buyC = colorOf("#00E676"); sellC = colorOf("#FF1744");   // every indicator: BUY = green box arrow, SELL = red box arrow
                    if (setupsFrom == DateTime.MinValue) setupsFrom = r.Time;
                }
                bool onlyNew = liveWindow && layerOf("SETUPS.NEW", 0) == 1;
                // every strategy setup that reached its outcome is recorded once (taken by you or not) → SetupLog.csv
                if (!pn.IsSplit && signalBox.SelectedIndex > 0 && signalBox.SelectedIndex < KeystoneReplaySignals.Names.Length)
                {
                    string srcS = KeystoneReplaySignals.Names[signalBox.SelectedIndex];
                    foreach (var sg in pn.Signals.Where(x => x.Time <= r.Time))
                    {
                        string sk = sg.Time.Ticks + "|" + sg.Dir + "|" + sg.Tag; if (setupLogged.Contains((liveWindow ? "" : "R|") + pn.Symbol + "|" + srcS + "|" + sk)) continue;
                        double entS = sg.Entry, stpS = !double.IsNaN(sg.Stop) ? sg.Stop : sg.StopDist > 0 ? entS - sg.Dir * sg.StopDist : double.NaN;
                        if (double.IsNaN(stpS) || Math.Abs(entS - stpS) <= 0) continue;
                        double tgtS = !double.IsNaN(sg.Target) ? sg.Target : sg.TargetDist > 0 ? entS + sg.Dir * sg.TargetDist : entS + sg.Dir * 2 * Math.Abs(entS - stpS);
                        int kindS = sg.Order == "STOP" ? 2 : sg.Order == "LIMIT" ? 1 : 0;
                        DateTime untilS = kindS == 0 ? sg.Time : sg.CancelAt == DateTime.MaxValue ? sg.Time.AddHours(2) : sg.CancelAt, exitS = sg.Exit > sg.Time ? sg.Exit : sg.Time.AddHours(4);
                        logPlayed(pn, srcS, sk, sg.Dir, sg.Time, (sg.Order == "MARKET" ? "at the signal" : sg.Order.ToLowerInvariant() + " order") + (sg.Tier != "" ? " • grade " + sg.Tier : ""), entS, stpS, tgtS, playOut(r.Bars, sg.Time, untilS, exitS, r.Time, sg.Dir, kindS, entS, stpS, tgtS));
                    }
                }
                // a MATCHES entry waiting for its outcome: price back to the entry within 30 min, then target / stop, out after 60 min
                {
                    Tuple<DateTime, int, double, double, double> mp;
                    if (!pn.IsSplit && matchPending.TryGetValue(pn.Symbol, out mp))
                    {
                        var resM = playOut(r.Bars, mp.Item1, mp.Item1.AddMinutes(30), mp.Item1.AddMinutes(60), r.Time, mp.Item2, 1, mp.Item3, mp.Item4, mp.Item5);
                        if (resM != null) { logPlayed(pn, "MATCHES", mp.Item1.Ticks.ToString(), mp.Item2, mp.Item1, "pullback limit", mp.Item3, mp.Item4, mp.Item5, resM); matchPending.Remove(pn.Symbol); }
                    }
                }
                foreach (var sg in pn.Signals.Where(x => x.Time <= r.Time && !cleanChart && (!liveWindow || layerOf("SETUPS", KeystoneLiveTools.Always) != KeystoneLiveTools.Off) && (!onlyNew || x.Time >= setupsFrom) && (!liveWindow || layerOf(x.Dir > 0 ? "SETUPS.BUY" : "SETUPS.SELL", 1) == 1)))
                {
                    double sx = indexOfTime(pn, sg.Time.AddMinutes(1)); double x = xOfIndex(pn, sx); if (x < 0 || x > pn.PlotW) continue;
                    // an arrow shape (not a candle colour): cyan = buy under the entry bar, purple = sell over it, white outline
                    int ci = (int)Math.Round(sx); var eb = ci >= 0 && ci < cs.Count ? cs[ci] : null;
                    double yBase = sg.Dir > 0 ? (eb != null ? yOf(pn, eb.Low) : yOf(pn, sg.Entry)) + 6 : (eb != null ? yOf(pn, eb.High) : yOf(pn, sg.Entry)) - 6; int d = sg.Dir > 0 ? 1 : -1;
                    Brush ac = sg.Dir > 0 ? buyC : sellC; bool newest = sg == lastReached && (r.Time - sg.Time).TotalMinutes <= (liveWindow ? 5 : 3);
                    if (newest && !liveWindow)
                    {
                        // a soft breathing glow that fades out over 3 minutes of replay time
                        double age = (r.Time - sg.Time).TotalMinutes, breath = 0.5 + 0.5 * Math.Sin(DateTime.Now.TimeOfDay.TotalMilliseconds / 260.0);
                        var halo = new System.Windows.Shapes.Ellipse { Width = 34, Height = 34, Fill = ac, Opacity = (0.12 + 0.22 * breath) * (1 - age / 3.5) }; System.Windows.Controls.Canvas.SetLeft(halo, x - 17); System.Windows.Controls.Canvas.SetTop(halo, yBase + d * 9 - 17); cv.Children.Add(halo);
                    }
                    double ak = liveWindow ? 0.7 : 1, flash = 0.5 + 0.5 * Math.Sin(DateTime.Now.TimeOfDay.TotalMilliseconds / 230.0);
                    // a box arrow: green box ▲ under the candle = BUY, red box ▼ over the candle = SELL (the newest one flashes)
                    double bxs = liveWindow ? 15 : 17;
                    var arrow = new Border { Width = bxs, Height = bxs, CornerRadius = new CornerRadius(3.5), Background = ac, BorderBrush = System.Windows.Media.Brushes.Black, BorderThickness = new Thickness(1.2), Opacity = liveWindow ? (newest ? 0.45 + 0.55 * flash : 0.9) : 1,
                        Child = new TextBlock { Text = sg.Dir > 0 ? "▲" : "▼", Foreground = System.Windows.Media.Brushes.White, FontSize = bxs * 0.62, FontWeight = FontWeights.Bold, HorizontalAlignment = HorizontalAlignment.Center, VerticalAlignment = VerticalAlignment.Center } };
                    System.Windows.Controls.Canvas.SetLeft(arrow, x - bxs / 2); System.Windows.Controls.Canvas.SetTop(arrow, d > 0 ? yBase + 1 : yBase - bxs - 1); cv.Children.Add(arrow);
