            // the trade the similar moments suggest: side, stop = target = the barrier, contracts for RISK $, value per trade after costs
            Func<ReplayPane, KeystoneAnalogAnswer, double, string> simPlan = (pn, a, edge) =>
            {
                if (pn.Trader == null || pn.SimBarrier <= 0 || a.Neighbors == 0) return "";
                double pv = KeystoneMoveStudy.PointValue(pn.Symbol), cost = KeystoneMoveStudy.Cost(pn.Symbol), risk = pn.SimBarrier;
                int side; int q; double evCash; PatternPlan(a, risk, pv, cost, NumberAllowZero(riskBox, 200), Math.Max(1, Integer(maxQtyBox, 20)), out side, out q, out evCash);
                if (Math.Abs(edge) < 8 || a.Up + a.Down < 40) return "PLAN: NO TRADE • history is split here";
                if (pn.LeanStreak < PlanConfirmMinutes) return "PLAN: WAIT • lean " + (side > 0 ? "▲" : "▼") + " " + pn.LeanStreak + " of " + PlanConfirmMinutes + " minutes — a plan only when the lean holds " + PlanConfirmMinutes + " minutes in a row";
                if (evCash <= 0) return "PLAN: NO TRADE • the edge is smaller than the costs (" + Cash(q * cost) + " a round trip for " + q + ")";
                return "PLAN: " + (side > 0 ? "BUY " : "SELL ") + q + " @ " + fmt(pn.SimEntry > 0 ? pn.SimEntry : pn.Trader.Price) + " (the reading's minute close) • stop " + fmt(risk) + " pts • target " + fmt(risk) + " pts (1 : 1, 30 min) • expected " + Signed(evCash) + " a trade after costs";
            };
            Func<string> trackRecord = () =>
            {
                int n = predRight + predWrong + predNeither; if (n == 0) return "TRACK RECORD (your replays): no plan resolved yet — every plan shown is logged and checked";
                int res = predRight + predWrong;
                return "TRACK RECORD (your replays): " + n + " plans • " + predRight + " right • " + predWrong + " wrong • " + predNeither + " neither → " + (res == 0 ? 0 : 100.0 * predRight / res).ToString("0") + "% right vs " + (100 * predExpected / n).ToString("0") + "% normal";
            };
            Action renderInfo = null; renderInfo = delegate
            {
                double net = dayNet();
                if (simTime != DateTime.MinValue && active != null)
                {
                    int m = active.Tf; DateTime closeAt;
                    if (m >= 1440) closeAt = active.Trader != null && active.Trader.Bars.Count > 0 ? active.Trader.Bars[active.Trader.Bars.Count - 1].Time : simTime;
                    else closeAt = simTime.Date.AddMinutes(Math.Ceiling((simTime.TimeOfDay.TotalMinutes + 1e-6) / m) * m);
                    var left = closeAt - simTime; if (left < TimeSpan.Zero) left = TimeSpan.Zero;
