                    var pt = args.GetPosition(hit2); sp.MouseOver = true; sp.MouseX = pt.X; sp.MouseY = pt.Y;
                    if (sp.Drag == null) { var want2 = sp.HotDrag.Any(h => pt.X >= h[0] && pt.X <= h[2] && pt.Y >= h[1] && pt.Y <= h[3]) ? System.Windows.Input.Cursors.Hand : System.Windows.Input.Cursors.Cross; if (hit2.Cursor != want2) hit2.Cursor = want2; }
                    if (sp.Drag == null || sp.Trader == null) { if (!timer.IsEnabled) render(sp); return; }
                    double dx = pt.X - sp.DownX, dy = pt.Y - sp.DownY; if (Math.Abs(dx) + Math.Abs(dy) > 3) sp.Moved = true;
                    if (sp.Drag == "PAN") { sp.RightOffset = sp.Ro0 - dx / sp.Spacing; sp.Follow = sp.RightOffset > -0.5; if (sp.PriceAuto && Math.Abs(dy) > 6) { sp.PriceAuto = false; sp.PRange = sp.Pr0; } /* up/down drag works at any zoom: it switches the price scale to manual */ if (!sp.PriceAuto) sp.PCenter = sp.Pc0 + dy * sp.PRange / Math.Max(1, sp.PlotH); }
                    else if (sp.Drag == "PRICEAXIS") { sp.PriceAuto = false; sp.PCenter = sp.Pc0; sp.PRange = Math.Max(sp.Trader.Tick * 4, sp.Pr0 * Math.Exp(dy / 160.0)); }
                    else if (sp.Drag == "TIMEAXIS") { sp.Spacing = Math.Max(1.5, Math.Min(60, sp.S0 * Math.Exp(-dx / 160.0))); }
                    else if ((sp.Drag == "STOP" || sp.Drag == "TARGET") && sp.Moved) sp.DragPrice = Math.Round(priceAt(sp, pt.Y) / sp.Trader.Tick) * sp.Trader.Tick;
