                        {
                            // FVG: candle 1, then candle 3 — the gap between candle 1's wick and candle 3's wick, or a message when they overlap
                            pn.Drag = null; var cl = pn.Candles; int ci = (int)Math.Round(indexAt(pn, pt.X));
                            if (ci < 0 || ci >= cl.Count) { pn.Toast = "FVG • click ON a candle"; pn.ToastAt = DateTime.Now; render(pn); return; }
                            if (pn.FvgPick < 0) { pn.FvgPick = ci; pn.Toast = "FVG • candle 1 picked (" + tzShow(cl[ci].Time.AddMinutes(-pn.Tf)).ToString("HH:mm") + ") • now click the 3rd candle"; pn.ToastAt = DateTime.Now; render(pn); return; }
                            int a0 = Math.Min(pn.FvgPick, ci), b0 = Math.Max(pn.FvgPick, ci); pn.FvgPick = -1;
                            if (b0 - a0 != 2) { pn.Toast = "FVG • pick the 1st and the 3rd candle (exactly one candle between them) • start again"; pn.ToastAt = DateTime.Now; render(pn); return; }
                            var k1 = cl[a0]; var k3 = cl[b0]; double lo0, hi0; string kind;
                            if (k3.Low > k1.High) { lo0 = k1.High; hi0 = k3.Low; kind = "bullish"; }
                            else if (k3.High < k1.Low) { lo0 = k3.High; hi0 = k1.Low; kind = "bearish"; }
                            else { pn.Toast = "NO FVG for these candles • candle 3 overlaps candle 1 (no gap between their wicks)"; pn.ToastAt = DateTime.Now; render(pn); return; }
                            pn.Drawings.Add(new ReplayDrawing { Kind = "FVG", T1 = k1.Time, T2 = k1.Time, P1 = lo0, P2 = hi0, Color = kind == "bullish" ? "#00E5FF" : "#FF4081", Width = drawWidth, Text = kind });
                            SaveStudioDrawings(panes); pn.Toast = "FVG " + kind + " " + fmt(lo0) + " – " + fmt(hi0) + " drawn"; pn.ToastAt = DateTime.Now; pn.SetTool("CURSOR"); render(pn); return;
                        }
                        if (pn.Tool == "HLINE" || pn.Tool == "VLINE" || pn.Tool == "ARROWUP" || pn.Tool == "ARROWDN" || pn.Tool == "TEXT")
                        {
                            var nd = new ReplayDrawing { Kind = pn.Tool, T1 = at, T2 = at, P1 = px, P2 = px, Color = drawColor, Width = drawWidth };
                            if (pn.Tool == "TEXT") { nd.Text = AskStudioText(w, "TEXT ON THE CHART", "note"); if (string.IsNullOrEmpty(nd.Text)) { pn.Drag = null; return; } }
                            pn.Drawings.Add(nd); SaveStudioDrawings(panes); pn.Drag = null; pn.SetTool("CURSOR"); render(pn); return;
                        }
                        pn.Preview = new ReplayDrawing { Kind = pn.Tool, T1 = at, T2 = at, P1 = px, P2 = px, Color = drawColor, Width = drawWidth }; pn.Drag = "DRAW";
                    }
                    else
                    {
                        pn.Drag = "PAN";
                        // a drawing's grab handle: resize / reshape it (before anything else under the mouse)
                        var dh = pn.DrawHandles.LastOrDefault(h => pt.X >= h.Item1[0] && pt.X <= h.Item1[2] && pt.Y >= h.Item1[1] && pt.Y <= h.Item1[3]);
                        if (dh != null) { pn.Drag = "RESIZEDRAW"; pn.Moving = dh.Item2; pn.ResizeCode = dh.Item3; pn.Selected = dh.Item2; hit.CaptureMouse(); args.Handled = true; render(pn); return; }
                        if (r != null)
                        {
                            Func<double, bool> near = p => Math.Abs(yOf(pn, p) - pt.Y) <= 6; int dir = Math.Sign(r.Position);
                            bool onX = pt.X >= pn.PlotW - 28 && pt.X <= pn.PlotW - 4;
                            if (!tradeOkOf(pn))
                            {
                                // disarmed: nothing on the chart touches a trade or an order — drawings and scrolling still work
                                bool tradeHit = (r.Position != 0 && (Math.Abs(yOf(pn, r.AvgPrice) - pt.Y) <= 10 || (r.StopPts != 0 && near(r.AvgPrice - dir * r.StopPts)) || (r.TargetPts > 0 && near(r.AvgPrice + dir * r.TargetPts))))
                                    || r.Orders.Any(x => near(x.Price)) || (anchorOf(pn) != null && Math.Abs(yOf(pn, anchorOf(pn).Item1) - pt.Y) <= 8);
                                if (tradeHit && (onX || pt.X >= pn.PlotW - 130)) { pn.Toast = "LIVE TRADING DISABLED • press ARM REAL ORDERS to manage trades from the chart"; pn.ToastAt = DateTime.Now; pn.Drag = null; render(pn); args.Handled = true; return; }
                                var dd0 = drawingAt(pn, pt.X, pt.Y);
                                if (dd0 != null) { pn.Drag = "MOVEDRAW"; pn.Moving = dd0; pn.MoveT1 = dd0.T1; pn.MoveT2 = dd0.T2; pn.MoveP1 = dd0.P1; pn.MoveP2 = dd0.P2; pn.MoveDownTime = timeOfIndex(pn, indexAt(pn, pt.X)); pn.MoveDownPrice = priceAt(pn, pt.Y); }
                                // a stop / target / order line grabbed while disarmed: say why it does not move (no preview that snaps back)
                                if (dd0 == null && tradeHit) { pn.Toast = "LIVE TRADING DISABLED • ARM REAL ORDERS to drag the stop / target / orders"; pn.ToastAt = DateTime.Now; }
                                hit.CaptureMouse(); args.Handled = true; render(pn); return;   // disarmed: only scrolling and drawings from here
                            }
                            else if (onX && r.Position != 0 && Math.Abs(yOf(pn, r.AvgPrice) - pt.Y) <= 9)
                            {
                                pn.Drag = null; hit.ReleaseMouseCapture();
                                double netX = r.Unrealized - KeystoneMoveStudy.Cost(pn.Symbol) * Math.Abs(r.Position);
                                if (StyledConfirm(w, "CLOSE THIS TRADE?", pn.Symbol + " " + (r.Position > 0 ? "LONG " : "SHORT ") + Math.Abs(r.Position) + " @ " + fmt(r.AvgPrice) + "  •  open " + Signed(netX) + " (after fees)\n\nCloses the position at market and cancels its stop, target and every working " + pn.Symbol + " order" + (pn.Link != null ? " on " + (pn.Link.Armed ? "the REAL account." : "the real account — ARM first, it is only watching now.") : "."), "CLOSE TRADE", Red))
                                { r.CancelOrders(); r.CloseAll("CLOSED ✕"); saveFills(pn); status.Text = pn.Symbol + " TRADE CLOSED (✕) • stop / target / orders cancelled"; status.Foreground = Gold; }
                                render(pn); args.Handled = true; return;
                            }
                            if (onX && r.Position != 0 && r.StopPts != 0 && Math.Abs(yOf(pn, r.AvgPrice - dir * r.StopPts) - pt.Y) <= 9) { pn.Sl.Text = "0"; pn.Drag = null; status.Text = pn.Symbol + " STOP REMOVED"; status.Foreground = Gold; render(pn); return; }
                            if (onX && r.Position != 0 && r.TargetPts > 0 && Math.Abs(yOf(pn, r.AvgPrice + dir * r.TargetPts) - pt.Y) <= 9) { pn.Tp.Text = "0"; pn.Drag = null; status.Text = pn.Symbol + " TARGET REMOVED"; status.Foreground = Gold; render(pn); return; }
                            var ox = onX ? r.Orders.FirstOrDefault(x => Math.Abs(yOf(pn, x.Price) - pt.Y) <= 9) : null;
                            if (ox != null) { r.Orders.Remove(ox); pn.Drag = null; status.Text = pn.Symbol + " ORDER CANCELLED"; status.Foreground = Gold; render(pn); return; }
                            if (r.Position != 0 && r.StopPts != 0 && near(r.AvgPrice - dir * r.StopPts)) pn.Drag = "STOP";
                            else if (r.Position != 0 && r.TargetPts > 0 && near(r.AvgPrice + dir * r.TargetPts)) pn.Drag = "TARGET";
                            else if (r.Position != 0 && r.TargetPts <= 0 && Math.Abs(yOf(pn, r.AvgPrice) - pt.Y) <= 10 && pt.X >= pn.PlotW - 120 && pt.X <= pn.PlotW - 74) pn.Drag = "TARGET";
                            else if (r.Position != 0 && r.StopPts == 0 && Math.Abs(yOf(pn, r.AvgPrice) - pt.Y) <= 10 && pt.X >= pn.PlotW - 74 && pt.X <= pn.PlotW - 28) pn.Drag = "STOP";
                            else if (r.Position != 0 && Math.Abs(yOf(pn, r.AvgPrice) - pt.Y) <= 8) pn.Drag = "BRACKET";   // pull a TP / SL out of the position line
                            // flat with a working order: its attached stop / target (placed for real when the order fills)
                            else if (anchorOf(pn) != null && r.StopPts > 0 && near(anchorOf(pn).Item1 - anchorOf(pn).Item2 * r.StopPts)) pn.Drag = "ASTOP";
                            else if (anchorOf(pn) != null && r.TargetPts > 0 && near(anchorOf(pn).Item1 + anchorOf(pn).Item2 * r.TargetPts)) pn.Drag = "ATARGET";
                            else if (anchorOf(pn) != null && Math.Abs(yOf(pn, anchorOf(pn).Item1) - pt.Y) <= 8 && pt.X >= pn.PlotW - 120 && pt.X <= pn.PlotW - 28) pn.Drag = "ABRACKET";
                            else
                            {
                                var o = r.Orders.FirstOrDefault(x => near(x.Price)); if (o != null) { pn.Drag = "ORDER"; pn.DragOrder = o; }
                                else
                                {
                                    var dd = drawingAt(pn, pt.X, pt.Y);
                                    if (dd != null) { pn.Drag = "MOVEDRAW"; pn.Moving = dd; pn.MoveT1 = dd.T1; pn.MoveT2 = dd.T2; pn.MoveP1 = dd.P1; pn.MoveP2 = dd.P2; pn.MoveDownTime = timeOfIndex(pn, indexAt(pn, pt.X)); pn.MoveDownPrice = priceAt(pn, pt.Y); }
                                }
                            }
                        }
                    }
                    hit.CaptureMouse(); args.Handled = true;
                };
                hit.MouseMove += delegate(object sender, MouseEventArgs args)
                {
                    var pt = args.GetPosition(hit); pn.MouseOver = true; pn.MouseX = pt.X; pn.MouseY = pt.Y; var r = pn.Trader;
                    if (pn.Drag == null)
                    {
                        // clickable things on the chart: ✕ = hand, drag handles = up / down arrows
                        Func<List<double[]>, bool> over = l => l.Any(h => pt.X >= h[0] && pt.X <= h[2] && pt.Y >= h[1] && pt.Y <= h[3]);
                        var want = over(pn.DrawHandles.Select(h => h.Item1).ToList()) ? System.Windows.Input.Cursors.SizeAll : over(pn.HotX) || over(pn.InfoHot.Select(h => h.Item1).ToList()) ? System.Windows.Input.Cursors.Hand : over(pn.HotDrag) ? System.Windows.Input.Cursors.Hand : over(pn.HotNo) ? System.Windows.Input.Cursors.No : pn.Tool == "CURSOR" && drawingAt(pn, pt.X, pt.Y) != null ? System.Windows.Input.Cursors.SizeAll : System.Windows.Input.Cursors.Cross;
                        if (hit.Cursor != want) hit.Cursor = want;
                    }
                    if (pn.Drag == null || r == null) { if (!timer.IsEnabled) render(pn); return; }
                    double dx = pt.X - pn.DownX, dy = pt.Y - pn.DownY; if (Math.Abs(dx) + Math.Abs(dy) > 3) pn.Moved = true;
                    double px = Math.Round(priceAt(pn, pt.Y) / r.Tick) * r.Tick;
                    if (pn.Drag == "PAN") { pn.RightOffset = pn.Ro0 - dx / pn.Spacing; pn.Follow = pn.RightOffset > -0.5; if (pn.PriceAuto && Math.Abs(dy) > 6) { pn.PriceAuto = false; pn.PRange = pn.Pr0; } /* up/down drag works at any zoom: it switches the price scale to manual */ if (!pn.PriceAuto) pn.PCenter = pn.Pc0 + dy * pn.PRange / Math.Max(1, pn.PlotH); }
                    else if (pn.Drag == "PRICEAXIS") { pn.PriceAuto = false; pn.PCenter = pn.Pc0; pn.PRange = Math.Max(r.Tick * 4, pn.Pr0 * Math.Exp(dy / 160.0)); }
                    else if (pn.Drag == "TIMEAXIS") { pn.Spacing = Math.Max(1.5, Math.Min(60, pn.S0 * Math.Exp(-dx / 160.0))); }
                    else if (pn.Drag == "DRAW" && pn.Preview != null) { pn.Preview.T2 = timeOfIndex(pn, indexAt(pn, pt.X)); pn.Preview.P2 = px; }
                    else if ((pn.Drag == "STOP" || pn.Drag == "TARGET") && r.Position != 0 && pn.Moved) pn.DragPrice = px;   // a preview: placed on release
                    else if (pn.Drag == "ORDER" && pn.DragOrder != null) pn.DragOrder.Price = px;
                    else if ((pn.Drag == "ASTOP" || pn.Drag == "ATARGET") && pn.Moved) pn.DragPrice = px;
                    else if (pn.Drag == "ABRACKET" && pn.Moved && anchorOf(pn) != null) { var lo = anchorOf(pn); pn.Drag = lo.Item2 * (px - lo.Item1) > 0 ? "ATARGET" : "ASTOP"; pn.DragPrice = px; }
                    else if (pn.Drag == "BRACKET" && r.Position != 0 && pn.Moved) pn.Drag = Math.Sign(r.Position) * (px - r.AvgPrice) > 0 ? "TARGET" : "STOP";
                    else if (pn.Drag == "RESIZEDRAW" && pn.Moving != null)
                    {
                        var atR = timeOfIndex(pn, indexAt(pn, pt.X)); string rc = pn.ResizeCode; var mv0 = pn.Moving;
                        if (rc.Contains("TMIN")) { if (mv0.T1 <= mv0.T2) mv0.T1 = atR; else mv0.T2 = atR; }
                        if (rc.Contains("T1")) mv0.T1 = atR; if (rc.Contains("T2")) mv0.T2 = atR;
                        if (rc.Contains("P1")) mv0.P1 = px; if (rc.Contains("P2")) mv0.P2 = px;
                    }
                    else if (pn.Drag == "MOVEDRAW" && pn.Moving != null)
                    {
                        var dt = timeOfIndex(pn, indexAt(pn, pt.X)) - pn.MoveDownTime; double dp = Math.Round((priceAt(pn, pt.Y) - pn.MoveDownPrice) / r.Tick) * r.Tick;
                        pn.Moving.T1 = pn.MoveT1 + dt; pn.Moving.T2 = pn.MoveT2 + dt; pn.Moving.P1 = pn.MoveP1 + dp; pn.Moving.P2 = pn.MoveP2 + dp;
                    }
                    render(pn);
                };
                hit.MouseLeftButtonUp += delegate(object sender, MouseButtonEventArgs args)
                {
                    var pt = args.GetPosition(hit); var r = pn.Trader; string was = pn.Drag; pn.Drag = null; hit.ReleaseMouseCapture();
                    if (was == "DRAW" && pn.Preview != null) { if (pn.Moved) { pn.Drawings.Add(pn.Preview); SaveStudioDrawings(panes); pn.SetTool("CURSOR"); } pn.Preview = null; }
                    else if ((was == "STOP" || was == "TARGET") && r != null && r.Position != 0 && pn.Moved && pn.DragPrice > 0)
                    {
                        // place on release; refuse a stop / target the price is already through (it would close the trade at once)
                        int sgn = Math.Sign(r.Position); double p0 = pn.DragPrice; pn.DragPrice = 0;
                        if (was == "STOP")
                        {
                            double dist = -sgn * (p0 - r.AvgPrice);
                            if (sgn * (r.Price - p0) <= r.Tick) { status.Text = "STOP NOT PLACED • " + fmt(p0) + " is at or beyond the current price " + fmt(r.Price) + " — it would close the trade at once"; status.Foreground = Gold; }
                            else if (Math.Abs(dist) < r.Tick / 2) { pn.Sl.Text = (-r.Tick).ToString("0.##", CultureInfo.InvariantCulture); status.Text = pn.Symbol + " STOP AT BREAKEVEN + 1 TICK"; status.Foreground = Green; }
                            else { pn.Sl.Text = dist.ToString("0.##", CultureInfo.InvariantCulture); status.Text = pn.Symbol + (dist < 0 ? " PROFIT STOP @ " + fmt(p0) + " • locks +" + fmt(-dist) + " pts" : " STOP @ " + fmt(p0)); status.Foreground = dist < 0 ? Green : Red; }
                        }
                        else
                        {
                            double dist = sgn * (p0 - r.AvgPrice);
                            if (sgn * (p0 - r.Price) <= r.Tick || dist <= 0) { status.Text = "TARGET NOT PLACED • " + fmt(p0) + " must be beyond the current price " + fmt(r.Price) + " on the profit side"; status.Foreground = Gold; }
                            else { pn.Tp.Text = dist.ToString("0.##", CultureInfo.InvariantCulture); status.Text = pn.Symbol + " TARGET @ " + fmt(p0); status.Foreground = Green; }
                        }
                    }
                    else if ((was == "ASTOP" || was == "ATARGET") && r != null && anchorOf(pn) != null && pn.Moved && pn.DragPrice > 0)
                    {
                        var lo = anchorOf(pn); double p0 = pn.DragPrice; pn.DragPrice = 0; double dist = lo.Item2 * (p0 - lo.Item1);
                        if (was == "ASTOP") { if (dist >= 0) { status.Text = "STOP must be on the loss side of the order"; status.Foreground = Gold; } else { pn.Sl.Text = (-dist).ToString("0.##", CultureInfo.InvariantCulture); status.Text = pn.Symbol + " STOP ATTACHED " + fmt(-dist) + " pts below the order • placed for real when it fills"; status.Foreground = Red; } }
                        else { if (dist <= 0) { status.Text = "TARGET must be on the profit side of the order"; status.Foreground = Gold; } else { pn.Tp.Text = dist.ToString("0.##", CultureInfo.InvariantCulture); status.Text = pn.Symbol + " TARGET ATTACHED +" + fmt(dist) + " pts • placed for real when the order fills (one cancels the other)"; status.Foreground = Green; } }
                    }
                    else if (was == "MOVEDRAW" || was == "RESIZEDRAW") { if (pn.Moved) SaveStudioDrawings(panes); pn.Selected = pn.Moving; pn.Moving = null; status.Text = "DRAWING SELECTED • Delete = remove • drag = move • right-click = colour / width / text"; status.Foreground = Cyan; }
                    else if (was == "PAN" && !pn.Moved && pn.Selected != null) pn.Selected = null;
                    else if (was == "PAN" && !pn.Moved && r != null && pn.OrderType.SelectedIndex > 0) { pn.Price.Text = fmt(Math.Round(priceAt(pn, pt.Y) / r.Tick) * r.Tick); status.Text = pn.Symbol + " PRICE " + pn.Price.Text + " • BUY or SELL places the " + Convert.ToString(pn.OrderType.Items[pn.OrderType.SelectedIndex]) + " order"; status.Foreground = Cyan; }
                    render(pn);
                };
                hit.MouseRightButtonUp += delegate(object sender, MouseButtonEventArgs args)
                {
                    var pt = args.GetPosition(hit); var r = pn.Trader; args.Handled = true;
                    var cm = new ContextMenu(); Func<string, Action, MenuItem> mi = (h, a) => { var m = new MenuItem { Header = h }; if (a != null) m.Click += delegate { a(); }; return m; };
                    double px = r == null ? priceAt(pn, pt.Y) : Math.Round(priceAt(pn, pt.Y) / r.Tick) * r.Tick;
                    var o = r == null ? null : r.Orders.FirstOrDefault(x => Math.Abs(yOf(pn, x.Price) - pt.Y) <= 6);
                    var dHit = drawingAt(pn, pt.X, pt.Y);
                    if (!tradeOkOf(pn) && (o != null || dHit == null)) { var dis = mi("LIVE TRADING DISABLED • press ARM REAL ORDERS", null); dis.IsEnabled = false; cm.Items.Add(dis); cm.Items.Add(new Separator()); o = null; }
                    if (o != null)
                    {
                        cm.Items.Add(mi("Cancel " + o.Label + " @ " + fmt(o.Price), delegate { r.Orders.Remove(o); status.Text = pn.Symbol + " ORDER CANCELLED"; status.Foreground = Gold; render(pn); }));
                        cm.Items.Add(mi("Cancel all orders", delegate { r.CancelOrders(); render(pn); }));
                    }
                    else if (dHit != null)
                    {
                        var colors = mi("Colour", null); foreach (var hex in DrawPalette) { string hx = hex; var cmi = mi("■ " + hx, delegate { dHit.Color = hx; SaveStudioDrawings(panes); render(pn); }); cmi.Foreground = colorOf(hx); colors.Items.Add(cmi); } cm.Items.Add(colors);
                        var widths = mi("Line width", null); foreach (var wv in new[] { 1.0, 1.5, 2.5, 4.0 }) { double wvv = wv; widths.Items.Add(mi((dHit.Width == wv ? "✓ " : "") + wv.ToString("0.#", CultureInfo.InvariantCulture), delegate { dHit.Width = wvv; SaveStudioDrawings(panes); render(pn); })); } cm.Items.Add(widths);
                        cm.Items.Add(mi(string.IsNullOrEmpty(dHit.Text) ? "Add text / label…" : "Edit text…", delegate { var t = AskStudioText(w, "TEXT", string.IsNullOrEmpty(dHit.Text) ? "" : dHit.Text); if (t != null) { dHit.Text = t; SaveStudioDrawings(panes); render(pn); } }));
                        cm.Items.Add(mi("Copy (same place, then drag it)", delegate { pn.Drawings.Add(new ReplayDrawing { Kind = dHit.Kind, T1 = dHit.T1, T2 = dHit.T2, P1 = dHit.P1, P2 = dHit.P2, Color = dHit.Color, Width = dHit.Width, Text = dHit.Text }); SaveStudioDrawings(panes); render(pn); }));
                        cm.Items.Add(new Separator());
                        cm.Items.Add(mi("Delete this drawing   (Delete key)", delegate { pn.Drawings.Remove(dHit); if (pn.Selected == dHit) pn.Selected = null; SaveStudioDrawings(panes); render(pn); }));
                    }
                    else
                    {
                        if (r != null && !r.Finished && !dayBanked && tradeOkOf(pn))
                        {
                            Action<string, int> at = (type, sign) => { int keep = pn.OrderType.SelectedIndex; pn.OrderType.SelectedIndex = type == "LIMIT" ? 1 : 2; pn.Price.Text = fmt(px); ((Tuple<Action<int>, Action>)pn.Hit.Tag).Item1(sign); pn.OrderType.SelectedIndex = keep; };
                            string q = Math.Max(1, Integer(pn.Qty, 1)).ToString(CultureInfo.InvariantCulture);
                            if (px < r.Price) { cm.Items.Add(mi("Buy " + q + " LIMIT @ " + fmt(px), delegate { at("LIMIT", 1); })); cm.Items.Add(mi("Sell " + q + " STOP @ " + fmt(px), delegate { at("STOP", -1); })); }
                            else { cm.Items.Add(mi("Sell " + q + " LIMIT @ " + fmt(px), delegate { at("LIMIT", -1); })); cm.Items.Add(mi("Buy " + q + " STOP @ " + fmt(px), delegate { at("STOP", 1); })); }
                            if (r.Position != 0)
                            {
                                int dir = Math.Sign(r.Position); double dist = Math.Abs(px - r.AvgPrice); bool profitSide = dir * (px - r.AvgPrice) > 0;
                                cm.Items.Add(new Separator());
                                if (profitSide) cm.Items.Add(mi("Take profit here (" + fmt(dist) + " pts)", delegate { pn.Tp.Text = Math.Max(r.Tick, dist).ToString("0.##", CultureInfo.InvariantCulture); }));
                                else cm.Items.Add(mi("Stop loss here (" + fmt(dist) + " pts)", delegate { pn.Sl.Text = Math.Max(r.Tick, dist).ToString("0.##", CultureInfo.InvariantCulture); }));
                                if (r.StopPts != 0) cm.Items.Add(mi("Remove stop loss", delegate { pn.Sl.Text = "0"; }));
                                if (r.TargetPts > 0) cm.Items.Add(mi("Remove take profit", delegate { pn.Tp.Text = "0"; }));
                                cm.Items.Add(mi("Close position", delegate { ((Tuple<Action<int>, Action>)pn.Hit.Tag).Item2(); }));
                            }
                            if (r.Orders.Count > 0) cm.Items.Add(mi("Cancel all orders", delegate { r.CancelOrders(); render(pn); }));
                            cm.Items.Add(new Separator());
                        }
                        var draw = mi("Draw", null);
                        foreach (var td in new[] { Tuple.Create("HLINE", "Horizontal line"), Tuple.Create("VLINE", "Vertical line"), Tuple.Create("TREND", "Trend line"), Tuple.Create("RAY", "Ray"), Tuple.Create("RECT", "Rectangle"), Tuple.Create("FVG", "FVG box"), Tuple.Create("FIB", "Fibonacci retracement"), Tuple.Create("ARROWUP", "Arrow up"), Tuple.Create("ARROWDN", "Arrow down"), Tuple.Create("TEXT", "Text"), Tuple.Create("LONG", "Long position"), Tuple.Create("SHORT", "Short position") })
                        {
                            var tdd = td; draw.Items.Add(mi(td.Item2, delegate { pn.SetTool(tdd.Item1); status.Text = tdd.Item2.ToUpperInvariant() + " • " + (new[] { "HLINE", "VLINE", "ARROWUP", "ARROWDN", "TEXT" }.Contains(tdd.Item1) ? "click" : "drag") + " on the chart"; status.Foreground = Cyan; }));
                        }
                        cm.Items.Add(draw);
                        if (r != null) cm.Items.Add(mi("Horizontal line @ " + fmt(px), delegate { pn.Drawings.Add(new ReplayDrawing { Kind = "HLINE", T1 = simTime, T2 = simTime, P1 = px, P2 = px, Color = drawColor, Width = drawWidth }); SaveStudioDrawings(panes); render(pn); }));
                        var tmpl = mi("Chart template", null);
                        for (int k = 0; k < themes.Count; k++) { int kk = k; tmpl.Items.Add(mi((k == themeIndex ? "✓ " : "") + themes[k].Name, delegate { themeIndex = kk; foreach (var p2 in panes) render(p2); saveWorkspace(); })); }
