                        int days = pn.Tf >= 1440 ? 60 : pn.Tf >= 240 ? 20 : pn.Tf >= 60 ? 10 : pn.Tf >= 15 ? 5 : 3; var firstSession = KeystoneStudioStore.SessionOf(first); string folder = StudioFolder(), sym = pn.Symbol; var inst = f.Inst;
                        Action<List<KeystoneArcBar>> prepend = older =>
                        {
                            older = older.Where(b => b.Time < first).OrderBy(b => b.Time).ToList();
                            if (older.Count == 0) { pn.HistoryEnd = true; pn.LoadingOlder = false; status.Text = pn.Symbol + " • no older history available"; status.Foreground = Muted; return; }
                            var all = new List<KeystoneArcBar>(older.Count + pn.PrevBars.Count); all.AddRange(older); all.AddRange(pn.PrevBars);
                            pn.PrevBars = all; pn.PrevCandles = null; pn.PrevTf = -1; pn.PrependAdjust = true; pn.LoadingOlder = false;
