                            if (pn.WantDays > 1 && pn.PrevBars.Select(b => KeystoneStudioStore.SessionOf(b.Time)).Distinct().Count() < pn.WantDays && pn.LoadOlder != null) { pn.LoadOlder(); return; }   // the PAST DAYS picker: keep going
