                { var sp = stratSetBtn.Parent as System.Windows.Controls.Panel; if (sp != null) sp.Children.Remove(stratSetBtn); stratSetBtn.Margin = new Thickness(0, 0, 6, 4); stratSetBtn.Height = 28; stratSetBtn.FontSize = 11.5; strip.Children.Add(stratSetBtn); }
