                        if (sl.Count == 0) jp.Children.Add(new TextBlock { Text = "Nothing recorded yet: entries are saved while the chart is open with FVG ZONES, SETUPS or MATCHES on.", Foreground = Muted, FontSize = 13, Margin = new Thickness(0, 0, 0, 14) });
                        else
