                                jp.Children.Add(HelixRow(new[] { src, cell(set.Where(a0 => a0[0] == todayS)), cell(set.Where(a0 => string.CompareOrdinal(a0[0], weekS) > 0)), cell(set), tk.Count + " • " + (tk.Count > 0 ? Signed(tk.Sum(a0 => nm(a0[15]))) : "–") },
