                                jp.Children.Add(HelixRow(new[] { g.Key.Split('|')[0], g.Key.Split('|')[1], dec.Count.ToString(), cell(g), (g.Count() - dec.Count).ToString(), tk.Count + " • " + (tk.Count > 0 ? Signed(tk.Sum(a0 => nm(a0[15]))) : "–") },
