                    bool flat = open && KBox("Stop copying.\n\nClose the FOLLOWERS' open positions now?\n\nYes = flatten them • No = keep them (their stops / targets stay at the broker)", "KEYSTONE • COPIER", MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.Yes;
                    foreach (var pn in panes) { foreach (var f in pn.Followers) f.Link.Disarm("COPY STOPPED", DateTime.Now, flat); pn.Followers.Clear(); }
                    copyOn = false; copyLeader = null; if (view == "COPIER") fillCopier();
