        // ---- BACKTEST STUDIO: its own data, workspace and drawings (Documents\KeystoneArc5MResearch\Studio) ------------------
        private static string StudioFolder() { return Path.Combine(DataStoreDirectory(), "Studio"); }

        // a small "type the text" box; null = cancelled
        private string AskStudioText(Window owner, string title, string start)
        {
            var d = new KeystoneWindow { Title = title, Width = 420, Height = 170, Background = Bg, Foreground = Text, WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = owner, ResizeMode = ResizeMode.NoResize, ShowInTaskbar = false };
            var box = Input(start ?? ""); box.FontSize = 15; box.Margin = new Thickness(0, 8, 0, 10);
            var ok = Btn("OK", Green); ok.Height = 30; ok.Width = 90; ok.Margin = new Thickness(0, 0, 8, 0); var cancel = Btn("CANCEL", Card); cancel.Height = 30; cancel.Width = 90;
            string result = null; ok.Click += delegate { result = box.Text; d.Close(); }; cancel.Click += delegate { d.Close(); };
            box.KeyDown += (s2, e2) => { if (e2.Key == System.Windows.Input.Key.Enter) { result = box.Text; d.Close(); } };
            var sp = new StackPanel { Margin = new Thickness(14) }; sp.Children.Add(Txt(title, Gold, 13, FontWeights.Bold)); sp.Children.Add(box);
            var row = new WrapPanel(); row.Children.Add(ok); row.Children.Add(cancel); sp.Children.Add(row);
            d.Content = sp; box.Focus(); d.ShowDialog();
            return result;
        }

        // DATA lives in Documents\KeystoneArcData (bars, studio account / journal / workspace, news) — apart from the reports and
        // exports in Documents\KeystoneArc5MResearch, so deleting reports never deletes data. The first call moves old data over.
        private static bool dataStoreMoved; private static readonly object dataStoreLock = new object();
        private static string DataStoreDirectory()
        {
            string root = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments), "KeystoneArcData");
            lock (dataStoreLock)
            {
                if (dataStoreMoved) return root; dataStoreMoved = true;
                try
                {
                    string old = DataDirectory(); Directory.CreateDirectory(root);
                    foreach (var sub in new[] { "DataCache", "Studio" })
                    {
                        string from = Path.Combine(old, sub), to = Path.Combine(root, sub); if (!Directory.Exists(from)) continue;
                        if (!Directory.Exists(to)) { Directory.Move(from, to); continue; }
                        foreach (var f in Directory.GetFiles(from, "*", SearchOption.AllDirectories))
                        {
                            string target = Path.Combine(to, f.Substring(from.Length).TrimStart(Path.DirectorySeparatorChar)); Directory.CreateDirectory(Path.GetDirectoryName(target));
                            if (!File.Exists(target)) File.Move(f, target);
                        }
                    }
                    foreach (var name in new[] { "ReplayAccount.txt", "ReplayDays.csv", "ReplayJournal.csv" })
                    {
                        string from = Path.Combine(old, name), to = Path.Combine(root, "Studio", name);
                        if (File.Exists(from) && !File.Exists(to)) { Directory.CreateDirectory(Path.GetDirectoryName(to)); File.Move(from, to); }
                    }
                }
                catch { }
            }
            return root;
        }
        private static string LabCacheFolder() { return Path.Combine(DataStoreDirectory(), "DataCache"); }
        private static int ParseStudioInt(string text, int fallback) { int v; return int.TryParse((text ?? string.Empty).Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out v) ? v : fallback; }
        private static DateTime ParseStudioDate(string text) { DateTime d; return DateTime.TryParseExact((text ?? string.Empty).Trim(), "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out d) ? d : DateTime.MinValue; }

        private static Dictionary<string, string> ReadStudioWorkspace()
        {
            var v = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            try { string f = Path.Combine(StudioFolder(), "Workspace.txt"); if (File.Exists(f)) foreach (var l in File.ReadAllLines(f)) { int i = l.IndexOf('='); if (i > 0) v[l.Substring(0, i).Trim()] = l.Substring(i + 1).Trim(); } } catch { }
            return v;
        }
        private static void WriteStudioWorkspace(Dictionary<string, string> v)
        {
            try { Directory.CreateDirectory(StudioFolder()); File.WriteAllLines(Path.Combine(StudioFolder(), "Workspace.txt"), v.Select(kv => kv.Key + "=" + kv.Value.Replace("\n", " ")).ToArray()); } catch { }
        }

        // Drawings are kept per instrument (like TradingView): a level drawn on Monday is still there on Tuesday.
        private static List<ReplayDrawing> LoadStudioDrawings(string symbol)
        {
            var list = new List<ReplayDrawing>();
            try
            {
                string f = Path.Combine(StudioFolder(), "Drawings.txt"); if (!File.Exists(f)) return list;
                foreach (var l in File.ReadAllLines(f))
                {
                    var a = l.Split('|'); if (a.Length < 6 || !string.Equals(a[0], symbol, StringComparison.OrdinalIgnoreCase)) continue;
                    var d = new ReplayDrawing { Kind = a[1], T1 = new DateTime(long.Parse(a[2], CultureInfo.InvariantCulture)), P1 = double.Parse(a[3], CultureInfo.InvariantCulture), T2 = new DateTime(long.Parse(a[4], CultureInfo.InvariantCulture)), P2 = double.Parse(a[5], CultureInfo.InvariantCulture) };
                    if (a.Length >= 9) { d.Color = a[6]; d.Width = double.Parse(a[7], CultureInfo.InvariantCulture); d.Text = a[8].Replace("\\n", "\n"); }
                    list.Add(d);
                }
            }
            catch { }
            return list;
        }
        private static void SaveStudioDrawings(List<ReplayPane> panes)
        {
            try
            {
                Directory.CreateDirectory(StudioFolder());
                File.WriteAllLines(Path.Combine(StudioFolder(), "Drawings.txt"), panes.SelectMany(pn => pn.Drawings.Select(d => string.Join("|", pn.Symbol, d.Kind, d.T1.Ticks.ToString(CultureInfo.InvariantCulture), d.P1.ToString("R", CultureInfo.InvariantCulture), d.T2.Ticks.ToString(CultureInfo.InvariantCulture), d.P2.ToString("R", CultureInfo.InvariantCulture), d.Color, d.Width.ToString("R", CultureInfo.InvariantCulture), (d.Text ?? "").Replace("|", "/").Replace("\n", "\\n")))).ToArray());
            }
            catch { }
        }

        // The lab's loaded 1-minute bars (Step 1) are copied into the studio's store (only sessions it does not have in full).
        private string ImportLabBarsIntoStudio()
        {
            var parts = new List<string>();
            try
            {
                // the same lab bars are copied once (remembered in LabImport.txt), so opening the studio stays fast
                string sigFile = Path.Combine(StudioFolder(), "LabImport.txt"); var sigs = new Dictionary<string, string>();
                try { if (File.Exists(sigFile)) foreach (var l in File.ReadAllLines(sigFile)) { int i = l.IndexOf('='); if (i > 0) sigs[l.Substring(0, i)] = l.Substring(i + 1); } } catch { }
                bool wrote = false;
                foreach (var pair in new[] { Tuple.Create("MNQ", mnqBars), Tuple.Create("MGC", mgcBars) })
                {
                    if (pair.Item2 == null || pair.Item2.Count == 0 || !KeystoneBracket.IsOneMinute(pair.Item2)) continue;
                    string sig = pair.Item2.Count + "|" + pair.Item2[0].Time.Ticks + "|" + pair.Item2[pair.Item2.Count - 1].Time.Ticks + "|" + pair.Item2[pair.Item2.Count - 1].Close.ToString("R", CultureInfo.InvariantCulture);
                    string had; if (sigs.TryGetValue(pair.Item1, out had) && had == sig && KeystoneStudioStore.Sessions(StudioFolder(), pair.Item1).Count > 0) continue;
                    int n = KeystoneStudioStore.Merge(StudioFolder(), pair.Item1, pair.Item2.ToList()); if (n > 0) parts.Add(pair.Item1 + " +" + n + " days from the lab");
                    sigs[pair.Item1] = sig; wrote = true;
                }
                if (wrote) { Directory.CreateDirectory(StudioFolder()); File.WriteAllLines(sigFile, sigs.Select(kv => kv.Key + "=" + kv.Value).ToArray()); }
            }
            catch (Exception ex) { parts.Add("lab copy failed: " + ex.Message); }
            return string.Join(", ", parts);
        }

        // Every 1-minute file the lab saved before (DataCache), one file at a time; per session the copy with the most minutes stays.
        private static IEnumerable<List<KeystoneArcBar>> LabCacheOneMinuteFiles(string symbol)
        {
            string folder = LabCacheFolder(); if (!Directory.Exists(folder)) yield break;
            foreach (var f in new DirectoryInfo(folder).GetFiles("*.bars").OrderBy(x => x.LastWriteTimeUtc))
            {
                List<KeystoneArcBar> list = null;
                try
                {
                    using (var reader = new BinaryReader(File.OpenRead(f.FullName)))
                    {
                        var parts = reader.ReadString().Split('|');
                        if (parts.Length < 4 || !string.Equals(parts[1], symbol, StringComparison.OrdinalIgnoreCase) || parts[3] != "1") continue;
                        if (parts[0] == "store1") { int nr = reader.ReadInt32(); for (int i = 0; i < nr; i++) { reader.ReadInt64(); reader.ReadInt64(); } }
                        else if (parts[0] != "v1") continue;
                        int n = reader.ReadInt32(); list = new List<KeystoneArcBar>(n);
                        for (int i = 0; i < n; i++) list.Add(new KeystoneArcBar { Time = new DateTime(reader.ReadInt64()), Symbol = symbol, Open = reader.ReadDouble(), High = reader.ReadDouble(), Low = reader.ReadDouble(), Close = reader.ReadDouble(), Volume = reader.ReadInt64() });
                    }
                }
                catch { list = null; }
                if (list != null && list.Count > 0) yield return list;
            }
        }

        private int ImportLabCacheIntoStudio()
        {
            int total = 0;
            foreach (var sym in new[] { "MNQ", "MGC" }) foreach (var list in LabCacheOneMinuteFiles(sym)) total += KeystoneStudioStore.Merge(StudioFolder(), sym, list);
            return total;
        }

        private void ImportLabCacheIntoStudioAsync(Dispatcher dispatcher, Action<int> done)
        {
            System.Threading.ThreadPool.QueueUserWorkItem(delegate
            {
                int n = 0; try { n = ImportLabCacheIntoStudio(); } catch { }
                if (dispatcher != null) dispatcher.BeginInvoke(new Action(delegate { if (n > 0) { if (studioDataChanged != null) studioDataChanged(); if (dataLibraryRefresh != null) dataLibraryRefresh(); } if (done != null) done(n); }));
            });
        }

        // the report of a practised range: each day, the totals, the account path
        private void ShowRangeReport(List<Tuple<DateTime, int, int, double, double>> rows, List<DateTime> days, string file)
        {
            var w = new KeystoneWindow { Title = "KEYSTONE ARC • RANGE REPORT", Width = 760, Height = 720, Background = Bg, Foreground = Text, WindowStartupLocation = WindowStartupLocation.CenterScreen, ShowInTaskbar = true };
            var st = new StackPanel { Margin = new Thickness(16) };
            double net = rows.Sum(x => x.Item4), peak = double.MinValue, dd = 0, start = rows[0].Item5 - rows[0].Item4;
            foreach (var x in rows) { peak = Math.Max(peak, x.Item5); dd = Math.Max(dd, peak - x.Item5); }
            st.Children.Add(Txt("RANGE REPORT • " + days.First().ToString("yyyy-MM-dd") + " → " + days.Last().ToString("yyyy-MM-dd"), Gold, 18, FontWeights.Bold));
            st.Children.Add(new TextBlock { Text = rows.Count + " days traded of " + days.Count + " • " + Signed(net) + " • green days " + rows.Count(x => x.Item4 > 0) + " • red days " + rows.Count(x => x.Item4 < 0) + " • best " + Signed(rows.Max(x => x.Item4)) + " • worst " + Signed(rows.Min(x => x.Item4)) + "\nTrades " + rows.Sum(x => x.Item2) + " • won " + rows.Sum(x => x.Item3) + " • account " + Cash(start) + " → " + Cash(rows.Last().Item5) + " • deepest drop from a high " + Cash(dd) + (file != null ? "\nSaved: " + file : ""), Foreground = MoneyBrush(net), FontSize = 13, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 6, 0, 10) });
            foreach (var x in rows) st.Children.Add(new TextBlock { Text = x.Item1.ToString("ddd yyyy-MM-dd", CultureInfo.InvariantCulture) + "   " + x.Item2.ToString().PadLeft(3) + " trades   " + x.Item3.ToString().PadLeft(3) + " won   " + Signed(x.Item4).PadLeft(10) + "   account " + Cash(x.Item5), Foreground = MoneyBrush(x.Item4), FontFamily = new FontFamily("Consolas"), FontSize = 12.5 });
            w.Content = new ScrollViewer { Content = st, VerticalScrollBarVisibility = ScrollBarVisibility.Auto };
            AskBeforeClosing(w, "RANGE REPORT", () => "Close the RANGE REPORT? It is saved as a CSV in the studio's Ranges folder.");
            w.Show();
        }

        // the similar-moments trade: side of the lean, contracts for the $ risk, value per trade after costs (stop = target = barrier)
        private static void PatternPlan(KeystoneAnalogAnswer a, double risk, double pv, double cost, double riskDollars, int maxQty, out int side, out int qty, out double evCash)
        {
            side = a.UpShare >= a.BaseUp ? 1 : -1; double win = side > 0 ? a.Up : a.Down, loss = side > 0 ? a.Down : a.Up;
            double evR = a.Neighbors == 0 ? 0 : (win - loss) / a.Neighbors;          // +1 / −1 per resolved case, neither ≈ 0
            qty = KeystoneSetupCoach.Contracts(riskDollars, risk, pv, maxQty); evCash = qty * (evR * risk * pv - cost);
        }
        private static bool PatternPlanTakes(KeystoneAnalogAnswer a, double evCash) { return a != null && Math.Abs(100 * (a.UpShare - a.BaseUp)) >= 8 && a.Up + a.Down >= 40 && evCash > 0; }
        private const int PlanConfirmMinutes = 3;   // the same lean in this many readings in a row before a plan is shown

        // ---- MATCHES: the closest past moments of the pattern box, nearest first; a mini chart 30 min before → 30 min after --------
        private void OpenMatchViewer(string sym, KeystoneAnalogIndex idx, KeystoneAnalogAnswer ans, DateTime now, double moveNow = 0, List<KeystoneArcBar> nowBars = null, Action<List<double[]>> onGhosts = null, bool anyTime = false, Action reopenOtherSearch = null)
        {
            var w = new KeystoneWindow { Title = "KEYSTONE ARC • MATCHES • " + sym, Width = 1180, Height = 760, MinWidth = 800, MinHeight = 480, Background = Bg, Foreground = Text, WindowStartupLocation = WindowStartupLocation.CenterScreen, ShowInTaskbar = true };
            var grid = new Grid { Margin = new Thickness(10) }; grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(420) }); grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            var left = new StackPanel();
            // IF YOU ENTER NOW: what the closest past moments did next — buy vs sell, against the normal odds at this time of day
            int res = ans.Up + ans.Down; double up = res == 0 ? 0 : 100.0 * ans.Up / res, dn = res == 0 ? 0 : 100.0 * ans.Down / res, baseUp = 100 * ans.BaseUp, edge = up - baseUp;
            double pv = KeystoneMoveStudy.PointValue(sym), mv = moveNow > 0 ? moveNow : ans.AvgBarrier;
            bool lean = res >= 40 && Math.Abs(edge) >= 8; int side = edge >= 0 ? 1 : -1;
            {
                var verdict = new Border { Background = Card, CornerRadius = new CornerRadius(8), Padding = new Thickness(12, 8, 12, 10), Margin = new Thickness(0, 0, 0, 10), BorderThickness = new Thickness(0, 0, 0, 3), BorderBrush = !lean ? Muted : side > 0 ? Green : Red };
                var vs = new StackPanel(); verdict.Child = vs;
                vs.Children.Add(new TextBlock { Text = "IF YOU ENTER NOW (" + sym + ")", Foreground = Muted, FontSize = 11, FontWeight = FontWeights.Bold });
                vs.Children.Add(new TextBlock { Text = !lean ? "NO CLEAR EDGE — the closest moments split like any day: wait" : side > 0 ? "▲ BUY HAS THE EDGE" : "▼ SELL HAS THE EDGE", Foreground = !lean ? Gold : side > 0 ? Green : Red, FontSize = 18, FontWeight = FontWeights.Bold, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 2, 0, 6) });
                Func<string, double, double, Brush, FrameworkElement> bar = (label, pct, basePct, br) =>
                {
                    var g = new Grid { Margin = new Thickness(0, 2, 0, 2) }; g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(92) }); g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) }); g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(120) });
                    g.Children.Add(new TextBlock { Text = label, Foreground = Text, FontSize = 12, FontWeight = FontWeights.Bold, VerticalAlignment = VerticalAlignment.Center });
                    var track = new Grid { Height = 14 }; track.Children.Add(new Border { Background = Tint(Text, 25), CornerRadius = new CornerRadius(7) });
                    track.Children.Add(new Border { Background = br, CornerRadius = new CornerRadius(7), HorizontalAlignment = HorizontalAlignment.Left, Width = Math.Max(4, 2.2 * pct) });
                    Grid.SetColumn(track, 1); g.Children.Add(track);
                    var t = new TextBlock { Text = pct.ToString("0", CultureInfo.InvariantCulture) + "%  (normal " + basePct.ToString("0", CultureInfo.InvariantCulture) + "%)", Foreground = br, FontSize = 12, FontWeight = FontWeights.Bold, Margin = new Thickness(8, 0, 0, 0), VerticalAlignment = VerticalAlignment.Center };
                    Grid.SetColumn(t, 2); g.Children.Add(t); return g;
                };
                vs.Children.Add(bar("BUY wins", up, baseUp, Green)); vs.Children.Add(bar("SELL wins", dn, 100 - baseUp, Red));
                vs.Children.Add(new TextBlock { Text = "\"wins\" = price moved " + mv.ToString("0.##", CultureInfo.InvariantCulture) + " pts (" + Cash(mv * pv) + " a micro) your way before " + mv.ToString("0.##", CultureInfo.InvariantCulture) + " pts against, within 30 min • from " + ans.Neighbors + " closest moments, " + ans.None + " went neither way" + (res < 40 ? " • few cases: weak reading" : ""), Foreground = Muted, FontSize = 11, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 6, 0, 0) });
                left.Children.Add(verdict);
            }
            left.Children.Add(Txt("THE " + Math.Min(20, ans.Ids.Count) + " CLOSEST PAST MOMENTS", Orchid, 15, FontWeights.Bold));
            left.Children.Add(new TextBlock { Text = "Compared with " + sym + " at " + (now == DateTime.MinValue ? "now" : now.ToString("ddd yyyy-MM-dd HH:mm")) + ". The box uses the closest 100 — nearest shape first; 'closeness' 0 = identical. Click one to see it; click a candle for its details.", Foreground = Muted, FontSize = 11, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 2, 0, 8) });
            var list = new StackPanel(); left.Children.Add(new ScrollViewer { Content = list, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, Height = 440 });
            Grid.SetColumn(left, 0); grid.Children.Add(left);
            var cv = new Canvas { Background = Panel, ClipToBounds = true, Cursor = System.Windows.Input.Cursors.Hand };
            var rightCol = new DockPanel { Margin = new Thickness(10, 0, 0, 0) }; Grid.SetColumn(rightCol, 1); grid.Children.Add(rightCol);
            var bar0 = new WrapPanel { Margin = new Thickness(0, 0, 0, 6) }; DockPanel.SetDock(bar0, Dock.Top); rightCol.Children.Add(bar0); rightCol.Children.Add(cv);
            var replayBtn = Btn("▶ REPLAY THIS MATCH", Card); replayBtn.Height = 28; replayBtn.FontSize = 12; replayBtn.ToolTip = "Play what came next, candle by candle";
            var ghostNote = new TextBlock { Text = "loading the closest paths…", Foreground = Muted, FontSize = 11.5, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(10, 0, 0, 0), TextWrapping = TextWrapping.Wrap, MaxWidth = 620 };
            bar0.Children.Add(replayBtn);
            if (reopenOtherSearch != null)
            {
                var searchBtn = Btn(anyTime ? "SEARCH: ANY TIME OF DAY ▸ same time only" : "SEARCH: SAME TIME OF DAY ▸ any time", Card); searchBtn.Height = 28; searchBtn.FontSize = 11.5; searchBtn.Margin = new Thickness(6, 4, 0, 4);
                searchBtn.ToolTip = "Same time of day = only moments within 30 min of this clock time (the market behaves differently at 9:30 than at 14:00). Any time = the same candle shape at any hour of the 6 years.";
                searchBtn.Click += delegate { w.Close(); reopenOtherSearch(); };
                bar0.Children.Add(searchBtn);
            }
            bar0.Children.Add(ghostNote);
            w.Content = grid;
            int reveal = int.MaxValue; List<double[]> ghosts = null; var replayTimer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromMilliseconds(170) };
            // what the chart shows: id -1 = NOW (your chart's last 30 minutes + the next 30 still empty), else a past moment
            int curId = int.MinValue, sel = -1; List<KeystoneArcBar> curBars = null; double curSp = 1;
            Func<string, Brush, double, double, bool, UIElement> tag = (text, br, x, yy, rightAlign) =>
            {
                var b = new Border { Background = Tint(Bg, 230), BorderBrush = br, BorderThickness = new Thickness(1.2), CornerRadius = new CornerRadius(4), Padding = new Thickness(6, 2, 6, 3), Child = new TextBlock { Text = text, Foreground = br, FontSize = 11, FontWeight = FontWeights.Bold } };
                b.Measure(new Size(double.PositiveInfinity, double.PositiveInfinity)); double bw = b.DesiredSize.Width > 0 ? b.DesiredSize.Width : 7 * text.Length;
                System.Windows.Controls.Canvas.SetLeft(b, rightAlign ? x - bw : x); System.Windows.Controls.Canvas.SetTop(b, yy - 10); return b;
            };
            Action<int> show = id =>
            {
                if (id != curId) sel = -1; curId = id;
                cv.Children.Clear(); bool isNow = id == -1;
                DateTime t; DateTime sess; double barrier; List<KeystoneArcBar> bars; int o = 0;
                if (isNow)
                {
                    bars = nowBars ?? new List<KeystoneArcBar>(); t = bars.Count > 0 ? bars[bars.Count - 1].Time : now; sess = t.Date; barrier = mv;
                }
                else
                {
                    t = KeystoneAnalog.TimeOf(idx, id); sess = KeystoneAnalog.SessionOfKey(idx.DayKey[id]); barrier = idx.Barrier[id]; o = idx.Outcome[id];
                    bars = KeystoneStudioStore.Load(StudioFolder(), sym, sess, sess).Where(b => b.Time > t.AddMinutes(-31) && b.Time <= t.AddMinutes(31)).ToList();
                }
                if (bars.Count < 5) { cv.Children.Add(new TextBlock { Text = isNow ? "your chart has fewer than 5 minutes loaded" : "no saved bars for that moment", Foreground = Muted, Margin = new Thickness(20) }); return; }
                int slots = isNow ? bars.Count + 30 : bars.Count;   // NOW: room on the right for the next 30 minutes
                double W = cv.ActualWidth > 100 ? cv.ActualWidth : 700, H = cv.ActualHeight > 100 ? cv.ActualHeight : 600, top = 58, plotH = H - 92, plotW = W - 110;
                var entryBar = bars.LastOrDefault(b => b.Time <= t) ?? bars[0]; double entry = entryBar.Close; int ei = bars.IndexOf(entryBar);
                double hi = Math.Max(bars.Max(b => b.High), entry + barrier), lo = Math.Min(bars.Min(b => b.Low), entry - barrier);
                // the closest moments' next 30 minutes, scaled to today's volatility: the median path and the middle half (25–75 %)
                double[] med = null, q25 = null, q75 = null;
                if (isNow && ghosts != null && ghosts.Count >= 5)
                {
                    med = new double[31]; q25 = new double[31]; q75 = new double[31];
                    for (int k = 0; k <= 30; k++) { var vals = ghosts.Where(g => g.Length > k && !double.IsNaN(g[k])).Select(g => g[k]).OrderBy(v => v).ToList(); if (vals.Count == 0) { med[k] = q25[k] = q75[k] = double.NaN; continue; } med[k] = vals[vals.Count / 2]; q25[k] = vals[vals.Count / 4]; q75[k] = vals[Math.Min(vals.Count - 1, vals.Count * 3 / 4)]; hi = Math.Max(hi, entry + q75[k]); lo = Math.Min(lo, entry + q25[k]); }
                }
                double pad = (hi - lo) * 0.08; hi += pad; lo -= pad;
                Func<double, double> y = p => top + (hi - p) / Math.Max(1e-9, hi - lo) * plotH; double sp = plotW / slots;
                curBars = bars; curSp = sp;
                // future side shading + the "now" line
                double mx = (ei + 1) * sp;
                var shade = new System.Windows.Shapes.Rectangle { Width = Math.Max(0, plotW - mx), Height = plotH, Fill = Tint(Card, 70) }; System.Windows.Controls.Canvas.SetLeft(shade, mx); System.Windows.Controls.Canvas.SetTop(shade, top); cv.Children.Add(shade);
                // target / stop for the side with the edge (both barriers when there is none)
                int s2 = lean ? side : 0;
                foreach (var lv in new[] { Tuple.Create(entry + barrier, s2 >= 0 ? (Brush)Green : Red, s2 > 0 ? "TARGET +" : s2 < 0 ? "STOP +" : "UP +", 1), Tuple.Create(entry - barrier, s2 <= 0 ? (Brush)Red : Green, s2 > 0 ? "STOP −" : s2 < 0 ? "TARGET −" : "DOWN −", -1) })
                {
                    double ly = y(lv.Item1); var br = s2 == 0 ? (lv.Item4 > 0 ? (Brush)Cyan : Orchid) : lv.Item2;
                    cv.Children.Add(new System.Windows.Shapes.Line { X1 = 0, X2 = plotW, Y1 = ly, Y2 = ly, Stroke = br, StrokeThickness = 1.2, StrokeDashArray = new DoubleCollection { 5, 3 } });
                    double pct = lv.Item4 > 0 ? up : dn;
                    cv.Children.Add(tag(lv.Item3 + barrier.ToString("0.##", CultureInfo.InvariantCulture) + " pts (" + Cash(barrier * pv) + ") • first " + pct.ToString("0") + "%", br, plotW + 104, ly, true));
                }
                cv.Children.Add(new System.Windows.Shapes.Line { X1 = 0, X2 = plotW, Y1 = y(entry), Y2 = y(entry), Stroke = Gold, StrokeThickness = 1, StrokeDashArray = new DoubleCollection { 2, 3 } });
                cv.Children.Add(new System.Windows.Shapes.Line { X1 = mx, X2 = mx, Y1 = top, Y2 = top + plotH, Stroke = Gold, StrokeThickness = 1.5 });
                // NOW: where the closest moments went next — faint paths, the middle-half band and the median path in gold
                if (isNow && ghosts != null && med != null)
                {
                    foreach (var g in ghosts)
                    {
                        var pcol = new PointCollection(); for (int k = 0; k <= 30 && k < g.Length; k++) if (!double.IsNaN(g[k])) pcol.Add(new System.Windows.Point((ei + k) * sp + sp / 2, y(entry + g[k])));
                        double fin = g.Reverse().FirstOrDefault(v => !double.IsNaN(v)); if (pcol.Count > 1) cv.Children.Add(new System.Windows.Shapes.Polyline { Points = pcol, Stroke = fin >= 0 ? Green : Red, StrokeThickness = 1, Opacity = 0.22 });
                    }
                    var band = new PointCollection(); for (int k = 0; k <= 30; k++) if (!double.IsNaN(q75[k])) band.Add(new System.Windows.Point((ei + k) * sp + sp / 2, y(entry + q75[k]))); for (int k = 30; k >= 0; k--) if (!double.IsNaN(q25[k])) band.Add(new System.Windows.Point((ei + k) * sp + sp / 2, y(entry + q25[k])));
                    if (band.Count > 2) cv.Children.Add(new System.Windows.Shapes.Polygon { Points = band, Fill = Gold, Opacity = 0.10 });
                    var mp = new PointCollection(); for (int k = 0; k <= 30; k++) if (!double.IsNaN(med[k])) mp.Add(new System.Windows.Point((ei + k) * sp + sp / 2, y(entry + med[k])));
                    if (mp.Count > 1) { cv.Children.Add(new System.Windows.Shapes.Polyline { Points = mp, Stroke = Gold, StrokeThickness = 2.6 }); var lastM = med.Reverse().FirstOrDefault(v => !double.IsNaN(v)); cv.Children.Add(tag("median of " + ghosts.Count + " matches: " + (lastM >= 0 ? "+" : "−") + Math.Abs(lastM).ToString("0.##", CultureInfo.InvariantCulture) + " pts in 30 min (" + (lastM >= 0 ? "+" : "−") + Cash(Math.Abs(lastM) * pv) + " a micro)", Gold, mp[mp.Count - 1].X - 4, mp[mp.Count - 1].Y - 16, true)); }
                    // the usual dip before the move: where an entry made the most sense in those matches
                    int dirM = med[30] >= 0 ? 1 : -1; var dips = ghosts.Where(g => g.Length > 30 && !double.IsNaN(g[30]) && Math.Sign(g[30]) == dirM).Select(g => dirM > 0 ? g.Take(16).Where(v => !double.IsNaN(v)).DefaultIfEmpty(0).Min() : g.Take(16).Where(v => !double.IsNaN(v)).DefaultIfEmpty(0).Max()).OrderBy(v => v).ToList();
                    if (dips.Count >= 3 && Math.Abs(dips[dips.Count / 2]) >= 0.5)
                    {
