                    var b = bars[i]; double x = i * sp + sp / 2; Brush br = b.Close >= b.Open ? Green : Red;
                    if (i == sel) { var hl = new System.Windows.Shapes.Rectangle { Width = sp, Height = plotH, Fill = Tint(Gold, 40) }; System.Windows.Controls.Canvas.SetLeft(hl, i * sp); System.Windows.Controls.Canvas.SetTop(hl, top); cv.Children.Add(hl); }
                    cv.Children.Add(new System.Windows.Shapes.Line { X1 = x, X2 = x, Y1 = y(b.High), Y2 = y(b.Low), Stroke = br, StrokeThickness = 1 });
                    var body = new System.Windows.Shapes.Rectangle { Width = Math.Max(1, sp * 0.7), Height = Math.Max(1, Math.Abs(y(b.Open) - y(b.Close))), Fill = br }; System.Windows.Controls.Canvas.SetLeft(body, x - sp * 0.35); System.Windows.Controls.Canvas.SetTop(body, Math.Min(y(b.Open), y(b.Close))); cv.Children.Add(body);
                }
