        // ---- STUDIO DOWNLOADER: one background queue for the whole add-on (newest weeks first); windows only watch it ----------
        private readonly List<Tuple<string, DateTime, DateTime, int>> dlQueue = new List<Tuple<string, DateTime, DateTime, int>>();
        private int dlDone, dlTotal, dlDays; private bool dlBusy, dlStop; private Dispatcher dlDispatcher; private string dlNow = string.Empty;
        private Action dlChanged; private Action<string, Brush> dlLog;
        private static DateTime SixYearsBack() { return DateTime.Today.AddYears(-6); }
        private string StudioDownloadStatus()
        {
            if (dlBusy) return "LOADING DATA • " + dlNow + " • week " + Math.Min(dlTotal, dlDone + 1) + " of " + dlTotal + " (" + (dlTotal == 0 ? 0 : 100 * dlDone / dlTotal) + "%) • " + dlDays + " days saved • you can keep working";
            return dlTotal == 0 ? "" : (dlStop ? "STOPPED • " : "DATA LOADED • ") + dlDone + " of " + dlTotal + " weeks • " + dlDays + " days saved or improved";
        }
        private void DlNotify(string line, Brush b)
        {
            if (line != null && dlLog != null) dlLog(line, b);
            if (dlChanged != null) dlChanged();
            if (studioDataChanged != null && (!dlBusy || dlDone % 8 == 0)) studioDataChanged();
            if (dataLibraryRefresh != null && (!dlBusy || dlDone % 8 == 0)) dataLibraryRefresh();
        }
        // queues the weeks of the ranges (newest first, MNQ + MGC of a week together); -1 = already running, 0 = nothing missing
        private int StartStudioDownload(Dispatcher d, string[] syms, List<Tuple<DateTime, DateTime>> ranges, bool onlyMissing, out int skipped) { return StartStudioDownload(d, syms, ranges, onlyMissing, 0, out skipped); }
        private int StartStudioDownload(Dispatcher d, string[] syms, List<Tuple<DateTime, DateTime>> ranges, bool onlyMissing, int startAttempt, out int skipped)
        {
            skipped = 0; if (dlBusy) return -1;
            dlQueue.Clear(); dlDone = 0; dlDays = 0; dlStop = false; dlDispatcher = d;
            DateTime from = ranges.Min(r => r.Item1);
            var have = syms.ToDictionary(x => x, x => KeystoneStudioStore.Sessions(StudioFolder(), x)); var asked = syms.ToDictionary(x => x, x => KeystoneStudioStore.Requested(StudioFolder(), x));
            var weeks = ranges.SelectMany(r => KeystoneStudioStore.Weeks(r.Item1, r.Item2)).GroupBy(x => x.Item1).Select(g => g.First()).OrderByDescending(x => x.Item1).ToList();
            foreach (var wk in weeks)
                foreach (var sym in syms)
                {
                    if (onlyMissing)
                    {
                        DateTime key = KeystoneStudioStore.WeekKey(wk.Item1.AddDays(1));
                        bool complete = KeystoneStudioStore.Missing(have[sym], wk.Item1.AddDays(1).Date > from ? wk.Item1.AddDays(1).Date : from, wk.Item2.Date, FullDayMinutes).Count == 0;
                        if (complete || asked[sym].Contains(key)) { skipped++; continue; }
                    }
                    dlQueue.Add(Tuple.Create(sym, wk.Item1, wk.Item2, startAttempt));
                }
            dlTotal = dlQueue.Count; if (dlTotal == 0) return 0;
            dlBusy = true; DlNotify("START • " + string.Join(" + ", syms) + " • " + dlTotal + " weeks, newest first" + (skipped > 0 ? " (" + skipped + " already saved)" : ""), Cyan);
            DlNext(); return dlTotal;
        }
        private void StopStudioDownload() { if (dlBusy) { dlStop = true; dlNow = "stopping after this week…"; DlNotify(null, null); } }
        private void DlNext()
        {
            if (dlStop || dlQueue.Count == 0) { dlBusy = false; DlNotify((dlStop ? "STOPPED" : "DONE") + " • " + dlDone + " of " + dlTotal + " weeks • " + dlDays + " days saved or improved", dlStop ? Gold : Green); return; }
            var item = dlQueue[0]; dlQueue.RemoveAt(0); string sym = item.Item1; DateTime a = item.Item2, b = item.Item3; int attempt = item.Item4;
            dlNow = sym + " " + a.AddDays(1).ToString("yyyy-MM-dd"); DlNotify(null, null);
            FetchWeekIntoStudio(dlDispatcher, sym, a, b, attempt, (changed, days, message, ok) =>
            {
                // a thin week (roll week, or an expired contract): ask the next contract too — each day keeps its fullest copy
                var haveNow = KeystoneStudioStore.Sessions(StudioFolder(), sym); int expect = ExpectedFullDays(a, b);
                int fullNow = Enumerable.Range(1, Math.Max(0, (b.Date - a.Date).Days)).Select(k => a.Date.AddDays(k)).Count(d => { int c; return haveNow.TryGetValue(d, out c) && c >= FullDayMinutes; });
                if (ok && attempt < 2 && expect > 0 && fullNow < expect) { if (dlLog != null) dlLog(sym + " " + a.ToString("yyyy-MM-dd") + " • " + message + " • " + fullNow + " of " + expect + " full days → also the next contract", Gold); dlQueue.Insert(0, Tuple.Create(sym, a, b, attempt + 1)); DlNext(); return; }
                dlDone++; dlDays += changed;
                if (ok && b.Date < DateTime.Today) KeystoneStudioStore.MarkRequested(StudioFolder(), sym, KeystoneStudioStore.WeekKey(a.AddDays(1)));
                DlNotify(sym + " " + a.ToString("yyyy-MM-dd") + " → " + b.ToString("MM-dd") + " • " + message, !ok ? Red : days > 0 ? Green : Muted);
                DlNext();
            });
        }
        // every thin weekday (60 … 799 minutes) of every instrument → its week again on the next contracts
        private string StartRepairThin(Dispatcher d)
        {
            if (dlBusy) return "ALREADY LOADING • " + StudioDownloadStatus();
            int total = 0; var parts = new List<string>();
            foreach (var sym in new[] { "MNQ", "MGC" })
            {
                var thin = KeystoneStudioStore.Sessions(StudioFolder(), sym).Where(kv => kv.Value >= 60 && kv.Value < FullDayMinutes && kv.Key.DayOfWeek != DayOfWeek.Saturday && kv.Key.DayOfWeek != DayOfWeek.Sunday).Select(kv => kv.Key).ToList();
                parts.Add(sym + " " + thin.Count + " thin days"); total += thin.Count;
            }
            if (total == 0) return "NO THIN DAYS • every saved weekday has 800+ minutes";
            var ranges = new List<Tuple<DateTime, DateTime>>(); int skipped;
            foreach (var sym in new[] { "MNQ", "MGC" })
                foreach (var day in KeystoneStudioStore.Sessions(StudioFolder(), sym).Where(kv => kv.Value >= 60 && kv.Value < FullDayMinutes && kv.Key.DayOfWeek != DayOfWeek.Saturday && kv.Key.DayOfWeek != DayOfWeek.Sunday).Select(kv => kv.Key))
                    ranges.Add(Tuple.Create(day, day));
            int n = StartStudioDownload(d, new[] { "MNQ", "MGC" }, ranges, false, 1, out skipped);
            return "REPAIRING • " + string.Join(", ", parts) + " • " + n + " week requests on the next contracts (each day keeps its fullest copy)";
        }
        // SEND DATA TO CLAUDE: three folders (GitHub takes up to 100 files per upload), each holding a "data" folder to drag in
        private const string ClaudeUploadUrl = "https://github.com/GSkopje10/KeyStone--NinjaTrader/upload/claude/chat-evidence-redesign-y226k7";
        private static string PrepareDataForClaude()
        {
            string root = Path.Combine(DataStoreDirectory(), "ForClaude"); if (Directory.Exists(root)) Directory.Delete(root, true);
            // every file to send, with its path inside the repo
            var items = new List<Tuple<string, string>>();
            foreach (var sym in new[] { "MNQ", "MGC" })
            {
                string dir = Path.Combine(StudioFolder(), sym); if (!Directory.Exists(dir)) continue;
                foreach (var f in Directory.GetFiles(dir, "*.bars").OrderBy(x => x)) items.Add(Tuple.Create(f, "data/" + sym + "/" + Path.GetFileName(f) + ".gz"));
            }
            foreach (var f in new[] { Path.Combine(StudioFolder(), "PredictionLog.csv"), Path.Combine(StudioFolder(), "ReplayDays.csv"), Path.Combine(StudioFolder(), "ReplayJournal.csv"), NewsFile() }) if (File.Exists(f)) items.Add(Tuple.Create(f, "data/logs/" + Path.GetFileName(f) + ".gz"));
            foreach (var dirName in new[] { Path.Combine(DataStoreDirectory(), "PatternLab"), BlsSavedFolder(), Path.Combine(StudioFolder(), "Ranges") })
                if (Directory.Exists(dirName)) foreach (var f in Directory.GetFiles(dirName)) items.Add(Tuple.Create(f, "data/logs/" + Path.GetFileName(dirName) + "/" + Path.GetFileName(f) + ".gz"));
            // compress each file (gzip) into parts of at most 20 MB and 90 files — GitHub's web upload takes those safely
            int part = 1, inPart = 0; long partBytes = 0, total = 0; const long cap = 20L * 1024 * 1024;
            foreach (var it in items)
            {
                string dst = Path.Combine(root, "PART " + part.ToString("00"), it.Item2.Replace('/', Path.DirectorySeparatorChar));
                Directory.CreateDirectory(Path.GetDirectoryName(dst));
                using (var input = File.OpenRead(it.Item1)) using (var output = File.Create(dst)) using (var gz = new System.IO.Compression.GZipStream(output, System.IO.Compression.CompressionMode.Compress)) input.CopyTo(gz);
                long size = new FileInfo(dst).Length; total += size; partBytes += size; inPart++;
                if (partBytes >= cap || inPart >= 90) { part++; partBytes = 0; inPart = 0; }
            }
            int parts = Directory.Exists(root) ? Directory.GetDirectories(root).Length : 0;
            File.WriteAllText(Path.Combine(root, "READ ME.txt"), "For each PART folder in order: open it, drag its folder 'data' onto " + ClaudeUploadUrl + " and press Commit changes (directly to the claude/... branch). Then reload the page for the next part.\r\n");
            return "READY • " + items.Count + " files compressed to " + (total / 1048576.0).ToString("0", CultureInfo.InvariantCulture) + " MB in " + parts + " PART folders (" + root + ")";
        }
        private string StartSixYears(Dispatcher d)
        {
            int skipped; int n = StartStudioDownload(d, new[] { "MNQ", "MGC" }, new List<Tuple<DateTime, DateTime>> { Tuple.Create(SixYearsBack(), DateTime.Today) }, true, out skipped);
            return n < 0 ? "ALREADY LOADING • " + StudioDownloadStatus() : n == 0 ? "ALL 6 YEARS ARE SAVED ALREADY (" + skipped + " weeks)" : "LOADING ALL 6 YEARS IN THE BACKGROUND • " + n + " weeks (" + skipped + " already saved) • newest first, you can keep working";
        }

        // ---- the studio's link to NinjaTrader: one week of 1-minute bars for one instrument, saved into the studio store -----
        // Same source as the lab's loader (open chart contract when its date fits, else the dated contract of that week).
        // done(changed days, days received, message, ok) runs on the dispatcher; a request that never answers ends after 120 s.
        private readonly List<BarsRequest> studioFetchRequests = new List<BarsRequest>();
        // a normal session has ~1,380 minutes; under 800 on a weekday = a thin (rolled-over) contract → also ask the next contract
        private const int FullDayMinutes = 800;
        private static int ExpectedFullDays(DateTime a, DateTime b)
        {
            int n = 0; for (var d = a.Date.AddDays(1); d <= b.Date && d < DateTime.Today; d = d.AddDays(1)) if (d.DayOfWeek != DayOfWeek.Saturday && d.DayOfWeek != DayOfWeek.Sunday) n++;
            return n;
        }
        private void FetchWeekIntoStudio(Dispatcher disp, string sym, DateTime a, DateTime b, int attempt, Action<int, int, string, bool> done)
        {
            Action<Action> later = x => { if (disp == null) x(); else disp.BeginInvoke(x); };
            string source; Instrument inst = null; bool mgc = KeystoneMoveStudy.IsMgc(sym);
            int ahead = attempt <= 0 ? (mgc ? 10 : 14) : attempt == 1 ? (mgc ? 70 : 105) : (mgc ? 130 : 195);   // this week's contract, then the next ones (rolls)
            try { inst = ResolveDynamicInstrument(sym, a.AddDays(ahead), out source); } catch (Exception ex) { source = ex.Message; }
            if (inst == null) { done(0, 0, "NO CONTRACT • " + source, false); return; }
            string hoursSource; TradingHours hours = null; try { hours = ResolveRequestTradingHours(sym, 1, out hoursSource); } catch { }
            BarsRequest request;
            try { request = new BarsRequest(inst, a, b) { BarsPeriod = new BarsPeriod { BarsPeriodType = BarsPeriodType.Minute, Value = 1 }, TradingHours = hours, MergePolicy = MergePolicy.UseGlobalSettings }; }
            catch (Exception ex) { done(0, 0, "REQUEST ERROR • " + ex.Message, false); return; }
            bool[] finished = { false }; string instName = inst.FullName;
            lock (studioFetchRequests) studioFetchRequests.Add(request);
            DispatcherTimer watchdog = null;
            if (disp != null)
            {
                watchdog = new DispatcherTimer(DispatcherPriority.Normal, disp) { Interval = TimeSpan.FromSeconds(120) };
                watchdog.Tick += delegate { watchdog.Stop(); if (finished[0]) return; finished[0] = true; done(0, 0, instName + " • NO ANSWER FROM NINJATRADER IN 120 S", false); };
                watchdog.Start();
            }
            request.Request(delegate(BarsRequest reply, ErrorCode error, string message)
            {
                System.Threading.ThreadPool.QueueUserWorkItem(delegate
                {
                    var list = new List<KeystoneArcBar>(); string problem = null; int changed = 0;
                    try
                    {
                        if (error != ErrorCode.NoError || reply == null || reply.Bars == null) problem = error + " " + message;
                        else for (int i = 0; i < reply.Bars.Count; i++) list.Add(new KeystoneArcBar { Time = reply.Bars.GetTime(i), Symbol = sym, Open = reply.Bars.GetOpen(i), High = reply.Bars.GetHigh(i), Low = reply.Bars.GetLow(i), Close = reply.Bars.GetClose(i), Volume = reply.Bars.GetVolume(i) });
                        if (list.Count > 0) changed = KeystoneStudioStore.Merge(StudioFolder(), sym, list.Where(x => x.Time > a && x.Time <= b));
                    }
                    catch (Exception ex) { problem = ex.Message; }
                    try { if (reply != null) reply.Dispose(); } catch { }
                    lock (studioFetchRequests) studioFetchRequests.Remove(request);
                    int days = list.GroupBy(x => KeystoneStudioStore.SessionOf(x.Time)).Count(g => g.Count() >= FullDayMinutes);   // full days only
                    later(delegate
                    {
                        if (watchdog != null) watchdog.Stop(); if (finished[0]) return; finished[0] = true;
                        done(changed, days, problem == null ? instName + " • " + list.Count + " minutes, " + days + " full days, " + changed + " saved" : instName + " • ERROR " + problem, problem == null);
                    });
                });
            });
        }

        // ---- news: Documents\KeystoneArcData\News.csv (yours to edit) + built-in FOMC / payrolls --------------------------------
        private static string NewsFile() { return Path.Combine(DataStoreDirectory(), "News.csv"); }
        private static List<KeystoneNewsEvent> LoadStudioNews()
        {
            var file = new List<KeystoneNewsEvent>();
            try { if (File.Exists(NewsFile())) file = KeystoneNews.ParseCsv(File.ReadAllLines(NewsFile())); } catch { }
            return KeystoneNews.Combine(KeystoneNews.BuiltIn(new DateTime(2019, 1, 1), DateTime.Today.AddDays(400)), file);
        }
        private static DateTime NewYorkTime(DateTimeOffset at)
        {
            foreach (var id in new[] { "Eastern Standard Time", "America/New_York" })
            {
                try { return TimeZoneInfo.ConvertTime(at, TimeZoneInfo.FindSystemTimeZoneById(id)).DateTime; } catch { }
            }
            return at.ToLocalTime().DateTime;
        }
        private static int FetchForexFactoryNews(bool force)
        {
            string stamp = Path.Combine(DataStoreDirectory(), "News.fetched.txt");
            try { if (!force && File.Exists(stamp) && (DateTime.UtcNow - File.GetLastWriteTimeUtc(stamp)).TotalMinutes < 60) return 0; } catch { }
            var found = new List<KeystoneNewsEvent>();
            try { System.Net.ServicePointManager.SecurityProtocol |= (System.Net.SecurityProtocolType)3072; } catch { }
            foreach (var url in new[] { "https://nfs.faireconomy.media/ff_calendar_thisweek.json", "https://nfs.faireconomy.media/ff_calendar_nextweek.json" })
            {
                try { using (var wc = new System.Net.WebClient()) { wc.Headers.Add("User-Agent", "KeystoneArc"); found.AddRange(KeystoneNews.ParseForexFactory(wc.DownloadString(url), NewYorkTime)); } } catch { }
            }
            Directory.CreateDirectory(DataStoreDirectory()); try { File.WriteAllText(stamp, DateTime.UtcNow.ToString("o")); } catch { }
            var keep = found.Where(e => e.Currency == "USD" && (e.Impact == "HIGH" || e.Impact == "MEDIUM")).ToList(); if (keep.Count == 0) return 0;
            var have = new HashSet<string>(); try { if (File.Exists(NewsFile())) foreach (var l in File.ReadAllLines(NewsFile())) have.Add(l.Trim()); } catch { }
            var add = keep.Select(KeystoneNews.ToCsv).Where(l => !have.Contains(l)).ToList(); if (add.Count == 0) return 0;
            bool fresh = !File.Exists(NewsFile());
            File.AppendAllLines(NewsFile(), (fresh ? new[] { "# date,time (New York),currency,impact (HIGH / MEDIUM),title — add your own lines; FOMC + payrolls are built in" } : new string[0]).Concat(add));
            return add.Count;
        }
        // CPI / PPI / payrolls of every past year from the BLS release archives (on your PC; at most once a day unless forced)
        // CPI / PPI / payrolls of every past year from the BLS release archives. BLS blocks programs (403), so: 1) pages you saved
        // with your browser in Documents\KeystoneArcData\News (any .htm / .html — Ctrl+S on the three archive pages), 2) a
        // browser-like request. Returns null when nothing was due (at most once a day unless forced).
        public static readonly string[] BlsArchivePages = { "https://www.bls.gov/bls/news-release/cpi.htm", "https://www.bls.gov/bls/news-release/ppi.htm", "https://www.bls.gov/bls/news-release/empsit.htm" };
        private static string BlsSavedFolder() { return Path.Combine(DataStoreDirectory(), "News"); }
        private static List<KeystoneNewsEvent> ParseBlsAll(string html)
        {
            return KeystoneNews.ParseBlsArchive(html, "cpi", "CPI (BLS)").Concat(KeystoneNews.ParseBlsArchive(html, "ppi", "PPI (BLS)")).Concat(KeystoneNews.ParseBlsArchive(html, "empsit", "NON-FARM PAYROLLS (BLS)")).ToList();
        }
        private static string BrowserLikeGet(string url)
        {
            var req = (System.Net.HttpWebRequest)System.Net.WebRequest.Create(url);
            req.UserAgent = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/129.0 Safari/537.36";
            req.Accept = "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8";
            req.Headers.Add("Accept-Language", "en-US,en;q=0.9"); req.Headers.Add("Upgrade-Insecure-Requests", "1");
            req.Headers.Add("Sec-Fetch-Dest", "document"); req.Headers.Add("Sec-Fetch-Mode", "navigate"); req.Headers.Add("Sec-Fetch-Site", "none"); req.Headers.Add("Sec-Fetch-User", "?1");
            req.AutomaticDecompression = System.Net.DecompressionMethods.GZip | System.Net.DecompressionMethods.Deflate; req.Timeout = 20000;
            using (var resp = req.GetResponse()) using (var rd = new StreamReader(resp.GetResponseStream())) return rd.ReadToEnd();
        }
        private static string FetchBlsNewsHistory(bool force)
        {
            string stamp = Path.Combine(DataStoreDirectory(), "News.bls.txt");
            try { if (!force && File.Exists(stamp) && (DateTime.UtcNow - File.GetLastWriteTimeUtc(stamp)).TotalHours < 24) return null; } catch { }
            try { System.Net.ServicePointManager.SecurityProtocol |= (System.Net.SecurityProtocolType)3072; } catch { }
            var found = new List<KeystoneNewsEvent>(); var errors = new List<string>(); int savedFiles = 0;
            try
            {
                Directory.CreateDirectory(BlsSavedFolder());
                foreach (var f in Directory.GetFiles(BlsSavedFolder()).Where(x => x.EndsWith(".htm", StringComparison.OrdinalIgnoreCase) || x.EndsWith(".html", StringComparison.OrdinalIgnoreCase) || x.EndsWith(".txt", StringComparison.OrdinalIgnoreCase)))
                { savedFiles++; found.AddRange(ParseBlsAll(File.ReadAllText(f))); }
            }
            catch (Exception ex) { errors.Add("saved pages: " + ex.Message); }
            foreach (var url in BlsArchivePages)
            {
                string name = Path.GetFileNameWithoutExtension(url).ToUpperInvariant();
                if (found.Any(e => e.Title.StartsWith(name == "EMPSIT" ? "NON-FARM" : name))) continue;   // already in a saved page
                try { var got = ParseBlsAll(BrowserLikeGet(url)); found.AddRange(got); if (got.Count == 0) errors.Add(name + ": no dates on the page"); }
                catch (Exception ex) { errors.Add(name + ": " + (ex.Message.Contains("403") ? "BLS refuses programs (403)" : ex.Message)); }
            }
            found = found.Where(e => e.Time >= new DateTime(2018, 1, 1)).GroupBy(e => e.Time.Ticks + e.Title).Select(g => g.First()).ToList();
            try { Directory.CreateDirectory(DataStoreDirectory()); File.WriteAllText(stamp, DateTime.UtcNow.ToString("o")); } catch { }
            var have = new HashSet<string>(); try { if (File.Exists(NewsFile())) foreach (var l in File.ReadAllLines(NewsFile())) have.Add(l.Trim()); } catch { }
            var add = found.Select(KeystoneNews.ToCsv).Where(l => !have.Contains(l)).ToList();
            if (add.Count > 0) { bool fresh = !File.Exists(NewsFile()); File.AppendAllLines(NewsFile(), (fresh ? new[] { "# date,time (New York),currency,impact (HIGH / MEDIUM),title" } : new string[0]).Concat(add)); }
            int cpi = found.Count(e => e.Title.StartsWith("CPI")), ppi = found.Count(e => e.Title.StartsWith("PPI")), nfp = found.Count(e => e.Title.StartsWith("NON-FARM"));
            return "BLS HISTORY • " + cpi + " CPI, " + ppi + " PPI, " + nfp + " payrolls days (" + savedFiles + " saved pages read) • " + add.Count + " new lines in News.csv"
                + (cpi == 0 || ppi == 0 || nfp == 0 ? " • MISSING: open the BLS pages in your browser (the button does it), press Ctrl+S on each and save into " + BlsSavedFolder() + ", then press GET again" + (errors.Count > 0 ? " (" + string.Join("; ", errors) + ")" : "") : "");
        }
        private void FetchNewsAsync(Dispatcher dispatcher, Action<string> done)
        {
            System.Threading.ThreadPool.QueueUserWorkItem(delegate
            {
                int n = 0; string err = null; try { n = FetchForexFactoryNews(false); } catch (Exception ex) { err = ex.Message; }
                if (dispatcher != null && (n > 0 || err != null)) dispatcher.BeginInvoke(new Action(delegate { if (done != null) done(err ?? (n + " news added")); }));
            });
        }

