            Grid.SetColumn(left, 0); root.Children.Add(left);
            // right: the report
            var tabs = new TabControl { Background = Panel, BorderBrush = Card };
            var overview = new StackPanel { Margin = new Thickness(14) }; var tables = new StackPanel { Margin = new Thickness(14) };
            var daysGrid = new Grid { Margin = new Thickness(10) };
