            tabs.Items.Add(new TabItem { Header = "TABLES", Content = new ScrollViewer { Content = tables, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, HorizontalScrollBarVisibility = ScrollBarVisibility.Auto } });
            tabs.Items.Add(new TabItem { Header = "EVERY DAY (LABELLED)", Content = daysGrid });
