            var openBtn = Btn("OPEN THIS DAY ON THE CHART", Green); openBtn.Height = 34; openBtn.Margin = new Thickness(0, 10, 0, 0); openBtn.ToolTip = "Opens the BACKTEST STUDIO on this day (start 5 minutes before the first label). Press ▶ PLAY: the report's labels and trades appear as the replay reaches them.";
            detail.Children.Add(detailText); detail.Children.Add(openBtn);
            var detailScroll = new ScrollViewer { Content = detail, VerticalScrollBarVisibility = ScrollBarVisibility.Auto }; Grid.SetRow(detailScroll, 1); Grid.SetColumn(detailScroll, 1); daysGrid.Children.Add(detailScroll);
            w.Content = root; FitToScreen(w);

            KeystoneReport current = null; var shown = new List<KeystoneReport.Day>();
            Func<string, Brush> cellBrush = t => t.StartsWith("+") ? Green : (t.StartsWith("-") || t.StartsWith("−")) ? Red : Text;
            Func<string, Brush> dayBrush = c => c == "green" ? Green : c == "red" ? Red : c == "orange" ? Orange : c == "blue" ? Blue : Muted;
            Action fillDays = delegate
            {
                dayList.Items.Clear(); shown.Clear(); if (current == null) return;
                string f = findBox.Text.Trim(); string lab = Convert.ToString(labelBox.SelectedItem ?? "ALL DAYS");
                foreach (var d in current.Days)
                {
                    string all = d.Date.ToString("yyyy-MM-dd ddd", CultureInfo.InvariantCulture) + " " + d.Label + " " + d.Note;
                    if (f != "" && all.IndexOf(f, StringComparison.OrdinalIgnoreCase) < 0) continue;
                    if (lab != "ALL DAYS" && !d.Label.StartsWith(lab.Split('(')[0].Trim(), StringComparison.Ordinal) && d.Label.IndexOf(lab.Split('(')[0].Trim(), StringComparison.Ordinal) < 0) continue;
                    shown.Add(d);
                    dayList.Items.Add(new TextBlock { Text = d.Date.ToString("yyyy-MM-dd ddd", CultureInfo.InvariantCulture) + "   " + d.Label, Foreground = dayBrush(d.Color), FontSize = 12 });
