                    c.Children.Add(new TextBlock { Text = sm[1], Foreground = Text, FontSize = 19, FontWeight = FontWeights.Bold, TextWrapping = TextWrapping.Wrap });
                    if (sm[2] != "") c.Children.Add(new TextBlock { Text = sm[2], Foreground = Muted, FontSize = 11, TextWrapping = TextWrapping.Wrap });
                    cards.Children.Add(new Border { Background = Card, CornerRadius = new CornerRadius(6), Padding = new Thickness(12, 8, 12, 8), Margin = new Thickness(0, 0, 10, 10), Width = 300, Child = c });
                }
                overview.Children.Add(cards);
                if (current.Method != "") { overview.Children.Add(Txt("HOW IT WAS MEASURED", Cyan, 12, FontWeights.Bold)); overview.Children.Add(new TextBlock { Text = current.Method, Foreground = Text, FontSize = 12, TextWrapping = TextWrapping.Wrap, MaxWidth = 900, HorizontalAlignment = HorizontalAlignment.Left, Margin = new Thickness(0, 4, 0, 0) }); }
                foreach (var sec in current.Sections)
                {
                    tables.Children.Add(Txt(sec.Title, Gold, 15, FontWeights.Bold));
                    if (sec.Note != "") tables.Children.Add(new TextBlock { Text = sec.Note, Foreground = Muted, FontSize = 11, TextWrapping = TextWrapping.Wrap, MaxWidth = 1000, HorizontalAlignment = HorizontalAlignment.Left, Margin = new Thickness(0, 2, 0, 6) });
                    var g = new Grid { Margin = new Thickness(0, 0, 0, 18), HorizontalAlignment = HorizontalAlignment.Left };
                    for (int ci = 0; ci < sec.Columns.Count; ci++) g.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
                    for (int ri = 0; ri <= sec.Rows.Count; ri++) g.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                    for (int ci = 0; ci < sec.Columns.Count; ci++)
                    {
                        var hd = new Border { Background = Card, Padding = new Thickness(8, 4, 8, 4), Child = new TextBlock { Text = sec.Columns[ci].ToUpperInvariant(), Foreground = Muted, FontSize = 10.5, FontWeight = FontWeights.Bold, MaxWidth = ci == 0 ? 420 : 140, TextWrapping = TextWrapping.Wrap } };
                        Grid.SetRow(hd, 0); Grid.SetColumn(hd, ci); g.Children.Add(hd);
                    }
                    for (int ri = 0; ri < sec.Rows.Count; ri++)
                        for (int ci = 0; ci < Math.Min(sec.Columns.Count, sec.Rows[ri].Count); ci++)
                        {
                            string t = sec.Rows[ri][ci];
                            var cell = new Border { Background = ri % 2 == 0 ? Panel : Bg, Padding = new Thickness(8, 3, 8, 3), Child = new TextBlock { Text = t, Foreground = ci == 0 ? Text : cellBrush(t), FontSize = 12, MaxWidth = ci == 0 ? 420 : 140, TextWrapping = TextWrapping.Wrap, HorizontalAlignment = ci == 0 ? HorizontalAlignment.Left : HorizontalAlignment.Right } };
                            Grid.SetRow(cell, ri + 1); Grid.SetColumn(cell, ci); g.Children.Add(cell);
