                    tables.Children.Add(g);
                }
                foreach (var lab in current.Days.Select(d => d.Label.Split(new[] { " • " }, StringSplitOptions.None)[0]).Select(x => x.Contains("→") ? x.Substring(x.IndexOf('→') + 1).Trim() : x).Where(x => x != "").GroupBy(x => x).OrderByDescending(g2 => g2.Count()).Take(30))
                    labelBox.Items.Add(lab.Key + " (" + lab.Count() + ")");
