                var d = shown[k];
                detailText.Text = d.Date.ToString("dddd yyyy-MM-dd", CultureInfo.InvariantCulture) + "\n" + d.Label + "\n\n" + d.Note + "\n\n" + string.Join("\n", d.Fields.Select(kv => kv.Key + ": " + kv.Value))
                    + (d.Markers.Count > 0 ? "\n\nLABELS ON THE CHART\n" + string.Join("\n", d.Markers.Select(m => m.Time.ToString(@"hh\:mm") + "  " + m.Text)) : "")
                    + (d.Trades.Count > 0 ? "\n\nTRADES\n" + string.Join("\n", d.Trades.Select(t => (t.Dir > 0 ? "LONG " : "SHORT ") + t.EntryTime.ToString(@"hh\:mm") + " @ " + t.Entry.ToString("0.##", CultureInfo.InvariantCulture) + " → " + t.ExitTime.ToString(@"hh\:mm") + " @ " + t.Exit.ToString("0.##", CultureInfo.InvariantCulture) + "  " + Signed(t.Pnl) + (t.Why != "" ? "  (" + t.Why + ")" : ""))) : "");
            };
            Action openDay = delegate
            {
                int k = dayList.SelectedIndex; if (current == null || k < 0 || k >= shown.Count) { status.Text = "PICK A DAY FIRST"; status.Foreground = Gold; return; }
                if (studioShowReportDay == null) OpenReplayTrader();
                if (studioShowReportDay != null) studioShowReportDay(current, shown[k]); else { status.Text = "THE STUDIO DID NOT OPEN"; status.Foreground = Red; }
            };
            openBtn.Click += delegate { openDay(); }; dayList.MouseDoubleClick += delegate { openDay(); };
            refresh(); show();
            w.Show();
        }

