        private string IdeasDataLine()
        {
            Func<List<KeystoneArcBar>, string, string> one = (b, s) => KeystoneBracket.IsOneMinute(b) && b.Count > 0
                ? s + " 1-minute " + b.Min(x => x.Time).ToString("yyyy-MM-dd") + " → " + b.Max(x => x.Time).ToString("yyyy-MM-dd") + " (" + b.Select(x => x.Time.Date).Distinct().Count() + " days)"
                : s + " NOT LOADED";
            return "DATA: " + one(mnqBars, "MNQ") + " • " + one(mgcBars, "MGC") + " • to load: Step 1 → MICRO A DAY → BOTH → DATE RANGE (e.g. 2020-01-01 → yesterday) → confirm → REQUEST DATA → BUILD; any strategy that loads 1-minute bars works.";
        }

        private void OpenIdeasLab(bool autoRun = false)
        {
            if (ideasLab != null && ideasLab.Win != null) { ideasLab.Win.Activate(); if (autoRun && ideasLab.Run != null) ideasLab.Run(); return; }
            ideasLab = new LabState { Name = "IDEAS", GridGroup = "", GridRows = "STOP", GridCols = "TARGET" };
            var st = ideasLab; Action<string, UIElement> add; var inputs = LabInputs(out add);
            var line = Input(IdeaPresets[0][1]); ideasLineBox = line; line.Width = 900; line.FontFamily = new FontFamily("Consolas"); line.FontSize = 13;
            var pick = Select(IdeaPresets.Select(p => p[0]).ToArray()); pick.SelectedIndex = 0; pick.Width = 430;
            var meaning = new TextBlock { Foreground = Cyan, FontSize = 11.5, TextWrapping = TextWrapping.Wrap, Width = 1400, Margin = new Thickness(2, 4, 2, 0) };
            var data = new TextBlock { Text = IdeasDataLine(), Foreground = Muted, FontSize = 10.5, TextWrapping = TextWrapping.Wrap, Width = 1400, Margin = new Thickness(2, 2, 2, 0) };
            var words = new TextBlock { Text = "WORDS • MNQ MGC BOTH • AT 0930[,1000] • BUY SELL EITHER (FVG: both sides, never against an open trade) • ORB n / FADE n (n-minute opening range) • FVG n (every n-minute gap) • FILL CLOSE,25,40,50,BREAK (+ STRICT) • BE pts (stop to entry) • PARTIAL pts (half off) • DAYTARGET $ / DAYSTOP $ per account • GAP pts • SESSION ASIA,LONDON,NY,ALL or FROM 0930 TO 1100 • ACCOUNTS n (each setup → next free account) • TP pts • SL pts / NONE / C1 (beyond the FVG's 1st candle) • MGCTP / MGCSL / MGCGAP (gold; default MNQ ÷ 10) • EXIT 1555 • QTY 1,2", Foreground = Muted, FontSize = 10, TextWrapping = TextWrapping.Wrap, Width = 1400, Margin = new Thickness(2, 2, 2, 0) };
            Action explain = delegate
            {
                var idea = KeystoneIdeas.Parse(line.Text);
                if (idea.Error != "") { meaning.Text = "✖ " + idea.Error; meaning.Foreground = Red; return; }
                meaning.Text = "I WILL TEST: " + KeystoneIdeas.Describe(idea); meaning.Foreground = Cyan;
            };
            line.TextChanged += delegate { explain(); };
            pick.SelectionChanged += delegate { if (pick.SelectedIndex >= 0) line.Text = IdeaPresets[pick.SelectedIndex][1]; explain(); };
            explain();
            var presets = KeystonePropRules.Presets(); var rulesBox = Select(presets.Select(p => p.Name).ToArray()); rulesBox.SelectedIndex = 0; rulesBox.Width = 240; var evalBox = Input("120"); evalBox.Width = 60; var actBox = Input("0"); actBox.Width = 60;
            add("YOUR IDEA IN WORDS", line); add("OR START FROM ONE OF MINE", pick); add("FIRM RULES", rulesBox); add("EVALUATION $", evalBox); add("ACTIVATION $", actBox);
            add("", meaning); add("", words); add("", data);
            st.Advice = () => KeystoneIdeas.Advice(st.Rows); string pending = line.Text;
            OpenLabWindow(st, "IDEAS",
                "Type the strategy in words and press RUN: every combination of your lists is traded on the real 1-minute bars you loaded (a minute touching the stop and the target = the stop), ranked by MONEY — plain account and prop (evaluations, payouts, first payout, copy trading, years, walk-forward, flip). TRADES: click one to see that row's trades on the chart and press PLAY to replay them.",
                inputs,
                (bars, progress, cancelled, rules) =>
                {
                    DateTime f, l, sp; int d; var idea = KeystoneIdeas.Parse(pending);
                    var rows = KeystoneIdeas.Run(idea, bars, rules, progress, cancelled, out f, out l, out sp, out d);
                    return new LabState { Rows = rows, First = f, Last = l, SplitAt = sp, Days = d, Note = "IDEA: " + idea.Text + " • " + KeystoneIdeas.Describe(idea) };
                },
                () => { var r = presets[Math.Max(0, rulesBox.SelectedIndex)].Copy(); r.EvalCost = NumberAllowZero(evalBox, 120); r.Activation = NumberAllowZero(actBox, 0); return r; },
                () =>
                {
                    data.Text = IdeasDataLine(); pending = line.Text; var idea = KeystoneIdeas.Parse(pending);
                    if (idea.Error != "") return "IDEA • " + idea.Error;
                    var have = new List<string>(); if (KeystoneBracket.IsOneMinute(mnqBars)) have.Add("MNQ"); if (KeystoneBracket.IsOneMinute(mgcBars)) have.Add("MGC");
                    var missing = idea.Symbols.Where(s => !have.Contains(s)).ToList();
                    return missing.Count == idea.Symbols.Count ? "NO 1-MINUTE " + string.Join(" / ", missing) + " BARS LOADED • " + data.Text : null;
                },
                autoRun);
            if (st.Win != null) st.Win.Closed += delegate { ideaChartEvents = null; ideaChartLabel = string.Empty; };
        }

        // The idea row's trades as chart events: the evidence chart and its replay show them instead of the Step 1 ledger.
        private void ShowIdeaRowOnChart(KeystoneLabRow r, KeystoneLabTrade t)
        {
            var slot = new Dictionary<KeystoneLabTrade, int>(); for (int i = 0; i < r.Trades.Count && i < r.Slots.Count; i++) slot[r.Trades[i]] = r.Slots[i];
            ideaChartLabel = r.Label;
            ideaChartEvents = r.Trades.Select((x, i) =>
            {
                int s; bool rot = slot.TryGetValue(x, out s);
                return new KeystoneArcEvent
                {
                    Id = "IDEA|" + x.Symbol + "|" + x.EntryTime.Ticks + "|" + i, Symbol = x.Symbol, SetupClass = "IDEA", Direction = x.Dir < 0 ? "SHORT" : "LONG", StrengthTag = x.Dir < 0 ? "SELL" : "BUY",
                    ReferenceTime = x.EntryTime, TriggerTime = x.EntryTime, EntryTime = x.EntryTime, Entry = x.Entry, Stop = x.Stop, Target = x.Target, Quantity = x.Qty, StopDistance = double.IsNaN(x.Stop) ? 0 : Math.Abs(x.Entry - x.Stop),
                    ExitTime = x.ExitTime, ExitPrice = x.Exit, GrossPnl = x.Net, Outcome = x.Outcome == "TARGET" ? "WIN" : x.Outcome == "STOP" ? "LOSS" : "SESSION EXIT",
                    RiskModel = "IDEA • " + r.Label, ReviewState = "ACCEPTED", ReviewNote = "IDEAS ROW", AssignedVirtualAccount = rot ? "ACCOUNT " + (s + 1) : string.Empty, QualityTier = string.Empty
                };
            }).ToList();
            evidenceReplayKey = string.Empty;
            ShowMicroTradeOnChart(new KeystoneMicroTrade { Symbol = t.Symbol, Open = t.EntryTime });
            SetEvidenceStatus("IDEAS • " + r.Label + " • " + ideaChartEvents.Count(e => e.Symbol == t.Symbol) + " " + t.Symbol + " trades on the chart • ▶ PLAY replays the day (close the IDEAS window to go back to the Step 1 ledger)", Cyan);
        }

        private void OpenEngulfingLab(bool autoRun = false)
        {
            if (engLab != null && engLab.Win != null) { engLab.Win.Activate(); if (autoRun && engLab.Run != null) engLab.Run(); return; }
            engLab = new LabState { Name = "123 ENGULFING MATH LAB", GridGroup = "", GridRows = "TIMEFRAME", GridCols = "DIRECTION" };
            var st = engLab; Action<string, UIElement> add; var inputs = LabInputs(out add);
            Func<string, string, double, TextBox> box = (label, value, width) => { var t = Input(value); t.Width = width; t.ToolTip = label; return t; };
            var tfs = box("TIMEFRAMES (MINUTES)", "1,5,15,30,60", 120); var dirs = box("DIRECTIONS", "BUY,SELL,BOTH", 110); var strengths = box("SIGNAL: ALL, WICK, SWEEP, SWEEP+WICK", "ALL,SWEEP+WICK", 140); var runs = box("RUN OF OPPOSITE CANDLES (MINIMUM)", "2", 60);
            var mnqStart = box("MNQ FROM", "0930", 60); var mgcStart = box("MGC FROM", "0800", 60); var closeB = box("CLOSE", "1555", 60);
            var mnqTp = box("MNQ TARGETS", "25,50,100", 120); var mnqSl = box("MNQ STOPS", "25,50", 100); var mgcTp = box("MGC TARGETS", "3,5,10", 100); var mgcSl = box("MGC STOPS", "3,5", 90); var qty = box("CONTRACTS", "1", 60);
            var presets = KeystonePropRules.Presets(); var rulesBox = Select(presets.Select(p => p.Name).ToArray()); rulesBox.SelectedIndex = 0; rulesBox.Width = 240; var evalBox = box("EVALUATION $", "120", 60); var actBox = box("ACTIVATION $", "0", 60);
            add("TIMEFRAMES (MIN)", tfs); add("DIRECTIONS", dirs); add("SIGNAL", strengths); add("MIN RUN", runs); add("MNQ FROM", mnqStart); add("MGC FROM", mgcStart); add("CLOSE", closeB);
            add("MNQ TARGETS", mnqTp); add("MNQ STOPS", mnqSl); add("MGC TARGETS", mgcTp); add("MGC STOPS", mgcSl); add("CONTRACTS", qty); add("FIRM RULES", rulesBox); add("EVALUATION $", evalBox); add("ACTIVATION $", actBox);
            st.Advice = () => KeystoneEngLab.Advice(new KeystoneEngLabResult { Rows = st.Rows, Days = st.Days, First = st.First, Last = st.Last });
            Func<KeystoneEngLabGrid> grid = () => new KeystoneEngLabGrid
            {
                Timeframes = ParseNumbers(tfs.Text, 5).Select(v => (int)Math.Round(v)).Where(v => v >= 1 && v <= 240).Distinct().ToList(), Directions = ParseWords(dirs.Text, new[] { "BUY", "SELL", "BOTH" }, "BOTH"),
                Strengths = ParseWords(strengths.Text, new[] { "ALL", "WICK", "SWEEP", "SWEEP+WICK" }, "ALL"), MinRuns = ParseNumbers(runs.Text, 2).Select(v => Math.Max(1, (int)Math.Round(v))).Distinct().ToList(),
                MnqTargets = ParseNumbers(mnqTp.Text, 50).Where(v => v > 0).ToList(), MnqStops = ParseNumbers(mnqSl.Text, 25).Where(v => v > 0).ToList(), MgcTargets = ParseNumbers(mgcTp.Text, 5).Where(v => v > 0).ToList(), MgcStops = ParseNumbers(mgcSl.Text, 3).Where(v => v > 0).ToList(),
                Contracts = ParseNumbers(qty.Text, 1).Select(v => Math.Max(1, (int)Math.Round(v))).Distinct().ToList(), MnqStart = Integer(mnqStart, 930), MgcStart = Integer(mgcStart, 800), Close = Integer(closeB, 1555)
            };
            OpenLabWindow(st, "123 ENGULFING MATH LAB",
                "Every 123 engulfing signal on every timeframe you list (candles built from the loaded 1-minute bars), BUY and SELL separately and together, filtered by signal strength and run length, traded with every target × stop × contracts: in at the next minute's open after the signal candle closes, one position at a time, out at the target, the stop (first when a minute touches both) or the close. MNQ and MGC separately, plain + prop + years + walk-forward.",
                inputs,
                (bars, progress, cancelled, rules) =>
                {
                    var g = grid(); g.Symbols = new[] { "MNQ", "MGC" }.Where(s => bars.Any(b => string.Equals(b.Symbol, s, StringComparison.OrdinalIgnoreCase))).ToList();
                    var r = KeystoneEngLab.Run(bars, g, rules, progress, cancelled);
                    return new LabState { Rows = r.Rows, First = r.First, Last = r.Last, SplitAt = r.SplitAt, Days = r.Days, Cancelled = r.Cancelled, Note = "Signals found: " + string.Join(" • ", r.Signals.Select(kv => kv.Key + " " + kv.Value)) };
                },
                () => { var r = presets[Math.Max(0, rulesBox.SelectedIndex)].Copy(); r.EvalCost = NumberAllowZero(evalBox, 120); r.Activation = NumberAllowZero(actBox, 0); return r; },
                () => { var g = grid(); if (!IsValidHhmm(g.MnqStart) || !IsValidHhmm(g.MgcStart) || !IsValidHhmm(g.Close)) return "TIMES MUST BE HHMM"; if (g.Timeframes.Count == 0 || g.MnqTargets.Count == 0 || g.MgcTargets.Count == 0 || g.MnqStops.Count == 0 || g.MgcStops.Count == 0) return "CHECK THE LISTS"; return null; },
                autoRun);
        }

        // ---- ASIAN MATH LAB window: every combination on the loaded bars, prop accounts, advice, apply to the lab --------
        private Window asianLabWindow; private KeystoneAsianLabResult asianLabResult; private KeystoneAsianLabRow asianLabSelected; private TabControl asianLabTabs; private TextBlock asianLabStatus;
        private string asianLabFilter = "ALL", asianLabSort = "PROP"; private bool asianLabCancel; private KeystonePropRules asianLabRules = new KeystonePropRules(); private Action asianLabRun;

        private static List<double> ParseNumbers(string text, double fallback)
        {
            var list = new List<double>();
            foreach (string part in (text ?? string.Empty).Split(new[] { ',', ';', ' ' }, StringSplitOptions.RemoveEmptyEntries)) { double v; if (double.TryParse(part, NumberStyles.Any, CultureInfo.InvariantCulture, out v) && v >= 0) list.Add(v); }
            if (list.Count == 0) list.Add(fallback);
            return list.Distinct().ToList();
        }
        private static List<string> ParseWords(string text, string[] allowed, string fallback)
        {
            var list = (text ?? string.Empty).ToUpperInvariant().Split(new[] { ',', ';', ' ' }, StringSplitOptions.RemoveEmptyEntries).Where(x => allowed.Contains(x)).Distinct().ToList();
            if (list.Count == 0) list.Add(fallback);
            return list;
        }

        private void SetAsianLabTab(string header, UIElement content)
        {
            if (asianLabTabs == null) return;
            foreach (TabItem t in asianLabTabs.Items) if (Convert.ToString(t.Header) == header) { t.Content = content; return; }
        }

