            SetAsianLabTab("COPY TRADING", MicroCopyView(r.P, asianLabRules)); SetAsianLabTab("LEGS", AsianLabLegsView(r)); SetAsianLabTab("MONTHS", MicroMonthsView(r.P));
            SetAsianLabTab("YEARS & PERIODS", AsianLabYearsView(r)); SetAsianLabTab("NIGHTS", AsianLabNightsView(r)); SetAsianLabTab("FLIP (LIVE ACCOUNT)", AsianLabFlipView(r));
            if (asianLabStatus != null) { asianLabStatus.Text = "SELECTED • " + r.Label + " • prop " + Signed(r.P.PropNet) + " • plain " + Signed(r.P.Net) + " (MNQ " + Signed(r.MnqNet) + " / MGC " + Signed(r.MgcNet) + ") • APPLY TO LAB puts it on the chart and in the pool (no reload)"; asianLabStatus.Foreground = MoneyBrush(r.P.PropNet); }
            if (jump && asianLabTabs != null) asianLabTabs.SelectedIndex = 3;
        }

        // The Asian settings in Step 1 (your setup), as a math-lab combination.
        private KeystoneArcAsianCombo MathLabMineCombo()
        {
            string scope = loadedScope == "MNQ" || loadedScope == "MGC" ? loadedScope : Convert.ToString(scopeBox == null ? "BOTH" : scopeBox.SelectedItem ?? "BOTH");
            if (scope != "MNQ" && scope != "MGC") scope = "BOTH";
            return new KeystoneArcAsianCombo
            {
                Scope = scope, MnqDirection = Convert.ToString(asianMnqDirectionBox == null ? "LONG" : asianMnqDirectionBox.SelectedItem ?? "LONG"), MgcDirection = Convert.ToString(asianMgcDirectionBox == null ? "LONG" : asianMgcDirectionBox.SelectedItem ?? "LONG"), RiskMode = "CASH",
                StartingQuantity = Math.Max(1, Integer(asianStartingQuantityBox, 1)), LegLoss = Number(asianReversalLossBox, 75), Reversals = Integer(asianMaxReversalsBox, 4), Target = Number(asianCycleTargetBox, 350),
                DailyLossLimit = asianDailyLossManual ? Number(asianDailyLossBox, 0) : 0, StartHhmm = Integer(asianStartTimeBox, 1800), EndHhmm = Integer(asianEndTimeBox, 1555)
            };
        }
        private KeystoneArcAsianCombo asianLabMine;
        private int asianLabLookback = 1;

        private UIElement AsianLabWalkView()
        {
            var root = new StackPanel { Margin = new Thickness(4) }; var res = asianLabResult; if (res == null) return root;
            var mine = KeystoneAsianLab.FindRow(res, asianLabMine);
            root.Children.Add(HelixTitle("DOES THE STRATEGY ADAPT? • WALK-FORWARD, ONE YEAR AT A TIME, NEVER LOOKING AHEAD", Gold));
            root.Children.Add(HelixNote("Every year the market moves differently. At the start of each year this picks the combination that did best on the earlier years ONLY, trades it for that year, and moves on. That is what you could really have done. If this makes money, re-tuning every year works; if only the RANKING's hindsight rows make money, the strategy is fitting the past."));
            var bar = new WrapPanel();
            bar.Children.Add(Txt("CHOOSE FROM", Muted, 11, FontWeights.Bold));
            foreach (var opt in new[] { Tuple.Create("LAST YEAR", 1), Tuple.Create("LAST 2 YEARS", 2), Tuple.Create("ALL EARLIER YEARS", 0) })
            { var o = opt; var b = Btn(o.Item1, asianLabLookback == o.Item2 ? Gold : Card); b.Height = 26; b.FontSize = 10; b.Padding = new Thickness(12, 0, 12, 0); b.Click += delegate { asianLabLookback = o.Item2; SetAsianLabTab("ADAPTS EACH YEAR?", AsianLabWalkView()); }; bar.Children.Add(b); }
            root.Children.Add(bar);
            var w = KeystoneAsianLab.WalkForward(res, asianLabRules, asianLabLookback, mine);
            var verdict = new TextBlock { Text = KeystoneAsianLab.WalkVerdict(w), Foreground = w.Adaptive.PropNet > 0 && w.YearsUp * 2 > w.Years.Count ? Green : Red, FontSize = 13, FontWeight = FontWeights.Bold, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(6, 6, 6, 6) };
            root.Children.Add(verdict);
            if (w.Years.Count == 0) return HelixScroll(root);
            var cards = new WrapPanel();
            cards.Children.Add(HelixCard("ADAPTIVE • RE-CHOSEN EVERY YEAR", Signed(w.Adaptive.PropNet), "plain " + Signed(w.Adaptive.Net) + " • " + w.Adaptive.Passed + " passed / " + w.Adaptive.Bought + " • " + w.Adaptive.Payouts + " payouts" + (w.Adaptive.Stats.HasPayout ? " • 1st payout " + w.Adaptive.Stats.CalendarDaysToFirstPayout + " d" : ""), MoneyBrush(w.Adaptive.PropNet), 300));
            if (w.Mine != null) cards.Children.Add(HelixCard("YOUR SETUP • FIXED", Signed(w.Mine.PropNet), mine.Label + " • plain " + Signed(w.Mine.Net), MoneyBrush(w.Mine.PropNet), 300));
            else cards.Children.Add(HelixCard("YOUR SETUP", "not in the lists", "add your Step 1 values to the boxes above and RUN", Muted, 260));
            if (w.BestFixed != null) cards.Children.Add(HelixCard("BEST FIXED • HINDSIGHT ONLY", Signed(w.BestFixed.PropNet), w.BestFixedRow.Label + " • known only afterwards", Muted, 300));
            root.Children.Add(cards);
            double[] cw = { 60, 380, 100, 100, 70, 70, 380, 100, 100, 100 };
            root.Children.Add(HelixHeader(new[] { "YEAR", "CHOSEN FROM THE YEARS BEFORE", "PLAIN", "PROP", "PASSED", "PAYOUTS", "BEST THAT YEAR (HINDSIGHT)", "ITS PROP", "YOURS PLAIN", "YOURS PROP" }, cw));
            foreach (var y in w.Years)
            {
                var row = HelixRow(new[] { y.Year.ToString(), y.Chosen.Label, Signed(y.ChosenPlain), Signed(y.ChosenProp), y.ChosenPassed.ToString(), y.ChosenPayouts.ToString(), y.Hindsight.Label, Signed(y.HindProp), mine == null ? "–" : Signed(y.MinePlain), mine == null ? "–" : Signed(y.MineProp) },
                    new[] { Gold, Text, MoneyBrush(y.ChosenPlain), MoneyBrush(y.ChosenProp), Green, Green, Muted, MoneyBrush(y.HindProp), MoneyBrush(y.MinePlain), MoneyBrush(y.MineProp) }, cw, MoneyBrush(y.ChosenProp), null);
                var yy = y; row.Cursor = System.Windows.Input.Cursors.Hand; row.MouseLeftButtonUp += delegate { ShowAsianLabSelected(yy.Chosen, false); };
                root.Children.Add(row);
            }
            int changes = w.Years.Skip(1).Select((y, i) => y.Chosen.Label != w.Years[i].Chosen.Label).Count(x => x);
            root.Children.Add(HelixNote("The chosen settings changed " + changes + " time" + (changes == 1 ? "" : "s") + " in " + w.Years.Count + " years; the hindsight best changed " + w.Years.Skip(1).Select((y, i) => y.Hindsight.Label != w.Years[i].Hindsight.Label).Count(x => x) + " times. Settings that keep changing mean the market rewards different things each year."));
            if (w.Adaptive.PropCurve.Count > 1) root.Children.Add(MicroChart("ADAPTIVE ACCOUNT • CASH − SPENT (one evaluation slot trading each year's choice)", w.Adaptive.PropCurve.Select(p => p.Item1).ToList(), Tuple.Create("ADAPTIVE", (Brush)Gold, w.Adaptive.PropCurve.Select(p => p.Item2).ToList())));
            return HelixScroll(root);
        }

        static List<KeystoneFlip.Unit> AsianUnits(KeystoneAsianLabRow r) { return r.Nights.OrderBy(n => n.Date).Select(n => new KeystoneFlip.Unit { Time = n.Date, Net = n.Net, Worst = Math.Min(n.Worst, n.Net) }).ToList(); }

        // FLIP for Asian: each row exactly as tested (its starting micros ARE the size; more micros = a tighter stop, not just bigger numbers).
        private UIElement AsianLabFlipView(KeystoneAsianLabRow r)
        {
            var root = new StackPanel { Margin = new Thickness(4) };
            root.Children.Add(HelixTitle("FLIP A LIVE ACCOUNT • " + r.Label, Gold));
            root.Children.Add(HelixNote("Your own account: START, every night of this row in order; at GOAL withdraw the profit and restart at START; below BUST (the night's worst open loss counts) deposit START again. The row's STARTING MICROS is the size — compare sizes with the rows below or add sizes to STARTING MICROS and RUN."));
            Action<string, UIElement> add; var inputs = LabInputs(out add);
            var sB = Input(flipStart); sB.Width = 80; var gB = Input(flipGoal); gB.Width = 80; var bB = Input(flipBust); bB.Width = 70; var go = Btn("RECALCULATE", Gold);
            add("START $", sB); add("GOAL $", gB); add("BUST BELOW $", bB); add(" ", go); root.Children.Add(inputs);
            var outPanel = new StackPanel(); root.Children.Add(outPanel);
            Action calc = delegate
            {
                flipStart = sB.Text; flipGoal = gB.Text; flipBust = bB.Text; double start = Number(sB, 500), goal = Number(gB, 1500), bust = NumberAllowZero(bB, 100);
                outPanel.Children.Clear();
                if (goal <= start || bust >= start) { outPanel.Children.Add(Txt("GOAL must be above START, BUST below START.", Red, 12, FontWeights.Bold)); return; }
                double[] w = { 420, 70, 70, 120, 120, 120, 100, 90, 90 };
                outPanel.Children.Add(HelixHeader(new[] { "ROW", "FLIPS", "BUSTS", "WITHDRAWN", "DEPOSITED", "NET CASH", "DAYS / FLIP", "REACH %", "BUST %" }, w));
                Action<KeystoneAsianLabRow, bool> line = delegate(KeystoneAsianLabRow x, bool mine)
                {
                    var f = KeystoneFlip.Run(AsianUnits(x), start, goal, bust, 0, 1);
                    var row = HelixRow(new[] { (mine ? "► " : "") + x.Label, f.Flips.ToString(), f.Busts.ToString(), Cash(f.Withdrawn), Cash(f.Deposited), Signed(f.Net), f.Flips == 0 ? "–" : f.MedianDaysPerFlip.ToString("0"), f.ReachPct.ToString("0") + "%", f.BustPct.ToString("0") + "%" },
                        new[] { mine ? Gold : Text, Green, Red, Green, Red, MoneyBrush(f.Net), Cyan, Green, Red }, w, mine ? Gold : MoneyBrush(f.Net), null);
                    var xx = x; row.Cursor = System.Windows.Input.Cursors.Hand; row.MouseLeftButtonUp += delegate { ShowAsianLabSelected(xx, false); if (asianLabTabs != null) asianLabTabs.SelectedIndex = asianLabTabs.Items.Count - 1; };
                    outPanel.Children.Add(row);
                };
                line(r, true);
                outPanel.Children.Add(HelixTitle("BEST ROWS FOR FLIPPING (top 40 plain-profitable rows)", Gold));
                foreach (var x in asianLabResult.Rows.Where(x => x.P.Net > 0 && x != r).OrderByDescending(x => x.P.Net).Take(40).OrderByDescending(x => KeystoneFlip.Run(AsianUnits(x), start, goal, bust, 0, 1).Net).Take(15)) line(x, false);
            };
            go.Click += delegate { calc(); }; calc();
            return HelixScroll(root);
        }

        private UIElement AsianLabAdviceView()
        {
            var root = new StackPanel { Margin = new Thickness(4) }; var res = asianLabResult; if (res == null) return root;
            if (res.Nights < 120) root.Children.Add(new Border { Background = Card, BorderBrush = Red, BorderThickness = new Thickness(2), Padding = new Thickness(10), Margin = new Thickness(4), Child = Txt("ONLY " + res.Nights + " NIGHTS LOADED • load several years (e.g. 2020-01-01 → yesterday) before trusting any of this.", Red, 13, FontWeights.Bold) });
            var mineRow = KeystoneAsianLab.FindRow(res, asianLabMine);
            if (mineRow != null)
            {
                var mc = HelixCard("YOUR SETUP • rank " + (res.Rows.IndexOf(mineRow) + 1) + " of " + res.Rows.Count, Signed(mineRow.P.PropNet), mineRow.Label + " • plain " + Signed(mineRow.P.Net) + " • " + mineRow.P.Passed + " passed, " + mineRow.P.Payouts + " payouts" + (mineRow.P.Stats.HasPayout ? " • 1st payout " + mineRow.P.Stats.CalendarDaysToFirstPayout + " d" : " • never paid") + " • years + " + mineRow.YearsUp + "/" + mineRow.Years, MoneyBrush(mineRow.P.PropNet), 700);
                mc.Cursor = System.Windows.Input.Cursors.Hand; mc.MouseLeftButtonUp += delegate { ShowAsianLabSelected(mineRow, true); }; root.Children.Add(mc);
            }
            root.Children.Add(HelixTitle("WHAT THE NUMBERS SAY", Gold));
            foreach (string line in KeystoneAsianLab.Advice(res)) root.Children.Add(new TextBlock { Text = "• " + line, Foreground = line.StartsWith("WARNING") || line.StartsWith("No combination") ? Red : line.StartsWith("STRONGEST") || line.StartsWith("BEST") ? Green : Text, FontSize = 12.5, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(6, 2, 6, 2) });
            if (res.Coverage.Count > 0)
            {
                root.Children.Add(HelixTitle("DATA COVERAGE • nights the cycle could open, per instrument and year", Gold));
                var yrs = res.Coverage.Select(c => c.Year).Distinct().OrderBy(y => y).ToList();
                var cw = new List<double> { 80 }; cw.AddRange(yrs.Select(y => 90.0)); var hd = new List<string> { "" }; hd.AddRange(yrs.Select(y => y.ToString()));
                root.Children.Add(HelixHeader(hd.ToArray(), cw.ToArray()));
                foreach (var g in res.Coverage.GroupBy(c => c.Symbol))
                {
                    var covCells = new List<string> { g.Key }; var cols = new List<Brush> { Gold };
                    foreach (int y in yrs) { var cv = g.FirstOrDefault(x => x.Year == y); covCells.Add(cv == null ? "0" : cv.NightsOpened + (cv.DaysWithBars > cv.NightsOpened ? " (" + (cv.DaysWithBars - cv.NightsOpened) + " no open)" : "")); cols.Add(cv == null || cv.NightsOpened < 150 ? Red : Text); }
                    root.Children.Add(HelixRow(covCells.ToArray(), cols.ToArray(), cw.ToArray(), Card, null));
                }
                root.Children.Add(HelixNote("About 250 nights per full year is normal. A red cell = that instrument's data is missing or its 18:00 opening bar was not found (\"no open\"); reload it before trusting its rows."));
            }
            root.Children.Add(HelixTitle("WHICH VALUE OF EACH SETTING WINS (all combinations with that value)", Gold));
            root.Children.Add(HelixNote("MEDIAN = the middle prop result of every combination using that value: a value that is good on the median is good in general, not just in one lucky row. FIRST PAYOUT = average days to the first payout of the rows that got paid."));
            double[] w = { 160, 90, 70, 110, 120, 120, 130, 120, 130 };
            root.Children.Add(HelixHeader(new[] { "SETTING", "VALUE", "ROWS", "PROFITABLE", "MEDIAN PROP", "BEST PROP", "FIRST PAYOUT", "ACCOUNTS LOST", "FULL-LOSS NIGHTS" }, w));
            foreach (var g in KeystoneAsianLab.Impacts(res.Rows).GroupBy(x => x.Setting))
            {
                var best = g.OrderByDescending(x => x.Median).First();
                foreach (var x in g)
                    root.Children.Add(HelixRow(new[] { x.Setting, (x == best ? "★ " : "") + x.Value, x.Rows.ToString(), x.Profitable + " (" + (100.0 * x.Profitable / Math.Max(1, x.Rows)).ToString("0") + "%)", Signed(x.Median), Signed(x.Best), x.AvgFirstPayoutDays > 0 ? x.AvgFirstPayoutDays.ToString("0") + " d" : "–", x.AvgBlowups.ToString("0.0"), x.AvgFullLossNights.ToString("0") },
                        new[] { Muted, x == best ? Gold : Text, Text, Text, MoneyBrush(x.Median), MoneyBrush(x.Best), Cyan, Red, Red }, w, x == best ? Gold : Card, null));
            }
            var cells = KeystoneAsianLab.Matrix(res.Rows); var tps = cells.Select(c => c.Target).Distinct().OrderBy(v => v).ToList();
            if (cells.Select(c => c.Reversals).Distinct().Count() > 1 || tps.Count > 1)
            {
                root.Children.Add(HelixTitle("REVERSALS × TAKE PROFIT • best prop result of each pair • accounts lost • first payout (click a cell)", Gold));
                root.Children.Add(HelixNote("Read across: a bigger take profit needs more legs to reach it. Read down: more reversals rescue more nights but one bad night costs more and blows more accounts. The best cell balances both."));
                var cw = new List<double> { 110 }; cw.AddRange(tps.Select(t => 190.0));
                var hd = new List<string> { "REVERSALS" }; hd.AddRange(tps.Select(t => "TP $" + t.ToString("0")));
                root.Children.Add(HelixHeader(hd.ToArray(), cw.ToArray()));
                var top = cells.OrderByDescending(c => c.Best.P.PropNet).First();
                foreach (var rv in cells.Select(c => c.Reversals).Distinct().OrderBy(v => v))
                {
                    var line = new WrapPanel(); line.Children.Add(new Border { Width = 110, Padding = new Thickness(6), Child = Txt(rv + " rev (" + (rv + 1) + " legs)", Gold, 11, FontWeights.Bold) });
                    foreach (double t in tps)
                    {
                        var cell = cells.FirstOrDefault(c => c.Reversals == rv && c.Target == t);
                        if (cell == null) { line.Children.Add(new Border { Width = 190 }); continue; }
                        var b = cell.Best; var st = new StackPanel();
                        st.Children.Add(Txt(Signed(b.P.PropNet), MoneyBrush(b.P.PropNet), 14, FontWeights.Bold));
                        st.Children.Add(Txt(KeystoneAsianLab.Blowups(b) + " lost • " + (b.P.Stats.HasPayout ? "1st pay " + b.P.Stats.CalendarDaysToFirstPayout + " d" : "never paid"), Text, 10, FontWeights.Normal));
                        st.Children.Add(Txt(b.Combo.Scope + " • " + b.Combo.StartingQuantity + "x • leg $" + b.Combo.LegLoss.ToString("0"), Muted, 9.5, FontWeights.Normal));
                        var bd = new Border { Width = 186, Margin = new Thickness(2), Padding = new Thickness(6, 4, 6, 4), Background = Card, BorderBrush = cell == top ? Gold : MoneyBrush(b.P.PropNet), BorderThickness = new Thickness(cell == top ? 2.5 : 1), CornerRadius = new CornerRadius(5), Child = st, Cursor = System.Windows.Input.Cursors.Hand };
                        var bb = b; bd.MouseLeftButtonUp += delegate { ShowAsianLabSelected(bb, true); };
                        line.Children.Add(bd);
                    }
                    root.Children.Add(line);
                }
            }
            return HelixScroll(root);
        }

        private UIElement AsianLabRankingView()
        {
            var root = new StackPanel { Margin = new Thickness(4) }; var res = asianLabResult; if (res == null) return root;
            var cards = new WrapPanel();
            Action<string, KeystoneAsianLabRow> card = delegate(string t, KeystoneAsianLabRow x)
            {
                if (x == null) return; var c = HelixCard(t, Signed(x.P.PropNet), x.Label + " • " + x.P.Passed + " passed, " + x.P.Payouts + " payouts" + (x.P.Stats.HasPayout ? " • 1st payout " + x.P.Stats.CalendarDaysToFirstPayout + " d" : " • never paid"), MoneyBrush(x.P.PropNet), 270);
                var xx = x; c.Cursor = System.Windows.Input.Cursors.Hand; c.MouseLeftButtonUp += delegate { ShowAsianLabSelected(xx, true); }; cards.Children.Add(c);
            };
            card("BEST FOR PROP", res.Rows.FirstOrDefault());
            card("STRONGEST • EVERY YEAR + UNSEEN 30%", res.Rows.Where(r => r.P.PropNet > 0 && r.OutSampleNet > 0 && r.YearsUp == r.Years).OrderByDescending(r => r.P.PropNet).FirstOrDefault());
            card("FASTEST FIRST PAYOUT (PROFITABLE)", res.Rows.Where(r => r.P.PropNet > 0 && r.P.Stats.HasPayout).OrderBy(r => r.P.Stats.CalendarDaysToFirstPayout).FirstOrDefault());
            foreach (string sc in new[] { "MNQ", "MGC", "BOTH" }) card("BEST " + sc, res.Rows.Where(r => r.Combo.Scope == sc).OrderByDescending(r => r.P.PropNet).FirstOrDefault());
            root.Children.Add(cards);
            var filters = new WrapPanel { Margin = new Thickness(2, 4, 2, 2) };
            foreach (string f in new[] { "ALL", "MNQ", "MGC", "BOTH", "LONG", "SHORT" })
            { string pick = f; var b = Btn(f, f == asianLabFilter ? Cyan : Card); b.Height = 26; b.FontSize = 10; b.Padding = new Thickness(12, 0, 12, 0); b.Click += delegate { asianLabFilter = pick; SetAsianLabTab("RANKING", AsianLabRankingView()); }; filters.Children.Add(b); }
            filters.Children.Add(Txt("   SORT BY", Muted, 10, FontWeights.Bold));
            foreach (string f in new[] { "PROP", "PLAIN", "FIRST PAYOUT", "PASS %", "UNSEEN 30%", "SMALLEST DD" })
            { string pick = f; var b = Btn(f, f == asianLabSort ? Gold : Card); b.Height = 26; b.FontSize = 10; b.Padding = new Thickness(12, 0, 12, 0); b.Click += delegate { asianLabSort = pick; SetAsianLabTab("RANKING", AsianLabRankingView()); }; filters.Children.Add(b); }
            root.Children.Add(filters);
            IEnumerable<KeystoneAsianLabRow> rows = res.Rows;
            if (asianLabFilter == "MNQ" || asianLabFilter == "MGC" || asianLabFilter == "BOTH") rows = rows.Where(r => r.Combo.Scope == asianLabFilter);
            else if (asianLabFilter == "LONG" || asianLabFilter == "SHORT") rows = rows.Where(r => (r.Combo.Scope == "MGC" ? r.Combo.MgcDirection : r.Combo.MnqDirection) == asianLabFilter && (r.Combo.Scope != "BOTH" || r.Combo.MgcDirection == asianLabFilter));
            rows = asianLabSort == "PLAIN" ? rows.OrderByDescending(r => r.P.Net) : asianLabSort == "FIRST PAYOUT" ? rows.OrderBy(r => r.P.Stats.HasPayout ? r.P.Stats.CalendarDaysToFirstPayout : int.MaxValue).ThenByDescending(r => r.P.PropNet)
                : asianLabSort == "PASS %" ? rows.OrderByDescending(r => r.P.PassRate) : asianLabSort == "UNSEEN 30%" ? rows.OrderByDescending(r => r.OutSampleNet) : asianLabSort == "SMALLEST DD" ? rows.OrderBy(r => r.P.MaxDrawdown) : rows.OrderByDescending(r => r.P.PropNet).ThenByDescending(r => r.P.Net);
            var list = rows.ToList();
            root.Children.Add(HelixNote("Click a row: every other tab switches to it. NIGHTS / WIN = nights in profit • TP = nights closed at the take profit • PLAIN = one account trading every night after $" + "costs • PROP = one evaluation slot in date order, a lost account replaced • UNSEEN 30% = the last 30% of nights • YEARS+ = years the prop result was positive. " + (list.Count > 300 ? "Showing the first 300 of " + list.Count + " (use the filters)." : list.Count + " rows.")));
            double[] w = { 34, 400, 60, 55, 55, 95, 85, 85, 85, 55, 60, 65, 70, 80, 100, 95, 60 };
            root.Children.Add(HelixHeader(new[] { "#", "COMBINATION", "NIGHTS", "WIN", "TP", "PLAIN NET", "MNQ", "MGC", "WORST DD", "EVALS", "PASSED", "PAYOUTS", "1ST PAY", "SPENT", "PROP NET", "UNSEEN 30%", "YEARS+" }, w));
            for (int i = 0; i < Math.Min(300, list.Count); i++)
            {
                var r = list[i];
                var row = HelixRow(new[] { (i + 1).ToString(), r.Label, r.Nights.Count.ToString(), (r.Nights.Count == 0 ? 0 : 100.0 * r.P.Wins / r.Nights.Count).ToString("0") + "%", (r.Nights.Count == 0 ? 0 : 100.0 * r.TargetNights / r.Nights.Count).ToString("0") + "%", Signed(r.P.Net), Signed(r.MnqNet), Signed(r.MgcNet), Cash(r.P.MaxDrawdown), r.P.Bought.ToString(), r.P.Passed.ToString(), r.P.Payouts.ToString(), r.P.Stats.HasPayout ? r.P.Stats.CalendarDaysToFirstPayout + " d" : "never", Cash(r.P.Spent), Signed(r.P.PropNet), Signed(r.OutSampleNet), r.YearsUp + "/" + r.Years },
                    new[] { Gold, Text, Text, Text, Cyan, MoneyBrush(r.P.Net), MoneyBrush(r.MnqNet), MoneyBrush(r.MgcNet), Red, Text, Green, Green, Cyan, Red, MoneyBrush(r.P.PropNet), MoneyBrush(r.OutSampleNet), r.YearsUp == r.Years && r.Years > 0 ? Green : Muted }, w, r == asianLabSelected ? Gold : MoneyBrush(r.P.PropNet), null);
                var rr = r; row.Cursor = System.Windows.Input.Cursors.Hand; row.MouseLeftButtonUp += delegate { ShowAsianLabSelected(rr, true); SetAsianLabTab("RANKING", AsianLabRankingView()); };
                root.Children.Add(row);
            }
            return HelixScroll(root);
        }

        private UIElement AsianLabChartsView(KeystoneAsianLabRow r)
        {
            var root = new StackPanel { Margin = new Thickness(4) };
