            root.Children.Add(MicroChart("PLAIN ACCOUNT NIGHT BY NIGHT • combined and each instrument inside the cycle (after costs)", days, series.ToArray()));
            root.Children.Add(MicroChartsView(r.P));
            return HelixScroll(root);
        }

