            {
                double net = g.Sum(x => x.Net), prop; r.P.PropByYear.TryGetValue(g.Key, out prop);
                int passed = r.P.Ledger.Where(l => l.Day.Year == g.Key).Sum(l => l.Passed), pays = r.P.Ledger.Where(l => l.Day.Year == g.Key).Sum(l => l.Payouts);
                root.Children.Add(HelixRow(new[] { g.Key.ToString(), g.Count().ToString(), (100.0 * g.Count(x => x.Target) / g.Count()).ToString("0") + "%", Signed(net), Signed(g.Sum(x => x.Mnq)), Signed(g.Sum(x => x.Mgc)), Signed(g.Min(x => x.Net)), passed.ToString(), pays.ToString(), Signed(prop) },
                    new[] { Gold, Text, Cyan, MoneyBrush(net), MoneyBrush(g.Sum(x => x.Mnq)), MoneyBrush(g.Sum(x => x.Mgc)), Red, Green, Green, MoneyBrush(prop) }, w, MoneyBrush(prop), null));
            }
            root.Children.Add(HelixTitle("EARLY 70% vs UNSEEN LAST 30% (split " + res.SplitAt.ToString("yyyy-MM-dd") + ")", Gold));
            root.Children.Add(HelixNote("The ranking used every night. A combination that only works in the early part was fitted to the past; one that also works in the last 30% is more likely real."));
            root.Children.Add(HelixRow(new[] { "EARLY 70%", Signed(r.InSampleNet) }, new[] { Gold, MoneyBrush(r.InSampleNet) }, new double[] { 200, 150 }, MoneyBrush(r.InSampleNet), null));
            root.Children.Add(HelixRow(new[] { "UNSEEN 30%", Signed(r.OutSampleNet) }, new[] { Gold, MoneyBrush(r.OutSampleNet) }, new double[] { 200, 150 }, MoneyBrush(r.OutSampleNet), null));
            // period A vs B
            root.Children.Add(HelixTitle("COMPARE TWO PERIODS (any dates inside the loaded range)", Gold));
            var bar = new WrapPanel(); var aFrom = Input(res.First.ToString("yyyy-MM-dd")); var aTo = Input(res.SplitAt.AddDays(-1).ToString("yyyy-MM-dd")); var bFrom = Input(res.SplitAt.ToString("yyyy-MM-dd")); var bTo = Input(res.Last.ToString("yyyy-MM-dd"));
            foreach (var tb in new[] { aFrom, aTo, bFrom, bTo }) tb.Width = 110;
            var go = Btn("COMPARE", Gold); var outPanel = new StackPanel();
            bar.Children.Add(Txt("A", Cyan, 12, FontWeights.Bold)); bar.Children.Add(aFrom); bar.Children.Add(aTo); bar.Children.Add(Txt("   B", Orchid, 12, FontWeights.Bold)); bar.Children.Add(bFrom); bar.Children.Add(bTo); bar.Children.Add(go);
            root.Children.Add(bar); root.Children.Add(outPanel);
            Action compare = delegate
            {
                outPanel.Children.Clear(); double[] w2 = { 90, 100, 70, 60, 110, 100, 100, 100, 70, 70, 80, 110 };
                outPanel.Children.Add(HelixHeader(new[] { "PERIOD", "FROM", "NIGHTS", "TP %", "PLAIN NET", "MNQ", "MGC", "WORST DD", "PASSED", "PAYOUTS", "1ST PAY", "PROP NET" }, w2));
                foreach (var p in new[] { Tuple.Create("A", aFrom.Text, aTo.Text, Cyan), Tuple.Create("B", bFrom.Text, bTo.Text, Orchid) })
                {
                    DateTime f, t; if (!DateTime.TryParse(p.Item2, CultureInfo.InvariantCulture, DateTimeStyles.None, out f) || !DateTime.TryParse(p.Item3, CultureInfo.InvariantCulture, DateTimeStyles.None, out t)) { outPanel.Children.Add(HelixNote("PERIOD " + p.Item1 + ": use YYYY-MM-DD")); continue; }
                    var nights = r.Nights.Where(x => x.Date >= f && x.Date <= t).ToList(); if (nights.Count == 0) { outPanel.Children.Add(HelixNote("PERIOD " + p.Item1 + ": no nights")); continue; }
                    var sub = KeystoneAsianLab.Row(r.Combo, nights, asianLabRules, DateTime.MaxValue, false, 0);
                    outPanel.Children.Add(HelixRow(new[] { p.Item1, f.ToString("yyyy-MM-dd"), nights.Count.ToString(), (100.0 * sub.TargetNights / nights.Count).ToString("0") + "%", Signed(sub.P.Net), Signed(sub.MnqNet), Signed(sub.MgcNet), Cash(sub.P.MaxDrawdown), sub.P.Passed.ToString(), sub.P.Payouts.ToString(), sub.P.Stats.HasPayout ? sub.P.Stats.CalendarDaysToFirstPayout + " d" : "never", Signed(sub.P.PropNet) },
                        new[] { p.Item4, Text, Text, Cyan, MoneyBrush(sub.P.Net), MoneyBrush(sub.MnqNet), MoneyBrush(sub.MgcNet), Red, Green, Green, Cyan, MoneyBrush(sub.P.PropNet) }, w2, p.Item4, null));
                }
            };
            go.Click += delegate { compare(); }; compare();
            return HelixScroll(root);
        }

        private UIElement AsianLabNightsView(KeystoneAsianLabRow r)
        {
            var root = new StackPanel { Margin = new Thickness(4) };
            root.Children.Add(HelixTitle(r.Label + " • EVERY NIGHT (newest first)", Gold));
            root.Children.Add(HelixNote("Click a night to open the chart on it. The chart shows the combination that is APPLIED to the lab — press APPLY TO LAB first if this is a different one (instant, no reload)."));
            bool trend = KeystoneAsianLab.IsTrend(r.Combo);
            double[] w = { 120, 140, 70, 70, 80, 100, 100, 110, 100, 100, 150, 110 };
            root.Children.Add(HelixHeader(new[] { "NIGHT", "DIRECTION", "MNQ LEGS", "MGC LEGS", "CONTRACTS", "MNQ", "MGC", "COMBINED", "LOWEST", "HIGHEST", "ENDED", "AT" }, w));
            string fixedDir = r.Combo.Scope == "MGC" ? r.Combo.MgcDirection : r.Combo.MnqDirection == r.Combo.MgcDirection || r.Combo.Scope == "MNQ" ? r.Combo.MnqDirection : "MNQ " + r.Combo.MnqDirection + " / MGC " + r.Combo.MgcDirection;
            foreach (var n in r.Nights.OrderByDescending(x => x.Date))
            {
                var nn = n;
                string nd = trend ? n.Dir : fixedDir;
                var row = HelixRow(new[] { n.Date.ToString("ddd yyyy-MM-dd", CultureInfo.InvariantCulture), nd, n.MnqLegs == 0 ? "–" : n.MnqLegs.ToString(), n.MgcLegs == 0 ? "–" : n.MgcLegs.ToString(), n.Contracts.ToString(), Signed(n.Mnq), Signed(n.Mgc), Signed(n.Net), Signed(n.Worst), Signed(n.Best), n.End, n.EndTime == DateTime.MinValue ? "" : n.EndTime.ToString("ddd HH:mm", CultureInfo.InvariantCulture) },
                    new[] { Gold, nd.Contains("SHORT") && !nd.Contains("LONG") ? Red : nd.Contains("LONG") && !nd.Contains("SHORT") ? Green : Orchid, Text, Text, Text, MoneyBrush(n.Mnq), MoneyBrush(n.Mgc), MoneyBrush(n.Net), Red, Green, n.Target ? Green : n.End == "SESSION END" ? Cyan : Red, Muted }, w, MoneyBrush(n.Net), null);
                row.Cursor = System.Windows.Input.Cursors.Hand; row.MouseLeftButtonUp += delegate { ShowAsianNightOnChart(nn.Date, r.Combo.Scope == "MGC" ? "MGC" : "MNQ"); };
                root.Children.Add(row);
            }
            return HelixScroll(root);
        }

        private void ShowAsianNightOnChart(DateTime night, string symbol)
        {
            if (config == null) return;
            if (evidenceWindow == null) OpenEvidenceChart(); else evidenceWindow.Activate();
            if (evidenceInstrumentTabs != null)
                for (int i = 0; i < evidenceInstrumentTabs.Items.Count; i++) { var tab = evidenceInstrumentTabs.Items[i] as TabItem; if (tab != null && Convert.ToString(tab.Header).StartsWith(symbol)) { evidenceInstrumentTabs.SelectedIndex = i; break; } }
            if (evidenceInstrumentBox != null) evidenceInstrumentBox.SelectedItem = symbol;
            SelectEvidenceSessionDate(night.ToString("yyyy-MM-dd"), true);
        }

        // Puts a combination into the Asian settings and re-runs the cycle, the pool and the chart on the bars already loaded.
        private bool ApplyAsianLabRow(KeystoneAsianLabRow r)
        {
            if (r == null) return false; var c = r.Combo;
            if (KeystoneAsianLab.IsTrend(c)) { UpdateUi("A TREND row changes direction every night • Step 1 has one fixed direction, so it cannot be applied • its nights are in NIGHTS (each with the direction it took)", Gold); if (asianLabStatus != null) { asianLabStatus.Text = "TREND rows cannot be applied: Step 1 has one fixed direction. Read its nights in NIGHTS."; asianLabStatus.Foreground = Gold; } return false; }
            if (!EvidenceIsAsian() || loadedEvents == null || loadedEvents.Count == 0 || string.IsNullOrEmpty(loadedScope)) { UpdateUi("RUN ASIAN 75 IN STEP 1 FIRST (the math lab uses its bars)", Gold); return false; }
            if (loadedScope != "BOTH" && loadedScope != c.Scope) { UpdateUi("ONLY " + loadedScope + " IS LOADED • choose BOTH in Step 1 to apply a " + c.Scope + " combination", Gold); return false; }
            if (operationBusy || isProcessing) { UpdateUi("WAIT FOR THE CURRENT OPERATION TO FINISH", Gold); return false; }
            if (asianDirectionBox != null) asianDirectionBox.SelectedItem = c.Scope == "MGC" ? c.MgcDirection : c.MnqDirection;
            if (asianMnqDirectionBox != null) asianMnqDirectionBox.SelectedItem = c.MnqDirection; if (asianMgcDirectionBox != null) asianMgcDirectionBox.SelectedItem = c.MgcDirection;
            if (asianRiskModeBox != null) asianRiskModeBox.SelectedIndex = 0;
            if (asianReversalLossBox != null) asianReversalLossBox.Text = c.LegLoss.ToString("0.##", CultureInfo.InvariantCulture);
            if (asianMaxReversalsBox != null) asianMaxReversalsBox.Text = c.Reversals.ToString(CultureInfo.InvariantCulture);
            if (asianCycleTargetBox != null) asianCycleTargetBox.Text = c.Target.ToString("0.##", CultureInfo.InvariantCulture);
            if (asianStartingQuantityBox != null) asianStartingQuantityBox.Text = c.StartingQuantity.ToString(CultureInfo.InvariantCulture);
            if (asianStartTimeBox != null) asianStartTimeBox.Text = c.StartHhmm.ToString("0000", CultureInfo.InvariantCulture);
            if (asianEndTimeBox != null) asianEndTimeBox.Text = c.EndHhmm.ToString("0000", CultureInfo.InvariantCulture);
            if (asianBreakEvenBox != null) asianBreakEvenBox.Text = "0"; if (asianCombinedStopBox != null) asianCombinedStopBox.Text = "0";
            if (asianDailyLossBox != null)
            {
                if (c.DailyLossLimit > 0) { asianDailyLossManual = true; asianDailyLossUpdating = true; try { asianDailyLossBox.Text = c.DailyLossLimit.ToString("0.##", CultureInfo.InvariantCulture); } finally { asianDailyLossUpdating = false; } }
                else asianDailyLossManual = false;
            }
            RefreshAsianDerivedInputs();
            // The loaded range, data and pool settings stay; only the Asian cycle settings change (the pool re-reads its own settings).
            DateTime loadedStart = config.Start, loadedEnd = config.End; int loadedOneDay = config.OneDayMode;
            c.Apply(config); config.Start = loadedStart; config.End = loadedEnd; config.OneDayMode = loadedOneDay; config.AsianInstrumentStopLossDollars = 0; config.AsianMnqInstrumentStopLossDollars = 0; config.AsianMgcInstrumentStopLossDollars = 0; config.AsianCombinedStopLossDollars = 0; config.AsianBreakEvenTriggerDollars = 0;
            double manual = AsianManualLoss();
            var cfgLoaded = CloneConfig(config); cfgLoaded.Scope = loadedScope; cfgLoaded.AsianDailyLossLimitDollars = AsianLossForScope(cfgLoaded, loadedScope, manual);
            var bars = loadedScope == "MNQ" ? mnqBars : loadedScope == "MGC" ? mgcBars : mnqBars.Concat(mgcBars).OrderBy(b => b.Time).ThenBy(b => b.Symbol, StringComparer.OrdinalIgnoreCase).ToList();
            var fresh = KeystoneArcEngine.DetectAndResolve(bars, bars, cfgLoaded).OrderBy(x => x.EntryTime).ThenBy(x => x.Symbol, StringComparer.OrdinalIgnoreCase).ToList();
            foreach (var e in fresh) { e.ReviewState = "ACCEPTED"; e.ReviewNote = "AUTO-INCLUDED: resolved Asian daily-cycle leg (math lab)"; }
            loadedEvents = fresh; loadedAsianLoss = cfgLoaded.AsianDailyLossLimitDollars;
            viewScope = c.Scope; config.Scope = c.Scope; config.AsianDailyLossLimitDollars = AsianLossForScope(config, c.Scope, manual);
            events = c.Scope == loadedScope ? loadedEvents : EventsForInstrumentView(c.Scope, cfgLoaded, manual);
            for (int i = 0; i < events.Count; i++) { events[i].AssignedVirtualAccount = string.Empty; events[i].SkipReason = string.Empty; }
            accounts = new List<KeystoneArcVirtualAccount>(); evidenceReplayKey = string.Empty;
            RebuildReviewList(); RenderEvents(); BuildMathReader(); RenderResearchFindings(); poolDayIndex = -1; RenderPoolDayPanel(); RefreshInstrumentViewControls();
            UpdateUi("APPLIED FROM THE MATH LAB (no reload) • " + r.Label + " • " + events.Count + " legs • recalculating the pool", Green);
            if (evidenceWindow != null) RequestEvidenceBars();
            SimulatePool();
            return true;
        }

        private string AsianLabCsv()
        {
            var res = asianLabResult; if (res == null) return string.Empty; var sb = new StringBuilder(); Func<double, string> f = v => v.ToString("0.##", CultureInfo.InvariantCulture);
            sb.AppendLine("# ASIAN MATH LAB • " + res.Nights + " nights " + res.First.ToString("yyyy-MM-dd") + " -> " + res.Last.ToString("yyyy-MM-dd") + " • unseen 30% from " + res.SplitAt.ToString("yyyy-MM-dd") + " • " + res.Rules.Describe().Replace(',', ' '));
            sb.AppendLine("rank,scope,mnq_dir,mgc_dir,micros,leg_loss,reversals,take_profit,max_loss,start,nights,win_nights,tp_nights,plain_net,mnq_net,mgc_net,worst_dd,evals,passed,payouts,funded_lost,spent,cash,prop_net,first_payout_days,spent_before_first_payout,payouts_in_a_row,money_needed,early70_net,unseen30_net,years_up,years,prop_by_year");
            for (int i = 0; i < res.Rows.Count; i++)
            {
                var r = res.Rows[i]; var c = r.Combo;
                sb.AppendLine(string.Join(",", new[] { (i + 1).ToString(), c.Scope, c.MnqDirection, c.MgcDirection, c.StartingQuantity.ToString(), f(c.LegLoss), c.Reversals.ToString(), f(c.Target), c.DailyLossLimit > 0 ? f(c.DailyLossLimit) : "AUTO", c.StartHhmm.ToString("0000"), r.Nights.Count.ToString(), r.P.Wins.ToString(), r.TargetNights.ToString(), f(r.P.Net), f(r.MnqNet), f(r.MgcNet), f(r.P.MaxDrawdown), r.P.Bought.ToString(), r.P.Passed.ToString(), r.P.Payouts.ToString(), r.P.FundedLost.ToString(), f(r.P.Spent), f(r.P.Cash), f(r.P.PropNet), r.P.Stats.HasPayout ? r.P.Stats.CalendarDaysToFirstPayout.ToString() : "", r.P.Stats.HasPayout ? f(r.P.Stats.SpentToFirstPayout) : "", r.P.Stats.PayoutsInARow.ToString(), f(r.P.MoneyNeeded), f(r.InSampleNet), f(r.OutSampleNet), r.YearsUp.ToString(), r.Years.ToString(), "\"" + string.Join(" ", r.P.PropByYear.OrderBy(k => k.Key).Select(k => k.Key + ":" + f(k.Value))) + "\"" }));
            }
            sb.AppendLine(); sb.AppendLine("# ADVICE"); foreach (string a in KeystoneAsianLab.Advice(res)) sb.AppendLine("\"" + a.Replace("\"", "'") + "\"");
            sb.AppendLine(); sb.AppendLine("# WHICH VALUE WINS"); sb.AppendLine("setting,value,rows,profitable,median_prop,best_prop,avg_first_payout_days");
            foreach (var x in KeystoneAsianLab.Impacts(res.Rows)) sb.AppendLine(string.Join(",", new[] { x.Setting, x.Value, x.Rows.ToString(), x.Profitable.ToString(), f(x.Median), f(x.Best), f(x.AvgFirstPayoutDays) }));
            if (asianLabSelected != null)
            {
                sb.AppendLine(); sb.AppendLine("# EVERY NIGHT • " + asianLabSelected.Label); sb.AppendLine("night,direction,mnq_legs,mgc_legs,contracts,mnq,mgc,combined,lowest,highest,ended,at");
                foreach (var n in asianLabSelected.Nights) sb.AppendLine(string.Join(",", new[] { n.Date.ToString("yyyy-MM-dd"), "\"" + (KeystoneAsianLab.IsTrend(asianLabSelected.Combo) ? n.Dir : asianLabSelected.Combo.MnqDirection + "/" + asianLabSelected.Combo.MgcDirection) + "\"", n.MnqLegs.ToString(), n.MgcLegs.ToString(), n.Contracts.ToString(), f(n.Mnq), f(n.Mgc), f(n.Net), f(n.Worst), f(n.Best), n.End, n.EndTime == DateTime.MinValue ? "" : n.EndTime.ToString("yyyy-MM-dd HH:mm") }));
                sb.AppendLine(); sb.AppendLine("# EVERY ACCOUNT • " + asianLabSelected.Label); sb.AppendLine("no,bought,passed,first_payout,ended,payouts,cash,spent,status");
                foreach (var a in asianLabSelected.P.Accounts) sb.AppendLine(string.Join(",", new[] { a.No.ToString(), a.Bought.ToString("yyyy-MM-dd"), a.PassedOn == DateTime.MinValue ? "" : a.PassedOn.ToString("yyyy-MM-dd"), a.PayoutDates.Count == 0 ? "" : a.PayoutDates[0].ToString("yyyy-MM-dd"), a.Ended == DateTime.MinValue ? "" : a.Ended.ToString("yyyy-MM-dd"), a.Payouts.ToString(), f(a.Cash), f(a.Spent), a.Status }));
            }
            return sb.ToString();
        }

        private string AsianLabHtml()
        {
            var res = asianLabResult; var r = asianLabSelected ?? (res == null ? null : res.Rows.FirstOrDefault()); if (res == null || r == null) return string.Empty;
            if (r.P.Ledger.Count == 0) KeystoneAsianLab.Detail(r, asianLabRules, res.SplitAt);
            Func<string, string> H = x => System.Net.WebUtility.HtmlEncode(x ?? string.Empty);
            Func<double, string> M = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            Func<double, string> C = v => v > 0 ? "g" : v < 0 ? "r" : "";
            var sb = new StringBuilder();
            sb.Append("<!doctype html><html><head><meta charset='utf-8'><title>Asian Math Lab</title><style>body{background:#0d0f14;color:#e8e6df;font:13px Segoe UI,Arial;margin:20px}h1,h2{color:#ebb02b}table{border-collapse:collapse;margin:6px 0}td,th{padding:4px 9px;border-bottom:1px solid #2a2e38;text-align:right}th{color:#ebb02b}td:first-child,th:first-child{text-align:left}.g{color:#32c57a}.r{color:#f05461}.n{color:#9aa0aa}.cards{display:flex;flex-wrap:wrap;gap:8px}.card{border:1px solid #ebb02b;border-radius:6px;padding:8px 12px;min-width:170px}.card b{display:block;font-size:20px}li{margin:3px 0}</style></head><body>");
            sb.Append("<h1>ASIAN MATH LAB</h1><p class='n'>").Append(res.Rows.Count).Append(" combinations • ").Append(res.Nights).Append(" nights ").Append(res.First.ToString("yyyy-MM-dd")).Append(" → ").Append(res.Last.ToString("yyyy-MM-dd")).Append(" • ").Append(H(res.Rules.Describe())).Append("</p>");
            sb.Append("<h2>WHAT THE NUMBERS SAY</h2><ul>"); foreach (string a in KeystoneAsianLab.Advice(res)) sb.Append("<li>").Append(H(a)).Append("</li>"); sb.Append("</ul>");
            sb.Append("<h2>SELECTED • ").Append(H(r.Label)).Append("</h2><div class='cards'>");
            Action<string, string, string> card = (t, v, sub) => sb.Append("<div class='card'>").Append(H(t)).Append("<b>").Append(H(v)).Append("</b><span class='n'>").Append(H(sub)).Append("</span></div>");
            var st = r.P.Stats;
            card("PROP NET", M(r.P.PropNet), r.P.Passed + " passed / " + r.P.Bought + " bought • " + r.P.Payouts + " payouts");
            card("PLAIN", M(r.P.Net), "MNQ " + M(r.MnqNet) + " • MGC " + M(r.MgcNet));
            card("FIRST PAYOUT", st.HasPayout ? st.CalendarDaysToFirstPayout + " days" : "never", st.HasPayout ? "spent " + M(st.SpentToFirstPayout) + " before it" : "");
            card("PAYOUTS IN A ROW", st.PayoutsInARow.ToString(), "failed evaluations in a row " + st.LongestFailStreak);
            card("TAKE PROFIT NIGHTS", (100.0 * r.TargetNights / Math.Max(1, r.Nights.Count)).ToString("0") + "%", "full loss nights " + (r.LossNights + r.AllStoppedNights) + " • avg " + M(r.AvgFullLoss));
            card("UNSEEN LAST 30%", M(r.OutSampleNet), "early 70% " + M(r.InSampleNet));
            card("MONEY NEEDED", M(r.P.MoneyNeeded), "most out of pocket at once");
            sb.Append("</div>");
            double eq = 0; var vals = r.Nights.Select(n => eq += n.Net).ToList();
            if (vals.Count > 1)
            {
                double mn = Math.Min(0, vals.Min()), mx = Math.Max(1, vals.Max());
                sb.Append("<h2>PLAIN ACCOUNT NIGHT BY NIGHT</h2><svg width='1100' height='240' style='background:#141821'><polyline fill='none' stroke='#32c57a' stroke-width='2' points='");
                for (int i = 0; i < vals.Count; i++) sb.Append((60 + i * 1020.0 / (vals.Count - 1)).ToString("0.#", CultureInfo.InvariantCulture)).Append(',').Append((14 + (mx - vals[i]) / (mx - mn) * 200).ToString("0.#", CultureInfo.InvariantCulture)).Append(' ');
                sb.Append("'/><text x='4' y='20' fill='#9aa0aa' font-size='11'>").Append(M(mx)).Append("</text><text x='4' y='218' fill='#9aa0aa' font-size='11'>").Append(M(mn)).Append("</text></svg>");
            }
            sb.Append("<h2>EACH YEAR</h2><table><tr><th>YEAR</th><th>NIGHTS</th><th>PLAIN</th><th>MNQ</th><th>MGC</th><th>PROP</th></tr>");
            foreach (var g in r.Nights.GroupBy(x => x.Date.Year).OrderBy(g => g.Key)) { double p; r.P.PropByYear.TryGetValue(g.Key, out p); double net = g.Sum(x => x.Net); sb.Append("<tr><td>").Append(g.Key).Append("</td><td>").Append(g.Count()).Append("</td><td class='").Append(C(net)).Append("'>").Append(M(net)).Append("</td><td>").Append(M(g.Sum(x => x.Mnq))).Append("</td><td>").Append(M(g.Sum(x => x.Mgc))).Append("</td><td class='").Append(C(p)).Append("'>").Append(M(p)).Append("</td></tr>"); }
            sb.Append("</table><h2>MONTH BY MONTH • PROFIT vs EXPENSES</h2><table><tr><th>MONTH</th><th>TRADING</th><th>BOUGHT</th><th>PASSED</th><th>PAYOUTS</th><th>SPENT</th><th>CASH IN</th><th>NET</th></tr>");
            foreach (var g in r.P.Ledger.GroupBy(l => new DateTime(l.Day.Year, l.Day.Month, 1)).OrderBy(g => g.Key)) { double sp = g.Sum(l => l.Spent), ca = g.Sum(l => l.Cash), tr = g.Sum(l => l.Pnl); sb.Append("<tr><td>").Append(g.Key.ToString("MMM yyyy", CultureInfo.InvariantCulture)).Append("</td><td class='").Append(C(tr)).Append("'>").Append(M(tr)).Append("</td><td>").Append(g.Sum(l => l.Bought)).Append("</td><td>").Append(g.Sum(l => l.Passed)).Append("</td><td>").Append(g.Sum(l => l.Payouts)).Append("</td><td class='r'>").Append(M(sp)).Append("</td><td class='g'>").Append(M(ca)).Append("</td><td class='").Append(C(ca - sp)).Append("'>").Append(M(ca - sp)).Append("</td></tr>"); }
            sb.Append("</table><h2>TOP 50 COMBINATIONS</h2><table><tr><th>COMBINATION</th><th>PLAIN</th><th>MNQ</th><th>MGC</th><th>WORST DD</th><th>PASSED</th><th>PAYOUTS</th><th>1ST PAY</th><th>PROP</th><th>UNSEEN 30%</th><th>YEARS+</th></tr>");
            foreach (var x in res.Rows.Take(50)) sb.Append("<tr><td>").Append(H(x.Label)).Append("</td><td class='").Append(C(x.P.Net)).Append("'>").Append(M(x.P.Net)).Append("</td><td>").Append(M(x.MnqNet)).Append("</td><td>").Append(M(x.MgcNet)).Append("</td><td class='r'>").Append(M(x.P.MaxDrawdown)).Append("</td><td>").Append(x.P.Passed).Append("</td><td>").Append(x.P.Payouts).Append("</td><td>").Append(x.P.Stats.HasPayout ? x.P.Stats.CalendarDaysToFirstPayout + " d" : "never").Append("</td><td class='").Append(C(x.P.PropNet)).Append("'>").Append(M(x.P.PropNet)).Append("</td><td class='").Append(C(x.OutSampleNet)).Append("'>").Append(M(x.OutSampleNet)).Append("</td><td>").Append(x.YearsUp).Append("/").Append(x.Years).Append("</td></tr>");
            sb.Append("</table><h2>WHICH VALUE WINS</h2><table><tr><th>SETTING</th><th>VALUE</th><th>ROWS</th><th>PROFITABLE</th><th>MEDIAN</th><th>BEST</th></tr>");
            foreach (var x in KeystoneAsianLab.Impacts(res.Rows)) sb.Append("<tr><td>").Append(H(x.Setting)).Append("</td><td>").Append(H(x.Value)).Append("</td><td>").Append(x.Rows).Append("</td><td>").Append(x.Profitable).Append("</td><td class='").Append(C(x.Median)).Append("'>").Append(M(x.Median)).Append("</td><td class='").Append(C(x.Best)).Append("'>").Append(M(x.Best)).Append("</td></tr>");
            sb.Append("</table></body></html>");
            return sb.ToString();
        }

        private void OpenAsianLab(bool autoRun = false)
        {
            if (asianLabWindow != null) { asianLabWindow.Activate(); if (autoRun && asianLabRun != null) asianLabRun(); return; }
            var w = new KeystoneWindow { Title = "KEYSTONE ARC • ASIAN MATH LAB", Width = 1560, Height = 940, MinWidth = 960, MinHeight = 600, Background = Bg, Foreground = Text, ResizeMode = ResizeMode.CanResize, WindowStartupLocation = WindowStartupLocation.CenterScreen, ShowInTaskbar = true };
            FitWindowToScreen(w);
            var root = new Grid { Margin = new Thickness(10) };
            for (int i = 0; i < 3; i++) root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            var head = new StackPanel();
            head.Children.Add(Txt("ASIAN MATH LAB • EVERY COMBINATION ON THE BARS YOU LOADED", Gold, 20, FontWeights.Bold));
            head.Children.Add(Txt("Type one value or a list (e.g. 75,100,150) in each box and press RUN: every combination runs through the same Asian engine as the lab (same legs, stops and reversals on real 1-minute bars), then through the prop rules: evaluations, funded accounts, payouts. Nothing is re-downloaded. APPLY TO LAB puts the selected combination on the chart (replay) and in the pool instantly.", Muted, 11, FontWeights.Normal));
            Grid.SetRow(head, 0); root.Children.Add(head);
            Func<string, string, double, TextBox> box = (label, value, width) => { var t = Input(value); t.Width = width; t.ToolTip = label; return t; };
            string curLoss = asianReversalLossBox == null ? "75" : asianReversalLossBox.Text, curRev = asianMaxReversalsBox == null ? "4" : asianMaxReversalsBox.Text, curTp = asianCycleTargetBox == null ? "350" : asianCycleTargetBox.Text;
            var scopes = box("INSTRUMENTS", loadedScope == "MNQ" ? "MNQ" : loadedScope == "MGC" ? "MGC" : "MNQ,MGC,BOTH", 130); var dirs = box("DIRECTIONS", "LONG,SHORT", 110);
            var mixed = new CheckBox { Content = "BOTH: ALSO MNQ/MGC OPPOSITE", Foreground = Text, Margin = new Thickness(6, 8, 6, 0), IsChecked = false };
            var mineNow = MathLabMineCombo(); asianLabMine = mineNow;
            var qty = box("STARTING MICROS", "1,2" + (mineNow.StartingQuantity > 2 ? "," + mineNow.StartingQuantity : ""), 70); var loss = box("LEG LOSS $", "75,100,150" + (new[] { "75", "100", "150" }.Contains(curLoss) ? "" : "," + curLoss), 120); var rev = box("REVERSALS", "2,3,4" + (new[] { "2", "3", "4" }.Contains(curRev) ? "" : "," + curRev), 80);
            var tp = box("TAKE PROFIT $", "200,350,500" + (new[] { "200", "350", "500" }.Contains(curTp) ? "" : "," + curTp), 120); var maxLoss = box("MAX COMBINED LOSS $ (0 = AUTO)", "0" + (mineNow.DailyLossLimit > 0 ? "," + mineNow.DailyLossLimit.ToString("0.##", CultureInfo.InvariantCulture) : ""), 90);
            var trendBox = box("TREND DAYS (0 = OFF)", "20", 70); trendBox.ToolTip = "With LONG and SHORT both in DIRECTIONS, extra rows choose each night's direction: LONG when the price before the open is above the average of the last N session prices, else SHORT. Several values: 10,20,50.";
            var start = box("START HHMM", asianStartTimeBox == null ? "1800" : asianStartTimeBox.Text, 70); var end = box("END HHMM", asianEndTimeBox == null ? "1555" : asianEndTimeBox.Text, 60); var cost = box("COST $ PER CONTRACT (ROUND TRIP)", "1.00", 60);
            var presets = KeystonePropRules.Presets(); var rulesBox = Select(presets.Select(p => p.Name).ToArray()); rulesBox.SelectedIndex = 0; rulesBox.Width = 250;
            var evalBox = box("EVALUATION $", "120", 60); var actBox = box("ACTIVATION $", "0", 60);
            var inputs = new WrapPanel { Margin = new Thickness(0, 4, 0, 2) };
            Action<string, UIElement> add = delegate(string l, UIElement e) { var sp = new StackPanel { Margin = new Thickness(2, 0, 6, 0) }; sp.Children.Add(Txt(l, Muted, 9.5, FontWeights.Bold)); sp.Children.Add(e); inputs.Children.Add(sp); };
            add("INSTRUMENTS", scopes); add("DIRECTIONS", dirs); add(" ", mixed); add("STARTING MICROS", qty); add("LEG LOSS $", loss); add("REVERSALS", rev); add("TAKE PROFIT $", tp); add("MAX LOSS $ (0=AUTO)", maxLoss); add("TREND DAYS", trendBox); add("START", start); add("END", end); add("COST $/CONTRACT", cost);
            add("FIRM RULES", rulesBox); add("EVALUATION $", evalBox); add("ACTIVATION $", actBox);
            var buttons = new WrapPanel();
            var runBtn = Btn("RUN", Gold); runBtn.Width = 120; var cancelBtn = Btn("CANCEL", Red); var applyBtn = Btn("APPLY SELECTED TO LAB (CHART + POOL, NO RELOAD)", Green); var expBtn = Btn("EXPORT HTML + CSV", Orchid);
            var toLab = Btn("GO TO LAB STEP 3", Cyan); toLab.Click += delegate { if (window != null) window.Activate(); if (workspaceTabs != null) workspaceTabs.SelectedIndex = 2; };
            buttons.Children.Add(runBtn); buttons.Children.Add(cancelBtn); buttons.Children.Add(applyBtn); buttons.Children.Add(expBtn); buttons.Children.Add(toLab);
            var top = new StackPanel(); top.Children.Add(inputs); top.Children.Add(buttons);
            Grid.SetRow(top, 1); root.Children.Add(top);
            var status = Txt("Set the lists and press RUN.", Gold, 12.5, FontWeights.Bold); status.TextWrapping = TextWrapping.Wrap; Grid.SetRow(status, 2); root.Children.Add(status);
            var tabs = new TabControl { Background = Panel, BorderBrush = Gold, BorderThickness = new Thickness(1), TabStripPlacement = Dock.Top };
            string[] names = { "ADVICE", "ADAPTS EACH YEAR?", "RANKING", "CHARTS", "EVALS & FUNDED", "SIZE & SPEED", "COPY TRADING", "LEGS", "MONTHS", "YEARS & PERIODS", "NIGHTS", "FLIP (LIVE ACCOUNT)" };
            var colors = new Brush[] { Green, Orange, Gold, Green, Cyan, Orange, Orchid, Gold, Gold, Cyan, Green, Red };
            for (int i = 0; i < names.Length; i++) tabs.Items.Add(new TabItem { Header = names[i], Background = colors[i], Foreground = Bg, FontWeight = FontWeights.Bold, Content = Txt("Press RUN.", Muted, 12, FontWeights.Normal) });
            Grid.SetRow(tabs, 3); root.Children.Add(tabs); asianLabTabs = tabs;
            Action run = delegate
            {
                var oneMinute = new List<KeystoneArcBar>(); if (KeystoneBracket.IsOneMinute(mnqBars)) oneMinute.AddRange(mnqBars); if (KeystoneBracket.IsOneMinute(mgcBars)) oneMinute.AddRange(mgcBars);
                if (oneMinute.Count == 0) { status.Text = "NO 1-MINUTE BARS LOADED • Step 1: ASIAN 75 REVERSAL, BOTH, your dates (e.g. 2020-01-01 → yesterday), START — then open the math lab."; status.Foreground = Red; return; }
                var g = new KeystoneAsianLabGrid
                {
                    Scopes = ParseWords(scopes.Text, new[] { "MNQ", "MGC", "BOTH" }, "BOTH"), Directions = ParseWords(dirs.Text, new[] { "LONG", "SHORT" }, "LONG"), MixedBoth = mixed.IsChecked == true,
                    Quantities = ParseNumbers(qty.Text, 1).Select(v => Math.Max(1, (int)Math.Round(v))).Distinct().ToList(), LegLosses = ParseNumbers(loss.Text, 75).Where(v => v > 0).ToList(), Reversals = ParseNumbers(rev.Text, 3).Select(v => (int)Math.Round(v)).Distinct().ToList(),
                    Targets = ParseNumbers(tp.Text, 350).Where(v => v > 0).ToList(), MaxLosses = ParseNumbers(maxLoss.Text, 0), StartTimes = ParseNumbers(start.Text, 1800).Select(v => (int)v).Where(IsValidHhmm).Distinct().ToList(), EndHhmm = Math.Max(0, Integer(end, 1555)), CostPerContract = NumberAllowZero(cost, 1),
                    TrendDays = ParseNumbers(trendBox.Text, 0).Select(v => (int)Math.Round(v)).Where(v => v > 1).Distinct().ToList()
                };
                if (g.LegLosses.Count == 0 || g.Targets.Count == 0 || g.StartTimes.Count == 0) { status.Text = "CHECK THE LISTS • leg loss and take profit must be above 0, times HHMM"; status.Foreground = Red; return; }
                var rules = presets[Math.Max(0, rulesBox.SelectedIndex)].Copy(); rules.EvalCost = NumberAllowZero(evalBox, 120); rules.Activation = NumberAllowZero(actBox, 0);
                asianLabMine = MathLabMineCombo();
                int count = KeystoneAsianLab.Combos(g, oneMinute.Any(b => b.Symbol != "MGC"), oneMinute.Any(b => b.Symbol == "MGC")).Count;
                if (count == 0) { status.Text = "NO COMBINATIONS • the instruments in the list are not loaded"; status.Foreground = Red; return; }
                if (count > 3000 && KBox(count.ToString("N0") + " combinations can take several minutes. Run them?", "Asian math lab", MessageBoxButton.YesNo, MessageBoxImage.Question) != MessageBoxResult.Yes) return;
                asianLabCancel = false; runBtn.IsEnabled = false; status.Text = "RUNNING " + count.ToString("N0") + " combinations on " + oneMinute.Select(b => b.Time.Date).Distinct().Count() + " days of bars…"; status.Foreground = Gold;
                var bars = oneMinute.OrderBy(b => b.Time).ToList(); var sw = System.Diagnostics.Stopwatch.StartNew();
                System.Threading.ThreadPool.QueueUserWorkItem(delegate
                {
                    KeystoneAsianLabResult res = null; string failure = null; int lastShown = 0;
                    try
                    {
                        res = KeystoneAsianLab.Run(bars, g, rules, (done, total) =>
                        {
                            if (done - lastShown < Math.Max(1, total / 50) && done != total) return; lastShown = done;
                            Action p = delegate { if (asianLabStatus != null && !asianLabCancel) asianLabStatus.Text = "RUNNING • " + done + " / " + total + " combinations • " + (sw.ElapsedMilliseconds / 1000) + " s"; };
                            if (w.Dispatcher == null || w.Dispatcher.CheckAccess()) p(); else w.Dispatcher.BeginInvoke(p);
                        }, () => asianLabCancel);
                    }
                    catch (Exception ex) { failure = ex.Message; }
                    Action done2 = delegate
                    {
                        runBtn.IsEnabled = true;
                        if (failure != null || res == null) { status.Text = "ERROR • " + failure; status.Foreground = Red; return; }
                        asianLabRules = rules; asianLabResult = res; asianLabSelected = null;
                        if (res.Rows.Count > 0) ShowAsianLabSelected(res.Rows[0], false);
                        SetAsianLabTab("ADVICE", AsianLabAdviceView()); SetAsianLabTab("RANKING", AsianLabRankingView()); SetAsianLabTab("ADAPTS EACH YEAR?", AsianLabWalkView()); tabs.SelectedIndex = 0;
                        var best = res.Rows.FirstOrDefault();
                        status.Text = (res.Cancelled ? "CANCELLED • " : "") + res.Rows.Count + " COMBINATIONS • " + res.Nights + " nights " + res.First.ToString("yyyy-MM-dd") + " → " + res.Last.ToString("yyyy-MM-dd") + " • " + (sw.ElapsedMilliseconds / 1000) + " s" + (best != null ? " • #1 " + best.Label + " • prop " + Signed(best.P.PropNet) : "");
                        status.Foreground = best != null && best.P.PropNet > 0 ? Green : Red;
                    };
                    if (w.Dispatcher == null || w.Dispatcher.CheckAccess()) done2(); else w.Dispatcher.BeginInvoke(done2);
                });
            };
            runBtn.Click += delegate { run(); }; cancelBtn.Click += delegate { asianLabCancel = true; status.Text = "CANCELLING…"; };
            applyBtn.Click += delegate { if (asianLabSelected == null) { status.Text = "RUN, then click a row"; status.Foreground = Gold; return; } if (ApplyAsianLabRow(asianLabSelected)) { status.Text = "APPLIED TO THE LAB • " + asianLabSelected.Label + " • the chart, replay and Step 3 pool now show it"; status.Foreground = Green; } };
            expBtn.Click += delegate
            {
                if (asianLabResult == null) { status.Text = "RUN FIRST"; status.Foreground = Gold; return; }
                try
                {
                    string dir = DataDirectory(); Directory.CreateDirectory(dir); string stem = Path.Combine(dir, "KeystoneArc_AsianLab_" + DateTime.Now.ToString("yyyyMMdd_HHmmss"));
                    File.WriteAllText(stem + ".csv", AsianLabCsv(), Encoding.UTF8); File.WriteAllText(stem + ".html", AsianLabHtml(), Encoding.UTF8);
                    status.Text = "EXPORTED " + stem + ".html + .csv • attach both to Claude"; status.Foreground = Green;
                    try { System.Diagnostics.Process.Start(stem + ".html"); } catch { }
                }
                catch (Exception ex) { status.Text = "EXPORT ERROR • " + ex.Message; status.Foreground = Red; }
            };
            ConfirmToolClose(w, "ASIAN MATH LAB");
            w.Content = root; asianLabWindow = w; asianLabStatus = status; asianLabRun = run;
            w.Closed += delegate { asianLabWindow = null; asianLabTabs = null; asianLabStatus = null; asianLabCancel = true; asianLabRun = null; };
            w.Show();
            if (autoRun) run();
        }

        private void ShowMicroTradeOnChart(KeystoneMicroTrade t)
        {
            if (t == null || config == null) return;
            if (evidenceWindow == null) OpenEvidenceChart(); else evidenceWindow.Activate();
            if (evidenceInstrumentTabs != null)
                for (int i = 0; i < evidenceInstrumentTabs.Items.Count; i++) { var tab = evidenceInstrumentTabs.Items[i] as TabItem; if (tab != null && Convert.ToString(tab.Header).StartsWith(t.Symbol)) { evidenceInstrumentTabs.SelectedIndex = i; break; } }
            if (evidenceInstrumentBox != null) evidenceInstrumentBox.SelectedItem = t.Symbol;
            SelectEvidenceSessionDate(KeystoneArcEngine.SessionGroupingDate(t.Open, config).ToString("yyyy-MM-dd"), true);
        }

        private UIElement MicroMonthsView(KeystoneMicroRow r)
        {
            var root = new StackPanel { Margin = new Thickness(4) };
            root.Children.Add(HelixTitle(r.Label + " • MONTH BY MONTH • PROFIT vs EXPENSES", Gold));
            root.Children.Add(HelixNote("TRADING = the plain account (1 micro each). PROP: evaluations bought, passed, payouts, accounts lost, what you spent, the cash you received and the month's net; RUNNING = cash − spent since the start."));
            double[] w = { 100, 70, 110, 70, 70, 70, 70, 100, 100, 110, 120 };
            root.Children.Add(HelixHeader(new[] { "MONTH", "SESSIONS", "TRADING", "BOUGHT", "PASSED", "PAYOUTS", "LOST", "SPENT", "CASH IN", "MONTH NET", "RUNNING" }, w));
            double run = 0;
            foreach (var g in r.Ledger.GroupBy(l => new DateTime(l.Day.Year, l.Day.Month, 1)).OrderBy(g => g.Key))
            {
                double spent = g.Sum(l => l.Spent), cash = g.Sum(l => l.Cash), net = cash - spent, tr = g.Sum(l => l.Pnl); run += net;
                root.Children.Add(HelixRow(new[] { g.Key.ToString("MMM yyyy", CultureInfo.InvariantCulture), g.Count().ToString(), Signed(tr), g.Sum(l => l.Bought).ToString(), g.Sum(l => l.Passed).ToString(), g.Sum(l => l.Payouts).ToString(), (g.Sum(l => l.Lost) + g.Sum(l => l.Failed)).ToString(), Cash(spent), Cash(cash), Signed(net), Signed(run) },
                    new[] { Gold, Text, MoneyBrush(tr), Text, Green, Green, Red, Red, Green, MoneyBrush(net), MoneyBrush(run) }, w, MoneyBrush(net), null));
            }
            root.Children.Add(HelixTitle("YEAR BY YEAR", Gold));
            root.Children.Add(HelixHeader(new[] { "YEAR", "SESSIONS", "TRADING", "BOUGHT", "PASSED", "PAYOUTS", "LOST", "SPENT", "CASH IN", "YEAR NET", "" }, w));
            foreach (var g in r.Ledger.GroupBy(l => l.Day.Year).OrderBy(g => g.Key))
            {
                double spent = g.Sum(l => l.Spent), cash = g.Sum(l => l.Cash), net = cash - spent, tr = g.Sum(l => l.Pnl);
                root.Children.Add(HelixRow(new[] { g.Key.ToString(), g.Count().ToString(), Signed(tr), g.Sum(l => l.Bought).ToString(), g.Sum(l => l.Passed).ToString(), g.Sum(l => l.Payouts).ToString(), (g.Sum(l => l.Lost) + g.Sum(l => l.Failed)).ToString(), Cash(spent), Cash(cash), Signed(net), "" },
                    new[] { Gold, Text, MoneyBrush(tr), Text, Green, Green, Red, Red, Green, MoneyBrush(net), Muted }, w, MoneyBrush(net), null));
            }
            return HelixScroll(root);
        }

        private UIElement MicroSizeView(KeystoneMicroRow r, List<KeystoneMicroADay.SizeRow> sizes)
        {
            var root = new StackPanel { Margin = new Thickness(4) };
            root.Children.Add(HelixTitle(r.Label + " • HOW MANY MICROS? (same days, same entries)", Gold));
            root.Children.Add(HelixNote("Each row trades the same sessions with more micros: EVAL = micros while in the evaluation (passes faster, blows up more), FUNDED = micros once funded. Sorted by the fastest first payout among the plans that make money. The worst open drawdown of the day is scaled too, so a bigger size dies on the same dips."));
            var paid = sizes.Where(x => x.Row.Stats.HasPayout && x.Row.PropNet > 0).OrderBy(x => x.Row.Stats.CalendarDaysToFirstPayout).ToList();
            var bestNet = sizes.OrderByDescending(x => x.Row.PropNet).First();
            var cards = new WrapPanel();
            if (paid.Count > 0) { var f = paid[0]; cards.Children.Add(HelixCard("FASTEST PROFITABLE FIRST PAYOUT", f.Row.Stats.CalendarDaysToFirstPayout + " days", f.EvalK + " micros in the evaluation, " + f.FundK + " funded • net " + Signed(f.Row.PropNet) + " • spent " + Cash(f.Row.Spent), Green, 300)); }
            cards.Children.Add(HelixCard("MOST MONEY", Signed(bestNet.Row.PropNet), bestNet.EvalK + " micros in the evaluation, " + bestNet.FundK + " funded • first payout " + (bestNet.Row.Stats.HasPayout ? bestNet.Row.Stats.CalendarDaysToFirstPayout + " days" : "never"), MoneyBrush(bestNet.Row.PropNet), 300));
            root.Children.Add(cards);
            double[] w = { 60, 70, 110, 90, 120, 70, 70, 70, 70, 100, 100, 110, 80 };
            root.Children.Add(HelixHeader(new[] { "EVAL", "FUNDED", "1ST PAYOUT", "SESSIONS", "SPENT BEFORE", "EVALS", "PASSED", "PAYOUTS", "LOST", "SPENT", "CASH", "NET", "PASS %" }, w));
            foreach (var x in sizes.OrderBy(x => x.Row.Stats.HasPayout ? x.Row.Stats.CalendarDaysToFirstPayout : int.MaxValue).ThenByDescending(x => x.Row.PropNet))
            {
                var q = x.Row; var s2 = q.Stats;
                root.Children.Add(HelixRow(new[] { x.EvalK.ToString("0"), x.FundK.ToString("0"), s2.HasPayout ? s2.CalendarDaysToFirstPayout + " days" : "never", s2.HasPayout ? s2.SessionsToFirstPayout.ToString() : "–", s2.HasPayout ? Cash(s2.SpentToFirstPayout) : "–", q.Bought.ToString(), q.Passed.ToString(), q.Payouts.ToString(), (q.FundedLost + q.Accounts.Count(a => a.Status == "FAILED EVALUATION")).ToString(), Cash(q.Spent), Cash(q.Cash), Signed(q.PropNet), q.PassRate.ToString("0") + "%" },
                    new[] { Gold, Gold, s2.HasPayout ? (s2.CalendarDaysToFirstPayout <= 30 ? Green : s2.CalendarDaysToFirstPayout <= 60 ? Gold : Orange) : Red, Text, Red, Text, Green, Green, Red, Red, Green, MoneyBrush(q.PropNet), Cyan }, w, MoneyBrush(q.PropNet), null));
            }
            return HelixScroll(root);
        }

        // HTML report: every tab of the selected version + the ranking, with SVG charts (opens in any browser).
        private string MicroHtml()
        {
            var res = microResult; var r = microSelected ?? (res == null ? null : res.Rows.FirstOrDefault()); if (res == null || r == null) return string.Empty;
            Func<string, string> H = x => System.Net.WebUtility.HtmlEncode(x ?? string.Empty);
            Func<double, string> M = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            Func<double, string> C = v => v > 0 ? "g" : v < 0 ? "r" : "";
            var sb = new StringBuilder();
            sb.Append("<!doctype html><html><head><meta charset='utf-8'><title>Micro A Day</title><style>body{background:#0d0f14;color:#e8e6df;font:13px Segoe UI,Arial;margin:20px}h1{color:#ebb02b}h2{color:#ebb02b;margin-top:28px}table{border-collapse:collapse;margin:6px 0}td,th{padding:4px 9px;border-bottom:1px solid #2a2e38;text-align:right}th{color:#ebb02b;text-align:right}td:first-child,th:first-child{text-align:left}.g{color:#32c57a}.r{color:#f05461}.n{color:#9aa0aa}.cards{display:flex;flex-wrap:wrap;gap:8px}.card{border:1px solid #ebb02b;border-radius:6px;padding:8px 12px;min-width:170px}.card b{display:block;font-size:20px}</style></head><body>");
            sb.Append("<h1>MICRO A DAY • ").Append(H(r.Label)).Append("</h1><p class='n'>").Append(res.Sessions).Append(" sessions ").Append(res.First.ToString("yyyy-MM-dd")).Append(" → ").Append(res.Last.ToString("yyyy-MM-dd")).Append(" • ").Append(H(res.Rules.Describe())).Append(" • ").Append(res.EvalK).Append(" micros in the evaluation, ").Append(res.FundK).Append(" funded</p>");
            var st = r.Stats;
            sb.Append("<div class='cards'>");
            Action<string, string, string> card = (t, v, sub) => sb.Append("<div class='card'>").Append(H(t)).Append("<b>").Append(H(v)).Append("</b><span class='n'>").Append(H(sub)).Append("</span></div>");
            card("PROP NET", M(r.PropNet), r.Passed + " passed / " + r.Bought + " bought • " + r.Payouts + " payouts");
            card("PLAIN ACCOUNT", M(r.Net), "worst drawdown " + M(r.MaxDrawdown));
            card("FIRST PAYOUT", st.HasPayout ? st.CalendarDaysToFirstPayout + " days" : "never", st.HasPayout ? st.FirstPayout.ToString("yyyy-MM-dd") + " • spent " + M(st.SpentToFirstPayout) + " before it" : "");
            card("PAYOUTS IN A ROW", st.PayoutsInARow.ToString(), "most on one account " + st.MostPayoutsOneAccount);
            card("AVERAGE PAYOUT", M(st.AvgPayout), "every " + st.AvgSessionsBetweenPayouts.ToString("0.0") + " sessions");
            card("MONEY NEEDED", M(r.MoneyNeeded), "most out of pocket at once");
            card("MONTHS IN PROFIT", st.MonthsPositive + " / " + st.Months, "best " + M(st.BestMonth) + " • worst " + M(st.WorstMonth));
            card("RANDOM ORDER", r.PassRate.ToString("0") + "% pass", "value of one evaluation " + M(r.ValuePerEval));
            sb.Append("</div>");
            Action<string, List<double>, string> svg = (title, vals, color) =>
            {
                sb.Append("<h2>").Append(H(title)).Append("</h2>");
                if (vals.Count < 2) return; double mn = Math.Min(0, vals.Min()), mx = Math.Max(1, vals.Max());
                sb.Append("<svg width='1100' height='240' style='background:#141821'><line x1='60' x2='1080' y1='").Append((14 + (mx - 0) / (mx - mn) * 200).ToString("0.#", CultureInfo.InvariantCulture)).Append("' y2='").Append((14 + (mx - 0) / (mx - mn) * 200).ToString("0.#", CultureInfo.InvariantCulture)).Append("' stroke='#555' stroke-dasharray='3,3'/><polyline fill='none' stroke='").Append(color).Append("' stroke-width='2' points='");
                for (int i = 0; i < vals.Count; i++) sb.Append((60 + i * 1020.0 / (vals.Count - 1)).ToString("0.#", CultureInfo.InvariantCulture)).Append(',').Append((14 + (mx - vals[i]) / (mx - mn) * 200).ToString("0.#", CultureInfo.InvariantCulture)).Append(' ');
                sb.Append("'/><text x='4' y='20' fill='#9aa0aa' font-size='11'>").Append(M(mx)).Append("</text><text x='4' y='218' fill='#9aa0aa' font-size='11'>").Append(M(mn)).Append("</text></svg>");
            };
            double eq = 0; svg("PLAIN ACCOUNT (1 micro each session, after costs)", r.Days.Select(d => eq += d.Pnl).ToList(), "#32c57a");
            svg("PROP • CASH − SPENT", r.PropCurve.Select(p => p.Item2).ToList(), "#ebb02b");
            sb.Append("<h2>MONTH BY MONTH • PROFIT vs EXPENSES</h2><table><tr><th>MONTH</th><th>SESSIONS</th><th>TRADING</th><th>BOUGHT</th><th>PASSED</th><th>PAYOUTS</th><th>LOST</th><th>SPENT</th><th>CASH IN</th><th>NET</th><th>RUNNING</th></tr>");
            double runN = 0;
            foreach (var g in r.Ledger.GroupBy(l => new DateTime(l.Day.Year, l.Day.Month, 1)).OrderBy(g => g.Key))
            {
                double sp = g.Sum(l => l.Spent), ca = g.Sum(l => l.Cash), tr = g.Sum(l => l.Pnl); runN += ca - sp;
                sb.Append("<tr><td>").Append(g.Key.ToString("MMM yyyy", CultureInfo.InvariantCulture)).Append("</td><td>").Append(g.Count()).Append("</td><td class='").Append(C(tr)).Append("'>").Append(M(tr)).Append("</td><td>").Append(g.Sum(l => l.Bought)).Append("</td><td>").Append(g.Sum(l => l.Passed)).Append("</td><td>").Append(g.Sum(l => l.Payouts)).Append("</td><td>").Append(g.Sum(l => l.Lost + l.Failed)).Append("</td><td class='r'>").Append(M(sp)).Append("</td><td class='g'>").Append(M(ca)).Append("</td><td class='").Append(C(ca - sp)).Append("'>").Append(M(ca - sp)).Append("</td><td class='").Append(C(runN)).Append("'>").Append(M(runN)).Append("</td></tr>");
            }
            sb.Append("</table><h2>EVERY ACCOUNT</h2><table><tr><th>#</th><th>BOUGHT</th><th>PASSED</th><th>FIRST PAYOUT</th><th>ENDED</th><th>PAYOUTS</th><th>CASH</th><th>SPENT</th><th>STATUS</th></tr>");
            foreach (var a in r.Accounts) sb.Append("<tr><td>").Append(a.No).Append("</td><td>").Append(a.Bought.ToString("yyyy-MM-dd")).Append("</td><td>").Append(a.PassedOn == DateTime.MinValue ? "–" : a.PassedOn.ToString("yyyy-MM-dd")).Append("</td><td>").Append(a.PayoutDates.Count == 0 ? "–" : a.PayoutDates[0].ToString("yyyy-MM-dd")).Append("</td><td>").Append(a.Ended == DateTime.MinValue ? "–" : a.Ended.ToString("yyyy-MM-dd")).Append("</td><td>").Append(a.Payouts).Append("</td><td class='g'>").Append(M(a.Cash)).Append("</td><td class='r'>").Append(M(a.Spent)).Append("</td><td>").Append(H(a.Status)).Append("</td></tr>");
            sb.Append("</table><h2>RANKING • EVERY VERSION</h2><table><tr><th>VERSION</th><th>TRADES</th><th>PLAIN NET</th><th>WORST DD</th><th>EVALS</th><th>PASSED</th><th>PAYOUTS</th><th>1ST PAYOUT</th><th>SPENT</th><th>PROP NET</th><th>EVERY YEAR</th></tr>");
            foreach (var x in res.Rows) sb.Append("<tr><td>").Append(H(x.Label)).Append("</td><td>").Append(x.Trades).Append("</td><td class='").Append(C(x.Net)).Append("'>").Append(M(x.Net)).Append("</td><td class='r'>").Append(M(x.MaxDrawdown)).Append("</td><td>").Append(x.Bought).Append("</td><td>").Append(x.Passed).Append("</td><td>").Append(x.Payouts).Append("</td><td>").Append(x.Stats.HasPayout ? x.Stats.CalendarDaysToFirstPayout + " d" : "never").Append("</td><td class='r'>").Append(M(x.Spent)).Append("</td><td class='").Append(C(x.PropNet)).Append("'>").Append(M(x.PropNet)).Append("</td><td>").Append(x.EveryYear ? "YES" : "no").Append("</td></tr>");
            sb.Append("</table><h2>BEST TAKE PROFIT (each instrument alone)</h2><table><tr><th>LINE</th><th>BEST FOR PROP</th><th>PROP NET</th><th>BEST PLAIN</th><th>PLAIN NET</th></tr>");
            foreach (var g in res.Grid.GroupBy(x => x.Direction + " " + x.Symbol)) { var bp = g.OrderByDescending(x => x.PropNet).First(); var bn = g.OrderByDescending(x => x.Net).First(); sb.Append("<tr><td>").Append(H(g.Key)).Append("</td><td>").Append(bp.Tp == 0 ? "HOLD" : "+" + bp.Tp).Append("</td><td class='").Append(C(bp.PropNet)).Append("'>").Append(M(bp.PropNet)).Append("</td><td>").Append(bn.Tp == 0 ? "HOLD" : "+" + bn.Tp).Append("</td><td class='").Append(C(bn.Net)).Append("'>").Append(M(bn.Net)).Append("</td></tr>"); }
            sb.Append("</table><h2>SESSIONS (BUY points)</h2><table><tr><th>PART</th><th>DAYS</th><th>UP DAYS</th><th>AVG PTS</th><th>TOTAL PTS</th></tr>");
            foreach (var m in res.Moves.Where(x => !x.Hour)) sb.Append("<tr><td>").Append(H(m.Symbol + " " + m.Name)).Append("</td><td>").Append(m.Days).Append("</td><td>").Append(m.UpPct.ToString("0")).Append("%</td><td class='").Append(C(m.AvgPts)).Append("'>").Append(m.AvgPts.ToString("0.##", CultureInfo.InvariantCulture)).Append("</td><td class='").Append(C(m.SumPts)).Append("'>").Append(m.SumPts.ToString("0.#", CultureInfo.InvariantCulture)).Append("</td></tr>");
            sb.Append("</table></body></html>");
            return sb.ToString();
        }

        private string MicroCsv()
        {
            var sb = new StringBuilder(); var res = microResult; if (res == null) return string.Empty;
            sb.AppendLine("# MICRO A DAY • " + res.Sessions + " sessions " + res.First.ToString("yyyy-MM-dd") + " -> " + res.Last.ToString("yyyy-MM-dd") + " • " + res.Rules.Describe().Replace(',', ' '));
            sb.AppendLine("rank,version,trades,won_pct,plain_net,worst_dd,underwater_days,evals,passed,payouts,funded_lost,spent,cash,prop_net,money_needed,pass_pct_random,value_per_eval,every_year,prop_by_year");
            for (int i = 0; i < res.Rows.Count; i++)
            {
                var r = res.Rows[i]; Func<double, string> f = v => v.ToString("0.##", CultureInfo.InvariantCulture);
                sb.AppendLine(string.Join(",", new[] { (i + 1).ToString(), "\"" + r.Label + "\"", r.Trades.ToString(), f(r.Trades == 0 ? 0 : 100.0 * r.Wins / r.Trades), f(r.Net), f(r.MaxDrawdown), r.LongestUnderwaterDays.ToString(), r.Bought.ToString(), r.Passed.ToString(), r.Payouts.ToString(), r.FundedLost.ToString(), f(r.Spent), f(r.Cash), f(r.PropNet), f(r.MoneyNeeded), f(r.PassRate), f(r.ValuePerEval), r.EveryYear ? "yes" : "no", "\"" + string.Join(" ", r.PropByYear.OrderBy(k => k.Key).Select(k => k.Key + ":" + f(k.Value))) + "\"" }));
            }
            sb.AppendLine(); sb.AppendLine("# TAKE PROFIT GRID"); sb.AppendLine("symbol,direction,tp,trades,hits,plain_net,worst_dd,passed,payouts,prop_net,net_by_year");
            foreach (var g in res.Grid) sb.AppendLine(string.Join(",", new[] { g.Symbol, g.Direction, g.Tp.ToString(CultureInfo.InvariantCulture), g.Trades.ToString(), g.Hits.ToString(), g.Net.ToString("0.##", CultureInfo.InvariantCulture), g.MaxDrawdown.ToString("0.##", CultureInfo.InvariantCulture), g.Passed.ToString(), g.Payouts.ToString(), g.PropNet.ToString("0.##", CultureInfo.InvariantCulture), "\"" + string.Join(" ", g.NetByYear.OrderBy(k => k.Key).Select(k => k.Key + ":" + k.Value.ToString("0", CultureInfo.InvariantCulture))) + "\"" }));
            sb.AppendLine(); sb.AppendLine("# SESSIONS AND HOURS (BUY points)"); sb.AppendLine("symbol,part,days,up_pct,avg_pts,total_pts");
            foreach (var m in res.Moves) sb.AppendLine(string.Join(",", new[] { m.Symbol, "\"" + m.Name + "\"", m.Days.ToString(), m.UpPct.ToString("0.#", CultureInfo.InvariantCulture), m.AvgPts.ToString("0.###", CultureInfo.InvariantCulture), m.SumPts.ToString("0.##", CultureInfo.InvariantCulture) }));
            if (microSelected != null)
            {
                sb.AppendLine(); sb.AppendLine("# EVERY TRADE • " + microSelected.Label); sb.AppendLine("open,symbol,side,entry,exit,exit_time,outcome,points,net,worst_open,best_open");
                foreach (var t in microSelected.TradeList.OrderBy(t => t.Open)) sb.AppendLine(string.Join(",", new[] { t.Open.ToString("yyyy-MM-dd HH:mm"), t.Symbol, t.Sell ? "SELL" : "BUY", t.Entry.ToString(CultureInfo.InvariantCulture), t.Exit.ToString(CultureInfo.InvariantCulture), t.ExitTime.ToString("yyyy-MM-dd HH:mm"), t.Outcome, t.Points.ToString("0.##", CultureInfo.InvariantCulture), t.Net.ToString("0.##", CultureInfo.InvariantCulture), t.Worst.ToString("0.##", CultureInfo.InvariantCulture), t.Best.ToString("0.##", CultureInfo.InvariantCulture) }));
                sb.AppendLine(); sb.AppendLine("# EVERY ACCOUNT • " + microSelected.Label); sb.AppendLine("no,bought,passed,ended,eval_days,funded_days,payouts,cash,spent,status");
                foreach (var a in microSelected.Accounts) sb.AppendLine(string.Join(",", new[] { a.No.ToString(), a.Bought.ToString("yyyy-MM-dd"), a.PassedOn == DateTime.MinValue ? "" : a.PassedOn.ToString("yyyy-MM-dd"), a.Ended == DateTime.MinValue ? "" : a.Ended.ToString("yyyy-MM-dd"), a.EvalDays.ToString(), a.FundedDays.ToString(), a.Payouts.ToString(), a.Cash.ToString("0.##", CultureInfo.InvariantCulture), a.Spent.ToString("0.##", CultureInfo.InvariantCulture), a.Status }));
            }
            return sb.ToString();
        }

        private void OpenMicroCompare()
        {
            if (microCompareWindow != null) { CloseToolQuietly(microCompareWindow); microCompareWindow = null; }
            var w = new KeystoneWindow { Title = "KEYSTONE ARC • MICRO A DAY • RESULTS", Width = 1500, Height = 900, MinWidth = 900, MinHeight = 560, Background = Bg, Foreground = Text, ResizeMode = ResizeMode.CanResize, WindowStartupLocation = WindowStartupLocation.CenterScreen, ShowInTaskbar = true };
            FitWindowToScreen(w);
            var root = new Grid { Margin = new Thickness(10) };
            for (int i = 0; i < 3; i++) root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            var head = new StackPanel();
            head.Children.Add(Txt("MICRO A DAY • RESULTS", Gold, 20, FontWeights.Bold));
            head.Children.Add(Txt("This window compares every version. The run you started (" + (config == null ? "" : config.MadDirection + ", TP MNQ " + config.MadMnqTarget + " / MGC " + config.MadMgcTarget) + ") is also in the lab: STEP 3 SIMULATION RESULTS (pool, first return, payout cycles, months) and the chart with replay — use GO TO LAB STEP 3.", Cyan, 11, FontWeights.Bold));
            head.Children.Add(Txt("1 micro per instrument at the " + KeystoneBracket.Hm(config == null ? 1800 : config.MadOpenHhmm) + " open, held through every session to the take profit or the close, no stop, no adding. Every version on the same days: BUY / SELL × MNQ / MGC / BOTH × take profits.", Muted, 11, FontWeights.Normal));
            Grid.SetRow(head, 0); root.Children.Add(head);
            var bar = new WrapPanel { Margin = new Thickness(0, 4, 0, 4) };
            var presets = KeystonePropRules.Presets(); var rulesBox = Select(presets.Select(p => p.Name).ToArray()); rulesBox.SelectedIndex = 0; rulesBox.Width = 280;
            var evalBox = Input("120"); evalBox.Width = 70; var actBox = Input("0"); actBox.Width = 70;
            var evalKBox = Input("1"); evalKBox.Width = 50; var fundKBox = Input("1"); fundKBox.Width = 50;
            evalKBox.ToolTip = "Micros per instrument while the account is in the evaluation (the plain account stays 1 micro)."; fundKBox.ToolTip = "Micros per instrument once the account is funded.";
            var rerun = Btn("RE-RUN WITH THESE RULES", Gold); var export = Btn("EXPORT HTML + CSV", Orchid);
            var toLab = Btn("GO TO LAB STEP 3 • POOL, CHART, REPLAY, FIRST RETURN", Cyan); toLab.Click += delegate { if (window != null) window.Activate(); if (workspaceTabs != null) workspaceTabs.SelectedIndex = 2; };
            bar.Children.Add(Txt("FIRM RULES", Gold, 11, FontWeights.Bold)); bar.Children.Add(rulesBox); bar.Children.Add(Txt("EVALUATION $", Muted, 11, FontWeights.Bold)); bar.Children.Add(evalBox);
            bar.Children.Add(Txt("ACTIVATION $", Muted, 11, FontWeights.Bold)); bar.Children.Add(actBox);
            bar.Children.Add(Txt("MICROS: EVALUATION", Muted, 11, FontWeights.Bold)); bar.Children.Add(evalKBox); bar.Children.Add(Txt("FUNDED", Muted, 11, FontWeights.Bold)); bar.Children.Add(fundKBox);
            bar.Children.Add(rerun); bar.Children.Add(export); bar.Children.Add(toLab);
            Grid.SetRow(bar, 1); root.Children.Add(bar);
            var status = Txt("MEASURING every version…", Gold, 12.5, FontWeights.Bold); status.TextWrapping = TextWrapping.Wrap; Grid.SetRow(status, 2); root.Children.Add(status);
            var tabs = new TabControl { Background = Panel, BorderBrush = Gold, BorderThickness = new Thickness(1), TabStripPlacement = Dock.Top };
            var colors = new Brush[] { Gold, Green, Cyan, Orange, Orchid, Gold, Gold, Orange, Cyan, Green };
            string[] names = { "RANKING", "CHARTS", "EVALS & FUNDED", "SIZE & SPEED", "COPY TRADING", "MONTHS", "BEST TAKE PROFIT", "SESSIONS & HOURS", "DAYS", "EACH YEAR" };
            for (int i = 0; i < names.Length; i++) tabs.Items.Add(new TabItem { Header = names[i], Background = colors[i], Foreground = Bg, FontWeight = FontWeights.Bold, Content = Txt("Measuring…", Muted, 12, FontWeights.Normal) });
            Grid.SetRow(tabs, 3); root.Children.Add(tabs); microTabs = tabs;
            var oneMinute = new List<KeystoneArcBar>(); if (KeystoneBracket.IsOneMinute(mnqBars)) oneMinute.AddRange(mnqBars); if (KeystoneBracket.IsOneMinute(mgcBars)) oneMinute.AddRange(mgcBars);
            var basis = config == null ? new KeystoneArcRunConfig() : CloneConfig(config); basis.StrategyCode = "MAD";
            Action run = null;
            run = delegate
            {
                if (oneMinute.Count == 0) { status.Text = "NO 1-MINUTE BARS LOADED • Step 1: MICRO A DAY, BOTH, your dates (several years, ending yesterday), START — this window opens by itself."; status.Foreground = Red; return; }
                var rules = presets[Math.Max(0, rulesBox.SelectedIndex)].Copy(); rules.EvalCost = Math.Max(0, NumberAllowZero(evalBox, 120)); rules.Activation = Math.Max(0, NumberAllowZero(actBox, 0));
                double evalK = Math.Max(1, Number(evalKBox, 1)), fundK = Math.Max(1, Number(fundKBox, 1));
                status.Text = "MEASURING every version, 124 take profits, sessions, accounts…"; status.Foreground = Gold; rerun.IsEnabled = false;
                var bars = oneMinute.OrderBy(b => b.Time).ToList(); basis.Start = bars[0].Time.AddMinutes(-1); basis.End = bars[bars.Count - 1].Time.AddDays(1);
                System.Threading.ThreadPool.QueueUserWorkItem(delegate
                {
                    KeystoneMicroResult res = null; string failure = null;
                    try { res = KeystoneMicroADay.Run(bars, basis, rules, evalK, fundK); } catch (Exception ex) { failure = ex.Message; }
                    Action done = delegate
                    {
                        rerun.IsEnabled = true;
                        if (failure != null || res == null) { status.Text = "ERROR • " + failure; status.Foreground = Red; return; }
                        microResult = res; microSelected = null;
                        SetMicroTab("BEST TAKE PROFIT", MicroTpView());
                        if (res.Rows.Count > 0) ShowMicroSelected(res.Rows[0], false);
                        SetMicroTab("RANKING", MicroRankingView()); tabs.SelectedIndex = 0;
                        var top = res.Rows.FirstOrDefault();
                        status.Text = (res.Sessions < 60 ? "⚠ ONLY " + res.Sessions + " SESSIONS — choose a longer date range • " : "") + res.Rows.Count + " VERSIONS • " + res.Sessions + " sessions " + res.First.ToString("yyyy-MM-dd") + " → " + res.Last.ToString("yyyy-MM-dd") + " • " + rules.Name + " • " + evalK + " micros in the evaluation, " + fundK + " funded" + (top != null ? " • #1 " + top.Label + " • prop " + Signed(top.PropNet) + " • plain " + Signed(top.Net) : "");
                        status.Foreground = res.Sessions < 60 ? Red : top != null && top.PropNet > 0 ? Green : Red;
                        microCompareRows = res.Rows;
                    };
                    if (w.Dispatcher == null || w.Dispatcher.CheckAccess()) done(); else w.Dispatcher.BeginInvoke(done);
                });
            };
            rerun.Click += delegate { run(); };
            export.Click += delegate
            {
                if (microResult == null) { status.Text = "RUN FIRST"; status.Foreground = Gold; return; }
                try
                {
                    string dir = DataDirectory(); Directory.CreateDirectory(dir); string stem = Path.Combine(dir, "KeystoneArc_MicroADay_" + DateTime.Now.ToString("yyyyMMdd_HHmmss"));
                    File.WriteAllText(stem + ".csv", MicroCsv(), Encoding.UTF8); File.WriteAllText(stem + ".html", MicroHtml(), Encoding.UTF8);
                    status.Text = "EXPORTED " + stem + ".html + .csv • open the HTML in your browser, attach both to Claude"; status.Foreground = Green;
                    try { System.Diagnostics.Process.Start(stem + ".html"); } catch { }
                }
                catch (Exception ex) { status.Text = "EXPORT ERROR • " + ex.Message; status.Foreground = Red; }
            };
            ConfirmToolClose(w, "MICRO A DAY RESULTS");
            w.Content = root; microCompareWindow = w; microCompareStatus = status; microRerun = run;
            w.Closed += delegate { microCompareWindow = null; microCompareStatus = null; microTabs = null; microRerun = null; };
            w.Show();
            run();
        }

        private bool IsBracketSelected() { string s = Convert.ToString(strategyBox == null ? null : strategyBox.SelectedItem ?? string.Empty); return s.StartsWith("PROP BRACKET", StringComparison.OrdinalIgnoreCase) || s.StartsWith("FIRST 5M FVG STUDY", StringComparison.OrdinalIgnoreCase) || IsRotationSelected(); }
        private bool IsRotationSelected() { return strategyBox != null && Convert.ToString(strategyBox.SelectedItem ?? string.Empty).StartsWith("ROTATION •", StringComparison.OrdinalIgnoreCase); }
        private bool BracketStudy() { return config != null && string.Equals(config.StrategyCode, "BRK", StringComparison.OrdinalIgnoreCase); }
        private readonly List<UIElement> bracketStrategyControls = new List<UIElement>();
        private bool bracketDefaultsApplied;
        private UIElement BuildBracketPanel()
        {
            var panel = Stack(); panel.Margin = new Thickness(0, 4, 0, 2);
            panel.Children.Add(Txt("FIRST 5M FVG STUDY • START LOADS 1-MINUTE MNQ + MGC, THEN MOVE STUDY OPENS", Gold, 13, FontWeights.Bold));
            panel.Children.Add(Txt("MNQ from 09:30, MGC from 08:00 (change them in MOVE STUDY). Sets compared side by side, each instrument separately: first FVG touch • 25% • 50% • green close + break • prior untouched FVG (touch, 50%) • first 5M BH. Every entry is followed to the close: points for / against / before the best / close, per year, vs buying at the start. End the range yesterday so the data is saved for next time.", Text, 10.5, FontWeights.Normal));
            panel.Children.Add(Txt("PROP BRACKET (same 1-minute load) also feeds the ROTATION TESTER and the PROP PLANNER buttons.", Muted, 10, FontWeights.Bold));
            panel.Children.Add(Txt("START loads real 1-minute bars 07:00–16:00 New York for the dates above (MNQ, MGC or BOTH) and opens the PROP PLANNER with REAL BRACKET days. There you choose (or let FIND SWEET SPOT choose) the entry time, the direction rule, the contracts and the target / stop for the evaluation and the funded account. Every day is replayed on the 1-minute bars; when a minute touches both the target and the stop, the stop counts first. The session choice above is not used — the planner's entry and close times decide.", Muted, 10, FontWeights.Normal));
            panel.Children.Add(Txt("TIP: 2 years or more (e.g. 2024-01-01 → today) so the sweet spot can check that a rule worked in EVERY year, not just one lucky stretch.", Cyan, 10, FontWeights.Bold));
            bracketStrategyControls.Clear(); bracketStrategyControls.Add(panel);
            panel.Visibility = Visibility.Collapsed;
            return panel;
        }
        private bool IsRecoilSelected() { return strategyBox != null && Convert.ToString(strategyBox.SelectedItem ?? string.Empty).StartsWith("RECOIL", StringComparison.OrdinalIgnoreCase); }
        private bool RecoilStudy() { return config != null && string.Equals(config.StrategyCode, "RCL", StringComparison.OrdinalIgnoreCase); }

        private UIElement BuildRecoilPanel()
        {
            var panel = Stack(); panel.Margin = new Thickness(0, 4, 0, 2);
            panel.Children.Add(Txt("RECOIL • ADD TO LOSERS", Orchid, 13, FontWeights.Bold));
            panel.Children.Add(Txt("From the start time, wait for the price to move TRIGGER points up or down. Enter AGAINST the move (down → BUY, up → SELL), add contracts every STEP points further against you up to MAX ENTRIES. The ladder closes at its profit target, at the maximum drawdown, or at the close. Each contract keeps its own fill price — the average and the P/L are exact.", Muted, 10, FontWeights.Normal));
            rcMnqStartBox = Input("930"); rcMgcStartBox = Input("930"); rcLastEntryBox = Input("1500"); rcCloseBox = Input("1600");
            rcSameStartBox = new CheckBox { Content = "MNQ AND MGC START LOOKING AT THE SAME TIME", IsChecked = true, Foreground = Text, Margin = new Thickness(6) };
            rcMnqTriggerBox = Input("100"); rcMgcTriggerBox = Input("20"); rcMnqStepBox = Input("100"); rcMgcStepBox = Input("20");
            rcLadderBox = Select("+1 EACH ADD • 1 → 2 → 3 → 4", "GROWING • 1 → 3 → 6 → 10", "DOUBLING • 1 → 2 → 4 → 8"); rcLadderBox.SelectedIndex = 0;
            rcModeBox = Select("ADD TO THE LOSER • ladder 1 → 2 → 3 → 4 contracts", "STOP AND REVERSE • 1, then 2 the other way, 3, 4"); rcModeBox.SelectedIndex = 0;
            rcMaxEntriesBox = Input("4"); rcBaseQtyBox = Input("1");
            rcTargetModeBox = Select("$ FOR THE WHOLE LADDER", "POINTS FROM THE AVERAGE PRICE"); rcTargetModeBox.SelectedIndex = 0;
            rcTargetBox = Input("400"); rcMnqTargetPtsBox = Input("50"); rcMgcTargetPtsBox = Input("10");
            rcMaxDdBox = Input("2000"); rcDdModeBox = Select("SHARED • MNQ + MGC TOGETHER", "SPLIT • EACH INSTRUMENT ITS OWN"); rcDdModeBox.SelectedIndex = 0;
            rcMnqDdBox = Input("2000"); rcMgcDdBox = Input("2000"); rcCyclesBox = Input("1");
            rcMnqPvBox = Input("2"); rcMgcPvBox = Input("10"); rcCommissionBox = Input("0.62"); rcSlipBox = Input("1"); rcStartBalanceBox = Input("5000");
            foreach (TextBox b in new[] { rcMnqStartBox, rcMgcStartBox, rcLastEntryBox, rcCloseBox, rcMnqTriggerBox, rcMgcTriggerBox, rcMnqStepBox, rcMgcStepBox, rcMaxEntriesBox, rcBaseQtyBox, rcTargetBox, rcMnqTargetPtsBox, rcMgcTargetPtsBox, rcMaxDdBox, rcMnqDdBox, rcMgcDdBox, rcCyclesBox, rcMnqPvBox, rcMgcPvBox, rcCommissionBox, rcSlipBox, rcStartBalanceBox })
            { WatchConfigurationInput(b); b.TextChanged += delegate { UpdateRecoilPreview(); }; }
            foreach (ComboBox b in new[] { rcLadderBox, rcTargetModeBox, rcDdModeBox, rcModeBox }) b.SelectionChanged += delegate { InvalidateConfigurationApproval(); UpdateRecoilPreview(); };
            rcSameStartBox.Checked += delegate { InvalidateConfigurationApproval(); UpdateRecoilPreview(); }; rcSameStartBox.Unchecked += delegate { InvalidateConfigurationApproval(); UpdateRecoilPreview(); };
            panel.Children.Add(Txt("1 • WHEN (NEW YORK TIME, HHMM)", Cyan, 10, FontWeights.Bold));
            panel.Children.Add(Row("MNQ STARTS LOOKING AT", rcMnqStartBox)); panel.Children.Add(Row("MGC STARTS LOOKING AT", rcMgcStartBox)); panel.Children.Add(Row("BOTH", rcSameStartBox));
            panel.Children.Add(Row("NO NEW LADDER AFTER", rcLastEntryBox)); panel.Children.Add(Row("CLOSE EVERYTHING AT", rcCloseBox));
            panel.Children.Add(Row("LADDERS A DAY PER INSTRUMENT (a new one only after a win)", rcCyclesBox));
            panel.Children.Add(Txt("2 • TRIGGER AND WHAT HAPPENS AFTER A LOSS (POINTS)", Cyan, 10, FontWeights.Bold));
            panel.Children.Add(Row("AFTER EVERY STEP POINTS AGAINST US", rcModeBox));
            panel.Children.Add(Txt("ADD = keep the position and add one more. REVERSE = close it (a loss) and open the next size the other way; the target makes the WHOLE cycle +TARGET $. Each run also runs the other mode on the same days for the comparison.", Muted, 9.5, FontWeights.Normal));
            panel.Children.Add(Row("MNQ: ENTER AFTER A MOVE OF", rcMnqTriggerBox)); panel.Children.Add(Row("MNQ: ADD EVERY", rcMnqStepBox));
            panel.Children.Add(Row("MGC: ENTER AFTER A MOVE OF", rcMgcTriggerBox)); panel.Children.Add(Row("MGC: ADD EVERY", rcMgcStepBox));
            panel.Children.Add(Row("LADDER", rcLadderBox)); panel.Children.Add(Row("MAX ENTRIES (FIRST + ADDS)", rcMaxEntriesBox)); panel.Children.Add(Row("FIRST ENTRY CONTRACTS", rcBaseQtyBox));
            panel.Children.Add(Txt("3 • EXIT", Cyan, 10, FontWeights.Bold));
            panel.Children.Add(Row("PROFIT TARGET", rcTargetModeBox)); panel.Children.Add(Row("TARGET $ (WHOLE LADDER)", rcTargetBox));
            panel.Children.Add(Row("MNQ TARGET POINTS (FROM THE AVERAGE)", rcMnqTargetPtsBox)); panel.Children.Add(Row("MGC TARGET POINTS (FROM THE AVERAGE)", rcMgcTargetPtsBox));
            panel.Children.Add(Row("MAX DRAWDOWN $ (THE BLOWUP)", rcMaxDdBox)); panel.Children.Add(Row("WITH BOTH INSTRUMENTS", rcDdModeBox));
            panel.Children.Add(Row("SPLIT: MNQ MAX DRAWDOWN $", rcMnqDdBox)); panel.Children.Add(Row("SPLIT: MGC MAX DRAWDOWN $", rcMgcDdBox));
            panel.Children.Add(Txt("4 • MONEY", Cyan, 10, FontWeights.Bold));
            panel.Children.Add(Row("MNQ $ PER POINT PER CONTRACT (CFD: PER LOT)", rcMnqPvBox)); panel.Children.Add(Row("MGC $ PER POINT PER CONTRACT (CFD: PER LOT)", rcMgcPvBox));
            panel.Children.Add(Row("COMMISSION $ PER CONTRACT PER SIDE", rcCommissionBox)); panel.Children.Add(Row("SLIPPAGE TICKS ON STOP / CLOSE EXITS", rcSlipBox));
            panel.Children.Add(Row("ONE LIVE ACCOUNT START $", rcStartBalanceBox));
            rcPreviewText = Txt(string.Empty, Green, 10, FontWeights.Bold); rcPreviewText.FontFamily = new FontFamily("Consolas"); panel.Children.Add(rcPreviewText);
            UpdateRecoilPreview();
            recoilStrategyControls.Clear(); recoilStrategyControls.Add(panel);
            panel.Visibility = Visibility.Collapsed;
            return panel;
        }

        // The ladder in numbers before the run: each entry, the average, the open P/L there and where it blows up.
        private void UpdateRecoilPreview()
        {
            if (rcPreviewText == null) return;
            if (rcSameStartBox != null && rcMgcStartBox != null && rcMnqStartBox != null) { rcMgcStartBox.IsEnabled = rcSameStartBox.IsChecked != true; if (rcSameStartBox.IsChecked == true && rcMgcStartBox.Text != rcMnqStartBox.Text) rcMgcStartBox.Text = rcMnqStartBox.Text; }
            KeystoneRecoilConfig c; string err;
            if (!ReadRecoilConfig(out c, out err, false)) { rcPreviewText.Text = "⚠ " + err; rcPreviewText.Foreground = Red; return; }
            var sb = new StringBuilder();
            if (c.Mode == "REVERSE")
            {
                foreach (string sym in new[] { "MNQ", "MGC" })
                {
                    bool mg = sym == "MGC"; double step = mg ? c.MgcStep : c.MnqStep, pv = mg ? c.MgcPointValue : c.MnqPointValue; double lost = 0;
                    sb.AppendLine(sym + " STOP AND REVERSE (first trade a BUY, $" + pv.ToString("0.##") + "/pt):");
                    for (int k = 0; k < c.MaxEntries; k++)
                    {
                        int q = KeystoneRecoil.ReverseQty(c, k); double need = c.TargetMode == "POINTS" ? (mg ? c.MgcTargetPoints : c.MnqTargetPoints) : (c.TargetDollars + lost) / (q * pv);
                        sb.AppendLine("  STEP " + (k + 1) + "  " + (k % 2 == 0 ? "BUY " : "SELL") + " " + q + "  target needs +" + need.ToString("0.#") + " pts • stop " + step.ToString("0.#") + " pts = −" + Cash(step * q * pv) + " • lost so far if stopped " + Cash(-(lost + step * q * pv)));
                        lost += step * q * pv;
                    }
                }
                rcPreviewText.Text = sb.ToString().TrimEnd(); rcPreviewText.Foreground = Green; return;
            }
            foreach (string sym in new[] { "MNQ", "MGC" })
            {
                bool mg = sym == "MGC"; double step = mg ? c.MgcStep : c.MnqStep, pv = mg ? c.MgcPointValue : c.MnqPointValue, dd = c.DrawdownMode == "SPLIT" ? (mg ? c.MgcMaxDrawdown : c.MnqMaxDrawdown) : c.MaxDrawdown;
                sb.AppendLine(sym + " (BUY example, first entry at 0, $" + pv.ToString("0.##") + "/pt):");
                double S = 0, Q = 0;
                for (int k = 0; k < c.MaxEntries; k++)
                {
                    double px = -k * step; int q = KeystoneRecoil.AddQty(c, k); S += px * q; Q += q;
                    double avg = S / Q, pl = (Q * px - S) * pv, tp = c.TargetMode == "POINTS" ? avg + (mg ? c.MgcTargetPoints : c.MnqTargetPoints) : avg + c.TargetDollars / (Q * pv);
                    sb.AppendLine("  " + (k == 0 ? "ENTRY" : "ADD " + k).PadRight(6) + " @ " + px.ToString("0.#").PadLeft(6) + "  +" + q + " = " + Q.ToString("0").PadLeft(3) + " contracts  avg " + avg.ToString("0.#").PadLeft(7) + "  open P/L " + Signed(pl).PadLeft(8) + "  target at " + tp.ToString("0.#"));
                }
                double blow = (S - dd / pv) / Q;
                sb.AppendLine("  BLOWUP at " + blow.ToString("0.#") + " (" + (-blow).ToString("0.#") + " pts below the first entry) = −" + Cash(dd) + (blow > -(c.MaxEntries - 1) * step ? "  ⚠ before the last add" : ""));
            }
            rcPreviewText.Text = sb.ToString().TrimEnd(); rcPreviewText.Foreground = Green;
        }

        private bool ReadRecoilConfig(out KeystoneRecoilConfig c, out string error, bool strict = true)
        {
            c = new KeystoneRecoilConfig(); error = null;
            int ms = Integer(rcMnqStartBox, 930), gs = rcSameStartBox != null && rcSameStartBox.IsChecked == true ? ms : Integer(rcMgcStartBox, 930), le = Integer(rcLastEntryBox, 1500), cl = Integer(rcCloseBox, 1600);
            if (!IsValidHhmm(ms) || !IsValidHhmm(gs) || !IsValidHhmm(le) || !IsValidHhmm(cl)) { error = "times must be HHMM from 0000 to 2359"; return false; }
            if (cl <= Math.Min(ms, gs) || le > cl) { error = "the close must be after the start and the last entry not after the close (same day)"; return false; }
            c.MnqStartHhmm = ms; c.MgcStartHhmm = gs; c.LastEntryHhmm = le; c.CloseHhmm = cl;
            c.MnqTrigger = Number(rcMnqTriggerBox, 100); c.MgcTrigger = Number(rcMgcTriggerBox, 20); c.MnqStep = Number(rcMnqStepBox, 100); c.MgcStep = Number(rcMgcStepBox, 20);
            c.Ladder = new[] { "ONE", "STEP", "DOUBLE" }[Math.Max(0, Math.Min(2, rcLadderBox == null ? 0 : rcLadderBox.SelectedIndex))];
            c.MaxEntries = Math.Max(1, Math.Min(12, Integer(rcMaxEntriesBox, 4))); c.BaseQty = Math.Max(1, Integer(rcBaseQtyBox, 1));
            c.TargetMode = rcTargetModeBox != null && rcTargetModeBox.SelectedIndex == 1 ? "POINTS" : "DOLLARS";
            c.TargetDollars = Number(rcTargetBox, 400); c.MnqTargetPoints = Number(rcMnqTargetPtsBox, 50); c.MgcTargetPoints = Number(rcMgcTargetPtsBox, 10);
            c.MaxDrawdown = Number(rcMaxDdBox, 2000); c.DrawdownMode = rcDdModeBox != null && rcDdModeBox.SelectedIndex == 1 ? "SPLIT" : "SHARED";
            c.MnqMaxDrawdown = Number(rcMnqDdBox, 2000); c.MgcMaxDrawdown = Number(rcMgcDdBox, 2000);
            c.CyclesPerDay = Math.Max(1, Integer(rcCyclesBox, 1));
            c.Mode = rcModeBox != null && rcModeBox.SelectedIndex == 1 ? "REVERSE" : "ADD";
            c.MnqPointValue = Number(rcMnqPvBox, 2); c.MgcPointValue = Number(rcMgcPvBox, 10); c.CommissionPerSide = NumberAllowZero(rcCommissionBox, 0.62); c.SlippageTicks = NumberAllowZero(rcSlipBox, 1);
            string scope = config == null ? "MNQ" : (config.Scope ?? "MNQ");
            if (scopeBox != null && !strict) scope = Convert.ToString(scopeBox.SelectedItem ?? scope);
            c.UseMnq = scope == "MGC" ? 0 : 1; c.UseMgc = scope == "MNQ" ? 0 : 1;
            if (config != null && config.Start > DateTime.MinValue) c.Start = config.Start.Date;
            if (config != null && config.End < DateTime.MaxValue && config.End > DateTime.MinValue) c.End = config.End.Date;
            if (c.MnqTrigger <= 0 || c.MgcTrigger <= 0 || c.MnqStep <= 0 || c.MgcStep <= 0) { error = "trigger and add distances must be above 0"; return false; }
            if (c.MaxDrawdown <= 0) { error = "max drawdown must be above 0"; return false; }
            return true;
        }

        private void RunRecoil()
        {
            if (isProcessing) { UpdateUi("PROCESSING IS ALREADY RUNNING • WAIT FOR STATUS", Gold); return; }
            KeystoneRecoilConfig rc; string error;
            if (!ReadRecoilConfig(out rc, out error)) { UpdateUi("RECOIL SETTINGS ERROR • " + error, Red); return; }
            if ((rc.UseMnq == 1 && mnqBars.Count == 0) || (rc.UseMgc == 1 && mgcBars.Count == 0)) { UpdateUi("RECOIL NEEDS VERIFIED 1-MINUTE BARS FOR " + (rc.UseMnq == 1 && mnqBars.Count == 0 ? "MNQ" : "MGC") + " • press START with RECOIL selected", Red); return; }
            double startBalance = Math.Max(1, Number(rcStartBalanceBox, 5000));
            var mnqCopy = rc.UseMnq == 1 ? new List<KeystoneArcBar>(mnqBars) : new List<KeystoneArcBar>(); var mgcCopy = rc.UseMgc == 1 ? new List<KeystoneArcBar>(mgcBars) : new List<KeystoneArcBar>();
            string key = mnqCopy.Count + "|" + mgcCopy.Count + "|" + (mnqCopy.Count > 0 ? mnqCopy[0].Time.Ticks + "|" + mnqCopy[mnqCopy.Count - 1].Time.Ticks : "0") + "|" + (mgcCopy.Count > 0 ? mgcCopy[0].Time.Ticks + "|" + mgcCopy[mgcCopy.Count - 1].Time.Ticks : "0");
            List<KeystoneHelixMinute> cached = key == recoilMinutesKey ? recoilMinutes : null;
            isProcessing = true;
            BeginBusy("RECOIL • RUNNING EVERY LADDER + THE RISK GRID");
            UpdateUi("RECOIL RUNNING • " + rc.Describe(), Gold);
            System.Threading.ThreadPool.QueueUserWorkItem(delegate
            {
                List<KeystoneHelixMinute> minutes = null; KeystoneRecoilResult result = null; var grids = new List<KeystoneRecoilGrid>(); var compare = new List<Tuple<string, KeystoneRecoilStats, KeystoneRecoilAccount>>(); var modes = new List<Tuple<string, KeystoneRecoilStats, KeystoneRecoilAccount>>(); string failure = null;
                try
                {
                    minutes = cached ?? KeystoneHelix.Align(mnqCopy, mgcCopy);
                    result = KeystoneRecoil.Run(minutes, rc);
                    // The other mode on the same days: ADD vs STOP AND REVERSE.
                    var other = rc.Copy(); other.Mode = rc.Mode == "REVERSE" ? "ADD" : "REVERSE";
                    var otherRun = KeystoneRecoil.Run(minutes, other);
                    foreach (var t in rc.Mode == "REVERSE" ? new[] { Tuple.Create("ADD TO LOSERS", otherRun), Tuple.Create("STOP AND REVERSE", result) } : new[] { Tuple.Create("ADD TO LOSERS", result), Tuple.Create("STOP AND REVERSE", otherRun) })
                        modes.Add(Tuple.Create(t.Item1, KeystoneRecoilStudy.Stats(t.Item1, t.Item2.Cycles, t.Item2.Days.Count, t.Item2.NoTriggerDays.Values.Sum()), KeystoneRecoilStudy.Account(t.Item2.Cycles, startBalance)));
                    if (rc.UseMnq == 1) grids.AddRange(KeystoneRecoilStudy.Grids(minutes, rc, "MNQ"));
                    if (rc.UseMgc == 1) grids.AddRange(KeystoneRecoilStudy.Grids(minutes, rc, "MGC"));
                    // MNQ only • MGC only • BOTH with the same settings (when both are loaded)
                    if (rc.UseMnq == 1 && rc.UseMgc == 1)
                        foreach (var t in new[] { Tuple.Create("MNQ ONLY", 1, 0), Tuple.Create("MGC ONLY", 0, 1), Tuple.Create("BOTH", 1, 1) })
                        {
                            var c = rc.Copy(); c.UseMnq = t.Item2; c.UseMgc = t.Item3;
                            if (c.UseMgc == 0 && rc.DrawdownMode == "SPLIT") c.MaxDrawdown = rc.MnqMaxDrawdown;
                            if (c.UseMnq == 0 && rc.DrawdownMode == "SPLIT") c.MaxDrawdown = rc.MgcMaxDrawdown;
                            var rr = t.Item1 == "BOTH" ? result : KeystoneRecoil.Run(minutes, c);
                            compare.Add(Tuple.Create(t.Item1, KeystoneRecoilStudy.Stats(t.Item1, rr.Cycles, rr.Days.Count, rr.NoTriggerDays.Values.Sum()), KeystoneRecoilStudy.Account(rr.Cycles, startBalance)));
                        }
                }
                catch (Exception ex) { failure = ex.Message; }
                DispatchToLab(delegate
                {
                    if (failure != null || result == null) { isProcessing = false; EndBusy(); UpdateUi("RECOIL ERROR • " + failure, Red); UpdateWorkflowState(); return; }
                    recoilMinutes = minutes; recoilMinutesKey = key; recoilResult = result; recoilConfig = rc; recoilGrids = grids; recoilCompare = compare; recoilModeCompare = modes; recoilGridIndex = 0;
                    recoilCycleById = result.Cycles.ToDictionary(x => x.Id);
                    events = RecoilEvents(result);
                    loadedEvents = events; loadedScope = config.Scope; viewScope = config.Scope; loadedAsianLoss = config.AsianDailyLossLimitDollars;
                    accounts = new List<KeystoneArcVirtualAccount>();
                    researchRunCompleted = true; unsavedResearch = events.Count > 0;
                    KeystoneArcHub.Publish(new List<KeystoneArcEvent>(), config);
                    RenderEvents(); RebuildReviewList();
                    SetGoldenResultsMode(false); SetHelixResultsMode(false);
                    SetRecoilResultsMode(true);
                    RenderRecoilResults();
                    if (evidenceWindow != null) { evidenceOverlayCache.Clear(); RenderEvidenceChart(); }
                    isProcessing = false; EndBusy();
                    var s = KeystoneRecoilStudy.Stats("ALL", result.Cycles, result.Days.Count);
                    UpdateUi("RECOIL COMPLETE • " + result.Cycles.Count + " LADDERS ON " + result.Days.Count + " DAYS • WON " + KeystoneRecoilStudy.Pc(s.WinRate) + " • BLOWN " + s.Blowups + " • NET " + Cash(s.Net) + " • Step 3 shows everything", s.Net >= 0 ? Green : Gold);
                    UpdateWorkflowState();
                    if (workspaceTabs != null && resultsTab != null) { resultsTab.IsEnabled = true; workspaceTabs.SelectedIndex = 2; }
                });
            });
        }

        // One ledger row per ladder (pins, replay steps, review list, exports).
        private List<KeystoneArcEvent> RecoilEvents(KeystoneRecoilResult r)
        {
            var list = new List<KeystoneArcEvent>();
            foreach (var c in r.Cycles)
            {
                if (c.Fills.Count == 0) continue;
                var last = c.Fills[c.Fills.Count - 1];
                list.Add(new KeystoneArcEvent
                {
                    Id = "RCL-" + c.Id.ToString("00000"), Symbol = c.Symbol, SetupClass = "RCL", Direction = c.Dir > 0 ? "LONG" : "SHORT", StrengthTag = c.Entries + " ENTRIES",
                    ReferenceTime = c.AnchorTime, TriggerTime = c.Fills[0].Time, EntryTime = c.Fills[0].Time, Entry = c.Fills[0].Price,
                    Stop = double.IsNaN(last.StopPrice) ? double.NaN : last.StopPrice, Target = last.TargetPrice, Quantity = c.MaxQty, StopDistance = double.IsNaN(last.StopPrice) ? 0 : Math.Abs(c.Fills[0].Price - last.StopPrice),
                    RiskModel = "RCL LADDER", ExitTime = c.ExitTime, ExitPrice = c.ExitPrice, Outcome = c.Win ? "WIN" : (c.Reason == "SESSION END" ? "SESSION EXIT" : "LOSS"), GrossPnl = c.Net,
                    PeakAfterEntry = c.MfeValue, TroughAfterEntry = c.MaeValue, SessionOrder = c.Id, ReviewState = "ACCEPTED", ReviewNote = RecoilCycleText(c)
                });
            }
            return list;
        }

        private string RecoilCycleText(KeystoneRecoilCycle c)
        {
            string f = c.Symbol == "MGC" ? "0.0" : "0.00";
            var sb = new StringBuilder();
            sb.AppendLine((c.Mode == "REVERSE" ? "RECOIL STOP-AND-REVERSE #" : "RECOIL LADDER #") + c.Id + " • " + c.Symbol + " • " + c.Day.ToString("ddd yyyy-MM-dd", CultureInfo.InvariantCulture) + " • ladder " + c.CycleInDay + " of the day");
            sb.AppendLine("START " + c.AnchorPrice.ToString(f) + " at " + Hm(c.AnchorTime) + " → moved " + (c.Dir > 0 ? "DOWN" : "UP") + " to " + c.TriggerLevel.ToString(f) + " → " + c.Side);
            foreach (var x in c.Fills)
                sb.AppendLine(c.Mode == "REVERSE"
                    ? "  " + Hm(x.Time) + "  " + (x == c.Fills[0] ? "" : "REVERSE → ") + (x.Dir > 0 ? "BUY " : "SELL ") + x.Qty + " @ " + x.Price.ToString(f) + (x.Gap ? " (gap)" : "") + " • target " + x.TargetPrice.ToString(f) + " • stop " + x.StopPrice.ToString(f)
                    : "  " + Hm(x.Time) + "  " + (x == c.Fills[0] ? c.Side : "ADD") + " " + x.Qty + " @ " + x.Price.ToString(f) + (x.Gap ? " (gap)" : "") + " → " + x.TotalQty + " contracts, average " + x.Avg.ToString(f) + " • target " + x.TargetPrice.ToString(f) + (double.IsNaN(x.StopPrice) ? " • blowup = shared $ drawdown" : " • blowup " + x.StopPrice.ToString(f)));
            sb.AppendLine("EXIT " + Hm(c.ExitTime) + " @ " + c.ExitPrice.ToString(f) + " • " + (c.Win ? "TARGET" : c.Reason) + (c.Ambiguous ? " (the trigger minute touched both sides)" : "") + " • gross " + Signed(c.Gross) + " − costs " + Cash(c.Commission + c.Slippage) + " = " + Signed(c.Net));
            sb.AppendLine("WORST OPEN P/L " + Signed(c.MaeValue) + " • BEST " + Signed(c.MfeValue));
            if (!double.IsNaN(c.LowestPrice))
                sb.Append("BOUNCE • the worst price until the close was " + c.LowestPrice.ToString(f) + " (" + Hm(c.LowestTime) + "); after it the best was " + (double.IsNaN(c.BestAfterLowest) ? "—" : c.BestAfterLowest.ToString(f) + " (" + Hm(c.BestAfterLowestTime) + ")")
                    + " • the full ladder (" + c.FullLadderEntries + " entries, no stop) would have been " + Signed(c.FullLadderAtLowest) + " at the worst and " + Signed(c.FullLadderAtBest) + " at the best");
            return sb.ToString().TrimEnd();
        }

        // ---- Step 3 RECOIL view ------------------------------------------------------------------
        private void SetRecoilResultsMode(bool on)
        {
            if (recoilResultsHost == null) return;
            if (on && helixResultsMode) SetHelixResultsMode(false);
            if (on && goldenResultsMode) SetGoldenResultsMode(false);
            if (on && !recoilResultsMode && oneDayPoolMetrics != null) oneDayMetricsVisibilityBeforeRecoil = oneDayPoolMetrics.Visibility;
            bool was = recoilResultsMode;
            if (!on && recoilSummaryHidden) SetRecoilSummaryHidden(false);
            recoilResultsMode = on;
            recoilResultsHost.Visibility = on ? Visibility.Visible : Visibility.Collapsed;
            if (!on && !was) return;
            Visibility normal = on ? Visibility.Collapsed : Visibility.Visible;
            if (poolLifecycleMetrics != null) poolLifecycleMetrics.Visibility = normal;
            if (oneDayPoolMetrics != null) oneDayPoolMetrics.Visibility = on ? Visibility.Collapsed : oneDayMetricsVisibilityBeforeRecoil;
            if (resultViewTabs != null) resultViewTabs.Visibility = normal;
            if (normalResultActions != null) normalResultActions.Visibility = normal;
            if (normalResultClearRow != null) normalResultClearRow.Visibility = normal;
            if (poolResultBanner != null) poolResultBanner.Visibility = normal;
            if (instrumentSplitText != null && on) instrumentSplitText.Visibility = Visibility.Collapsed;
            if (resultsHeadingText != null) resultsHeadingText.Text = on ? "RECOIL • ADD TO LOSERS • SETUPS, RISK GRID AND ONE LIVE ACCOUNT" : "PROP VIRTUAL-POOL RESULTS • ALL ELIGIBLE SETUPS";
            SizeRecoilHost();
        }

        private void SizeRecoilHost()
        {
            if (recoilResultsHost == null || !recoilResultsMode) return;
            double page = resultsPageScroll == null ? 0 : resultsPageScroll.ActualHeight, top = resultsTopPanel == null ? 0 : resultsTopPanel.ActualHeight;
            recoilResultsHost.Height = page > 200 ? Math.Max(520, page - top - 18) : 760;
        }

        private void SetRecoilSummaryHidden(bool hide)
        {
            recoilSummaryHidden = hide;
            Visibility v = hide ? Visibility.Collapsed : Visibility.Visible;
            if (recoilVerdictCard != null) recoilVerdictCard.Visibility = v;
            if (recoilTiles != null) recoilTiles.Visibility = v;
            if (resultsTopPanel != null && recoilResultsMode) resultsTopPanel.Visibility = v;
            if (recoilSummaryToggle != null) recoilSummaryToggle.Content = hide ? "▼ SHOW SUMMARY" : "▲ FULL SCREEN TABLES";
            if (resultsPageScroll != null) resultsPageScroll.ScrollToTop();
            SizeRecoilHost();
        }

        private UIElement BuildRecoilResultsHost()
        {
            var g = new Grid { Visibility = Visibility.Collapsed };
            for (int i = 0; i < 3; i++) g.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            g.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            var head = new Grid(); head.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) }); head.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            var verdict = new StackPanel();
            recoilVerdictHead = new TextBlock { Text = "RECOIL", Foreground = Gold, FontSize = 20, FontWeight = FontWeights.Bold, TextWrapping = TextWrapping.Wrap };
            recoilVerdictSub = new TextBlock { Text = "Choose RECOIL in Step 1 and press START.", Foreground = Text, FontSize = 11, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 2, 0, 0) };
            verdict.Children.Add(recoilVerdictHead); verdict.Children.Add(recoilVerdictSub); head.Children.Add(verdict);
            var actions = new UniformGrid { Columns = 2, Margin = new Thickness(8, 0, 0, 0), Width = 430 };
            var rerun = Btn("RE-RUN WITH STEP 1 SETTINGS", Green); rerun.ToolTip = "Reads the RECOIL settings in Step 1 again and re-runs on the bars already loaded (no reload).";
            var export = Btn("EXPORT REPORT (HTML + CSV)", Gold);
            var chart = Btn("LADDERS ON THE CHART", Blue);
            var verify = Btn("LADDER LIST (STEP 2)", Cyan);
            var planWith = Btn("PROP PLANNER WITH THESE DAYS", Orchid); planWith.ToolTip = "Open the PROP PLANNER with the RECOIL days as the source: pass rate, payouts, value of one evaluation, separate vs copy vs rotation, history by year.";
            planWith.Click += delegate { if (propPlannerWindow != null) { CloseToolQuietly(propPlannerWindow); propPlannerWindow = null; } string sym = recoilResult == null ? null : (recoilResult.Cycles.Select(c => c.Symbol).Distinct().Count() > 1 ? "BOTH" : recoilResult.Cycles.Select(c => c.Symbol).FirstOrDefault()); OpenPropPlanner(sym); };
            foreach (var b in new[] { rerun, export, chart, verify, planWith }) { b.Height = 30; b.FontSize = 11; actions.Children.Add(b); }
            rerun.Click += delegate { RunRecoil(); };
            export.Click += delegate { ExportRecoilReport(); };
            chart.Click += delegate { OpenRecoilChart(null); };
            verify.Click += delegate { if (workspaceTabs != null) workspaceTabs.SelectedIndex = 1; };
            Grid.SetColumn(actions, 1); head.Children.Add(actions);
            recoilVerdictCard = new Border { Background = Card, BorderBrush = Gold, BorderThickness = new Thickness(5, 1.5, 1.5, 1.5), CornerRadius = new CornerRadius(6), Padding = new Thickness(12, 8, 10, 8), Margin = new Thickness(2, 2, 2, 4), Child = head };
            g.Children.Add(recoilVerdictCard);
            recoilTiles = new WrapPanel { Margin = new Thickness(0, 0, 0, 2) }; Grid.SetRow(recoilTiles, 1); g.Children.Add(recoilTiles);
            var slim = new Grid { Margin = new Thickness(2, 0, 2, 2) };
            slim.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto }); slim.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            recoilSummaryToggle = Btn("▲ FULL SCREEN TABLES", Cyan); recoilSummaryToggle.Height = 28; recoilSummaryToggle.FontSize = 11; recoilSummaryToggle.Padding = new Thickness(12, 0, 12, 0);
            recoilSummaryToggle.Click += delegate { SetRecoilSummaryHidden(!recoilSummaryHidden); };
            slim.Children.Add(recoilSummaryToggle);
            recoilSlimText = new TextBlock { Foreground = Gold, FontSize = 12, FontWeight = FontWeights.Bold, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(10, 0, 4, 0), TextTrimming = TextTrimming.CharacterEllipsis };
            Grid.SetColumn(recoilSlimText, 1); slim.Children.Add(recoilSlimText);
            Grid.SetRow(slim, 2); g.Children.Add(slim);
            recoilTabs = new TabControl { Background = Panel, BorderBrush = Orchid, BorderThickness = new Thickness(1), Margin = new Thickness(0, 2, 0, 0), TabStripPlacement = Dock.Top, VerticalContentAlignment = VerticalAlignment.Stretch, HorizontalContentAlignment = HorizontalAlignment.Stretch };
            Brush[] colors = { Gold, Green, Cyan, Blue, Orchid, Red };
            string[] names = { "OVERVIEW", "STEPS & BOUNCES", "RISK GRID", "ONE LIVE ACCOUNT", "EVERY LADDER", "BREAKDOWNS" };
            for (int i = 0; i < names.Length; i++) recoilTabs.Items.Add(new TabItem { Header = names[i], Background = colors[i], Foreground = Bg, FontWeight = FontWeights.Bold, Content = Txt("Run RECOIL to fill this tab.", Muted, 11, FontWeights.Normal) });
            foreach (TabItem t in recoilTabs.Items) t.PreviewMouseLeftButtonDown += delegate { if (!recoilSummaryHidden) SetRecoilSummaryHidden(true); };
            Grid.SetRow(recoilTabs, 3); g.Children.Add(recoilTabs);
            recoilResultsHost = g;
            return g;
        }

        private void SetRecoilTab(string name, UIElement content)
        {
            if (recoilTabs == null) return;
            foreach (TabItem t in recoilTabs.Items) if (Convert.ToString(t.Header) == name) { t.Content = HelixScroll(content); return; }
        }

        private void RenderRecoilResults()
        {
            var r = recoilResult; if (r == null || recoilTabs == null) return;
            var c = recoilConfig ?? r.Config;
            var s = KeystoneRecoilStudy.Stats("ALL", r.Cycles, r.Days.Count, r.NoTriggerDays.Values.Sum());
            double startBalance = Math.Max(1, Number(rcStartBalanceBox, 5000));
            var acct = KeystoneRecoilStudy.Account(r.Cycles, startBalance);
            recoilVerdictHead.Text = r.Cycles.Count == 0 ? "NO LADDERS" : r.Cycles.Count + " LADDERS  •  WON " + KeystoneRecoilStudy.Pc(s.WinRate) + " (NEED " + KeystoneRecoilStudy.Pc(s.BreakEven) + ")  •  NET " + Signed(s.Net);
            recoilVerdictHead.Foreground = r.Cycles.Count == 0 ? Gold : (s.Net > 0 ? Green : Red);
            recoilVerdictCard.BorderBrush = recoilVerdictHead.Foreground;
            recoilVerdictSub.Text = KeystoneRecoilStudy.Verdict(r, s) + "\n" + c.Describe() + "\nThis is the ladder itself (setups only + one live account). Prop accounts — evaluation fees, payouts, copy trading, rotation and account groups by session — come in the next part.";
            recoilSlimText.Text = recoilVerdictHead.Text + "   •   " + c.Instruments() + " • " + c.LadderText(); recoilSlimText.Foreground = recoilVerdictHead.Foreground;
            recoilTiles.Children.Clear();
            recoilTiles.Children.Add(HelixCard("LADDERS • " + c.Instruments(), r.Cycles.Count.ToString(), s.Days + " days • " + r.NoTriggerDays.Values.Sum() + " instrument-days without the move", Cyan, 230));
            recoilTiles.Children.Add(HelixCard("WON AT THE TARGET", s.Wins + " • " + KeystoneRecoilStudy.Pc(s.WinRate), "average " + Signed(s.AvgWin) + " • break-even win rate " + KeystoneRecoilStudy.Pc(s.BreakEven), Green, 230));
            recoilTiles.Children.Add(HelixCard("BLOWN AT THE MAX DRAWDOWN", s.Blowups.ToString(), "closed at the end of the day: " + s.SessionEnds + " • average loss " + Signed(s.AvgLoss), Red, 250));
            recoilTiles.Children.Add(HelixCard("NET AFTER COSTS", Signed(s.Net), Signed(s.PerCycle) + " a ladder • costs " + Cash(s.Commission), MoneyBrush(s.Net), 220));
            recoilTiles.Children.Add(HelixCard("ONE LIVE ACCOUNT", Cash(acct.Start) + " → " + Cash(acct.End), "max drawdown " + Cash(-acct.MaxDrawdown) + (acct.Ruined ? " • LOST " + acct.RuinDate.ToString("yyyy-MM-dd") : ""), MoneyBrush(acct.End - acct.Start), 260));
            SetRecoilTab("OVERVIEW", RecoilOverviewView(r, s));
            SetRecoilTab("STEPS & BOUNCES", RecoilStepsView(r));
            SetRecoilTab("RISK GRID", RecoilGridView());
            SetRecoilTab("ONE LIVE ACCOUNT", RecoilAccountView(r, acct));
            SetRecoilTab("EVERY LADDER", RecoilLaddersView(r));
            SetRecoilTab("BREAKDOWNS", RecoilBreakdownView(r));
            SizeRecoilHost();
        }

        private UIElement RecoilOverviewView(KeystoneRecoilResult r, KeystoneRecoilStats s)
        {
            var root = new StackPanel { Margin = new Thickness(4) };
            root.Children.Add(HelixTitle("THE LADDER", Gold));
            root.Children.Add(HelixNote((recoilConfig ?? r.Config).Describe()));
            if (recoilModeCompare.Count == 2)
            {
                root.Children.Add(HelixTitle("ADD TO LOSERS vs STOP AND REVERSE (same days, same trigger, sizes, target and drawdown)", Orchid));
                double[] mw = { 300, 260, 260 };
                root.Children.Add(HelixHeader(new[] { "" }.Concat(recoilModeCompare.Select(x => x.Item1 + ((recoilConfig ?? r.Config).Mode == (x.Item1.StartsWith("ADD") ? "ADD" : "REVERSE") ? " (SHOWN)" : ""))).ToArray(), mw));
                Func<string, Func<KeystoneRecoilStats, KeystoneRecoilAccount, string>, Func<KeystoneRecoilStats, KeystoneRecoilAccount, Brush>, UIElement> mrow = (name, val, col) =>
                    HelixRow(new[] { name }.Concat(recoilModeCompare.Select(x => val(x.Item2, x.Item3))).ToArray(), new Brush[] { Muted }.Concat(recoilModeCompare.Select(x => col(x.Item2, x.Item3))).ToArray(), mw, Card, null);
                root.Children.Add(mrow("CYCLES", (a, b) => a.Cycles.ToString(), (a, b) => Text));
                root.Children.Add(mrow("WON / LOST ALL STEPS / CLOSED AT THE END", (a, b) => a.Wins + " / " + a.Blowups + " / " + a.SessionEnds, (a, b) => Text));
                root.Children.Add(mrow("WIN RATE • NEEDED", (a, b) => KeystoneRecoilStudy.Pc(a.WinRate) + " • " + KeystoneRecoilStudy.Pc(a.BreakEven), (a, b) => a.WinRate >= a.BreakEven ? Green : Red));
                root.Children.Add(mrow("NET AFTER COSTS", (a, b) => Signed(a.Net), (a, b) => MoneyBrush(a.Net)));
                root.Children.Add(mrow("AVERAGE WIN • AVERAGE LOSS", (a, b) => Signed(a.AvgWin) + " • " + Signed(a.AvgLoss), (a, b) => Text));
                root.Children.Add(mrow("ONE LIVE ACCOUNT: START → END", (a, b) => Cash(b.Start) + " → " + Cash(b.End), (a, b) => MoneyBrush(b.End - b.Start)));
                root.Children.Add(mrow("ONE LIVE ACCOUNT: MAX DRAWDOWN", (a, b) => Cash(-b.MaxDrawdown) + (b.Ruined ? " • LOST" : ""), (a, b) => Red));
                root.Children.Add(HelixNote("To see every table, chart and grid for the other mode, switch AFTER EVERY STEP POINTS AGAINST US in Step 1 and press RE-RUN."));
            }
            if (recoilCompare.Count > 0)
            {
                root.Children.Add(HelixTitle("MNQ ONLY vs MGC ONLY vs BOTH (same settings)", Cyan));
                double[] w = { 300, 220, 220, 220 };
                root.Children.Add(HelixHeader(new[] { "" }.Concat(recoilCompare.Select(x => x.Item1)).ToArray(), w));
                Func<string, Func<KeystoneRecoilStats, KeystoneRecoilAccount, string>, Func<KeystoneRecoilStats, KeystoneRecoilAccount, Brush>, UIElement> row = (name, val, col) =>
                    HelixRow(new[] { name }.Concat(recoilCompare.Select(x => val(x.Item2, x.Item3))).ToArray(), new Brush[] { Muted }.Concat(recoilCompare.Select(x => col(x.Item2, x.Item3))).ToArray(), w, Card, null);
                root.Children.Add(row("LADDERS", (a, b) => a.Cycles.ToString(), (a, b) => Text));
                root.Children.Add(row("WON / BLOWN / CLOSED AT THE END", (a, b) => a.Wins + " / " + a.Blowups + " / " + a.SessionEnds, (a, b) => Text));
                root.Children.Add(row("WIN RATE • NEEDED", (a, b) => KeystoneRecoilStudy.Pc(a.WinRate) + " • " + KeystoneRecoilStudy.Pc(a.BreakEven), (a, b) => a.WinRate >= a.BreakEven ? Green : Red));
                root.Children.Add(row("NET AFTER COSTS", (a, b) => Signed(a.Net), (a, b) => MoneyBrush(a.Net)));
                root.Children.Add(row("AVERAGE WIN • AVERAGE LOSS", (a, b) => Signed(a.AvgWin) + " • " + Signed(a.AvgLoss), (a, b) => Text));
                root.Children.Add(row("ONE LIVE ACCOUNT: START → END", (a, b) => Cash(b.Start) + " → " + Cash(b.End), (a, b) => MoneyBrush(b.End - b.Start)));
                root.Children.Add(row("ONE LIVE ACCOUNT: MAX DRAWDOWN", (a, b) => Cash(-b.MaxDrawdown) + (b.Ruined ? " • LOST" : ""), (a, b) => Red));
            }
            root.Children.Add(HelixTitle("WHAT IT MEANS", Green));
            root.Children.Add(HelixNote("Adding to a loser wins often (a small bounce to the target) and loses rarely but big (the whole max drawdown). It pays only if the win rate is above the break-even rate — " + KeystoneRecoilStudy.Pc(s.BreakEven) + " here (average loss ÷ (average win + average loss)). STEPS & BOUNCES shows how deep ladders go and what the bounce was worth; RISK GRID tries every add distance × target on the same days, per year."));
            if (r.SkippedDays.Count > 0) { root.Children.Add(HelixTitle("DAYS WITH MISSING DATA (" + r.SkippedDays.Count + ")", Red)); foreach (var d in r.SkippedDays.Take(40)) root.Children.Add(HelixNote(d)); }
            return root;
        }

        private UIElement RecoilStepsView(KeystoneRecoilResult r)
        {
            var root = new StackPanel { Margin = new Thickness(4) };
            var c = recoilConfig ?? r.Config;
            root.Children.Add(HelixTitle("HOW DEEP THE LADDERS WENT", Gold));
            root.Children.Add(HelixNote("Each row = ladders that used exactly that many entries. BOUNCE = points from the worst price to the best price after it (until the close). FULL LADDER AT THE BEST = what the position (every add the worst price reached, no stop) was worth at that best price — the reversal you would have caught by holding."));
            double[] w = { 200, 80, 80, 80, 90, 120, 130, 170 };
            root.Children.Add(HelixHeader(new[] { "ENTRIES (CONTRACTS)", "LADDERS", "WON", "BLOWN", "AT CLOSE", "NET", "AVG BOUNCE PTS", "FULL LADDER AT BEST" }, w));
            int tot = 0;
            foreach (var row in KeystoneRecoilStudy.Steps(r.Cycles, c.MaxEntries))
            {
                tot += KeystoneRecoil.AddQty(c, row.Entries - 1);
                root.Children.Add(HelixRow(new[] { row.Entries + " (" + tot + ")", row.Cycles.ToString(), row.Wins.ToString(), row.Blowups.ToString(), row.SessionEnds.ToString(), Signed(row.Net), row.AvgBounce.ToString("0.#", CultureInfo.InvariantCulture), Signed(row.AvgFullAtBest) },
                    new Brush[] { Text, Text, Green, Red, Cyan, MoneyBrush(row.Net), Cyan, MoneyBrush(row.AvgFullAtBest) }, w, row.Blowups > 0 ? Red : (row.Wins > 0 ? Green : Card), null));
            }
            var blown = r.Cycles.Where(x => x.Blown).ToList();
            root.Children.Add(HelixTitle("AFTER A BLOWUP: DID THE PRICE COME BACK?", Red));
            if (blown.Count == 0) root.Children.Add(HelixNote("No ladder was blown."));
            else
            {
                int back = blown.Count(x => !double.IsNaN(x.BestAfterLowest) && x.Dir * (x.BestAfterLowest - x.AvgAtExit) >= 0);
                root.Children.Add(HelixNote(blown.Count + " blowups • the price came back to the ladder's average later that day on " + back + " of them • average full ladder at the best price after the low: " + Signed(blown.Average(x => x.FullLadderAtBest)) + " (what holding without a stop would have given — with a much deeper drawdown: average " + Signed(blown.Average(x => x.FullLadderAtLowest)) + " at the worst)."));
                double[] bw = { 120, 60, 70, 110, 110, 130, 150, 150 };
                root.Children.Add(HelixHeader(new[] { "DAY", "INST", "SIDE", "BLOWN AT", "WORST", "BEST AFTER", "FULL LADDER WORST", "FULL LADDER BEST" }, bw));
                foreach (var x in blown.OrderBy(x => x.Day))
                {
                    string f = x.Symbol == "MGC" ? "0.0" : "0.00";
                    root.Children.Add(HelixRow(new[] { x.Day.ToString("yyyy-MM-dd"), x.Symbol, x.Side, Hm(x.ExitTime) + " " + x.ExitPrice.ToString(f), double.IsNaN(x.LowestPrice) ? "—" : x.LowestPrice.ToString(f), double.IsNaN(x.BestAfterLowest) ? "—" : x.BestAfterLowest.ToString(f), Signed(x.FullLadderAtLowest), Signed(x.FullLadderAtBest) },
                        new Brush[] { Text, x.Symbol == "MGC" ? Gold : Blue, Text, Red, Red, Cyan, Red, MoneyBrush(x.FullLadderAtBest) }, bw, Red, () => OpenRecoilChart(x)));
                }
            }
            return root;
        }

        private UIElement RecoilGridView()
        {
            var root = new StackPanel { Margin = new Thickness(4) };
            root.Children.Add(HelixNote("Every add distance (rows; the trigger keeps your trigger ÷ add ratio) × $ target (columns) re-run on the same days and minutes. Each cell: win % • net after costs • blowups. Gold = your Step 1 setting, green outline = the best cell. All years first, then each year (volatility changes)."));
            if (recoilGrids.Count == 0) { root.Children.Add(HelixNote("No grid yet.")); return root; }
            root.Children.Add(HelixTitle("BEST PER YEAR", Gold));
            double[] bw = { 150, 120, 110, 80, 90, 120, 140 };
            root.Children.Add(HelixHeader(new[] { "INSTRUMENT", "BEST ADD EVERY", "BEST TARGET", "WIN %", "BLOWN", "BEST NET", "YOUR SETTING NET" }, bw));
            foreach (var g in recoilGrids)
            {
                if (g.Best == null) continue;
                root.Children.Add(HelixRow(new[] { g.Symbol + " • " + (g.Year == "ALL" ? "ALL YEARS" : g.Year), g.Best.Distance.ToString("0.##") + " pts", Cash(g.Best.Target), KeystoneRecoilStudy.Pc(g.Best.WinRate), g.Best.Blowups.ToString(), Signed(g.Best.Net), g.Yours == null ? "—" : Signed(g.Yours.Net) },
                    new Brush[] { g.Symbol == "MGC" ? Gold : Blue, Cyan, Cyan, Text, Red, MoneyBrush(g.Best.Net), g.Yours == null ? Muted : MoneyBrush(g.Yours.Net) }, bw, g.Year == "ALL" ? Gold : Card, null));
            }
            var pick = Select(recoilGrids.Select(g => g.Symbol + " • " + (g.Year == "ALL" ? "ALL YEARS" : g.Year)).ToArray()); pick.Width = 300; pick.HorizontalAlignment = HorizontalAlignment.Left;
            var host = new StackPanel();
            Action draw = delegate { host.Children.Clear(); int i = Math.Max(0, Math.Min(recoilGrids.Count - 1, pick.SelectedIndex)); recoilGridIndex = i; host.Children.Add(RecoilGridTable(recoilGrids[i])); };
            pick.SelectedIndex = Math.Max(0, Math.Min(recoilGrids.Count - 1, recoilGridIndex)); pick.SelectionChanged += delegate { draw(); };
            root.Children.Add(HelixTitle("ADD DISTANCE × TARGET", Cyan)); root.Children.Add(Row("SHOW", pick)); root.Children.Add(host); draw();
            return root;
        }

        private UIElement RecoilGridTable(KeystoneRecoilGrid g)
        {
            var table = new Grid { Margin = new Thickness(2, 4, 2, 4), HorizontalAlignment = HorizontalAlignment.Left };
            table.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(110) });
            foreach (double t in g.Targets) table.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(96) });
            for (int i = 0; i <= g.Distances.Length; i++) table.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            Action<UIElement, int, int> put = (el, rr, cc) => { Grid.SetRow(el, rr); Grid.SetColumn(el, cc); table.Children.Add(el); };
            put(new TextBlock { Text = "ADD EVERY \\ TARGET", Foreground = Gold, FontSize = 10, FontWeight = FontWeights.Bold, Margin = new Thickness(4) }, 0, 0);
            for (int t = 0; t < g.Targets.Length; t++) put(new TextBlock { Text = Cash(g.Targets[t]), Foreground = Green, FontSize = 11, FontWeight = FontWeights.Bold, Margin = new Thickness(4), HorizontalAlignment = HorizontalAlignment.Center }, 0, t + 1);
            double maxAbs = 1; foreach (var c in g.Cells) if (c != null) maxAbs = Math.Max(maxAbs, Math.Abs(c.Net));
            for (int d = 0; d < g.Distances.Length; d++)
            {
                put(new TextBlock { Text = g.Distances[d].ToString("0.##") + " pts", Foreground = Cyan, FontSize = 11, FontWeight = FontWeights.Bold, Margin = new Thickness(4), VerticalAlignment = VerticalAlignment.Center }, d + 1, 0);
                for (int t = 0; t < g.Targets.Length; t++)
                {
                    var c = g.Cells[d, t]; bool yours = c == g.Yours, best = c == g.Best;
                    var st = new StackPanel();
                    st.Children.Add(new TextBlock { Text = c.Cycles == 0 ? "no ladder" : c.Cycles + " • " + KeystoneRecoilStudy.Pc(c.WinRate) + " • " + c.Blowups + "✕", Foreground = c.Cycles == 0 ? Muted : Text, FontSize = 10, HorizontalAlignment = HorizontalAlignment.Center });
                    st.Children.Add(new TextBlock { Text = Signed(c.Net), Foreground = MoneyBrush(c.Net), FontSize = 11, FontWeight = FontWeights.Bold, HorizontalAlignment = HorizontalAlignment.Center, Opacity = 0.55 + 0.45 * Math.Abs(c.Net) / maxAbs });
                    put(new Border { Background = Card, BorderBrush = yours ? Gold : (best ? Green : Panel), BorderThickness = new Thickness(yours || best ? 2.5 : 1), CornerRadius = new CornerRadius(3), Margin = new Thickness(1), Padding = new Thickness(2, 3, 2, 3), Child = st,
                        ToolTip = "add every " + g.Distances[d].ToString("0.##") + " pts • target " + Cash(g.Targets[t]) + "\n" + c.Cycles + " ladders • " + c.Wins + " won • " + c.Blowups + " blown\nnet " + Signed(c.Net) + " • worst day " + Signed(c.WorstDay) + (yours ? "\nYOUR STEP 1 SETTING" : "") + (best ? "\nBEST CELL" : "") }, d + 1, t + 1);
                }
            }
            var wrap = new StackPanel();
            wrap.Children.Add(HelixNote(g.Symbol + " • " + (g.Year == "ALL" ? "all years" : g.Year) + (g.Best == null ? "" : " • best: add every " + g.Best.Distance.ToString("0.##") + " pts, target " + Cash(g.Best.Target) + " = " + Signed(g.Best.Net)) + (g.Yours == null ? "" : " • yours = " + Signed(g.Yours.Net))));
            wrap.Children.Add(table);
            return wrap;
        }

        private UIElement RecoilAccountView(KeystoneRecoilResult r, KeystoneRecoilAccount a)
        {
            var root = new StackPanel { Margin = new Thickness(4) };
            var c = recoilConfig ?? r.Config;
            root.Children.Add(HelixNote("One real account (forex-lot style: $ per point per contract/lot from Step 1 — MNQ $" + c.MnqPointValue.ToString("0.##") + ", MGC $" + c.MgcPointValue.ToString("0.##") + "). Start " + Cash(a.Start) + "; every ladder's net is added when it closes. The account is lost at $0."));
            var cards = new WrapPanel();
            cards.Children.Add(HelixCard("START → END", Cash(a.Start) + " → " + Cash(a.End), a.Trades + " ladders • " + a.Wins + " won • " + a.Blowups + " blown", MoneyBrush(a.End - a.Start), 300));
            cards.Children.Add(HelixCard("MAX DRAWDOWN", Cash(-a.MaxDrawdown), "lowest balance " + Cash(a.Low) + " • peak " + Cash(a.Peak), Red, 260));
            if (a.Ruined) cards.Children.Add(HelixCard("ACCOUNT LOST", a.RuinDate.ToString("yyyy-MM-dd"), "the balance reached $0", Red, 220));
            root.Children.Add(cards);
            root.Children.Add(HelixTitle("BALANCE AFTER EVERY LADDER", Cyan));
            root.Children.Add(RecoilEquityChart(a));
            root.Children.Add(HelixTitle("MONTHS", Gold));
            double[] w = { 120, 120, 80, 80 };
            root.Children.Add(HelixHeader(new[] { "MONTH", "NET", "WON", "BLOWN" }, w));
            foreach (var m in a.Months) root.Children.Add(HelixRow(new[] { m.Item1.ToString("MMM yyyy", CultureInfo.InvariantCulture), Signed(m.Item2), m.Item3.ToString(), m.Item4.ToString() }, new Brush[] { Text, MoneyBrush(m.Item2), Green, Red }, w, m.Item2 >= 0 ? Green : Red, null));
            return root;
        }

        private UIElement RecoilEquityChart(KeystoneRecoilAccount a)
        {
            double width = 900, height = 220, padL = 70, padR = 12, padT = 10, padB = 24;
            var canvas = new Canvas { Width = width, Height = height, Background = Card, HorizontalAlignment = HorizontalAlignment.Left, Margin = new Thickness(2) };
            if (a.Equity.Count == 0) { canvas.Children.Add(new TextBlock { Text = "No ladders.", Foreground = Muted, Margin = new Thickness(10) }); return canvas; }
            DateTime t0 = a.Equity[0].Item1, t1 = a.Equity[a.Equity.Count - 1].Item1; if (t1 <= t0) t1 = t0.AddDays(1);
            double lo = Math.Min(a.Start, a.Equity.Min(e => e.Item2)), hi = Math.Max(a.Start, a.Equity.Max(e => e.Item2)); if (hi - lo < 1) { hi += 1; lo -= 1; }
            Func<DateTime, double> X = t => padL + (width - padL - padR) * (t - t0).TotalSeconds / (t1 - t0).TotalSeconds;
            Func<double, double> Y = v => padT + (height - padT - padB) * (hi - v) / (hi - lo);
            for (int k = 0; k <= 4; k++) { double v = lo + (hi - lo) * k / 4.0; var tb = new TextBlock { Text = Cash(v), Foreground = Muted, FontSize = 9 }; Canvas.SetLeft(tb, 4); Canvas.SetTop(tb, Y(v) - 7); canvas.Children.Add(tb); }
            canvas.Children.Add(new System.Windows.Shapes.Line { X1 = padL, X2 = width - padR, Y1 = Y(a.Start), Y2 = Y(a.Start), Stroke = Muted, StrokeThickness = 1, StrokeDashArray = new DoubleCollection { 4, 3 } });
            var line = new System.Windows.Shapes.Polyline { Stroke = a.End >= a.Start ? Green : Red, StrokeThickness = 2, Points = new PointCollection() };
            double prev = Y(a.Start); line.Points.Add(new Point(padL, prev));
            foreach (var e in a.Equity) { line.Points.Add(new Point(X(e.Item1), prev)); prev = Y(e.Item2); line.Points.Add(new Point(X(e.Item1), prev)); }
            canvas.Children.Add(line);
            var l0 = new TextBlock { Text = t0.ToString("MMM d, yyyy", CultureInfo.InvariantCulture), Foreground = Muted, FontSize = 9 }; Canvas.SetLeft(l0, padL); Canvas.SetTop(l0, height - 16); canvas.Children.Add(l0);
            var l1 = new TextBlock { Text = t1.ToString("MMM d, yyyy", CultureInfo.InvariantCulture), Foreground = Muted, FontSize = 9 }; Canvas.SetLeft(l1, width - padR - 70); Canvas.SetTop(l1, height - 16); canvas.Children.Add(l1);
            return canvas;
        }

        private UIElement RecoilLaddersView(KeystoneRecoilResult r)
        {
            var root = new StackPanel { Margin = new Thickness(4) };
            root.Children.Add(HelixNote("Every ladder with every fill. Click a row to open that day on the chart (the ladder is drawn: start, trigger, each add, the average, target and blowup lines, the exit)."));
            double[] w = { 112, 50, 46, 56, 84, 64, 260, 84, 70, 110, 96, 110 };
            string[] head = { "DAY", "INST", "#", "SIDE", "START", "ENTRIES", "FILLS (TIME QTY@PRICE)", "AVERAGE", "EXIT", "RESULT", "NET", "WORST OPEN" };
            var rows = r.Cycles.OrderBy(x => x.EntryTime).ToList();
            root.Children.Add(HelixPaged(head, w, rows.Count, i =>
            {
                var x = rows[i]; string f = x.Symbol == "MGC" ? "0.0" : "0.00";
                Brush res = x.Win ? Green : (x.Blown ? Red : Cyan);
                string[] cells = { x.Day.ToString("yyyy-MM-dd ddd", CultureInfo.InvariantCulture), x.Symbol, x.CycleInDay.ToString(), x.Side, x.AnchorPrice.ToString(f), x.Entries + " (" + x.MaxQty + ")", string.Join("  ", x.Fills.Select(z => Hm(z.Time) + " " + z.Qty + "@" + z.Price.ToString(f))), x.AvgAtExit.ToString(f), Hm(x.ExitTime), x.Win ? "TARGET" : x.Reason, Signed(x.Net), Signed(x.MaeValue) };
                Brush[] colors = cells.Select(z => (Brush)Text).ToArray(); colors[1] = x.Symbol == "MGC" ? Gold : Blue; colors[9] = res; colors[10] = MoneyBrush(x.Net); colors[11] = Red;
                return HelixRow(cells, colors, w, res, () => OpenRecoilChart(x));
            }, 60, false));
            return root;
        }

        private UIElement RecoilBreakdownView(KeystoneRecoilResult r)
        {
            var root = new StackPanel { Margin = new Thickness(4) };
            root.Children.Add(HelixNote("Every ladder grouped by one condition at a time. Win % = ladders closed at the target. Green rows made money."));
            double[] w = { 240, 80, 70, 70, 80, 120, 120, 120 };
            foreach (var b in KeystoneRecoilStudy.Breakdowns(r.Cycles))
            {
                if (b.Rows.Count == 0) continue;
                root.Children.Add(HelixTitle(b.Title, Cyan)); root.Children.Add(HelixNote(b.Note));
                root.Children.Add(HelixHeader(new[] { "GROUP", "LADDERS", "WON", "BLOWN", "WIN %", "NET", "AVG WIN", "AVG LOSS" }, w));
                foreach (var g in b.Rows)
                {
                    var s = g.Stats;
                    root.Children.Add(HelixRow(new[] { g.Group, s.Cycles.ToString(), s.Wins.ToString(), s.Blowups.ToString(), KeystoneRecoilStudy.Pc(s.WinRate), Signed(s.Net), Signed(s.AvgWin), Signed(s.AvgLoss) },
                        new Brush[] { Text, Text, Green, Red, s.WinRate >= s.BreakEven ? Green : Red, MoneyBrush(s.Net), Green, Red }, w, s.Net > 0 ? Green : (s.Net < 0 ? Red : Card), null));
                }
            }
            return root;
        }

        private void OpenRecoilChart(KeystoneRecoilCycle cy)
        {
            if (events.Count == 0) { UpdateUi("RUN RECOIL FIRST", Gold); return; }
            if (cy != null)
            {
                recoilSelectedId = cy.Id;
                if (reviewList != null) { int idx = reviewRows.FindIndex(e => e.SessionOrder == cy.Id); if (idx >= 0) reviewList.SelectedIndex = idx; }
                if (evidenceWindow != null && evidenceWindow.IsVisible) { SelectEvidenceSessionDate(cy.Day.ToString("yyyy-MM-dd"), true); evidenceWindow.Activate(); return; }
            }
            OpenEvidenceChart();
        }

        private void ExportRecoilReport()
        {
            if (recoilResult == null) { UpdateUi("RUN RECOIL FIRST", Gold); return; }
            try
            {
                string dir = DataDirectory(); Directory.CreateDirectory(dir);
                string stamp = DateTime.Now.ToString("yyyyMMdd_HHmmss");
                string html = Path.Combine(dir, "KeystoneArc_Recoil_Report_" + stamp + ".html"), csv = Path.Combine(dir, "KeystoneArc_Recoil_Ladders_" + stamp + ".csv");
                File.WriteAllText(html, KeystoneRecoilStudy.Html(recoilResult, recoilGrids, recoilModeCompare.Concat(recoilCompare).ToList(), Math.Max(1, Number(rcStartBalanceBox, 5000))), Encoding.UTF8);
                File.WriteAllText(csv, KeystoneRecoilStudy.Csv(recoilResult), Encoding.UTF8);
                UpdateUi("EXPORTED RECOIL REPORT • " + html + " • ladders CSV " + csv, Green);
            }
            catch (Exception ex) { UpdateUi("RECOIL EXPORT ERROR • " + ex.Message, Red); }
        }

