            Action<List<KeystonePropPlanResult>> renderSweet = list =>
            {
                var p = new StackPanel();
                if (list == null || list.Count == 0) { p.Children.Add(HelixNote("Press FIND SWEET SPOT.")); setTab(3, p); return; }
                bool br = list[0].Plan != null && list[0].Plan.Source == "BRACKET";
                p.Children.Add(HelixNote("Every plan below was simulated with the same firm rules and ranked by VALUE / EVAL (what one evaluation is worth after its cost). Click a row to load that plan into the settings and run it." + (br ? " BY YEAR = the same rule on each year's days alone (top 25): ✓ positive in every year = a real candidate • ✗ = it needed one lucky year. Prefer the best ✓ over a higher ✗." : "")));
                if (br) { var bestEvery = list.FirstOrDefault(s => s.EveryYear); p.Children.Add(Txt(bestEvery == null ? "NO RULE WAS POSITIVE IN EVERY YEAR — the ranking is luck; do not trade it." : "BEST RULE THAT WORKED IN EVERY YEAR: #" + (list.IndexOf(bestEvery) + 1) + " • " + bestEvery.Label + " • " + Signed(bestEvery.ValuePerEval) + " per evaluation • " + bestEvery.YearText, bestEvery == null ? Red : Green, 12.5, FontWeights.Bold)); }
                double[] w5 = br ? new double[] { 40, 640, 60, 56, 100, 100, 90, 70, 330 } : new double[] { 40, 420, 70, 64, 110, 110, 100, 90, 10 };
                p.Children.Add(HelixPaged(new[] { "#", "PLAN", "PASS", "DAYS", "FUNDED PAYS", "VALUE / EVAL", "LOSING EVALS", "FAILS IN A ROW", br ? "BY YEAR" : "" }, w5, list.Count, i =>
                {
                    var s = list[i];
                    string yr = s.YearText.Length == 0 ? (br ? "—" : "") : (s.EveryYear ? "✓ " : "✗ ") + s.YearText;
                    return HelixRow(new[] { (i + 1).ToString(), s.Label, s.PassRate.ToString("0") + "%", s.AvgDaysToPass.ToString("0.0"), Cash(s.FundedValue), Signed(s.ValuePerEval), s.LosingShare.ToString("0") + "%", s.LongestFailStreak95.ToString(), yr },
                        new[] { Gold, Text, Text, Text, Text, MoneyBrush(s.ValuePerEval), Text, Text, s.YearText.Length == 0 ? Muted : (s.EveryYear ? Green : Red) }, w5, i == 0 ? Gold : MoneyBrush(s.ValuePerEval), delegate { if (applyPlanAndRun != null) applyPlanAndRun(s.Plan); });
                }, 40, false));
                setTab(3, p);
            };

            Action run = delegate
            {
                if (busy) return;
                var rules = readRules(); var plan = readPlan(); var days = readDays();
                if (plan.Source == "REAL" && (days == null || days.Count(d => d.Traded) == 0)) { status.Text = "NO RECOIL DAYS • run RECOIL in the lab first (or choose COIN FLIP)."; status.Foreground = Red; return; }
                string bSym = kind().StartsWith("BRACKET") ? kind().Substring(8) : null; int bEntry = (int)PropNum(entryBox, 935), bClose = (int)PropNum(closeBox, 1555); string bDir = readDir();
                if (bSym != null && (!IsValidHhmm(bEntry) || !IsValidHhmm(bClose) || bClose <= bEntry)) { status.Text = "BRACKET TIME ERROR • entry and close are HHMM New York time, close after entry (e.g. 935 and 1555)."; status.Foreground = Red; return; }
                int n = Math.Max(500, Math.Min(50000, (int)PropNum(simsBox, 4000))), slots = Math.Max(1, Math.Min(100, (int)PropNum(slotsBox, 5))), months = Math.Max(1, Math.Min(60, (int)PropNum(monthsBox, 12)));
                string source = sources[Math.Max(0, Math.Min(sources.Count - 1, sourceBox.SelectedIndex))];
                busy = true; runBtn.IsEnabled = sweetBtn.IsEnabled = false; status.Text = "RUNNING • " + n.ToString("N0") + " evaluations + " + slots + " accounts × 3 ways × " + months + " months…"; status.Foreground = Gold;
                System.Threading.ThreadPool.QueueUserWorkItem(delegate
                {
                    KeystonePropPlanResult x = null, luck = null; var programs = new List<KeystonePropProgram>(); var years = new List<KeystonePropYear>(); string failure = null;
                    try
                    {
                        if (bSym != null)
                        {
                            plan.Bracket = KeystoneBracket.Build(daysFor(bSym), bSym, bEntry, bClose, bDir);
                            if (plan.Bracket.Traded == 0) throw new Exception("no trades • the entry time " + KeystoneBracket.Hm(bEntry) + " is outside the loaded hours (" + dataText(bSym) + ")");
                        }
                        x = KeystonePropPlanner.Evaluate(rules, plan, days, n, 17);
                        int runs = Math.Max(200, Math.Min(2000, 400000 / Math.Max(1, slots * months)));
                        foreach (var mode in new[] { "SEPARATE", "COPY", "ROTATION" }) programs.Add(KeystonePropPlanner.Program(rules, plan, days, mode, slots, months * 21, runs, 23));
                        if (plan.Source == "REAL" || plan.Source == "BRACKET") { years = KeystonePropPlanner.History(rules, plan, days); var coin = plan.Copy(); coin.Source = "COIN"; coin.DayCost = plan.Source == "BRACKET" ? plan.Bracket.CostPerContract * plan.EvalContracts : plan.DayCost; luck = KeystonePropPlanner.Evaluate(rules, coin, null, n, 17); }
                    }
                    catch (Exception ex) { failure = ex.Message; }
                    Action done = delegate
                    {
                        busy = false; runBtn.IsEnabled = sweetBtn.IsEnabled = true;
                        if (failure != null || x == null) { status.Text = "PLANNER ERROR • " + failure; status.Foreground = Red; return; }
                        renderPlan(x, programs, years, luck, source);
                        propLastPrograms = programs; propLastYears = years; propLastSource = source; propLastResult = x;
                        status.Text = "DONE • one evaluation is worth " + Signed(x.ValuePerEval) + " • pass " + x.PassRate.ToString("0.0") + "% • " + slots + " separate accounts for " + months + " months: typical " + Signed(programs[0].P50) + ", money needed " + Cash(programs[0].MoneyNeeded95);
                        status.Foreground = x.ValuePerEval > 0 ? Green : Red;
                        tabs.SelectedIndex = 0;
                    };
                    if (w.Dispatcher == null || w.Dispatcher.CheckAccess()) done(); else w.Dispatcher.BeginInvoke(done);
                });
            };

            Action<KeystonePropPlan> applyPlan = p =>
            {
                eTBox.Text = p.EvalTarget.ToString("0", CultureInfo.InvariantCulture); eSBox.Text = p.EvalStop.ToString("0", CultureInfo.InvariantCulture); fTBox.Text = p.FundTarget.ToString("0", CultureInfo.InvariantCulture); fSBox.Text = p.FundStop.ToString("0", CultureInfo.InvariantCulture);
                eKBox.Text = p.EvalSize.ToString("0.##", CultureInfo.InvariantCulture); eStopBox.Text = p.EvalDayStop.ToString("0", CultureInfo.InvariantCulture); fKBox.Text = p.FundSize.ToString("0.##", CultureInfo.InvariantCulture); fStopBox.Text = p.FundDayStop.ToString("0", CultureInfo.InvariantCulture);
                eCBox.Text = p.EvalContracts.ToString(CultureInfo.InvariantCulture); fCBox.Text = p.FundContracts.ToString(CultureInfo.InvariantCulture);
                if (p.Bracket != null) { entryBox.Text = p.Bracket.EntryHhmm.ToString(CultureInfo.InvariantCulture); closeBox.Text = p.Bracket.CloseHhmm.ToString(CultureInfo.InvariantCulture); dirBox.SelectedIndex = Math.Max(0, Array.IndexOf(KeystoneBracket.Directions, p.Bracket.Direction)); }
            };
            applyPlanAndRun = p => { applyPlan(p); run(); };

            Action sweet = delegate
            {
                if (busy) return;
                var rules = readRules(); var plan = readPlan(); var days = readDays();
                if (plan.Source == "REAL" && (days == null || days.Count(d => d.Traded) == 0)) { status.Text = "NO RECOIL DAYS • run RECOIL in the lab first (or choose COIN FLIP)."; status.Foreground = Red; return; }
                int n = Math.Max(300, Math.Min(5000, (int)PropNum(simsBox, 4000) / 2));
                string bSym = kind().StartsWith("BRACKET") ? kind().Substring(8) : null; int bClose = (int)PropNum(closeBox, 1555);
                busy = true; runBtn.IsEnabled = sweetBtn.IsEnabled = false; status.Text = bSym != null ? "SEARCHING THE SWEET SPOT ON REAL " + bSym + " PRICES • every entry time × direction, then every size, then each year (uses all CPU cores, about a minute)…" : "SEARCHING THE SWEET SPOT • every plan × " + n.ToString("N0") + " evaluations…"; status.Foreground = Gold;
                Action<string> progress = msg => { Action u = delegate { if (busy) status.Text = "SEARCHING THE SWEET SPOT ON REAL " + bSym + " PRICES • " + msg + "…"; }; if (w.Dispatcher == null || w.Dispatcher.CheckAccess()) u(); else w.Dispatcher.BeginInvoke(u); };
                System.Threading.ThreadPool.QueueUserWorkItem(delegate
                {
                    List<KeystonePropPlanResult> list = null; string failure = null;
                    try
                    {
                        if (bSym != null) { list = KeystoneBracket.SweetSpot(daysFor(bSym), bSym, IsValidHhmm(bClose) ? bClose : 1555, rules, plan, n, 31, progress); if (list.Count == 0) throw new Exception("fewer than 10 trading days for every entry time • load more dates (" + dataText(bSym) + ")"); }
                        else list = KeystonePropPlanner.SweetSpot(rules, plan, days, n, 31);
                    }
                    catch (Exception ex) { failure = ex.Message; }
                    Action done = delegate
                    {
                        busy = false; runBtn.IsEnabled = sweetBtn.IsEnabled = true;
                        if (failure != null || list == null) { status.Text = "SWEET SPOT ERROR • " + failure; status.Foreground = Red; return; }
                        renderSweet(list);
                        useBtn.IsEnabled = list.Count > 0; propLastSweet = list;
                        propLastSweetRange = bSym != null ? bSym + " " + KeystoneBracket.RangeText(daysFor(bSym)) : "COIN";
                        if (bSym != null) StoreSavedRules(bSym, list.Take(25).Select((x, i) => KeystoneBracket.SavedRule.From(x, KeystoneBracket.RangeText(daysFor(bSym)), i + 1)).ToList());
                        var b = list[0]; var every = list.FirstOrDefault(s => s.EveryYear);
                        int tradedDays = b.Plan != null && b.Plan.Bracket != null ? b.Plan.Bracket.Traded : 0;
                        if (bSym != null && every != null) b = every;
                        status.Text = (bSym != null ? (every != null ? "SWEET SPOT • BEST RULE THAT WORKED EVERY YEAR: " : "SWEET SPOT • NO RULE WORKED IN EVERY YEAR • #1 ") : "SWEET SPOT • #1 ") + b.Label + " • one evaluation worth " + Signed(b.ValuePerEval) + " • pass " + b.PassRate.ToString("0") + "% • press USE BEST PLAN or click any row";
                        status.Foreground = b.ValuePerEval > 0 ? Green : Red;
                        if (bSym != null && tradedDays < 120) { status.Text = "WARNING: ONLY " + tradedDays + " TRADING DAYS LOADED — far too few to trust; load 2 years in Step 1. " + status.Text; status.Foreground = Gold; }
                        tabs.SelectedIndex = 3;
                    };
                    if (w.Dispatcher == null || w.Dispatcher.CheckAccess()) done(); else w.Dispatcher.BeginInvoke(done);
                });
            };
            Action<List<Tuple<KeystoneBracket.SavedRule, KeystonePropPlanResult>>, string> renderProof = (proof, range) =>
            {
                var p = new StackPanel();
                if (proof == null || proof.Count == 0) { p.Children.Add(HelixNote("PROOF TEST re-runs the best rules saved by your last FIND SWEET SPOT on the data loaded now. 1) Run FIND SWEET SPOT on one period (e.g. 2025–2026). 2) In the lab load dates the rules never saw (e.g. 2023-01-01 → 2024-12-31) with PROP BRACKET. 3) Press PROOF TEST.")); setTab(4, p); return; }
                int held = proof.Count(t => t.Item2.ValuePerEval > 0), every = proof.Count(t => t.Item2.EveryYear);
                bool overlap = KeystoneBracket.Overlaps(proof[0].Item1.FoundRange, range);
                p.Children.Add(Txt(overlap ? "WARNING: the rules were found on " + proof[0].Item1.FoundRange + " and the data now is " + range + " — they overlap, so this is NOT a proof. Load dates the rules never saw." : held + " OF " + proof.Count + " SAVED RULES STAYED PROFITABLE ON NEW DATA (" + range + ") • " + every + " positive in every year. Found on " + proof[0].Item1.FoundRange + ".", overlap ? Red : (held * 2 >= proof.Count ? Green : Red), 14, FontWeights.Bold));
                var best = proof.Where(t => t.Item2.EveryYear).OrderByDescending(t => t.Item2.ValuePerEval).FirstOrDefault();
                p.Children.Add(Txt(best == null ? "No saved rule was positive in every year of the new data — none of them is proven." : "STRONGEST ON NEW DATA: " + best.Item2.Label + " • " + Signed(best.Item2.ValuePerEval) + " per evaluation (found: " + Signed(best.Item1.FoundValue) + ") • " + best.Item2.YearText, best == null ? Red : Green, 12.5, FontWeights.Bold));
                p.Children.Add(HelixNote("FOUND = what the sweet spot measured on its own dates • NOW = the same rule on the data loaded now. A real edge keeps most of its value on new data; a lucky fit falls to zero or below. Click a row to load the rule and run it."));
                double[] wp = { 36, 600, 210, 60, 100, 110, 280, 70 };
                p.Children.Add(HelixHeader(new[] { "#", "RULE", "FOUND: VALUE / EVAL", "PASS", "FUNDED PAYS", "NOW: VALUE", "NOW: BY YEAR", "HOLDS?" }, wp));
                foreach (var t in proof)
                {
                    var tt = t; bool ok = tt.Item2.ValuePerEval > 0;
                    p.Children.Add(HelixRow(new[] { tt.Item1.Rank.ToString(), tt.Item2.Label, Signed(tt.Item1.FoundValue) + (tt.Item1.FoundEveryYear ? " ✓" : ""), tt.Item2.PassRate.ToString("0") + "%", Cash(tt.Item2.FundedValue), Signed(tt.Item2.ValuePerEval), (tt.Item2.EveryYear ? "✓ " : "✗ ") + tt.Item2.YearText, ok ? (tt.Item2.EveryYear ? "YES" : "PARTLY") : "NO" },
                        new[] { Gold, Text, Muted, Text, Text, MoneyBrush(tt.Item2.ValuePerEval), tt.Item2.EveryYear ? Green : Red, ok ? (tt.Item2.EveryYear ? Green : Gold) : Red }, wp, ok ? (tt.Item2.EveryYear ? Green : Gold) : Red, delegate { if (applyPlanAndRun != null) applyPlanAndRun(tt.Item2.Plan); }));
                }
                setTab(4, p);
            };
            Action proofRun = delegate
            {
                if (busy) return;
                string kd = kind();
                if (!kd.StartsWith("BRACKET")) { status.Text = "PROOF TEST needs REAL BRACKET days: load dates in the lab with PROP BRACKET, choose REAL BRACKET in DAYS COME FROM."; status.Foreground = Red; return; }
                string sym = kd.Substring(8);
                var saved = LoadSavedRules().Where(r => r.Symbol == sym).OrderBy(r => r.Rank).ToList();
                if (saved.Count == 0) { status.Text = "NO SAVED " + sym + " RULES • run FIND SWEET SPOT on another period first (e.g. 2025–2026); its best 25 rules are saved for the proof."; status.Foreground = Red; return; }
                var rules = readRules(); var plan = readPlan(); int n = Math.Max(500, Math.Min(4000, (int)PropNum(simsBox, 4000) / 2));
                busy = true; runBtn.IsEnabled = sweetBtn.IsEnabled = proofBtn.IsEnabled = false; status.Text = "PROOF TEST • " + saved.Count + " saved " + sym + " rules (found on " + saved[0].FoundRange + ") on the data loaded now…"; status.Foreground = Gold;
                System.Threading.ThreadPool.QueueUserWorkItem(delegate
                {
                    List<Tuple<KeystoneBracket.SavedRule, KeystonePropPlanResult>> proof = null; string failure = null, range = string.Empty;
                    try { var md = daysFor(sym); range = KeystoneBracket.RangeText(md); proof = KeystoneBracket.ProofTest(md, saved, rules, plan, n, 41); } catch (Exception ex) { failure = ex.Message; }
                    Action done = delegate
                    {
                        busy = false; runBtn.IsEnabled = sweetBtn.IsEnabled = proofBtn.IsEnabled = true;
                        if (failure != null || proof == null) { status.Text = "PROOF TEST ERROR • " + failure; status.Foreground = Red; return; }
                        renderProof(proof, range); propLastProof = proof; propLastProofRange = range;
                        int held = proof.Count(t => t.Item2.ValuePerEval > 0);
                        status.Text = "PROOF TEST • " + held + " of " + proof.Count + " rules stayed profitable on " + range + (KeystoneBracket.Overlaps(saved[0].FoundRange, range) ? " (WARNING: overlaps the dates they were found on)" : " (new data)") + " • see the PROOF TEST tab";
                        status.Foreground = held * 2 >= proof.Count ? Green : Red; tabs.SelectedIndex = 4;
                    };
                    if (w.Dispatcher == null || w.Dispatcher.CheckAccess()) done(); else w.Dispatcher.BeginInvoke(done);
                });
            };
            proofBtn.Click += delegate { proofRun(); };
            sweetBtn.Click += delegate { sweet(); };
            runBtn.Click += delegate { run(); };
            useBtn.Click += delegate { if (propLastSweet.Count > 0) applyPlanAndRun((propLastSweet.FirstOrDefault(s => s.EveryYear) ?? propLastSweet[0]).Plan); };
            exportBtn.Click += delegate
            {
                if (propLastResult == null) { status.Text = "RUN THIS PLAN FIRST"; status.Foreground = Gold; return; }
                try
                {
                    string dir = DataDirectory(); Directory.CreateDirectory(dir);
                    string html = Path.Combine(dir, "KeystoneArc_PropPlanner_" + DateTime.Now.ToString("yyyyMMdd_HHmmss") + ".html");
                    File.WriteAllText(html, KeystonePropPlanner.Html(propLastResult, propLastPrograms, propLastYears, propLastSweet, propLastSource, propLastProof, propLastProofRange, propLastSweetRange), Encoding.UTF8);
                    string csv = null;
                    if (propLastResult.Plan != null && propLastResult.Plan.Bracket != null) { csv = Path.ChangeExtension(html, null) + "_days.csv"; File.WriteAllText(csv, KeystoneBracket.DayCsv(propLastResult.Plan), Encoding.UTF8); }
                    status.Text = "EXPORTED • " + html + (csv != null ? " + every day: " + Path.GetFileName(csv) : "") + " • attach these files to Claude"; status.Foreground = Green;
                }
                catch (Exception ex) { status.Text = "EXPORT ERROR • " + ex.Message; status.Foreground = Red; }
            };
            // The sweet spot list belongs to the data it was searched on: hide it when other data is loaded now.
            if (propLastSweetRange != "COIN" && propLastSweet.Count > 0)
            {
                bool same = false; foreach (var sym in labBars.Keys) if (propLastSweetRange == sym + " " + KeystoneBracket.RangeText(daysFor(sym))) same = true;
                if (!same) { propLastSweet = new List<KeystonePropPlanResult>(); propLastSweetRange = string.Empty; }
            }
            renderSweet(propLastSweet); useBtn.IsEnabled = propLastSweet.Count > 0;
            renderProof(null, string.Empty); propLastProof = new List<Tuple<KeystoneBracket.SavedRule, KeystonePropPlanResult>>(); propLastProofRange = string.Empty;
            // Keep the last rule and firm rules you ran (a new data load must not reset them).
            if (propLastResult != null) { showRules(propLastResult.Rules); applyPlan(propLastResult.Plan); refreshPoints(); }

            ConfirmToolClose(w, "PROP PLANNER");
            w.Content = root; propPlannerWindow = w;
            w.Closed += delegate { propPlannerWindow = null; applyPlanAndRun = null; propPlannerRun = null; propPlannerSweet = null; propPlannerProof = null; };
            w.Show();
            propPlannerRun = run; propPlannerSweet = sweet; propPlannerTabs = tabs; propPlannerStatus = status; propPlannerProof = proofRun;
        }
        private Action<KeystonePropPlan> applyPlanAndRun;
